void main_() {
  //*
  std::ios::sync_with_stdio(false);
  std::cin.tie(nullptr);
  //*/
  const usize n = scan<usize>();
  std::vector<std::vector<usize>> s(n);
  for (auto &e : s) {
    std::string t;
    std::cin >> t;
    for (const auto &f : t) {
      e.push_back(f - 'a');
    }
  }
  struct node {
    std::array<usize, 26> next;
    std::array<usize, 26> count;
    node() {
      for (const usize i : rep(0, 26)) {
        next[i] = 0;
        count[i] = 0;
      }
    }
  };
  std::vector<node> g(1);
  for (auto &t : s) {
    std::vector<usize> stack;
    usize cur = 0;
    std::reverse(t.begin(), t.end());
    for (const auto e : t) {
      stack.push_back(cur);
      if (g[cur].next[e] == 0) {
        g[cur].next[e] = g.size();
        g.emplace_back();
      }
      cur = g[cur].next[e];
    }
    std::array<bool, 26> ext;
    for (const usize i : rep(0, 26)) {
      ext[i] = false;
    }
    std::reverse(t.begin(), t.end());
    for (const auto e : t) {
      ext[e] = true;
      cur = stack.back();
      stack.pop_back();
      for (const usize i : rep(0, 26)) {
        if (ext[i]) {
          g[cur].count[i] += 1;
        }
      }
    }
  }
  u64 ans = 0;
  for (auto &t : s) {
    usize cur = 0;
    std::reverse(t.begin(), t.end());
    const usize c = t.back();
    t.pop_back();
    for (const auto e : t) {
      cur = g[cur].next[e];
    }
    ans += g[cur].count[c];
  }
  std::cout << ans - n << eoln;
}

} // namespace n91

int main() {
  n91::main_();
  return 0;
}

