int main() {
    cin >> n;
    for(int i = 1; i <= n; ++i) {
        cin >> s[i];
        reverse(s[i].begin(), s[i].end());
    }
    sort(s + 1, s + n + 1, cmp);
    for(int i = 1; i <= n; ++i) {
        int hash = 0, xar = 1;
        vector < vector < int > > f = vector < vector < int > > (s[i].size() + 1, vector < int >(26));
        for(int j = 0; j < (int)s[i].size() - 1; ++j) {
            hash = (hash + (ll)xar * s[i][j] % MOD) % MOD;
            xar = (ll)xar * p % MOD;
        }
        ans += raod[{hash, s[i].back() - 'a'}];
        for(int j = s[i].size() - 1; ~j; --j) {
            for(int k = 0; k < 26; ++k) {
                f[j][k] = f[j + 1][k];
