            for(int k = 0; k < 26; ++k) {
                if(f[j][k]) {
                    ++raod[{hash, k}];
                }
            }
            hash = (hash + (ll)xar * s[i][j] % MOD) % MOD;
            xar = xar * p % MOD;
        }
    }
    cout << ans << endl;
}

