struct Trie
{
    Trie *next[26];
    Trie *par;
    int cnt; //終端の個数
    int c; //ノード上の文字
    Trie(int c, Trie* p) : c(c), par(p), cnt(0)
    {
        fill(next, next+26, (Trie *) 0);
    }
    Trie() : Trie(0, NULL) {}
    void insert(const char *s)
    {
        if(*s == '\0')
        {
            this -> cnt += 1;
            return;
        }
        if(this -> next[*s-'a'] == NULL)
            this -> next[*s-'a'] = new Trie(*s-'a', this);
        this -> next[*s-'a'] -> insert(s+1);
    }
    int find(const char *s)
    {
        if(*s == '\0') return this -> cnt;
        if(this -> next[*s-'a'] == NULL)
            return 0;
        return this -> next[*s-'a'] -> find(s+1);
    }
};

ll ans = 0;
struct node
{
    int n; //部分木に存在する終端の個数
    vector<int> cnt; //部分木に'a'+iを含む文字列はcnt[i]個存在する
    node() : n(0), cnt(26) {}
    node& operator+=(const node &rh)
    {
        n += rh.n;
        rep(i,26) cnt[i] += rh.cnt[i];
        return *this;
    }
};
node dfs(Trie* t) 
{
    node v;
    vector<ll> chars(26); //子の終端の文字と個数
    rep(i,26)
    {
        if(t -> next[i] == NULL) continue;
        if(t -> next[i] -> cnt > 0)
        {
            chars[i] = t -> next[i] -> cnt;
        }
        v += dfs(t -> next[i]);
    }
    if(t -> par == NULL)
    {
        rep(i,26) ans += chars[i] * (chars[i] - 1) / 2;
    }
    rep(i,26)
    {
        ans += chars[i] * (v.cnt[i] - chars[i]);
    }
    //このノードの情報を含める
    v.n += (t -> cnt);
    v.cnt[t -> c] = v.n;
    return v;
}

