    vector<int> b(26, -1);
    for (int i = 0; i < sz(s); ++i) {
        b[s[i] - 'a'] = i;
    }
    int node = 0;
    for (int i = 0; i < sz(s); ++i) {
        for (int j = 0; j < 26; ++j) {
            if (i <= b[j]) {
                ++counts[node][j];
            }
        }
        int c = s[i] - 'a';
        if (!go[node][c]) {
            go[node][c] = ++last;
        }
        node = go[node][c];
    }
    ++leaves[node];
}

ll ans = 0;

