    for (int node = 0; node <= last; ++node) {
        for (int c = 0; c < 26; ++c) {
            if (!go[node][c]) continue;
            int to = go[node][c];
            ans += (ll) leaves[to] * (counts[node][c] - 1);
        }
    }
}

