#include <string.h>

using namespace std;

const int Alphabets = 26;

class TreeNode{
public:
	vector<TreeNode*> children;
	vector<int> counts;
	vector<bool> leaves;
	int count;
	TreeNode(): children(Alphabets, nullptr), counts(Alphabets, 0), count(0), leaves(Alphabets, 0){
	}
	void append(const string& s, int index){
		count ++;
		if(index < 0){
			return;
		}
		const int c = s[index] - 'a';
		if(index == 0){
			leaves[c] = true;
		}
		if(children[c] == nullptr){
			children[c] = new TreeNode();
		}
		children[c]->append(s, index - 1);
	}
	void prepare_counts(){
		for(int i = 0; i < Alphabets; i ++){
			TreeNode* child = children[i];
			if(child){
				child->prepare_counts();
				for(int j = 0; j < Alphabets; j ++){
					if(i == j){
						counts[i] += child->count;
					}else{
						counts[j] += child->counts[j];
					}
				}
			}
		}
	}
	long long calc_total(){
		long long total = 0;
		for(int i = 0; i < Alphabets; i ++){
			if(leaves[i]){
				total += counts[i];
			}
			auto* child = children[i];
			if(child){
				total += child->calc_total();
			}
		}
		return total;
	}
	void print(const string s){
		for(int i = 0; i < Alphabets; i ++){
			string x;
			x += ('a' + i);
			x += s;
			if(children[i]){
				children[i]->print(x);
			}
			if(counts[i] != 0){
				string y;
				y += ('a' + i);
				printe("t", y, s, counts[i]);
			}
		}
	}
};

