using namespace std;

const int SIGMA = 26;

struct Trie {
	Trie* son[SIGMA];

	int cnt, sz;

	int dp[SIGMA];

	Trie() {
		memset(son, NULL, sizeof(son));
		memset(dp, 0, sizeof(dp));
		cnt = sz = 0;
	}
};


void add(Trie* nod, const string& str, int pos) {
	if((int)str.size() == pos) {
		nod -> cnt++;
	}
	else {
		int ch = str[pos] - 'a';
		if(nod -> son[ch] == NULL)
			nod -> son[ch] = new Trie();
		add(nod -> son[ch], str, pos + 1);
	}
} 

void dfs(Trie* nod) {
	nod -> sz = nod -> cnt;

	for(int ch = 0; ch < SIGMA; ch++) {
		if(nod -> son[ch] != NULL) {

			dfs(nod -> son[ch]);

			nod -> sz += nod -> son[ch] -> sz;

			for(int cur = 0; cur < SIGMA; cur++) {
				if(cur == ch)
					nod -> dp[cur] += nod -> son[ch] -> sz;
				else
					nod -> dp[cur] += nod -> son[ch] -> dp[cur];
			}
		}
	}
}

ll solve(Trie* nod) {
	ll ans = 0;
	for(int ch = 0; ch < SIGMA; ch++) {
		if(nod -> son[ch] != NULL) {
			ans += solve(nod -> son[ch]);
			ans += 1LL * nod -> son[ch] -> cnt * nod -> dp[ch];
		}
	}
	return ans;
}


