template<int char_size,int base>
struct Trie {
    struct Node {
        vector<int> child,accept;
        int c;
        int common;
        Node(int c):c(c),common(0) {
            child.assign(char_size,-1);
        }
    };
    vector<Node> tree;
    vector<int> alpha;
    int root = 0;
    Trie() {
        tree.emplace_back(0);
        init();
    }
    void init() {
        alpha.assign(char_size,0);
    }
    void insertalpha(char s) {
        alpha[s - base] = 1;
    }
    void insert(const string &s,int id) {
        int node_id = 0;
        for (int i = 0; i < (int)s.size(); ++i) {
            int c = s[i] - base;
            int &next_id = tree[node_id].child[c];
            if (next_id < 0) {
                next_id = (int)tree.size();
                tree.emplace_back(c);
            }
            ++tree[node_id].common;
            node_id = next_id;
        }
        ++tree[node_id].common;
        tree[node_id].accept.push_back(id);
    }
    // insert s to Trie
    void insert(const string &s) {
        insert(s,tree[0].common);
    }
    // return the number of s in Trie
    int search(const string &s,bool prefix = false) {
        int node_id = 0;
        for (int i = 0;i < (int)s.size(); ++i) {
            int c = s[i] - base;
            int &next_id = tree[node_id].child[c];
            if (next_id < 0) return 0;
            node_id = next_id;
        }
        int ans = 0;
        for (int i = 0;i < char_size; ++i) {
            if (alpha[i] && tree[node_id].child[i] >= 0) {
                int x = tree[node_id].child[i];
                if (tree[x].accept.size() > 0) ++ans;
            } 
        }
        return ans;
    }
};

