class rollinghash {
public:
    string s;
    ll base1 = 1007, base2 = 2009;
    ll mod1 = 1000000007, mod2 = 998244353;
    VL hash1, hash2, power1, power2;
    rollinghash(const string& _s) {
        s = _s;
        int n = s.size();
        hash1.resize(n + 1);
        hash2.resize(n + 1);
        power1.resize(n + 1, 1);
        power2.resize(n + 1, 1);
        FOR(i, 0, n) {
            hash1[i + 1] = (hash1[i] * base1 + s[i]) % mod1;
            hash2[i + 1] = (hash2[i] * base2 + s[i]) % mod2;
            power1[i + 1] = (power1[i] * base1) % mod1;
            power2[i + 1] = (power2[i] * base2) % mod2;
        }
    }

    inline ll hash(int l, int r) const {
        ll res1 = hash1[r] - hash1[l] * power1[r - l] % mod1;
        if (res1 < 0) res1 += mod1;
        return res1;
    }
};

int cnt[26] = {};
int main() {
    init();

    int n; cin >> n;
    vector<rollinghash> h;
    h.reserve(n);
    FOR(i, 0, n) {
        string s; cin >> s;
        h.emplace_back(s);
    }

    vector<map<ll, int>> m(26);
    FOR(i, 0, n)FOR(j, 0, 26) {
        int k = 0;
        for (; k < h[i].s.length() && h[i].s[k] - 'a' != j; ++k);
        if (k != h[i].s.length())++cnt[j];
        for (++k; k < h[i].s.length(); ++k) {
            ++m[j][h[i].hash(k, h[i].s.length())];
        }
    }

    ll ans = -n;
    FOR(i, 0, n) {
        if (h[i].s.length() == 1) {
            ans += cnt[h[i].s[0] - 'a'];
        }
        else {
            ans += m[h[i].s[0] - 'a'][h[i].hash(1, h[i].s.length())];
        }
    }
    print(ans);

    return 0;
}

