const int N = 1e6 + 10;
const int L = 26;

int g[N][L];
int cnt[N][L];
int len = 2;

void add(int v, int id, string &s, vi &addition) {
   int c = s[id] - 'a';
   if (id + 1 != s.size()) {
       if (!g[v][c]) {
           g[v][c] = len++;
       }
       add(g[v][c], id + 1, s, addition);
   }
   if (addition[c] == 0)
       addition[c]++;
   fori (i, L) {
       cnt[v][i] += addition[i];
   }
}

int get(string &s) {
    int n = s.size();
    int v = 1;
    fori (i, n - 1) {
        int c = s[i] - 'a';
        if (!g[v][c])
            return 0;
        v = g[v][c];
    }
    return cnt[v][s.back() - 'a'];
}

