constexpr int kNumAlphabets = 'z' - 'a' + 1;

struct Node {
  Node() : counts(kNumAlphabets), children(kNumAlphabets) {}
  std::vector<int> counts;
  std::vector<Node*> children;
};

int main() {
  Node* root = new Node;
  int N;
  std::cin >> N;
  std::vector<std::string> S(N);
  for (int i = 0; i < N; ++i) {
    std::cin >> S[i];
    std::reverse(S[i].begin(), S[i].end());
    std::vector<int> counts(kNumAlphabets);
    for (const auto c : S[i]) {
      ++counts[c - 'a'];
    }
    auto node = root;
    for (int j = 0; j < kNumAlphabets; ++j) {
      root->counts[j] += counts[j] > 0;
    }
    for (const auto c : S[i]) {
      const auto index = c - 'a';
      --counts[index];
      auto& child = node->children[index];
      if (!child) {
        child = new Node;
      }
      for (int j = 0; j < kNumAlphabets; ++j) {
        child->counts[j] += counts[j] > 0;
      }
      node = child;
    }
  }
  std::int64_t count = 0;
  for (const auto& s : S) {
    auto node = root;
    for (std::size_t j = 0; j < s.size() - 1; ++j) {
      node = node->children[s[j] - 'a'];
    }
    count += node->counts[s.back() - 'a'] - 1;
  }
  std::cout << count << std::endl;
  return 0;
}

