void add_to_trie(string st){
	int cur=0;
	for (int i=0;i<st.size();i++){
		int id=st[i]-'a';
		if (son[cur][id]==0){
			++C;
			son[cur][id]=C;
			parent[C]=cur;
			edge_letter[C]=id;
		}
		cur=son[cur][id];
	}
	is_terminal[cur]=1;
	for (int i=0;i<26;i++){
		already_have[i]=0;
	}
	while (cur>0){
		subtree_size[cur]++;
		already_have[edge_letter[cur]]=1;
		cur=parent[cur];
		for (int i=0;i<26;i++){
			if (already_have[i])
				count_with[cur][i]++;
		}
	}
}

