    ll SSN = S[i].second.size();
    // ll count=0;
    vector<ll> SS(SSN + 1, 0);
    REP(j, SSN) { SS[j + 1] = SS[j] | (1LL << (S[i].second[j] - 'a')); }
    string now = "";
    RREP(j, SSN) {
      AUTO(m, M[hash<string>()(now)]) {
        if (SS[j + 1] & (1LL << (m.first - 'a')))
          ans += m.second;
      }
      now = S[i].second[j] + now;
    }

    ll po = hash<string>()(S[i].second.substr(1, SSN - 1));
    char poo = S[i].second[0];
    if (M.find(po) == M.end()) {
      map<char, ll> yo;
      yo[poo] = 1;
      M[po] = yo;
    } else {
      if (M[po].find(poo) == M[po].end())
        M[po][poo] = 1;
      else
        M[po][poo]++;
    }
  }
  cout << ans << endl;

  return 0;
}

