struct TrieTree {
	struct Node {
		char c;
		int level;
		int last = 0;
		unordered_map< char, int > next;
		Node(char _c, int _l) : c(_c), level(_l) {}
		Node() {}
	};
	vector< Node > nodes;
	TrieTree() {
		nodes.resize(1);
		nodes[0].c = '.';
		nodes[0].level = 0;
	}
	bool find(const string &S) {
		bool ret = true;
		int j = 0;
		int N = S.size();
		rep(i, N) {
			char c = S[i];
			if (nodes[j].next[c] == 0) {
				ret = false;
				break;
			} else {
				j = nodes[j].next[c];
			}
		}
		//if(nodes[j].last==0)ret=0;
		return ret;
	}
	void add(const string &S) {
		int j = 0;
		int N = S.size();
		rep(i, N) {
			char c = S[i];
			if (nodes[j].next[c] == 0) {
				nodes[j].next[c] = nodes.size();
				nodes.push_back(Node(c, i + 1));
			}
			j = nodes[j].next[c];
		}
		nodes[j].last = 1;
	}
	vector< vector< int > > count;
	int dfs1(int x) {
		int ret = 0;
		for (auto p : nodes[x].next) {
			int tmp = dfs1(p.second);
			rep(j, 26) count[x][j] += count[p.second][j];
			count[x][p.first - 'a'] += tmp;
			ret += tmp;
		}
		return ret + nodes[x].last;
	}
	void dfs2(int x, int &ans) {
		for (auto p : nodes[x].next) {
			if (nodes[p.second].last) {
				count[x][p.first - 'a']--;
				ans += count[x][p.first - 'a'];
				dfs2(p.second, ans);
			} else {
				dfs2(p.second, ans);
			}
		}
	}
	int solve() {
		count.resize(nodes.size(), vector< int >(26, 0));
		dfs1(0);
		int ans = 0;
		dfs2(0, ans);
		return ans;
	}
};
