using ull = unsigned long long;

const ull mod = 1e17 + 3;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int N;
    cin >> N;
    vector<string> S(N);
    for (int i = 0; i < N; i++) {
        cin >> S[i];
        reverse(S[i].begin(), S[i].end());
    }
    sort(S.begin(), S.end(), [](auto& s1, auto& s2) {
        return s1.size() > s2.size();
    });
    unordered_map<ull, vector<int>> cnt;
    vector<int> one(26);
    ull ans = 0;
    for (auto& s : S) {
        int n = s.size();
        if (n == 1) {
            ans += one[s[0] - 'a'];
            continue;
        }
        vector<ull> hashes(n - 1);
        hashes[0] = s[0] - 'a' + 1;
        for (int i = 1; i < n - 1; i++) hashes[i] = (hashes[i-1] * 30 + s[i] - 'a' + 1) % mod;
        if (cnt.count(hashes[n-2])) ans += cnt[hashes[n-2]][s[n-1] - 'a'];
        vector<int> found(26);
        found[s[n-1] - 'a'] = 1;
        for (int i = n - 2; i > 0; i--) {
            found[s[i] - 'a'] = 1;
            if (cnt.count(hashes[i-1]) == 0) cnt[hashes[i-1]] = vector<int>(26);
            for (int c = 0; c < 26; c++) cnt[hashes[i-1]][c] += found[c];
        }
        found[s[0] - 'a'] = 1;
        for (int c = 0; c < 26; c++) one[c] += found[c];
    }
    cout << ans << endl;
}

