struct Trie {
  struct Node {
    static const int ALPHA = 26;
    int is;
    array<int,ALPHA> nxt;
    int depth;
    Node(): is(), nxt(), depth() {}
    int& operator [] (size_t idx) {
      return nxt[idx];
    }
  };
  vector<Node> nodes;
  int ptr;
  Trie(): nodes(1), ptr(1) {}
  void add(const string &s) {
    int cur = 0;
    for (const char &c: s) {
      int u = c - 'a';
      if (!nodes[cur][u]) {
        nodes.emplace_back();
        nodes[ptr].depth = 1 + nodes[cur].depth;
        nodes[cur][u] = ptr++;
      }
      cur = nodes[cur][u];
    }
    nodes[cur].is = 1;
  }
  string tmp;
  void dfs(int u = 0, int w = 0) {
    error(u, char(w+'a'), tmp);
    sz[u] = 0;
    for (int i = 0; i < 26; ++i) if (nodes[u][i]) {
      int v = nodes[u][i];
      tmp += 'a' + i;
      dfs(v, i);
      tmp.pop_back();
      sz[u] += sz[v];
      for (int j = 0; j < 26; ++j) {
        cnt[u][j] += cnt[v][j];
      }
    }
    error(u, sz[u]);
    for (int i = 0; i < 26; ++i) if (nodes[u][i]) {
      int v = nodes[u][i];
      if (nodes[v].is) {
        error(u, char(i+'a'), cnt[u][i]);
        ans += cnt[u][i] - 1;
      }
    }
    sz[u] += nodes[u].is;
    if (u) {
      cnt[u][w] = sz[u];
    }
  }
};

