struct trie
{
	trie *nt[26], *pr;
	int p[26];
	bool f;

	trie()
	{
		pr = nullptr;
		for (int i = 0; i < 26; i++) {
			nt[i] = nullptr;
			p[i] = 0;
		}
		f = false;
	}

	void insert(int p)
	{
		if (p >= s.length()) {
			pr->p[s[p - 1] - 'a']++;
			f = true;
			return;
		}
		int tc = s[p] - 'a';
		if (!nt[tc])
			nt[tc] = new trie;
		nt[tc]->pr = this;
		nt[tc]->insert(p + 1);
	}

	void ps()
	{
		if (f) {
			for (int i = 0; i < 26; i++)
				if (fp[i])
					ans += pc[i];
		}
		for (int i = 0; i < 26; i++)
			pc[i] += p[i];
		for (int i = 0; i < 26; i++) {
			if (!nt[i]) continue;
			fp[i]++;
			nt[i]->ps();
			fp[i]--;
		}
		for (int i = 0; i < 26; i++)
			pc[i] -= p[i];
	}
};

