  }
  for (int i = 0; i < sigma; ++i) {
    a[i] = 0;
  }
  for (int i = sz(s) - 1; i >= 0; --i) {
    v = p[v];
    int c = s[i] - 'a';
    a[c] = 1;
    for (int cc = 0; cc < sigma; ++cc) {
      cnt[v][cc] += a[cc];
    }
