struct RollingHash{
    static const ll base1 = 1009;
    static const ll base2 = 2009;
    static const ll mod1 = 1000000009;
    static const ll mod2 = 1000000007;
    int n;
    vl hash1,hash2,pow1,pow2;
    RollingHash() = default;
    RollingHash(const string &s){
        n = s.size();
        hash1.assign(n+1, 0);
        hash2.assign(n+1, 0);
        pow1.assign(n+1, 1);
        pow2.assign(n+1, 1);
        rep(i,n){
            hash1[i+1] = (hash1[i] * base1 + s[i]) % mod1;
            hash2[i+1] = (hash2[i] * base2 + s[i]) % mod2;
            pow1[i+1] = (pow1[i] * base1) % mod1;
            pow2[i+1] = (pow2[i] * base2) % mod2;
        }
    }
    // S[l,r)のハッシュ値を返す.
    // O(1)
    inline pair<ll,ll> hash(int l, int r) const {
        ll res1 = (hash1[r] - (hash1[l]*pow1[r-l] % mod1) + mod1) % mod1;
        ll res2 = (hash2[r] - (hash2[l]*pow2[r-l] % mod2) + mod2) % mod2;
        return make_pair(res1, res2);
    }
    inline pair<ll,ll> hash() const {
        return hash(0, n);
    }
    // Longest Common Prefix.
    // O(logN)
    inline int calcLCP(const RollingHash & rh, int l1, int r1, int l2, int r2) const {
        int low = 0, high = min(r1-l1, r2-l2);
        while(high - low > 1){
            int mid = (low + high) / 2;
            if(hash(l1, l1+mid) == hash(l2, l2+mid)){
                low = mid;
            }else{
                high = mid;
            }
        }
        return low;
    }
    // hash h1とhash h2を結合.
    pair<ll,ll> concat(pair<ll,ll> h1, pair<ll,ll> h2, int h2len){
        ll res1 = h1.first * pow1[h2len] + h2.first % mod1;
        ll res2 = h1.second * pow2[h2len] + h2.second % mod2;
        return make_pair(res1, res2);
    }
};

