	for (int i = 0; i < K; i++) exist[i] = false;
	int len = str[id].size();
	node[len] = rt;
	for (int i = len - 1; i >= 0; i--) node[i] = ch[node[i + 1]][str[id][i] - 'a'];
	for (int i = 0; i <= len; i++) {
		for (int j = 0; j < K; j++) {
			if (!i || !exist[j]) continue;
			int trans = ch[node[i]][j];
			if (trans >= 0) ans += sz[trans];
		}
		if (i < len) exist[str[id][i] - 'a'] = true;
	}
}
void dfs(int u) {
	ans -= 1ll * sz[u] * (sz[u] + 1) / 2;
	for (int i = 0; i < K; i++) {
		if (~ch[u][i]) dfs(ch[u][i]);
	}
}

