	read(n);
	rt = newnode();
	for (int i = 0; i < n; i++) {
		scanf("%s", tmp);
		str[i] = string(tmp), insert();
	}
	for (int i = 0; i < n; i++) update(i);
	dfs(rt);
	write(ans), putchar('\n'); 
	return 0;
}

