using namespace std;

typedef long long int ll;

const int N = 2e5 + 5;

int nxt[N][26], cnt[N][26], cur = 0;

void insert (string s) {
  vector < int > c (26, 0);
  int idx = 0;
  for (auto i : s) c[i - 'a']++;
  for (int j = 0; j < 26; j++) cnt[idx][j] += (c[j] > 0);
  for (auto i : s) {
    c[i - 'a']--;
    if (!nxt[idx][i - 'a']) {
      nxt[idx][i - 'a'] = ++cur;
    }
    idx = nxt[idx][i - 'a'];
    for (int j = 0; j < 26; j++) cnt[idx][j] += (c[j] > 0);
  }
}

int solve (string s) {
  int n = s.length(), idx = 0;
  for (int i = 0; i < n - 1; i++) {
    idx = nxt[idx][s[i] - 'a'];
  }

  return cnt[idx][s[n - 1] - 'a'] - 1;
}

