	int head[MOD], nxt[maxn], dat[maxn];
	ull val[maxn];
	HashMap(){ tot = 0; memset(head, -1, sizeof(head)); }
	inline void update(ull h){
		int v = h % MOD;
		for(int i = head[v]; ~i; i = nxt[i]) if(val[i] == h){
			++dat[i];
			return;
		}
		nxt[tot] = head[v];
		dat[tot] = 1;
		val[tot] = h;
		head[v] = tot++;
		return;
	}
