const int MR = 1e6 + 10;
const int MS = 30;

int trie[MR][MS], cnt;

// ile slow sie konczy i ile konczy sie na dana litere w poddrzewie
struct
{
    int subTree[MS];
}ile[MR];

char s[MR];
int dl;
LL res;

int frq[MS];
void add(int nr, int dl)
{
    if (nr)
    {
        // zmniejsz wystepowanie kolejnych liter, gdy idziesz do kolejnego wierzcholka
        frq[s[dl] - 'a']--;
    }

    // pierwsza litera moze zawedrowac gdziekolwiek, trzeba dodac liczbe wyrazow, ktore wystapily w poddrzewie z ta litera
    if (dl == 1)
        res += ile[nr].subTree[s[0] - 'a'];

    // zwieksz liczbe wystapien odpowiednich liter w poddrzewach
    // zwroc uwage, zeby tego samego wyrazu nie liczyc w poddrzewie kilkukrotnie
    // trzeba dodac jeden, jesli z tego wyrazu pozniej dodamy jakas litere
    FORQ(c, 'a', 'z')
        ile[nr].subTree[c - 'a'] += frq[c - 'a'] ? 1 : 0;

    if (!dl)
    {
        return;
    }

    int wsk = s[dl - 1] - 'a';

    // zobacz czy potrzebny nowy wierzch trie
    if (!trie[nr][wsk])
        trie[nr][wsk] = ++cnt;

    add(trie[nr][wsk], dl - 1);
}

int main()
{
    fast_io();
    int N;
    scanf("%d", &N);
    vector < pair<int, string> > V;
    REP(i, N)
    {
        scanf("%s", s);
        string tmp(s);
        V.push_back(MP(tmp.length(), tmp));
    }

    sort(V.begin(), V.end());

    // dodawaj do drzewa od najdluzszych
    while (!V.empty())
    {
        REP(i, V.back().first)
        {
            frq[V.back().second[i] - 'a']++;
            s[i] = V.back().second[i];
        }
        s[V.back().first] = 0;

        add(0, V.back().first);
        V.pop_back();
    }

    printf("%lld\n", res);

    return 0;
}

