using namespace std;

const int M = 1e6 + 10;
const int N = 2e5 + 10;

int n;
char ch[M];

pair<int, int> a[N];
int g[M][26];

bool cmp(pair<int, int> a, pair<int, int> b) {
	return a.first < b.first;
}

int tr[M][26], rt = 1, num[M], cnt = 1;

void Ins(int st, int len) {
	int now = rt;
	for (int i = 0; i < len; i++) {
		int j = ch[st + i] - 'a';
		if (!tr[now][j]) tr[now][j] = ++cnt;
		now = tr[now][j];
	}
	num[now]++;
}

int main() {
	cin >> n;
	int hav = 0;
	for (int i = 1; i <= n; i++) {
		scanf("%s", ch + hav);
		int len = strlen(ch + hav);
		reverse(ch + hav, ch + hav + len);
		a[i].first = len;
		a[i].second = hav;
		hav += len;
	}
	sort(a + 1, a + n + 1, cmp);
	long long ans = 0;
	for (int i = 1; i <= n; i++) {
		int st = a[i].second, len = a[i].first;
		for (int j = 0; j < 26; j++) g[len][j] = 0;
		for (int j = len - 1; j >= 0; j--) {
			for (int k = 0; k < 26; k++) g[j][k] = g[j + 1][k];
			g[j][ch[st + j] - 'a'] = 1;
		}
		int now = rt;
		for (int j = 0; j < len; j++) {
			for (int k = 0; k < 26; k++) {
				if (!g[j][k] || !tr[now][k]) continue;
				ans += num[tr[now][k]];
			}
			now = tr[now][ch[st + j] - 'a'];
			if (!now) break;
		}
		Ins(st, len);
	}
	cout << ans << endl;
}

