struct Trie {
    Trie() {
        memset(next,0,sizeof(next));
        memset(rightest,0,sizeof(rightest));
        ch = '#';
        deep = 0;
    }
    char ch;
    int deep;
    int rightest[26];
    Trie* next[26];
};
// Trie tries[26];
Trie root;

class Solution
{
	void addToTrie(string &s, int* rightest) {
        rep(i,0,26) {
            if(rightest[i] > root.deep) root.rightest[i]++;
        }
        if(root.next[s[0]-'a']==nullptr) {
            root.next[s[0]-'a'] = new Trie();
        }
        Trie* cur = root.next[s[0]-'a'];
        if(cur->ch == '#') cur->ch = s[0];
        cur->deep = 1;
        rep(i,0,26) {
            if(rightest[i] > cur->deep) cur->rightest[i]++;
        }
        rep(i,1,s.length()) {
            if(cur->next[s[i]-'a']==nullptr) {
                cur->next[s[i]-'a'] = new Trie();
            }
            Trie* next = (cur->next[s[i]-'a']);
            next->deep = cur->deep+1;
            rep(j,0,26) {
                if(rightest[j] > next->deep) next->rightest[j]++;
            }
            next->ch = s[i];
            cur = next;
        }
    }
    ll countT(string &s) {
        Trie* cur = &root;
        rep(i,0,s.length()-1) {
            Trie* next = cur->next[s[i]-'a'];
            cur = next;
        }
        return cur->rightest[s[s.length()-1]-'a']-1;
    }
public:
	void Solve()
	{
		int n;
        cin>>n; 
        {
            vector<string> vs(n);
            rep(i,0,n) {
                cin>>vs[i];
                int rightest[26];
                memset(rightest,-1,sizeof(rightest));
                reverse(vs[i].begin(), vs[i].end());
                rep(j,0,vs[i].length()) {
                    rightest[vs[i][j]-'a'] = j+1;
                }

                addToTrie(vs[i], rightest);
            }
            ll ans = 0;
            rep(i,0,n) {
                ans += countT(vs[i]);
            }
            cout<<ans<<endl;
        }
	}

private:
};
