using namespace std;

struct node {
  node* children[26];
  int letters[26];

  node(){
    for(int i = 0; i < 26; i++){
      children[i] = NULL;
      letters[i] = 0;
    }
  }

  ~node(){
    for(int i = 0; i < 26; i++){
      delete children[i];
    }
  }

  void include_letters(int l){
    for(int i = 0; i < 26; i++){
      letters[i] += (l & (1 << i)) != 0;
    }
  }
};

char str[1000100];

int main(){
  int N;
  while(scanf("%d", &N) > 0){
    vector<string> S(N);

    node* root = new node();

    for(int i = 0; i < N; i++){
      scanf("%s", str);
      S[i] = str;
      reverse(S[i].begin(), S[i].end());
      int len = S[i].size();

      vector<int> letters(len);
      letters[len-1] = 1 << (S[i][len-1] - 'a');
      for(int j = len-2; j >= 0; j--){
	letters[j] |= letters[j+1] | (1 << (S[i][j] - 'a'));
      }

      node* u = root;

      for(int j = 0; j < S[i].size(); j++){
	u->include_letters(letters[j]);
	int ch = S[i][j] - 'a';

	if(!u->children[ch]){
	  u->children[ch] = new node();
	}

	u = u->children[ch];
      }
    }

    long long ans = 0;

    for(int i = 0; i < N; i++){
      node* u = root;

      int len = S[i].size();
      for(int j = 0; j < len-1; j++){
	int ch = S[i][j] - 'a';
	u = u->children[ch];
      }

      ans += u->letters[S[i][len-1] - 'a'] - 1;
    }

    printf("%lld\n", ans);

    delete root;
  }
}

