bool isGood(string a , string b){

    map<char , int>  mp , mp2 ;
    for(int i = 0 ;i < a.size() ; ++i){
        mp[a[i]]++;
    }

    for(int i = 0 ;i < b.size() ; ++i){
        mp2[b[i]]++;
        if(mp[b[i]] < mp2[b[i]] )
            return false;
    }

    int n = a.size();
    int m = b.size();
    int j = n-1;
    for(int i = m-1; i > 1 ; --i ){
            if(b[i] != a[j--]){
                return false;
            }
        }

    int trigger = 0;
    char find = (m > 1 ? b[1] : b[0]);
    for( ; j >= 0 ; --j){
        if(m == 1){
            if(find == a[j])
                return true;
        }
        else if(m == 2){
            if(a[j] == b[1] && a[j-1] == b[0])
                return true;


            return false;
        }
        else{
            if(find == a[j]){
                if(trigger ==  1)
                    return true;

                find = b[0];
                trigger++;
            }
        }
