const int let = 26;
const int max_states = int(1e6) + 1;

struct trie
{
	vector<array<int, let>> next;
	vector<string> who_need;
	vector<int> cnt_in_subtree;

	array<int, let> array_of_minus_ones, array_of_zeros;

	trie ()
	{
		for (auto &it : array_of_minus_ones)
			it = -1;
		for (auto &it : array_of_zeros)
			it = 0;

		next.reserve(max_states + 1);

		next.push_back(array_of_minus_ones);
		who_need.push_back("");
		cnt_in_subtree.push_back(0);
	}

	void add (const string &s, const char what)
	{
		int state = 0;
		cnt_in_subtree[state]++;

		for (char ch : s)
		{
			if (next[state][ch - 'a'] == -1)
			{
				next[state][ch - 'a'] = int(next.size());
				next.push_back(array_of_minus_ones);
				who_need.push_back("");
				cnt_in_subtree.push_back(0);
			}

			state = next[state][ch - 'a'];
			cnt_in_subtree[state]++;
		}

		who_need[state] += what;
	}

	array<int, let> dfs (const int state, ll &ans)
	{
		auto res = array_of_zeros;

		for (int i = 0; i < let; i++)
			if (next[state][i] != -1)
			{
				const int to = next[state][i];
				auto cur = dfs(to, ans);
				assert(cur[i] <= cnt_in_subtree[to]);
				cur[i] = cnt_in_subtree[to];
				for (int j = 0; j < int(cur.size()); j++)
					res[j] += cur[j];
			}

//		if (state == 0)
//		{
//			cerr << "cnt[b] = " << (next[state][1] == -1 ? -1 : cnt_in_subtree[next[state][1]]) << endl;
//
//			for (auto it : res)
//				cerr << it << ' ';
//			cerr << endl;
//		}

		for (char ch : who_need[state])
			ans += res[ch - 'a'];
		for (auto ch : who_need[state])
			res[ch - 'a']++;
		return res;
	}

	ll calc_ans ()
	{
		ll ans = 0;
		dfs(0, ans);
		return ans;
	}
};

void solve(istream &cin = std::cin, ostream &cout = std::cout)
{
	int n;
	cin >> n;

	vector<string> str(n);
	for (auto &it : str)
	{
		cin >> it;
		reverse(it.begin(), it.end());
	}

	trie data;
	for (auto it : str)
		data.add(it.substr(0, int(it.size()) - 1), it.back());
	cout << data.calc_ans() << endl;
}

