struct Trie{
    Trie* children[26];
    int is_end;
    int num;

    Trie(){
        for(int i = 0; i < 26; ++i)
            children[i] = NULL;
        is_end = 0;
        num = 0;
    }
    Trie* upsert(char ch){
        if(children[ch - 'a'] == NULL)
            children[ch - 'a'] = new Trie();
        return children[ch - 'a'];
    }
};

int main(){
    int n;
    scanf("%d", &n);
    char s[1000005];
    Trie *root = new Trie();
    Trie *p;
    int len;
    int i, j;
    int d[26];
    long long ans = 0;
    while(n--){
        scanf("%s", s);
        len = strlen(s);
        for(i = 0; i < 26; ++i)
            d[i] = 0;
        std::set<char> se;
        for(i = len - 1; i >= 0; --i){
            ++d[s[i] - 'a'];
            se.insert(s[i]);    
        }  
        for(char ch: se){
            p = root->upsert(ch);
            ++p->num;
            ans += (long long)p->is_end;
        }
        p = root;
        //printf("%lld ", ans);
        for(i = len - 1; i >= 1; --i){
            p = p->upsert(s[i]);
            --d[s[i] - 'a'];
            if(!d[s[i] - 'a'])
                se.erase(s[i]);
            for(char ch: se){
                ++p->upsert(ch)->num;
                ans += p->upsert(ch)->is_end;
            }
        }
        p = p->upsert(s[0]);
        ++p->is_end;
        //printf("%lld ", ans);
        ans += (long long)p->num - 1;
        //++p->num;
        //printf("%lld\n", ans);
    }
    printf("%lld\n", ans);
    return 0;
}

