template <typename T>
struct trie{
	T init_value;
	struct node{
		vector<int> next;
		T v;
		T sum;
		int depth;
		node(int k,T iv,int d){
			next.resize(k,-1);
			v = iv;
			sum = iv;
			depth = d;
		}

		int link;
	};
	vector<node> _N;
	vector<string> _S;
	int n;
	trie(int k,T iv){
		init_value = iv;
		n = k;
		_N.push_back(node(n,init_value,0));
	}

	T add(string &s,int now = 0,int nowv=0){
		if(now==s.size())return init_value;
		int c = get(s[now]);
		if(_N[nowv].next[c]==-1){
			_N[nowv].next[c] = _N.size();
			_N.push_back(node(n,init_value,_N[nowv].depth+1));
		}
		int newv = _N[nowv].next[c];
		vector<long long> V = init_value;
		V = add(s,now+1,newv);
		V[c]++;
		for(int i=0;i<26;i++){
			if(V[i]>0){
				_N[nowv].v[i]++;
			}
		}

		_S.push_back(s);
		return V;

		//_N[now].v = x;

	}

	void set_link(){
		_N[0].link = 0;
		queue<int> Q;
		Q.push(0);
		while(Q.size()!=0){
			int now = Q.front();
			Q.pop();
			_N[now].v = func(_N[now].v,_N[_N[now].link].v);
			_N[now].sum = func(_N[now].sum,_N[now].v);
			for(int i=0;i<n;i++){
				int to = _N[now].next[i];
				if(to==-1)continue;
				int x = now;
				while(x!=0){
					x = _N[x].link;
					if(_N[x].next[i]!=-1){
						x = _N[x].next[i];
						break;
					}
				}
				_N[to].link = x;
				_N[to].sum = func(_N[to].sum,_N[now].sum);
				Q.push(to);
			}
		}
	}

	T get_value(string S){
		T ret = init_value;;
		int now = 0;
		for(int i=0;i<S.size();i++){
			int c = get(S[i]);
			if(_N[now].next[c]!=-1){

				now = _N[now].next[c];
				//ret = func(ret,_N[now].v);
			}
			else{
				return ret;
				while(now!=0){
					now = _N[now].link;
					if(_N[now].next[c]!=-1){
						now = _N[now].next[c];
						ret = func(ret,_N[now].v);
						break;
					}
				}
			}
		}
		return _N[now].v;
		return ret;
	}

	int get(char c){
		return c-'a';
	}

	T func(T a,T b){
		return a;
		//return a+b;
	}

};

