                rep(r, 26) {
                    if (c[r]) sum += s[r][t];
                }

                c[char(a[j][k] - 'a')] = 1;
            }
            ret += sum;

            H g = b[j].get(1, siz(a[j]));
            v.pb(Q(char(a[j][0] - 'a'), g.fs, g.sc));

            j++;
        }
        for (auto g : v) {
            s[g.xx][H{ g.yy,g.zz }]++;
        }
        i = j;
    }

    return ret;
}

int solve() {
    vec<string>a;
    vi mp(26, 0);

    rep(i, n) d[i].clear(), e[i].clear();

    rep(i, n) {
        string t = nyu[i];
        if (siz(t) == 1) {
            mp[(int)(t[0] - 'a')]++;
        }
        else a.pb(t);
    }

    n = siz(a);
    vec<bool>c(26);

    int ret = 0;
    rep(i, n) {
        rep(i, 26) c[i] = 0;
        for (auto d : a[i]) {
            c[(int)(d - 'a')] = 1;
        }
        rep(j, 26) {
            if (c[j]) ret += mp[j];
        }
    }

    rep(i, n) reverse(all(a[i]));
    sort(all(a), [&](string& i, string& j) {
        if (siz(i) != siz(j)) return siz(i) < siz(j);
        return i < j;
        });


    rep(i, n) {
        d[i] = vec<vec<bool>>(siz(a[i]), vec<bool>(26, 0));
        e[i] = vec<vec<int>>(siz(a[i]), vec<int>(26, 0));


        for (int j = siz(a[i]) - 1; j >= 0; j--) {
            d[i][j][(int)(a[i][j] - 'a')] = 1;


            if (j < siz(a[i]) - 1) {
                rep(k, 26) {
                    d[i][j][k] = d[i][j][k] | d[i][j + 1][k];
                }
            }//j文字目以降に文字kは存在しますか？


            rep(k, 26) if (d[i][j][k]) e[i][j][k] = 1;


            if (i > 0 && j < siz(a[i - 1])) {
                rep(k, 26) {
                    e[i][j][k] += e[i - 1][j][k];
                }
            }//i文字目までに、j文字目以降に文字kが存在していた文字列は何個ありますか？
        }
    }

    int ans = ret;

    rep(i, n) {
        //最後からの共通部分列の長さがsiz(a[i])-1以上の物はドーレ？

        int ok = i, ng = n, mid;
        while (ng - ok > 1) {
            mid = (ok + ng) / 2;
            int j = 0;
            while (j < min(siz(a[i]), siz(a[mid])) && a[i][j] == a[mid][j]) {
                j++;
            }

            if (j >= siz(a[i]) - 1) ok = mid;
            else ng = mid;
        }
        ans += e[ok][siz(a[i]) - 1][(int)(a[i][siz(a[i]) - 1] - 'a')] - e[i][siz(a[i]) - 1][(int)(a[i][siz(a[i]) - 1] - 'a')];
    }

    return ans;
}

