using namespace std;
long long BASE;
const long long MOD = 1000000007;
vector<long long> power, inv;
long long modpow(long long a, long long b){
  long long ans = 1;
  while (b > 0){
    if (b % 2 == 1){
      ans *= a;
      ans %= MOD;
    }
    a *= a;
    a %= MOD;
    b /= 2;
  }
  return ans;
}
long long modinv(long long a){
  return modpow(a, MOD - 2);
}
void precalc(int n){
  power = vector<long long>(n);
  power[0] = 1;
  for (int i = 1; i < n; i++){
    power[i] = power[i - 1] * BASE % MOD;
  }
  inv = vector<long long>(n);
  inv[0] = 1;
  inv[1] = modinv(BASE);
  for (int i = 2; i < n; i++){
    inv[i] = inv[i - 1] * inv[1] % MOD;
  }
}
struct rolling_hash{
  int N;
  vector<long long> S;
  rolling_hash(){
  }
  rolling_hash(string s){
    N = s.size();
    S = vector<long long>(N + 1, 0);
    for (int i = 0; i < N; i++){
      S[i + 1] = (S[i] + s[i] * power[i]) % MOD;
    }
  }
  int size(){
    return N;
  }
  long long hash(int L, int R){
    return (S[R] - S[L] + MOD) * inv[L] % MOD;
  }
  long long all(){
    return S[N];
  }
};
pair<long long, int> merge(pair<long long, int> A, pair<long long, int> B){
  long long ans1 = (A.first + B.first * power[A.second]) % MOD;
  int ans2 = A.second + B.second;
  return make_pair(ans1, ans2);
}
int main(){
  ios::sync_with_stdio(false);
  random_device rnd;
  mt19937 mt(rnd());
  BASE = mt() % 10000000 + 10000000;
  precalc(1000001);
  int N;
  cin >> N;
  vector<string> S(N);
  for (int i = 0; i < N; i++){
    cin >> S[i];
  }
  vector<rolling_hash> RH(N);
  for (int i = 0; i < N; i++){
    RH[i] = rolling_hash(S[i]);
  }
  map<pair<long long, int>, int> mp;
  for (int i = 0; i < N; i++){
    mp[make_pair(RH[i].all(), RH[i].size())]++;
  }
  long long ans = 0;
  for (int i = 0; i < N; i++){
    int sz = S[i].size();
    if (sz == 1){
      continue;
    }
    vector<bool> alphabet(26, false);
    for (int j = 1; j <= sz; j++){
