using namespace std;
const int alpha = 26;
const int maxn = 2e5 + 10;
struct node {
  int cnt[alpha];
  node* nxt[alpha];
  node () {
    for(int i = 0; i < alpha; i++) {
      cnt[i] = 0;
      nxt[i] = NULL;
    }
  }
} *root;

void insert(string s) {
  int cnt[alpha] = {0};
  for(int i = 0; i < s.size(); i++) {
    cnt[s[i] - 'a'] += 1;
  }
  node* cur = root;
  for(int i = 0; i < s.size(); i++) {
    for(int j = 0; j < alpha; j++) cur -> cnt[j] += bool(cnt[j]);
    int c = s[i] - 'a';
    cnt[c] -= 1;
    if(cur -> nxt[c] == NULL) {
      cur -> nxt[c] = new node();
    }
    cur = cur -> nxt[c];
  }
}
int solve(string s) {
  node *cur = root;
  for(int i = 0; i + 1 < s.size(); i++) {
    int c = s[i] - 'a';
    cur = cur -> nxt[c];
  }
  return cur -> cnt[s.back() - 'a'] - 1;
}

string s[maxn];

int main() {
  int n;
  cin >> n;
  root = new node();
  for(int i = 0; i < n; i++) {
    cin >> s[i];
    reverse(s[i].begin(), s[i].end());
    insert(s[i]);
  }
  long long ans = 0;
  for(int i = 0; i < n; i++) {
    ans += solve(s[i]);
  }
  cout << ans << endl;
  return 0;
}

