			}
		}
	}
}

int query(string s, int i, int n = root) {
	if(i == 0){
		return nodes[n].cc[getIndex(s[i])];
	}
	if(nodes[n].c[getIndex(s[i])] == -1)
		return 0;
	else
		return query(s, i -1, nodes[n].c[getIndex(s[i])]);
}

