template<typename T, char start='a', int C=26>
struct Trie{
    struct Node{
        vector<int> ch, dp;
        T val;
        Node(){
            val = 0;
            ch.assign(C, -1);
            dp.assign(C, 0);
        }
    };

    vector<Node> nodes;
    int64_t ans = 0;

    Trie(){ nodes.push_back(Node()); }

    int add(int nd, int d, const string& S, vector<int>& num){
        if(int(S.size()) == d){
            nodes[nd].val = 1;
            return nd;
        }else{
            for(int j=0; j<26; j++) if(num[j]){
                int c = nodes[nd].ch[j];
                if(c != -1 && nodes[c].val) ans++;
            }
            int c = S[d] - start;
            num[c]--;
            if(nodes[nd].ch[c] == -1){
                nodes[nd].ch[c] = nodes.size();
                nodes.push_back(Node());
            }
            return add(nodes[nd].ch[c], d+1, S, num);
        }
    }
    int add(const string& S){
        vector<int> num(C);
        for(char c : S) num[c-'a']++;
        return add(0, 0, S, num);
    }
};

