class RollingHash {
	string s;
	int n;
	ModInt base;
	vector<ModInt> has, power;
public:
	RollingHash(string s, int b) : n(s.size()), base(b) { init(s, b); }
	void init(string s, int b) {
		n = s.size();
		has.resize(n);
		power.resize(n);
		base = ModInt(b);
		this->s = s;
		rep(i, n) {
			has[i] = ModInt(s[i]);
			if (i) {
				has[i] += base * has[i - 1];
				power[i] = power[i - 1] * base;
			}
			else power[i] = 1;
		}
	}
	operator int() const {
		return has.back();
	}
	ModInt query(int a, int b) {
		return has[b - 1] - power[b - a] * (!a ? ModInt(0) : has[a - 1]);
	}
	RollingHash& operator+=(string t) {
		s += t;
		has.resize(n + t.size());
		power.resize(n + t.size());
		for (int i = n; i < n + t.size(); i++) {
			has[i] = ModInt(t[i] * base);
			has[i] += base * has[i - 1];
			power[i] = power[i - 1] * base;
		}
		n += t.size();
		return *this;
	}
};
