// Trie
/*-----------------------------*/
// Map[{l,k}] := cnt of a group of k strings such that they a common prefix of
// lenght l
map<pii, int> Map;
/*-------Trie Setting---------*/
const int Alphabets = 26;
const int AlphabetBase = 'a';  // '0'
/*------------------------------------*/
class Trie {
   public:
    struct node {
        bool isleaf;
        node* children[Alphabets];
        int id;
        int cnt;
        node() : cnt(0), isleaf(0), id(nodesize++) {
            memset(children, 0, sizeof children);
        }
    } * root;
    static int nodesize;

    // check children
    static bool is_free_node(node* n) {
        for (int i = 0; i < Alphabets; i++) {
            if (n->children[i] != NULL) return true;
        }
        return false;
    }

    bool _remove(const string& s, node* n, int level) {
        if (level == (int)s.size())
            return 1;
        else {
            int idx = s[level] - AlphabetBase;
            if (_remove(s, n->children[idx], level + 1)) {
                Map[pii(level + 1, n->children[idx]->cnt)]--;
                n->children[idx]->cnt--;
                return 1;
            }
        }
        return 1;
    }

    void DEL(const string& s, node* n, int level) {
        if (level == (int)s.size()) return;
        int idx = s[level] - AlphabetBase;
        n = n->children[idx];
        Map[pii(level + 1, n->cnt)]--;
        n->cnt--;
        DEL(s, n, level + 1);
    }

    static void clean_up(node* n) {
        if (n == 0 || n->isleaf) return;
        for (int i = 0; i < Alphabets; i++) clean_up(n->children[i]);
        delete n;
    }

   public:
    Trie() { root = new node(); }
    ~Trie() { clean_up(root); }

    int getnodesize() { return nodesize; }
    void insert(string& s) {
        node* n = root;
        for (int level = 0; level < (int)s.size(); level++) {
            int idx = s[level] - AlphabetBase;
            if (n->children[idx] != NULL)
                n = n->children[idx];
            else {
                n->children[idx] = new node();
                n = n->children[idx];
            }
            n->cnt++;
            Map[pii(level + 1, n->cnt)]++;
        }
        n->isleaf = 1;
    }
    bool exists(string& s) {
        node* n = root;
        for (int level = 0; level < (int)s.size(); level++) {
            int idx = s[level] - AlphabetBase;
            if (n->children[idx] == NULL) return 0;
            n = n->children[idx];
        }
        return (n != 0 && n->isleaf);  //
    }
    bool remove(string& s) { return _remove(s, root, 0); }
    void DEL(string& s) { DEL(s, root, 0); }
};
int Trie::nodesize = 0;

