void Add(trie *tr, int lvl, string &S, int my[])
{
    for (int i = 0; i < Maxl; i++)
        if (my[lvl] & 1 << i) tr->cnt[i]++;
    if (lvl == 0) return;
    int ind = S[lvl] - 'a';
    if (!tr->ch[ind]) tr->ch[ind] = new trie();
    Add(tr->ch[ind], lvl - 1, S, my);
}

int Get(trie *tr, int lvl, string &S)
{
    if (lvl == 0) return tr->cnt[S[0] - 'a'] - 1;
    else return Get(tr->ch[S[lvl] - 'a'], lvl - 1, S);
}

