/*
https://qiita.com/keymoon/items/11fac5627672a6d6a9f6
RollingHash(s, mod, base):= 文字列 s のハッシュテーブルを構築する。
get(l, r):= 区間 [l,r) のハッシュ値を求める。
connect(h1, h2, h2len):= ハッシュ値 h1 と, 長さ h2len のハッシュ値 h2 を結合する。
LCP(b, l1, r1, l2, r2):= 区間 [l1,r1) と, ハッシュテーブルが b からなる区間 [l2,r2) の文字列の最長共通接頭辞の長さを求める。
*/
constexpr __uint128_t mod = (1ull << 61ull) - 1;
__uint128_t power[1010101];
__uint128_t rhbase;
static inline uint64_t add(uint64_t a, uint64_t b) {
	if((a += b) >= mod) { a -= mod; } return a;
}
static inline uint64_t mul(uint64_t a, uint64_t b) {
	__uint128_t c = (__uint128_t) a * b; return add(c >> 61, c & mod);
}
void init_rollinghash(){
	mt19937_64 mt(chrono::steady_clock::now().time_since_epoch().count());
	uniform_int_distribution< __uint128_t > rand(1, mod - 1);
	rhbase = rand(mt);
	power[0] = 1;
	for(ll i = 0; i < 1010100; i++) {
		power[i + 1] = mul(power[i], rhbase);
	}
}
class RollingHash {
public:
	vector< __uint128_t > hashed;
	const __uint128_t base;

	RollingHash() = default;

	RollingHash(const string &s, __uint128_t base = rhbase) : base(base) {
		ll sz = s.size();
		hashed.assign(sz + 1, 0);
		for(ll i = 0; i < sz; i++) {
			hashed[i + 1] = add(mul(hashed[i], base), s[i]);
		}
	}

	template< typename T >
	RollingHash(const vector< T > &s, __uint128_t base = rhbase) : base(base) {
		size_t sz = s.size();
		hashed.assign(sz + 1, 0);
		for(ll i = 0; i < sz; i++) {
			hashed[i + 1] = add(mul(hashed[i], base), s[i]);
		}
	}

	__uint128_t query(ll l, ll r) const {
		return add(hashed[r], mod - mul(hashed[l], power[r - l]));
	}

	__uint128_t combine(__uint128_t h1, __uint128_t h2, size_t h2len) const {
		return add(mul(h1, power[h2len]), h2);
	}

	ll lcp(const RollingHash &b, ll l1, ll r1, ll l2, ll r2) const {
		assert(base == b.base);
		ll len = min(r1 - l1, r2 - l2);
		ll low = 0, high = len + 1;
		while(high - low > 1) {
			ll mid = (low + high) / 2;
			if(query(l1, l1 + mid) == b.query(l2, l2 + mid)) low = mid;
			else high = mid;
		}
		return low;
	}
};

