struct Trie{
    // short cntpc[MAXN][26] = {};
    int head = 1, tot = 1; // head is idx of head node, tot is the last allocated node

    int & __alloc() {
        cnt[++tot] = 0;
        memset(nxt[tot], 0, sizeof(nxt[tot]));
        return tot;
    }

    void clear() { tot = 0; head = __alloc(); }

    int insert(const string & s) {
        int n = s.size();
        dp[n] = vector<bool>(26);
        rrep(i,n-1,-1){
            dp[i]=dp[i+1];
            dp[i][s[i]-'a']=1;
        }

        int tmp = head;
        int res=0;

        cntp[tmp]++;
        for(int i = 0; i < s.size(); i++) {
            rep(j,0,26) 
                if(dp[i][j] && nxt[tmp][j]) 
                    res+=cnt[nxt[tmp][j]];

            if(nxt[tmp][s[i] - 'a']) tmp = nxt[tmp][s[i] - 'a'];
            else tmp = nxt[tmp][s[i] - 'a'] = __alloc();
            cntp[tmp]++;
        }
        // print("visiting node ", tmp);
        cnt[tmp]++;
        return res;
    }

} trie;

