int main() {
  ios_base::sync_with_stdio(false);

  int n;
  cin >> n;
  vector<string> a(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
    reverse(a[i].begin(), a[i].end());
  }

  auto f = [](long long v, int c) {
    long long res = (1LL * 9487 * v + c) % 29996224275833;
    return res;
  };
  auto rh = [&](string &s) {
    int n = s.length();
    vector<long long> res(n + 1);
    for (int i = 0; i < n; i++) {
      res[i + 1] = f(res[i], s[i]);
    }
    return res;
  };

  const int N = 1e6 + 5;
  vector<vector<long long>> mp(N);

  auto hash = [&](string &s) {
    int L = s.length();
    vector<long long> h = rh(s);
    vector<int> last(26, -1);

    for (int i = 0; i < L; i++) {
      last[s[i] - 'a'] = i;
    }  

    for (int i = 0; i <= L; i++) {
      long long pref = h[i];
      for (int j = 0; j < 26; j++) {
        if (last[j] < i) continue;
        long long all = f(pref, j + 'a');
        mp[i].push_back(all);
      }
    }
  };
  for (auto s : a) {
    hash(s);
  }
  for (auto &i : mp) {
    sort(i.begin(), i.end());
  }

  long long ans = 0;
  for (auto s : a) {
    int L = s.length();
    long long cur = rh(s)[L];
    auto l = lower_bound(mp[L - 1].begin(), mp[L - 1].end(), cur);
    auto r = lower_bound(mp[L - 1].begin(), mp[L - 1].end(), cur + 1);
    ans += (r - l);
  }
  cout << ans - n << '\n';

  return 0;
}

