struct rolling_hash {
  static const uint64_t mod = (1ull << 61ull) - 1;
  using uint128_t = __uint128_t;
  vector<uint64_t> hashed, power;
  const uint64_t base;

  static inline uint64_t add(uint64_t a, uint64_t b) {
    if ((a += b) >= mod) a -= mod;
    return a;
  }

  static inline uint64_t mul(uint64_t a, uint64_t b) {
    uint128_t c = (uint128_t)a * b;
    return add(c >> 61, c & mod);
  }

  static inline uint64_t generate_base() {
    mt19937_64 mt(chrono::steady_clock::now().time_since_epoch().count());
    uniform_int_distribution<uint64_t> rand(1, rolling_hash::mod - 1);
    return rand(mt);
  }

  rolling_hash() = default;

  rolling_hash(const string &s, uint64_t base) : base(base) {
    size_t sz = s.size();
    hashed.assign(sz + 1, 0);
    power.assign(sz + 1, 0);
    power[0] = 1;
    for (int i = 0; i < sz; i++) {
      power[i + 1] = mul(power[i], base);
      hashed[i + 1] = add(mul(hashed[i], base), s[i]);
    }
  }

  template <typename T>
  rolling_hash(const vector<T> &s, uint64_t base) : base(base) {
    size_t sz = s.size();
    hashed.assign(sz + 1, 0);
    power.assign(sz + 1, 0);
    power[0] = 1;
    for (int i = 0; i < sz; i++) {
      power[i + 1] = mul(power[i], base);
      hashed[i + 1] = add(mul(hashed[i], base), s[i]);
    }
  }

  uint64_t query(int l, int r) const {
    return add(hashed[r], mod - mul(hashed[l], power[r - l]));
  }

  uint64_t combine(uint64_t h1, uint64_t h2, size_t h2len) const {
    return add(mul(h1, power[h2len]), h2);
  }

  int lcp(const rolling_hash &b, int l1, int r1, int l2, int r2) const {
    assert(base == b.base);
    int len = min(r1 - l1, r2 - l2);
    int low = 0, high = len + 1;
    while (high - low > 1) {
      int mid = (low + high) / 2;
      if (query(l1, l1 + mid) == b.query(l2, l2 + mid)) low = mid;
      else high = mid;
    }
    return low;
  }
};

void solve(int n, vector<string> s) {
  vector<pair<int, string>> ls(n);
  rep(i, n)ls[i] = mp(sz(s[i]), s[i]);
  SORT(ls);
  vm hs(26);
  auto rh_base = rolling_hash::generate_base();
  int ans = 0;
  each(p, ls) {
    auto [l, x] = p;
    rolling_hash rh(x, rh_base);
    vb cm(26);
    rep(i, p.first) {
      cm[x[i] - 'a'] = true;
      auto h = rh.query(i + 1, l);
      rep(j, 26) {
        if(cm[j])ans += hs[j][h];
      }
    }
    hs[x[0] - 'a'][rh.query(1, l)]++;
  }
  COUT(ans);
}


