template<int char_size>
struct TrieNode {
  int nxt[char_size];

  int exist;
  int counter[char_size];
  vector<int> accept;

  TrieNode() : exist(0) {
    memset(counter, 0, sizeof(counter));
    memset(nxt, -1, sizeof(nxt));
  }
};

template<int char_size, int margin>
struct Trie {
  using Node = TrieNode<char_size>;

  vector<Node> nodes;
  int root;

  Trie() : root(0) {
    nodes.push_back(Node());
  }

  void update_direct(int node, int id) {
    nodes[node].accept.push_back(id);
  }

  void update_child(int node, int child, int id, vb &used) {
    rep(i,char_size) nodes[node].counter[i] += used[i];
  }

  void add(const string &str, int str_index, int node_index, int id, vb &used) {
    if (str_index == str.size()) {
      update_direct(node_index, id);
    } else {
      const int c = str[str_index] - margin;
      if (nodes[node_index].nxt[c] == -1) {
        nodes[node_index].nxt[c] = (int) nodes.size();
        nodes.push_back(Node());
      }
      add(str, str_index + 1, nodes[node_index].nxt[c], id, used);
      used[c] = true;
      update_child(node_index, nodes[node_index].nxt[c], id, used);
    }
  }

  void add(const string &str, int id) {
    vb used(char_size, false);
    add(str, 0, 0, id, used);
  }

  void add(const string &str) {
    add(str, nodes[0].exist);
  }

  void query(const string &str, const function<void(int)> &f, int str_index, int node_index) {
    if (str_index == str.size()) {
      f(node_index);
    } else {
      const int c = str[str_index] - margin;
      if (nodes[node_index].nxt[c] == -1) return;
      query(str, f, str_index + 1, nodes[node_index].nxt[c]);
    }
  }

  void query(const string &str, const function<void(int)> &f) {
    query(str, f, 0, 0);
  }

  int count() const {
    return (nodes[0].exist);
  }

  int size() const {
    return ((int) nodes.size());
  }
};

void solve() {
  int n; cin >> n;
  vector<string> g(n); cin >> g;
  for (auto &s : g) reverse(ALL(s));

  Trie<26, 'a'> trie;
  for (auto &s : g) trie.add(s);

  ll ans = 0;

  for (auto &s : g) {
    int c = s.back() - 'a';
    s.pop_back();
    trie.query(s, [&](int idx) { ans += trie.nodes[idx].counter[c] - 1; });
  }

  cout << ans << endl;
}


