bool cl(string const& a,string const& b){
  return a.length()>b.length();
}
int judge(string const& b,string const& a){
  int n=b.length();
  int cur=0;
  int a_size=a.length();
  string last=a.substr(2,a_size-2);

  if(last!=b.substr(n-(a_size-2),a_size-2))return 0;

  rep(i,n){
    if(cur>0){
      if(a[1]==b[i]){
        if(n-1-i==a.length()-2){
          if(b.substr(i+1,n-1-i)==a.substr(2,a_size-2))return 1;
          else return 0;
        }
      }
      else{
        if(n-1-i<=a_size-2)return 0;
      }
    }
    else if(a[cur]==b[i])++cur;
  }
  return 0;
}

signed main(){
  int n;cin>>n;
  vector<string> s(n);
  rep(i,n)cin>>s[i];
  sort(s.begin(),s.end(),cl);
  int res=0;
  //cout<<"DEBUG"<<"\n";
  //rep(i,n)cout<<s[i]<<"\n";
  rep(i,n)s[i]+='.';
  rep(i,n){
    rep(j,n){
      if(s[i].length()<s[j].length()){
        res+=judge(s[j],s[i]);
        //printf("(i,j)=(%d, %d), res=%d\n",i,j,res);
      }
      else break;
    }
  }
  cout<<res<<"\n";
  return 0;
}

