#define MAXN 200100
int cnt[MAXN][26];
typedef pair<int, char> ic;
map<ic, vec<ic>> G;

int t[MAXN][26];
int numV = 0;
int nowIndex = 0;
int ans = 0;

void dfs(ic id, ic parent, string S, int pos) {
  if (pos == (int)S.size()) return;
  REP(i, 26) { cnt[id.fst][i] += t[nowIndex][i] >= pos; }
  bool flg = true;
  FORA(e, G[id]) {
    if (e != parent) {
      if (e.snd == S[pos]) {
        dfs(e, id, S, pos + 1);
        flg = false;
      }
    }
  }
  if (flg) {
    ic ele = mp(++numV, S[pos]);
    G[id].pb(ele);
    G[ele].pb(id);
    dfs(ele, id, S, pos + 1);
  }
}
void dfs2(ic id, ic parent, string S, int pos) {
  if (pos == (int)S.size() - 1) {
    ans += cnt[id.fst][S[pos] - 'a'];
    return;
  }
  FORA(e, G[id]) {
    if (e != parent) {
      if (e.snd == S[pos]) {
        dfs2(e, id, S, pos + 1);
      }
    }
  }
}
