    for (auto c: str) {
      i32 idx = path.back();
      path.pop_back();
      has[c - 'a'] = 1;
      for (auto i: range(0, 26)) {
        node[idx].count[i] += has[i];
      }
    }
  }
  i32 ans = 0;
  for (auto &x: S) {
    const auto str = x.substr(0, x.size() - 1);
    i32 cur = root;
    for (auto c: str) {
      cur = node[cur].child[c - 'a'];
    }
    ans += node[cur].count[x.back() - 'a'];
  }
  std::cout << ans - N << '\n';
  return 0;
}

