template<int char_size, char base>
struct Trie{
    struct Node{
        vector<int> next, accept;
        vector<ll> cnt;
        int count; //子以下に追加された文字列の数

        Node() : count(0){
            next.assign(char_size, -1);
            cnt.assign(char_size, 0);
        }
    };

    vector<Node> nodes;

    Trie() {nodes.eb();}

    int count() const {return nodes.front().count;}

    int size() const {return sz(nodes);}

    void insert(const string &s, int id = -1){
        int now = 0;
        rep(i, sz(s)){
            int &next = nodes[now].next[s[i]-base];
            if(next == -1){
                next = size(), nodes.eb();
            }
            nodes[now].count++, now = next;
        }
        nodes[now].count++, nodes[now].accept.pb(id == -1? count()-1 : id);
    }

    bool search(const string &s, bool prefix = false){
        int now = 0;
        rep(i, sz(s)){
            now = nodes[now].next[s[i]-base];
            if(now == -1) return false;
        }
        return (prefix)? true : !nodes[now].accept.empty();
    }

    void dfs(int now){
        rep(i, char_size){
            int e = nodes[now].next[i];
            if(e == -1) continue;
            dfs(e);
            rep(j, char_size) nodes[now].cnt[j] += nodes[e].cnt[j];
            nodes[now].cnt[i] += nodes[e].count;
        }
    }

    ll query(const string &s){
        int now = 0;
        rep(i, sz(s)-1) now = nodes[now].next[s[i]-base];
        return nodes[now].cnt[s.back()-base]-1;
    }
};

