using namespace std;

inline int inv(int a, int md) {
  a %= md;
  if (a < 0) a += md;
  int b = md, u = 0, v = 1;
  while (a) {
    int t = b / a;
    b -= t * a; swap(a, b);
    u -= t * v; swap(u, v);
  }
  assert(b == 1);
  if (u < 0) u += md;
  return u;
}

class HASH {
  public:;
  int a = 1e9 + 7;
  int b = 998244353;
  int x = 0, y = 0;
  HASH(){};
  HASH(int _x, int _y) : x(_x), y(_y) {
    if(x < 0) x += a;
    if(x >= a) x -= a;
    if(y < 0) y += b;
    if(y >= b) y -= b;
  };

  HASH operator + (const HASH &c) const {
    return HASH(x + c.x, y + c.y);
  }
  HASH operator - (const HASH &c) const {
    return HASH(x - c.x, y - c.y);
  }
  HASH operator * (const HASH &c) const {
    return HASH(((long long) x * c.x) % a, ((long long) y * c.y) % b);
  }
  HASH operator * (int c) const {
    return HASH(((long long) x * c) % a, ((long long) y * c) % b);
  }
  HASH operator / (const HASH &c) const {
    HASH _c = HASH(inv(c.x, a), inv(c.y, b));
    return *this * _c;
  }
  HASH operator / (int c) const {
    return *this / HASH(c, c);
  }
  bool operator < (const HASH &c) const {
    return make_pair(x, y) < make_pair(c.x, c.y);
  }
};

class suffix_hash {
  public:;
  string s;
  vector<HASH> pref;
  HASH c;
  int n;
  vector<HASH> p;
  suffix_hash(string _s) : s(_s) {
    HASH c(97, 31);
    n = s.length();
    pref.resize(n + 1);
    p.resize(n + 1);
    p[0] = HASH(1, 1);
    for(int i = 1; i < n + 1; i++) {
      p[i] = p[i - 1] * c;
    }
    for(int i = 1; i < n + 1; i++) {
      pref[i] = pref[i - 1] + p[i] * (s[i - 1] - 'a' + 3);
    }
  }
  long long get(int l, int r) {
    int md = 1e9 + 7;
    HASH cc = (pref[r] - pref[l]) / p[l];
    return 1LL * cc.x * md + cc.y;
  }
};

