    suffix_hash cur(s[i]);
    long long c = cur.get(0, s[i].length() - 1);
    res += cnt[make_pair(c, s[i].back())];
    for(int j = 0; j < (int) s[i].length(); j++) {
      for(int u = 0; u < 26; u++) {
        char t = 'a' + u;
        long long p = cur.get(0, j + 1);
        if(last[u] <= j) continue;
        cnt[make_pair(p, t)]++;
      }
    }
    for(int j = 0; j < 26; j++) if(last[j] > -1) cnt[make_pair(0, 'a' + j)]++;
  }
  cout << res;
  return 0;
}

