template<int char_size,int margin>
class Trie{
private:
    struct Node{
        int ne[char_size];
        int num;
        vec<int> accept;
        Node():num(0){
            memset(ne,-1,sizeof(ne));
        }
    };

    vec<Node> nodes;
    int root;
public:
    Trie():root(0){
        nodes.push_back(Node());
    }

    void update_direct(int node,int id){
        nodes[node].accept.push_back(id);
        nodes[node].num++;
    }

    void add(const string& S,int s_id,int node_id,int id){
        if(s_id==S.size()) update_direct(node_id,id);
        else{
            int c = S[s_id]-margin;
            if(nodes[node_id].ne[c]==-1){
                nodes[node_id].ne[c] = (int) nodes.size();
                nodes.push_back(Node());
            }
            add(S,s_id+1,nodes[node_id].ne[c],id);
        }
    }

    void add(const string& S,int id){
        add(S,0,0,id);
    }

    void add(const string &S){
        add(S,nodes[0].num);
    }

    template<class F>
    void query(const string& S,F& f,int s_id,int node_id){
        for(auto& id:nodes[node_id].accept) f(id);
        if(s_id==S.size()) return ;
        else{
            int c = S[s_id]-margin;
            if(nodes[node_id].ne[c]==-1) return ;
            query(S,f,s_id+1,nodes[node_id].ne[c]);
        }
    }

    void dfs(const string& S,int s_id,int node_id,set<char>& st,ll& ans){
        if(node_id==-1) exit(0);
        if(s_id==S.size()){
            ans += nodes[node_id].num;
            return ;
        }
        int nc = S[s_id]-margin;
        dfs(S,s_id+1,nodes[node_id].ne[nc],st,ans);
        st.insert(S[s_id]);
        for(auto& c:st){
            int id = nodes[node_id].ne[c-margin];
            if(id!=-1) nodes[id].num++;
        }
    }

    template<class F>
    void query(const string& S,F& f){
        query(S,f,0,0);
    }

    int count()const{
        return nodes[0].num;
    }

    int size()const{
        return (int) nodes.size();
    }

};

