class RH{
public:
    using u64 = uint_fast64_t;
    using size_type = uint_fast32_t;
    using i128 = __int128_t;

    static constexpr u64 MOD = (1ul << 61) - 1;
    static constexpr u64 base = 20200819; // random

    string S;
    vector<u64> hash_,pow;

private:
    static constexpr u64 mask30 = (1ul << 30) - 1;
    static constexpr u64 mask31 = (1ul << 31) - 1;

    u64 mul(i128 a, i128 b) const{
        i128 t = a * b;
        t = (t >> 61) + (t & MOD);

        if(t >= MOD) return t - MOD;
        return t;
    }
    size_type xorshift(size_type x) const{
        x ^= x << 13;
        x ^= x >> 17;
        x ^= x << 5;
        return x;
    }
public:
    RH(const RH &) = default;
    RH(RH&&) = default;

    RH():S(){}
    RH(const string& S) : S(S){
        size_type SL = (size_type)S.length();

        hash_.resize(SL+1,0);
        pow.resize(SL+1,1);
        for(size_type i = 0; i < SL; i++){
            hash_[i+1] = mul(hash_[i],base) + xorshift(S[i]+1);
            pow[i+1] = mul(pow[i],base);
            if(hash_[i+1] >= MOD) hash_[i+1] -= MOD;
        }
    }

    void apply(const char c){
        S.push_back(c);
        hash_.emplace_back(mul(hash_.back(),base) + xorshift(c+1));
        pow.emplace_back(mul(pow.back(),base));
        if(hash_.back() >= MOD) hash_.back() -= MOD;
    }
    u64 hash() const { return hash_.back(); }
    u64 hash(size_type r) const{
        return hash(0,r);
    }
    u64 hash(size_type l, size_type r) const{
        u64 ret = MOD + hash_[r] - mul(hash_[l],pow[r-l]);
        return ret < MOD ? ret : ret - MOD;
    }
    u64 back_hash(size_type i) const{
        size_type SL = (size_type)S.length();
        return hash(SL-i,SL);
    }

    // LCP : 最長共通接頭辞
    /*
     * 自身の部分文字列[l1,r1)とRH bの部分文字列[l2,r2)との最長共通接頭辞の右端を求める
     * 自身の部分文字列[l1,l1+戻り値)が最長共通接頭辞 (戻り値文の文字)
     */
    size_type LCP(const RH& b,size_type l1, size_type r1,size_type l2,size_type r2){
        size_type len = min(r1-l1,r2-l2);

        size_type l = 0, r = len+1;
        while(r-l>1){
            size_type m = (l+r)/2;
            if(this->hash(l1,l1+m) == b.hash(l2,l2+m)){
                l = m;
            }else{
                r = m;
            }
        }
        return l;
    }
    size_type LCP(const RH& b){
        return LCP(b,0,this->S.length(),0,b.S.length());
    }
    size_type size() const { return S.length(); }
};


using ull = RH::u64;
template <class Type>
Type solve(Type res = Type()) {
    int N;
    cin >> N;
    vector<string> S(N);
    for (auto& in : S) cin >> in;

    map<char, int> one_alpha;
    using Item = pair<ull, char>;
    map<Item, map<char, int>> mp;

    for (int i = 0; i < N; i++) {
        if (S[i].length() == 1) {
            one_alpha[S[i][0]]++;
        } else {
            // add
            RH rh(S[i]);
            char a = S[i][0], b = S[i][1];
            mp[make_pair(rh.hash(2, (int)S[i].length()), b)][a]++;
        }
    }
    for (int i = 0; i < N; i++) {
        if (S[i].length() == 1) {
            res += one_alpha[S[i][0]];
        } else {
            {
                set<char> alpha;
                for (auto& c : S[i]) alpha.emplace(c);

                int T = 0;
                for (auto& c : alpha) {
                    T += one_alpha[c];
                }
                res += T;
            }
            {
                RH rh(S[i]);
                // search
                multiset<char> st;
                for (int j = 0; j < (int)S[i].length(); j++) {
                    st.emplace(S[i][j]);
                }

                int T = 0;
                for (int j = (int)S[i].length(); j >= 2; j--) {
                    st.erase(st.lower_bound(S[i][j - 1]));
                    ull h = rh.hash(j, (int)S[i].length());

                    for(auto& p:mp[make_pair(h,S[i][j-1])]){
                        if (st.find(p.first) != st.end()) {
                            T += p.second;
                        }
                    }
                }
                res += T;
            }
        }
    }
    res = res - N;

    return res;
}

