class Rolliha{
public:
    using ull=unsigned long long int;
    using uint=unsigned int;
    const ull MASK30=(1ULL<<30)-1;
    const ull MASK31=(1ULL<<31)-1;
    const ull MOD_rh=(1ULL<<61)-1;
    const ull POSITIVIZER=MOD_rh*((1ULL<<3)-1);

    int sz;
    vector<ull> hash_table,power; //1-indexed

    Rolliha(const string& s,uint base=0):sz{(int)s.size()}{
        hash_table.assign(sz+1,0);
        power.assign(sz+1,1);

        random_device rd;
        uniform_int_distribution<uint> dist(129,numeric_limits<int>::max()-1);
        if(base==0) base=dist(rd);

        rep(i,sz){
            power[i+1]=mul(power[i],base);
            hash_table[i+1]=mul(hash_table[i],base)+s[i];
            if(hash_table[i+1]>=MOD_rh) hash_table[i+1]-=MOD_rh;
        }
    }

    //(l,r] 1-indexedの場合
    ull sechash(int l,int r){
        return calc_mod(hash_table[r]+POSITIVIZER-mul(hash_table[l],power[r-l]));
    }

    //mod 2^61-1
    ull mul(ull a,ull b){
        ull aq=a>>31, bq=b>>31;
        ull ar=a&MASK31, br=b&MASK31;
        ull mid=aq*br+ar*bq;
        ull midu=mid>>30;
        ull midl=mid&MASK30;
        return ((aq*bq)<<1)+midu+(midl<<31)+ar*br;
    }

    ull mul(ull a,uint b){
        ull aq=a>>31;
        ull ar=a&MASK31, br=b&MASK31;
        ull mid=aq*br;
        ull midu=mid>>30;
        ull midl=mid&MASK30;
        return midu+(midl<<31)+ar*br;
    }

    ull calc_mod(ull x){
        ull xq=x>>61;
        ull xr=x&MOD_rh;
        ull res=xq+xr;
        if(res>=MOD_rh) res-=MOD_rh;
        return res;
    }
};

