struct Trie {
  int ch[26];
  int ex;
  Trie() {
    clear();
  }
  void clear() {
    REP(i, 26) ch[i] = -1;
    ex = 0;
  }
};

const int MAX_C = 1123456;
Trie trie[MAX_C];
int trie_sz = 0;

void add_trie(const int id, const string &s, const int pos) {
  if (pos == (int)s.size()) {
    trie[id].ex = 1;
    return;
  }
  int c = s[pos] - 'a';
  if (trie[id].ch[c] == -1) {
    trie[id].ch[c] = trie_sz++;
  }
  add_trie(trie[id].ch[c], s, pos + 1);
}

void walk_trie(const int id, const string&s, const int pos, ll &ans, vector<ll>& count) {
  if (pos == (int)s.size()) {
    return ;
  }

  REP(d, 26) if (count[d] > 0) {
    int nid = trie[id].ch[d];
    if (nid != -1) {
      if (trie[nid].ex) { ans++;
      //  cout << s.substr(0, pos) << " " << (char)(d+'a') << endl;
      }
    }
  }

  int c = s[pos] - 'a';
  if (trie[id].ch[c] != -1) {
    count[c]--;
    walk_trie(trie[id].ch[c], s, pos + 1, ans, count);
  }
}

