};

int main() {
	int n;
	std::cin >> n;
	std::vector<std::string> s(n);
	rep(i,n) std::cin >> s[i];
	// create trie
	std::vector<Node> trie;
	trie.emplace_back(' ',false,0);
	auto add = [&](auto f,int i,std::string& t,int j) -> void {
		if(j==-1) {
			trie[i].end=true;
			return;
		}
		if(trie[i].to[t[j]-'a']==-1) {
			int k=trie.size();
			trie[i].to[t[j]-'a']=k;
			trie.emplace_back(t[j],false,k);
			f(f,k,t,j-1);
		} else {
			f(f,trie[i].to[t[j]-'a'],t,j-1);
		}
	};
	rep(i,n) {
		add(add,0,s[i],s[i].size()-1);
	}
	lnt ans=0;
	std::vector<lnt> v(26,0);
	std::vector<lnt> active(26,0);
