		rep(j,26) {
			int to=trie[i].to[j];
			if(to==-1) continue;
			if(trie[to].end) v[j]++;
		}
		rep(j,26) {
			int to=trie[i].to[j];
			if(to==-1) continue;
			f(f,to);
		}
		if(activated) {
			active[trie[i].c-'a']-=activated;
		}
		rep(j,26) {
			int to=trie[i].to[j];
			if(to==-1) continue;
			if(trie[to].end) v[j]--;
		}
	};
	dfs(dfs,0);
