const int N = 2e5 + 10;

int n, tmp[ABC];
map <char, int> cnt;

struct node{
	int cnt[ABC];
	node *nxt[ABC];

	node () {
		memset(cnt, 0, sizeof cnt);
		REP(i, ABC)
			nxt[i] = NULL;
	}
} *root;

void Add(const string &s){
	FORA(x, s)
		tmp[x - 'a']++;

	node *curr = root;
	REP(i, ABC)
		curr -> cnt[i] += tmp[i];

	FORA(x, s){
		tmp[x - 'a']--;
		if (curr -> nxt[x - 'a'] == NULL)
			curr -> nxt[x - 'a'] = new node();
		curr = curr -> nxt[x - 'a'];
		REP(i, ABC)
			curr -> cnt[i] += (tmp[i] ? 1 : 0);
	}
}

int Query(const string &s){
	node *curr = root;
	REP(i, sz(s) - 1){
		int x = s[i] - 'a';
		if (curr -> nxt[x] == NULL)
			return 0;
		curr = curr -> nxt[x];
	}

	return curr -> cnt[s.back() - 'a'];
}

int main () {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	root = new node();

	cin >> n;
	vs v;
	ll sol = 0;
	REP(i, n){
		string s; cin >> s;
		if (sz(s) == 1){
			sol += cnt[s[0]];
			cnt[s[0]]++;
		} else {
			reverse(all(s));
			v.PB(s);
			Add(s);
		}
	}

	FORA(x, v){
		if (sz(x) == 2)
			sol += cnt[x[0]] + cnt[x[1]];
		sol += Query(x) - 1;
	}

	cout << sol << '\n';

	return 0;
}

