struct node_t {
    map<char, node_t*> go;
    array<int, 27> marks;
    bool is_term = false;
};

void traverse(node_t* v, int64_t& ans) {
    array<int, 26> sum;
    std::fill(ALL(sum), 0);

    for (auto& el: v->go) {
        for (int j = 0; j < 26; ++j)
            sum[j] += el.second->marks[j];
    }

    for (auto& el: v->go) {
        traverse(el.second, ans);

        if (el.second->is_term)
            ans += sum[el.first - 'a'] - el.second->marks[el.first - 'a'];
    }

    if (v->is_term) {
        ans += v->marks[26] - 1;
    }
}

int main() {
    std::iostream::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    // code here
    node_t* root = new node_t();

    int n = input<int>();
    int64_t ans = 0;

    for (int i = 0; i < n; ++i) {
        string s;
        cin >> s;
        reverse(ALL(s));

        vector<node_t*> seq = {root};

        node_t* cur = root;
        for (char ch: s) {
            if (not cur->go[ch])
                cur->go[ch] = new node_t();

            cur = cur->go[ch];
            seq.push_back(cur);
        }

        cur->is_term = 1;
        cur->marks[26] += 1;

        int markset = 1 << 26;
        for (int i = SZ(s) - 1; i >= 0; --i) {
            markset |= (1 << (s[i] - 'a'));

            for (int j = 0; j <= 26; ++j)
                if (markset & (1 << j))
                    seq[i]->marks[j] += 1;
        }
    }

    traverse(root, ans);
    cout << ans << "\n";

    return 0;
}

