int get(int c, int r) {
	int s = 0;
	while (r >= 0) {
		s += f[c][r];
		r &= r + 1;
		--r;
	}
	return s;
}
int get(int c, int l, int r) {
	return get(c, r) - get(c, l - 1);
}
void upd(int c, int pos) {
	while (pos < N) {
		f[c][pos]++;
		pos |= pos + 1;
	}
}
