using namespace std;

struct Node {
    map<char, Node*> sons;
    vector<int64_t> count_below;

    Node() : count_below(26, 0) {}
};

void Insert(Node* &root, const string &word, int index, vector<bool> &seen) {
    if (index < 0) {
        return;
    }

    auto ch = word[index];
    if (root->sons.count(ch) == 0) {
        root->sons[ch] = new Node();
    }

    Insert(root->sons[ch], word, index - 1, seen);
    seen[ch - 'a'] = true;
    for (size_t i = 0; i < seen.size(); i += 1) {
        if (seen[i]) {
            root->count_below[i] += 1;
        }
    }
}

Node* BuildTrie(const vector<string> &words) {
    auto root = new Node();
    for (const auto &word : words) {
        vector<bool> seen(26, false);
        Insert(root, word, word.size() - 1, seen);
    }
    return root;
}

int64_t CountMatches(Node *root, const string &word) {
    auto iter = root;
    for (int i = word.size() - 1; i > 0; i -= 1) {
        iter = iter->sons[word[i]];
    }
    return iter->count_below[word[0] - 'a'] - 1;
}

int64_t Solve(const vector<string> &words) {
    auto root = BuildTrie(words);

    int64_t res = 0;
    for (const auto &word : words) {
        res += CountMatches(root, word);
    }
    return res;
}

int main() {
    int n;
    cin >> n;
    cin.get();

    vector<string> words(n);
    for (auto &word : words) {
        getline(cin, word);
    }

    auto res = Solve(words);
    cout << res << "\n";

    return 0;
}

