const int maxn = 2e5 + 10;
const int maxs = 1e6 + 10;
const int p = 1e9 + 7;
const int q = 179;

int last = 0;
map<int, int> hh;
map<int, int> mp;
vector<char> a;
int res[maxs][26];
int cnt[26];
int h[maxn];

int get_id(int hsh) {
    if (hh.find(hsh) != hh.end()) {
        return hh[hsh];
    }
    hh[hsh] = ++last;
    return last;
}

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);

    int n;
    cin >> n;
    a.resize(n);
    for (int i = 0; i < n; i++) {
        string s;
        cin >> s;
        a[i] = s[0];
        memset(cnt, 0, sizeof cnt);
        for (int j = 0; j < sz(s); j++) {
            cnt[s[j] - 'a']++;
        }
        for (int j = sz(s); j >= 0; j--) {
            if (j == sz(s)) {
                int id = get_id(h[i]);
                for (int k = 0; k < 26; k++) {
                    if (cnt[k]) {
                        res[id][k]++;
                    }
                }
            } else {
                cnt[s[j] - 'a']--;
                int tmp = h[i];
                h[i] = (h[i] * q % p + s[j]) % p;
                int id = get_id(h[i]);
                if (j == 0) {
                    mp[h[i]]++;
                    h[i] = tmp;
                }
                for (int k = 0; k < 26; k++) {
                    if (cnt[k]) {
                        res[id][k]++;
                    }
                }
            }
        }
    }
    int ans = 0;
    for (int i = 0; i < n; i++) {
        int id = get_id(h[i]);
        ans += res[id][a[i] - 'a'];
    }
    for (auto &el : mp) {
        ans -= el.y * (el.y + 1) / 2;
    }
    cout << ans << "\n";


    return 0;
}

