const int N = 200006;
const int alpha = 26;
struct node
{
	int cnt[alpha];
	node* nxt[alpha];
	node() {
		for (int i = 0; i < alpha; i++) {
			cnt[i] = 0;
			nxt[i] = NULL;
		}
	}
} *root;

void Insert(string s) {
	int cnt[alpha] = {0};
	for (int i = 0; i < (int)s.size(); i++)
		cnt[s[i] - 'a']++;

	node* cur = root;
	for (int i = 0; i < (int)s.size(); i++) {
		for (int j = 0; j < alpha; j++)
			cur->cnt[j] += bool(cnt[j]);
		int c = s[i] - 'a';
		cnt[c] -= 1;
		if (cur->nxt[c] == NULL)
			cur->nxt[c] = new node();
		cur = cur->nxt[c];
	}
}

int go(string s) {
	node *cur = root;
	for (int i = 0; i + 1 < (int)s.size(); i++) {
		int c = s[i] - 'a';
		cur = cur->nxt[c];
	}
	return cur->cnt[s.back() - 'a'] - 1;
}
