ll md[2] = {231, 3006703054056749LL}, pw[MAX];

ll mult (ll a, ll b, bool fl) {
	return (a * 1LL * b) % md[fl];
}

ll add (ll a, ll b, bool fl) {
	b += md[fl], a += md[fl];
	return (a % md[fl] + b % md[fl]) % md[fl];
}

map<ll, int> m1;

int main () {
