#define tr(c, i) for(auto i = (c).begin(); i != (c).end(); i++)
#define pb push_back
#define sz(a) i64((a).size())
#define all(c) (c).begin(), (c).end()
#define REP(s, e, i) for(i=(s); i < (e); ++i)

struct Trie {

  Trie() : nodes(1, vi(26, -1)), ends(1, 0),
	   chars(1, '$' - 'a'),
	   parents(1, -1),
	   times(1, 0),
	   counts(1, vi(26, 0)){
  }

  void add(const string &S) {
    i64 cur = 0;
    for(auto c: S) {
      i64 &next = nodes[cur][c - 'a'];
      if(next == -1) {
	next = sz(nodes);

	nodes.pb(vi(26, -1));
	ends.pb(0);
	chars.pb(c - 'a');

	parents.pb(cur);
	times.pb(1);

	counts.pb(vi(26, 0));
      }
      else {
	times[next]++;
      }
      cur = next;
    }
    ends[cur] = 1;

    vi flags(26, 0);
    i64 i;
    while(cur != -1) {
      REP(0, 26, i) {
	counts[cur][i] += flags[i];
      }
      if(cur != 0) {
	flags[chars[cur]] = 1;
      }
      cur = parents[cur];
    }
  }

  i64 solve() {
    i64 N = sz(nodes), i;

    /*
    // dump trie
    REP(0, N, i) {      
      cerr << "trie edge " << parents[i] << " -> " << i << " char " << char('a' + chars[i]) << " count " << times[i] << " end " << ends[i]  << endl;
    }
    */

    i64 ans = 0;
    REP(0, N, i) {
      i64 cur = N - i - 1;
      if(cur == 0)
	continue;

      if(ends[cur] == 1) {
	ans += counts[parents[cur]][chars[cur]] - 1;
	//cerr << " delta " << cur << " ->  " << counts[parents[cur]][chars[cur]] - 1 << endl;
      }
    }
    return ans;    
  }

  vvi nodes;
  vi ends;
  vector<char> chars;
  vi parents;
  vi times;
  vvi counts;
};

int main(int argc, char *argv[]) {
  i64 N, i;
  cin >> N;

  Trie trie;
  REP(0, N, i) {
    string S;
    cin >> S;
    reverse(all(S));
    trie.add(S);
  }

  cout << trie.solve() << endl;

  return 0;
}

