#define NMAX 2000005
#define alfa 27

struct Trie {
	int nr[alfa];
	Trie* urm[alfa];
};
typedef Trie* T;

T create_trie()
{
	T nou;
	nou = new Trie;
	memset(nou->urm, 0, sizeof(nou->urm));
	memset(nou->nr, 0, sizeof(nou->nr));
	return nou;
}

void add_word(T p, char* s, int freq[])
{
	if (*s == '\0') {
		return;
	}
	for (int i = 0; i <= 'z' - 'a'; i++) {
		if (freq[i] >= 1) {
			p->nr[i]++;
		}
	}
	if (p->urm[*s - 'a'] == 0) {
		p->urm[*s - 'a'] = create_trie();
	}
	freq[*s - 'a']--;
	add_word(p->urm[*s - 'a'], s + 1, freq);
}


int search(T p, const char* s, char value)
{
	if (*s == '\0') {
		return p->nr[value - 'a'];
	}
	if (p->urm[*s - 'a'])
		return search(p->urm[*s - 'a'], s + 1, value);
	return 0;
}


void str_reverse(char* str) {
	char* str_end = strchr(str, 0);
	std::reverse(str, str_end);
}

