map<int, vector<int> > H;

void input_init(void) {
	cin >> N;
	S.resize(N);
	for (int i = 0; i < N; ++i) {
		cin >> S[i];
		int len = S[i].length();
		(H[len]).push_back(i);
	}
}

bool check(int x, int y) {
	int sz_x = S[x].length();
	if (sz_x == 1) {
		unsigned int loc = S[y].find(S[x][0], 0);
		if (loc != string::npos)
			return true;
		else
			return false;
	}
	int sz_y = S[y].length();
	string end_x = S[x].substr(1);
	string end_y = S[y].substr(sz_y - (sz_x - 1));
	if (end_x != end_y)
		return false;
	int pos = S[y].find(S[x][0], 0);
	if (pos >= 0 && pos < sz_y - (sz_x - 1))
		return true;
	return false;
}

void solve(void) {
	vector<int> v_len;
	map<int, vector<int> >::iterator itr;
	for (itr = H.begin(); itr != H.end(); ++itr)
		v_len.push_back(itr->first);

	for (int i = 0; i < (int)v_len.size() - 1; ++i) {
		vector<int> v = H[v_len[i]];
		for (int j = 0; j < (int)v.size(); ++j) {
			for (int k = i + 1; k < (int)v_len.size(); ++k) {
				vector<int> u = H[v_len[k]];
				for (int l = 0; l < (int)u.size(); ++l) {
					if (check(v[j], u[l]) == true)
						++ans;
				}
			}
		}
	}
}

int main(void) {
	input_init();
	solve();
	cout << ans << '\n';
	return 0;
}

