        vp[i] = {m,s};
    }
    sort(ALL(vp));
    string U="";
    for(int i = 0; i < N; ++i) {
        U += vp[i].second;
    }

    RH rh(U);
    map<unsigned,int> mp;
    vector<ll> d(26,0);

    ll ans=0;
    vector<int> c(26,0);
    int sum=0;
    for(int i = 0; i < N; ++i) {
        string& s = vp[i].second;
        int m = s.size();
        for(int i = 0; i < 26; ++i) {
            c[i]=0;
        }
        for(int i = 0; i < m; ++i) {
            c[s[i]-'a']++;
        }
        {
            for(int j=0;j<26;++j) {
                if(!c[j]) continue;
                ans += d[j];
            }            
        }
        for(int i = m-1; 0 <= i; --i) {
            int l=sum+i,r=sum+m;
            c[s[i]-'a']--;
            for(int j=0;j<26;++j) {
                if(!c[j]) continue;
                auto p=rh.get(l,r);
                if(mp.count(p) && mp[p]==j) ans++;
            }
        }
        if(m==1) {
            d[s[0]-'a']++;
        }
        else{
            mp[rh.get(sum+1,sum+m)]=s[0]-'a';
        }
        sum+=m;
    }
    cout << ans << endl;
    return 0;
}

