using namespace std;

unsigned long long popcount(unsigned long long x) {
  x = ((x & 0xaaaaaaaaaaaaaaaaUL) >> 1) + (x & 0x5555555555555555UL);
  x = ((x & 0xccccccccccccccccUL) >> 2) + (x & 0x3333333333333333UL);
  x = ((x & 0xf0f0f0f0f0f0f0f0UL) >> 4) + (x & 0x0f0f0f0f0f0f0f0fUL);
  x = ((x & 0xff00ff00ff00ff00UL) >> 8) + (x & 0x00ff00ff00ff00ffUL);
  x = ((x & 0xffff0000ffff0000UL) >> 16) + (x & 0x0000ffff0000ffffUL);
  x = ((x & 0xffffffff00000000UL) >> 32) + (x & 0x00000000ffffffffUL);
  return x;
}

struct node {
  int ok;
  array<int, 26> to;
  node() {
    ok = 0;
    for (int i = 0; i < 26; ++i) to[i] = -1;
  }
};

int n;
vector<string> s;
vector<node> trie;

long long solve();

int main() {
  cin >> n;
  s.resize(n);
  for (auto &p : s) {
    cin >> p;
    reverse(p.begin(), p.end());
  }
  sort(s.begin(), s.end(),
       [](string &l, string &r) { return l.size() < r.size(); });
  cout << solve() << endl;
  return 0;
}

long long solve() {
  long long res = 0;
  node uni;
  trie.push_back(uni);
  for (int i = 0; i < n; ++i) {
    int len = s[i].size(), id = 0;
    vector<int> memo(len + 1, 0);
    for (int j = len - 1; j >= 0; --j)
      memo[j] = memo[j + 1] | (1LL << (s[i][j] - 'a'));
    for (int j = 0; j < len; ++j) {
      int c = s[i][j] - 'a';
      res += popcount(memo[j] & trie[id].ok);
      if (trie[id].to[c] < 0) {
        trie[id].to[c] = trie.size();
        trie.push_back(uni);
      }
      if (j == len - 1) trie[id].ok |= 1 << c;
      id = trie[id].to[c];
    }
  }
  return res;
}

