	int mx = 0;
	for (int i = 1; i <= n; ++i)
	{
		int x = id[i];
		while (mx > len[x] - 1)
			--mx;
		for (int c = 0; c < 26; ++c)
			cur[c] = 0;
		ull val = 0;
		for (int j = len[x] - 1; j >= 1; --j)
			val = val * Base + s[x][j] - 'a' + 1, ++cur[s[x][j] - 'a'];
		++cur[s[x][0] - 'a'];
		if (len[x] - 1 <= mx && len[x] <= 500005)
