class InputReader {
public:
    InputReader() {
        input_file = stdin;
        cursor = 0;
        fread(buffer, SIZE, 1, input_file);
    }
    InputReader(const char *file_name) {
        input_file = fopen(file_name, "r");
        cursor = 0;
        fread(buffer, SIZE, 1, input_file);
    }
    inline InputReader &operator >>(int &n) {
        while((buffer[cursor] < '0' || buffer[cursor] > '9') && buffer[cursor] != '-') {
            advance();
        }
        int sign = 1;
        if (buffer[cursor] == '-') {
            sign = -1;
            advance();
        }
        n = 0;
        while('0' <= buffer[cursor] && buffer[cursor] <= '9') {
            n = n * 10 + buffer[cursor] - '0';
            advance();
        }
        n *= sign;
        return *this;
    }
private:
    FILE *input_file;
    static const int SIZE = 1 << 17;
    int cursor;
    char buffer[SIZE];
    inline void advance() {
        ++ cursor;
        if(cursor == SIZE) {
            cursor = 0;
            fread(buffer, SIZE, 1, input_file);
        }
    }
};

const int MAXN = 200000;
const int SIGMA = 26;

struct Node {
    Node *son[SIGMA];
    int contains[SIGMA];
    Node *parent;

    Node(Node *_parent = nullptr) {
        for (int i = 0; i < SIGMA; i++) {
            son[i] = nullptr;
            contains[i] = 0;
        }
        parent = _parent;
    }
};

string s[1 + MAXN];
Node *where[1 + MAXN];

int main() {
    timeBegin();
    //ifstream cin("input.txt");
    //ofstream cout("papagali.out");
    int n;
    cin >> n;
    Node *root = new Node;
    for (int i = 1; i <= n; i++) {
        cin >> s[i];
        reverse(s[i].begin(), s[i].end());
        Node *node = root;
        for (auto ch : s[i]) {
            if (node->son[ch - 'a'] == nullptr) {
                node->son[ch - 'a'] = new Node(node);
            }
            node = node->son[ch - 'a'];
        }
        where[i] = node;
        vector<bool> seen(SIGMA, false);
        for (int j = s[i].size() - 1; j >= 0; j--) {
            seen[s[i][j] - 'a'] = true;
            node = node->parent;
            for (int k = 0; k < SIGMA; k++) {
                if (seen[k]) {
                    node->contains[k]++;
                }
            }
        }
    }
    long long answer = 0;
    for (int i = 1; i <= n; i++) {
        answer += where[i]->parent->contains[s[i].back() - 'a'] - 1;
    }
    cout << answer << "\n";
    //timeDuration();
    return 0;
}

