int root;
int newNode(){
	++Node;
	go[Node].assign(26, -1);
	child[Node].assign(26, 0);
	return Node;
}

int cnt_string(vector<int>& x){
	int len = x.size();
	int cur = root;
	for(int i = len - 1; i > 0; --i){
		if (go[cur][x[i]] == -1){
			return 0;
		}
		cur = go[cur][x[i]];
	}
	return child[cur][x[0]];
}

void add_string(vector<int>& x){
	int len = x.size();
	int cur = root;
	vector<int> exchr(26,0);


	for(auto e: x){
		exchr[e]++;
	}
	for(int i = len - 1; i >= 0; --i){
		for(int j = 0; j < 26; ++j){
			if (exchr[j] > 0){
				child[cur][j]++;
			}
		}
		--exchr[x[i]];
		if (go[cur][x[i]] == -1){
			go[cur][x[i]]= newNode();
		}
		cur = go[cur][x[i]];
	}
}


