const ull B = 1e9 + 7;

map<pair<ull, int>, int> l_hashs;

ll get_cnt(string s) {
    map<char, int> chars;
    REP(i, s.size()) chars[s[i]]++;

    ll ret = 0;
    ull h = 0;
    REP(i, s.size() - 1) {
        for (auto p : chars) {
            if (p.second == 0) continue;

            if (l_hashs.count({h * B + p.first, i + 1}) > 0) {
                ret += p.second;
            }
        }
        h = h * B + s[s.size() - 1 - i];
        chars[s[s.size() - 1 - i]]--;
    }
    return ret;
