class BFirstSecond {
public:
    void solve() {
        int n = in.readInt();
        auto s = in.readStringArray(n);

        int maxLen = 0;
        for (const auto& t : s) {
            maxim(maxLen, int(t.size()));
        }
        arr<bool> has(maxLen, false);
        for (const auto& t : s) {
            has[t.size() - 1] = true;
        }
        arr<unordered_map<ll, int>> pat(26, unordered_map<ll, int>());
        vector<ll> hash1;
        for (const auto& t : s) {
            unsigned prefix = setBit(0u, t[0] - 'a');
            StringHash hash(t);
            hash1.push_back(hash.hash(1));
            for (int i : range(2, t.size() + 1)) {
                prefix = setBit(prefix, t[i - 1] - 'a');
                if (!has[t.size() - i]) {
                    continue;
                }
                ll cHash = hash.hash(i);
                for (int j : range(26)) {
                    if (isSet(prefix, j)) {
                        pat[j][cHash]++;
                    }
                }
            }
        }
        ll answer = 0;
        int i = 0;
        for (const auto& t : s) {
            answer += pat[t[0] - 'a'][hash1[i++]];
        }
        out.printLine(answer);
    }
};


