const int MAXN = 200000;
const int MAXSUMLEN = 1000000;
const int MAXNODE = MAXSUMLEN + 1;
struct Node { int nxt[26], subtreecntwith[26], subtreecnt; int cnt; };

int n;
char s[MAXSUMLEN + 1];
int offset[MAXN + 1], len[MAXN];

Node node[MAXNODE]; int nnode, root;

int makenode() { int ret = nnode++; REP(i, 26) node[ret].nxt[i] = -1, node[ret].subtreecntwith[i] = 0; node[ret].cnt = node[ret].subtreecnt = 0; return ret; }

ll dfs(int at) {
	ll ret = 0;
	node[at].subtreecnt = node[at].cnt;
	REP(x, 26) {
		int to = node[at].nxt[x]; if (to == -1) continue;
		ret += dfs(to);
		node[at].subtreecnt += node[to].subtreecnt;
		REP(y, 26) node[at].subtreecntwith[y] += y == x ? node[to].subtreecnt : node[to].subtreecntwith[y];
	}
	if (node[at].cnt > 0) {
		ret += (ll)node[at].cnt * (node[at].subtreecnt - node[at].cnt);
	}
	REP(x, 26) {
		int to = node[at].nxt[x]; if (to == -1) continue;
		if (node[to].cnt == 0) continue;
		ret += (ll)node[to].cnt * (node[at].subtreecntwith[x] - node[to].subtreecnt);
	}
	return ret;
}

ll solve() {
	nnode = 0;
	root = makenode();
	REP(i, n) {
		int at = root;
		for (int j = len[i] - 1; j >= 0; --j) {
			char c = s[offset[i] + j];
			int x = c - 'a';
			if (node[at].nxt[x] == -1) { int to = makenode(); node[at].nxt[x] = to; }
			at = node[at].nxt[x];
		}
		++node[at].cnt;
	}
	return dfs(root);
}

void run() {
	scanf("%d", &n);
	offset[0] = 0;
	REP(i, n) {
		scanf("%s", s + offset[i]);
		len[i] = strlen(s + offset[i]);
		offset[i + 1] = offset[i] + len[i];
	}
	printf("%lld\n", solve());
}

int main() {
	run();
	return 0;
}

