bool canTransform(const string& from, const string& to) {
    //toの後ろto.size() - 1文字は絶対に合っていないといけない
    //toの先頭文字に関しては含まれていればいい

    //例
    //from = abcxyx
    //to   = cyx

    if (from.size() < to.size()) {
        return false;
    }
    //まずtoの先頭1文字がfromの先頭からfrom.size() - to.size() + 1文字目までのどこかに含まれていることが必要
    uint64_t index = from.find(to[0]);
    if (index == string::npos || index >= from.size() - to.size() + 1) {
        return false;
    }

    return to.substr(1) == from.substr(from.size() - to.size() + 1);
}

bool match(const string& a, const string& b) {
    return canTransform(a, b) || canTransform(b, a);
}

