    cin >> s[i];
  }
  sort(s.begin(), s.end(),
       [](const string &x, const string &y) { return x.size() > y.size(); });
  vector<map<P, ll>> c_sufs(26);
  vector<ll> c_cnt(26);
  ll ans = 0;
  for (int i = 0; i < n; i++) {
    //cerr << s[i] << endl;
    if (s[i].size() == 1) {
      int idx = s[i][0] - 'a';
      ans += c_cnt[idx];
      c_cnt[idx]++;
      continue;
    }
    vector<int> ok(26);
    for (auto c : s[i]) {
      int idx = c - 'a';
      ok[idx] = 1;
    }
    for (int j = 0; j < 26; j++)
      if (ok[j]) c_cnt[j]++;
    RollingHash rh(s[i]);
    int sz = s[i].size();

    // [][----]
    auto p = rh.query(1, sz);
    int index = s[i][0] - 'a';
    if (c_sufs[index].count(p)) ans += c_sufs[index][p];

    vector<int> cnt(26);
    for (int j = 0; j < sz; j++) {
      int idx = s[i][j] - 'a';
      auto val = rh.query(j, sz);
      //cerr << j << " " << val.first << " " << val.second << endl;
      for (int k = 0; k < 26; k++) {
        if (cnt[k]) c_sufs[k][val]++;
      }
