struct trie{
    mat G;
    vec num, dflt;
    trie() : G(1, vec(26, -1)), num(1, 0), dflt(26, -1){}
    void append(string &s){
        int now = 0;
        ++num[now];
        for(char c : s){
            int id = c - 'a';
            if(G[now][id] == -1){
                G[now][id] = G.size();
                now = G.size();
                G.push_back(dflt);
                num.push_back(1);
            }else{
                now = G[now][id];
                ++num[now];
            }
        }
    }
    int ans(string &s){
        int now = 0;
        for(char c : s){ now = G[now][c - 'a'];}
        return num[now];
    }
};

int main(){
    cin>>N;
    vector<string> s(N);
    vector<trie> data(26, trie());
    rep(i,N) {
        cin>>s[i];
        reverse(ALL(s[i]));
        S = s[i];
        vector<bool> exist(26, false);
        Rrep(j, s[i].size()){
            int id = s[i][j] - 'a';
            S.pop_back();
            if(!exist[id]){
                exist[id] = true;
                data[id].append(S);
            }
        }
    }
    ll res = 0;
    rep(i,N){
        int id = *s[i].rbegin() - 'a';
        s[i].pop_back();
        res += data[id].ans(s[i]) - 1;
    }
    cout<<res<<endl;
}

