struct node {
    int cnt[26];
    node* to[26];

    node () {
        for (int i = 0; i < 26; ++i)
            cnt[i] = 0, to[i] = nullptr;
    }
};

ll ans = 0;
vector<int> cur(26);
void add(node*& root, string& x, int pos = 0) {
    if (!root)
        root = new node();

    if (pos < x.size()) {
        for (int i = 0; i < 26; ++i)
            cur[i] += root->cnt[i];

        ans += cur[x[pos]];
        cur[x[pos]] = 0;

        if (pos == x.size() - 1)
            ++root->cnt[x[pos]];
        add(root->to[x[pos]], x, pos + 1);
    }
}

void solve() {
    int n;
