    node* root = nullptr;
    vector<string> s(n);
    for (int i = 0; i < n; ++i) {
        cin >> s[i];

        reverse(s[i].begin(), s[i].end());
        for (char& c : s[i]) c -= 'a';
    }
    sort(s.begin(), s.end(), [](const string& a, const string& b) {
        return a.size() < b.size();
    });

    for (int i = 0; i < n; ++i) {
        cur.assign(26, 0);
        add(root, s[i]);
    }

    cout << ans << '\n';
}

