struct AlphaNode {
	int next[26];
	int count[26];
};

int num_nodes;
int root;
AlphaNode nodes[kMaxNumNodes];

int calc(const string& s) {
	int current = root;
	for (int i = 0; i < s.length() - 1; ++i) {
		int c = s[i] - 'a';
		current = nodes[current].next[c];
		if (current == 0) {
			return 0;
		}
	}
	return nodes[current].count[s.back() - 'a'];
}

void add(const string& s) {
	vector<int> num_chars(26);
	for (char c : s) {
		++num_chars[c - 'a'];
	}
	int current = root;
	for (int i = 0; i < s.length(); ++i) {
		for (int j = 0; j < 26; ++j) {
			if (num_chars[j] > 0) {
				++nodes[current].count[j];
			}
		}
		int c = s[i] - 'a';
		--num_chars[c];
		if (nodes[current].next[c] == 0) {
			nodes[current].next[c] = (++num_nodes);
		}
		current = nodes[current].next[c];
	}
}

