struct node {
  array<int, 26> to, memo;
  node() {
    for (int i = 0; i < 26; ++i) to[i] = -1, memo[i] = 0;
  }
};

int n;
vector<string> s;
vector<node> trie;

long long solve();

int main() {
  cin >> n;
  s.resize(n);
  for (auto &p : s) {
    cin >> p;
    reverse(p.begin(), p.end());
  }
  sort(s.begin(), s.end(),
       [](string &l, string &r) { return l.size() < r.size(); });
  cout << solve() << endl;
  return 0;
}

long long solve() {
  long long res = 0;
  node uni;
  trie.push_back(uni);
  for (int i = 0; i < n; ++i) {
    int len = s[i].size(), id = 0;
    vector<int> memo(len + 1, 0);
    for (int j = len - 1; j >= 0; --j)
      memo[j] = memo[j + 1] | (1LL << (s[i][j] - 'a'));
    for (int j = 0; j < len; ++j) {
      int c = s[i][j] - 'a';
      for (int k = 0; k < 26; ++k)
        if (memo[j] >> k & 1) res += trie[id].memo[k];
      if (trie[id].to[c] < 0) {
        trie[id].to[c] = trie.size();
        trie.push_back(uni);
      }
      if (j == len - 1) ++trie[id].memo[c];
      id = trie[id].to[c];
    }
  }
  return res;
}

