signed main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(20);

    int n;
    cin>>n;
    vector<pair<int,string>> a(n);
    for(int i=0;i<n;i++){
        cin>>a[i].second;
        a[i].first = a[i].second.size();
    }
    sort(a.begin(),a.end());

    const ll mod1 = 1000000103, mod2 = 1000000483;
    ll mul1=10009;
    ll mul2=10007;

    map<ll,ll> mp1[26],mp2[26];
    ll ans = 0;
    ll one[26]={};
    for(int i=0;i<n;i++){
        string s = a[i].second;
        if(s.size() == 1){
            one[s[0]-'a']++;
            continue;
        }
        ll h1=0;
        ll h2=0;
        int m = s.size(), c=26;
        int cnt[c][m+1]={};
        for(int j=0;j<m;j++){
            cnt[s[j]-'a'][j+1]++;
            for(int k=0;k<26;k++) cnt[k][j+1] += cnt[k][j];
        }
        // one
        for(int j=0;j<26;j++){
            if(cnt[j][m] == 0)continue;
            ans += one[j];
        }
        for(int j=m-1;j>=1;j--){
            h1 = (h1*mul1 + s[j]) % mod1;
            h2 = (h2*mul2 + s[j]) % mod2;
            for(int k=0;k<26;k++){
                if(cnt[k][j] && mp1[k].count((int)h1) && mp2[k].count((int)h2)){
                    ans += mp1[k][h1];
                }
            }
        }
        mp1[(int)(s[m-1]-'a')][h1]++;
        mp2[(int)(s[m-1]-'a')][h2]++;
    }
    cout << ans << endl;

}

#include <bits/stdc++.h>
using namespace std;
const long long BASE = 987654321;
const long long MOD = 999999937;
vector<long long> power, inv;
long long modpow(long long a, long long b){
  long long ans = 1;
  while (b > 0){
    if (b % 2 == 1){
      ans *= a;
      ans %= MOD;
    }
    a *= a;
    a %= MOD;
    b /= 2;
  }
  return ans;
}
long long modinv(long long a){
  return modpow(a, MOD - 2);
}
void precalc(int n){
  power = vector<long long>(n);
  power[0] = 1;
  for (int i = 1; i < n; i++){
    power[i] = power[i - 1] * BASE % MOD;
  }
  inv = vector<long long>(n);
  inv[0] = 1;
  inv[1] = modinv(BASE);
  for (int i = 2; i < n; i++){
    inv[i] = inv[i - 1] * inv[1] % MOD;
  }
}
struct rolling_hash{
  int N;
  vector<long long> S;
  rolling_hash(){
  }
  rolling_hash(string s){
    N = s.size();
    S = vector<long long>(N + 1, 0);
    for (int i = 0; i < N; i++){
      S[i + 1] = (S[i] + s[i] * power[i]) % MOD;
    }
  }
  int size(){
    return N;
  }
  long long hash(int L, int R){
    return (S[R] - S[L] + MOD) * inv[L] % MOD;
  }
  long long all(){
    return S[N];
  }
};
pair<long long, int> merge(pair<long long, int> A, pair<long long, int> B){
  long long ans1 = (A.first + B.first * power[A.second]) % MOD;
  int ans2 = A.second + B.second;
  return make_pair(ans1, ans2);
}
int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  precalc(1000001);
  int N;
  cin >> N;
  vector<string> S(N);
  for (int i = 0; i < N; i++){
    cin >> S[i];
  }
  vector<rolling_hash> RH(N);
  for (int i = 0; i < N; i++){
    RH[i] = rolling_hash(S[i]);
  }
  vector<map<long long, int>> mp(1000001);
  for (int i = 0; i < N; i++){
    mp[S[i].size()][RH[i].all()]++;
  }
  long long ans = 0;
  for (int i = 0; i < N; i++){
    int sz = S[i].size();
    if (sz == 1){
      continue;
    }
    vector<bool> alphabet(26, false);
    for (int j = 0; j <= sz; j++){
      if (j > 1) {
        for (int k = 0; k < 26; k++){
          if (alphabet[k]){
            pair<long long, int> A = make_pair((int)('a' + k), 1);
            pair<long long, int> B = make_pair(RH[i].hash(j, sz), sz - j);
            pair<long long, int> C = merge(A, B);
            if (mp[sz - j + 1].count(C.first)){
              ans += mp[sz - j + 1][C.first];
            }
          }
        }
      }
      if (j < sz) {
      	alphabet[S[i][j] - 'a'] = true;
      }
    }
  }
  cout << ans << endl;
}

