void solve(string & s)
{
    int sz=s.size();
    for(int i=0; i<26; i++)
        first[i]=1e7;
    for(int i=0; i<sz; i++)
        first[s[i]-'a']=min(first[s[i]-'a'],i);
    ll h1=0, h2=0;
    for(int i=sz-1; i>=0; i--)
    {
        for(int j=0; j<26; j++)
