            {
                ll h11=(h1*p1 + j+1)%m1, h22=(h2*p2 + j+1)%m2;
                cnt[ {h11, h22}]++;
                ans+=cnt2[ {h11,h22}];
            }
        h1=(h1*p1 + s[i]-'a'+1)%m1;
        h2=(h2*p2 + s[i]-'a'+1)%m2;

    }
}

