int multiply(int a, int b, int in_mod) { return (a * b) % in_mod; }
int mult_identity(int a) { return 1; }


auto power(auto a, int b, int in_mod)
{
    auto prod = mult_identity(a);
    auto mult = a % in_mod;
    while (b != 0)
    {
        if (b % 2)
        {
            prod = multiply(prod, mult, in_mod);
        }
        mult = multiply(mult, mult, in_mod);
        b /= 2;
    }
    return prod;
}
int mod_inv(int q, int in_mod)
{

    return power(q, in_mod - 2, in_mod);
}

const int K = 26;

struct Vertex {
    int next[K];
    bool leaf = false;
    int leafs_cnt = 0;
    int cnt[K];

    Vertex() {
        fill(begin(next), end(next), -1);
        fill(begin(cnt), end(cnt), 0);
    }
};
#define trie sad_trie

vector<Vertex> trie(1);
void add_string(string const& s) {
    int v = 0;
    for (char ch : s) {
        int c = ch - 'a';
        if (trie[v].next[c] == -1) {
            trie[v].next[c] = trie.size();
            trie.emplace_back();
        }
        trie[v].leafs_cnt++;
        v = trie[v].next[c];
    }


    trie[v].leaf = true;
    trie[v].leafs_cnt++;
}

void simplify(int v, int way)
{

    for(int i= 0;i<K;i++)
    {
        if(trie[v].next[i] != -1)
        {
            simplify(trie[v].next[i], i);
        }


    }



    for(int i= 0;i<K;i++)
    {
        if(trie[v].next[i] != -1)
        {
            for(int j = 0;j<K;j++)
            {
                trie[v].cnt[j] += trie[trie[v].next[i]].cnt[j];
            }
        }
    }
    if(way != -1)
        trie[v].cnt[way] = trie[v].leafs_cnt ;

}

void solve()
{
    int n;
    cin>>n;
    vector<string> s(n);
    for(int i= 0;i<n;i++)
    {
        cin>>s[i];
        reverse(all(s[i]));
        add_string(s[i]);
    }
    simplify(0, -1);
    int ways = 0;
    for(auto i:s)
    {
        int v = 0;
        int n = i.size() -1;
        for(int j= 0;j<n;j++)
            v = trie[v].next[i[j]-'a'];
        for(int j = 0;j<K;j++)
        {

            if(trie[v].next[j]!=-1)
            {
                ways += trie[trie[v].next[j]].cnt[i[n]-'a'];
            }
        }
        ways--;
    }
    assert(ways>=0);
    assert(ways<=(n*(n-1))/2);
    cout<<ways<<endl;

}


