struct Node{
    vector<bool> mm;
    char c;
    vector<Node> child;
    Node(char _c):c(_c){
        mm = vector<bool>(26, false);
    }
    void gen(string &s, int now, char &x) {
        if(now == s.size()) mm[x-'a'] = 1;
        else {
            rip(i, child.size(), 0) {
                if(child[i].c == s[now]) {
                    child[i].gen(s, now+1, x);
                    return;
                }
            }
            child.push_back(Node(s[now]));
            child.back().gen(s, now+1, x);
        }
    }
    ll dfs(vector<ll> cnt) {
        ll ret = 0;
        if(c != '$') ret += cnt[c-'a'];
        rip(i, 26, 0) if(mm[i]) ret += cnt[i];
        rip(i,26,0) cnt[i] += mm[i];
        // cout << c << " ";vdeb(cnt);
        rip(i, child.size(),0) ret += child[i].dfs(cnt);
        return ret;
    }
    void deb(int depth) const{
        // rip(i,depth,0) printf("  ");
        // cout << c MM mm << endl;
        rip(i, child.size(), 0) child[i].deb(depth+1);
    }
};

