//-------------------------------------

// RollingHash(s, base) := 文字列sのハッシュテーブルを計算する
// get(l, r) := [l, r)のハッシュ値を求める
// connect(h1, h2, h2len) := ハッシュ値h1と, 長さh2lenのハッシュ値h2を結合する。
// LCP(b, l1, r1, l2, r2) := 区間[l1, r1)と、ハッシュテーブルがbである区間[l1,
// r2)の文字列の 最長共通接頭辞の長さを求める。
template <unsigned mod> struct RollingHash {
    vector<unsigned> hashed, power;

    inline unsigned mul(unsigned a, unsigned b) const {
        unsigned long long x = (unsigned long long)a * b;
        unsigned xh = (unsigned)(x >> 32), xl = (unsigned)x, d, m;
        asm("divl %4; \n\t" : "=a"(d), "=d"(m) : "d"(xh), "a"(xl), "r"(mod));
        return m;
    }

    RollingHash(const string &s, unsigned base = 10007) {
        int sz = (int)s.size();
        hashed.assign(sz + 1, 0);
        power.assign(sz + 1, 0);
        power[0] = 1;
        for(int i = 0; i < sz; i++) {
            power[i + 1] = mul(power[i], base);
            hashed[i + 1] = mul(hashed[i], base) + s[i];
            if(hashed[i + 1] >= mod)
                hashed[i + 1] -= mod;
        }
    }

    unsigned get(int l, int r) const {
        unsigned ret = hashed[r] + mod - mul(hashed[l], power[r - l]);
        if(ret >= mod)
            ret -= mod;
        return ret;
    }

    unsigned connect(unsigned h1, int h2, int h2len) const {
        unsigned ret = mul(h1, power[h2len]) + h2;
        if(ret >= mod)
            ret -= mod;
        return ret;
    }

    int LCP(const RollingHash<mod> &b, int l1, int r1, int l2, int r2) {
        int len = min(r1 - l1, r2 - l2);
        int low = -1, high = len + 1;
        while(high - low > 1) {
            int mid = (low + high) / 2;
            if(get(l1, l1 + mid) == b.get(l2, l2 + mid))
                low = mid;
            else
                high = mid;
        }
        return (low);
    }
};

using RH = RollingHash<1000000007>;

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    vector<string> s(N);
    for(int i = 0; i < N; i++) {
        cin >> s[i];
    }
    sort(ALL(s), [](const string &a, const string &b) {
        return (a.size() > b.size());
    });
    ll ans = 0;
    map<pair<unsigned, int>, ll> cnt;
    for(int i = 0; i < N; i++) {
        vector<int> exist;
        int num = 0;
        exist.emplace_back(0);
        for(int j = 0; j < s[i].size(); j++) {
            num |= (1 << (s[i][j] - 'a'));
            exist.emplace_back(num);
        }
        reverse(ALL(exist));
        reverse(ALL(s[i]));
        RH rh(s[i]);
        ans +=
            cnt[make_pair(rh.get(0, (int)s[i].size() - 1), s[i].back() - 'a')];
        for(int k = 0; k < 26; k++) {
            if(exist[0] & (1 << k)) {
                cnt[make_pair(0, k)]++;
            }
        }
        for(int j = 0; j < s[i].size(); j++) {
            for(int k = 0; k < 26; k++) {
                if(exist[j + 1] & (1 << k)) {
                    cnt[make_pair(rh.get(0, j + 1), k)]++;
                }
            }
        }
    }
    cout << ans << endl;
}

