void add(int x){
    int n=s[x].length();
    int now=1;
    for(int i=0;i<n;i++){
        for(int j=0;j<26;j++){
            if(s[x][i]-'a'==j)sum[i][j]=sum[i-1][j]+1;
            else sum[i][j]=sum[i-1][j];
        }
    }
    for(int i=n-1;~i;i--){
        for(int j=0;j<26;j++){
            if(sum[i][j]){
                if(!nex[now][j])
                    nex[now][j]=++cnt;
                num[nex[now][j]]++;
            }
        }
        now=nex[now][s[x][i]-'a'];
    }
}
