//=============rolling_hash============================
ll rolling_hash(string a) {
  if (!init) {
    init = true;
    random_device rnd;
    mt19937 mt(rnd());
    uniform_int_distribution<> rand9(0, 8);
    ll temp = rand9(mt);
    M = MB.at(temp).first;
    B = MB.at(temp).second;
  }
  ll al = a.size();
  ll ah = 0;
  for (ll i = 0; i < al; ++i) {
    ah = (ah * B % M + a.at(i)) % M;
  }
  return ah;
}
