struct trie{
    char c;
    map<char, trie*> next_chars;
    map<char, ll> end_chars;
};

void add_word(string s, int idx, trie* t){
    char c = s.at(idx);
    if (idx == s.size() - 1){
        t->end_chars[c]++;
        return;
    }
    if((t->next_chars.find(c) == t->next_chars.end())){
        trie hoge = {c, {}, {}};
        t->next_chars[c] = &hoge;
    }
    add_word(s, idx+1, t->next_chars.at(c));
}

map <char, ll> calc(trie &t, ll & ans){
    auto nm = t.next_chars;
    auto em = t.end_chars;
    auto c = t.c;
    map<char, ll> ret;
    for(auto p: nm){
        auto nt = p.second;
        for(auto p2: calc(*(nt), ans)){
            ret[p2.first] += p2.second;
        }
    }
    for(auto p: em){
        ans += p.second * ret[p.first];
        ret[p.first] += p.second;
    }
    ll max_cnt = 0;
    for(auto p: ret){
        ll cnt = p.second;
        max_cnt = max(cnt, max_cnt);
    }
    ret[c] = max_cnt;
    return ret;
}



