        ll len=s.length();
        int cnt[28]={0};
        for(int i=0;i<len;i++)
        {
            cnt[s[i]-'a']++;
        }
        ll suff1=0,suff2=0;
        for(int req=1;req<len;req++)
        {
            if(req==1)
            {
                for(char ch='a';ch<='z';ch++)
                {
                    if(cnt[ch-'a']>0)
                    {
                        ll now=ch;
                        ans+=mark[mp(now,now)];
                    }
                }
                continue;
            }
            cnt[s[len-req+1]-'a']--;
            suff1*=p1;
            suff1+=(s[len-req+1]*p1);
            suff1%=m1;
            suff2*=p2;
            suff2+=(s[len-req+1]*p2);
            suff2%=m2;
            if(good[req]==0)
                continue;
            for(char ch='a';ch<='z';ch++)
            {
                if(cnt[ch-'a']>0)
                {
                    ll now1=(suff1+ch)%m1;
                    ll now2=(suff2+ch)%m2;
                    ans+=mark[mp(now1,now2)];
                }
            }
        }
    }
    cout<<ans<<'\n';
}
