int newnode(){
    return ++ sz;
}

void insert(int p, char *s){
    while (*s != '\0'){
        int ch = *s - 'a';
        if (!go[p][ch]){
            go[p][ch] = newnode();
        }
        p = go[p][ch];
        ++ s;
    }
    end[p] = true;
}

void dfs(int u){
    tot[u] = end[u];
    for (int i = 0; i < SIGMA; ++ i){
        int v = go[u][i];
        if (v){
            dfs(v);
            for (int j = 0; j < SIGMA; ++ j){
                if (j == i){
                    vis[u][j] += tot[v];
                }
                else{
                    vis[u][j] += vis[v][j];
                }
            }
            tot[u] += tot[v];
        }
    }
}

ll ans;

void solve(int u){
    if (!u){
        return;
    }
    for (int i = 0; i < SIGMA; ++ i){
        int v = go[u][i];
        if (end[v]){
            ans += vis[u][i] - 1;
        }
        solve(v);
    }
}

