            ha[i][j].hash2_=(ha[i][j-1].hash2_*base2+str[i][j]+11)%mod2;
        }
        Hash hash;
        if(str[i].size()==2)
            hash=0;
        else 
            hash=GetHash(i,2,str[i].size()-1);
        if(mp.find(hash)==mp.end())
            mp[hash]=vector<int>(26,0);
        ++mp[hash][str[i][1]];
