struct node_t {
    map<char, node_t*> go;
    bool is_term = false;
};

array<int, 27> traverse(node_t* v, string& s, int64_t& ans) {
    array<int, 27> cur;
    std::fill(ALL(cur), 0);

    vector<char> let;
    vector<node_t*> go;
    vector<array<int, 27>> data;

    for (auto& el: v->go) {
        let.push_back(el.first - 'a');
        go.push_back(el.second);

        s += el.first;
        array<int, 27> res = traverse(el.second, s, ans);
        s.pop_back();
        data.push_back(res);

        for (int i = 0; i <= 26; ++i)
            cur[i] += res[i];
    }

    for (int i = 0; i < SZ(go); ++i) {
        if (go[i]->is_term)
            ans += cur[let[i]] - data[i][let[i]];
    }

    if (v->is_term) {
        ans += cur[26];
        cur[26] += 1;

        int letset = 0;
        for (char ch: s)
            letset |= (1 << (ch - 'a'));

        for (int i = 0; i < 26; ++i)
            if (letset & (1 << i))
                cur[i] += 1;
    }

    return cur;
}

