void add(string s) {
//    cout << "s: " << s << endl;
    int cur = 1;
    vector<int> nodes;
    for(int i = 0; i < s.size(); i++) {
        int c = s[i] - 'a';
        nodes.push_back(cur);
        if(!to[cur][c]) to[cur][c] = ++tot;
        cur = to[cur][c];
    }
    int add = pre[nodes.back()][s.back()-'a'];
    ans += add;
//    cout << "add: " << add << endl;
    vector<bool> F(26);
    for(int i = (int)s.size()-1, j = (int)nodes.size()-1; j >= 0; i--, j--) {
        int c = s[i]-'a';
        F[c] = true;
        for(int k = 0; k < 26; k++) {
            if(F[k]) pre[nodes[j]][k]++;
        }
    }
}

