	for(int i = 1; i < MX; i++) {
		pwr[i] = (P * pwr[i - 1]) % MOD;
	}
	for(ll i = 0; i < n; i++) {
		string s; cin >> s;
		v.push_back(s);
		ll hash = 0;
		for(ll j = s.size() - 1; j >= 0; j--) {
