		f[hash]++;
	}
	ll ans = 0;
	for(ll i = 0; i < n; i++) {
		vector<ll> freq(26);
		for(auto c: v[i]) {
			freq[c - 'a']++;
		}
		ll hash = 0;
		for(ll j = v[i].size() - 1; j >= 1; j--) {
			for(ll k = 0; k < 26; k++) {
				if(freq[k]) {
					ans += f[(hash + (pwr[v[i].size() - 1 - j]) * (k + 1)) % MOD];
				}
			}
			hash = (hash + pwr[v[i].size() - 1 - j] * (v[i][j] - 'a' + 1));
			freq[v[i][j] - 'a']--;
		}
	}
	cout << ans << endl;
