  for (int i = 0; i < n; i++) {
    cin >> a[i];
    reverse(a[i].begin(), a[i].end());
  }

  auto f = [](int v, int c) {
    int res = (1LL * 7630369 * v + c) % 998244353;
    return res;
  };
  auto rh = [&](string &s) {
    int n = s.length();
    vector<int> res(n + 1);
    for (int i = 0; i < n; i++) {
      res[i + 1] = f(res[i], s[i]);
    }
    return res;
  };

  const int N = 1e6 + 5;
  vector<vector<int>> mp(N);

  auto hash = [&](string &s) {
    int L = s.length();
    vector<int> h = rh(s);
    vector<int> last(26, -1);

    for (int i = 0; i < L; i++) {
      last[s[i] - 'a'] = i;
    }  

    for (int i = 0; i <= L; i++) {
      int pref = h[i];
      for (int j = 0; j < 26; j++) {
        if (last[j] < i) continue;
        int all = f(pref, j + 'a');
        mp[i].push_back(all);
      }
    }
  };
  for (auto s : a) {
    hash(s);
  }
  for (auto &i : mp) {
    sort(i.begin(), i.end());
  }

  long long ans = 0;
  for (auto s : a) {
    int L = s.length();
    int cur = rh(s)[L];
    auto l = lower_bound(mp[L - 1].begin(), mp[L - 1].end(), cur);
    auto r = lower_bound(mp[L - 1].begin(), mp[L - 1].end(), cur + 1);
    ans += (r - l);
  }
  cout << ans - n << '\n';

  return 0;
}

