// ei1333's BIT
struct BIT {
  VI data;

  BIT(ll sz) {
    data.assign(++sz, 0);
  }

  ll sum(ll k) {
    ll ret = 0;
    for(++k; k > 0; k -= k & -k) ret += data[k];
    return (ret);
  }

  // [i, j]
  ll range_sum(ll i, ll j){
    if(i==0){
      return sum(j);
    }else{
      return sum(j) - sum(i-1);    
    }
  }

  void add(ll k, ll x) {
    for(++k; k < data.size(); k += k & -k) data[k] += x;
  }
};

struct Hoge{
  vector<BIT> bits;

  Hoge(string& s){
    ll N = s.size();
    rep(i,26){
      auto bi = BIT(N);
      bits.push_back(bi);
    }
    rep(i,N){
      ll v = s[i]-'a';
      bits[v].add(i, 1);
    }
  }

  ll range_count(ll l, ll r, char c){
    ll v = c-'a';
    return bits[v].range_sum(l,r);
  }
};

