struct AhoCorasick {
	int ch[M][C], f[M], pre[M];
	vector<int> isEnd[M];
	int idx;

	void Insert(string &s, int id, int op) {
		int o = 0;
		for (int i = op; i < s.size(); i++) {
			// 注意加入的是 [0, 26)
			int c = s[i] - 'a';
			if (ch[o][c])
				o = ch[o][c];
			else
				o = ch[o][c] = ++idx;
		}
		isEnd[o].push_back(id * (op ? -1 : 1));
	}

	void GetFail() {
		queue<int> q;
		for (int c = 0; c < C; c++)
			if (ch[0][c]) q.push(ch[0][c]);

		while (!q.empty()) {
			int o = q.front();
			q.pop();
			for (int c = 0; c < C; c++) {
				int &u = ch[o][c];
				int j = f[o];
				if (!u) {
					u = ch[j][c];
					continue;
				}
				q.push(u);
				while (j && !ch[j][c]) j = f[j];
				f[u] = ch[j][c];
				pre[u] = isEnd[f[u]].size() ? f[u] : pre[f[u]];
			}
		}
	}

	void GetMatchPos(string &s, vector<int> &pos) {
		int o = 0;
		for (int i = 0; i < s.size(); i++)
			o = ch[o][s[i] - 'a'];

		int p = o;
		// 即使不是接受态，往前跳几下就可能是接受态了
		if (!isEnd[o].size() && pre[o]) p = pre[o];
		while (isEnd[p].size()) {
			for (auto id: isEnd[p])
				if (id < 0) pos.push_back(-id);
			if (p == 0) break;
			p = pre[p];
		}
	}
};
AhoCorasick ac;

string s[N];
int pos[N][C];

int main() {
	ios::sync_with_stdio(0);

	int n;
	cin >> n;
	for (int i = 1; i <= n; i++) {
		cin >> s[i];
		memset(pos[i], 0x3f, sizeof(pos[i]));
		for (int j = 0; j < s[i].size(); j++) {
			int c = s[i][j] - 'a';
			pos[i][c] = min(pos[i][c], j);
		}
		ac.Insert(s[i], i, 0);
		ac.Insert(s[i], i, 1);
	}
	ac.GetFail();

	ll ans = 0;
	for (int i = 1; i <= n; i++) {
		vector<int> fail;
		ac.GetMatchPos(s[i], fail);
		for (auto p: fail) {
			if (p == i) continue;
			int c = s[p].front() - 'a';
			int len = s[i].size() - (s[p].size() - 1);
			ans += pos[i][c] < len;
		}
	}
	cout << ans << endl;

	return 0;
}

