class Loli {
	string str;
	vector<ll> hash, pw;
	ll mod = 1000000007, base = 1007;
	int len;
public:
	Loli(string st) : hash(st.length() + 1), pw(st.length() + 1), str(st), len(str.length()) {

		hash[0] = 0, pw[0] = 1;

		rep(i, 1, len + 1) {
			pw[i] = ((ll)pw[i - 1] * base) % mod;
			hash[i] = ((ll)hash[i - 1] * base + (ll)str[i - 1]) % mod;
		}
	}

	int gethash(int l, int r = -1) {//半開
    if(r == -1) r = len;
		return  (hash[r] - (ll)hash[l] * pw[r - l] % mod + mod) % mod;
	}
  inline int getALLhash(){
    return gethash(0, len);
  }
};
