struct Trie {
    vector<Trie*> to;
    Trie* par;
    vector<int> cntchar;
    Trie() {
        to.resize(27, NULL);
        par = NULL;
        cntchar.resize(26,0);
    }
};

void solve() {
    int n;
    cin >> n;
    vector<string> s(n);
    REP(i, n) {
        cin >> s[i];
    }
    Trie* root = new Trie();
    vector<Trie*> gchild(n, NULL);
    REP(i, n) {
        string& nowst = s[i];
        Trie* nownode = root;
        IREP(j, nowst.size()) {
            int now = nowst[j] - 'a';
            if (nownode->to[now] == NULL) {
                Trie* nextnode = new Trie();
                nownode->to[now] = nextnode;
                nextnode->par = nownode;
                nownode = nextnode;
            } else {
                nownode = nownode->to[now];
            }
        }
        gchild[i] = nownode;
        vector<bool> memo(26, false);
        int nowidx = nowst.size() - 1;
        while (nownode != root) {
            int now = nowst[nowidx--] - 'a';
            memo[now] = true;
            nownode = nownode->par;
            if (nownode != NULL) {
                REP(k, 26) {
                    if (memo[k]) {
                        ++nownode->cntchar[k];
                    }
                }
            }
        }
    }

    ll ans = 0;
    REP(i,n) {
        Trie* now = gchild[i];
        int nowidx = s[i][s[i].size()-1] - 'a';
        if (now->par != NULL) {
            Trie* parnode = now->par;
            ans += parnode->cntchar[nowidx] - 1;
        }
    }
    cout << ans << endl;
}

int main() {
    char tmp;
    while (cin >> tmp) {
        cin.putback(tmp);
        solve();
    }
}

#include <iostream>
