                if ((int)tmp[sub].size() == 0) tmp[sub] = v;
                else {
                    vector<int> &vv = tmp[sub];
                    for (int j=0; j<27; ++j) vv[j] += v[j];
                }
            }
            mp.swap(tmp);
            --cur;
        }
        string sub = S[i].substr(0, len-1);
