struct Trie{

    static const int N_alphabet = 26;
    static const char begin_alphabet = 'a';
    using data_type = int;
    static const data_type not_exist = 0;

    Trie *next[N_alphabet];
    data_type val = not_exist;

    Trie(){
        fill(next, next + N_alphabet, (Trie *)0);
    }

    // Sに対してval=vにupdate
    void insert(string &S, vec &num, int i = 0){
        if(i < S.size()){
            REP(j, 26) if(num[j] > 0){
                if(this->next[j] == NULL)
                    this->next[j] = new Trie();
                this->next[j]->val += 1;
            }

            num[S[i] - begin_alphabet]--;
            if(this->next[S[i] - begin_alphabet] == NULL)
                this->next[S[i] - begin_alphabet] = new Trie();
            this->next[S[i] - begin_alphabet]->insert(S, num, i + 1);

        }
    }

    // Sのvalを求める、なければnot_existを返す
    data_type find(string &S, int i = 0){
        if(i == S.size()) return this->val;
        if(this->next[S[i] - begin_alphabet] == NULL) return not_exist;
        return this->next[S[i] - begin_alphabet]->find(S, i + 1);
    }
};

