template<lint MOD>
struct mcint
{
	lint n;
	mcint()
	{
		n = 0;
	}
	mcint(lint a)
	{
		n = a % MOD;
	}
	mcint& operator+=(mcint a)
	{
		n += a.n;
		n %= MOD;
		return *this;
	}
	mcint& operator-=(mcint a)
	{
		n += MOD;
		n -= a.n;
		n %= MOD;
		return *this;
	}
	mcint& operator*=(mcint a)
	{
		n *= a.n;
		n %= MOD;
		return *this;
	}
	mcint& operator++()
	{
		n++;
		n %= MOD;
		return *this;
	}
	mcint& operator--()
	{
		n += MOD;
		n--;
		n %= MOD;
		return *this;
	}

	mcint operator+(mcint b)
	{
		mcint a = *this;
		a += b;
		return a;
	}
	mcint operator-(mcint b)
	{
		mcint a = *this;
		a -= b;
		return a;
	}
	mcint operator*(mcint b)
	{
		mcint a = *this;
		a *= b;
		return a;
	}
};

template<lint MOD>
struct RH
{
	vect<mcint<MOD>> rhash;
	vect<mcint<MOD>> powtbl;
	RH(string s, lint base) : rhash(s.length() + 1), powtbl(s.length() + 1)
	{
		rhash[0] = 0;
		powtbl[0] = 1;

		rep(i, s.length())
		{
			powtbl[i + 1] = powtbl[i] * base;
			rhash[i + 1] = rhash[i] * base + s[i];
		}
	}

	auto h(lint l, lint r)
	{
		return rhash[r] - rhash[l] * powtbl[r - l];
	}
};

int main()
{
	lint n;
	cin >> n;
	vecs s(n);
	rep(i, n)
		cin >> s[i];

	sort(all(s), [](const string a, const string b) {
		return a.length() < b.length();
		});

	lint base = mtrand() % 1000 + 1000;

	map<pair<lint, lint>, lint> m;

	lint ans = 0;

	rep(i, n)
	{
		RH<mod> rh(s[i], base);

		lint an[26] = {};

		an[s[i][0] - 'a']++;

		repb(j, 2, s[i].length())
		{
			an[s[i][j - 1] - 'a']++;
			lint h = rh.h(j, s[i].length()).n;

			rep(k, 26)
			{
				if (an[k] == 0)
					continue;
				ans += m[make_pair(k, h)];
			}
		}

		m[make_pair(s[i][0] - 'a', rh.h(1, s[i].length()).n)]++;
	}

	cout << ans << endl;

	return 0;
}

