struct trie{
    vector<vector<P> > G;
    vec num;
    trie() : G(1, vector<P>(0)), num(1, 0){}
    void append(string &s){
        int now = 0;
        ++num[now];
        for(char c : s){
            int id = c - 'a';
            bool flag = false;
            for(P p : G[now]){
                if(p.fi == id){
                    now = p.se;
                    ++num[now];
                    flag = true;
                    break;
                }
            }
            if(!flag){
                G[now].emplace_back(id, G.size());
                now = G.size();
                G.emplace_back();
                num.push_back(1);
            }
        }
    }
    int ans(string &s){
        int now = 0;
        for(char c : s){
            int id = c - 'a';
            for(P p : G[now]){
                if(p.fi == id){
                    now = p.se;
                    break;
                }
            }
        }
        return num[now];
    }
};

