struct Trie{
	const static int alphaSize = 26;
	inline int toNum(char c) {
		return c - 'a';
	}

	struct TrieNode{
		vector<int> child = vector<int>(alphaSize, 0);
		vector<int> count = vector<int>(alphaSize, 0);
	};
	vector<TrieNode> trie;

	inline ll insert(string s, vector<int>& cnt) {
		int cur = 0;
		for (int i = 0; i < s.length() - 1; i++) {
			for (int j = 0; j < alphaSize; j++)
				trie[cur].count[j] += (cnt[j] > 0);
//			W(trie[cur].count);

			if (trie[cur].child[toNum(s[i])])
				cur = trie[cur].child[toNum(s[i])];
			else {
				cur = trie[cur].child[toNum(s[i])] = trie.size();
				trie.push_back(TrieNode());
			}

			cnt[s[i] - 'a']--;
		}
		int last = -1;
		for (int j = 0; j < 26; j++)
			if (cnt[j] > 0) {
				last = j;
				break;
			}

//		W(s, "!", cur);
//		W(trie[cur].count);
//		W(last, trie[cur].count[last]);

		return trie[cur].count[last];
	}

	inline Trie() {
		trie.push_back(TrieNode());
	}
};

