		}
		nxt[T]=fst[S],fst[S]=T,key[T]=s,val[T]=1;
		T++;
	}
	int query(hashv s) {
		int S=(s.fi*mod2+s.se)%V;
		if (ptm[S]!=ctm) return 0;
		for (int j=fst[S];j!=-1;j=nxt[j]) if (key[j]==s) 
