const int mod1=1000000007,mod2=998244353,MAX=1000005,INF=1<<30;

ll ru1[MAX],ru2[MAX];

struct Rollinghash{
    string S;
    int n;
    int base1;
    int base2;
    vector<ll> h1,h2;
    vector<int> bit;

    void make(string &T,int ba1,int ba2){
        S=T;
        n=S.size();
        h1.assign(n+1,0);
        h2.assign(n+1,0);
        bit.assign(n+1,0);
        base1=ba1;
        base2=ba2;

        for(int i=1;i<=n;i++){
            h1[i]=h1[i-1]*base1+ll(S[i-1]-'a');
            h1[i]%=mod1;

            h2[i]=h2[i-1]*base2+ll(S[i-1]-'a');
            h2[i]%=mod2;
        }

        for(int i=n-1;i>=0;i--){
            bit[i]=bit[i+1]|(1<<(S[i]-'a'));
        }
    }

    pair<ll,ll> ha(int l,int r){
        pair<ll,ll> res;
        res.fi=(h1[r]-h1[l]*ru1[r-l]%mod1+mod1)%mod1;
        res.se=(h2[r]-h2[l]*ru2[r-l]%mod2+mod2)%mod2;

        return res;
    }//開区間
};

