    sort(all(A),[](auto a,auto b){
        if(si(a)==si(b)) return a<b;
        return si(a)<si(b);
    });

    vector<Rollinghash> S(N);
    for(int i=0;i<N;i++){
        S[i].make(A[i],ha1,ha2);
    }

    int i=0;
    while(i<N){
