class BFirstSecond {
public:

    vector<vector<int>> graph;
    vector<vector<int>> dp;

    void dfs(string& s, int idx, int pos, vector<int>& now, vector<int>& cnt) {
      //cerr << s << endl;
      debug(idx, pos);
      int d = s[idx] - 'a';
      chmax(cnt[d], now[d]);

      if (idx+1 == s.size()) {
        dp[pos][s.back()-'a']++;
        debug(pos, s.back()-'a');
        int last = s.back()-'a';
        chmax(cnt[last], now[last]);
        return;
      }

      rep(i, 26) {
        if (dp[pos][i] > 0) debug(pos, i, dp[pos][i]);
        now[i] += dp[pos][i];
      }
      chmax(cnt[d], now[d]);

      if (graph[pos][d] == -1) {
        graph[pos][d] = graph.size();
        dp.emplace_back(vector<int>(26, 0));
        graph.emplace_back(vector<int>(26, -1));
        dfs(s, idx+1, graph[pos][d], now, cnt);
      } else {
        dfs(s, idx+1, graph[pos][d], now, cnt);
      }


    }

    void solve(istream& cin, ostream& cout) {
      SPEED;
      int n; cin >> n;
      vector<pair<int, string>> vec(n);
      rep(i, n) {
        cin >> vec[i].second;
        reverse(all(vec[i].second));
        vec[i].first = vec[i].second.size();
      }
      sort(all(vec));
      graph.emplace_back(vector<int>(26, -1));
      dp.emplace_back(vector<int>(26, 0));
      ll ret = 0;
      rep(i, n) {
        vector<int> now(26);
        vector<int> cnt(26);
        dfs(vec[i].second, 0, 0, now, cnt);
        rep(j, 26) {
          ret += cnt[j];
        }
      }
      cout << ret << endl;
    }
};

signed main() {
  BFirstSecond solver;
  std::istream& in(std::cin);
  std::ostream& out(std::cout);
  solver.solve(in, out);
  return 0;
}

