ll power(ll a, ll b, ll z = MOD)
{
	ll res = 1;
	a = (a%z);
	while(b)
	{
		if(b&1)
			res = (res*a)%z;
		a = (a*a)%z;
		b = b>>1;
	}
	return res;
}

ll inverse(ll a, ll z = MOD)
{
	return power(a, z-2, z);
}

ll extend(ll a, ll b, ll &x, ll &y)
{
	if(b == 0)
	{
		x = 1;
		y = 0;
		return a;
	}
	ll x1, y1;
	ll g = extend(b, a%b, x1, y1);
	x = y1;
	y = x1- (a/b)*y1;
	return g;
}

ll mat_power(ll a, ll b, ll c, ll d, ll n, ll z = MOD)
{
	ll a0 = 1, b0 = 0, c0 = 0, d0 = 1;
	while(n)
	{
		if(n&1)
		{
			ll a1 = a0, b1 = b0, c1 = c0, d1 = d0;
			a0 = (a1*a + b1*c)%z;
			b0 = (a1*b + b1*d)%z;
			c0 = (c1*a + d1*c)%z;
			d0 = (c1*b + d1*d)%z;
		}
		ll a1 = a, b1 = b, c1 = c, d1 = d;
		a = (a1*a1 + b1*c1)%z;
		b = (a1*b1 + b1*d1)%z;
		c = (c1*a1 + d1*c1)%z;
		d = (c1*b1 + d1*d1)%z;
		n = n>>1;
	}
	return c0;
}

int n;
string aray[200001];
int top[200001][26];

ll dp(int l, int r, int ind)
{
	if(l >= r)
		return 0;
	if((int)aray[l].size() == ind+1)
	{
		ll final = 0;
		int last = r+1;
		for(int i=r;i>l;i--)
		{
			if(top[i][aray[l][ind]-'a'] >= ind)
				final++;
			if(aray[i][ind] != aray[l][ind])
				last = i;
		}
		return final + dp(l+1, last-1, ind+1) + dp(last, r, ind);
	}
	for(int i=l+1;i<=r;i++)
	{
		if(aray[l][ind] != aray[i][ind])
			return dp(l, i-1, ind+1) + dp(i, r, ind);
	}
	return dp(l, r, ind+1);
}

