template<lint MOD>
struct mcint
{
	lint n;
	mcint()
	{
		n = 0;
	}
	mcint(lint a)
	{
		n = a % MOD;
	}
	mcint& operator+=(mcint a)
	{
		n += a.n;
		n %= MOD;
		return *this;
	}
	mcint& operator-=(mcint a)
	{
		n += MOD;
		n -= a.n;
		n %= MOD;
		return *this;
	}
	mcint& operator*=(mcint a)
	{
		n *= a.n;
		n %= MOD;
		return *this;
	}
	mcint& operator++()
	{
		n++;
		n %= MOD;
		return *this;
	}
	mcint& operator--()
	{
		n += MOD;
		n--;
		n %= MOD;
		return *this;
	}

	mcint operator+(mcint b)
	{
		mcint a = *this;
		a += b;
		return a;
	}
	mcint operator-(mcint b)
	{
		mcint a = *this;
		a -= b;
		return a;
	}
	mcint operator*(mcint b)
	{
		mcint a = *this;
		a *= b;
		return a;
	}
};

template<lint MOD>
struct RH
{
	vect<mcint<MOD>> rhash;
	vect<mcint<MOD>> powtbl;
	RH(const string& s, lint base) : rhash(s.length() + 1), powtbl(s.length() + 1)
	{
		rhash[0] = 0;
		powtbl[0] = 1;

		rep(i, s.length())
		{
			powtbl[i + 1] = powtbl[i] * base;
			rhash[i + 1] = rhash[i] * base + s[i];
		}
	}

	auto h(lint l, lint r)
	{
		return rhash[r] - rhash[l] * powtbl[r - l];
	}
};

