	Node* ch[26];
    //残りの文字にアルファベット'a'+jが何個含まれるか
	int cnt[26];
	Node() {
		rep(i, 26) {
			ch[i] = NULL;
			cnt[i] = 0;
		}
	}
};

void add(Node* nd, string s) {
	reverse(all(s));
	int alf[26] = {};
	rep(i, s.size())alf[s[i] - 'a']++;
	rep(j, 26)if (alf[j] > 0)nd->cnt[j]++;
	rep(i, s.size()) {
		int t = s[i] - 'a';
		alf[t]--;
		if (nd->ch[t] == NULL)nd->ch[t] = new Node();
		nd = nd->ch[t];
		rep(j, 26)if (alf[j] > 0) {
			nd->cnt[j]++;
		}
	}
}
int query(Node* nd, string s) {
	int z = s[0] - 'a';
	for (int i = (int)s.size() - 1; i > 0; i--) {
		int t = s[i] - 'a';
		if (nd->ch[t] == NULL)return 0;
		nd = nd->ch[t];
	}
	return nd->cnt[z];
}
