	for(int i=0;i<x.length();i++)
	{
		int b = x[i] - 'a';
		if(!cur->child[b])cur->child[b] = new trie();
		cur = cur->child[b];
		cur->f[b]++;
	}
}

void dfs(trie* c)
{
    for(int i=0;i<26;i++)if(c->child[i])
    {
        dfs(c->child[i]);
        for(int j=0;j<26;j++)
            c->f[j] += c->child[i]->f[j];
    }
}

int check(string x)
{
    int m = x.length();
    trie* cur = head;
	for(int i=0;i<m-1;i++)cur = cur->child[x[i]-'a'];
	int lastc = x[m-1]-'a';
	int ans = (cur->child[lastc]->f[lastc]) - 1;
	for(int i=0;i<26;i++)if(i != lastc && cur->child[i])
        ans += cur->child[i]->f[lastc];
	return ans;
}
