        int cnt[26];
        Node(){
            rep(i, 26){
                ptr[i] = nullptr;
                cnt[i] = 0;
            }
        }
    };

    Node *root;
    Trie(){
        root = new Node;
    }

    void add(string &s){
        Node *t = root;
        rep(i, s.size()){
            if(!t->ptr[s[i] - 'a']) t->ptr[s[i] - 'a'] = new Node;
            t->ptr[s[i] - 'a']->cnt[s[i] - 'a']++;
            t = t->ptr[s[i] - 'a'];
        }
    }

    void _dfs(Node *t){
        int tmp[26];
        memset(tmp, 0, sizeof(tmp));
        rep(i, 26)if(t->ptr[i]){
            _dfs(t->ptr[i]);
            rep(c, 26) tmp[c] += t->ptr[i]->cnt[c];
        }
        rep(c, 26) chmax(t->cnt[c], tmp[c]);
    }

    void dfs(){
        _dfs(root);
    }

    int query(string &s){
        Node *t = root;
        rep(i, (int)s.size()-1){
            t = t->ptr[s[i] - 'a'];
        }
        return t->cnt[*s.rbegin() - 'a'];
    }

    void _print(Node *t){
        rep(i, 26) printf("%d ", t->cnt[i]);
        printf("\n");
        rep(i, 26)if(t->ptr[i]){
            printf("%c\n", i + 'a');
            _print(t->ptr[i]);
        }
    }

    void print(){
        _print(root);
    }
};

