struct TrieNode
{
	vector<TrieNode* >ptr;
	vi fre;
	TrieNode()
	{
		ptr.resize(26);
		rep(i,26)
			ptr[i] = NULL;
		fre.resize(26, 0);
	}
};
void Insert(TrieNode* root, str s)
{
	int n = s.length();

	rloop(i,n-1,1,1)
	{
		int c = s[i]-'a';
		if(root->ptr[c])
			root = root->ptr[c];
		else
		{
			root->ptr[c] = new TrieNode;
			root = root->ptr[c];
		}
	}
	root->fre[s[0]-'a']++;
}
void input()
{  
    int n;
