	vs s(n);
    TrieNode *root = new TrieNode;
    rep(i,n)
    {
    	cin >> s[i];
    	s[i] += 'a';
    	Insert(root, s[i]);
    }

    lli ans = 0;
    rep(i,n)
    {
    	TrieNode *tmp = root;
    	vi fres(26, 0);
    	int m = s[i].length();
    	rep(j, m)
    		fres[s[i][j]-'a']++;

    	rloop(j, m-1, 1, 1)
    	{
    		tmp = tmp->ptr[s[i][j]-'a'];
    		fres[s[i][j]-'a']--;
    		rep(k, 26)
    			if(tmp->fre[k] && fres[k])
    				ans += tmp->fre[k];
    	}
    }
    cout << ans/2 <<'\n';
}

