template<lint MOD>
struct mcint
{
	lint n;
	mcint()
	{
		n = 0;
	}
	mcint(lint a)
	{
		n = a % MOD;
	}
	mcint& operator+=(mcint a)
	{
		n += a.n;
		n %= MOD;
		return *this;
	}
	mcint& operator-=(mcint a)
	{
		n += MOD;
		n -= a.n;
		n %= MOD;
		return *this;
	}
	mcint& operator*=(mcint a)
	{
		n *= a.n;
		n %= MOD;
		return *this;
	}
	mcint& operator++()
	{
		n++;
		n %= MOD;
		return *this;
	}
	mcint& operator--()
	{
		n += MOD;
		n--;
		n %= MOD;
		return *this;
	}

	mcint operator+(mcint b)
	{
		mcint a = *this;
		a += b;
		return a;
	}
	mcint operator-(mcint b)
	{
		mcint a = *this;
		a -= b;
		return a;
	}
	mcint operator*(mcint b)
	{
		mcint a = *this;
		a *= b;
		return a;
	}
};

mcint<mod> rhash[200010];
