struct RH
{
	RH(const string& s, lint base, lint base2)
	{
		rhash[0] = 0;
		powtbl[0] = 1;
		rhash2[0] = 0;
		powtbl2[0] = 1;

		rep(i, s.length())
		{
			powtbl[i + 1] = powtbl[i] * base;
			rhash[i + 1] = rhash[i] * base + s[i];
			powtbl2[i + 1] = powtbl2[i] * base2;
			rhash2[i + 1] = rhash2[i] * base2 + s[i];
		}
	}

	auto h(lint l, lint r)
	{
		return rhash[r] - rhash[l] * powtbl[r - l];
	}

	auto h2(lint l, lint r)
	{
		return rhash2[r] - rhash2[l] * powtbl2[r - l];
	}
};

