const ull Base = 137;
const int Z = 1e5 + 5;
const int N = 2e5 + 10;
//const int N = 100 + 10;
unordered_map<ull, int> t[Z + 10];
int n, len[N], id[N];
string s[N];
int cur[26];
bool cmp(int x, int y)
{
	return len[x] > len[y];
}
int main()
{
	std::ios::sync_with_stdio(false);
	cin >> n;
	for (int i = 1; i <= n; ++i)
	{
		cin >> s[i];
		len[i] = s[i].length();
	}
	iota(id + 1, id + 1 + n, 1);
	sort(id + 1, id + 1 + n, cmp);
	ll ans = 0;
	int mx = 0;
	for (int i = 1; i <= n; ++i)
	{
		int x = id[i];
		memset(cur, 0, sizeof cur); 
		ull val = 0;
		for (int j = len[x] - 1; j >= 1; --j)
			val = val * Base + s[x][j] - 'a' + 1, ++cur[s[x][j] - 'a'];
		++cur[s[x][0] - 'a'];
		if (len[x] - 1 <= mx && len[x] <= Z)
			ans += t[len[x] - 1][val * Base + s[x][0] - 'a' + 1];
		val = 0;
		int lim = i == n ? -1 : len[id[i + 1]] - 1;
		if (lim >= 0)
			for (int c = 0; c < 26; ++c)
				if (cur[c])
					++t[0][val * Base + c + 1];
		for (int j = len[x] - 1, p = 1; j >= 0; --j, ++p)
		{
			val = val * Base + s[x][j] - 'a' + 1;
			cur[s[x][j] - 'a']--;
			if (p > Z || p > lim)
				break;
			for (int c = 0; c < 26; ++c)
				if (cur[c])
					++t[p][val * Base + c + 1];
		}
	}
	cout << ans << endl;
	return 0;
}

