    struct node{
        int sz=0,sz2=0;
        np ch[26]={};
    };
    np root=new node();
    void add(string s){
        np t=root;
        t->sz++;
        rep(i,s.size()){
            if(!t->ch[s[i]-'a'])t->ch[s[i]-'a']=new node();
            t=t->ch[s[i]-'a'];
            t->sz++;
        }
        t->sz2=1;
    }
    void add2(string s){
        map<char,lint>m;
        rep(i,s.size())m[s[i]]++;
        np t=root;
        t->sz++;
        if(!t->ch[s[0]-'a'])t->ch[s[0]-'a']=new node();
        rep(i,s.size()){
            if(!t->ch[s[i]-'a'])t->ch[s[i]-'a']=new node();
            m[s[i]]--;
            t->sz2++;
            for(auto e:m){
                if(e.first==s[i])continue;
                if(!t->ch[e.first-'a'])t->ch[e.first-'a']=new node();
                if(e.second)t->ch[e.first-'a']->sz2++;
            }
            t=t->ch[s[i]-'a'];
        }
    }
    lint get(string s){
        np t=root;
        rep(i,s.size()){
            t=t->ch[s[i]-'a'];
        }
        return t->sz2;
    }
};

