struct node
{
    int n; //部分木に存在する終端の個数
    vector<int> cnt; //部分木に'a'+iを含む文字列はcnt[i]個存在する
    node() : n(0), cnt(26) {}
    node& operator+=(const node &rh)
    {
        n += rh.n;
        rep(i,26) cnt[i] += rh.cnt[i];
        return *this;
    }
};
node dfs(Trie* t) 
{
    node v;
    vector<ll> chars(26); //子の終端の文字と個数
    rep(i,26)
    {
        if(t -> next[i] == NULL) continue;
        if(t -> next[i] -> cnt > 0)
        {
            chars[t -> next[i] -> c] += t -> next[i] -> cnt;
        }
        v += dfs(t -> next[i]);
    }
    if(t -> par == NULL)
    {
        rep(i,26) ans += chars[i] * (chars[i] - 1) / 2;
    }
    rep(i,26)
    {
        ans += chars[i] * (v.cnt[i] - chars[i]);
    }
    //このノードの情報を含める
    v.n += (t -> cnt);
    v.cnt[t -> c] = v.n;
    return v;
}

