struct RollingHash{
    const long long MASK30 = (1LL << 30) - 1;
    const long long MASK31 = (1LL << 31) - 1;
    const long long MASK61 = MOD;

    int N;
    vector<long long> hs, b;
    long long base;

    RollingHash(string &s, long long base_=-1){
        if(base_ == -1){
            random_device rnd; // 非決定的な乱数生成器
            mt19937 mt(rnd());
            base = mt()+1;
        }
        else{
            base = base_;
        }

        N = s.size();
        hs.resize(N+1); b.resize(N+1); b[0] = 1; hs[0] = 0;
        for(int i=0; i<N; i++){
            b[i+1] = Mul(b[i], base);
            hs[i+1] = Mul(hs[i], base) + s[i];
            if(hs[i+1] >= MOD) hs[i+1] -= MOD;
        }
    }

    long long get(int l, int r){
        long long ret = hs[r] + MOD - Mul(hs[l], b[r - l]);
        if(ret >= MOD) ret -= MOD;
        return ret;
    }

    //mod 2^61-1を計算する関数
    long long CalcMod(long long x){
        long long xu = x >> 61;
        long long xd = x & MASK61;
        long long ret = xu + xd;
        if (ret >= MOD) ret -= MOD;
        return ret;
    }

    //a*b mod 2^61-1を返す関数(最後にModを取る)
    long long Mul(long long a, long long b){
        long long au = a >> 31;
        long long ad = a & MASK31;
        long long bu = b >> 31;
        long long bd = b & MASK31;
        long long mid = ad * bu + au * bd;
        long long midu = mid >> 30;
        long long midd = mid & MASK30;
        return CalcMod(au * bu * 2 + midu + (midd << 31) + ad * bd);
    }
};

bool comp(string s, string t){
    return s.size()<t.size();
}

void Main(){
    int N; cin >> N;
    vector<string> S(N); REP(i,N){cin >> S[i]; REVERSE(S[i]);}
    sort(ALL(S), comp);

    random_device rnd; // 非決定的な乱数生成器
    mt19937 mt(rnd());
    ll base = mt()+1;

    ll ans = 0;
    map<ll,ll> m;
    REP(i,N){
        int k = S[i].size();
        VVI n(26,VI(k+1,0));
        REP(j,k){
            int x = S[i][j]-'a';
            n[x][j] = 1;
        }
        REP(l,26)REP(j,k) n[l][k-1-j] += n[l][k-j];

        RollingHash rh(S[i], base);
        REP(j,k){
            REP(a,26){
                if(n[a][j] == 0) continue;
                ll h = rh.Mul(rh.get(0,j), base) + (ll)(a+'a');
                if(EXIST(m,h)) ans += m[h];
            }
        }

        ll h = rh.get(0,k);
        if(EXIST(m,h)) m[h]++;
        else m[h] = 1;
    }
    cout << ans << en;
    return;
}

