void Hash(int ind,string s){
	ll has=0;
	h[ind].pb(s[0]);
	has+=s[0];
	for(int i=1;i<s.size();i++){
		h[ind].pb(h[ind][i-1]+(s[i])*p[i]);
		has+=(s[i])*p[i];
	}
	used[has]++;
}
int main(){
	p[0]=1;
	for(int i=1;i<=200000;i++)p[i]=p[i-1]*31;

	int n;cin>>n;
