	ll cnt=0;

	for(int i=1;i<=n;i++){

		ll cnt1=0;

		int used1[27];for(int j=0;j<26;j++)used1[j]=0;
		for(int j=0;j<(int)s[i].size();j++){
			if(used1[s[i][j]-'a']==0){
				ll num=s[i][j];
				cnt+=used[num];
				cnt1+=used[num];
			}
			used1[s[i][j]-'a']++;
		}
		for(int j=0;j<=26;j++)used1[j]=0;

		for(int j=0;j<(int)s[i].size();j++){
			if(used1[s[i][j]-'a']==0){
				for(int k=(int)s[i].size()-1;k>j;k--){
