class Trie
{
    public:
    Trie* child[26];
    bool last;
    int pre_count=0, cnt=0;
    vector<string> prefix;
    int cntt=0;
    Trie()  
    {
        cnt=0;
        last=false;
        cntt=0;
        loop(i,0,26)
        {
            child[i]=NULL;
        }
    }   
    void insert(Trie *root, string s)
    {
        Trie *itr=root;
        each(x,s)
        {
            Trie *next=itr->child[x-'a'];
            if(!next)
            {
                next=new Trie();
                itr->child[x-'a']=next;
            }
            itr=next;
            itr->cnt++;
        }
        itr->last=true;
        itr->cntt++;
    }
    int search(Trie *root, string s)
    {
        Trie *itr=root;
        each(x,s)
        {
            if(!itr->child[x-'a'])
            {
                return 0;
            }
            itr=itr->child[x-'a'];
        }
        return itr->cntt;
    }
};
void solve()
{
    int n;
    IN n;
    vector<string> v(n);
    read(v)
    Trie *tr=new Trie();
    loop(i,0,n)
    {
        vector<int> cnt(26,0);
        each(x,v[i])
        {
            cnt[x-'a']++;
        }
        string temp="";
        rloop(j,sz(v[i])-1,0)
        {
            loop(ch,0,26)
            {
                if(cnt[ch])
                {
                    tr->insert(tr,temp+(char)(ch+'a'));
                }
            }
            cnt[v[i][j]-'a']--;
            temp+=v[i][j];
        }
    }
    ll ans=0;
    loop(i,0,n)
    {
        reverse(all(v[i]));
        ans+=(ll)(tr->search(tr,v[i]));
        ans--;
    }
    OUT ans<<nl;
}  

