typedef long long LL;
const int MN = 200005;
const int ML = 1000005;
const int Sig = 26;

int N;
char s[ML];
int Key[MN], Cha[MN];

int tr[ML][Sig], num[ML][Sig], buk[Sig], cnt;

inline void Insert(int id, int len) {
	static int stk[ML];
	for (int j = 0; j < Sig; ++j) buk[j] = 0;
	stk[0] = 1;
	for (int i = 1; i <= len; ++i) {
		int w = stk[i - 1], c = s[i] - 'a';
		if (!tr[w][c]) tr[w][c] = ++cnt;
		stk[i] = tr[w][c];
		buk[c] = i;
	}
	Key[id] = stk[len - 1];
	Cha[id] = s[len] - 'a';
	for (int j = 0; j < Sig; ++j) if (buk[j])
		++num[stk[buk[j] - 1]][j];
}

int main() {
	scanf("%d", &N), cnt = 1;
	for (int i = 1; i <= N; ++i) {
		scanf("%s", s + 1);
		int len = strlen(s + 1);
		std::reverse(s + 1, s + len + 1);
		Insert(i, len);
	}
	for (int i = cnt; i >= 1; --i)
		for (int j = 0; j < Sig; ++j) if (tr[i][j]) {
			int v = tr[i][j];
//			printf("(%d) ----%c---> (%d)\n", i, 'a' + j, v);
			for (int k = 0; k < Sig; ++k)
				num[i][k] += num[v][k];
		}
	LL Ans = 0;
	for (int i = 1; i <= N; ++i)
