bool cmp(string &a, string &b) {
    return a.size() < b.size();
}

void add(int id, int v) {
    if (id == ts.size()) {
        ++bor[v].term;
        return;
    }
    for (int i = 0; i < 26; ++i) {
        if (bor[v].to[i] == -1) continue;
        if (last[i] < id) continue;
        ans += bor[bor[v].to[i]].term;
    }
    if (bor[v].to[ts[id] - 'a'] == -1) {
        while (id < ts.size()) {
            int tv = bor.size();
            bor[v].to[ts[id] - 'a'] = tv;
            bor.push_back(node());
            ++id;
            v = tv;
        }
        ++bor[v].term;
        return;
    }
    add(id + 1, bor[v].to[ts[id] - 'a']);
}

