	for (int i = 0; i < N; ++i) mp[i].clear();
	int ans = 0;
	for (string s : v) {
		int n = s.size();
		int cnt[26] = {0};
		for (char c : s) {
			cnt[c - 'a']++;
		}
		int hash1 = 0, hash2 = 0;
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < 26; ++j) {
				int curhash1 = hash1 * pw + (j + 1), curhash2 = hash2 * pw + (j + 1);
				curhash1 %= mod1, curhash2 %= mod2;
				if (cnt[j] and mp[i + 1].count({curhash1, curhash2})) {
					ans += mp[i + 1][{curhash1, curhash2}];
				}
			}
			--cnt[s[n - i - 1] - 'a'];
			hash1 = hash1 * pw + (s[n - i - 1] - 'a') + 1;
			hash2 = hash2 * pw + (s[n - i - 1] - 'a') + 1;
			hash1 %= mod1, hash2 %= mod2;
		}
		++mp[n][{hash1, hash2}];
	}
	return ans;
}

int32_t main() {	
	fast_cin();  
	int n; cin >> n;
	vector<string> v(n);
	for (auto &s : v) cin >> s;
	int ans = solve(v);
	reverse(v.begin(), v.end());
	ans += solve(v);
	cout << ans << endl;
	return 0;
}

