struct Trie {
    const char base;
    struct Node {
        array<int, 26> child; // 子の頂点番号 存在しなければ-1
        array<ll, 26> cnt;
        Node() {
            for(int i = 0; i < 26; i++) {
                child[i] = -1;
                cnt[i] = 0;
            }
        }
    };
    vector<Node> nodes;
    Trie(char base) : base(base) { nodes.emplace_back(Node()); }
    void insert(const string &s) {
        int now = 0;
        int n = (int)s.size();
        for(int i = 0; i < n - 1; i++) {
            int &nxt = nodes[now].child[s[i] - base];
            if(nxt == -1) {
                nxt = (int)nodes.size();
                nodes.emplace_back(Node());
            }
            now = nxt;
        }
        nodes[now].cnt[s.back() - base]++;
    }
    ll get(const string &s, vector<int> &exist) {
        ll res = 0;
        int now = 0;
        int n = (int)s.size();
        for(int i = 0; i < n; i++) {
            for(int k = 0; k < 26; k++) {
                if(exist[i] & (1 << k)) {
                    res += nodes[now].cnt[k];
                }
            }
            int &nxt = nodes[now].child[s[i] - base];
            if(nxt == -1) {
                return res;
            }
            now = nxt;
        }
        return res;
    }
};

int main() {
