    });

    Trie trie('a');
    ll ans = 0;
    for(int i = 0; i < N; i++) {
        int n = (int)s[i].size();
        vector<int> exist(n + 1, 0);
        for(int j = n - 1; j >= 0; j--) {
            exist[j] = exist[j + 1] | (1 << (s[i][j] - 'a'));
        }
        ans += trie.get(s[i], exist);
        trie.insert(s[i]);
    }
    cout << ans << endl;
}

