  ll tsz = trie.nodes.size();
  vector char_cnt(tsz, vector(26, 0LL));
  vector<ll> str_cnt(tsz);

  auto dfs = [&](auto rF, int idx) -> void {
    auto& nd = trie.nodes[idx];
    for (ll c0 = 0; c0 < 26; c0++) {
      ll cld = nd.next[c0];
      if (cld == -1) continue;
      rF(rF, cld);
      for (ll c = 0; c < 26; c++) {
	if (c == c0) char_cnt[idx][c] += str_cnt[cld];
