const int MAXN = 1000005;

llint n, cnt = 1, sol;
string s[MAXN];
int p[MAXN][26], val[MAXN], siz[MAXN];
int dp[MAXN][26];

void ubaci (string t) {
    int len = t.size();
    int curr = 1;
    for (int i = len - 1; i >= 0; i--) {
        if (p[curr][t[i] - 'a'] == 0) p[curr][t[i] - 'a'] = ++cnt;
        curr = p[curr][t[i] - 'a'];
    }
    val[curr]++;
}

void dfs (int x) {
    siz[x] += val[x];
    for (int i = 0; i < 26; i++) {
        int sus = p[x][i];
        if (sus == 0) continue;
        dfs(sus);
        siz[x] += siz[sus];
        for (int j = 0; j < 26; j++) {
            if (i != j) dp[x][j] += dp[sus][j]; else dp[x][j] += siz[sus];
        }
    }
}

void upit (string t) {
    int len = t.size();
    int curr = 1;
    for (int i = len - 1; i > 0; i--) {
        curr = p[curr][t[i] - 'a'];
    }
    sol += dp[curr][t[0] - 'a'];
}

