using namespace std;

typedef long long ll;

vector< vector<int> > T[26];
int l, Size;

bool Match(string a, string b, int k)
{
    for (int i = 0; i < k; ++i)
        if (a[i] != b[i])
            return false;
    return true;
}

void Stworz(int n, vector<string> a)
{
    int p = 1;
    while (p < n)
        p *= 2;
    l = p;
    Size = 2 * p - 1;
    vector< vector<int> > puste(Size + 1);
    for (int i = 0; i < 26; ++i)
        T[i] = puste;
    for (int i = 0; i < 26; ++i)
    {
        for (int j = 0; j < n; ++j)
        {
            for (int k = a[j].size() - 1; k >= 0; --k)
            {
                if (a[j][k] == (char) (i + 'a'))
                {
                    T[i][j + l].push_back(k);
                    break;
                }
            }
        }
    }
    for (int i = 0; i < 26; ++i)
    {
        for (int j = l - 1; j >= 1; --j)
        {
            for (int k = 0; k < T[i][2 * j].size(); ++k)
                T[i][j].push_back(T[i][2 * j][k]);
            for (int k = 0; k < T[i][2 * j + 1].size(); ++k)
                T[i][j].push_back(T[i][2 * j + 1][k]);
            sort(T[i][j].begin(), T[i][j].end());
        }
    }
}

ll Ile(vector<int>& a, int k)
{
    int l = 0, p = a.size() - 1, s, r = -1;
    while (l <= p)
    {
        s = (l + p) / 2;
        if (a[s] >= k)
        {
            r = s;
            p = s - 1;
        }
        else
            l = s + 1;
    }
    if (r == -1)
        return 0;
    return a.size() - r;
}

ll Pyt(vector< vector<int> >& T, int a, int b, int k)
{
    a += l;
    b += l;
    int wyn = Ile(T[a], k);
    if (a != b)
        wyn += Ile(T[b], k);
    while (a / 2 != b / 2)
    {
        if (a % 2 == 0)
            wyn += Ile(T[a + 1], k);
        if (b % 2 == 1)
            wyn += Ile(T[b - 1], k);
        a /= 2;
        b /= 2;
    }
    return wyn;
}

int main()
{
    ios_base::sync_with_stdio(0);
    int n;
    cin >> n;
    vector<ll> lit(26, 0);
    vector<string> a;
    for (int i = 0; i < n; ++i)
    {
        string x;
        cin >> x;
        if (x.size() == 1)
            ++lit[x[0] - 'a'];
        else
        {
            a.push_back(x);
            reverse(a.back().begin(), a.back().end());
            a.back() += (char) ('a' - 1);
        }
    }
    sort(a.begin(), a.end());
    n = a.size();
    for (int i = 0; i < n; ++i)
        if (a[i][a[i].size() - 1] == (char) ('a' - 1))
            a[i].erase(a[i].size() - 1, 1);
    ll odp = 0;
    Stworz(n, a);
    for (int i = 0, j = 0; j < n; ++j)
    {
        while (!(a[i].size() >= a[j].size() && Match(a[i], a[j], a[j].size() - 1)))
            ++i;
        if (i == j)
            continue;
        odp += Pyt(T[a[j][a[j].size() - 1] - 'a'], i, j - 1, a[j].size() - 1);
    }
    sort(a.begin(), a.end());
    for (int i = n - 1, j = n - 1; i >= 0; --i)
    {
        while (!(a[j].size() >= a[i].size() && Match(a[i], a[j], a[i].size() - 1)))
            --j;
        if (i == j)
            continue;
        odp += Pyt(T[a[i][a[i].size() - 1] - 'a'], i + 1, j, a[i].size() - 1);
    }
    vector<ll> wyst(26, 0);
    for (int i = 0; i < n; ++i)
    {
        for (int j = 0; j < 26; ++j)
        {
            bool jest = false;
            for (int k = 0; k < a[i].size(); ++k)
                if (a[i][k] == (char) (j + 'a'))
                    jest = true;
            if (jest)
                ++wyst[j];
        }
    }
    for (int i = 0; i < 26; ++i)
        odp += lit[i] * wyst[i];
    cout << odp;
    return 0;
}

