ll ans;

template<int char_size,int base>
struct Trie{
    struct Node {
        vector<int> next;  //子の頂点番号を格納。存在しなければ-1
        vector<int> accept; //末端がこの頂点になる文字列のstr_idを保存
        int c;  //文字数をint型で表現したもの
        int common;  //いくつの文字列がこの頂点を共有しているか
        Node(int c_): c(c_),common(0){
            next.assign(char_size, -1);

        }
    };
    vector<Node> nodes;//Trie 本体
    int root; //根
    Trie() :root(0){
        //初期化。はじめは根しか無い
        nodes.push_back(Node(root));
    }

    void insert(const string &word, int word_id){//単語:str と　単語の番号: str_id
    int node_id=0;
    for(int i=0;i< (int)word.size();i++){
        int c = (int)(word[i]-base);
        int &next_id = nodes[node_id].next[c];
        if(next_id == -1){ //次の頂点が存在しなければ追加
        next_id = (int)nodes.size();
        nodes.push_back(Node(c));

        }
        ++nodes[node_id].common;
        node_id = next_id;
    }
    ++nodes[node_id].common;//単語の終端なのでノードが終端となる文字列の数として加算
    nodes[node_id].accept.push_back(word_id);//単語の終端なので、頂点に番号を入れておく

    }
    void insert(const string&word){
        insert(word,nodes[0].common);
    }
    //単語とprefixの検索

    bool search(const string &word, bool prefix = false){
        int node_id=0;
        for(int i=0;i<(int)word.size();i++){
            int c= (int)(word[i]-base);
            int next_id = nodes[node_id].next[c];
            if(next_id==-1){
                return false;
            }
            node_id = next_id;

        }
        return (prefix)? true: nodes[node_id].accept.size()>0; //最後の頂点が受理状態か確認
    }
    void mysearch(const string &word ){
        bool exist[word.size()][char_size];
        memset(exist,false,sizeof(exist));
        repr(i,word.size()){
            if(i==word.size()-1){
                rep(j,char_size)exist[i][j]=(j==(int)(word[i]-base));

            }
            else{
                rep(j,char_size)exist[i][j]=(j==(int)(word[i]-base))|exist[i+1][j];

            }
        }

        int node_id=0;
        for(int i=0;i<(int)word.size();i++){
            rep(j,26)if(exist[i][j]){
                int next_id = nodes[node_id].next[j];
                if(next_id!=-1&&nodes[next_id].accept.size()>0)ans++;
            }
            node_id = nodes[node_id].next[(int)(word[i]-base)];

        }
    }
    //指定したprefixを持つ文字列があるか検索
    bool startwith(const string &prefix){
        return search(prefix,true);


    }
    // 挿入した単語の数
    int count() const{
        return (nodes[0].common);
    }
    //Trie木のノード数
    int size() const{
        return (int)nodes.size();
    }



};

