const ll P = 31;
const ll MX = 1000005;

ll pwr[MX];
map<pair<ll, ll>, vector<ll> > f;
vector<string> v;

int main(){
	fast_cin();
	// freopen("input.in","r",stdin);
	// freopen("output.out","w",stdout);
	ll n; cin >> n;
	pwr[0] = 1;
	for(ll i = 1; i < MX; i++) {
		pwr[i] = (P * pwr[i - 1]) % MOD;
	}
	ll ans = 0;
	for(ll i = 0; i < n; i++) {
		string s; cin >> s;
		v.push_back(s);
	}
	sort(v.begin(), v.end(), [&](string &a, string &b) -> bool {
		return a.size() > b.size();
	});
	for(auto s: v) {
		vector<ll> freq(26);
		for(auto c: s) {
			freq[c - 'a']++;
		}
		ll hash = 0;
		for(ll j = s.size() - 1; j >= 0; j--) {
			if(!f.count({hash, s.size() - 1 - j})) {
				f[{hash, s.size() - 1 - j}] = vector<ll>(26);
			}
			auto now = &f[{hash, s.size() - 1 - j}];
			for(ll k = 0; k < 26; k++) {
				if(freq[k]) ((*now)[k])++;
			}
			if(j) {
				freq[s[j] - 'a']--;
				hash = (hash + (ll)(s[j]) * (pwr[s.size() - 1 - j])) % MOD;
			}
		}
		auto val = f[{hash, s.size() - 1}];
		ll match = s[0] - 'a';
		ans += (val[match] - 1);
	}
	cout << ans << endl;
	return 0;
}

