using ull = unsigned long long;
const static int MAX_N = 200000;
int first[MAX_N][26];

int main(){
    unsigned N;
    scanf("%u\n", &N);
    pair<string, pair<char, unsigned> > word[N];
    unsigned sz[N];
    memset(first, -1, sizeof first);
    for (unsigned i = 0; i < N; i++)
    {
        cin >> word[i].first;
        sz[i] = word[i].first.size();
        reverse(word[i].first.begin(), word[i].first.end());
        for (unsigned j = 0; j < sz[i]; j++){
            first[i][word[i].first[j] - 'a'] = j;
        }
        word[i].second.second = i;
        word[i].second.first = word[i].first[sz[i]-1];
        word[i].first.pop_back();
    }
    sort(word, word + N);
    ull answer = 0;
    for (unsigned i = 0; i < N-1; i++){
        unsigned j = i+1;
        while(j < N && sz[word[j].second.second] == sz[word[i].second.second]) j++;
        while(j < N && word[j].first.substr(0, sz[word[i].second.second]-1) == word[i].first){
            if(first[word[j].second.second][word[i].second.first - 'a'] + 1 >= sz[word[i].second.second]) answer++;
            j++;
        }
    }
    printf("%llu\n", answer);
	return 0;
}

