	ll N;
	cin>>N;
	vector<string> a(N);
	rep(i,N){
		cin>>a[i];
		reverse(all(a[i]));
	}

/*
	ll N=2;
	vector<string> a(N);
	rep(i,N){
		string t(1e6,'a');
		if(i==0)t+='b';
		a[i]=t;
	}
*/

	sort(a.begin(), a.end(), [](const string &x, const string &y) {
		return x.size() > y.size();
	});

	vector<vector<ll>> pos(N,vector<ll>(26,-INF));
	rep(i,N){
		rep(j,a[i].size())chmax(pos[i][a[i][j]-'a'],j);
	}

	Trie< 26, 'a' > trie;
	rep(i,N){
		if(a[i].size()==(size_t)1)continue;
		string t=a[i].substr(0,a[i].size()-1);
		trie.add(t);
	}

	ll ans=0;
	rep(i,N){
		if(a[i].size()==(size_t)1)continue;
		//index = trie木に追加した単語のindex
		auto update = [&](ll index){
			debug(i,index);
			if(index==i)return;
			ll x=a[index].back()-'a';
			if(pos[i][x]>=(ll)(a[index].size())-1)ans++;
		};
		//Sのi文字目から一致する単語それぞれに対して関数 update が呼ばれる
		debug(a[i]);
		trie.query(a[i], update, 0, 0);
	}
	debug(ans);

	vector<ll> c(26,0);
	rep(i,N){
		if(a[i].size()!=(size_t)1)continue;
		c[a[i][0]-'a']++;
	}
	rep(i,N){
		if(a[i].size()==(size_t)1)continue;
		vector<ll> t(26,false);
		rep(j,a[i].size())t[a[i][j]-'a']=true;
		rep(j,26){
			if(t[j])ans+=c[j];
		}
	}
	p(ans);
}

