struct RollingHash {
    static const ll b1 = 1007, b2 = 2009;
    static const ll mod1 = 1000000007, mod2 = 1000000009;
    vll h1, h2, p1, p2;

    RollingHash(const string& s) {
        ll n = s.size();
        h1.assign(n + 1, 0);
        h2.assign(n + 1, 0);
        p1.assign(n + 1, 1);
        p2.assign(n + 1, 1);
        for (int i = 0; i < n; ++i) {
            h1[i + 1] = (h1[i] * b1 + s[i]) % mod1;
            h2[i + 1] = (h2[i] * b2 + s[i]) % mod2;
            p1[i + 1] = (p1[i] * b1) % mod1;
            p2[i + 1] = (p2[i] * b2) % mod2;
        }
    }

    void add(char c, ll i) {
        h1[i + 1] = (h1[i] * b1 + c) % mod1;
        h2[i + 1] = (h2[i] * b2 + c) % mod2;
        p1[i + 1] = (p1[i] * b1) % mod1;
        p2[i + 1] = (p2[i] * b2) % mod2;
    }

    inline pll get(ll l, ll r) const {
        ll res1 = h1[r] - h1[l] * p1[r-l] % mod1;
        if (res1 < 0) res1 += mod1;
        ll res2 = h2[r] - h2[l] * p2[r-l] % mod2;
        if (res2 < 0) res2 += mod2;
        return make_pair(res1, res2);
    }

    inline pll get() const {
        int n = h1.size();
        return get(0, n - 1);
    }
};

typedef pair<ll, string> pls;
