int cntc[26][1000010];
int x[26];
void add(node* t, string p){
	node* t0=t;
	for(int i=0; i<p.size(); i++){
		if(!t0->nxt[p[i]-'a']){
			t0->nxt[p[i]-'a']=new node(m++);
		}
		t0=t0->nxt[p[i]-'a'];
        for(int j=0; j<26; j++){
            if(x[j]==i){
                cntc[j][t0->num]++;
            }
        }
	}
    cnt[t0->num]++;
}
ll cnts[1000010];
ll dp[26][1000010];
ll ans;
void dfs(node* t){
	if(!t) return;
    for(int l=0; l<26; l++){
        dp[l][t->num]+=cntc[l][t->num];
    }
	for(int j=0; j<26; j++){
        if(!t->nxt[j]) continue;
        dfs(t->nxt[j]);
        cnts[t->num]+=cnts[t->nxt[j]->num];
        for(int l=0; l<26; l++){
            dp[l][t->num]+=dp[l][t->nxt[j]->num];
        }
    }
    for(int j=0; j<26; j++){
        if(!t->nxt[j]) continue;
        for(int l=0; l<26; l++){
            if(!t->nxt[l] || l==j) continue;
            ans+=dp[l][t->nxt[j]->num]*cnt[t->nxt[l]->num];
        }
    }
    ans+=cnts[t->num]*cnt[t->num];
    cnts[t->num]+=cnt[t->num];
}
