template<class T>
struct RollingHash{
	int Base=283;
	const int MOD1=1e9+7,MOD2=1e9+9;
	vector<int>hash1,hash2,power1,power2;
	RollingHash(T s){
		int sz=s.size();
		hash1.resize(sz+1,0);hash2.resize(sz+1,0);
		power1.resize(sz+1,1);power2.resize(sz+1,1);
		rep(i,sz){
			hash1[i+1]=(hash1[i]*Base+s[i])%MOD1;
			hash2[i+1]=(hash2[i]*Base+s[i])%MOD2;
			power1[i+1]=power1[i]*Base%MOD1;
			power2[i+1]=power2[i]*Base%MOD2;
		}
	}
	P get(int l,int r){
		return P((hash1[r]-hash1[l]*power1[r-l]+MOD1)%MOD1,(hash2[r]-hash2[l]*power2[r-l]+MOD2)%MOD2);
	}
	int lcp(int x,int y){
		int len=min(hash1.size()-1-y,hash1.size()-1-x);
		int ok=0,ng=len+1;
		while(ng-ok>1){
			int mid=(ok+ng)/2;
			if(get(x,x+mid)==get(y,y+mid))ok=mid;
			else ng=mid;
		}
		return ok;
	}
};

