class node {
public:
	int cnt[maxl];
	node *child[maxl];

	node() {
		for(int i=0;i<26;i++) {
			cnt[i] = 0;
			child[i] = NULL;
		}
	}

	void insert_word(int d) {
		if(d == sz(curr)) return;

		int ind = int(curr[d] - 'a');

		if(child[ind] == NULL) {
			child[ind] = new node();
		}

		child[ind]->insert_word(d + 1);

		if(!occured[ind]) {
			occured[ind] = true;
			cnt[ind]++;
		}
	}

	void dfs() {
		for(int i=0;i<26;i++) {
			if(child[i] == NULL) continue;
			child[i]->dfs();

			for(int j=0;j<26;j++) {
				cnt[j] += child[i]->cnt[j];
			}
		}
	}

	int query(int letter, int d) {
		if(d == sz(curr) - 1) return cnt[letter];

		int ind = int(curr[d] - 'a');
		return child[ind]->query(letter, d + 1);
	}
};

