struct Trie{
    Trie* child[26];
    bool end;
    int num[26];
    int wordEnd;
    int numContain;
};
Trie* getNew(){
    Trie* x = new Trie;
    for(int i=0;i<26;i++)
        x->child[i] = nullptr;
    x->end = false;
    for(int i=0;i<26;i++)
        x->num[i] = 0;
    x->wordEnd = 0;
    x->numContain = 0;
    return x;
}
void insert(Trie *head, string s){
    Trie *curr = head;
    for(int i=0;i<s.length();i++){
        if(curr->child[s[i]-'a']==nullptr)
            curr->child[s[i]-'a'] = getNew();
        curr = curr->child[s[i]-'a'];
        curr->numContain++;
    }
    curr->num[s[s.length()-1]-'a']++;
    curr->wordEnd++;
    curr->end = true;
}
void prop(Trie *head,int c){
    Trie *curr = head;
    for(int i=0;i<26;i++){
        if(curr->child[i]!=nullptr){
            prop(curr->child[i],i);
            for(int j=0;j<26;j++)
                curr->num[j]+=(curr->child[i])->num[j];
        }
    }
    if(c!=-1)
        curr->num[c]= curr->numContain;
}
int search(Trie *head, string s){
    Trie *curr = head;
    for(int i=0;i<s.length()-1;i++){
        if(curr->child[s[i]-'a']==nullptr){
            return 0;
        }
        curr = curr->child[s[i]-'a'];

    }
    int ans = 0;
    for(int i=0;i<26;i++){
        if(curr->child[i]!=nullptr)
            ans+=(curr->child[i])->num[s[s.length()-1]-'a'];
    }
    return ans;

}
