template <typename F>
constexpr decltype(auto) fix(F&& f) {
	return[f = std::forward<F>(f)](auto&&... args) {
		return f(f, std::forward<decltype(args)>(args)...);
	};
}

struct Node {
	int count[26] = {};
	std::array<std::unique_ptr<Node>, 26> children = {};
};

int main() {
	int n;
	std::cin >> n;

	std::array<int, 26> one = {};
	std::array<std::unique_ptr<Node>, 26> roots = {};

	std::int64_t ans = 0;

	std::vector<std::string> input(n);
	for (auto&& s : input) {
		std::cin >> s;

		if (s.size() == 1) {
			++one[s[0] - 'a'];
			continue;
		}

		std::array<int, 26> count = {};
		for (auto&& c : s)
			++count[c - 'a'];

		for (int j = 0; j < 26; ++j)
			if (count[j] != 0)
				++one[j];

		int depth = 0;
		fix([&](auto&& f, std::unique_ptr<Node>& ptr) -> void {
			if (ptr == nullptr)
				ptr = std::make_unique<Node>();

			if (depth + 1 == s.size())
				++ptr->count[s[0] - 'a'];
			else {
				--count[*(s.rbegin() + depth) - 'a'];
				for (int j = 0; j < 26; ++j)
					if (count[j] != 0)
						++ptr->count[j];

				++depth;
				f(f, ptr->children[*(s.rbegin() + depth) - 'a']);
			}
		})(roots[s.back() - 'a']);
	}

	for (auto&& s : input) {
		if (s.size() == 1) {
			ans += one[s[0] - 'a'] - 1;
			continue;
		}

		int depth = 0;
		fix([&](auto&& f, const std::unique_ptr<Node>& ptr) -> void {
			if (ptr == nullptr)
				exit(1);

			if (depth + 2 == s.size())
				ans += ptr->count[s[0] - 'a'] - 1;
			else {
				++depth;
				f(f, ptr->children[*(s.rbegin() + depth) - 'a']);
			}
		})(roots[s.back() - 'a']);
	}

	std::cout << ans << std::endl;
}

