const int sz = 1e6+5;

int nk, csub[sz], trie[26][sz], dp[26][sz];

int fnc(int ch, int u) {
   int &w = dp[ch][u];
   if(w < 0) {
      w = 0;
      for(int i=0; i<26; i++) {
         int v = trie[i][u];
         if(v < 0) continue;
         if(i == ch) w += csub[v];
         else w += fnc(ch, v);
      }
   }
   return w;
}

void tsc(int x) {
   for(int i=0; i<26; i++) {
      int y = trie[i][x];
      if(y < 0) continue;
      tsc(y);
      csub[x] += csub[y];
   }
}

