struct no {
    map<char, int> nxt;
    map<char, int> f;

    int next(char c){
        if(nxt.find(c) == nxt.end())
            return -1;
        return nxt[c];
    }
};

vector<no> trie;

inline int create(int u, char c){
    if(trie[u].next(c) == -1){
        trie[u].nxt[c] = trie.size();
        trie.push_back(no()); 
    }
    return trie[u].next(c);
}

inline void add(string s){ // adds string s to trie
     int u = root; 
     map<char, int> freq;
     for(char c: s)
         freq[c]++;
     for(auto it: freq)
        trie[u].f[it.fst] += (it.snd > 0);
     for(char c: s){
        u = create(u, c);
        freq[c]--;
        if(freq[c] == 0)
            freq.erase(c);
        for(auto it: freq)
            trie[u].f[it.fst] += (it.snd > 0);
     }
}

inline void init(){
    trie.clear();
    trie.push_back(no());
    root = 0;
}


