template<class Type>
Type solve(Type res = Type()){
    int N; cin >> N;
    vector<string> S(N); for(auto& in:S) cin >> in;

    map<char,int> one_alpha;
    map<ull,map<pair<char,char>,int>> mp;

    for(int i = 0; i < N;i++){
        if(S[i].length() == 1){
            one_alpha[S[i][0]]++;
        }else{
            // add
            RH rh; rh.init(S[i]);
            char a = S[i][0],b = S[i][1];
            mp[rh.h(2,(int)S[i].length())][make_pair(a,b)]++;
        }
    }
    for(int i = 0; i < N;i++){
        if(S[i].length() == 1){
            res += one_alpha[S[i][0]];
        }else{
            {
                set<char> alpha;
                for(auto& c:S[i]) alpha.emplace(c);

                int T = 0;
                for(auto& c:alpha){
                    T += one_alpha[c];
                }
                res += T;

            }
            {
                RH rh; rh.init(S[i]);
                // search
                multiset<char> st;
                for(int j = 0; j < (int)S[i].length();j++){
                    st.emplace(S[i][j]);
                }

                int T = 0;
                for(int j = (int)S[i].length(); j >= 2; j--){
                    st.erase(st.lower_bound(S[i][j-1]));
                    ull h = rh.h(j,(int)S[i].length());

                    for(auto& p:mp[h]){
                        pair<char,char> ab;
                        int num;
                        tie(ab,num) = p;

                        if(ab.second == S[i][j-1]){
                            if(st.find(ab.first) != st.end()){
                                T += num;
                            }
                        }
                    }
                }
                res += T;

            }
        }
    }
    res = res - N;

    return res;
}

