		an[s[i][0] - 'a']++;

		repb(j, 2, s[i].length())
		{
			an[s[i][j - 1] - 'a']++;
			lint h = rh.h(j, s[i].length()).n;

			rep(k, 26)
			{
				if (an[k] == 0)
					continue;
				ans += m[make_pair(k, h)];
			}
		}

		m[make_pair(s[i][0] - 'a', rh.h(1, s[i].length()).n)]++;
	}

	cout << ans << endl;

	return 0;
}

