struct trie{
    struct node;
    using np=node*;
    struct node{
        int sz=0,sz2=0;
        np ch[26]={};
    };
    np root=new node();
    void add(string s){
        np t=root;
        t->sz++;
        rep(i,s.size()){
            if(!t->ch[s[i]-'a'])t->ch[s[i]-'a']=new node();
            t=t->ch[s[i]-'a'];
            t->sz++;
        }
        t->sz2=1;
    }
    void add2(string s){
        unordered_map<char,lint>m;
        rep(i,s.size())m[s[i]-'a']++;
        bitset<26>b;
        rep(i,26)b[i]=m[i];
        np t=root;
        rep(i,s.size()){
            for(int j=b._Find_first();j<26;j=b._Find_next(j)){
                if(j==s[i]-'a')continue;
                if(!t->ch[j])t->ch[j]=new node();
                t->ch[j]->sz2++;
            }
            if(!t->ch[s[i]-'a'])t->ch[s[i]-'a']=new node();
            t=t->ch[s[i]-'a'];
            t->sz2++;
            m[s[i]-'a']--;
            if(m[s[i]-'a']==0)b[i]=0;
        }
    }
    lint get(string s){
        np t=root;
        rep(i,s.size()){
            if(!t->ch[s[i]-'a'])t->ch[s[i]-'a']=new node();
            t=t->ch[s[i]-'a'];
        }
        return t->sz2;
    }
};

