int pow[2][1 + nmax];

void precompute() {
  pow[0][0] = pow[1][0] = 1;
  for(int i = 1;i <= nmax; i++) {
    pow[0][i] = 1LL * pow[0][i - 1] * base % modulo;
    pow[1][i] = 1LL * pow[1][i - 1] * base % modulo2;
  }
}

class Hash {
public:
  int l;
  int number, number2;
  Hash(char ch = -1) {
    if(ch == -1) {
      l = number = number2 = 0;
    } else {
      l = 1;
      number = number2 = ch - 'a';
    }
  }

  Hash operator + (Hash a) const {
    Hash result;
    result.l = l + a.l;
    result.number = (1LL * number * pow[0][a.l] + a.number) % modulo;
    result.number2 = (1LL * number2 * pow[1][a.l] + a.number2) % modulo2;
    return result;
  }
  bool operator == (Hash a) const {
    return l == a.l && number == a.number && number2 == a.number2;
  }
  bool operator < (Hash a) const {
    if(l != a.l)
      return l < a.l;
    else if(number != a.number)
      return number < a.number;
    else
      return number2 < a.number2;
  }
};
