template<int sigma, int a>
struct Trie{
private:
    template<int sigma>
    struct Node{
        int chi[sigma];
        int siz = 0;
        Node(){
            memset(chi, -1, sizeof(chi));
        }
    };
    vector<Node<sigma>> nodes;
public:
    Trie(){
        nodes.push_back(Node<sigma>());
    }
    void add_node(int n, int c){
        nodes[n].chi[c] = nodes.size();
        nodes.push_back(Node<sigma>());
    }
    void add(string s){
        int n = 0;
        nodes[n].siz++;
        for(int i=0; i<s.size(); i++){
            if(nodes[n].chi[s[i]-a] == -1) add_node(n, s[i]-a);
            n = nodes[n].chi[s[i]-a];
            nodes[n].siz++;
        }
    }
    int count_prefix(string s){
        int n = 0;
        for(int i=0; i<s.size(); i++){
            if(nodes[n].chi[s[i]-a] == -1) return 0;
            n = nodes[n].chi[s[i]-a];
        }
        return nodes[n].siz;
    }
};

