            uli h = hashes[sz(s[i]) - j - 1]; // j+1
            for (auto v : st) {
                if (cnt[v].count(h) > 0) {
                    res += cnt[v][h];
                }
            }
        }
        cnt[s[i][0] - 'a'][hashes[sz(s[i]) - 1]]++;
    }
    cout << res << endl;

    return 0;
}

