void add(string& s, int ind, node* cur, node* par = 0) {
	if (ind == s.size()) {
		par->nds.push_back(s.back() - 'a');
	}
	else {
		if (cur->lt[s[ind] - 'a']) {
			add(s, ind + 1, cur->lt[s[ind] - 'a'], cur);
		}
		else {
			cur->lt[s[ind] - 'a'] = new node();
			add(s, ind + 1, cur->lt[s[ind] - 'a'], cur);
		}
	}
}

void add2(string& s, int ind, node* cur) {
	if (cur->cnt.size() == 0) {
		cur->cnt.resize(26);
	}
	cur->cnt[s[ind] - 'a']++;
	if (ind == s.size() - 1) {
		return;
	}
	else {
		if (cur->lt[s[ind] - 'a']) {
			add2(s, ind + 1, cur->lt[s[ind] - 'a']);
		}
		else {
			cur->lt[s[ind] - 'a'] = new node();
			add2(s, ind + 1, cur->lt[s[ind] - 'a']);
		}
	}
}

void bfs(node* cur, node* par = 0) {
	for (int i = 0; i < 26; i++) {
		if (cur->lt[i]) {
			bfs(cur->lt[i], cur);
		}
	}

	if (par != 0) {
		if (cur->cnt.size() != 26) return;
		for (int i = 0; i < 26; i++) {
			par->cnt[i] += cur->cnt[i];
		}
	}
}

