	for (auto c : cur->nds) {
		ret += cur->cnt[c] - 1;
	}
	if (ret == 1) {
		cout << "";
	}
	for (int i = 0; i < 26; i++) {
		if (cur->lt[i]) ret += ans(cur->lt[i]);
	}

	return ret;
}

