Int g(int d, int f, int t)
{
    Int res = 0;
    VInt v;
    while(f < t && L[f] == d)
    {
        v.push_back(V[f].second - 'a');
        ++f;
    }
    int i, j;
    FOR(i, f, t)
    for(int c : v)
        if(C[i][c] > 0)
            ++res;

    FOR(i, f + 1, t + 1)
        if(i == t || V[i].first[d] != V[f].first[d])
        {
            int t = V[f].first[d] - 'a';
            FOR(j, f, i) --C[j][t];
            res += g(d + 1, f, i);
            FOR(j, f, i) ++C[j][t];
            f = i;
        }

    return res;
}

