struct Trie {

  Trie() : nodes(1, vi(26, -1)), ends(1, 0),
	   chars(1, -1),
	   parents(1, -1),
	   times(1, 0) {
  }

  void add(const string &S) {
    i64 cur = 0;
    for(auto c: S) {
      i64 &next = nodes[cur][c - 'a'];
      if(next == -1) {
	next = sz(nodes);

	nodes.pb(vi(26, -1));
	ends.pb(0);
	chars.pb(c - 'a');

	parents.pb(cur);
	times.pb(1);
      }
      else {
	times[next]++;
      }
      cur = next;
    }
    ends[cur] = 1;
  }

  i64 solve() {
    i64 N = sz(nodes), i, j;

    // build count acche
    vvi counts(N, vi(26, 0));
    REP(0, N, i) {
      i64 cur = N - i - 1;
      if(cur == 0)
	continue;

      counts[parents[cur]][chars[cur]] += times[cur];
      REP(0, 26, j) {
	counts[parents[cur]][j] += counts[cur][j];
      }
    }

    i64 ans = 0;
    REP(0, N, i) {
      i64 cur = N - i - 1;
      if(cur == 0)
	continue;

      if(ends[cur] == 1) {
	ans += counts[parents[cur]][chars[cur]] - 1;
      }
    }
    return ans;    
  }

  vvi nodes;
  vi ends;
  vector<char> chars;
  vi parents;
  vi times;
};

