ll ans;
int n,tot,cnt[N][28];
bool ok[N][28];
char s[N];
struct Trie{
	int ch[26],ed;
}trie[N];
void Insert(char *s){
	int len=strlen(s+1);
	int u=1;
	for(int i=1;i<=len;++i){
		for(int c=0;c<26;++c){
			ok[i][c]=ok[i-1][c];
		}
		ok[i][s[i]-'a']=true;
	}
	for(int i=len;i>=1;--i){
		int c=s[i]-'a';
		if(!trie[u].ch[c])trie[u].ch[c]=++tot;
		for(int j=0;j<26;++j){
			if(ok[i][j])++cnt[u][j];
		}
		u=trie[u].ch[c];
	}
	++trie[u].ed;
}
void dfs(int u){
	int qwq[26];
	for(int i=0;i<26;++i)qwq[i]=0;
	for(int c=0;c<26;++c){
		int v=trie[u].ch[c];
		if(!v)continue;
		qwq[c]+=trie[v].ed;
		dfs(v);
	}
	for(int i=0;i<26;++i){
		ans+=1LL*qwq[i]*cnt[u][i];
	}
}
