struct Trie {
    vector<array<int, 26> > trie_nodes = {{}};
    vector<int> sz = {0};
    vector<array<int, 26> > cnt = {{}};

    void push(string s){
        VI last(26, -1);
        REP(i,s.length()) last[s[i] - 'a'] = i;
        int node = 0;
        sz[node]++;
        REP(j,26) if (last[j] >= 0) cnt[node][j]++;
        REP(i,s.length()){
            char c = s[i];
            int x = c - 'a';
            if (!trie_nodes[node][x]){
                trie_nodes[node][x] = trie_nodes.size();
                trie_nodes.push_back({});
                sz.push_back(0);
                cnt.push_back({});
            }
            node = trie_nodes[node][x];
            sz[node]++;
            REP(j,26) if (last[j] > i) cnt[node][j]++;    
        }
    }

    int calc(string s){
        int node = 0;
        REP(i,s.length()-1){
            char c = s[i];
            int x = c - 'a';
            if (!trie_nodes[node][x]) return 0;
            node = trie_nodes[node][x];
        }
        return cnt[node][s.back() - 'a'];
    }
};

