const ull Base = 137;
const int N = 5e5 + 10;
//const int N = 100 + 10;
unordered_map<ull, int> t[N][26];
int n, len[N], id[N];
string s[N];
int cur[26];
bool cmp(int x, int y)
{
	return len[x] > len[y];
}
int main()
{
	std::ios::sync_with_stdio(false);
	cin >> n;
	for (int i = 1; i <= n; ++i)
	{
		cin >> s[i];
		len[i] = s[i].length();
	}
	iota(id + 1, id + 1 + n, 1);
	sort(id + 1, id + 1 + n, cmp);
	ll ans = 0;
	int mx = 0;
	for (int i = 1; i <= n; ++i)
	{
		int x = id[i];
		while (mx > len[x] - 1)
		{
			for (int c = 0; c < 26; ++c)
				t[mx][c].clear();
			--mx;
		}
		ull val = 0;
		for (int j = len[x] - 1; j >= 1; --j)
			val = val * Base + s[x][j] - 'a' + 1, ++cur[s[x][j] - 'a'];
		++cur[s[x][0] - 'a'];
		if (len[x] <= 500005)
			ans += t[len[x] - 1][s[x][0] - 'a'][val];
		val = 0;
		int lim = i == n ? -1 : len[id[i + 1]] - 1;
		if (lim >= 0)
			for (int c = 0; c < 26; ++c)
				if (cur[c])
					++t[0][c][val];
		for (int j = len[x] - 1, p = 1; j >= 0; --j, ++p)
		{
			val = val * Base + s[x][j] - 'a' + 1;
			cur[s[x][j] - 'a']--;
			if (p > 500005 || p > lim)
				continue;
			for (int c = 0; c < 26; ++c)
				if (cur[c])
					++t[p][c][val], mx = max(mx, p);
		}
	}
	cout << ans << endl;
	return 0;
}

