struct Node {
    vector<int> next;
    int is_term;
    Node() {
        next.resize(26);
        next.assign(26, -1);
        is_term = 0;
    }
};
const int N = 1e6 + 3e5;
//const int N = 13;
vector<Node> trie(N);
int sz = 0;
void add(string s) {
    int v = 0;
    for (char c2 : s) {
        char c = c2 - 'a';
        if (trie[v].next[c] == -1) {
            trie[v].next[c] = ++sz;
        }
        v = trie[v].next[c];
    }
    ++trie[v].is_term;
}
void solve() {
    int n;
    cin >> n;
    vector<string>s(n);
    cin >> s;
    rep(i, 0, n) {
        reverse(all(s[i]));
        add(s[i]);
    }
    int ans = 0;
    rep(i, 0, n) {
        int v = 0;
        vi cnt(26);
        rep(j, 0, s[i].size()) ++cnt[s[i][j] - 'a'];
        rep(j, 0, s[i].size()) {
            rep(k, 0, 26) {
                if (trie[v].next[k] != -1 && cnt[k])
                ans += trie[trie[v].next[k]].is_term;
            }
            v = trie[v].next[s[i][j] - 'a'];
            --cnt[s[i][j] - 'a'];
        }
    }
    put(ans - n);
}


