int vcnt;
inline void ins(const string &s) {
	int root=0;stack<int> S;
	for(int i=0;i<s.length();i++) {
		int tmp=s[i]-'a';S.push(root);
		if(!trie[root].ch[tmp]) trie[root].ch[tmp]=++vcnt;
		root=trie[root].ch[tmp];trie[root].siz++;
	}
	while(!S.empty()) {
		int temp=S.top();S.pop();
		for(int i=0;i<26;i++) {
			trie[temp].cnt[i]=0;
			for(int j=0;j<26;j++) {
				if(trie[temp].ch[j]) {
					if(i==j) trie[temp].cnt[i]+=trie[trie[temp].ch[j]].siz;
					else trie[temp].cnt[i]+=trie[trie[temp].ch[j]].cnt[i];
				}
			}
		}
	}
}
ll ans=0;
void calc(const string &s) {
	int root=0;
	if(s.length()==1) ans+=trie[root].cnt[s[0]-'a']-1;
	else 
	for(int i=0;i<s.length();i++) {
		root=trie[root].ch[s[i]-'a'];
		if(i==s.length()-2) ans+=trie[root].cnt[s[i+1]-'a']-1;
	}
}
