using namespace std;

struct MyTrie {
    MyTrie* next[26];
    int leaf;
    MyTrie() {
        leaf = 0;
        for (int i = 0; i < 26; i++) {
            next[i] = nullptr;
        }
    }
    ~MyTrie() {
        for (int i = 0; i < 26; i++) {
            if (next[i]) {
                delete next[i];
            }
        }
    }
};

void insert_word(struct MyTrie* root, const string& s, int pos) {
    if (pos == s.size()) {
        root->leaf += 1;
        return;
    }
    char c = s[pos];
    if (root->next[c - 'a'] == nullptr) {
        root->next[c - 'a'] = new MyTrie();
    }
    insert_word(root->next[c - 'a'], s, pos + 1);
}

struct MyTrie* find_word(struct MyTrie* root, const string& s, int pos) {
    if (s.size() == pos) {
        return root;
    }
    char c = s[pos];
    if (root->next[c - 'a'] == nullptr) {
        return nullptr;
    }
    return find_word(root->next[c - 'a'], s, pos + 1);
}

int main() {
    int n;
    cin >> n;
    vector<string> vs;
    string s;
    struct MyTrie* root = new MyTrie();
    for (int i = 0; i < n; i++) {
        cin >> s;
        reverse(s.begin(), s.end());
        vs.push_back(s);

        insert_word(root, s, 0);
    }
    long long int res = 0;
    for (int i = 0; i < n; i++) {
        vector<int> v(26, 0);
        for (auto ss : vs[i]) {
            v[ss - 'a']++;
        }

        struct MyTrie* base = root;
        for (int k = 0; k < 26; k++) {
            if (base->next[k] != nullptr && v[k] > 0) {
                res += base->next[k]->leaf;
            }
        }
        for (int j = 0; j < vs[i].size(); j++) {
            v[vs[i][j] - 'a']--;
            base = base->next[vs[i][j] - 'a'];
            if (base == nullptr) break;
            for (int k = 0; k < 26; k++) {
                if (base->next[k] != nullptr && v[k] > 0) {
                    res += base->next[k]->leaf;
                }
            }
        }
    }
    cout << res - n << endl;
}

