constexpr char newl = '\n';

template<const int CHAR_NUM = 26, const char FIRST_CHAR = 'a', const int NONE = -1>
struct Trie {
    struct Node {
        bool word_exists;
        int cnt[CHAR_NUM];
        int idxs[CHAR_NUM]; // idxs[c - FIRST_CHAR]: 次の文字がcであるNodeの場所(treeのindex)
        Node() : word_exists(false) {
            fill(idxs, idxs + CHAR_NUM, NONE);
            fill(cnt, cnt + CHAR_NUM, 0);
        };
    };

    vector<Node> tree;

    Trie() {
        tree.emplace_back();
    }

    void insert(string& s) {
        char last_char = s.back();
        s.pop_back();

        int cur = 0;
        for (char c : s) {
            if (tree[cur].idxs[c - FIRST_CHAR] == NONE) {
                tree[cur].idxs[c - FIRST_CHAR] = tree.size();
                tree.emplace_back();
            }
            cur = tree[cur].idxs[c - FIRST_CHAR];
        }
        tree[cur].word_exists = true;
        tree[cur].cnt[last_char - FIRST_CHAR]++;
    }

    bool find(const string& s) {
        int cur = 0;
        for (char c : s) {
            if (tree[cur].idxs[c - FIRST_CHAR] == NONE) {
                return false;
            }
            cur = tree[cur].idxs[c - FIRST_CHAR];
        }
        return tree[cur].word_exists;
    }

    int count(const string& s) {
        int res = 0;
        int cur = 0;
        array<int, CHAR_NUM> counter{};
        for (int i = 0; i < CHAR_NUM; i++) {
            counter[i] = tree[cur].cnt[i];
        }
        bool f = false;
        for (char c : s) {
            res += counter[c - FIRST_CHAR];
            counter[c - FIRST_CHAR] = 0;

            if (tree[cur].idxs[c - FIRST_CHAR] == NONE) {
                f = true;
            }
            if (f) continue;
            cur = tree[cur].idxs[c - FIRST_CHAR];

            for (int i = 0; i < CHAR_NUM; i++) {
                counter[i] += tree[cur].cnt[i];
            }
        }
        return res;
    }
};

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;

    vector<string> v(n);
    for (int i = 0; i < n; i++) {
        cin >> v[i];
        reverse(v[i].begin(), v[i].end());
    }
    sort(v.begin(), v.end(), [&](const string& s1, const string& s2) {
        return s1.size() < s2.size();
    });

    ll ans = 0;
    Trie<> t;
    for (string& s : v) {
        ans += t.count(s);
        t.insert(s);
    }
    cout << ans << newl;

    return 0;
}

