void Stworz(int n, vector<string> a)
{
    int p = 1;
    while (p < n)
        p *= 2;
    l = p;
    size = 2 * p - 1;
    vector< vector<int> > puste(size + 1);
    for (int i = 0; i < 26; ++i)
        T[i] = puste;
    for (int i = 0; i < 26; ++i)
    {
        for (int j = 0; j < n; ++j)
        {
            for (int k = a[j].size() - 1; k >= 0; --k)
            {
                if (a[j][k] == (char) (i + 'a'))
                {
                    T[i][j + l].push_back(k);
                    break;
                }
            }
        }
    }
    for (int i = 0; i < 26; ++i)
    {
        for (int j = l - 1; j >= 1; --j)
        {
            for (int k = 0; k < T[i][2 * j].size(); ++k)
                T[i][j].push_back(T[i][2 * j][k]);
            for (int k = 0; k < T[i][2 * j + 1].size(); ++k)
                T[i][j].push_back(T[i][2 * j + 1][k]);
            sort(T[i][j].begin(), T[i][j].end());
        }
    }
}

int Ile(vector<int>& a, int k)
{
    int l = 0, p = a.size() - 1, s, r = -1;
    while (l <= p)
    {
        s = (l + p) / 2;
        if (a[s] >= k)
        {
            r = s;
            p = s - 1;
        }
        else
            l = s + 1;
    }
    if (r == -1)
        return 0;
    return a.size() - r;
}

int Pyt(vector< vector<int> >& T, int a, int b, int k)
{
    a += l;
    b += l;
    int wyn = Ile(T[a], k);
    if (a != b)
        wyn += Ile(T[b], k);
    while (a / 2 != b / 2)
    {
        if (a % 2 == 0)
            wyn += Ile(T[a + 1], k);
        if (b % 2 == 1)
            wyn += Ile(T[b - 1], k);
        a /= 2;
        b /= 2;
    }
    return wyn;
}

