const int mxN = 2e5+5;

int N;
string S[mxN];
int rt[26][mxN];

struct node {
	int s, e, m;
	vector<int> v;
	node *l, *r;
	node(int s, int e, int* A): s(s), e(e), m((s+e)/2) {
		if (s == e) {
			v.push_back(A[s]);
		} else {
			l = new node(s,m,A), r = new node(m+1,e,A);
			for (int i = 0, j = 0; i < SZ(l->v) || j < SZ(r->v);) {
				if (i < SZ(l->v) && (j == SZ(r->v) || l->v[i] < r->v[j]))
					v.push_back(l->v[i++]);
				else
					v.push_back(r->v[j++]);
			}
		}
	}

	int query(int a, int b, int k) {
		if (a > b) return 0;
		if (s == a && e == b) {
			return v.end()-lower_bound(ALL(v),k);
		} else if (b <= m) return l->query(a,b,k);
		else if (a > m) return r->query(a,b,k);
		else return l->query(a,m,k) + r->query(m+1,b,k);
	}
} *root[26];

int main() {
    ios::sync_with_stdio(false); cin.tie(0); cout.tie(0);

    cin >> N;
    memset(rt,-1,sizeof rt);
    FOR(i,1,N){
		cin >> S[i];
		reverse(ALL(S[i]));
	}
	sort(S+1,S+1+N);

	FOR(i,1,N){
		RFOR(j,SZ(S[i])-1,0){
			if (rt[S[i][j]-'a'][i] == -1) {
				rt[S[i][j]-'a'][i] = j;
			}
		}
	}

	FOR(i,0,25) root[i] = new node(1,N,rt[i]);

	ll ans = 0;
	FOR(i,1,N){
		if (SZ(S[i]) == 1) {
			ans += root[S[i][0]-'a']->query(1,N,0)-1;
		} else {
			string R(S[i]), T(S[i]);
			R.pop_back();
			T.pop_back();
			T.back() += 1;
			auto x = lower_bound(S+1,S+1+N,R)-S;
			auto y = lower_bound(S+i,S+1+N,T)-S;
			//~ TRACE(S[i] _ R _ T _ x _ y);
			ans += root[S[i].back()-'a']->query(x,y-1,SZ(T)-1)-1;
		}
	}
	cout << ans << '\n';
}

