        if (root->ch[s[i] - 'a'] == 0) {

            root->ch[s[i] - 'a'] = new node();
            root->ch[s[i] - 'a']->par = root;
        }
        root = root->ch[s[i] - 'a'];
    }
    long long ans = root->with[s[0] - 'a'];
    if (root->ch[s[0] - 'a'] == NULL) {
        root->ch[s[0] - 'a'] = new node();
        root->ch[s[0] - 'a']->par = root;
    }
    root = root->ch[s[0] - 'a'];
    bool has[26];
    for (int i = 0; i < 26; i++) {
        has[i] = 0;
    }
    for (int i = 0; i < s.size(); i++) {
        has[s[i]-'a'] = true;
        root = root->par;
        for (int j = 0; j < 26; j++) {
            root->with[j] += has[j];
        }
