struct Trie {
  ll cnt[26];
  Trie *child[26];

  Trie()
  {
    rep( i, 26 ) {
      child[i] = nullptr;
      cnt[i] = 0;
    }
  }

  ~Trie() {
    rep( i, 26 ) if( child[i] != nullptr )
      delete child[i];
  }

  void addStr( const std::string &s, ll dep = 0 ) {
    if( dep )
      ++this->cnt[s[dep-1]-'a'];

    if( dep == s.size() ) {
      return;
    }

    if( this->child[s[dep]-'a'] == nullptr ) {
      this->child[s[dep]-'a'] = new Trie();
    }

    this->child[s[dep]-'a']->addStr( s, dep+1 );
  }

  void dfs() {
    rep( i, 26 ) if( this->child[i] != nullptr ) {
      this->child[i]->dfs();

      rep( j, 26 )
        this->cnt[j] += this->child[i]->cnt[j];
    }
  }

  ll traverse( const std::string &s, char ch, ll dep = 0 ) {
    if( dep == s.size() ) {
      return this->cnt[ch-'a'];
    }

    assert( this->child[s[dep]-'a'] != nullptr );

    return this->child[s[dep]-'a']->traverse( s, ch, dep+1 );
  }
};

