	for(int k=1;k<20;k++){
		for(int i=0;i<n;i++){
			int j = i+(1<<(k-1));
			if(j >= n)
				f[i][k] = -1;
			else
				f[i][k] = min(f[i][k-1],f[j][k-1]);
		}
	}


	vector<query> q;
