ll ans = 0;

struct Trie {
    bool cont;
    vector<Trie*> child;
    Trie() {
        cont = false;
        child.resize(26);
        REP(i, 26) child[i] = nullptr;
    }
    void Add(string& str, int idx) {
        if(idx == (int)str.size()) {
            cont = true;
            return;
        }
        int num = str[idx] - 'a';
        if(child[num] == nullptr) {
            child[num] = new Trie();
        }
        child[num]->Add(str, idx + 1);
    }
};

pair<vector<ll>, ll> dfs(Trie* node) {
    vector<ll> cnt(26, 0);
    ll sum = 0;
    vector<bool> ok(26, false);
    vector<ll> minus(26, 0);
    REP(i, 26) {
        if(node->child[i] == nullptr) continue;
        auto tmp = dfs(node->child[i]);
        tmp.first[i] = tmp.second;
        if((node->child[i])->cont) ok[i] = true;
        minus[i] = tmp.second;
        REP(j, 26) cnt[j] += tmp.first[j];
        sum += tmp.second;
    }
    REP(i, 26) {
        if(ok[i]) ans += cnt[i] - minus[i];
    }
    if(node->cont) ans += sum;
    if(node->cont) sum = 1;
    return {cnt, sum};
}

