char s[N];
int n, ch[N][26], C[N][26], D[N][26];
int sz;
int cnt[N], cur[26];

struct Trie{
	void init(){
		sz = 1;
		memset(ch[0], 0, sizeof(ch[0]));
		cnt[0] = 0;
	}
	int query(int len){
		rep(i, 0, 26)	cur[i] = 0;
		rep(i, 0, len){
			++cur[s[i]-'a'];
		}

		int ret = 0;

		int u = 0, c = 0;

		rep(i, 0, len){
			c = s[i] - 'a';

			rep(j, 0, 26){
				if(cur[j])	ret += D[u][j];
			}

			if(!ch[u][c])	break;

			u = ch[u][c];

			--cur[c];
		}

		u = 0;
		rep(i, 0, len - 1){
			c = s[i] - 'a';
			if(!ch[u][c]){
				return ret;
			}
			u = ch[u][c];
		}
		c = s[len-1] - 'a';
		return ret + C[u][c];
	}

	int ins(int len){
		int u = 0, c = 0;
		rep(i, 0, 26)	cur[i] = 0;
		rep(i, 0, len)	++cur[s[i]-'a'];
		rep(i, 0, len){
			c = s[i] - 'a';
			if(!ch[u][c]){
				memset(ch[sz], 0, sizeof(ch[sz]));
				cnt[sz] = 0;
				rep(j, 0, 26){
					C[sz][j] = D[sz][j] = 0;
				}
				ch[u][c] = sz++;
			}

			if(i == len - 1){
				++D[u][c];
			}
			rep(j, 0, 26){
				if(cur[j])	++C[u][j];
			}
			--cur[c];

			u = ch[u][c];
		}

		++cnt[u];

		return cnt[u] - 1;
	}
}tr;

