        st[i] = s.size();
        s += v[i];
    }
    RollingHash rh(s);
    hash_map<u64, u64, hash_u64> mp;
    ll ans = 0;
    vector<u64> mem(26);
    rep(i, 26) { mem[i] = (u64)(rh.mod1 + 1) * (u64)('a' + i); }
    rep(i, n) {
        int mask = 0;
        rep3(j, v[i].size() - 1, 0) {
            mask |= (1 << (v[i][j] - 'a'));
            ll now = rh.get(st[i], st[i] + j);
            if(cnt[j + 1]) ans += popcount(mp[now] & mask);
        }
        mp[rh.get(st[i], st[i] + v[i].size())]++;
        cnt[v[i].size()]++;
    }
    cout << ans << endl;
