struct vert{
    vector<ll> needed = vector<ll>(26);
    vector<ll> have = vector<ll>(26);
    vi nchar = vi(26,-1);
    ll ans = 0;
    ll contain = 0;
};

vector<vert> trie(1);

int ptr = 1;

void updvert(int vnum){
    FOR(i,26){
        if(trie[vnum].nchar[i] == -1) continue;
        vert &child = trie[trie[vnum].nchar[i]];
        trie[vnum].contain += child.contain;
        trie[vnum].ans += child.ans;
        FOR(j,26){
            if(i == j) trie[vnum].have[j] += child.contain;
            else trie[vnum].have[j] += child.have[j];
        }
    }
    FOR(i,26){
        trie[vnum].ans += trie[vnum].needed[i]*(trie[vnum].have[i]-1LL);
    }
//    cerr << vnum << " " << trie[vnum].ans << "\n";
}

void addstring(string a){
    int n = a.length();
    int cpos = 0;
    for(int i = n; i >= 1; i--){
        int ne = a[i-1]-'a';
        if(i == 1){
            trie[cpos].contain++;
            trie[cpos].needed[ne]++;
            trie[cpos].have[ne]++;
            continue;
        }
        if(trie[cpos].nchar[ne] == -1){
            trie.emplace_back();
            trie[cpos].nchar[ne] = ptr++;
//            cerr << ptr-1 << ": " << ne << "\n";
        }
        cpos = trie[cpos].nchar[ne];
    }
}

int main()
{
    ios_base::sync_with_stdio(0); cin.tie(0);
    int n; cin >> n;
    FOR(i,n){
        string a; cin >> a;
        addstring(a);
    }
    for(int i = ptr-1; i >= 0; i--) updvert(i);
    cout << trie[0].ans << "\n";
    return 0;
}

