void solve(const vector <int>& ids, int x) {
    if (ids.size() <= 1)
        return;
    memset(cnt, 0, sizeof cnt);
    for (int id : ids) {
        for (int j = 0; j < K; ++j) {
            if (pos[id][j] <= (int)s[id].size() - x) {
                ++cnt[j];
            }
        }
    }
    for (int id : ids) {
        if (x == (int)s[id].size()) {
            ans += cnt[s[id][(int)s[id].size() - x] - 'a'] - 1;
        }
    }
    vector <int> to_ids;
    for (int j = 0; j < K; ++j) {
        to_ids.clear();
        for (int id : ids) {
            if (x < (int)s[id].size() && (s[id][(int)s[id].size() - x] - 'a') == j) {
                to_ids.push_back(id);
            }
        }
        solve(to_ids, x + 1);
    }
}

