struct Node
{
    vector<int> A;
    vector<Node*> C;
    int count;
    Node():A(26,0),C(26,nullptr),count(0){}
    void insert(string &s, int pos, vector<int> &B)
    {
        if(pos<0)
            return;
        int z = s[pos]-'a';
        if(C[z]==nullptr)
            C[z]=new Node();
        C[z]->insert(s,pos-1,B);
        B[z]=1;
        for(int i=0; i<26; ++i)
            A[i]+=B[i];
        ++count;
    }
    int query(string &s, int pos)
    {
        if(pos<0)
            return count;
        int z = s[pos]-'a';
        if(pos==0)
            return A[z];
        if(C[z]==nullptr)
            return 0;
        else
            return C[z]->query(s,pos-1);

    }
};
void solve()
{
    int N;
