template <typename T>
struct trie{
	T init_value;
	struct node{
		vector<int> next;
		vector<int> v;
		int depth;
		node(int k,T iv,int d){
			next.resize(k,-1);
			v = iv;
			depth = d;
		}

		int link;
	};
	vector<node> _N;
	int n;
	trie(int k,T iv){
		init_value = iv;
		n = k;
		_N.push_back(node(n,init_value,0));
	}

	T add(string &s,int now = 0,int nowv=0){
		if(now==s.size())return init_value;
		int c = get(s[now]);
		if(_N[nowv].next[c]==-1){
			_N[nowv].next[c] = _N.size();
			_N.push_back(node(n,init_value,_N[nowv].depth+1));
		}
		int newv = _N[nowv].next[c];
		vector<int> V = init_value;
		V = add(s,now+1,newv);
		V[c]++;
		for(int i=0;i<26;i++){
			if(V[i]>0){
				_N[nowv].v[i]++;
			}
		}
		return V;

	}



	T get_value(string &S){
		T ret = init_value;;
		int now = 0;
		for(int i=0;i<S.size();i++){
			int c = get(S[i]);
			if(_N[now].next[c]!=-1){
				now = _N[now].next[c];
			}
			else{
				return ret;
			}
		}
		return _N[now].v;
	}

	int get(char c){
		return c-'a';
	}


};

