#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

const int MAX_LEN = 1e6 + 10, ALPHA = 26;

int N;
ll ans;

struct TNode {
    TNode *child[ALPHA], *parent;
    int siz, siz_with[ALPHA], val;
    bool isword;

    TNode() : parent(nullptr), siz(0), val(0), isword(false) {
        memset(child, 0, sizeof(child));
        siz = 0;
        memset(siz_with, 0, sizeof(siz_with));
    }

    void build() {
        for (int i = 0; i < ALPHA; i++) {
            if (child[i]) {
                child[i]->build();
                siz += child[i]->siz;
                for (int j = 0; j < ALPHA; j++) {
                    siz_with[j] += child[i]->val == j ? child[i]->siz : child[i]->siz_with[j];
                }
            }
        }
        siz += isword;
    }

    void solve() {
        if (isword) {
            ans += parent->siz_with[val] - 1;
        }
        for (int i = 0; i < ALPHA; i++) {
            if (child[i]) {
                child[i]->solve();
            }
        }
    }
} *root;

int main() {
    scanf("%d", &N);
    root = new TNode(); root->val = -1;
    for (int i = 1; i <= N; i++) {
        static char S[MAX_LEN]; scanf("%s", S + 1);
        int len = strlen(S + 1);
        TNode *x = root;
        for (int j = len; j; j--) {
            int c = S[j] - 'a';
            if (!x->child[c]) {
                (x->child[c] = new TNode())->parent = x;
            }
            (x = x->child[c])->val = c;
        }
        x->isword = true;
    }
    root->build();
    root->solve();
    printf("%lld\n", ans);
}

