bool check(string a,string b){
	if(a.length()>b.length()){
		swap(a,b);
	}

	int n=a.length();
	int m=b.length();
	int ind=-1;

	forn(i,0,m){
		if(b[i]==a[0]){ind=i; break;}
	}
	if(ind==-1)return 0;
	int j=m-1;

	for(int i=n-1;i>=1;i--){
			if(j==ind || a[i]!=b[j])return 0;
			j--;
	}
	return 1;

}

