struct hashMap {
	static const int mxn = 19260817;
	int hd[mxn];
	vector <int> nex;
	vector <ll> key;
	vector <int> val;
	hashMap() { memset(hd, -1, sizeof(hd)); nex.clear(); key.clear(); val.clear(); }
#define fore(e, id) for (int e = hd[id]; ~e; e = nex[e])
	int &operator [] (ll x) {
		int id = x % mxn; fore(e, id) if (key[e] == x) return val[e];
		key.pb(x); nex.pb(hd[id]); hd[id] = nex.size() - 1; val.pb(0);
		return val[nex.size() - 1];
	}
#undef fore
};

hashMap S;

