int solve(string s,string t)
{
    int num=0;
    for(unsigned int i=0;i<t.size();i++)
    {
        if(s.size()>=t.size())
            break;
        if(s[num]!=t[num])
            t.erase(num,1);
        else
        {
            if (s.size()==1)
                return 1;
            else if(num==0) num++;
            else break;
        }
    }
    if(s!=t)
        return 0;
    return 1;
}

