struct Trie{
  int count;
  int depth;
  Trie* link[26];
  int alpha[26];
  Trie(int cnt,int dpt):count(cnt),depth(dpt){
    for(int i = 0; i < 26; ++i){
      link[i] = nullptr;
      alpha[i] = 0;
    }
  }  
};

int main(){
  int n; cin >> n;
  vector<string> v(n); cin >> v;
  sort(v.begin(), v.end(), [](const string&l,const string&r){
	 return l.size() > r.size();   });

  Trie* head = new Trie(0,0);  
  ll ans = 0;

  int ex[26] = {};

  for(auto&s:v){
    bitset<26>bs;

    if(s.size() == 1){
      ans += ex[s.front()-'a'];
      ex[s.front()-'a']++;
      continue;
    }

    for(int i = 0; i < 26; ++i){
      int x = s[i] - 'a';
      if(!bs[x]){
	ex[x]++;
	bs[x] = true;
      }
    }

    reverse(s.begin(),s.end());

    int last[26] = {};
    for(int i = 0; i < (int)s.size(); ++i){
      last[s[i]-'a'] = i;
    }

    Trie* it = head;
    char c = s.back();
    s.pop_back();

    for(auto&e:s){
      int x = e - 'a';
      if(it->link[x] == nullptr){
	it = it->link[x] = new Trie(0,it->depth+1);
      } else {
	it = it->link[x];
      }
      it->count++;
      for(int i = 0; i < 26; ++i){
	if(last[i] > it->depth) it->alpha[i]++;
      }
    }

    ans += it->alpha[c-'a'];

    s.push_back(c);
    int x = c - 'a';
    if(it->link[x] == nullptr){
      it = it->link[x] = new Trie(0,it->depth+1);
    } else {
      it = it->link[x];
    }
    it -> count++;
  }
  cout << ans << endl;
}

