using namespace std;

struct Node {
    map<char, Node*> sons;
    vector<int64_t> count_below;

    Node() : count_below(26, 0) {}
};

void Insert(Node* &root, const string &word, int index) {
    if (index < 0) {
        return;
    }

    auto ch = word[index];
    if (root->sons.count(ch) == 0) {
        root->sons[ch] = new Node();
    }

    root->count_below[ch - 'a'] += 1;
    Insert(root->sons[ch], word, index - 1);
}

void CountBelow(Node* &root) {
    for (auto &p : root->sons) {
        auto son = p.second;
        CountBelow(son);
        for (size_t i = 0; i < root->count_below.size(); i += 1) {
            root->count_below[i] += son->count_below[i];
        }
    }
}

Node* BuildTrie(const vector<string> &words) {
    auto root = new Node();
    for (const auto &word : words) {
        Insert(root, word, word.size() - 1);
    }
    CountBelow(root);
    return root;
}

int64_t CountMatches(Node *root, const string &word) {
    auto iter = root;
    for (int i = word.size() - 1; i > 0; i -= 1) {
        iter = iter->sons[word[i]];
    }
    return iter->count_below[word[0] - 'a'] - 1;
}

int64_t Solve(const vector<string> &words) {
    auto root = BuildTrie(words);

    int64_t res = 0;
    for (const auto &word : words) {
        res += CountMatches(root, word);
    }
    return res;
}

