    vector<string> S(N);
    for (int i=0; i<N; ++i) cin >> S[i];

    for (int i=0; i<N; ++i) reverse(S[i].begin(), S[i].end());
    sort(S.begin(), S.end(), [](auto a, auto b){return (int)a.size() > (int)b.size();});

    map<string, vector<int>> mp;
    ll res = 0;
    int cur = (int)S.front().size();
    for (int i=0; i<N; ++i) {
        int len = (int)S[i].size();
        if (cur >= len) {
            int dif = cur - len + 1;
            map<string, vector<int>> tmp;
