  vector<TrNode> trie;
  trie.push_back(TrNode());
  int tidx = 1;
  for (ll i = 0; i < N; i++) {
    string s; cin >> s;
    reverse(s.begin(), s.end());
    S[i] = s;
    ll slen = s.size();
    int idx = 0;
    for (ll j = 0; j < slen; j++) {
      int c = s[j] - 'a';
      if (trie[idx].nxt[c] == -1) {
	trie.push_back(TrNode());
	DLOG("trie[", idx, "].nxt[", c, "]=", tidx);
	trie[idx].nxt[c] = tidx;
	tidx++;
      }
      idx = trie[idx].nxt[c];
    }
    trie[idx].term = true;
  }

  auto dfs = [&](auto rF, int idx) -> void {
    DLOG("dfs", idx);
    TrNode& nd = trie[idx];
    for (int i = 0; i < 26; i++) {
      int p = nd.nxt[i];
      if (p == -1) continue;
      rF(rF, p);
      for (int c = 0; c < 26; c++) {
