bool judge(const string& lhs, const string& rhs)
{
    bool ret = false;
    if(rhs.length() > 1)
    {
        if(lhs.compare(lhs.size() - rhs.size() + 1, rhs.size() - 1, rhs.substr(1)) == 0)
        {
            auto pos = lhs.find(rhs[0]);
            if(pos != string::npos && pos < (lhs.size() - rhs.size() + 1))
            {
                ret = true;
            }
        }
    }
    else if(lhs.find(rhs) != string::npos)
    {
        ret = true;
    }
    return (ret);
}

