struct TrieNode *getNode(void) 
{ 
    struct TrieNode *pNode =  new TrieNode; 

    pNode->here = 0; 

    for (int i = 0; i < 26; i++) {
        pNode->child[i] = NULL; 
        pNode->hasc[i] = 0;
    }

    return pNode; 
}

void dfs(struct TrieNode *u){

	if(u==NULL)return;

	for(int i=0;i<26;i++){
		if(u->child[i]==NULL || u->child[i]->here==0)continue;
		// ans += u->child[i]->here*(u->child[i]->here-1);
		for(int j=0;j<26;j++){
