  rep(i, n) {
    cin >> s[i];
    reverse(all(s[i]));
  }

  // b
  // a
  // cba
  // c
  // d
  // ba

  ll ans = 0;
  for (char alpha = 'a'; alpha <= 'z'; ++alpha) {
    Trie trie;
    trie.value = 0;
    function<bool(Trie&, const string&, int)> add_trie =
        [&](Trie& t, const string& si, int i) {
          bool have = false;
          if (i < si.size()) {
            if (t.children.empty()) {
              t.children.resize(26);
              rep(i, 26) t.children[i].value = 0;
            }
            Trie& c = t.children[si[i] - 'a'];
            if (add_trie(c, si, i + 1)) {
              have = true;
            }
            if (si[i] == alpha) have = true;
          }
          if (have && si.size() - i >= 2) {
            if (alpha == 'b') dbg(si);
            ++t.value;
          }
          return have;
        };
    for (const auto& si : s) add_trie(trie, si, 0);
    for (const auto& si : s) {
      if (si.back() == alpha) {
        const Trie* t = &trie;
        rep(i, si.size() - 1) {
          assert(!t->children.empty());
          t = &t->children[si[i] - 'a'];
        }
        dbg(si, t->value);
        ans += t->value;
      }
    }
  }
  wt(ans);
}

