void insrt(string &s) {
	int cur = 1;
	for(auto ch: s) {
		if(!nxt[cur][ch - 'a']) {
			nxt[cur][ch - 'a'] = ++ptr;
 		}
 		cur = nxt[cur][ch - 'a'];
	}
	nxt[cur][26]++;
}

