const ll mykake = 128ll;
const ll mymod = 2000000011ll;



void solve(){
    cin >> n;

    for(int i=0;i<n;i++){
        cin >> tableee[i].second;
        tableee[i].first = tableee[i].second.size();
        exist[tableee[i].first] = true;
        cexist[tableee[i].first][tableee[i].second.front() - 'a'] = true;
    }
    sort(tableee, tableee + n);
    reverse(tableee, tableee + n);
    for(int i=0;i<n;i++){
        string s;

        s = tableee[i].second;

        reverse(s.begin(), s.end());
        ll mylen = s.size() - 1;
        ll ret = 0;
        for(int j=0;j<s.size()-1;j++){
            ret *= mykake;
            ret += s[j] - 'a' + 25;
            ret %= mymod;
        }

        ll myhash = ret;
        ret = 0;

        int c = s.back() - 'a';

        auto ite2 = st.lower_bound(fin{mylen, myhash, c + 1, 0});
        auto ite1 = st.lower_bound(fin{mylen, myhash, c, (ll)s.size() - 1});
        /*
        p(s);
        line();
        p("search from");
        pe(mylen);pe(myhash);pe(c + 1);p(0);
        pe(mylen);pe(myhash);pe(c);p(s.size() - 1);
        line();

        for(auto e : st) {
            pe(e.len);pe(e.hash);pe(e.mozi);p(e.idx);
        }
        */
        ll idx1 = distance(st.begin(), ite1);
        ll idx2 = distance(st.begin(), ite2);


        ans += idx2 - idx1;

        vec table(26, -INF);
        for(int j=0;j<s.size();j++){
            table[s[j] - 'a'] = max(table[s[j] - 'a'], (ll)j);
        }
        for(int k=0;k<26;k++){
            if (table[k] != -INF) st.insert(fin{0, 0, k, table[k]});
        }
        for(int j=0;j<s.size();j++){
            ret *= mykake;
            ret += s[j] - 'a' + 25;
            ret %= mymod;
            if (!exist[j + 2]) continue;
            for(int k=0;k<26;k++){
                if (table[k] != -INF && cexist[j + 2][k]) st.insert(fin{j + 1, ret, k, table[k]});
            }
        }


    }
    p(ans);
    return;
}

