using namespace std;

struct Node {
	Node() {
		c = -1;
		for (int i = 0; i < 26; ++i) {
			nxt[i] = nullptr;
			cnt[i] = 0;
		}
		isend = false;
		tot = 0;
	}

	int c;
	Node* nxt[26];
	int cnt[26];
	bool isend;
	int tot;
};

void add(Node* root, const string& s) {
	Node* cur = root;
	for (int i = 0; i < s.length(); ++i) {
		int c = s[i] - 'a';
		if (cur->nxt[c]) {
			cur = cur->nxt[c];
		} else {
			Node* p = new Node();
			cur->nxt[c] = p;
			cur = cur->nxt[c];
		}
		cur->c = c;
	}
	cur->isend = true;
}

void dfs(Node* v, string& path) {
	if (!v) {
		return;
	}
	if (v->isend) {
		v->tot = 1;
	}
	for (int i = 0; i < 26; ++i) {
		if (v->nxt[i]) {
			path += 'a' + v->nxt[i]->c;
			dfs(v->nxt[i], path);
			path.pop_back();
			v->tot += v->nxt[i]->tot;
			for (int j = 0; j < 26; ++j) {
				if (i != j) {
					v->cnt[j] += v->nxt[i]->cnt[j];
				}
			}
			v->cnt[i] += v->nxt[i]->tot;
		}
	}
}

long long res = 0;

void dfs2(Node* cur, Node* prev = nullptr) {
	if (!cur) {
		return;
	}

	if (prev && cur->isend) {
		res += (cur->tot - 1);

		res += (prev->cnt[cur->c] - cur->tot);
	}

	for (int i = 0; i < 26; ++i) {
		if (cur->nxt[i]) {
			dfs2(cur->nxt[i], cur);
		}
	}
}

void solve() {
	int n;
	cin >> n;
	Node* root = new Node();

	for (int i = 0; i < n; ++i) {
		string s;
		cin >> s;
		reverse(s.begin(), s.end());
		add(root, s);
	}

	string curs;
	dfs(root, curs);
	dfs2(root);
	cout << res << endl;
}

