class RollingHash {
    int b1 = 1007, b2 = 1009;
    int m1 = 1e9 + 7, m2 = 1e9 + 9;
    vec<int>h1, p1;
public:
    void init(const string& s) {
        int n = s.size();
        h1.assign(n + 1, 0);
        p1.assign(n + 1, 1);
        for (int i = 0; i < n; i++) {
            h1[i + 1] = (h1[i] + s[i]) * b1 % m1;
            p1[i + 1] = p1[i] * b1 % m1;
        }
    }
    int get(int l, int r) {
        int t1 = ((h1[r] - h1[l] * p1[r - l]) % m1 + m1) % m1;
        return t1;
    }//[l,r)
};
