struct node {
    int to[ 26 ] ;
    int subtree ;
    int en ;
    int cnt[ 26 ] ;
    node ( ) {
        subtree = 0 ;
        for ( int i = 0 ; i < 26 ; ++ i ) {
            to[ i ] = cnt[ i ] = 0 ;
        }
    }
};
node v[ 7 * MAXN ] ;
int tpsz = 1 ;

long long ans = 0 ;

void add_word ( string &s ) {
    int sz = s.size ( ) ;
    int aux = 1 ;
    for ( int i = sz - 1 ; i >= 0 ; -- i ) {
        int val = ( s[ i ] - 'a' ) ;
        ++ v[ aux ].subtree ;
        if ( v[ aux ].to[ val ] == 0 ) {
            v[ aux ].to[ val ] = ++ tpsz ;
        }
        aux = v[ aux ].to[ val ] ;
    }
    ++ v[ aux ].subtree ;
    ++ v[ aux ].en ;
}

void upd ( int where ) {
    for ( int i = 0 ; i < 26 ; ++ i ) {
        if ( v[ where ].to[ i ] > 0 ) {
            upd ( v[ where ].to[ i ] ) ;
            for ( int j = 0 ; j < 26 ; ++ j ) {
                if ( i != j ) {
                    v[ where ].cnt[ j ] += v[ v[ where ].to[ i ] ].cnt[ j ] ;
                }
                else {
                    v[ where ].cnt[ j ] += v[ v[ where ].to[ i ] ].subtree ;
                }
            }
        }
    }
}

void calc ( int where ) {
    for ( int i = 0 ; i < 26 ; ++ i ) {
        if ( v[ where ].to[ i ] > 0 ) {
            if ( v[ v[ where ].to[ i ] ].en > 0 ) {
                ans += ( v[ where ].cnt[ i ] - 1 ) ;
            }
            calc ( v[ where ].to[ i ] ) ;
        }
    }
}

