    rep(i, N) SN[i] = S[i].size();
    RS = S;
    rep(i, N) reverse(all(RS[i]));

    vvc<bool> A(N, vc<bool>(26));
    map<pair<ull, ll>, ll> mp;

    map<pair<ull, ll>, bool> use;
    vc<RollingHash> vrh;
    rep(i, N) {
        RollingHash rh(RS[i]);
        vrh.emplace_back(rh);
        use[{rh.get(0, SN[i] - 1), S[i][0] - 'a'}] = 1;
    }

    rep(i, N) {
        RollingHash rh = vrh[i];
        rep(j, SN[i]) {
            A[i][S[i][j] - 'a'] = true;
            rep(k, 26) {
