ll ans=0;

map<string,ll> ms;
map<string,bool> seen[200001];
void dfs(string s,int i){
    seen[i][s]=true;
    if(s.size()==1){
        return ;
    }
    elif(s.size()==2){
        if(!seen[i][s.substr(1,1)]){ans+=ms[s.substr(1,1)];dfs(s.substr(1,1),i);}
        if(!seen[i][s.substr(0,1)]){ans+=ms[s.substr(0,1)];dfs(s.substr(0,1),i);}


    }
    else{
        if(!seen[i][s.substr(0,1)+s.substr(2,s.size()-2)]){ans+=ms[s.substr(0,1)+s.substr(2,s.size()-2)];dfs(s.substr(0,1)+s.substr(2,s.size()-2),i);}
        if(!seen[i][s.substr(1,1)+s.substr(2,s.size()-2)]){ans+=ms[s.substr(1,1)+s.substr(2,s.size()-2)];dfs(s.substr(1,1)+s.substr(2,s.size()-2),i);}

    }
    return ;
}


