template<char base = 'a'>
struct trie{
  struct node{
    std::vector<int> next_alp;
    int val;
    node():next_alp(26,-1),val(-1){}
    node(int k):next_alp(26,-1),val(k){}
    node(int c,int id):next_alp(26,-1),val(-1){
      next_alp[c] = id;
    }
  };
  std::vector<node> nodes;
  int k;
  trie():nodes(26),k(0){}

  std::vector<int> encode(std::string const& s){
    int n = s.size();
    std::vector<int> a(n);
    for(int i=0;i<n;++i)a[i]=s[i]-base;
    return a;
  }
  void add_impl(std::vector<int> const& a,int ai,int nodei){
    if(ai+1==a.size()){
      nodes[nodei].val = k++;
      return;
    }
    auto& nxt = nodes[nodei].next_alp[a[ai+1]];
    if(nxt==-1){
      nxt = nodes.size();
      nodes.emplace_back();
    }
    add_impl(a,ai+1,nxt);
  }
  void add(std::string const& s){
    add_impl(encode(s),0,s[0]-base);
  }
  bool find(std::string const& s){
    auto cur = nodes[s[0]-base];
    if(std::all_of(cur.next_alp.begin(),cur.next_alp.end(),[](int i){return i==-1;})&&cur.val==-1)return false;
    for(int i=0;i+1<s.size();++i){
      int c = s[i+1]-base;
      if(cur.next_alp[c]==-1)return false;
      cur = nodes[cur.next_alp[c]];
    }
    return true;
  }
  vector<int> candidate_nxtalp(node& x){
    vector<int> res;
    for(int i=0;i<26;++i)if(x.next_alp[i]!=-1&&nodes[x.next_alp[i]].val!=-1)res.emplace_back(i);
    return res;
  }
  int64_t match(std::string const& s){
    auto&& a = encode(s);
    node& cur = nodes[a.front()];
    if(std::all_of(cur.next_alp.begin(),cur.next_alp.end(),[](int i){return i==-1;})&&cur.val==-1)return 0;
    auto calc = [&](int i,node& cur){
      auto&& cna = candidate_nxtalp(cur);
      vector<bool> alp_flag(26);
      for(;i<size(a);++i)alp_flag[a[i]]=1;
      vector<int> ea;
      for(int i=0;i<26;++i)if(alp_flag[i])ea.emplace_back(i);
      vector<int> res;
      set_intersection(begin(cna),end(cna),begin(ea),end(ea),back_inserter(res));
      return size(res);
    };
    int64_t ans = 0;
    vector<bool> alp_flag(26);
    for(int i=0;i<size(a);++i)alp_flag[a[i]]=1;
    for(int i=0;i<26;++i)if(alp_flag[i]&&nodes[i].val!=-1)ans++;
    for(int i=0;i+1<size(a);++i){
      ans += calc(i+1,cur);
      int nid = cur.next_alp[a[i+1]];
      if(nid==-1)break;
      cur = nodes[nid];
    }
    return ans;
  }
};

