pli nx(pli x, char t) {
  return {x.first * P + t, (x.second * (ll)P1 + t) % mod};
}

vli mhash(const string & s) {
  vli h(s.size() + 1);
  if (pw.size() < h.size()) {
    pw.resize(h.size());
    pw1.resize(h.size());
  }
  for (int i = 0; i < s.size(); ++i) {
    h[i+1] = nx(h[i], s[i]);
    pw[i+1] = pw[i] * P;
    pw1[i+1] = pw1[i] * P1 % mod;
  }
  return h;
}

int up(int x) {
  if (x < 0) return x + mod;
  return x;
}

pli geth(const vli& v, int b, int len) {
  return pli(v[b+len].first - pw[len] * v[b].first, up((v[b+len].second - pw1[len] * v[b].second) % mod));
}

