void insert(const string &s)
{
	static int col[26];
	int len=s.size();
	for(int i=0;i<len;i++)
		col[s[i]-'a']++;
	int u=1;
	for(int i=0;i<len;i++)
	{
		int c=s[i]-'a';
		for(int j=0;j<26;j++)
			if(col[j]) trie[u].col[j]++;
		if(!trie[u].ch[c]) trie[u].ch[c]=++tot;
		u=trie[u].ch[c];
		col[c]--;
	}
	return;
}
int query(const string &s)
{
	int len=s.size();
	int u=1;
	for(int i=0;i<len-1;i++)
		u=trie[u].ch[s[i]-'a'];
	return trie[u].col[s[len-1]-'a']-1;
}
