void Hash(int ind,string s){
	ll has=0;
	h[ind].pb(s[0]-'a'+1);
	has+=s[0]-'a'+1;
	for(int i=1;i<(int)s.size();i++){
		h[ind].pb(has+(s[i]-'a'+1)*p[i]);
		has+=(s[i]-'a'+1)*p[i];
	}
	used[has]++;
}
