struct Trie {
  ll cnt;
  Trie *child[26];
  std::vector<ll> count_ch;

  Trie()
  : count_ch(26, 0), cnt(0)
  {
    rep( i, 26 ) {
      child[i] = nullptr;
    }
  }
};

ll insert( const std::string &s, Trie *root ) {
  ll ret = 0;
  std::vector<ll> count(27, 0);

  rep( i, s.size() )
    ++count[s[i]-'a'];

  Trie *trie = root;

  rep( i, s.size() ) {
    rep( j, 26 ) if( count[j] )
      ++trie->count_ch[j];

    if( trie->child[s[i]-'a'] == nullptr )
      trie->child[s[i]-'a'] = new Trie();

    trie = trie->child[s[i]-'a'];
    --count[s[i]-'a'];
  }

  return ret;
}

ll traverse( const std::string &s, Trie *root ) {
  Trie *trie = root;

  rep( i, s.size()-1 ) {
    trie = trie->child[s[i]-'a'];
  }

  return trie->count_ch[s[s.size()-1]-'a']-1;
}

