struct trie{
	struct node{
		array<int,char_size>next,cnt;
		int id;
		node():id(-1){next.fill(-1);cnt.fill(0);}
	};
	vector<node>v;
	trie(){v.push_back(node());}
	int add(const string&s,int idx)
	{
		int p=0;
		vector<int>ids;
		for(int i=0;i<s.size();i++)
		{
			ids.push_back(p);
			int j=s[i]-'a';
			if(v[p].next[j]<0)
			{
				v[p].next[j]=v.size();
				v.push_back(node());
			}
			p=v[p].next[j];
		}
		v[p].id=idx;
		int ex=0;
		for(int i=s.size();i--;)
		{
			ex|=1<<(s[i]-'a');
			for(int j=0;j<26;j++)if(ex>>j&1)v[ids[i]].cnt[j]++;
		}
		return ids.back();
	}
};
