class Trie {
public:
	struct Node {
		Node *next[26];
        ll res[26];
        ll sm[26];
		int sub;
		Node() : sub(0){
			for(int i = 0; i < 26; i++){
				next[i] = nullptr;
                res[i] = 0;
                sm[i] = 0;
            }
		}
	};
	Node* root;
    ll ans;
	Trie(){
		root = new Node();
	}
	//Trie木にxを加える
	void add(string& s) {
        Node *curr = root;
		for(int i = 0; i < (int)s.size(); i++){
			if(i==(int)s.size()-1){
                curr->res[s[i]-'a']++;
            }
            int y = s[i] - 'a';
			if (!curr->next[y]) {
				curr->next[y] = new Node();
			}
			curr->sub++;
			curr = curr->next[y];
		}
		curr->sub++;
	}
    //何らかのクエリ
	int query(Node *curr,int d) {
		int res = 0;
		for(int i = 0; i < 26; i++){
			if(curr->next[i]){
				res += query(curr->next[i],d+1);
			}
		}
		return res;
	}
	int query() {
		return query(root, 0);
	}
    void dfs(Node *curr,int c){
        for(int i = 0; i < 26; i++){
			if(curr->next[i]){
                dfs(curr->next[i],i);    
                for(int j=0;j<26;j++){
                    curr->sm[j] += curr->next[i]->sm[j];
                }
            }
		}
        for(int i=0;i<26;i++){
            // cerr << c << " "<< curr->sm[i] << " " << curr->res[i] << endl;
            if(curr->res[i]){
                ans += curr->sm[i]-1;
            }
        }
        if(c!=-1){
            curr->sm[c] = curr->sub;
        }
    }
    ll init(){
        ans = 0;
        dfs(root,-1);
        return ans;
    }
};

