void buildtree(int node, int k) {
    if (k == s.size()) {
        ok[node] = 1;
        return;
    }
    if (nxt[node][s[k]-'a'] == 0) {
        nxt[node][s[k]-'a'] = ++num;
    }
    buildtree(nxt[node][s[k]-'a'], k+1);
}

void dfs(int node, int k) {
    // cout << s << " " << node << " " << k << endl;
    if (k == s.size() - 1) {
        return;
    }

    for (int i = 0; i < 26; i++) {
        if (cnt[i] == 0) continue;
        if (ok[nxt[node][i]]) ans++;
    }

    cnt[s[k]]--;
    dfs(nxt[node][s[k]-'a'], k+1);
}



