    for (int j = 0; j < 26; ++j) {
      r[i][j] = rand();
      r[i][j] = (r[i][j] << 25) ^ rand();
      r[i][j] = (r[i][j] << 25) ^ rand();
    }
  }

  ios_base::sync_with_stdio(false);

  int n;
  cin >> n;
  vector<string> a(n);
  for (int i = 0; i < n; ++i) {
    cin >> a[i];
  }
  sort(a.begin(), a.end(), [](string& a, string &b) {
    return a.size() < b.size();
  });

  unordered_map<uint64_t, int> m;
  int64_t ans = 0;
  for (string& s : a) {
    vector<int> v(s.size());
    for (int i = 0; i < s.size(); ++i) {
      v[i] = 1 << (s[i] - 'a');
      if (i) v[i] |= v[i - 1];
    }
    if (m.count(0)) {
      int tmp = m[0] & v.back();
      ans += __builtin_popcount(tmp);
    }

    uint64_t h = 0;
    for (int i = int(s.size()) - 1, j = 0; i >= 1; --i, ++j) {
      h ^= r[j][s[i] - 'a'];
      if (m.count(h)) {
        int tmp = m[h] & v[i - 1];
        ans += __builtin_popcount(tmp);
      }
    }
    m[h] |= v[0];
  }
  cout << ans << endl;

