class trie
{
	private:
		trie* ch[26];
		int cnt;
		vector<int> count_ch;

	public:

		trie()
		{
			cnt=0;
			count_ch=vector<int>(26,0);
			for(int i=0;i<26;i++)
			{
				ch[i]=NULL;
			}
		}

		int insert(string s)
		{
			trie* node= this;

			int ans=0;

			vector<int> count(27,0);

			for(int i=0;i<s.length();i++)
			{
				count[s[i]-'a']++;
			}

			for(int i=0;i<s.length();i++)
			{
				if(i+1==s.length())
				{
					ans+=node->count_ch[s[i]-'a'];
				}
				for(int j=0;j<26;j++)
				{
					if(count[j])
						node->count_ch[j]++;
				}
				if(node->ch[s[i]-'a']==NULL)
					node->ch[s[i]-'a']=new trie();
				node=node->ch[s[i]-'a'];
				count[s[i]-'a']--;
			}
			return ans;

		}



};



