/* 
// ローリングハッシュ計算用の各種定数
// 配列 a[0, n) に対して sum [i = 0 to n - 1] (a[i] * x^i) mod m の形でハッシュを計算する
// radix は計算に用いる x で, その逆元が inv である
*/
class RollingHashConstant {
public:
	static constexpr int trials = 3;	// 用いる mod の数

	// TODO: 良い定義方法を考える
	// mod は 2 ^ 31 以下の素数
	static constexpr std::array<uint32_t, trials> mod_list = {
		1029392827,
		1052308451,
		1038234577
	};
	static constexpr std::array<uint32_t, trials> radix_list = {
		922013041,
		225237713,
		867506933
	};
	static constexpr std::array<uint32_t, trials> inv_list = {
		182811337,
		394845847,
		601827159
	};
};

/*
// ローリングハッシュの計算を補助する型 (複数要素の演算をまとめて行うクラス: 1つの整数と考えてもよい)
// これをハッシュとして使うと長さの異なる文字列で衝突するので注意
// 比較関数は set/map 用
*/
class RollingHashBase {
	static constexpr int trials_m = RollingHashConstant::trials;
	std::array<uint32_t, trials_m> values_m = {};

public:
	RollingHashBase() = default;
	explicit RollingHashBase(uint32_t value);

private:
	explicit RollingHashBase(const std::array<uint32_t, trials_m>& values);

public:
	static int compare(const RollingHashBase& a, const RollingHashBase& b);
	static RollingHashBase getRadix();
	static RollingHashBase getInverseRadix();

	RollingHashBase& operator+=(const RollingHashBase& other);
	RollingHashBase& operator-=(const RollingHashBase& other);
	RollingHashBase& operator*=(const RollingHashBase& other);
};

bool operator==(const RollingHashBase& a, const RollingHashBase& b);
bool operator!=(const RollingHashBase& a, const RollingHashBase& b);
bool operator<(const RollingHashBase& a, const RollingHashBase& b);
bool operator<=(const RollingHashBase& a, const RollingHashBase& b);
bool operator>(const RollingHashBase& a, const RollingHashBase& b);
bool operator>=(const RollingHashBase& a, const RollingHashBase& b);

RollingHashBase operator+(const RollingHashBase& a, const RollingHashBase& b);
RollingHashBase operator-(const RollingHashBase& a, const RollingHashBase& b);
RollingHashBase operator*(const RollingHashBase& a, const RollingHashBase& b);

/* radix の累乗を O(1) で得るためにメモを行うクラス */
class RollingHashMemo {
	static std::vector<RollingHashBase> pow_table_m;	// radix の累乗
	static std::vector<RollingHashBase> inv_table_m;	// radix の逆元の累乗

public:
	static void prepare(int new_size);
	static RollingHashBase getPower(int exp);
	static RollingHashBase getInversePower(int exp);
};

/* 
// RollingHashBase に文字列長の情報を付加したもの
// ある文字列に(ほぼ一意に)対応すると考えてよい: 関数の命名もこれにならう
// 比較関数は set/map 用
*/
class RollingHash {
