/*-----------------------------------*/

RollingHashBase::RollingHashBase(uint32_t value) {
	for (int i = 0; i < trials_m; ++i) {
		values_m[i] = value % RollingHashConstant::mod_list[i];
	}
}

RollingHashBase::RollingHashBase(const std::array<uint32_t, trials_m>& values) 
	: values_m(values) {
}

int RollingHashBase::compare(const RollingHashBase& a, const RollingHashBase& b) {
	for (int i = 0; i < trials_m; ++i) {
		if (a.values_m[i] < b.values_m[i]) return -1;
		if (a.values_m[i] > b.values_m[i]) return 1;
	}
	return 0;
}

RollingHashBase RollingHashBase::getRadix() {
	return RollingHashBase(RollingHashConstant::radix_list);
}

RollingHashBase RollingHashBase::getInverseRadix() {
	return RollingHashBase(RollingHashConstant::inv_list);
}

RollingHashBase& RollingHashBase::operator+=(const RollingHashBase& other) {
	for (int i = 0; i < trials_m; ++i) {
		values_m[i] += other.values_m[i];
		if (values_m[i] >= RollingHashConstant::mod_list[i]) {
			values_m[i] -= RollingHashConstant::mod_list[i];
		}
	}
	return *this;
}

RollingHashBase& RollingHashBase::operator-=(const RollingHashBase& other) {
	for (int i = 0; i < trials_m; ++i) {
		if (values_m[i] < other.values_m[i]) {
			values_m[i] += RollingHashConstant::mod_list[i];
		}
		values_m[i] -= other.values_m[i];
	}
	return *this;
}

RollingHashBase& RollingHashBase::operator*=(const RollingHashBase& other) {
	for (int i = 0; i < trials_m; ++i) {
		values_m[i] = uint64_t(values_m[i]) * other.values_m[i] % RollingHashConstant::mod_list[i];
	}
	return *this;
}

bool operator==(const RollingHashBase& a, const RollingHashBase& b) {
	return RollingHashBase::compare(a, b) == 0;
}

bool operator!=(const RollingHashBase& a, const RollingHashBase& b) {
	return RollingHashBase::compare(a, b) != 0;
}

bool operator<(const RollingHashBase& a, const RollingHashBase& b) {
	return RollingHashBase::compare(a, b) < 0;
}

bool operator<=(const RollingHashBase& a, const RollingHashBase& b) {
	return RollingHashBase::compare(a, b) <= 0;
}

bool operator>(const RollingHashBase& a, const RollingHashBase& b) {
	return RollingHashBase::compare(a, b) > 0;
}

bool operator>=(const RollingHashBase& a, const RollingHashBase& b) {
	return RollingHashBase::compare(a, b) >= 0;
}

RollingHashBase operator+(const RollingHashBase& a, const RollingHashBase& b) {
	RollingHashBase ret(a);
	ret += b;
	return ret;
}

RollingHashBase operator-(const RollingHashBase& a, const RollingHashBase& b) {
	RollingHashBase ret(a);
	ret -= b;
	return ret;
}

RollingHashBase operator*(const RollingHashBase& a, const RollingHashBase& b) {
	RollingHashBase ret(a);
	ret *= b;
	return ret;
}

/*-----------------------------------*/
/*-------   RollingHashMemo   -------*/
/*-----------------------------------*/

// 単位元を入れておく
std::vector<RollingHashBase> RollingHashMemo::pow_table_m(1, RollingHashBase(1));
std::vector<RollingHashBase> RollingHashMemo::inv_table_m(1, RollingHashBase(1));

/* 長さ new_size まで累乗を前計算する O(new_size - old_size) */
void RollingHashMemo::prepare(int new_size) {
	int old_size = pow_table_m.size();
	if (old_size >= new_size) return;
	pow_table_m.resize(new_size);
	inv_table_m.resize(new_size);

	for (int i = old_size; i < new_size; ++i) {
		pow_table_m[i] = RollingHashBase::getRadix() * pow_table_m[i - 1];
		inv_table_m[i] = RollingHashBase::getInverseRadix() * inv_table_m[i - 1];
	}
}

/* radix の exp 乗を得る O(1) */
RollingHashBase RollingHashMemo::getPower(int exp) {
	prepare(exp + 1);
	return pow_table_m[exp];
}

/* radix の -exp 乗を得る O(1) */
RollingHashBase RollingHashMemo::getInversePower(int exp) {
	prepare(exp + 1);
	return inv_table_m[exp];
}

/*-----------------------------------*/
/*---------   RollingHash   ---------*/
/*-----------------------------------*/

RollingHash::RollingHash(int length, const RollingHashBase& base)
	: length_m(length), base_m(base) {
}

RollingHash::RollingHash(uint32_t value) 
	: length_m(1), base_m(value) {
}

/* 文字列先頭への追加 O(1) */
void RollingHash::pushFront(uint32_t element) {
	*this = concatenate(RollingHash(element), *this);
}

/* 文字列末尾への追加 O(1) */
void RollingHash::pushBack(uint32_t element) {
	*this = concatenate(*this, RollingHash(element));
}

/* 先頭要素の消去 O(1) */
/* 先頭要素が element 以外であった場合は正しい結果にならない */
void RollingHash::popFront(uint32_t element) {
	*this = removePrefix(RollingHash(element), *this);
}

/* 末尾要素の消去 O(1) */
/* 末尾要素が element 以外であった場合は正しい結果にならない */
void RollingHash::popBack(uint32_t element) {
	*this = removeSuffix(*this, RollingHash(element));
}

int RollingHash::compare(const RollingHash& a, const RollingHash& b) {
	if (a.length_m < b.length_m) return -1;
	if (a.length_m > b.length_m) return 1;
	return RollingHashBase::compare(a.base_m, b.base_m);
}

/* 文字列の連結 O(1) */
RollingHash RollingHash::concatenate(const RollingHash& a, const RollingHash& b) {
	return RollingHash(
		a.length_m + b.length_m,
		a.base_m + RollingHashMemo::getPower(a.length_m) * b.base_m
	);
}

/* 文字列 a から接頭辞 b を取り除いた結果を返す O(1) */
/* 文字列 b が文字列 a の接頭辞でない場合は正しい結果にならない */
RollingHash RollingHash::removePrefix(const RollingHash& a, const RollingHash& b) {
	return RollingHash(
		a.length_m - b.length_m,
		RollingHashMemo::getInversePower(a.length_m) * (a.base_m - b.base_m)
	);
}

/* 文字列 a から接尾辞 b を取り除いた結果を返す O(1) */
/* 文字列 b が文字列 a の接尾辞でない場合は正しい結果にならない */
RollingHash RollingHash::removeSuffix(const RollingHash& a, const RollingHash& b) {
	return RollingHash(
		a.length_m - b.length_m,
		a.base_m - RollingHashMemo::getPower(a.length_m) * b.base_m
	);
}

bool operator==(const RollingHash& a, const RollingHash& b) {
	return RollingHash::compare(a, b) == 0;
}

bool operator!=(const RollingHash& a, const RollingHash& b) {
	return RollingHash::compare(a, b) != 0;
}

bool operator<(const RollingHash& a, const RollingHash& b) {
	return RollingHash::compare(a, b) < 0;
}

bool operator<=(const RollingHash& a, const RollingHash& b) {
	return RollingHash::compare(a, b) <= 0;
}

bool operator>(const RollingHash& a, const RollingHash& b) {
	return RollingHash::compare(a, b) > 0;
}

bool operator>=(const RollingHash& a, const RollingHash& b) {
	return RollingHash::compare(a, b) >= 0;
}

