/* 空文字列を生成 */
RollingHashString::RollingHashString() {
	initialize(std::vector<uint32_t>());
}

RollingHashString::RollingHashString(const std::vector<uint32_t>& str) {
	initialize(str);
}

RollingHashString::RollingHashString(const std::string& str) {
	initialize(std::vector<uint32_t>(str.begin(), str.end()));
}

/* 各 i (0 <= i <= n) について部分文字列 [0, i) のハッシュを計算 O(n) */
void RollingHashString::initialize(const std::vector<uint32_t>& str) {
	length_m = str.size();

	hashes_m.clear();
	hashes_m.reserve(str.size() + 1);
	hashes_m.push_back(RollingHash());

	RollingHash hash;
	for (uint32_t element : str) {
		hash.pushBack(element);
		hashes_m.push_back(hash);
	}
}

/* 位置 index から count 要素切り取ってできる文字列のハッシュを得る O(1) */
/* 引数は std::string::substr に合わせている */
RollingHash RollingHashString::substr(int index, int count) {
	int left = index;
	int right = count == -1 ? length_m : std::min(length_m, index + count);
	return RollingHash::removePrefix(hashes_m[right], hashes_m[left]);
}
