struct SegmentTree {
    int N;
    vector<Int> A;
    SegmentTree(int n) {
        N = 1;
        while (N < n) N *= 2;
        A.resize(2 * N);
    }
    void add(int idx, Int val) {
        idx += N;
        A[idx] += val;
        idx >>= 1;
        while (idx > 0) {
            A[idx] = A[2*idx+0] + A[2*idx+1];
            idx >>= 1;
        }
    }
    Int sum(int L, int R) {
        L += N, R += N;
        Int ans = 0;
        while (L < R) {
            if (L & 1) ans += A[L++];
            if (R & 1) ans += A[--R];
            L >>= 1, R >>= 1;
        }
        return ans;
    }
};
int main() {
    int N; cin >> N;
    vector<string> S(N); for (auto &s : S) cin >> s;
    vector<string> R = S;
    for (auto &r : R) reverse(begin(r), end(r));
    sort(begin(R), end(R));
    vector<SegmentTree> st;
    vector<vector<int>> cnt(N, vector<int>(26));
    for (int i = 0; i < 26; i++) {
        st.emplace_back(N);
    }
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < R[i].size(); j++) {
            cnt[i][R[i][j] - 'a']++;
        }
        for (int j = 0; j < 26; j++) {
            if (cnt[i][j] > 0) {
                st[j].add(i, +1);
            }
        }
    }
    vector<int> currSet, nextSet;
    for (int i = 0; i < N; i++) currSet.push_back(i);
    int num = 1;
    Int ans = 0;
    while (!currSet.empty()) {
        for (int i : currSet) {
            if (R[i].size() == num) {
                string head = R[i].substr(0, R[i].size() - 1);
                int idx0 = lower_bound(begin(R), end(R), head) - begin(R);
                int idx1 = upper_bound(begin(R), end(R), head + '|') - begin(R);
                ans += st[R[i][R[i].size() - 1] - 'a'].sum(idx0, idx1) - 1;
            }
        }
        nextSet.clear();
        for (int i : currSet) {
            char ch = R[i][num - 1];
            cnt[i][ch - 'a']--;
            if (cnt[i][ch - 'a'] == 0) {
                st[ch - 'a'].add(i, -1);
            }
            if (R[i].size() > num) {
                nextSet.push_back(i);
            }
        }
        swap(currSet, nextSet);
        num++;
    }
    cout << ans << endl;
    return 0;
}

