struct Node {
    bool isend;
    unordered_map<char, Node*> m;
    Node(): isend(false) {}
};
class Trie {
public:
    Node* root;
    /** Initialize your data structure here. */
    Trie(): root(new Node()) {

    }

    /** Inserts a word into the trie. */
    void insert(string word) {
        Node *node = root;
        REP(i,0,word.size()) {
            char c = word[i];
            if (node->m.count(c) == 0) node->m[c] = new Node();

            node = node->m[c];
        }

        node->isend = true;
    }

    /** Returns if the word is in the trie. */
    bool search(string word) {        
        Node *node = root;
        for (char c: word) {
            if (node->m.count(c) == 0) return false;
            node = node->m[c];
        }
        return node->isend;
    }

    /** Returns if there is any word in the trie that starts with the given prefix. */
    bool startsWith(string prefix) {        
        Node *node = root;
        for (char c: prefix) {
            if (node->m.count(c) == 0) return false;
            node = node->m[c];
        }
        return true;
    }
};

void solve() {
    int n;
    cin >> n;
    VS ss(n);
    REP(i,0,n) cin >> ss[i];
    vector<vector<int>> ds(n);
    REP(i,0,n) {
        int p = 0;
        REP(j,0,ss[i].size()) {
            p |= (1<<(ss[i][j] - 'a'));
            ds[i].emplace_back(p);
        }
        reverse(all(ds[i]));
    }

    REP(i,0,n) reverse(all(ss[i]));
    Trie t;
    REP(i,0,n) t.insert(ss[i]);

    LL cnt = 0;
    REP(i,0,n) {
        // dump(i);
        Node *node = t.root;
        REP(j,0,ss[i].size()-1) {
            char c = ss[i][j];
            // if (node->isend) ++cnt;
            REP(k,0,26) {
                char d = char('a'+k);
                if (d == c) continue;
                // if (ds[i][j].count(d) == 0) continue;
                if (!(ds[i][j] & (1<<k))) continue;
                if (node->m.count(d) == 0) continue;
                if (!node->m[d]->isend) continue;
                ++cnt;
            }
            if (node->m.count(c) == 0) break;
            node = node->m[c];
            if (node->isend) ++cnt;
        }
        // dump(cnt);
    }
    cout << cnt << endl;
}

