void gen(string &str, int id)
{
    ll hashValue = 0;
    vector<ll> v;
    int cnt[26];
    memset(cnt, 0, sizeof cnt);
    int idx = 0;
    for(int i=0; i<str.length(); i++){
        ll ch = str[i]-'a';
        cnt[ch]++;
    }
    int n = (int) str.length();

    for(int i=n-1; i>=0; i--){
        for(ll j=0; j<26; j++){
            ll temp = hashValue;
            if(cnt[j] == 0) continue;
            temp += ((j+1)*po[idx]);
            if(temp > MOD) temp -= MOD;
            v.push_back(temp);
//            prnt(id, idx, (char)(j+(int)'a'), temp);
        }
        if(i!= n-1)v.push_back(hashValue);
//        prnt(id, idx, 'X', hashValue);

        ll ch = str[i]-'a';
        cnt[ch]--;
        hashValue += ((ch+1)*po[idx]);
        if(hashValue > MOD) hashValue -= MOD;
        idx++;
    }
    Hash[id] = hashValue;

    sort(v.begin(), v.end());
    vec[id].push_back(v[0]);
    for(int i=1; i<v.size(); i++){
        if(v[i] == v[i-1]){
            //cout << "FUCK" << endl;
            continue;
        }
        else {
            vec[id].push_back(v[i]);
        }
    }
