                node = node->m[c];
            }
            node->isend = true;
        }
        bool search(string word){
            Node *node = root;
            for(char c : word){
                if(node->m.count(c) == 0) return false;
                node = node->m[c];
            }
            return node->isend;
        }
        bool startsWith(string prefix){
            Node *node = root;
            for(char c : prefix){
                if(node->m.count(c) == 0) return false;
                node = node->m[c];
            }
            return true;
        }
};

