signed main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(20);

    int n;
    cin>>n;
    vector<pair<int,string>> a(n);
    for(int i=0;i<n;i++){
        cin>>a[i].second;
        a[i].first = a[i].second.size();
    }
    sort(a.begin(),a.end());

    const int mod1 = 1000000103, mod2 = 1000000483;
    int mul1=10009;
    int mul2=10007;

    map<int,int> mp1[26],mp2[26];
    ll ans = 0;
    int ma = 0;
    ll one[26]={};
    for(int i=0;i<n;i++){
        string s = a[i].second;
        if(s.size() == 1){
            one[s[0]-'a']++;
            continue;
        }
        ll h1=0;
        ll h2=0;
        int m = s.size(), c=26;
        int cnt[c][m+1]={};
        for(int j=0;j<m;j++){
            cnt[s[j]-'a'][j+1]++;
            for(int k=0;k<26;k++) cnt[k][j+1] += cnt[k][j];
        }
        // one
        for(int j=0;j<26;j++){
            if(cnt[j][m] == 0)continue;
            ans += one[j];
        }
        int now = 0;
        for(int j=m-1;j>=1;j--){
            now++;
            h1 = (ll)(h1*mul1 + s[j]) % mod1;
            h2 = (ll)(h2*mul2 + s[j]) % mod2;
            if(now > ma)continue;
            for(int k=0;k<26;k++){
                if(cnt[k][j] && mp1[k].count((int)h1) && mp2[k].count((int)h2)){
                    ans += min(mp1[k][h1],mp2[k][h2]);
                }
            }
        }
        chmax(ma,s.size());
        mp1[(int)(s[0]-'a')][h1]++;
        mp2[(int)(s[0]-'a')][h2]++;
    }
    cout << ans << endl;

}

