struct Node {
	Node* to[26];
	bool fin = false;
	Node() {};
};

int node;
Node arr[MAXN];

Node* new_node() {
	return &arr[node++];
}

void add(Node* root, const string& s) {
	for (char c : s) {
		int pos = c - 'a';
		if (!root->to[pos])
			root->to[pos] = new_node();
		root = root->to[pos];
	}
	root->fin = true;
}

int n;
Node* root;
string s[N];

Node* go(Node* v, char c) {
	return v->to[c - 'a'];
}

int get(Node* v, int c) {
	return (v->to[c] ? v->to[c]->fin : 0);
}

void solve() {
	cin >> n;
	root = new_node();
	for (int i = 0; i < n; i++) {
		cin >> s[i];
		reverse(all(s[i]));
		add(root, s[i]);
	}
	int cnt[26];
	LL ans = 0;
	for (int i = 0; i < n; i++) {
		fill(cnt, cnt + 26, 0);
		for (char c : s[i])
			cnt[c - 'a']++;
		Node* v = root;
		for (int j = 0; j < 26; j++) {
			if (char(j + 'a') == s[i][0] || cnt[j] == 0)
				continue;
			ans += get(v, j);
		}
		for (int j = 0; j < size(s[i]) - 1; j++) {
			cnt[s[i][j] - 'a']--;
			v = go(v, s[i][j]);
			ans += v->fin;
			for (int k = 0; k < 26; k++) {
				if (char(k + 'a') == s[i][j + 1] || cnt[k] == 0)
					continue;
				ans += get(v, k);
			}
		}
	}
	cout << ans;
}

