			if (S[i].size() > S[j].size()) break;
			int si = (int) S[i].size();
			int last_char = S[i][si - 1] - 'a';
			bool good = true;
			for (int k = 0; k < si - 1; k++) {
				good &= (S[i][k] == S[j][k]);

			}
			if (!good) break;
			if (good && L[j][last_char] != -1 &&  L[j][last_char] >= si - 1) {
				r += 1;
			}
		}
	}
	for (const auto& p: C) {
		for (int i = 0; i < (int) S.size(); i++) {
			if (L[i][p.first - 'a'] != -1) r += p.second;
		}
	}
	cout << r << endl;
}

