template< ll char_size >
class TrieNode {
public:
	ll nxt[char_size];

	ll exist;
	vector< ll > accept;

	TrieNode() : exist(0) {
		memset(nxt, -1, sizeof(nxt));
	}
};

/*
あるノードの配下の全てのノードには自身に対応する文字列に共通するプレフィックスがあり, 
ルートには空の文字列が対応している。

計算量：
　add O(|S|)
　query O(|S|)

exist は子供以下に追加された文字列の個数, 
accept はそのノードにマッチする全ての追加された文字列の番号が格納される。

Trie< char_size, margin >(): 
　文字列の種類数 char_size, 開始文字が margin のトライ木を作成する。
add(S): 文字列 S をトライ木に追加する
query(S, f): 文字列 S のプレフィックスに一致する文字列を検索する。
　一致した文字列ごとに関数 f が呼び出される。
size(): ノード数を返す
count(): 存在する文字列の個数を返す
*/
template< ll char_size, ll margin >
class Trie {
public:
	using Node = TrieNode< char_size >;

	vector< Node > nodes;
	ll root;

	Trie() : root(0) {
		nodes.push_back(Node());
	}

	void update_direct(ll node, ll id) {
		nodes[node].accept.push_back(id);
	}

	void update_child(ll node, [[maybe_unused]] ll child, [[maybe_unused]] ll id) {
		++nodes[node].exist;
	}

	void add(const string &str, ll str_index, ll node_index, ll id) {
		if(str_index == (ll)str.size()) {
			update_direct(node_index, id);
		} else {
			const ll c = str[str_index] - margin;
			if(nodes[node_index].nxt[c] == -1) {
				nodes[node_index].nxt[c] = (ll) nodes.size();
				nodes.push_back(Node());
			}
			add(str, str_index + 1, nodes[node_index].nxt[c], id);
			update_child(node_index, nodes[node_index].nxt[c], id);
		}
	}

	void add(const string &str, ll id) {
		add(str, 0, 0, id);
	}

	void add(const string &str) {
		add(str, nodes[0].exist);
	}

	template<typename F> void query(const string &str, const F &f, ll str_index, ll node_index) {
		for(auto &idx : nodes[node_index].accept) f(idx);
		if(str_index == (ll)str.size()) {
			return;
		} else {
			const ll c = str[str_index] - margin;
			if(nodes[node_index].nxt[c] == -1) return;
			query(str, f, str_index + 1, nodes[node_index].nxt[c]);
		}
	}

	template<typename F> void query(const string &str, const F &f) {
		query(str, f, 0, 0);
	}

	ll count() const {
		return (nodes[0].exist);
	}

	size_t size() const {
		return nodes.size();
	}
};

