ll dp(int l, int r, int ind)
{
	if(l >= r)
		return 0;
	if(aray[l].size() == ind+1)
	{
		ll final = 0;
		int last = r+1;
		for(int i=l+1;i<=r;i++)
		{
			if(aray[i][ind] == aray[l][ind])
				final++;
			else
			{
				last = min(last, i);
				if(aray[i].size() > ind+1)
				{
					if(aray[i][ind+1] == aray[l][ind])
						final++;
				}
			}
		}
		return final + dp(l+1, last-1, ind+1) + dp(last, r, ind);
	}
	for(int i=l+1;i<=r;i++)
	{
		if(aray[l][ind] != aray[i][ind])
			return dp(l, i-1, ind+1) + dp(i, r, ind);
	}
	return dp(l, r, ind+1);
}
