constexpr char C = 'a';

struct trie{

	trie *child[NUM_a];
	int val;

	trie() {
		val = 0;
		// for(int _ = 0; _ < NUM_a; _++) child[_] = NULL;
		fill(child,child + NUM_a, (trie *)(0));
	}

	~trie() {
		/**
		*
		*
		**/
	}

	void add(char *c){
		if(*c == '\0') return;
		if(this->child[*c-C] == NULL){
			trie *node = new trie();
			this->child[*c-C] = node;
		}

        if(*(c+1) == '\0') this->child[*c-C]->val++;

		this->child[*c-C]->add(c+1);
	}

	int find(char *c){
		if(*c == '\0'){
			int con = 0;
			for(int _ = 0; _ < NUM_a; _++){
				if(this->child[_] != NULL) con += this->child[_]->val;
			}
			return this->val - con;
		}

		if(this->child[*c-C] == NULL) return 0;
		else  return this->child[*c-C]->find(c+1);
	}

	void del(char *c){
		if(*c == '\0') return ;

		if(this->child[*c-C] != NULL){
			this->child[*c-C]->del(c+1);
			if(child[*c-C]->val == 1) {
				delete child[*c-C];
				child[*c-C] = NULL;
			} else child[*c-C]->val--;
		}
	}

	void print(int depth = 0){
		for(int _ = 0; _ < NUM_a; _++){
			if(child[_] != NULL){
				for(int __ = 0; __ < depth; __++) cout<<" ";
				cout<<(char)(C+_)<<" "<<child[_]->val<<endl;
				this->child[_]->print(depth+1);
			}
		}
	}

    int count(char *c, vector<bool> &con, int num, int si, bool flag){
		if(*c == '\0'){
			return 0;
		}

        int sum = 0;

		if(this->child[*c-C] != NULL)  sum += this->child[*c-C]->count(c+1, con, num-1, si, true);
        else count(c+1, con, num-1, si, false);

        con[*c - C] = true;

        if(flag) {
             for(int _ = 0; _ < NUM_a; _++){
                trie *t = this->child[_];

                if(t == NULL) continue;

                if(con[_]) {
                    sum += t->val;
                }

            }
        }

        return sum;
	}
};

