class prefix_tree {
private:
    struct node {
        int child[26];
        int is_word;
        int count_words;
        char letter;
        node() {
            for (int i=0; i<26; i++) child[i] = -1;
            is_word = count_words = 0;
            letter = '0';
        }
    } nil;

    vector <node> nodes;
public:
    void add_word(string s) {
        int ptr = 0;
        for (char c:s) {
            nodes[ptr].count_words++;
            int p2 = nodes[ptr].child[c-'a'];
            if (p2==-1) {
                p2 = nodes[ptr].child[c-'a'] = nodes.size();
                nodes.push_back(nil);
                nodes[p2].letter = c;
            }
            ptr = p2;
        }
        nodes[ptr].count_words++;
        nodes[ptr].is_word = 1;
        // for (node i:nodes) cout<<i.count_words<<" "<<i.is_word<<" "<<i.letter<<"\n";
        // cout<<"\n";
    }

    int index_of_string(string s) {
        int ptr = 0;
        for (char c:s) {
            int p2 = nodes[ptr].child[c-'a'];
            if (p2 == -1) return -1;
            ptr = p2;
        }
        return ptr;
    }

    vector <int> dpret[26]; // dp[c][i] -  number of words pass node i, has letter c in the back
    bool initialized;
    int dp(char c, int i) {
        if (!initialized) {
            initialized = 1;
            for (int i=0; i<26; i++) dpret[i].assign(nodes.size(), -1);
        }
        if (dpret[c-'a'][i] != -1) return dpret[c-'a'][i];
        if (c==nodes[i].letter) return dpret[c-'a'][i] = nodes[i].count_words;
        int ret = 0;
        for (int j=0; j<26; j++) if (nodes[i].child[j] != -1) {
            ret += dp(c, nodes[i].child[j]);
        }
        return dpret[c-'a'][i] = ret;
    }

    prefix_tree() {
        initialized = 0;
        nodes = {nil};
    }
} ptree;
