/* Rolling Hash */
// n = 9999991, 10000019, 924844033, 1012924417

struct RollingHash {
  int N, base;
  vector<ll> hash, pow;

  template<typename Type>
  RollingHash(int base, int n, Type *arr): N(n), base(base), hash(n + 1), pow(n + 1) {
    hash[0] = 0;
    pow[0] = 1;
    for (int i = 0; i < N; i++) {
      hash[i + 1] = (hash[i] + arr[i]) * base % mod;
      pow[i + 1] = pow[i] * base % mod;
    }
  }

  // get [l,r)
  ll getHash(int l, int r) {
    return (mod + hash[r] - hash[l] * pow[r - l] % mod) % mod;
  }
};

char S[2000000];
char *s[SIZE];
map<ll, int> counter[26];

int main() {
  int N, M[SIZE];

  scanf("%d", &N);

  char *c = S;

  for (int i = 0; i < N; i++) {
    scanf("%s", c);
    M[i] = strlen(c);
    s[i] = c;
    c += M[i] + 1;
  }

  debug(c - S);

  RollingHash rh1(1012924417, c - S, S);
  RollingHash rh2(924844033, c - S, S);

  for (int i = 0; i < N; i++) {
    debug(s[i] - S, M[i]);
    int base = s[i] - S;
    ll p = (rh1.getHash(base + 1, base + M[i]) << 32) + rh2.getHash(base + 1, base + M[i]);
    counter[s[i][0] - 'a'][p]++;
  }

  ll ans = 0;

  for (int i = 0; i < N; i++) {
    bool f[26] = {};
    for (int j = 0; j < M[i]; j++) {
      f[s[i][j] - 'a'] = true;

      for (int k = 0; k < 26; k++) {
        if (!f[k]) continue;
        int base = s[i] - S;
        ll p = (rh1.getHash(base + j + 1, base + M[i]) << 32) + rh2.getHash(base + j + 1, base + M[i]);
        auto it = counter[k].find(p);

        if (it != counter[k].end()) {
          ans += it->second - (j == 0);
        }
      }
    }
  }

  cout << ans << endl;

  return 0;
}

