/**
 * Description: insert int, query max xor with some int in the trie
 * Time: O(MXBIT)
 * Source: CF Algorithms Gym
 * Verification: January Easy 2018 - Shubham and Subarray Xor
 */

template<int MX> struct Trie {
    int par[MX];
    int nex[MX][26], sz[MX], num = 0; // num is last node in trie
    int ind = 0;
    int ext = 0;
    // change 2 to 26 for lowercase letters
    Trie() { memset(par, 0, sizeof par); memset(nex,0,sizeof nex); memset(sz,0,sizeof sz); }
    void ins(string x) { // insert or delete
        int cur = 0;
        for(auto u: x){
            if(!nex[cur][u-'a']){
                nex[cur][u-'a'] = ++num;
                par[num] = cur;
            }
            cur = nex[cur][u-'a'];
        }

        sz[cur]++;
    }

    void add(char c){
        if(!nex[ind][c-'a']) ext++;
        else ind = nex[ind][c-'a'];
    }
    void del(){
        if(ext > 0) ext--;
        else ind = par[ind];
    }

    int get(){
        if(ext > 0) return 0;
        return sz[ind];
    }
};


