struct trie {
    using sitor = string::const_iterator;

    trie* nxt[26];
    int cnt[27];

    trie() { 
        memset(nxt, 0, sizeof(nxt));
        memset(cnt, 0, sizeof(cnt));
    } 

    ~trie() {
        rep(i, 26) if (nxt[i]) delete nxt[i];
    }

    void insert(sitor beg, sitor end) {
        if (beg == end) {
            ++cnt[26];
            return ;
        }
        int cur = beg[0] - 'a';
        if (!nxt[cur]) nxt[cur] = new trie();
        nxt[cur]->insert(++beg, end);
    }

    int cal_cnt() {
        // DB("cal cnt"); 
        int total = cnt[26];
        rep(i, 26) {
            if (!nxt[i]) continue;
            int subtotal = nxt[i]->cal_cnt();
            rep(f, 26) {
                cnt[f] += nxt[i]->cnt[f];
            }
            cnt[i] += subtotal - nxt[i]->cnt[i];
            total += subtotal;
        }
        // rep(i, 26) { 
            // if (cnt[i] == 0) continue; 
            // deb(char(i + 'a'), cnt[i]); 
        // } 
        return total;
    }

    trie* get(sitor beg, sitor end) {
        if (beg == end) return this;
        int cur = beg[0] - 'a';
        if (!nxt[cur]) return 0;
        return nxt[cur]->get(++beg, end);
    }
};

