int add(string s) {
	int cur = 0;
	for (auto x: s) {
		if (!nxt[cur][x - 'a']) {
			uk++;
			nxt[cur][x - 'a'] = uk;
		}
		cur = nxt[cur][x - 'a'];
	}
	return cur;
}


