namespace Trie{
    int tot = 1;
    int trie[MAXN][26],d[MAXN][26];

    void Insert(string s){
        int len = s.length();
        int now = 1;
        int pre[26];
        memset(pre,0,sizeof(pre));
        for(int i = 0;i < len;i++){
            int ch = s[i] - 'a';
            if(!trie[now][ch])
                trie[now][ch] = ++tot;
            now = trie[now][ch];
            d[now][ch] += 1;
            if(pre[ch])
                d[pre[ch]][ch] -= 1;
            pre[ch] = now;
        }
    }

    void dfs(int u){
        for(int i = 0;i < 26;i++){
            int v = trie[u][i];
            if(v){
                dfs(v);
                d[u][i] += d[v][i];
            }
        }
        //cout << u << " : " << d[u][0] << " " << d[u][1] << endl;
    }

    int Query(string s){
        int len = s.length();
        int now = 1;
        for(int i = 0;i < len - 1;i++){
            int ch = s[i] - 'a';
            now = trie[now][ch];
        }
        int res = 0;
        for(int i = 0;i < 26;i++){
            if(trie[now][i])
                res += d[trie[now][i]][s.back() - 'a'];
        }
        return res;
    }
}

