struct node{
    node* c[26]{};
    int cntEnd = 0;

    node(){
        memset(c, 0, sizeof(c));
    }
};

int add(const string& s, node* root){
    VI cnt(26);
    for(int i = 0; i < s.length(); ++i){
        cnt[s[i] - 'a']++;
    }
    int res = 0;
    for(int i = 0; i < s.length(); ++i){
        for(int j = 0; j < 26; ++j){
            if (cnt[j] > 0 && root->c[j] != nullptr){
                res += root->c[j]->cntEnd;
            }
        }
        cnt[s[i] - 'a']--;
        if (root->c[s[i] - 'a'] == nullptr){
            root->c[s[i] - 'a'] = new node();
        }
        root = root->c[s[i] - 'a'];
    }
    root->cntEnd++;
    return res;
}

