int lim[N];
int t[4 * N];
int f[N][26];
string a[N];

void build(int v, int tl, int tr) {
  if (tl == tr) {
    t[v] = lcp[tl];
  } else {
    int tm = (tl + tr) / 2;
    build(2 * v, tl, tm);
    build(2 * v + 1, tm + 1, tr);
    t[v] = min(t[2 * v], t[2 * v + 1]);
  }
}

int get(int v, int tl, int tr, int l, int r) {
  if (tr < l || r < tl) {
    return (int) 1e9;
  }
  if (l <= tl && tr <= r) {
    return t[v];
  }
  int tm = (tl + tr) / 2;
  return min(get(2 * v, tl, tm, l, r), get(2 * v + 1, tm + 1, tr, l, r));
}

void build() {
  build(1, 1, n - 1);
}

int get(int i, int j) {
  if (i == j) {
    cout << "why equal?\n";
    exit(0);
  }
  if (i > j) {
    swap(i, j);
  }
  return get(1, 1, n - 1, i, j - 1);
}

