bool judge(const string& lhs, const string& rhs, int lhs_size, int rhs_size)
{
    bool ret = false;
    if(rhs_size > 1)
    {
        if(lhs.compare(lhs_size - rhs_size + 1, rhs_size - 1, &rhs[1]) == 0)
        {
            auto pos = lhs.find(rhs[0]);
            if(pos != string::npos && pos < (lhs_size - rhs_size + 1))
            {
                ret = true;
            }
        }
    }
    else if(lhs.find(rhs[0]) != string::npos)
    {
        ret = true;
    }
    return (ret);
}

