void solve(vector <string> &A, vector <vector <int>> &X, ll &ats) {
	if (A.size()>1) {
	int m=(int)A.size();
	vector <int> B(26,0);
	vector <int> C(26,0);
	vector <vector <string>> D(26);
	vector <vector <vector <int>>> E(26);
	for (int i=0;i<m;i++) {
		string s=A[i];
		vector <int> Y=X[i];
		if ((int)s.length()==1) {int a=s[0]-'a'; B[a]++;}
		else {
			int a=s[(int)s.length()-1]-'a';
			for (int j=0;j<26;j++) {
				if (Y[j]>0) {C[j]++;}
				}
			s.pop_back();
			//cout<<a<<" "<<s<<endl;
			Y[a]--;
			D[a].push_back(s);
			E[a].push_back(Y);
			}
		}
	for (int i=0;i<26;i++) {
		//cout<<i<<" "<<B[i]<<" "<<C[i]<<endl;
		ats+=B[i]*C[i];}
	for (int i=0;i<26;i++) {
		//cout<<i<<" "<<D[i].size()<<endl;
		solve(D[i],E[i],ats);
		}}
	return;
	}

