typedef struct trie_node{
    int to[30];
    bool end=false;
}trie_node;
vector<trie_node> trie_tree;

int change_char_to_int(char trie_ca){ // small alphabets
    return (int)trie_ca-(int)'a';
}

void trie_init(){
    trie_node trie_tn;
    memset(trie_tn.to,-1,sizeof(trie_tn.to));
    trie_tree.push_back(trie_tn);
}

vector<int> nodes;
int cnt[1100000][30];

void trie_set(string &trie_sa,int trie_a,int trie_b,int trie_n=0){
    nodes.push_back(trie_n);
    if(trie_a==trie_b){
        trie_tree[trie_n].end=true;
        return;
    }
    int trie_t=change_char_to_int(trie_sa[trie_a]);
    int trie_p=trie_tree[trie_n].to[trie_t];
    if(trie_p!=-1){
        trie_set(trie_sa,trie_a+1,trie_b,trie_p);
        return;
    }
    trie_node trie_tn;
    memset(trie_tn.to,-1,sizeof(trie_tn.to));
    trie_tree[trie_n].to[trie_t]=trie_tree.size(),trie_p=trie_tree.size();
    trie_tree.push_back(trie_tn);
    trie_set(trie_sa,trie_a+1,trie_b,trie_p);
}

void trie_set(string &trie_sa){
    nodes.clear();
    trie_set(trie_sa,0,trie_sa.size());
}

int trie_find(string &trie_sa,int trie_a,int trie_b,bool trie_sub=true,int trie_n=0){
    if(trie_a==trie_b){
        return trie_n;
    }
    if(trie_n>=trie_tree.size())return -1;
    int trie_t=change_char_to_int(trie_sa[trie_a]);
    int trie_p=trie_tree[trie_n].to[trie_t];
    if(trie_p==-1)return -1;
    return trie_find(trie_sa,trie_a+1,trie_b,trie_sub,trie_p);
}

bool trie_find(string &trie_sa,bool trie_sub=true){
    return trie_find(trie_sa,0,trie_sa.size(),trie_sub);
}


int main(){
    int n,m;
    int i,j,k;
    int a,b,c;
    LL s=0;
    string sa;
    trie_init();
    cin>>n;
    vector<P> v1;
    vector<string> v2;
    for(i=0;i<n;i++){
        cin>>sa;
        v1.push_back(make_pair(sa.size(),i));
        reverse(sa.begin(),sa.end());
        v2.push_back(sa);
    }
    sort(v1.rbegin(),v1.rend());
    for(i=0;i<n;i++){
        sa=v2[v1[i].second];
        trie_set(sa);
        a=0;
        for(j=(int)sa.size()-1;j>=0;j--){
            a|=1<<((int)sa[j]-(int)'a');
            for(k=0;k<26;k++){
                if(a&(1<<k))cnt[nodes[j]][k]++;
            }
        }
        char ca=sa.back();
        sa.pop_back();
        a=trie_find(sa,true);
        if(a!=-1)s+=(LL)cnt[a][(int)ca-(int)'a']-1;
    }

    cout<<s<<endl;
}

