    cin.tie(nullptr);            // インタラクティブ問題ではコメントアウトすること

    ll n = in1;
    vector<string> s = qin(n);
    FOREACH(x, s) reverse(ALLOF(x));
    sort(ALLOF(s), [](string &s, string &t) { return s.size() < t.size(); });

    vector g(1, vector<ll>());
    vector c(1, vector<ll>(26, -1));
    vector prev(1, pair(-1, -1));
    vector<ll> dp(1, 0);
    constexpr ll root = 0;

    auto DEBUG_SHOW = [&](ll x) -> string {
        string r;
        while (x != root) {
            auto [j, u] = prev[x];
            r.push_back('a' + j);
            x = u;
        }
        return r;
    };

    ll ans = 0;
    FOREACH(t, s) {
        multiset<ll> ms;
        FOREACH(x, t) ms.insert(x - 'a');
        for (ll now = root, i = 0; i < t.size(); i++) {
            ll j = t[i] - 'a';
            ms.erase(ms.find(j));
            REP(k, 26) if (k != j) if (ms.find(k) != ms.end()) {
                if (c[now][k] != -1) {
                    ans += dp[c[now][k]];
                }
            }
            ans += dp[now];
            if (c[now][j] == -1) {
                c[now][j] = g.size();
                g[now].push_back(g.size());
                g.emplace_back();
                c.emplace_back(26, -1);
                dp.push_back(0);
                prev.emplace_back(j, now);
            }
            now = c[now][j];
            if (i+1 == t.size()) {
                dp[now]++;
            }
        }
    }
    say(ans);


}

