template <typename T>
size_t make_hash(const T &v) { return hash<T>()(v); }
void hash_combine(size_t &h, const size_t &v) { h ^= v + 0x9e3779b9 + (h << 6) + (h >> 2); }
template <typename T>
struct hash_container {
  size_t operator()(const T &v) const {
    size_t h = 0;
    for (const auto &e : v) hash_combine(h, make_hash(e));
    return h;
  }
};
template <typename T, typename U>
struct hash<pair<T, U>> {
  size_t operator()(const pair<T, U> &v) const {
    size_t h = make_hash(v.first);
    hash_combine(h, make_hash(v.second));
    return h;
  }
};
template <typename... T>
struct hash<vector<T...>> : hash_container<vector<T...>> {};
