struct TRIE {
	vector<string> S;//配列は1-indexed
	ll N;

	vvll graph;//0-indexed(0はroot)
	vector<char> ch;

	TRIE(vector<string> S0) {
		S = S0;
		ll N = S.size() - 1;

		repn(i, N)S[i] += '*';

		graph.push_back({});
		ch.push_back('.');

		repn(i, N) {
			ll v = 0;
			rep(j, S[i].size()) {
				ll newv = -1;

				for (ll w : graph[v]) {
					if (ch[w] == S[i][j]) { newv = w; break; }
				}

				if (newv == -1) {
					newv = graph.size();
					graph.push_back({});
					graph[v].push_back(newv);
					ch.push_back(S[i][j]);
				}
				v = newv;

			}
		}
	}
};


int main() {
	ll N;
	cin >> N;
	vector<string> S(N + 1);
	repn(i, N) {
		cin >> S[i];
		reverse(S[i].begin(), S[i].end());
	}

	TRIE t(S);
	vvll g = t.graph;
	vector<char> col = t.ch;
	ll M = g.size();
	//cout << M << endl;

	//rep(i, M)cout << col[i] << endl;
	//rep(v, M)for (ll w : g[v]) { cout << v << " "<<w << endl; }

	vll par(M, -1);
	vll sz(M, 0);
	for (ll v = M - 1; v >= 0; v--) {
		if (g[v].size() == 0) { sz[v] = 1; }
		for (ll w : g[v]) {
			par[w] = v;
			sz[v] += sz[w];
		}
	}

	vvll count(M, vll(26, 0));
	for (ll v = M - 1; v >= 0; v--) {
		for (ll w : g[v]) {
			rep(j, 26)count[v][j] += count[w][j];
		}

		if (col[v] != '.' && col[v] != '*') {
			count[v][col[v] - 'a'] = sz[v];
		}

	}

	ll ans = 0;
	rep(v, M) {
		if (col[v] != '*') { continue; }
		char c = col[par[v]];
		ll w = par[par[v]];

		//cout << w << " " << c << endl;

		ans += count[w][c - 'a'] - 1;
	}

	cout << ans << endl;
}

