template <typename Container>
class roll_hash {
 public:
  roll_hash(const Container& cont = Container()) : muls_(rand2()) {
    init(cont);
  }

  roll_hash(const roll_hash& other, const Container& cont)
      : muls_(other.muls_) {
    init(cont);
  }

  int size() const { return (int)pows_[0].size() - 1; }

  void push_back(typename Container::value_type val) {
    for (int k = 0; k < 2; ++k) {
      pows_[k].push_back(
          (int)((long long)pows_[k].back() * muls_[k] % MODS[k]));
      prefs_[k].push_back(
          (int)(((long long)prefs_[k].back() * muls_[k] + val) % MODS[k]));
    }
  }

  void pop_back() {
    for (int k = 0; k < 2; ++k) {
      pows_[k].pop_back();
      prefs_[k].pop_back();
    }
  }

  // Hashes the closed range [first, last].
  long long operator()(int first, int last) const {
    assert(first <= last);
    ++last;
    std::array<long long, 2> vals;
    for (int k = 0; k < 2; ++k) {
      vals[k] = prefs_[k][last] -
                (long long)prefs_[k][first] * pows_[k][last - first] % MODS[k];
      if (vals[k] < 0) {
        vals[k] += MODS[k];
      }
    }
    return (vals[0] << 32) + vals[1];
  }

  long long operator()(const Container& other) const {
    std::array<long long, 2> vals = {0, 0};
    for (int k = 0; k < 2; ++k) {
      for (int i = 0; i < (int)other.size(); ++i) {
        vals[k] = (vals[k] * muls_[k] + other[i]) % MODS[k];
      }
    }
    return (vals[0] << 32) + vals[1];
  }

 private:
  static constexpr std::array<int, 2> MODS = {2'147'483'629, 2'147'483'647};
  std::array<int, 2> muls_;
  std::array<std::vector<int>, 2> pows_, prefs_;

  static std::array<int, 2> rand2() {
    std::mt19937 thanos(
        (std::uint_fast32_t)std::chrono::high_resolution_clock::now()
            .time_since_epoch()
            .count());
    std::uniform_int_distribution<int> snap(1'000'000, 1'000'000'000);
    return std::array{snap(thanos), snap(thanos)};
  }

  void init(const Container& cont) {
    int n = (int)cont.size();
    for (int k = 0; k < 2; ++k) {
      pows_[k].reserve(n + 1);
      pows_[k].push_back(1);
      for (int i = 0; i < n; ++i) {
        pows_[k].push_back((int)((long long)pows_[k][i] * muls_[k] % MODS[k]));
      }
      prefs_[k].reserve(n + 1);
      prefs_[k].push_back(0);
      for (int i = 0; i < n; ++i) {
        prefs_[k].push_back(
            (int)(((long long)prefs_[k][i] * muls_[k] + cont[i]) % MODS[k]));
      }
    }
  }
};

int main() {
  auto start_time = std::chrono::steady_clock::now();
  std::mt19937 thanos(
      (std::uint_fast32_t)start_time.time_since_epoch().count());
  std::ios::sync_with_stdio(false);
  std::cin.tie(nullptr);
  std::cout.precision(24);
  int n;
  cin >> n;
  vector<string> ss(n);
  for (string& s : ss) {
    cin >> s;
    reverse(s.begin(), s.end());
  }
  roll_hash<string> base;
  vector<long long> poss, vals;
  for (const string& s : ss) {
    vector<int> cnt(26);
    for (char c : s) {
      ++cnt[c - 'a'];
    }
    roll_hash hasher(base);
    for (int i = 0; i < ssize(s); ++i) {
      for (int j = 0; j < 26; ++j) {
        if (cnt[j] > 0) {
          hasher.push_back((char)('a' + j));
          poss.push_back(hasher(0, i));
          hasher.pop_back();
        }
      }
      hasher.push_back(s[i]);
      --cnt[s[i] - 'a'];
    }
    assert(hasher.size() == ssize(s));
    vals.push_back(hasher(0, hasher.size() - 1));
  }
  sort(poss.begin(), poss.end());
  long long ans = -n;
  for (long long x : vals) {
    auto [lower, upper] = equal_range(poss.begin(), poss.end(), x);
    ans += upper - lower;
  }
  cout << ans << '\n';
  return 0;
}

