  for (auto i : s) c[i - 'a']++;
  for (int j = 0; j < 26; j++) cnt[idx][j] += (c[j] > 0);
  for (auto i : s) {
    c[i - 'a']--;
    if (!nxt[idx][i - 'a']) {
