struct no {
    int nxt[30];
    int f[30];

    int next(char c){
        if(nxt[c-'a'] == -1)
            return -1;
        return nxt[c-'a'];
    }

    no() {
        for(int a=0;a<30;a++){
            nxt[a] = -1;
            f[a] = 0;
        }
    }
};

vector<no> trie;

inline int create(int u, char c){
    if(trie[u].next(c) == -1){
        trie[u].nxt[c-'a'] = trie.size();
        trie.push_back(no()); 
    }
    return trie[u].next(c);
}

inline void add(string s){ // adds string s to trie
     int u = root; 
     int freq[30];
     memset(freq, 0, sizeof(freq));
     for(char c: s)
         freq[c-'a']++;
     for(int a=0;a<30;a++)
        trie[u].f[a] += (freq[a] > 0);
     for(char c: s){
        u = create(u, c);
        freq[c-'a']--;
        for(int a=0;a<30;a++){
            trie[u].f[a] += (freq[a] > 0);
        }
     }
}

inline void init(){
    trie.clear();
    trie.push_back(no());
    root = 0;
}


void print() { // prints the whole trie
    for(int i=0;i<trie.size();i++){
        printf("i %d nxt: ", i); 
        for(int a=0;a<30;a++){
            if(trie[i].nxt[a] == -1) continue;
            printf("(%c %d) ", 'a'+a, trie[i].nxt[a]); 
        }
        puts("");
    }
}


inline int query(string s){
    int u = root; 
    for(int a=0;a+1<s.size();a++){
        u = trie[u].next(s[a]);
        if(u == -1)
            return 0;
    }
    return trie[u].f[s.back()-'a'];
}

