const int MAX = 1e6 + 5;
int go[MAX][26];
bool leaf[MAX];
int sz = 1;
void add(string s){
    int cur = 0;
    for(auto c: s){
        if(!go[cur][c - 'a']) go[cur][c - 'a'] = sz++;
        cur = go[cur][c - 'a'];
    }
    leaf[cur] = true;
}
int main(){
    ios_base::sync_with_stdio(0); cin.tie(0);
    int n; cin >> n;
    vector<string> s(n);
    for(int i = 0; i < n; i++) cin >> s[i], reverse(s[i].begin(), s[i].end());
    for(auto& x: s) add(x);
    ll ans = 0;
    for(int i = 0; i < n; i++){
//        vector<int> cnt(26);
        int cnt[26];
        for(auto c: s[i]){
            cnt[c - 'a']++;
        }
        int cur = 0;
        for(int j = 0; j < (int) s[i].size() - 1; j++){
            for(int c = 0; c < 26; c++){
                if(cnt[c] && go[cur][c]){
                    ans += leaf[go[cur][c]];
                }
            }
            cnt[s[i][j] - 'a']--;
            if(!go[cur][s[i][j] - 'a']) break;
            cur = go[cur][s[i][j] - 'a'];
        }
    }
    cout << ans << '\n';
    return 0;
}

