using namespace std;

struct node {
	long long cnt;
	node *children[26];

public:
	node() {
		cnt = 0;
		for (int i = 0; i < 26; i++)
			children[i] = nullptr;
	}
};

string info[MAXN];

bool comp(string a, string b) {
	return a.length() > b.length();
}
int main() {
#ifdef orange
    freopen("input.txt", "r", stdin);
#endif
	int n;
	cin >> n;
	for (int i = 0; i < n; i++)
		cin >> info[i];
	sort(info, info + n, comp);
//	for (int i = 0; i < n; i++)
//		cout << info[i] << "\n";
	node *trie = new node;
	long long ans = 0;
	for (int i = 0; i < n; i++) {
		node *curr = trie;
		for (int j = info[i].length() - 1; j >= 0; j--) {
			int n = info[i][j] - 'a';
			if (curr->children[n] == nullptr)
				curr->children[n] = new node;
			curr = curr->children[n];
		}
	//	cout << i << " " << curr->cnt << "\n";
		ans += curr->cnt;
		curr = trie;
		int last[26];
		fill(last, last + 26, -1);
		for (int j = 0; j < info[i].length(); j++) {
			last[info[i][j] - 'a'] = j;
		}
		deque<int> lastIdx;
		for (int z = 0; z < 26; z++)
			if (last[z] != -1)
				lastIdx.push_back(last[z]);
		sort(lastIdx.begin(), lastIdx.end(), greater<int>());
//        for (int a : lastIdx) cout << a << " ";
//        cout << endl;
		for (int j = info[i].length() - 1; j >= 0; j--) {

			if (lastIdx.size() && lastIdx.front() == j)
				lastIdx.pop_front();
			for (int a : lastIdx) {
				node *branch = curr;
				int n = info[i][a] - 'a';
				if (branch->children[n] == nullptr)
					branch->children[n] = new node;
				branch = branch->children[n];
				branch->cnt++;
			}

			int next = info[i][j] - 'a';
			curr->cnt++;
			if (curr->children[next] == nullptr) {
				curr->children[next] = new node;
			}
			curr = curr->children[next];
		}
	}
	cout << ans << "\n";

}

