int N;
bool chk[26];
ll ans, d[MAXN * 5];
map<int, int> mp[26];
string S[MAXN];
pair<int, int> A[MAXN];

int main() {
	ios::sync_with_stdio(0); cin.tie(0);
	cin >> N;
	for(int i=1; i<=N; i++) {
		cin >> S[i];
		A[i].fi = S[i].size();
		A[i].se = i;
	}
	sort(A+1, A+1+N);

	d[0] = 1;
	for(int i=1; i<=1e6; i++) d[i] = 31LL * d[i-1] % MOD;

	for(int i=1; i<=N; i++) {
		string s = S[A[i].se];
		string t = s; reverse(t.begin(), t.end());

		ll v = 0, tmp;
		for(int j=0; j<t.size(); j++) {
			v = (v + d[j] * t[j]) % MOD;
		}
		int n = s.size();
		tmp = (v - d[n-1] * t[n-1] + MOD) % MOD;

		memset(chk, 0, sizeof(chk));
		for(int j=0; j<s.size(); j++) {
			v = (v - d[n-j-1] * t[n-j-1] + MOD) % MOD;
			chk[s[j]-'a'] = 1;
			for(int a=0; a<26; a++) if(chk[a]) {
				ans += mp[a][v];
			}
		}
		mp[s[0]-'a'][tmp]++;
	}
	cout << ans;
}

