bool isP(string s1, string s2)
{
    string a,b;
    if(s1.size()==s2.size())return s1==s2;
    s1.size()>s2.size() ?( a= s1 ,b=s2): (a=s2, b=s1);

    int i=0,j=0, k=abs(s1.size()-s2.size());

    for(int i=0;i<a.size() && j<b.size();i++)
        if(k>0&&a[i]==b[j])j++,i++,k--;
        else if(k>0) k--;
        else if(k==0&& a[i]==b[j])j++;
        else break;

    return j==b.size();

}

