struct Trie {
	std::vector<std::vector<int>> g;
	std::vector<std::vector<int>> laz;
	std::vector<int> sz;
	int p;

	Trie() : p(0) {
		g.emplace_back(std::vector<int>(26, -1));
		laz.emplace_back(std::vector<int>(26, 0));
		sz.emplace_back(0);
		++p;
	}

	// trieに文字列sを追加する
	void add(const std::string& s) {
		size_t par = 0;
		++sz[0];
		for (size_t i = 0; i < s.size(); ++i) {
			if (i + 1 == s.size()) {
				++laz[par][s[i] - 'a'];
			}
			if (g[par][s[i] - 'a'] == -1) {
				g.emplace_back(std::vector<int>(26, -1));
				laz.emplace_back(std::vector<int>(26, 0));
				sz.emplace_back(0);
				g[par][s[i] - 'a'] = p++;
			}
			par = g[par][s[i] - 'a'];
			++sz[par];
		}
	}

	// 今見ている頂点から次の文字を検索する(なければ-1)
	int next(size_t par, char c) {
		return g[par][c - 'a'] == -1;
	}

	// sがTrieのprefixか判定する
	bool find(const std::string & s) {
		int p = 0;
		for (size_t i = 0; i < s.size(); ++i) {
			p = next(p, s[i]);
			if (p == -1) return false;
		}
		return true;
	}
};

signed main() {
	INIT;

	VAR(int, n);
	VEC(std::string, s, n);

	Trie tr;
	REP(i, n) {
		std::reverse(ALL(s[i]));
		tr.add(s[i]);
	}

	ans = -n;
	auto rec = [&](auto && f, int v) -> void {
		REP(c, 26) {
			if (tr.g[v][c] == -1) continue;
			int to = tr.g[v][c];
			REP(d, 26) {
				if (tr.laz[v][d] == 0) continue;
				if (c == d) ans += (i64)tr.sz[to] * tr.laz[v][d];
				else tr.laz[to][d] += tr.laz[v][d];
			}
			f(f, to);
		}
	};
	rec(rec, 0);
	OUT(ans)BR;

	return 0;
}

