    bool leaf = false;
	Node(){ }
	Node(Node* n):Node() { par = n; }
	Node* make(string& str, vector<int>& azs, int idx = -1){
        if(idx >= 0){
            ch = str[idx];
            azs[ch - 'a']--;
        }
        for(int i = 0; i < 26; i++){
            nums[i] += azs[i] > 0;
        }
        printde(ch, nums);
		if((int)str.size() == idx + 1){ leaf = true; return this; }
		char next = str[idx + 1];
		if(!dests.count(next)){
			dests[next] = new Node(this);
		}
		return dests[next]->make(str, azs, idx + 1);
	}

	ll calc(){
        ll ret = 0;
        printde(ch, dests.size());
        if(leaf){
            ret = par->nums[ch - 'a'] - 1;
            printde(ch, ret, par->ch, par->nums[ch - 'a']);
        }
        for(auto& dest : dests){
            ret += dest.second->calc();
        }
        return ret;
    }
};

struct Trie {
    struct Node {
        char ch;
        map<char, int> dests;
        int parentIdx;
        int nums[26] = {};
        bool leaf = false;
        bool isRoot(){ return !ch; }
    };
    vector<Node> nodes;
    void add(string& s, vector<int>& azs, int sidx = -1, int nidx = 0, int pidx = -1){
        if(nidx >= (int)nodes.size()){
            nodes.push_back({});
        }
        auto& dests = nodes[nidx].dests;
        nodes[nidx].ch = sidx >= 0 ? s[sidx] : 0;
        nodes[nidx].parentIdx = pidx;

        if(!nodes[nidx].isRoot()){
            azs[nodes[nidx].ch - 'a']--;
            for(int i = 0; i < 26; i++){
                nodes[nidx].nums[i] += azs[i] > 0;
            }
        }
        // printde(nodes[nidx].ch, nodes[nidx].nums);

		if(sidx + 1 == (int)s.size()){ nodes[nidx].leaf = true; return; }
		char next = s[sidx + 1];
		if(!dests.count(next)){
            dests[next] = nodes.size();
            add(s, azs, sidx + 1, nodes.size(), nidx);
		}else{
            add(s, azs, sidx + 1, dests[next], nidx);
        }
        printde(nodes[nidx].ch);
        // printde(nodes[nidx].ch, nodes[nidx].dests);
    }

    ll calc(int nidx = 0){
        ll ret = 0;
        printde(nodes[nidx].ch, nodes[nidx].dests);
        if(nodes[nidx].leaf){
            ret = nodes[nodes[nidx].parentIdx].nums[nodes[nidx].ch - 'a'] - 1;
            // printde(nodes[nidx].ch, ret, nodes[nodes[nidx].parentIdx].ch, nodes[nodes[nidx].parentIdx].nums[nodes[nidx].ch - 'a']);
        }
        for(auto& dest : nodes[nidx].dests){
            ret += calc(dest.second);
        }
        return ret;
    }
};

