using namespace std;

struct trie{
	struct node{
		vector<int> nextNode;
		vector<int> v;
		node(){
			nextNode.resize(26,-1);
			v.resize(26,0);
		}
	};
	vector<node> nodes;

	trie(){
		nodes.push_back(node());
	}

	void add(string &S,char lastChar,int currentPos = 0,int currentNode=0){

		if(currentPos==S.size()){
			nodes[currentNode].v[encode(lastChar)]++;
			return;
		}

		int c = encode(S[currentPos]);
		if(nodes[currentNode].nextNode[c]==-1){
			nodes[currentNode].nextNode[c] = nodes.size();
			nodes.push_back(node());
		}

		int nextNode = nodes[currentNode].nextNode[c];
		add(S,lastChar,currentPos+1,nextNode);

		return;
	}

	int get_value(string &S,vector<int> &mask,int currentPos = 0,int currentNode=0){
		int ret = 0;
		for(int i=0;i<26;i++){
			if((mask[currentPos]>>i)&1){
				ret += nodes[currentNode].v[i];
			}
		}

		if(currentPos==S.size())return ret;

		int c = encode(S[currentPos]);
		if(nodes[currentNode].nextNode[c]==-1){
			return ret;
		}

		int nextNode = nodes[currentNode].nextNode[c];
		return ret + get_value(S,mask,currentPos+1,nextNode);

	}

	int encode(char c){
		return c-'a';
	}


};

