ll compute_hash(string s,ll p,ll m)
{
    ll mult=1;
    ll ans=0;
    for(int i=0;i<s.length();i++)
    {
        ans+=(s[i]*mult);
        ans%=m;
        mult*=p;
        mult%=m;
    }
    return ans;
}
void solve()
{
    ll n;
