const ll MOD1 = 1e9 + 7;
const ll MOD2 = 1e9 + 9;
const ll p = 47;
const ll K = 2e9;

vpll sufHashes(string s){
    int n = s.length();
    vpll h(n);
    ll h1 = 0, h2 = 0;
    forr(i, n - 1){
        ll x = s[i] - 'a' + 1;
        h1 = (h1 * p + x) % MOD1;
        h2 = (h2 * p + x) % MOD2;
        h[i] = {h1, h2};
    }
    h.pb({0, 0});
    return h;
}

void solve() {
    int n;
    cin >> n;
    vs a(n);
    forn(i, n) cin >> a[i];
    vvpll h;
    unordered_set<ll> hashes;
    vvi pos(n, vi(26, 1e9));
    forn(i, n){
        forn(j, a[i].length()){
            int c = a[i][j] - 'a';
            if (pos[i][c] == 1e9) pos[i][c] = j;
        }
    }
    forn(i, n){
        h.pb(sufHashes(a[i]));
        hashes.insert(h[i][0].F * K + h[i][0].S);
    }
    ll ans = 0;
    forn(i, n){
        int l = a[i].length();
        forn1(j, a[i].length()){
            l--;
            pll h0 = h[i][j + 1];
            forn(c, 26){
                if (pos[i][c] <= j){
                    pll H = {(h0.F * p + c + 1) % MOD1, (h0.S * p + c + 1) % MOD2};
                    if (hashes.count(H.F * K + H.S)){
                        ans++;
                    }
                }
            }
        }
    }
    cout << ans << '\n';
}

