struct TriNode{
	unordered_map<char,int> t;
	bool f;
	unordered_map<char,TriNode *> children;
	TriNode(){
		f = false;
	}
};


struct Trie{
	TriNode *root;
	Trie(){
		root = new TriNode();
	}
};

void solve(){
	int n;
	cin>>n;
	vector<string> t(n);
	for(int i=0;i<n;i++) cin>>t[i];

	sort(t.begin(),t.end(),[](string &a,string &b){return a.size() < b.size();});
	vector<vector<int>> idx(n,vector<int>(26,MOD));
	for(int i=0;i<n;i++){
		int tn = t[i].size();
		for(int j=0;j<tn;j++){
			idx[i][t[i][j]-'a'] = min(idx[i][t[i][j]-'a'],j);
		}
	}

	auto tree = Trie();
	LL res = 0;
	for(int i=0;i<n;i++){
		int tn = t[i].size();
		auto cur = tree.root;
		for(int j=(tn-1);j>0;j--){
			for(auto item:cur->t){
					char cc = item.first;
					int cnt = item.second;
					if(idx[i][cc-'a']<=j){
						res += cnt;
					}
			}
			auto p = cur->children[t[i][j]];
			if(p==nullptr){
				cur->children[t[i][j]] = new TriNode();
				cur = cur->children[t[i][j]];
				continue;
			}else{
				cur = cur->children[t[i][j]];
			}
		}
		if(cur->children[t[i][0]] == nullptr){
				cur->children[t[i][0]] = new TriNode();
			}
			cur->t[t[i][0]]++;
	}

	cout<<res<<endl;
}

