        reverse(s.begin(), s.end());
        int mylen = s.size() - 1;
        ll ret = 0;
        rets.clear();
        for(int j=0;j<s.size();j++){
            ret *= mykake;
            ret += s[j] - 'a' + 25;
            ret %= mymod;
            rets.pb(ret);
        }
        ll myhash;
        if (s.size() == 1){
            myhash = 0;
        } else {
            myhash = rets[s.size() - 2];
        }
        int c = s.back() - 'a';
        ans += st[P(myhash * 26 + c, mylen)];
        table.clear();
        for(int j=0;j<26;j++){
            table.pb(-INF);
        }
        for(int j=0;j<s.size();j++){
            table[s[j] - 'a'] = max(table[s[j] - 'a'], (ll)j);
        }
        for(int k=0;k<26;k++){
            if (table[k] != -INF) st[P(k,0)] ++;
        }
        for(int j=0;j<s.size()-1;j++){
            ret = rets[j];
            if (!exist[j + 2]) continue;
            ll idx = ret * 26;
            for(int k=0;k<26;k++){
                if (table[k] != -INF && cexist[j + 2][k] && table[k] >= j + 1) st[P(idx, j+1)]++;
                idx++;
            }
        }
    }
    p(ans);
    return;
}

