void insert(trie* itr, string& s, int& mask, int id = 0) {
	if(id < s.size()) {
		int c = s[id]-'a';
		if(itr->children[c] == nullptr) {
			itr->children[c] = new trie;
		}
		insert(itr->children[c], s, mask, id+1);
		mask |= (1 << c);
		if(id+1 < s.size()) {
			REP(i, 26) {
				if(mask & (1 << i)) ++itr->have[i];
			}
		}
		// cout << s << ' ' << id << endl;
		// REP(i, 26) cout << itr->have[i] << ' ';
		// cout << endl;
	} else {
		itr->word = true;
	}
}

void dfs(trie* itr) {
	REP(i, 26) {
		if(itr->children[i] == nullptr) continue;
		if(itr->children[i]->word) {
			ans += itr->have[i];
		}
		dfs(itr->children[i]);
	}
}

