        return rt->cnt[x-'a'];
    }
    else
    {
        int xx=ss[i]-'a';
            if(rt->children[xx]==NULL)
            {
                rt->children[xx]=create();
                return search(rt->children[xx],ss,x,i+1);
            }
            else
            {
                return search(rt->children[xx],ss,x,i+1);

            }
        }

}
