{
    rt->depth=d;
    for(int j=0;j<26;j++)
    {
        if(rt->children[j]!=NULL)
        {
            dfs1(rt->children[j],d+1,y);

        }
    }

}
ll dfs(struct node*rt,int k)
{
    ll ans=0;ll cnt=0;
    for(int j=0;j<26;j++)
    {
        if(rt->children[j]!=NULL)
        {
            ans=ans+dfs(rt->children[j],k);
            cnt=cnt+rt->children[j]->rem;
        }
    }
    cnt=cnt+rt->rem;
    rt->rem=cnt%k;
    ans=ans+(cnt/k)*(rt->depth);
    return ans;
}
