int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  ll N;
  cin >> N;
  vector<ll> SN(N);
  vector<ll> pat;
  rolling_hash("a");
  vector<ll> dp(pow(10, 6) + 10);
  dp.at(0) = 1;
  for (ll i = 0; i < dp.size() - 1; ++i) {
    dp.at(i + 1) = (dp.at(i) * B) % M;
  }
  for (ll i = 0; i < N; ++i) {
    string S;
    cin >> S;
    ll rs = rolling_hash(S);
    SN.at(i) = rs;
    vector<bool> alfa(26, false);
    for (ll j = 0; j < S.size(); ++j) {
      alfa.at(S.at(j) - 'a') = true;
      rs -= ((S.at(j) - 'a' + pp) * dp.at(S.size() - j - 1)) % M;
      if (rs < 0) {
        rs += M;
      }
      rs %= M;
      for (ll k = 0; k < 26; ++k) {
        ll now_rs = rs;
        if (alfa.at(k)) {
          now_rs += ((k + pp) * dp.at(S.size() - j - 1)) % M;
          now_rs %= M;
          pat.push_back(now_rs);
          // cout << now_rs << "\n";
        }
      }
    }
    // cout << "\n";
  }
  sort(pat.begin(), pat.end());
  ll ans = -N;
  for (ll i = 0; i < N; ++i) {
    ans += upper_bound(pat.begin(), pat.end(), SN.at(i)) - lower_bound(pat.begin(), pat.end(), SN.at(i));
  }
  cout << ans << "\n";
}

