	for(int i=0;i<n;i++)
	{
		scanf("%s",&str);
		S[i]=str;
		reverse(S[i].begin(),S[i].end());
		trie *at=&root;
		for(int j=0;j<S[i].size();j++)
		{
			int pos=-1;
			for(int k=0;k<at->ch.size();k++) if(at->ch[k]==S[i][j]) pos=k;
			if(pos==-1)
			{
				pos=at->ch.size();
				at->ch.push_back(S[i][j]);
				at->nd.push_back(new trie());
			}
			at=at->nd[pos];
		}
		at->end=true;
	}
	int ret=0;
	for(int i=0;i<n;i++)
	{
		memset(cnt,0,sizeof(cnt));
		for(int j=0;j<S[i].size();j++) cnt[S[i][j]-'a']++;
