namespace Trie{
    int tot = 1;
    int trie[MAXN][26],size[MAXN],end[MAXN];

    void Insert(string s){
        int len = s.length();
        int now = 1;
        for(int i = 0;i < len;i++){
            int ch = s[i] - 'a';
            if(!trie[now][ch])
                trie[now][ch] = ++tot;
            now = trie[now][ch];
        }
        end[now] = 1;
    }

    void dfs(int u,int fa){
        size[u] = end[u];
        for(int i = 0;i < 26;i++){
            int v = trie[u][i];
            if(v){
                dfs(v,u);
                size[u] += size[v];
            }
        }
    }

    int Query(string s){
        int len = s.length();
        int now = 1;
        for(int i = 0;i < len - 1;i++){
            int ch = s[i] - 'a';
            now = trie[now][ch];
        }
        return size[now];
    }
}

