auto meld(tuple<int,int,int> s,tuple<int,int,int> t){
    constexpr int64_t base=10007;
    constexpr int64_t mod[2]={1000000007LL,999999937LL};
    int64_t a[2]={};
    a[0]=(int64_t(get<0>(s))*base%mod[0]+get<0>(t))%mod[0];
    a[1]=(int64_t(get<1>(s))*base%mod[1]+get<1>(t))%mod[1];
    return make_tuple(a[0],a[1],get<2>(s)+get<2>(t));
}
auto make(char c){
    return make_tuple(int(c),int(c),1);
}
