int main(){
	auto f=[](auto s){return get<0>(s)^get<1>(s);};
	vector<__gnu_pbds::gp_hash_table<pair<int,int>,int,decltype(f)>>m(1000000,__gnu_pbds::gp_hash_table<tuple<int,int,int>,int,decltype(f)>(f));
	int n;
	cin>>n;
	vector<tuple<int,int,int>>v(n,empty());
	for(int i=0;i<n;++i){
		string s;
		cin>>s;
		reverse(all(s));
		vector<int>cnt(26,0);
		for(int j=0;j<(int)s.size();++j)cnt[s[j]-'a']++;
		bitset<26>b;
		for(int j=0;j<26;++j)if(cnt[j])b[j]=1;
		for(int j=0;j<(int)s.size();++j){
			for(int k=b._Find_first();k<26;k=b._Find_next(k)){
				auto e=meld(v[i],make(k+'a'));
				m[get<2>(e)][{get<0>(e),get<1>(e)}]++;
			}
			v[i]=meld(v[i],make(s[j]));
			cnt[s[j]-'a']--;
			if(!cnt[s[j]-'a'])b[s[j]-'a']=0;
		}
	}
	int64_t ans=0;
	for(int i=0;i<n;++i){
		ans+=m[get<2>(v[i])][{get<0>(v[i]),get<1>(v[i])}]-1;
	}
	cout<<ans<<endl;
}

