	cin.tie(0);
	cin >> N;
	vector<string> V;
	init();
	for(int i = 0; i < N; ++i){
		string s; cin >> s;
		V.push_back(s);
		insertString(s, s.size() - 1);
	}
	doDP();
	ll cc = 0;
	for(string s : V){
		int v = query(s, s.size() - 1);
		//cerr << s << ": " << v << endl;
		cc += v - 1;
	}
	cout << cc << endl;
	return 0;
}

