struct Trie {
	struct Node {
		Node *ch[26] = {NULL, NULL};
		int cnt[26] = { 0 };
	};
	Node *root = NULL;
	Node *nodes = new Node[1000001];
	int head = 0;
	void add(std::string s) {
		std::reverse(s.begin(), s.end());
		Node **node = &root;
		std::vector<Node *> path;
		s.push_back((char) 0);
		for (auto i : s) {
			if (!*node) *node = nodes + head++;
			path.push_back(*node);
			if (!i) continue;
			node = &(*node)->ch[i - 'a'];
		}
		s.pop_back();
		std::reverse(s.begin(), s.end());
		path.pop_back();
		std::reverse(path.begin(), path.end());
		bool used[26] = { 0 };
		for (int i = 0; i < (int) s.size(); i++){
			used[s[i] - 'a'] = true;
			for (int j = 0; j < 26; j++) path[i]->cnt[j] += used[j];
