			}
			std::cerr << "  --- " << std::endl;*/
		}
		// std::cerr << std::endl;
	}
	int cnt(std::string s) {
		std::reverse(s.begin(), s.end());
		char back = s.back();
		s.pop_back();
		// std::cerr << s << "  +  " << back << std::endl;
		Node *cur = root;
		for (auto i : s) {
			if (!cur) return 0;
			cur = cur->ch[i - 'a'];
		}
		if (!cur) return 0;
		return cur->cnt[back - 'a'];
	}
};

