void insert(int l, int r, int id) {
	int x = 0; 
	v[0].push_back(id);
	for (int i = l; i <= r; i++) {
		int c = s[i]-'a';
		if (!ch[x][c]) ch[x][c] = ++tot;
		x = ch[x][c];
		v[x].push_back(id);
	}
}

void solve(int l, int r, int id) {
	int x = 0;
	for (int i = l; i < r; i++) {
		int c = s[i]-'a';
		x = ch[x][c];
	}
	for (auto y : v[x]) {
		if (y == id || R[y] - L[y] + 1 <= r - l + 1) continue;
		if (ok[L[y] + r - l][s[r]-'a']) ans++;
	}
}

int main() {
	read(n);
	for (int i = 1; i <= n; i++) {
		scanf("%s", t + 1);
		m = strlen(t + 1);
		L[i] = len + 1;
		for (int j = m; j; j--) {
			s[++len] = t[j];
		}
		R[i] = len; 
		insert(L[i], R[i], i);
	} 
	for (int i = 1; i <= n; i++) {
		for (int j = R[i]; j >= L[i]; j--) {
			for (int k = 0; k < 26; k++) ok[j][k] = ok[j+1][k];
			ok[j][s[j]-'a'] = 1;
		}
	}
	for (int i = 1; i <= n; i++) {
		solve(L[i], R[i], i);
	}
	printf("%lld\n", ans);
	return 0;
}

