struct node {
	node* lt[26];
	vector<ll> cnt;
	vector<ll> nds;
	ll cntH = 0;
};

node* rt = new node();

void add(string& s, int ind, node* cur) {
	if (ind == s.size() - 1) {
		if (cur->cnt.size() == 0) {
			cur->cnt.resize(26);
		}
		cur->nds.push_back(s.back() - 'a');
	}
	else {
		if (cur->lt[s[ind] - 'a']) {
			add(s, ind + 1, cur->lt[s[ind] - 'a']);
		}
		else {
			cur->lt[s[ind] - 'a'] = new node();
			add(s, ind + 1, cur->lt[s[ind] - 'a']);
		}
	}
}

void add2(string& s, int ind, node* cur) {
	if (cur->cnt.size() == 0) {
		cur->cnt.resize(26);
	}
	cur->cnt[s[ind] - 'a']++;
	if (ind == s.size() - 1) {
		return;
	}
	else {
		if (cur->lt[s[ind] - 'a']) {
			add2(s, ind + 1, cur->lt[s[ind] - 'a']);
		}
		else {
			cur->lt[s[ind] - 'a'] = new node();
			add2(s, ind + 1, cur->lt[s[ind] - 'a']);
		}
	}
}

void bfs(node* cur, node* par = 0) {
	for (int i = 0; i < 26; i++) {
		if (cur->lt[i]) {
			bfs(cur->lt[i], cur);
		}
	}

	if (par != 0) {
		for (int i = 0; i < 26; i++) {
			par->cnt[i] += cur->cnt[i];
		}
	}
}

ll ans(node* cur) {
	ll ret = 0;
	for (auto c : cur->nds) {
		ret += cur->cnt[c] - 1;
	}
	if (ret == 1) {
		cout << "";
	}
	for (int i = 0; i < 26; i++) {
		if (cur->lt[i]) ret += ans(cur->lt[i]);
	}

	return ret;
}

