const int NMAX = 1001000;
const int SIGMA = 26;

bool leaf[NMAX];
int mov[NMAX][SIGMA];
int nxt = 1;

void add(const string &s) {
	int cur = 0;
	for (auto &c : s) {
		int idx = c - 'a';
		if (mov[cur][idx] == -1) {
			cur = mov[cur][idx] = nxt++;
		} else {
			cur = mov[cur][idx];
		}
	}

	leaf[cur] = true;
}


ll cnt[SIGMA + 1];
ll ans = 0LL;

void dfs(int v, int ch) {
	ll tmp = 0LL;

	if(ch != -1) {
		tmp = cnt[ch];
		cnt[SIGMA] += tmp;
		cnt[ch] = 0LL;

		if (leaf[v]) {
			ans += cnt[SIGMA];
		}
	}

	rep(c, SIGMA) {
		if(mov[v][c] != -1) {
			cnt[c] += leaf[mov[v][c]];
		} 
	}

	rep(c, SIGMA) {
		if(mov[v][c] != -1) {
			dfs(mov[v][c], c);
		}	
	}

	rep(c, SIGMA) {
		if(mov[v][c] != -1) {
			cnt[c] -= leaf[mov[v][c]];
		}  
	}

	if(ch != -1) {
		cnt[SIGMA] -= tmp;
		cnt[ch] = tmp;
	}

}

