        }
    }
    for (int i = 1; i < n; ++i){
        for (int j = 0; j < 26; ++j){
            a[i][j] += a[i - 1][j];
        }
    }
    res = 0;
    for (int i = 0; i < n; ++i){
        ll low = i, high = n;
        string ss = s[i].substr(0, s[i].size() - 1);
        while(low + 1 < high){
            ll mid = low + high >> 1;
            ll fl = 1;
            if(s[mid].size() <= ss.size()){
