class rollinghash {
public:
    string s;
    ll base1 = 1007, base2 = 2009;
    ll mod1 = 1000000007, mod2 = 998244353;
    VL hash1, hash2, power1, power2;
    rollinghash(const string& _s) {
        s = _s;
        int n = s.size();
        hash1.resize(n + 1);
        hash2.resize(n + 1);
        power1.resize(n + 1, 1);
        power2.resize(n + 1, 1);
        FOR(i, 0, n) {
            hash1[i + 1] = (hash1[i] * base1 + s[i]) % mod1;
            hash2[i + 1] = (hash2[i] * base2 + s[i]) % mod2;
            power1[i + 1] = (power1[i] * base1) % mod1;
            power2[i + 1] = (power2[i] * base2) % mod2;
        }
    }

    inline pair<ll, ll> hash(int l, int r) const {
        ll res1 = hash1[r] - hash1[l] * power1[r - l] % mod1;
        if (res1 < 0) res1 += mod1;
        ll res2 = hash2[r] - hash2[l] * power2[r - l] % mod2;
        if (res2 < 0) res2 += mod2;
        return { res1, res2 };
    }
};

