bool check(string &key, string &s) {
	if (s.length() < key.length()) return false;
	int i;
	for (i = 0; i < key.length(); i++) {
		if (s[i] != key[i]) {
			return false;
		}
	}
	return true;
}

int findL(int index) {
	string key;
	int i;
	rep(i, (int)s[index].length() - 1) key += s[index][i];

	int ng = -1, ok = index;
	while (ok - ng >= 2) {
		int mid = (ng + ok) / 2;
		if (check(key, s[mid])) ok = mid;
		else ng = mid;
	}
	return ok;
}

int findR(int index) {
	string key;
	int i;
	rep(i, (int)s[index].length() - 1) key += s[index][i];

	int ok = index, ng = n;
	while (ng - ok >= 2) {
		int mid = (ng + ok) / 2;
		if (check(key, s[mid])) ok = mid;
		else ng = mid;
	}
	return ok;
}

void add(int index) {
	int len = s[index].length();

	for (int i = 0; i < len; i++) {
		//TLE
		for (int j = 0; j <= i; j++) {
			cnts[j][s[index][i] - 'a']++;
		}
	}
}

void del(int index) {
	int len = s[index].length();

	for (int i = 0; i < len; i++) {
		//TLE
		for (int j = 0; j <= i; j++) {
			cnts[j][s[index][i] - 'a']--;
		}
	}
}

