struct trie {
    using sitor = string::const_iterator;

    trie* nxt[26];
    int cnt[27];

    trie() { 
        memset(nxt, 0, sizeof(nxt));
        memset(cnt, 0, sizeof(cnt));
    } 

    ~trie() {
        rep(i, 26) if (nxt[i]) delete nxt[i];
    }

    void insert(sitor beg, sitor end) {
        ++cnt[26];
        if (beg == end) return ;
        int cur = beg[0] - 'a';
        if (!nxt[cur]) nxt[cur] = new trie();
        nxt[cur]->insert(++beg, end);
    }

    void cal_cnt() {
        rep(i, 26) {
            if (!nxt[i]) continue;
            nxt[i]->cal_cnt();
            rep(f, 26) cnt[f] += nxt[i]->cnt[f];
            cnt[i] += nxt[i]->cnt[26];
        }
    }

    trie* get(sitor beg, sitor end) {
        if (beg == end) return this;
        int cur = beg[0] - 'a';
        if (!nxt[cur]) return 0;
        return nxt[cur]->get(++beg, end);
    }
};

