const int POOL_SIZE = 1<<20;

struct Node {
    Node *child[26];
    bool isLeaf;
    int mask[26];
    Node *parent;
    Node() : isLeaf(false), parent(0) {
        memset(child, 0, sizeof child);
        memset(mask, 0, sizeof mask);
    }
    Node(Node *parent) : isLeaf(false), parent(parent) {
        memset(child, 0, sizeof child);
        memset(mask, 0, sizeof mask);
    }
    void insert(char *word) {
        if (*word) {
            getChild(*word)->insert(word+1);
        } else {
            isLeaf = true;
        }
    }
    static Node pool[POOL_SIZE];
    static Node *ptr;
    Node* getChild(char c) {
        return child[c-'a'] ? child[c-'a'] : (child[c-'a'] = new(ptr++) Node(this));
    }
} Node::pool[POOL_SIZE], *Node::ptr = pool;

void solve() {
    int N;
    cin >> N;

    vector<string> s(N);
    VI a(N);
    REP(i, N) {
        cin >> s[i];
        a[i] = i;
    }
    sort(ALL(a), [&s](int i, int j) {
        return s[i].size() > s[j].size();
    });

    Node root;
    int l = 0, r = 0;
    LL ans = 0;
    while (l < N) {
        while (r < N && s[a[r]].size() == s[a[l]].size()) {
            r++;
        }
        REPP(i, l, r) {
            string &t = s[a[i]];
            Node *ptr = &root;
            for (int i = t.size() - 1; i > 0; i--) {
                ptr = ptr->getChild(t[i]);
            }
            ans += ptr->mask[t[0] - 'a'];
        }
        while (l < r) {
            string &t = s[a[l]];
            Node *ptr = &root;
            for (int i = t.size() - 1; i >= 0; i--) {
                ptr = ptr->getChild(t[i]);
            }
            bool f[26] = {};
            for (char c : t) {
                REP(k, 26) {
                    ptr->mask[k] += f[k];
                }
                f[c - 'a'] = true;
                ptr = ptr->parent;
            }
            REP(k, 26) {
                root.mask[k] += f[k];
            }
            l++;
        }
    }
    cout << ans << endl;
}

