using namespace std;

class Trie {
public:

    vector<vector<int>> go;
    vector<int> fin, parent;

    Trie() {
        new_node();
    }

    int new_node() {
        go.push_back(vector<int>(26));
        fin.push_back(0);
        parent.push_back(0);
        return fin.size() - 1;
    }

    void push(string &s) {
        int u = 0;

        for (auto x : s) {
            int p = x - 'a';

            if (go[u][p] == 0) {
                int r = new_node();
                go[u][p] = r;
                parent[r] = u;
            }

            u = go[u][p];
        }

        fin[u] = 1;
    }

    long long solve(int s = 0) {
        long long res = 0;

        if (fin[s]) {
            vector<bool> freq(26);
            int p = s, u, d = 0;

            do {
                u = p; p = parent[p]; ++d;

                for (int i = 0; i < 26; ++i) {
                    if (go[p][i] == u)
                        freq[i] = true;

                    if (d >= 2 && freq[i] && go[p][i] && fin[go[p][i]]) {
                        res++;
                    }

                }
            } while (p != 0);
        }

        for (int i = 0; i < 26; ++i) {
            if (go[s][i])
                res += solve(go[s][i]);
        }

        return res;
    }
};

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    int n; cin >> n;

    Trie t;

    for (int i = 0; i < n; ++i) {
        string s; cin >> s;
        reverse(s.begin(), s.end());
        t.push(s);
    }

    long long res = t.solve();

    cout << res << endl;

    return 0;
}

