        for (const auto& t : s) {
            maxim(maxLen, int(t.size()));
        }
        arr<map<pair<int, ll>, int>> pat(maxLen, map<pair<int, ll>, int>());
        vector<ll> hash1;
        for (const auto& t : s) {
            unsigned prefix = setBit(0u, t[0] - 'a');
            StringHash hash(t);
            hash1.push_back(hash.hash(1));
            for (int i : range(2, t.size() + 1)) {
                ll cHash = hash.hash(i);
                prefix = setBit(prefix, t[i - 1] - 'a');
                for (int j : range(26)) {
                    if (isSet(prefix, j)) {
                        pat[t.size() - i][{j, cHash}]++;
                    }
                }
            }
        }
        ll answer = 0;
        int i = 0;
        for (const auto& t : s) {
            answer += pat[t.size() - 1][{t[0] - 'a', hash1[i++]}];
        }
        out.printLine(answer);
    }
};


