class trie {
public:
  trie(size_t max_size) {
    size = 1; // only root
    next.assign(26, vector<int>(max_size, -1));
    end.assign(max_size, false);
    //
    count.assign(26, vector<ll>(max_size, 0ll));
    //
  }

  bool search(string s) {
    int now = 0;
    for (char c : s) {
      if (next[c - 'a'][now] == -1) return false;
      now = next[c - 'a'][now];
    }
    return end[now];
  }

  void insert(string s) {
    int now = 0;
    vector<int> path;
    int checked = 0;
    for (char c : s) {
      path.push_back(now);
      if (next[c - 'a'][now] == -1) next[c - 'a'][now] = size++;
      //
      if ((checked >> (c - 'a') & 1) == 0) {
        checked |= 1 << (c - 'a');
        for (size_t i = 0; i < path.size(); ++i) ++count[c - 'a'][path[i]];
      }
      //
      now = next[c - 'a'][now];
    }
    end[now] = true;
  }
  //
  int solve(string s, char x) {
    int now = 0;
    for (char c : s) now = next[c - 'a'][now];
    return count[x - 'a'][now];
  }
  //

private:
  vector<vector<int>> next;
  vector<bool> end;
  //
  vector<vector<ll>> count;
  //
  int size;
};

