template<typename rh_type>
class RollingHash {
public:
	rh_type mod;
	vector< rh_type > hashed, power;

	inline rh_type mul(rh_type a, rh_type b) const {
		return a * b % mod;
	}

	//RollingHash(vector<ll> &s, rh_type mod = 2147483647, rh_type base = 524287) : mod(mod) {
	RollingHash(const string &s, rh_type mod = 2147483647, rh_type base = 524287) : mod(mod) {
		ll sz = (ll) s.size();
		hashed.assign(sz + 1, 0);
		power.assign(sz + 1, 0);
		power[0] = 1;
		for(ll i = 0; i < sz; i++) {
			power[i + 1] = mul(power[i], base);
			hashed[i + 1] = mul(hashed[i], base) + s[i];
			if(hashed[i + 1] >= mod) hashed[i + 1] -= mod;
		}
	}

	rh_type query(ll l, ll r) const {
		rh_type ret = hashed[r] + mod - mul(hashed[l], power[r - l]);
		if(ret >= mod) ret -= mod;
		return ret;
	}

	rh_type connect(rh_type h1, ll h2, ll h2len) const {
		rh_type ret = mul(h1, power[h2len]) + h2;
		if(ret >= mod) ret -= mod;
		return ret;
	}

	ll LCP(const RollingHash &b, ll l1, ll r1, ll l2, ll r2) {
		ll len = min(r1 - l1, r2 - l2);
		ll low = -1, high = len + 1;
		while(high - low > 1) {
			ll mid = (low + high) / 2;
			if(query(l1, l1 + mid) == b.query(l2, l2 + mid)) low = mid;
			else high = mid;
		}
		return (low);
	}
};

