      ok[now] = ok[now-1]|(1<<num);
    }

    //iより左にjが存在するか
    for(int j=m;j>=0;j--){
      if(j==m){
        //26種類
        for(int k=0;k<26;k++){
          if((ok[j]>>k)&1){
            ull ad = 'a' + k;
            //付け加えたもの
            ull tmp = ((ret*B)%h + ad)%h;
            auto itr = mp.find(tmp);
