class rollinghash {
    ll base1 = 1007, base2 = 2009;
    ll mod1 = 1000000007, mod2 = 998244353;
    VL hash1, hash2, power1, power2;
public:
    rollinghash(const string& s) {
        int n = s.size();
        hash1.resize(n + 1);
        hash2.resize(n + 1);
        power1.resize(n + 1, 1);
        power2.resize(n + 1, 1);
        FOR(i, 0, n) {
            hash1[i + 1] = (hash1[i] * base1 + s[i]) % mod1;
            hash2[i + 1] = (hash2[i] * base2 + s[i]) % mod2;
            power1[i + 1] = (power1[i] * base1) % mod1;
            power2[i + 1] = (power2[i] * base2) % mod2;
        }
    }

    inline pair<ll, ll> hash(int l, int r) const {
        ll res1 = hash1[r] - hash1[l] * power1[r - l] % mod1;
        if (res1 < 0) res1 += mod1;
        ll res2 = hash2[r] - hash2[l] * power2[r - l] % mod2;
        if (res2 < 0) res2 += mod2;
        return { res1, res2 };
    }
};

int main() {
    init();

    int n; cin >> n;
    VS s(n);
    vector<rollinghash> h;
    h.reserve(n);
    FOR(i, 0, n) {
        cin >> s[i];
        h.emplace_back(s[i]);
    }

    map<int, map<pair<ll, ll>, int>> m;
    VI cnt(26);
    {
        set<int> is;
        FOR(i, 0, n) {
            FOR(j, 0, s[i].length()) {
                pair<ll, ll> suf = h[i].hash(j, s[i].length());
                for (auto itr = is.begin(); itr != is.end(); ++itr)
                    ++m[*itr][suf];
                is.insert(s[i][j] - 'a');
            }
            for (auto itr = is.begin(); itr != is.end(); ++itr)
                ++cnt[*itr];
            is.clear();
        }
    }

    ll ans = -n;
    FOR(i, 0, n) {
        if (s[i].length() == 1) {
            ans += cnt[s[i][0] - 'a'];
        }
        else {
            ans += m[s[i][0] - 'a'][h[i].hash(1, s[i].length())];
        }
    }
    print(ans);

    return 0;
}

