        REP(j, v[i].size()) {
            X[v[i][j] - 'a']++;
        }
        for (ll j = v[i].length() - 1; j >= 0; --j) {
            ll t = v[i][j] - 'a';
            X[t]--;
            REP(x, 27) {
                if (X[x] == 0)
