struct Trie {
	bool f;
	bool isend;
	vector<int>siz;
	int cnt;
	Trie *par;
	Trie *next[26];
	Trie():siz(26,0),cnt(0) { isend = false; f = 0; par = (Trie*)0; fill(next, next + 26, (Trie*)0); }
};
Trie *ins(string t, Trie *r) {
	for (int i = 0; i < t.size(); i++) {
		int c = t[i] - 'a';
		if (!r->next[c])r->next[c] = new Trie;
		r->next[c]->par = r;
		r = r->next[c];
		r->f = 1;
		r->cnt++;
		if (i == (int)t.size() - 1)r->isend = true;
	}
	return r;
}
void dfs(Trie *r) {
	REP(i, 26) {
		if (r->next[i]) {
			Trie *nr = r->next[i];
			nr->siz[i] += nr->cnt;
			dfs(nr);
			REP(j, 26)r->siz[j] += nr->siz[j];
		}
	}
}
void show(Trie *r, string &s) {
	cerr << s << endl;
	REP(i, 26) {
		if (r->next[i]) {
			s += (char)(i + 'a');
			show(r->next[i], s);
			s.pop_back();
		}
	}
}
