constexpr int DEBUG = 0;

constexpr int MAX_L = 1000000;

// Supports two operations.
// - Updates a single element.
// - Returns a sum of a range.
// Verified: CF573Div1D
class BinaryIndexedTree {
 private:
  int n;
  vector<int> xs;
 public:
  BinaryIndexedTree(int n) : n(n), xs(n) {}

  // Adds x to the i-th element.
  void Add(int i, int x) {
    int cur = i;
    while (cur < n) {
      xs[cur] += x;
      cur = cur | (cur + 1);
    }
  }

  // Returns a sum of a range [l r).
  int SumOfRange(int l, int r) {
    if (l >= r) return 0;
    if (l > 0) {
      return SumOfRange(0, r) - SumOfRange(0, l);
    }
    int s = 0;
    int i = r - 1;
    while (i >= 0) {
      s += xs[i];
      i = (i & (i + 1)) - 1;
    }
    return s;
  }
};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  cin >> n;
  vector<string> ss(n);
  for (int i = 0; i < n; i++) {
    cin >> ss[i];
    reverse(ss[i].begin(), ss[i].end());
  }
  sort(ss.begin(), ss.end());
  for (const string& s : ss) {
    if (DEBUG) cout << s << endl;
  }

  vector<vector<int>> l_to_is(MAX_L + 1);  // Length to indexes
  for (int i = 0; i < n; i++) {
    l_to_is[ss[i].length()].push_back(i);
  }

  vector<vector<int>> c_count_table(n, vector<int>(26));
  for (int i = 0; i < n; i++) {
    for (char c : ss[i]) {
      c_count_table[i][c - 'a']++;
    }
  }

  vector<BinaryIndexedTree> trees(26, BinaryIndexedTree(n));
  for (int i = 0; i < n; i++) {
    for (int c = 0; c < 26; c++) {
      if (c_count_table[i][c] > 0) {
        trees[c].Add(i, 1);
      }
    }
  }

  deque<int> q;
  for (int l = 1; l <= MAX_L; l++) {
    for (int i : l_to_is[l]) {
      q.push_back(i);
    }
  }

  int64 ans = 0;
  for (int l = 1; l <= MAX_L; l++) {
    for (int string_index : l_to_is[l]) {
      if (DEBUG) cout << "string_index: " << string_index << endl;
      if (l >= 2) {
        string key_1 = ss[string_index].substr(0, ss[string_index].length() - 1);
        string key_2 = key_1;
        key_2[key_2.length() - 1]++;

        int i_1 = distance(ss.begin(), lower_bound(ss.begin(), ss.end(), key_1));
        int i_2 = distance(ss.begin(), lower_bound(ss.begin(), ss.end(), key_2));
        // [i_1, i_2)
        if (DEBUG) cout << "i_1: " << i_1 << " i_2: " << i_2 << endl;
        ans += trees[ss[string_index].back() - 'a'].SumOfRange(i_1, i_2);
      } else {
        ans += trees[ss[string_index].back() - 'a'].SumOfRange(0, n);
      }
    }

    for (int i : q) {
      c_count_table[i][ss[i][l - 1] - 'a']--;
      if (c_count_table[i][ss[i][l - 1] - 'a'] == 0) {
        trees[ss[i][l - 1] - 'a'].Add(i, -1);
      }
    }
    while (!q.empty() && ss[q.front()].length() == l) {
      q.pop_front();
    }
  }
  ans -= n;

  cout << ans << endl;
}

