int ins(string& s) {
    int res = 0;
    vi ctr(26, 0);
    M00(i, sz(s)) ctr[s[i]-'a']++;
    tnode* cur = root;
    M00(i, 26) cur->freqs[i] += (ctr[i] > 0);
    M00d(i, sz(s)) {
        int idx = s[i] - 'a';
