        if(i == 0) {
            res = cur->freqs[idx]-1;
        }
        cur = cur->ch[idx];
        ctr[idx]--;
        M00(j, 26) cur->freqs[j] += (ctr[j] > 0);
    }
    assert(res >= 0);
    return res;
}

