template<int char_size,int base>
struct Trie {
    struct Node {
        vector<int> child,accept;
        int c;
        int common;
        Node(int c):c(c),common(0) {
            child.assign(char_size,-1);
        }
    };
    vector<Node> tree;
    int root = 0;
    Trie() {
        tree.emplace_back(0);
    }
    void insert(const string &s,int id) {
        int node_id = 0;
        for (int i = 0; i < (int)s.size(); ++i) {
            int c = s[i] - base;
            int &next_id = tree[node_id].child[c];
            if (next_id < 0) {
                next_id = (int)tree.size();
                tree.emplace_back(c);
            }
            ++tree[node_id].common;
            node_id = next_id;
        }
        ++tree[node_id].common;
        tree[node_id].accept.push_back(id);
    }
    // insert s to Trie
    void insert(const string &s) {
        insert(s,tree[0].common);
    }
    // return the number of s in Trie
    int search(const string &s) {
        vector<int> alpha(26,0);
        rep(i,s.size()) alpha[s[i] - 'a']++;

        int node_id = 0;
        int ans = 0;
        for (int i = 0;i < (int)s.size(); ++i) {
            rep(j,26) {
                if (alpha[j] && tree[node_id].child[j]) {
                    int x = tree[node_id].child[j];
                    if (tree[x].accept.size() > 0) ++ans;
                } 
            }
            alpha[s[i] - 'a']--;
            int c = s[i] - base;
            int &next_id = tree[node_id].child[c];
            if (next_id < 0) return ans;
            node_id = next_id;
        }
        return ans;
    }
};

