const char START = 'a'; // first letter in alphabet
const int MAX = 1e6 + 5, ALPHA = 26;

int dp[MAX][ALPHA];

struct Trie {

  int root, nodes, nxt[MAX][ALPHA], cnt[MAX];

  void init(){
    root = nodes = 1;
    memset(nxt, 0, sizeof nxt);
    memset(cnt, 0, sizeof cnt);
  }

  void insert(string str){
    int cur = root;
    for(auto c : str){
      if(!nxt[cur][c - START]) nxt[cur][c - START] = ++nodes;
      cur = nxt[cur][c - START];
      cnt[cur]++;
    }
  }

  int find(string str){
    int cur = root;
    for(int i = 0; i + 1 < str.sz; i++){
      char c = str[i];
      if(!nxt[cur][c - START] or !cnt[nxt[cur][c - START]]) return false;
      cur = nxt[cur][c - START];
    }
    int c = str.back() - 'a';
    return dp[cur][c] - 1;
  }

  void erase(string str){ // may need to call find() before
    int cur = root;
    for(auto c : str) {
      cur = nxt[cur][c - START];
      cnt[cur]--;
    }
  }
} T;

