        curr->freq[s[i]-'a']++;
    }
    curr->end = true;
}
void prop(Trie *head,int c){
    Trie *curr = head;
    for(int i=0;i<26;i++){
        if(curr->child[i]!=nullptr){
            prop(curr->child[i],i);
            for(int j=0;j<26;j++){
                curr->freq[j]+=(curr->child[i])->freq[j];
            }
        }
    }
}
