    vvc<bool> A(N, vc<bool>(26));
    map<pair<ull, ll>, ll> mp;

    vc<bool> U(1000005);

    vc<RollingHash> vrh;
    rep(i, N) {
        RollingHash rh(RS[i]);
        vrh.emplace_back(rh);
