            n = nodes[n].chi[s[i]-a];
            nodes[n].x += y;
        }
    }
    T count_prefix(string s){
        int n = 0;
        for(int i=0; i<s.size(); i++){
            if(nodes[n].chi[s[i]-a] == -1) return e;
            n = nodes[n].chi[s[i]-a];
        }
        return nodes[n].x;
    }
};

