    trie.push_back(vector<int>(26, -1));
    on.push_back(vector<int>(26, 0));
    return nodes++;
  };
  auto Insert = [&](const string& s) {
    int cur = 0;
    vector<int> cnt(26);
    for (int i = 0; i < s.size(); ++i)
      ++cnt[s[i] - 'a'];
    for (int i = 0; i < s.size(); ++i) {
      for (int k = 0; k < 26; ++k) {
        on[cur][k] += (cnt[k] > 0 ? 1 : 0);
      }
      int c = s[i] - 'a';
      if (trie[cur][c] == -1) {
        trie[cur][c] = Create();
      }
      cur = trie[cur][c];
      --cnt[c];
    }
  };
  long long ans = 0;
  for (int i = 0; i < n; ++i) {
    // check trie
    int node = 0;
    bool ok = true;
    for (int j = 0; j + 1 < v[i].size(); ++j) {
      if (trie[node][v[i][j] - 'a'] == -1) {
        ok = false;
        break;
      }
      node = trie[node][v[i][j] - 'a'];
    }
    if (ok) {
      ans += on[node][v[i].back() - 'a'];
    }
    Insert(v[i]);
  }
  cout << ans << '\n';
}

