class Trie{
public:
	int ROOT;
	void Insert(char *s) {
		int p = ROOT;
		int len = strlen(s);
		for (int i = 0; i < len; ++i) {
			sum[p]++;
			if (!son[p][s[i] - 'a']) son[p][s[i] - 'a'] = ++cnt;
			p = son[p][s[i] - 'a'];
		}
		sum[p]++;
	}
	int Search(char *s) {
		int p = ROOT;
		int len = strlen(s);
		for (int i = 0; i < len; ++i) {
			if (!son[p][s[i] - 'a']) return 0;	
			p = son[p][s[i] - 'a'];
		}
		return sum[p];
	}
	void Solve(char *s) {
		int len = strlen(s);
		int c = 0;
		for (int i = len - 1; ~i; --i) tmp[c++] = s[i];
		tmp[c] = '\0';
		Insert(tmp);
	}	
	int Ask(char *s) {
		int len = strlen(s);
		int c = 0;
		for (int i = len - 1; ~i; --i) tmp[c++] = s[i];
		tmp[c] = '\0';
		return Search(tmp);
	}
}T[26];
