struct Node
{
    int to[26];
    char c;
    bool final;
};

const int maxN = 1e6 + 47;
Node nodes[maxN];
int cnt[maxN][26];
int nodes_cnt = 1;

void insert(const string& s)
{
    int cur = 0;
    FOR(i, 0, SZ(s))
    {
        int& nxt = nodes[cur].to[s[i] - 'a'];
        if (nxt == 0)
        {
            nxt = nodes_cnt++;
            nodes[nxt].c = s[i];
        }
        cur = nxt;
    }
    nodes[cur].final = true;
}

LL ans = 0;

int dfs(int cur)
{
    int res = 0;
    if (nodes[cur].final)
    {
        cnt[cur][nodes[cur].c - 'a']++;
        res++;
    }
    FOR(c, 0, 26)
    {
        int nxt = nodes[cur].to[c];
        if (nxt)
        {
            int val = dfs(nxt);
            res += val;
            FOR(t, 0, 26)
            {
                if (nodes[nxt].c - 'a' != t)
                    cnt[cur][t] += cnt[nxt][t];
                else
                    cnt[cur][t] += val;
            }
        }
    }
    FOR(c, 0, 26)
    {
        int nxt = nodes[cur].to[c];
        if (nxt && nodes[nxt].final)
        {
            ans += cnt[cur][c] - 1;
        }
    }
    return res;
}

