typedef long long LL;

const int MAXN = 200000;
const int MAXL = 1000000;
const int PRI = 10;
const int MOD = 1000000009;

int N;
int Cnt[30];
int Pow[MAXL + 5];
std::string S[MAXN + 5];

struct Node {
	int cnt[30];
};

std::map<int, Node> Num;

int Hash(const std::string &str, int l, int r) {
	int ret = 0;
	for (int i = l; i <= r; i++)
		ret = ((LL)ret * PRI % MOD + str[i]) % MOD;
	return ret;
}

bool Comp(const std::string &i, const std::string &j) {
	return i.size() < j.size();
}

int main() {
	scanf("%d", &N);
	for (int i = 1; i <= N; i++)
		std::cin >> S[i];
	std::sort(S + 1, S + N + 1, Comp);
//	for (int i = 1; i <= N; i++)
//		std::cout << S[i] << std::endl;
	Pow[0] = 1;
	for (int i = 1; i <= MAXL; i++)
		Pow[i] = (LL)Pow[i - 1] * PRI % MOD;
	LL Ans = 0;
	for (int i = 1; i <= N; i++) {
		int len = S[i].size();
		int key = Hash(S[i], 0, len - 1);
		for (int j = 1; j <= len; j++) {
			Cnt[S[i][j - 1] - 'a']++;
			key = ((key - (LL)Pow[len - j] * S[i][j - 1] % MOD) % MOD + MOD) % MOD;
			if (Num.count(key)) {
				Node cur = Num[key];
				for (int k = 0; k < 26; k++)
					if (Cnt[k])
						Ans += cur.cnt[k];
			}
		}
		for (int j = 0; j < 26; j++)
			Cnt[j] = 0;
//		printf("%d\n", Hash(S[i], 1, len - 1));
		Node &cur = Num[Hash(S[i], 1, len - 1)];
		cur.cnt[S[i][0] - 'a']++;
	}
	printf("%lld", Ans);
	return 0;
}

