struct Trie{
    int a[maxm][26],tot;
    int type[maxm];
    int val[maxm];
    int ed[maxm][26];
    void add(string s){
        int len=s.size();
        int node=0;
        for(int i=len-1;i>=0;i--){
            int v=s[i]-'a';
            if(!a[node][v]){
                a[node][v]=++tot;
                type[tot]=v;
            }
            node=a[node][v];
        }
        val[node]++;
    }
    void dfs(int x){
        for(int i=0;i<26;i++){
            int v=a[x][i];
            if(!v)continue;
            dfs(v);
            val[x]+=val[v];
            for(int j=0;j<26;j++){
                ed[x][j]+=ed[v][j];
            }
        }
        ed[x][type[x]]=val[x];
    }
    void cal(string s){
        int len=s.size();
        int node=0;
        for(int i=len-1;i>=1;i--){
            int v=s[i]-'a';
            node=a[node][v];
        }
        for(int i=0;i<26;i++){
            int v=a[node][i];
            if(!v)continue;
            ans+=ed[v][s[0]-'a'];
        }
    }
}T;
signed main(){
    cin>>n;
    for(int i=1;i<=n;i++){
        cin>>s[i];
        T.add(s[i]);
    }
    T.dfs(0);
    for(int i=1;i<=n;i++){
        T.cal(s[i]);
    }
    ans-=n;
    cout<<ans<<endl;
    return 0;
}
