void add(int i,char *s)
{
  //printf("%d %c\n",i,*s);
  if(*s==0){
    fn[i]=true;
  }
  else if(ch[i][(*s)-'a']==-1){
    ch[i][(*s)-'a']=N;
    for(int x=0;x<26;x++){
      ch[N][x]=-1;
    }
    fn[N]=false;
    N++;
    add(N-1,s+1);
  }
  else{
    add(ch[i][(*s)-'a'],s+1);
  }
}

long long ans;

void count(int i)
{
  ct[i]=(fn[i]?1:0);
  for(int y=0;y<26;y++){
    ex[i][y]=0;
  }
  for(int x=0;x<26;x++){
    int j=ch[i][x];
    if(j==-1)continue;
    count(j);
    ct[i]+=ct[j];
    for(int y=0;y<26;y++){
      if(y==x){
	ex[i][y]+=ct[j];
      }
      else{
	ex[i][y]+=ex[j][y];
      }
    }
  }
  for(int x=0;x<26;x++){
    int j=ch[i][x];
    if(j!=-1&&fn[j]){
      ans+=ex[i][x]-1;
