using namespace std;

int main() {
	int N;
	cin >> N;
	vector<string> S(N);
	for (int i = 0; i < N; ++i) { cin >> S[i]; }

	sort(S.begin(), S.end(), [](auto s, auto t) {
			if (s.size() == t.size()) { return s < t; }
			return s.size() < t.size(); });

	// contain[i][j][k] := S[i]について, j番目までに文字kを含んでいる
	vector<vector<vector<bool>>> contain(N);
	for (int i = 0; i < N; ++i) {
		vector<vector<bool>> tmp(S[i].size(), vector<bool>(26, false));
		for (int j = 0; j < S[i].size(); ++j) {
			tmp[j][S[i][j] - 'a'] = true;
			if (j == 0) { continue; }
			for (int k = 0; k < 26; ++k) {
				tmp[j][k] = tmp[j][k] | tmp[j - 1][k];
			}
		}
		contain[i] = tmp;
	}

	map<string, vector<Int>> mp;
	Int ans = 0;
	for (int i = 0; i < N; ++i) {
		int n = S[i].size();
		for (int j = n; j > 0; --j) {
			string s = S[i].substr(j);
			if (!mp.count(s)) { continue; }
			for (int k = 0; k < 26; ++k) {
				if (!contain[i][j - 1][k]) { continue; }
				ans += mp[s][k];
			}
		}
		string s = S[i].substr(1);
		if (!mp.count(s)) {
			mp[s] = vector<Int>(26, 0);
		}
		mp[s][S[i][0] - 'a'] += 1;
	}
	cout << ans << "\n";

	return 0;
}

