const int N = 26; // changable

struct Trie {
	Trie* child[N];
	int endVal;
	Trie(){
		for(int i = 0; i < N; i++){
			child[i] = NULL;
		}
		endVal = 0;
	}
	~Trie(){
		for(int i = 0; i < N;i ++){
			delete child[i];
		}
	}
} *root = new Trie();

void add(string s){
	Trie* cur = root;
	for(int i = 0; i < s.length(); i++){
		int j = s[i] - 'a';
		if(cur -> child[j] == NULL){
			cur -> child[j] = new Trie();
		}
		cur = cur -> child[j];
	}
	cur -> endVal ++;
}

int search(string s){
	Trie* cur = root;
	for(int i = 0; i < s.length(); i++){
		int j = s[i] - 'a';
		if(cur -> child[j] == NULL) return 0;
		cur = cur -> child[j];
	}
	if(cur == NULL) return 0;
	else return cur -> endVal;
}

long long res(string s){
    Trie* cur = root;
    vector<int> cnt(N, 0);
    long long ans = 0;
    for(int i = 0; i < s.length();i ++){
         cnt[s[i] - 'a'] ++;
    }
    for(int i = 0; i < s.length(); i++){
        for(int k = 'a'; k <= 'z'; k++){
            int jk = k - 'a';
            if(cnt[jk] && cur->child[jk] != NULL) ans += cur->child[jk]->endVal;
        }
        int j = s[i] - 'a';
        if(cur->child[j] == NULL) return ans;
        cur = cur->child[j];
    }
    return ans;
}

