void insert(const string &s)
{
	int len=s.size();
	int u=1;
	trie[u].siz++;
	for(int i=0;i<len;i++)
	{
		int c=s[i]-'a';
		if(!trie[u].ch[c]) trie[u].ch[c]=++tot;
		u=trie[u].ch[c];
		trie[u].siz++;
	}
	return;
}
int res;
void dfs(int u,int c)
{
	if(!u) return;
	for(int i=0;i<26;i++)
		if(i!=c) dfs(trie[u].ch[i],c);
	if(trie[u].ch[c]) res+=trie[trie[u].ch[c]].siz;
	return;
}
