	char c = getchar_unlocked();
	int t = 0, f = 1;
	while (!isdigit(c) && c != EOF)
		f = (c == '-' ? -1 : 1), c = getchar_unlocked();
	while (isdigit(c) && c != EOF)
		t = t * 10 + c - '0', c = getchar_unlocked();
	return t * f;
}

inline void read(char* s) {
	char c = getchar_unlocked();
	while (isspace(c))
		c = getchar_unlocked();
	while (!isspace(c))
		*s++ = c, c = getchar_unlocked();
	*s = '\0';
}

