void add(const string& s) {
	int node = 0;
	for (char ch : s) {
		if (!t[node][ch - 'a'])
			t[node][ch - 'a'] = ++sz;
		node = t[node][ch - 'a'];
	}
	finish[node] = 1;
}

int query(const string& s, int idx) {
	int node = 0, res = 0;
	for (int i = 0; i < s.size(); ++i) {
		for (int j = 0; j < 26; ++j)
			if (((a[idx][i] >> j) & 1) && finish[t[node][j]])
				++res;
		node = t[node][s[i] - 'a'];
	}
	return res - 1;
}

