struct Trie{
    Trie* children[26];
    int is_end;
    int num[26];

    Trie(){
        for(int i = 0; i < 26; ++i){
            children[i] = NULL;
            num[i] = 0;
        }
        is_end = 0;
    }
    Trie* upsert(char ch){
        if(children[ch - 'a'] == NULL)
            children[ch - 'a'] = new Trie();
        return children[ch - 'a'];
    }
    Trie* find(char ch){
        return children[ch - 'a'];
    }
};

