                if(d[j] < i){
                    ++p->num[j];
                    q = p->find('a' + j);
                    if(q)
                        ans += q->is_end;
                }
        }
        ans += (long long)(p->num[s[0] - 'a'] - 1);
        p = p->upsert(s[0]);
        ++p->is_end;
    }
    printf("%lld\n", ans);
    return 0;
}

