        // print(dp[2]);
        // print(dp[3]);

        int tmp = head;

        cntp[tmp]++;
        rep(j,0,26) if(dp[0][j]) cntpc[tmp][j]++;
        // printn(cntpc[tmp],26);

        for(int i = 0; i < s.size(); i++) {
            if(nxt[tmp][s[i] - 'a']) tmp = nxt[tmp][s[i] - 'a'];
            else tmp = nxt[tmp][s[i] - 'a'] = __alloc();

            cntp[tmp]++;
            rep(j,0,26) if(dp[i+1][j]) cntpc[tmp][j]++;
        }
        // print("visiting node ", tmp);
        cnt[tmp]++;
    }

    int count(const string & s) {
        int n=s.size();
        int res=0;

        int tmp = head;
        if(n==1) res+=cntpc[tmp][s.back() - 'a'];
        for(int i = 0; i < s.size(); i++) {
            if(!nxt[tmp][s[i] - 'a']) break;
