    if(id==sz(word)){
        cur->ch.pb(chh);
        return ;
    }
    char mych= word[id];

    if(cur->child.find(mych)==cur->child.end()){
        cur->child[mych]= new trie();
    }
    trie* node = cur->child[mych];
    insertt(node,word,id+1,chh);
}
