typedef unsigned long long ull;
const ull B = 1e9 + 9;

int cnt[26];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> n;

    for (int i = 0; i < n; i++) cin >> s[i];

    sort(s, s + n, [&] (string v, string u) {
        return v.size() < u.size();
    });

    long long res = 0;
    map<ull, int> c;

    for (int i = 0; i < n; i++) {
        ull h = 0;

        for (auto ch: s[i]) cnt[ch - 'a']++;

        for (int j = 0; j < 26; j++) if (cnt[j] > 0) {
            if (c.count(j + 1)) {
                res += c[j + 1];
            }
        }

        ull x = 1;

        for (int j = (int)s[i].size() - 1; j >= 0; j--) {
            h = x * (s[i][j] - 'a' + 1) + h;
            cnt[s[i][j] - 'a']--;

            if (j != s[i].size() - 1 && c.count(h)) {
                res += c[h];
            }

            x *= B;

            for (int k = 0; k < 26; k++) if (cnt[k] > 0) {
                if (j - 1 >= 0 && k == (s[i][j - 1] - 'a')) continue;
                if (c.count(h + x * (k + 1))) {
                    res += c[h + x * (k + 1)];
                }
            }
        }

        c[h]++;
    }

    cout << res << endl;

    return 0;
}

