//ローリングハッシュ
struct RollingHash {
    static const int base1 = 1007, base2 = 2009;
    static const int mod1 = 1000000007, mod2 = 1000000009;
    vector<long long> hash1, hash2, power1, power2;

    // construct
    RollingHash(const string &S) {
        int n = (int)S.size();
        hash1.assign(n + 1, 0);
        hash2.assign(n + 1, 0);
        power1.assign(n + 1, 1);
        power2.assign(n + 1, 1);
        for(int i = 0; i < n; ++i) {
            hash1[i + 1] = (hash1[i] * base1 + S[i]) % mod1;
            hash2[i + 1] = (hash2[i] * base2 + S[i]) % mod2;
            power1[i + 1] = (power1[i] * base1) % mod1;
            power2[i + 1] = (power2[i] * base2) % mod2;
        }
    }

    // get hash of S[left:right]
    inline pair<long long, long long> get(int l, int r) const {
        long long res1 = hash1[r] - hash1[l] * power1[r - l] % mod1;
        if(res1 < 0)
            res1 += mod1;
        long long res2 = hash2[r] - hash2[l] * power2[r - l] % mod2;
        if(res2 < 0)
            res2 += mod2;
        return {res1, res2};
    }
};

void solve() {
    ll n;
    cin >> n;

    vec<string> s(n);
    vec<RollingHash> rh;
    REP(i, n) {
        cin >> s[i];
        rh.push_back(RollingHash(s[i]));
    }

    map<pair<int, P>, ll> mp; //a-[末尾]
    REP(i, n) {
        int d = s[i][0] - 'a';
        auto ret = rh[i].get(1, s[i].size());
        mp[make_pair(d, ret)]++;
    }

    ll ans = 0;
    REP(i, n) {
        vec<bool> used(16, false);
        REP(j, s[i].size()) {
            used[s[i][j] - 'a'] = true;
            P ret = rh[i].get(j + 1, s[i].size());
            REP(k, 26) {
                if(!used[k])
                    continue;
                if(mp.count(make_pair(k, ret))) {
                    ans += mp[make_pair(k, ret)];
                }
            }
        }
    }
    cout << ans - n << en;
}

