    map<pll, ll> mp;
    ll ans = 0;
    rep(i, n) {
        string& t = v[i].second;
        RollingHash rh = RollingHash(t);
        pll p = rh.get();
        ans += mp[p];
        vll c(26);
        rep(j, t.size()) ++c[t[j] - 'a'];
        string _t = "";
        rep(j, t.size()) {
            rep(k, 26) if(c[k] > 0) {
                char ch = 'a' + k;
                rh.add(ch, j);
