node * root;

ll computePairs(node * r) {
    set<char> met;
    met.insert(r->letter);
    ll ans = 0;
    r = r->parent;

    met.insert(r->letter);

    while (r != root) {
        r = r->parent;
        for (node * c : r->children) {
            if (c != nullptr && c->beginpoint && met.count(c->letter))
                ans++;
        }
        met.insert(r->letter);
    }

    return ans;
}

void mktrie() {
    root = new node(nullptr, '0');
    beginpoints.resize(n, nullptr);

