const int N = 200200;
const int M = (int)1e6 + 7;
const int A = 26;
string s[N];
int n;
pii ord[N];
int go[M][A];
int m;
int a[M][A];
int cnt[A];
ll ans = 0;

void solve(int id) {
	int v = 0;
	int L = (int)s[id].length();
	for (int i = 0; i < A; i++)
		cnt[i] = 0;
	for (int i = 0; i < L; i++)
		cnt[(int)(s[id][i] - 'a')]++;
	for (int i = 0; i < L; i++) {
		for (int c = 0; c < A; c++)
			if (cnt[c] > 0)
				ans += a[v][c];
		if (i == L - 1) break;
		int c = (int)(s[id][i] - 'a');
		cnt[c]--;
		if (go[v][c] == 0) go[v][c] = m++;
		v = go[v][c];
	}
	int c = (int)(s[id].back() - 'a');
	a[v][c]++;
}

