		reverse(all(s[i]));
		ord[i] = mp((int)s[i].length(), i);
	}
	sort(ord, ord + n);
	m = 1;
	for (int i = 0; i < n; i++)
		solve(ord[i].second);
	cout << ans << "\n";

	return 0;
}

