struct Node {
    bool isend;
    unordered_map<char, Node*> m;
    Node(): isend(false) {}
    set<int> s;
};
class Trie {
public:
    Node* root;
    /** Initialize your data structure here. */
    Trie(): root(new Node()) {

    }

    /** Inserts a word into the trie. */
    void insert(string word, int n) {
        Node *node = root;
        REP(i,0,word.size()) {
            char c = word[i];
            if (node->m.count(c) == 0) node->m[c] = new Node();

            node->s.insert(n);

            node = node->m[c];
        }
        node->s.insert(n);

        node->isend = true;
    }

    /** Returns if the word is in the trie. */
    bool search(string word) {        
        Node *node = root;
        for (char c: word) {
            if (node->m.count(c) == 0) return false;
            node = node->m[c];
        }
        return node->isend;
    }

    /** Returns if there is any word in the trie that starts with the given prefix. */
    bool startsWith(string prefix) {        
        Node *node = root;
        for (char c: prefix) {
            if (node->m.count(c) == 0) return false;
            node = node->m[c];
        }
        return true;
    }
};

void solve() {
    int n;
    cin >> n;
    VS ss(n);
    REP(i,0,n) cin >> ss[i];
    vector<vector<set<char>>> ds(n);
    REP(i,0,n) {
        set<char> s;
        REP(j,0,ss[i].size()) {
            s.insert(ss[i][j]);
            ds[i].emplace_back(s);
        }
        reverse(all(ds[i]));
    }

    REP(i,0,n) reverse(all(ss[i]));
    Trie t;
    REP(i,0,n) t.insert(ss[i], i);

    LL cnt = 0;
    REP(i,0,n) {
        // dump(i);
        Node *node = t.root;
        bool b = false;
        REP(j,0,ss[i].size()-1) {
            char c = ss[i][j];
            if (node->m.count(c) == 0) {
                b = true;
                break;
            }
            node = node->m[c];
        }
        if (b) continue;
        for (int v: node->s) {
            if (v == i) continue;
            if (ss[v].size() <= ss[i].size()) continue;
            // dump(v);
            // if (ds[v][ss[i].size()-1].count(ss[i][ss[i].size()-1]) > 0) ++cnt;
            if (ds[v][ss[i].size()-1].count(ss[i][ss[i].size()-1]) > 0) ++cnt;
            // dump(ss[v][ss[i].size()-1]);
            // dump(ss[i][ss[i].size()-1]);
        }
    }
    cout << cnt << endl;
}

signed main() {
    solve();

    return 0;
}

