#include <array>
template<typename T>
class RollingHash {
    constexpr static int N = 3;
    array<ll, N> MOD;
    array<ll, N> Base;
    vector<ll> hash[N], pw[N];

public:
    RollingHash(T &s) {
        MOD = {{1000000007, 1000000009, 1234567891}};
        Base = {{1007, 1009, 1013}};
        int n = static_cast<int>(s.size());
        for (int i = 0; i < N; i++) {
            hash[i].resize(n + 1, 0);
            pw[i].resize(n + 1, 1);
            for (int j = 0; j < n; j++) {
                hash[i][j + 1] = (hash[i][j] * Base[i] + s[j]) % MOD[i];
                pw[i][j + 1] = (pw[i][j] * Base[i]) % MOD[i];
            }
        }
    }
    array<ll, N> getHash(int l, int r) {
        array<ll, N> res;
        for (int i = 0; i < N; i++) {
            res[i] = (((hash[i][r] - pw[i][r - l] * hash[i][l]) % MOD[i]) + MOD[i]) % MOD[i];
        }
        return res;
    }
};

#include <map>

const int N = 3;
using ARR = array<ll, N>;

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n;
    cin, n;
    ll ans = -n;
    ARR MOD = {{1000000007, 1000000009, 1234567891}};
    ARR Base = {{1007, 1009, 1013}};

    auto nxt = [&](const ARR &arr, char c) {
        ARR a;
        REP(i, 0, N) {
            a[i] = (arr[i] * Base[i] + c) % MOD[i];
        }
        return a;
    };

    map<ARR, ll> m;
    vector<string> v(n);
    REP(i, 0, n) {
        cin, v[i];
        reverse(v[i].begin(), v[i].end());
    }

    REP(i, 0, n) {
        ARR arr = {0, 0, 0};
        REP(j, 0, v[i].size()) {
            arr = nxt(arr, v[i][j]);
        }
        m[arr]++;
    }

    REP(_, 0, n) {
        string s = v[_];
        vector<int> mp(26, 0);
        int sz = s.size();
        REP(i, 0, sz) {
            mp[s[i] - 'a']++;
        }
        ARR a = {0, 0, 0};
        REP(i, 0, sz + 1) {
            REP(j, 0, 26) {
                if (mp[j] > 0) {
                    ARR cp = nxt(a, 'a' + j);
                    ans += m[cp];
                }
            }
            if (i != sz) {
                mp[s[i] - 'a']--;
                a = nxt(a, s[i]);
            }
        }
    }
    print(ans);

    return 0;
}

