void add(string &s){
    int pos=0;
    rep(i,s.length()){
        if(G[pos][s[i]-'a']!=-1){
            pos=G[pos][s[i]-'a'];
            continue;
        }
        int npos=G.size();
        G[pos][s[i]-'a']=npos;
        G.push_back(vector<int>(26,-1));
        mark.push_back(false);
        pos=npos;
        //cout << pos << " " << s[i] << endl;
    }
    mark[pos]=true;
}

int search(string &s){
    int pos=0;
    rep(i,s.length()){
        pos=G[pos][s[i]-'a'];
    }
    return pos;
}

void dfs(int s){
    rep(k,26){
        if(G[s][k]==-1) continue;
        int t=G[s][k];
        //cout << t << " " << (char)(k+'a') << endl;
        dfs(t);
        rep(l,26){
            if(k!=l) cnt[s][l]+=cnt[t][l];
        }
        cnt[s][k]+=num[t];
        num[s]+=num[t];
    }
    if(mark[s]) num[s]+=1;
}

