const int N = 2e5 + 5;

typedef bitset<26> bst;

struct tp {
	tp *child[26];
	int cnt[26];
	tp() {
		for (int i = 0; i < 26; ++i) {
			child[i] = 0;
			cnt[i] = 0;
		}
	}
}*root;

int n;
char s[10 * N];

bst update(int u, tp *cur) {
	if (u == 0) {
		bst c;
		return c;
	}
	int a = s[u] - 'a';
	if (!cur->child[a]) cur->child[a] = new tp();
	bst b = update(u - 1, cur->child[a]);
	if (!b[a]) b[a] = 1;
	for (int i = 0; i < 26; ++i) {
		cur->cnt[i] += b[i];
	}
	return b;
}

int query(tp *cur, int len) {
	int a = s[len] - 'a';
	if (!cur) {
		return 0;
	}
	if (len == 1) {
		return cur->cnt[a];
	}
	return query(cur->child[a], len - 1);
}

string str[N];

int main() {
	root = new tp();
	read(n);
	LL ans = 0;
	for (int i = 1; i <= n; ++i) {
		cin >> str[i];
		int len = str[i].size();
		for (int j = 0; j < len; ++j) {
			s[j + 1] = str[i][j];
		}
		update(len, root);
	}
	for (int i = 1; i <= n; ++i) {
		int len = str[i].size();
		for (int j = 0; j < len; ++j) {
			s[j + 1] = str[i][j];
		}
		ans += query(root, len);
	}
	printf("%lld\n", ans - n);
    return 0;
}

