class Hash {
    private: 
        int n;
        string str;
        vector<int> pw, invpw, pref;
        int m, base;

    public:
        int fp(int a, int b) {
            int ret = 1;
            while(b) {
                if(b & 1) ret = 1ll * ret * a % m;
                b >>= 1;
                a = 1ll * a * a % m;
            }
            return ret;
        }

        Hash() {}
        Hash(string &_str, int _base, int _m) {
            str = _str;
            n = str.size();
            base = _base;
            m = _m;
            pw.resize(n, 1);
            invpw.resize(n, 1);
            pref.resize(n + 1, 0);
            for(int i = 1; i < n; i++) {
                pw[i] = 1ll * pw[i - 1] * base % m;
                invpw[i] = fp(pw[i], m - 2);
            }
            for(int i = 0; i < n; i++) {
                pref[i + 1] = (pref[i] + 1ll * pw[i] * str[i] % m) % m;
            }
        }

        int get(int i, int len) {
            int ret = (1ll * pref[i + len] - pref[i]) % m;
            ret = 1ll * ret * invpw[i] % m;
            if(ret < 0) ret += m;
            return ret;
        }
};

