    });
    map<pair<ll, ll>, ll> cnt[26];
    ll ans = 0;
    for(int i = 0; i < N; i++) {
        int sz = s[i].size();
        reverse(ALL(s[i]));
        RollingHash rh(s[i]);
        if(sz == 1) {
            cnt[s[i][0] - 'a'][make_pair(0LL, 0LL)]++;
            continue;
        }
        vector<int> exist;
        int num = 0;
        for(int j = 0; j < sz; j++) {
            num |= (1 << (s[i][j] - 'a'));
            exist.emplace_back(num);
        }
        reverse(ALL(exist));
        for(int j = 0; j < sz - 1; j++) {
            for(int k = 0; k < 26; k++) {
                if(exist[j] & (1 << k)) {
                    if(cnt[k].count(rh.get(0, j)) == 0) {
                        continue;
                    }
                    ans += cnt[k][rh.get(0, j)];
                }
            }
        }
