template<long long iden, long long size>
struct Trie{
  struct Node{
    vector<ll>next,idx;
    vector<ll>al;
    ll num;
    Node():num(0){
       next.assign(size,-1);
       al.assign(size,0);
    }
  };
  vector<Node>data;
  Trie(){
    data.emplace_back();
  }
  void add(const string &s, ll id){
    ll pos=0;
    vector<bool>tmp(26);
    vector<ll>history;
    for(ll i=0;i<s.size();i++){
      history.PB(pos);
      ll c = s[i] - iden;
      if(data[pos].next[c]==-1){
        data[pos].next[c]=data.size();
        data.emplace_back();
      }
      data[pos].num++;
      pos = data[pos].next[c];
    }
    data[pos].num++;
    data[pos].idx.push_back(id);
    rrep(i,0,s.size()){
      if(!tmp[s[i]-iden]){
        data[history[i]].al[s[i]-iden]++;
        tmp[s[i]-iden]=true;
      }
    }
  }
  ll ret=0;
  void search(const string &s){
    ll pos=0;
    for(ll i=0;i+1<s.size();i++){
      ll c = s[i] - iden;
      if(data[pos].next[c]==-1)break;
      pos = data[pos].next[c];
    }
    ll nxt=s.back()-iden;
    //cout<<s spa str[pos]<<endl;
    //debug(data[pos].al,26);
    ret+=data[pos].al[nxt]-1;
  }
  vector<ll>v;
  void dfs(ll pos, ll d){
    for(ll i=0;i<size;i++){
      if(data[pos].next[i]!=-1){
        dfs(data[pos].next[i], d+1);
        rep(j,0,size)data[pos].al[j]+=data[data[pos].next[i]].al[j];
      }
    }
  }
  vector<string>str;
  void build_str(ll pos=0,string s=""){
    while(str.size()<=pos)str.push_back("");
    str[pos]=s;
    for(ll i=0;i<size;i++){
      if(data[pos].next[i]!=-1){
        build_str(data[pos].next[i],s+char(i+iden));
      }
    }
  }
};
