int trie[M][26] , mark[M][26];

vector<string>vec;
int n , id = 1;

void Insert(string &s){
    int row = 1;
    vector<int>nodes;
    for(int i = 0;i < s.size();i++){
        int d = s[i] - 'a';
        if(trie[row][d] == 0){
            trie[row][d] = ++id;
        }
        row = trie[row][d];
        nodes.push_back(row);
    }

    int cnt[26];MEM(cnt,0);
    for(int i = s.size() - 1;i >= 0;i--){
        int d = s[i] - 'a';
        int now = nodes[i];
        cnt[d] = 1;
        for(int j = 0;j < 26;j++){
            mark[now][j] += cnt[j];
        }
    }
    for(int j = 0;j < 26;j++){
        mark[1][j] += cnt[j];
    }
}
LL query(string &s){
    int row = 1;
    for(int i = 0;i < (int)s.size() - 1;i++){
        int d = s[i] - 'a';
        row = trie[row][d];
        if(row == 0)return 0;
    }
//    debug(row);
    int d = s.back() - 'a';
    LL ans = 0;
    for(int i = 0;i < 26;i++){
        int now = trie[row][i];
        if(now == 0)continue;
        ans += mark[now][d];
    }

    return ans;
}
