void solve(){
    int n;
    cin >> n;
    string a[n];
    map<int, map<int, int>> mp;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        int m = a[i].size();
        int pref[m][30];
        memset(pref, 0, sizeof(pref));
        for (int j = 0; j < m; ++j) {
            pref[j][a[i][j] - 'a'] = 1;
            if (j)
                for (int k = 'a';k <= 'z'; ++k)
                    pref[j][k - 'a'] += pref[j - 1][k - 'a'];
        }
        int now = 0;
        for (int k = 'a'; k <= 'z'; ++k) {
            if (pref[m - 1][k - 'a'])
                mp[now][k]++;
            }
        for (int j = m - 1; j > 0; --j) {
            now = (now * p + a[i][j] - 'a' + 1) % mod;
            for (int k = 'a'; k <= 'z'; ++k) {
                if (pref[j - 1][k - 'a'])
                    mp[now][k]++;
            }
        }
    }
    int ans = 0;
    for (int i = 0; i < n; ++i) {
        int now = 0;
        for (int j = a[i].size() - 1; j > 0; --j) {
            // cout <<
            now = (now * p + a[i][j] - 'a' + 1) % mod;
        }
        ans += mp[now][a[i][0]] - 1;
    }
    cout << ans << endl;
}

