struct Trie {
	bool f;
	bool isend;
	int siz[26];
	int cnt;
	int ch;
	Trie *par;
	Trie *next[26];
	Trie() :cnt(0) { REP(i, 26)siz[i] = 0; isend = false; f = 0; par = (Trie*)0; fill(next, next + 26, (Trie*)0); }
};
Trie *ins(string t, Trie *r) {
	for (int i = 0; i < t.size(); i++) {
		int c = t[i] - 'a';
		if (!r->next[c])r->next[c] = new Trie;
		r->next[c]->par = r;
		r = r->next[c];
		r->f = 1;
		r->cnt++;
		r->ch = c;
		if (i == (int)t.size() - 1)r->isend = true;
	}
	return r;
}
