void insert(string &s) {
    for (int j = 0; j < 26; j++) pre[0][j] = s[0] - 'a' == j;
    for (int i = 1; i < s.size(); i++)
        for (int j = 0; j < 26; j++)
            pre[i][j] = pre[i - 1][j] | (s[i] - 'a' == j);
    trie *cur = root;
    for (int i = s.size() - 1; i >= 0; i--) {
        if (cur->son[s[i] - 'a'] == NULL) cur->son[s[i] - 'a'] = new trie;
