	for(int i=1; i<=1e6; i++) d[i] = 31LL * d[i-1] % MOD;

	for(int i=1; i<=N; i++) {
		string s = S[A[i].se];
		string t = s; reverse(t.begin(), t.end());

		ll v = 0, tmp;
		for(int j=0; j<t.size(); j++) {
			v = (v + d[j] * t[j]) % MOD;
		}
		int n = s.size();
		tmp = (v - d[n-1] * t[n-1] + MOD) % MOD;

		memset(chk, 0, sizeof(chk));
		for(int j=0; j<s.size(); j++) {
			v = (v - d[n-j-1] * t[n-j-1] + MOD) % MOD;
			chk[s[j]-'a'] = 1;
			for(int a=0; a<26; a++) if(chk[a]) {
				ans += mp[a][pii(n-j-1, v)];
			}
		}
		mp[s[0]-'a'][pii(n-1, tmp)]++;
	}
	cout << ans;
}

