class Trie {
  vector<vector<int>> trie;
  vector<int> mask;

public:
  Trie() {
    createNode();
  }

  int getRoot() {
    return 0;
  }

  int next(int state, char c) {
    assert(state < int(trie.size()));
    int ci = c - 'a';
    // cout << "nya" << " " << state << " " << ci << endl;
    if (trie[state][ci] == 0) {
      trie[state][ci] = createNode();
      // cout << "c: " << createNode()<< endl;
      // cout << trie[state][ci] << endl;
    }
    assert(trie[state][ci] > 0);
    return trie[state][ci];
  }

  int get_mask(int state) {
    return mask[state];
  }

  void add_mask(int state, char c) {
    mask[state] |= 1 << (c - 'a');
  }

private:
  int createNode() {
    int node_id = trie.size();
    trie.push_back(vector<int>(26));
    mask.push_back(0);
    // cout << "create: " << node_id << endl;
    return node_id;
  }
};


