int change_char_to_int(char trie_ca){ // small alphabets
    return (int)trie_ca-(int)'a';
}

void trie_init(){
    trie_node trie_tn;
    memset(trie_tn.to,-1,sizeof(trie_tn.to));
    trie_tree.push_back(trie_tn);
}

vector<int> nodes;
