void trie_set(string &trie_sa,int trie_a,int trie_b,int trie_n=0){
    nodes.push_back(trie_n);
    if(trie_a==trie_b){
        trie_tree[trie_n].end=true;
        return;
    }
    int trie_t=change_char_to_int(trie_sa[trie_a]);
    int trie_p=trie_tree[trie_n].to[trie_t];
    if(trie_p!=-1){
        trie_set(trie_sa,trie_a+1,trie_b,trie_p);
        return;
    }
    trie_node trie_tn;
    memset(trie_tn.to,-1,sizeof(trie_tn.to));
    trie_tree[trie_n].to[trie_t]=trie_tree.size(),trie_p=trie_tree.size();
    trie_tree.push_back(trie_tn);
    trie_set(trie_sa,trie_a+1,trie_b,trie_p);
}

void trie_set(string &trie_sa){
    nodes.clear();
    trie_set(trie_sa,0,trie_sa.size());
}

int trie_find(string &trie_sa,int trie_a,int trie_b,bool trie_sub=true,int trie_n=0){
    if(trie_a==trie_b){
        return trie_n;
    }
    if(trie_n>=trie_tree.size())return -1;
    int trie_t=change_char_to_int(trie_sa[trie_a]);
    int trie_p=trie_tree[trie_n].to[trie_t];
    if(trie_p==-1)return -1;
    return trie_find(trie_sa,trie_a+1,trie_b,trie_sub,trie_p);
}

int trie_find(string &trie_sa,bool trie_sub=true){
    return trie_find(trie_sa,0,trie_sa.size(),trie_sub);
}


