using Hash = __int128;

constexpr Hash MOD = 1e18+9;
constexpr Hash A = 1e9-1;

int main(){
    int n;
    cin>>n;
    vector<string> s(n);
    for(int i=0;i<n;i++) cin>>s[i];

    map<pair<Hash,char>,int> mp;

    for(const auto& ss:s){
        Hash h = 0;
        for(int j=1;j<ss.size();j++){
            h = (h*A + ss[j])%MOD;
        }
        mp[make_pair(h,ss[0])]++;
    }

    ll ans = 0;
    for(const auto& ss:s) {
        vector<int> cnt(26);
        for(auto c:ss) cnt[c-'a']++;
        Hash h = 0;
        Hash a = 1;
        for(int i=ss.size()-1;i>=0;i--){
            for(int j=0;j<26;j++){
                auto key = make_pair(h,char(j+'a'));
                if(cnt[j] && mp.count(key)){
                    ans+=mp[key];
                }
            }
            cnt[ss[i]-'a']--;
            h=(h+ss[i]*a)%MOD;
            a = a*A%MOD;
        }
    }

    cout<<ans-n<<endl;
    return 0;
}

