using namespace std;
const int N=2e5+10;
typedef unsigned long long ull;
#define pb(x) push_back(x) 
vector<int> str[N];
vector<ull> ha[N];

ull base[N];
map<ull,vector<int>> mp;
int cnt[26];
ull GetHash(int i,int x,int y){
    return ha[i][y]-ha[i][x-1]*base[y-x+1];
}
int main(){
    base[0]=1;
    for(int i=1;i<N;++i)base[i]=base[i-1]*133331;
    int n;
    scanf("%d",&n);
    for(int i=1;i<=n;++i){
        str[i].pb(0);
        int ch;
        do{
            ch=getchar();
        }while(isspace(ch));
        do{
            str[i].pb(ch-'a');
        }while(!isspace(ch=getchar()));
        ha[i].resize(str[i].size(),0);

        for(int j=1;j<str[i].size();++j){
            ha[i][j]=ha[i][j-1]*133331+str[i][j]+17;
        }
        ull hash;
        if(str[i].size()==2)
            hash=0;
        else 
            hash=GetHash(i,2,str[i].size()-1);

        if(mp.find(hash)==mp.end())
            mp[hash]=vector<int>(26,0);
        ++mp[hash][str[i][1]];
    }
    ull ans=0;
    for(int i=1;i<=n;++i){
        memset(cnt,0,sizeof(cnt));
        for(unsigned int j=1;j<str[i].size();++j)
            ++cnt[str[i][j]];
        for(unsigned int j=str[i].size();j>1;--j){
            ull hash=0;
            if(j!=str[i].size()){
                hash=GetHash(i,j,str[i].size()-1);
                --cnt[str[i][j]];
            }
            if(mp.find(hash)==mp.end())continue;
            vector<int> &tmp=mp[hash];
            for(int k=0;k<26;++k)
                if(cnt[k]>0){
                    assert(tmp[k]<=1);
                    ans+=tmp[k];
                }


        }
    }
    ans-=n;
    printf("%llu",ans);
    return 0;
}
