template<unsigned MOD>
struct RollingHash{
  //hashed: hashed[0]=0でhashed[i+1]=0~iのハッシュ値
  //hashed[k]=Σ[i=0 to k]s[i]*base^(k-i-1)
  vector<unsigned> hashed,power;
  //↓????
  inline unsigned mul(unsigned a, unsigned b) const{
      unsigned long long x=(unsigned long long) a*b;
      unsigned xh=(unsigned)(x>>32), xl=(unsigned)x,d,m;
      asm("divl %4; \n\t" : "=a" (d), "=d" (m) : "d" (xh), "a" (xl), "r" (MOD));
      return m;
  }
  RollingHash(const string &s, unsigned base=10007){
      int sz=(int)s.size();
      hashed.assign(sz+1,0);
      power.assign(sz+1,0);
      power[0]=1;
      for(int i=0;i<sz;i++){
          power[i+1]=mul(power[i],base);
          //s[i]の値をそのまま足してるから
          //sが数字になろうがアルファベットだろうがok
          hashed[i+1]=mul(hashed[i],base)+s[i];
          if(hashed[i+1]>=MOD) hashed[i+1]-=MOD;
      }
  }
  //[l,r)のハッシュ値の取得
  //abracadabra
  //hashed[7]           =a*base^6+b*base^5+r*base^4+...+d
  //hashed[3]           =a*base^2+b*base  +r
  //hashed[3]*base^(7-3)=a*base^6+b*base^5+r*base^4
  //引くと[l,r)のハッシュ値が求まる
  unsigned get(int l, int r)const{
      unsigned ret=hashed[r]+MOD-mul(hashed[l],power[r-l]);
      if(ret>=MOD)ret-=MOD;
      return ret;
  }
  // h1,h2はハッシュ値
  unsigned connect(unsigned h1, int h2, int h2len) const{
      unsigned ret=mul(h1,power[h2len])+h2;
      if(ret>=MOD) ret-=MOD;
      return ret;
  }
  //l1,r1 : このハッシュの区間[l1,r1)
  //比較したいハッシュbと，それの区間[l2,r2)
  //返り値はLongestCommonPrefixの長さ
  //単純な文字列の比較ならgetして比べる．O(1)とO(log)違うから
  //logは定数じゃない！(戒め)
  int LCP(int l1, int r1, const RollingHash<MOD> &b, int l2, int r2){
      //ニブタンをする
      int len=min(r1-l1,r2-l2);
      int low=-1,high=len+1;
      while(high-low>1){
          int mid=(low+high)/2;
          if(get(l1,l1+mid)==b.get(l2,l2+mid))    low =mid;
          else                                    high=mid;
      }
      return (low);
  }
};
