#define base 100303
#define mod 100000007
#define ll long long 
using namespace std;
const int N=1000010,M=200010;
int n,v[N],c[26];
ll ans;
char s[N];
string str[M];
struct HASH{
	int nt[N],v[N],val[N],hd[N],o=1;
	void ins(string s){
		int tmp=0,t,len=s.size();
		for(int i=len-1;~i;--i)tmp=((ll)tmp*base+s[i])%mod;
		t=tmp%N;
		for(int i=hd[t];i;i=nt[i])if(v[i]==tmp){val[i]++;return;}
		v[o]=tmp;val[o]=1;
		nt[o]=hd[t];hd[t]=o++;
	}
	int que(int x){
		for(int i=hd[x%N];i;i=nt[i])if(v[i]==x)return val[i];
		return 0;
	}
}H;
