template <int char_size, int base>
struct Trie {
    struct Node {
        vector<int> nxt;
        vector<int> accept;
        int c;
        int common;
        vector<int> cmn;
        Node(int c_) : c(c_), common(0) {
            nxt.assign(char_size, -1);
            cmn.assign(27, 0);
        }
    };

    vector<Node> nodes;
    int root;

    Trie() : root(0) {
        nodes.emplace_back(root);
    }

    // 文字列の挿入
    void insert(const string &ward, int ward_id) {
        int node_id = 0;
        for (const auto e: ward) {
            const int c = int(e - base);
            int &nxt_id = nodes[node_id].nxt[c];
            if (nxt_id == -1) {
                nxt_id = (int) nodes.size();
                nodes.emplace_back(c);
            }
            nodes[node_id].common++;
            node_id = nxt_id;
        }
        nodes[node_id].common++;
        nodes[node_id].accept.emplace_back(ward_id);
    }

    void insert(const string &ward, int ward_id, vector<int>& cnt) {
        int node_id = 0;
        for(int i = 0; i < 26; ++i){
            nodes[node_id].cmn[i] += (cnt[i] != 0);
        }
        for (const auto e: ward) {
            const int c = int(e - base);
            int &nxt_id = nodes[node_id].nxt[c];
            if (nxt_id == -1) {
                nxt_id = (int) nodes.size();
                nodes.emplace_back(c);
            }
            nodes[node_id].common++;
            node_id = nxt_id;
            --cnt[c];
            for(int i = 0; i < 26; ++i){
                nodes[node_id].cmn[i] += (cnt[i] != 0);
            }
        }
        nodes[node_id].common++;
        nodes[node_id].cmn[26]++;
        nodes[node_id].accept.emplace_back(ward_id);
    }

    void insert(const string &ward) {
        vector<int> cnt(26);
        for(auto &&e : ward){
            cnt[e - base]++;
        }
        insert(ward, nodes[0].common, cnt);
    }

    // 文字列の検索
    bool search(const string &word, bool prefix = false) {
        int node_id = 0;
        for (const auto e: word) {
            const int c = int(e - base);
            const int nxt_id = nodes[node_id].nxt[c];
            if (nxt_id == -1) {
                return false;
            }
            node_id = nxt_id;
        }
        return ((prefix) ? true : nodes[node_id].accept.size() > 0);
    }

    // 指定した接頭辞 (prefix) を持つ文字列の検索
    bool prefixSearch(const string &prefix) {
        return search(prefix, true);
    }

    // 指定した接頭辞 (prefix) を持つ文字列の総数
    int prefixCount(const string &prefix) {
        int node_id = 0;
        for (const auto e: prefix) {
            const int c = int(e - base);
            const int nxt_id = nodes[node_id].nxt[c];
            if (nxt_id == -1) {
                return 0;
            }
            node_id = nxt_id;
        }
        return nodes[node_id].common;
    }

    int prefixCount(const string &prefix, char x) {
        int node_id = 0;
        for (const auto e: prefix) {
            const int c = int(e - base);
            const int nxt_id = nodes[node_id].nxt[c];
            if (nxt_id == -1) {
                return 0;
            }
            node_id = nxt_id;
        }
        //return nodes[node_id].common;
        return (nodes[node_id].cmn[x - base]);
    }

    // 挿入した文字列の総数
    int count() const {
        return nodes[0].common;
    }

    // 頂点の総数
    int size() const {
        return (int) nodes.size();
    }
};

