const ll HASH_P=2013265921LL;
const ll HASH_Wn=52278LL;
void makehash(vector<ll> &array,vector<ll> &outarray,ll leng)
{
  ll asz=outarray.size();
  ll alast=0;
  ll wi=1;
  for(ll i=0;i<leng;i++){
    alast=(alast+array[asz+i-1]%HASH_P*wi)%HASH_P;
    if (i==leng-1)break;
    wi*=HASH_Wn;
    wi%=HASH_P;
  }
  outarray[asz-1]=alast;

  for(ll i=asz-2;i>=0;i--){
    outarray[i]=(((outarray[i+1]-array[i+leng]*wi)%HASH_P)*HASH_Wn%HASH_P+array[i]+HASH_P)%HASH_P;
  }
}

