struct node{
    char ch;
    vector<node*> next;
    vector<int> sub;
    node(char ch){
        this->ch=ch;
        next.resize(26,NULL);
        sub.resize(26,0);
    }
};
node* head;
void dfs(string &tmp, int s, int e, node* head, unordered_set<int>& indices){
    if(s>e){return ;}
    if(head->next[tmp[s]-'a']==NULL){
        head->next[tmp[s]-'a']=new node(tmp[s]);
    }
    if(indices.find(s)!=indices.end()){
        ++head->sub[tmp[s]-'a'];
    }
    for(int i=0;i<26;++i){
        head->sub[i]-=head->next[tmp[s]-'a']->sub[i];
    }
    dfs(tmp,s+1,e,head->next[tmp[s]-'a'],indices);
    for(int i=0;i<26;++i){
        head->sub[i]+=head->next[tmp[s]-'a']->sub[i];
    }
}

