    int len = (int) a[i].size();
    int pos = i, lo = i + 1, hi = n;
    while (lo <= hi) {
      int mid = (lo + hi) / 2;
      if (get(i, mid) >= len - 1) {
        pos = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
    lim[i] = pos;
    pos = i;
    lo = 1;
    hi = i - 1;
    while (lo <= hi) {
      int mid = (lo + hi) / 2;
      if (get(mid, i) >= len - 1) {
        pos = mid;
        hi = mid - 1;
      } else {
        lo = mid + 1;
      }
    }
