  }
  ll sol = 0;
  for (int i = 1; i <= n; i++) {
    int x = a[i].back() - 'a', need = f[i][x];
    int now = calc(1, 1, n, bg[i], lim[i], x, need);
    sol += now - 1;
  }
  cout << sol << "\n";
  return 0;
}

