template<int char_size>
struct Trie_Node{
    vector<int> next;
    vector<int> accept;
    vector<int> cnt;
    int exist;
    int size;

    Trie_Node() : exist(0){
        next.assign(char_size, -1);
        cnt.assign(char_size, 0);
    }
};

template<int char_size, char base>
struct Trie{
    using Node = Trie_Node<char_size>;
    vector<Node> nodes;
    int root;

    Trie() : root(0){
        nodes.pb(Node());
    }

    void insert(const string &s, int id){
        int now = 0;
        rep(i, sz(s)){
            int c = s[i]-base;
            int &next = nodes[now].next[c];
            if(next == -1){
                next = sz(nodes), nodes.pb(Node());
            }
            nodes[now].exist++, now = next;
        }
        nodes[now].exist++, nodes[now].accept.pb(id);
    }

    void insert(const string &s){
        insert(s, nodes[0].exist);
    }

    bool search(const string &s, bool prefix = false){
        int now = 0;
        rep(i, sz(s)){
            int c = s[i]-base;
            int &next = nodes[now].next[c];
            if(next == -1) return false;
            now = next;
        }
        return (prefix)? true : sz(nodes[now].accept) > 0;
    }

    bool prefix_search(const string &s){
        return search(s, true);
    }

    int count() const {return nodes[0].exist;}

    int size() const {return sz(nodes);}
};

Trie<26, 'a'> trie;

void dfs(int i, int c){
    using Node = Trie_Node<26>;
    Node &now = trie.nodes[i];
    now.size = sz(now.accept);
    fill(all(now.cnt), 0);
    rep(j, 26){
        if(now.next[j] == -1) continue;
        dfs(now.next[j], j);
        Node nt = trie.nodes[now.next[j]];
        now.size += nt.size;
        rep(k, 26){
            if(j == k) now.cnt[k] += nt.size;
            else now.cnt[k] += nt.cnt[k];
        }
    }
}

