		scanf("%s", s + 1);
		int len = strlen(s + 1);
		for (int i = 1; i <= len; ++i) {
			book[Tas].push_back(s[i]);	
		}
		if (len == 1) {
			letsum[s[1] - 'a']++;
		}
		else {
			int h[31];
			for (int i = 0; i <= 30; ++i) h[i] = 0;
			for (int i = 1; i <= len; ++i) {
				if (!h[s[i] - 'a']) { 
					h[s[i] - 'a'] = 1;
					T[s[i] - 'a'].Solve(s + i + 1);
				}
			}
			for (int i = 0; i < 25; ++i) if (h[i] != 0) letsum[i]++;
		}
	}
	for (int Tas = 1; Tas <= n; ++Tas) {
		int len = book[Tas].size();
		for (int i = 1; i <= len; ++i) s[i] = book[Tas][i - 1];
		s[len + 1] = '\0';
		if (len == 1) {
			ans += letsum[s[1] - 'a'] - 1;
		}
		else {
			ans += T[s[1] - 'a'].Ask(s + 2) - 1;
		}
	}
	cout << ans << endl;
	return 0;	
}

