void isgood(string s, vector <int> &C) {
	vector <int> X(26,0);
	for (int i=0;i<s.length();i++) {
		int x=s[i]-'a';
		X[x]++;
		}
	for (int i=0;i<26;i++) {
		if (X[i]>0) {C[i]++;}
		}
	return;
	}

void solve(vector <string> &A, ll &ats) {
	if (A.size()>1) {
	int m=(int)A.size();
	vector <int> B(26,0);
	vector <int> C(26,0);
	vector <vector <string>> D(26);
	for (int i=0;i<m;i++) {
		string s=A[i];
		if ((int)s.length()==1) {int a=s[0]-'a'; B[a]++;}
		else {
			isgood(s,C);
			int a=s[(int)s.length()-1]-'a';
			s.pop_back();
			//cout<<a<<" "<<s<<endl;
			D[a].push_back(s);
			}
		}
	for (int i=0;i<26;i++) {
		//cout<<i<<" "<<B[i]<<" "<<C[i]<<endl;
		ats+=B[i]*C[i];}
	for (int i=0;i<26;i++) {
		//cout<<i<<" "<<D[i].size()<<endl;
		solve(D[i],ats);
		}}
	return;
	}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin>>n;
    ll ats=0;
    vector <string> A(n);
    for (int i=0;i<n;i++) {cin>>A[i];}
    solve(A,ats);
    cout<<ats<<endl;
    return 0;
}

