#define FOR(i, a, b) for(int i = (a); i < (b); ++i)
#define RFOR(i, b, a) for(int i = (b) - 1; i >= (a); --i)

#define SZ(a) (int)((a).size())
#define ALL(a) a.begin(), a.end()

typedef long long LL;
typedef pair<int, int> PII;

const int MAXN = 1 << 18;
const int MAXL = 1 << 20;

string s[MAXN];
vector<vector<int> > mask;
int t[MAXL][26], dp[MAXL][26];
int sz = 1;
int idxes[MAXN];
LL ans;

void add(int v, int idx, int pos)
{
	if(pos == SZ(s[idx]) - 1)
		ans += dp[v][s[idx][pos] - 'a'];
	FOR(j, 0, 26)
		dp[v][j] += (mask[idx][pos] >> j) & 1;
	int& to = t[v][s[idx][pos] - 'a'];
	if(to == 0)
		to = ++sz;
	if(pos + 1 < SZ(s[idx]))
		add(to, idx, pos + 1);
}

int main()
{
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	int n;
	cin >> n;
	mask.assign(n, vector<int>());
	FOR(i, 0, n)
	{
		cin >> s[i];
		reverse(ALL(s[i]));
		mask[i].assign(SZ(s[i]), 0);
		RFOR(j, SZ(s[i]), 0)
		{
			mask[i][j] = (j + 1 == SZ(s[i]) ? 0 : mask[i][j + 1]) | (1 << (s[i][j] - 'a'));
		}
	}
	iota(idxes, idxes + n, 0);
	sort(idxes, idxes + n, [=](int i, int j) {return SZ(s[i]) > SZ(s[j]);});
	FOR(i, 0, n)
	{
		add(1, idxes[i], 0);
	}
	cout << ans << "\n";
	return 0;
}

