template <int char_size, int base>
struct Trie {
    struct Node {
        vector<int> next_node;
        vector<int> accept;
        vector<int> is_exist;
        int c;
        int common;
        Node(int _c) : c(_c), common(0) {
            next_node.assign(char_size, -1);
            is_exist.assign(26, 0);
        }
    };
    vector<Node> nodes;
    int root;
    Trie() : root(0) {
        nodes.push_back(Node(root));
    }

    void insert(const string &word, vector<int> cnt, int word_id) {
        int node_id = 0;
        for (int i = 0; i < word.size(); i++) {
            int c = word[i] - base;
            int &next_id = nodes[node_id].next_node[c];
            if (next_id == -1) {
                next_id = nodes.size();
                nodes.push_back(Node(c));
            }
            ++nodes[node_id].common;
            for (int j = 0; j < 26; ++j) {
                if (cnt[j]) ++nodes[node_id].is_exist[j];
            }
            --cnt[c];
            node_id = next_id;
        }
        ++nodes[node_id].common;
        nodes[node_id].accept.push_back(word_id);
    }
    void insert(const string &word, vector<int> cnt) {
        insert(word, cnt, nodes[0].common);
    }

    int search(const string &word, bool prefix = false) {
        int node_id = 0;
        for (int i = 0; i < word.size() - 1; i++) {
            int c = word[i] - base;
            int &next_id = nodes[node_id].next_node[c];
            if (next_id == -1) {
                return 0;
            }
            node_id = next_id;
        }
        int c = word.back() - base;
        return nodes[node_id].is_exist[c];
    }

    int search_id(const string &word) {
        int node_id = 0;
        for (int i = 0; i < word.size(); i++) {
            int c = word[i] - base;
            int &next_id = nodes[node_id].next_node[c];
            if (next_id == -1) {
                return -1;
            }
            node_id = next_id;
        }
        return node_id;
    }
};

int main(void){
    ll n;
    cin >> n;
    Trie<26, 'a'> trie;
    vector<string> ss(n);
    rep(i, n){
        string &s = ss[i];
        cin >> s;
        reverse(all(s));
        vector<int> cnt(26);
        for (char c : s) ++cnt[c - 'a'];
        trie.insert(s, cnt);
    }

    ll ans = 0;
    rep(i, n) ans += trie.search(ss[i]);
    co(ans - n);

    return 0;
}

