#define RFOR(i,a,b) for (int i=(b)-1;i>=(a);--i)
#define REP(i,n) for (int i=0;i<(n);++i)
#define RREP(i,n) for (int i=(n)-1;i>=0;--i)

using namespace std;

using ll = long long;

struct Node {
    vector<Node *> children;
    Node *parent;
    vector<int> cnt;

    Node() : children(26, nullptr), parent(nullptr), cnt(26) { }
};

int main() {

    cin.tie(0);
    ios::sync_with_stdio(false);

    int N;
    cin >> N;
    vector<string> S(N);
    REP(i, N) {
        cin >> S[i];
    }

    Node trie;
    REP(i, N) {
        int L = S[i].size();
        Node *p = &trie;
        RREP(j, L) {
            int x = S[i][j] - 'a';
            if (p->children[x] == nullptr) {
                p->children[x] = new Node;
                p->children[x]->parent = p;
                //p->children[x]->cnt[x]++;
                p->cnt[x]++;
            }
            p = p->children[x];
        }
        while (p->parent) {
            REP(j, 26) {
                p->parent->cnt[j] += p->cnt[j];
            }
            p = p->parent;
        }
    }

    ll result = 0;
    REP(i, N) {
        int L = S[i].size();
        Node *p = &trie;
        RFOR(j, 1, L) {
            int x = S[i][j] - 'a';
            p = p->children[x];
        }
        int x = S[i][0] - 'a';
        result += p->cnt[x] - 1;
    }

    cout << result << endl;

    return 0;
}

