int main(int argc, char** argv) {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(12);

    int n;
    cin >> n;
    vector<string> S;
    for (int i = 0; i < n; ++i) {
        string s;
        cin >> s;
        S.push_back(s);
    }

    auto cmp = [&](const string& l, const string& r) {
        if (l.length() == r.length()) {
            return l < r;
        }
        return l.length() < r.length();
    };
    sort(S.begin(), S.end(), cmp);

    set<string> M;
    vector<int> cnts(26, 0);
    long long res = 0;
    for (auto& s : S) {
        for (auto c : s) {
            ++cnts[c - 'a'];
        }
        for (char ch = 'a'; ch <= 'z'; ++ch) {
            if (cnts[ch - 'a'] > 0) {
                string t;
                t += ch;
                if (M.count(t) > 0) {
                    ++res;
                }
            }
        }
        int n = s.length();
        string t;
        for (int i = n - 1; i >= 0; --i) {
            t += s[i];
            --cnts[s[i] - 'a'];
            for (char ch = 'a'; ch <= 'z'; ++ch) {
                if (cnts[ch - 'a'] > 0) {
                    t += ch;
                    if (M.count(t)) {
                        ++res;
                    }
                    t.pop_back();
                }
            }
        }

        M.insert(t);
    }

    cout << res << '\n';

    return 0;
}

