                f[j][k] = f[j + 1][k];
            }
            f[j][s[i][j] - 'a'] = 1;  
        } 
        hash1 = 0, hash2 = 0, xar1 = 1, xar2 = 1;
        for(int j = 0; j < (int)s[i].size(); ++j) {
            for(int k = 0; k < 26; ++k) {
                if(f[j][k]) {
                    ++raod[k][{hash1, hash2}];
                }
            }
            hash1 = (hash1 + (ll)xar1 * s[i][j] % MOD1) % MOD1;
            hash2 = (hash2 + (ll)xar2 * s[i][j] % MOD2) % MOD2;
            xar1 = xar1 * p1 % MOD1;
            xar2 = xar2 * p2 % MOD2;
        }
    }
    cout << ans << endl;
}

