using vi = vector<ll>;
using vvi = vector<vi>;

#define all(a) a.begin(), a.end()
#define pb push_back

void solve() {
    int n; cin >> n;
    vector<pair<string, char>> vec(n);
    for (int i = 0; i < n; i++) {
        string s; cin >> s;
        reverse(s.begin() + 1, s.end());
        vec[i].second = s[0];
        vec[i].first = s.substr(1, s.size() - 1);
    }
    sort(all(vec));
    ll M = 999999937;
    ll k = 45;
    vvi hash(n);
    for (int i = 0; i < n; i++) {
        hash[i] = vi(vec[i].first.size() + 1);
        for (int j = 1; j < hash[i].size(); j++) {
            hash[i][j] = hash[i][j - 1] * k + vec[i].first[j - 1];
            hash[i][j] %= M;
        }
    }

    vvi cnt(n, vi(26));
    for (int i = 0; i < n; i++) {
        for (auto c : vec[i].first) {
            cnt[i][c - 'a']++;
        }
    }

    ll res = 0;

    vi st;
    vector<pair<char, int>> query;
    for (int i = 0; i < n; i++) {
        while (!st.empty()) {
            int v = st.back();
            if (hash[v].back() == hash[i][vec[v].first.size()]) {
                break;               
            } else {
                st.pop_back();
                query.pop_back();
            }
        }
        for (auto q : query) {
            if (cnt[i][q.first - 'a'] + (q.first == vec[i].second) >= q.second) res++;
        }
        st.push_back(i);
        query.push_back({vec[i].second, cnt[i][vec[i].second - 'a'] + 1});
    }
    cout << res << endl;
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);
    solve();
}

