{
    int n;
    cin >> n;
    auto trie = Node{'a', {}, {}, vector<count_t>(26), 0};
    for(int i=0; i<n; ++i){
        string s;
        cin >> s;
        reverse(s.begin(), s.end());
        construct(trie, s, 0);
    }
    traverse(trie);
    // print(trie);
    // cout << "\n\n";
    cout << count(trie);
    return 0;
}

