        bor[v].trans[let] = bor.size();
        bor.emplace_back();
      }
      v = bor[v].trans[let];
      path.push_back(v);
    }
    was.assign(26, false);
    for (int j = (int)data[i].length() - 1; j >= 0; --j) {
      int let = data[i][j] - 'a';
      if (was[let]) {
        continue;
      }
      was[let] = true;
      for (int pos = j; pos >= 0; --pos) {
        ++bor[path[pos]].reachable[let];
        //cout << "add v: " << v << " let: " << let << endl;
      }
    }
  }
  li res = -n;
  for (auto& s : data) {
    int v = 0;
    for (int i = 0; i + 1 < s.length(); ++i) {
      v = bor[v].trans[s[i] - 'a'];
    }
    res += bor[v].reachable[s.back() - 'a'];
  }
  cout << res << endl;

}

