const int MAXN = 2e5 + 5;

struct Hash
{
	ll mod, base;
	vector<ll> pwb,val;

	Hash(ll base = 0): mod(1e9), base(base) {}
	inline void set_base(ll base_){ mod=1e9; base=base_;}

	void set_hash(const string &s)
	{
		val.resize(s.size()); pwb.resize(s.size());
		pwb[0] = 1;
		for(int i=1; i<(int)val.size(); ++i)
			val[i] = (val[i-1] * base + s[i]) %mod,
			pwb[i] = pwb[i-1] * base %mod;
	}

	inline ll get_seg(int l,int r){ return (val[r] - val[l-1] * pwb[r-l+1] %mod + mod) %mod;}

	inline bool eq(int l1,int r1,int l2,int r2){ return get_seg(l1,r1) == get_seg(l2,r2);}
	inline bool eq(const pii &p,const pii &q){ return get_seg(p.first,p.second) == get_seg(q.first,q.second);}
};

struct Double_Hash
{
	Hash h1,h2;
	Double_Hash(ll base1=0, ll base2=0): h1(base1), h2(base2) {}
	inline void set_base(ll base1,ll base2){ h1.set_base(base1); h2.set_base(base2);}

	void set_hash(const string &s){ h1.set_hash(s); h2.set_hash(s);}

	inline pii get_seg(int l,int r){ return make_pair(h1.get_seg(l,r), h2.get_seg(l,r));}

	inline bool eq(int l1,int r1,int l2,int r2){ return h1.eq(l1,r1,l2,r2) && h2.eq(l1,r1,l2,r2);}
	inline bool eq(const pii &p,const pii &q){ return h1.eq(p,q) && h2.eq(p,q);}
};

string s[MAXN];
Double_Hash h[MAXN];

map<pii, vector<char> > t;

int cnt1[30];

