const ll p = 31, m = 1e9+9;
unordered_map<ll,ll> cnt;

ll compute_hash(string& s){
    vector<int> letras(27,0);
    ll pref = 0;
    int n = s.size();
    for(int i=0;i<n;i++){
        letras[s[i]-'a'+1]++;
    }

    for(int j=1;j<27;j++){
        if(letras[j]){
            cnt[(pref*p+j)%m]++;
        }
    }
    for(int i=n-1;i>=0;i--){
        pref = (pref*p+(s[i]-'a'+1))%m;
        letras[s[i]-'a'+1]--;
        for(int j=1;j<27;j++){
            if(letras[j]){
                cnt[(pref*p+j)%m]++;
            }
        }
    }
    return pref;
}

