void InitPower(int n){
    power1[0]=power2[0]=1;
    for(int i=1;i<=n;++i){
        power1[i]=power1[i-1]*base1%mod1;
        power2[i]=power2[i-1]*base2%mod2;
    }
}
struct Hash{
    Hash(ll hash1=0,ll hash2=0):hash1_(hash1),hash2_(hash2){}
    bool operator <(Hash h)const{
        if (hash1_==h.hash1_)return hash2_<h.hash2_;
        else return hash1_<h.hash1_;
    }
    ll hash1_,hash2_;
};
vector<Hash> ha[N];
Hash GetHash(int i,int x,int y){
    return Hash(((ha[i][y].hash1_-ha[i][x-1].hash1_*power1[y-x+1])%mod1+mod1)%mod1,
                ((ha[i][y].hash2_-ha[i][x-1].hash2_*power2[y-x+1])%mod2+mod2)%mod2);
}
