using namespace std;

struct Node
{
    int cnt;
    int tar[26];
    Node *chd[26];
    Node(void) { cnt = 0; for(auto &i : tar) i = 0; for(auto &i : chd) i = nullptr; }
};

Node *ins(Node *root, const char str[])
{
    if(!root) root = new Node;

    ++root->cnt;
    if(!str[0]) return root;
    if(!str[1])
    {
        root->tar[*str - 'a']++;
    }

    root->chd[*str - 'a'] = ins(root->chd[*str - 'a'], str + 1);
    return root;
}

long long dfs(Node *root, int arr[], int cur)
{
    if(!root) return 0;
    long long ret = 1ll * arr[cur] * root->cnt;
    for(int i = 0; i < 26; ++i) arr[i] += root->tar[i];
    for(int i = 0; i < 26; ++i) ret += dfs(root->chd[i], arr, i);
    for(int i = 0; i < 26; ++i) arr[i] -= root->tar[i];
    return ret;
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    Node *root = new Node;
    int n; cin >> n;
    for(int i = 0; i < n; ++i)
    {
        string s; cin >> s;
        reverse(s.begin(), s.end());
        root = ins(root, s.c_str());
    }

    int arr[26]{};
    cout << (dfs(root, arr, 0) - n);
}

