int get(int pos)
{
    int res = 0;
    while (pos >= 0)
    {
        res += fenw[pos];
        pos = (pos & (pos + 1)) - 1;
    }
    return res;
}

void add(int pos, int x)
{
    while (pos < N)
    {
        fenw[pos] += x;
        pos = (pos | (pos + 1));
    }
}

