                for(int c = 0; c < 26; c++)
                    cnt1[c] = cnt2[c] = 0;
                cnt0 = 0;
            }
            if(lg + 1 <= (int)s[i].size())
            {
                cnt1[s[i][lg] - 'a']++;
                ans += cnt2[s[i][lg] - 'a'];
            }
            if(lg + 2 <= (int)s[i].size())
            {
                cnt2[s[i][lg + 1] - 'a']++;
                ans += cnt1[s[i][lg + 1] - 'a'];
            }
            ans += cnt0;
            if(lg == (int)s[i].size())
                cnt0++;
            last = i;
        }
    }
    cout << ans << "\n";
    return 0;
}

