using namespace std;

int main() {
  ios_base::sync_with_stdio(false);

  int n;
  cin >> n;
  vector<string> a(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
    reverse(a[i].begin(), a[i].end());
  }

  auto f = [](int v, int c) {
    int res = (1LL * 200003 * v + c) % 1000000007;
    return res;
  };
  auto rh = [&](string &s) {
    int n = s.length();
    vector<int> res(n + 1);
    for (int i = 0; i < n; i++) {
      res[i + 1] = f(res[i], s[i]);
    }
    return res;
  };

  const int N = 1e6 + 5;
  vector<map<int, int>> mp(N);

  auto hash = [&](string &s) {
    int L = s.length();
    vector<int> h = rh(s);
    vector<vector<int>> dp(L + 1, vector<int>(26));
    for (int i = L - 1; i >= 0; i--) {
      dp[i][s[i] - 'a'] = 1;
      for (int j = 0; j < 26; j++) {
        dp[i][j] |= dp[i + 1][j];
      }
    }  

    for (int i = 0; i <= L; i++) {
      int pref = h[i];
      for (int j = 0; j < 26; j++) {
        if (dp[i][j] == 0) continue;
        int all = f(pref, j + 'a');
        mp[i][all]++;
      }
    }
  };
  for (auto s : a) {
    hash(s);
  }

  long long ans = 0;
  for (auto s : a) {
    int L = s.length();
    ans += mp[L - 1][rh(s)[L]];
  }
  cout << ans - n << '\n';

  return 0;
}

