map<ll,ll>used;
vector<ll>h[200001];
ll p[200001];
ll mod=100000020383;


void Hash(int ind,string s){
	ll has=0;
	h[ind].pb(s[0]%mod);
	has+=s[0];
	has%=mod;
	for(int i=1;i<(int)s.size();i++){
		h[ind].pb((has+(s[i])*p[i])%mod);
		has+=(s[i])*p[i];
		has%=mod;
	}
	used[has]++;
}
int main(){
	p[0]=1;
	for(int i=1;i<=200000;i++)p[i]=p[i-1]*97;

	int n;cin>>n;
	string s[n+1];

	for(int i=1;i<=n;i++)cin>>s[i];

	for(int i=1;i<=n;i++){
		Hash(i,s[i]);
	}

	ll cnt=0;

	for(int i=1;i<=n;i++){

		ll cnt1=0;

		int used1[27];for(int j=0;j<26;j++)used1[j]=0;
		for(int j=0;j<(int)s[i].size();j++){
			if(used1[s[i][j]-'a']==0){
				ll num=s[i][j]%mod;
				cnt+=used[num];

			}
			used1[s[i][j]-'a']++;
		}
		for(int j=0;j<=26;j++)used1[j]=0;

		for(int j=0;j<(int)s[i].size();j++){
			if(used1[s[i][j]-'a']==0){
				for(int k=(int)s[i].size()-1;k>j;k--){
					ll num=0;
					num+=s[i][j]%mod;
					ll op=h[i][s[i].size()-1]-h[i][k-1];
					op/=p[k-1];

					num+=op;
					cnt+=used[num%mod];
					cnt1+=used[num%mod];
				}	
			}
			used1[s[i][j]-'a']++;
		}
		cnt--;
	}
	cout<<cnt;
	return 0;
}

