using namespace std;

/* constant */

const int MAX_N = 200000;
const int MAX_L = 1000000;
const int MAX_M = MAX_L + 1;
const int K = 26;

/* typedef */

typedef long long ll;
typedef int vec[K];

/* global variables */

char s[MAX_L + 4];
string ss[MAX_N];
int ps[MAX_M];
vec cs[MAX_M], cts[MAX_M];

/* subroutines */

bool cmpstr(const string &a, const string &b) {
  return a.size() > b.size();
}

void printvec(vec v) {
  for (int i = 0; i < K; i++) printf("%d ", v[i]);
  putchar('\n');
}

void store_word(string &w, int &m) {
  int u = 0;
  for (int i = w.size() - 1; i >= 0; i--) {
    int c = w[i] - 'a';
    int v = cs[u][c];
    if (v < 0) {
      v = cs[u][c] = m++;
      ps[v] = u;
    }
    u = v;
  }

  vec t;
  memset(t, 0, sizeof(t));

  for (int i = 0; i < w.size(); i++) {
    u = ps[u];
    t[w[i] - 'a'] = 1;
    for (int j = 0; j < K; j++) cts[u][j] += t[j];
  }
}

int lookup_word(string &w) {
  int u = 0;
  for (int i = w.size() - 1; i > 0; i--) {
    int c = w[i] - 'a';
    if (cs[u][c] < 0) return 0;
    u = cs[u][c];
  }
  return cts[u][w[0] - 'a'];
}

/* main */

int main() {
  int n;
  scanf("%d", &n);

  for (int i = 0; i < n; i++) {
    scanf("%s", s);
    ss[i] = string(s);
  }
  sort(ss, ss + n, cmpstr);
  //for (int i = 0; i < n; i++) cout << ss[i] << endl;

  memset(cs, -1, sizeof(cs));
  ps[0] = -1;

  int m = 1;
  ll sum = 0;
  for (int i = 0; i < n; i++) {
    string &w = ss[i];
    sum += lookup_word(w);
    store_word(w, m);
  }

  printf("%lld\n", sum);
  //printf("m=%d\n", m);
  //printvec(cts[0]);
  return 0;
}

