const int N = (int) 2e5 + 100;
vector <int> pos[N];
int sz = 1;

void solve(int id)
{
    scanf("%s", str);
    int n = strlen(str);
    reverse(str, str + n);

    int v = 0;
    for (int i = 0; i < n; i++)
    {
        int c = str[i] - 'a';
        if (goTo[v][c] == 0)
        {
            parc[sz] = c;
            goTo[v][c] = sz++;
        }
        pos[id].push_back(v);
        v = goTo[v][c];
    }
    pos[id].push_back(v);
    term[v] = id;
}

int answer;
int has[ALP];

int timer;

void addPair(int a, int b)
{
    if (a > b)
        swap(a, b);
    if (a == -1 || a == b)
        return;
    answer++;
}

void getAns(int id)
{
    //for (int x : pos[id])
    //    eprintf("%d ", x);
    //eprintf("\n");
    memset(has, false, sizeof has);
    for (int i = (int) pos[id].size() - 1; i >= 0; i--)
    {
        int v = pos[id][i];
//        addPair(id, term[v]);

        for (int j = 0; j < ALP; j++)
            if (has[j])
                addPair(id, term[goTo[v][j]]);

        has[parc[v]] = true;
    }
}

