struct Trie {
    using State = string::iterator;
    struct Node {
        Node *ch[26] = {};
        int cnt[26] = {};
        int s = 0;
    };

    Node *root = nullptr;

    void insert(string &s, int cnt[]) {
        if (root == nullptr) root = new Node();
        root->s++;
        repeat(i, 26) {
            if (cnt[i]) root->cnt[i]++;
        }

        if (root->ch[s[0] - 'a'] == nullptr) root->ch[s[0] - 'a'] = new Node();
        insert(root->ch[s[0] - 'a'], s.begin(), cnt);
    };

    void insert(Node *u, State s, int cnt[]) {
        cnt[*s - 'a']--;
        u->s++;
        repeat(i, 26) {
            if (cnt[i]) u->cnt[i]++;
        }

        s++;
        if (*s == '\0') return;
        if (u->ch[*s - 'a'] == nullptr) u->ch[*s - 'a'] = new Node();
        insert(u->ch[*s - 'a'], s, cnt);
    };

    int find(string &s) {
        if (s.size() == 1) {
            return root->cnt[s[0] - 'a'];
        }
        else {
            return find(root->ch[s[0] - 'a'], s.begin());
        }
    };
    int find(Node *u, State s) {
        if (u == nullptr) return 0;

        ++s;
        if (s[1] == '\0') {
            return u->cnt[*s - 'a'];
        }
        else {
            return find(u->ch[*s - 'a'], s);
        }
    };
};

