int sm[N][ALP];

int new_node() {
	fill(go[pnt], go[pnt] + ALP, -1);
	fill(sm[pnt], sm[pnt] + ALP, 0);
	pnt++;
	return pnt - 1;
}

void init() {
	root = new_node();
}

void add(string s) {
	vector<int> path = {root};
	int cur = root;
	for (auto t : s) {
		if (go[cur][t - 'a'] == -1) {
			go[cur][t - 'a'] = new_node();
		}
		cur = go[cur][t - 'a'];
		path.push_back(cur);
	}
	vector<int> any(ALP);
	reverse(path.begin(), path.end());
	reverse(s.begin(), s.end());
	for (int i = 1; i < (int)path.size(); i++) {
		any[s[i - 1] - 'a'] = 1;
		for (int j = 0; j < ALP; j++) {
			if (any[j]) {
				sm[path[i]][j]++;
			}
		}
	}
}

