struct Trie{
    struct Node{
        int c;
        array<int,26> nxt;
        array<int,26> cnt;
        int sz;

        Node(int c):c(c),sz(0){
            nxt.fill(-1);
            cnt.fill(0);
        }
    };
    vector<Node> nodes;

    Trie(){nodes.emplace_back(-1);}

    void add(const string& s){
        int pos=0;
        for(char c:s){
            int ci=c-'a';

            int npos=nodes[pos].nxt[ci];
            if(npos==-1){
                npos=nodes.size();
                nodes[pos].nxt[ci]=npos;
                nodes.emplace_back(ci);
            }
            pos=npos;
        }
        ++nodes[pos].sz;
    }

    int find(const string& s) const{
        int pos=0;
        for(char c:s){
            int ci=c-'a';
            pos=nodes[pos].nxt[ci];
        }
        return pos;
    }

    void fillcnt(){
        for(int pos=(int)nodes.size()-1;pos>=0;--pos){
            auto& node=nodes[pos];

            rep(c,26){
                int npos=node.nxt[c];
                if(npos==-1) continue;

                const auto& cnode = nodes[npos];
                node.sz+=cnode.sz;
                rep(d,26){
                    node.cnt[d]+=cnode.cnt[d];
                }
            }
            if(node.c!=-1) node.cnt[node.c]=node.sz;
        }
    }
};

