struct TrieMap {

  int A;
  vector<vector<int>> trans;
  vector<int> value;

  TrieMap() {}

  TrieMap(int A) : A(A), trans(1, vector<int>(A, -1)), value(1, -1) {}

  int get(int o) const { return value[o]; }

  int getId(const vector<int> &s) const {
    int o = 0;
    for (int c : s) {
      o = trans[o][c];
      if (o == -1)
        return -1;
    }
    return o;
  }

  int getV(const vector<int> &s) const { return value[getId(s)]; }

  int extend(int o, int c) {
    if (trans[o][c] == -1) {
      trans[o][c] = trans.size();
      trans.push_back(vector<int>(A, -1));
      value.push_back(-1);
    }
    return trans[o][c];
  }

  void ins(const vector<int> &s, int v) {
    int o = 0;
    for (int c : s) o = extend(o, c);
    value[o] = v;
  }
} mp;

