      vec.push_back(s[i][j] - 'a');
    }
    trieMap.ins(vec, 1);
  }
  int ans = 0;
  for (int i = 0; i < n; ++i) {
    int id = 0;
    vector<int> occ(26);
    ans -= 1;
    for (char c : s[i]) ++occ[c - 'a'];
    for (int j = 0; j < s[i].size(); ++j) {
      for (int t = 0; t < 26; ++t)
        if (occ[t]) {
          int jd = trieMap.trans[id][t];
          if (jd != -1 && trieMap.value[jd] == 1)
            ++ans;
        }
      --occ[s[i][j] - 'a'];
      id = trieMap.trans[id][s[i][j] - 'a'];
    }
  }
  cout << ans << '\n';

#ifdef ELEGIA
  LOG("Time: %dms\n", int ((clock()
          -nol_cl) / (double)CLOCKS_PER_SEC * 1000));
#endif
  return 0;
}

