        // Move to the next node before that check for answer
        for(int j=0;j<26;j++)
        if(table[i+2][j]!=0 && (cur->arr[in]->arr[j] != NULL)) ans+=cur->arr[in]->arr[j]->freq;
        cur = cur->arr[in]; 
    } 

    // Return the updated root 
