void solve(int n, vector<string> s) {
  const string A = "a";
  vvs as(26);
  each(x, s)as[x.back() - 'a'].push_back(x);
  vector<trie_tree<26, 'a'>> tt(26);
  rep(i, 26)each(x, as[i])tt[i].add(A + x.substr(0, sz(x) - 1));
  int ans = 0;
  each(x, s) {
    int l = sz(x);
    vi cm(l + 1);
    rrep(j, l)cm[j] = cm[j + 1] | lshift(x[j] - 'a');
    rep(j, 26) {
      auto f = [&](int idx) {
        if((cm[sz(as[j][idx]) - 1] >> j) & 1){
          ans++;
        }
      };
      tt[j].query(A + x.substr(0, l - 1), f);
    }
  }
  COUT(ans - n);
}


