struct node {
	int eos = 0, chi = 0;
	int cc[26];
	node * c[26];
};

node * root;

int getIndex(char c) {
	if(c >= 'a' && c <= 'z')
		return c - 'a';
	return 0;
}

node * createNode() {
	node * r = new node();
	for(int i = 0; i < 26; i++)
		r->c[i] = 0, r->cc[i] = 0;
	return r;
}

void insertString(string & s, int i, node * n = root) {
	n->chi++;
	if(i == -1) {
		n->eos++;
		return;
	}
	if(n->c[getIndex(s[i])] == 0)
		n->c[getIndex(s[i])] = createNode();
	//cerr << "insert " << s << " i: " << i << " cc: " << (n->chi) <<endl;
	insertString(s, i - 1, n->c[getIndex(s[i])]);
}

void init() {
	root = createNode();
}

void doDP(node * n = root){
	for(int i = 0; i < 26; ++i){
		if(n->c[i] != 0){
			doDP(n->c[i]);
			for(int j = 0; j < 26; ++j){
				int cv = n->c[i]->cc[j];
				if(j == i) cv = n->c[i]->chi;
				//if(cv > 0) cerr << "cv: " << cv << endl;
				n->cc[j] = n->cc[j] + cv;
			}
		}
	}
}

int query(string s, int i, node * n = root) {
	if(i == 0){
		return n->cc[getIndex(s[i])];
	}
	if(n->c[getIndex(s[i])] == 0)
		return 0;
	else
		return query(s, i -1, n->c[getIndex(s[i])]);
}

