template< typename T,char start='a',int csize=26 >
struct Trie{
    const int NONE = -1;
    struct Node{
        const int NONE = -1;
        vector<int> nxt;
        vector<int> acs;
        T val;
        T prefsum;
        Node(){
            val=0;
            prefsum=0;
            nxt.resize(csize,NONE);
            acs.resize(26,0);
        }
    };

    vector<Node> nodes;
    ll ans=0;

    Trie(){
        nodes.push_back(Node());
    }

    void accept(int noid,int id,T v){
        nodes[noid].acs[v]++;
        //nodes[noid].val=max(nodes[noid].val,v);
        nodes[noid].prefsum+=v;
    }

    void update(int noid,T v){
        nodes[noid].prefsum+=v;
    }

    void add(const string &S,int stid,int noid,int id,T v){
        if(stid==S.size()){
            accept(noid,id,v);
        }else{
            int c=S[stid]-start;
            if(nodes[noid].nxt[c]==NONE){
                nodes[noid].nxt[c]=(int)nodes.size();
                nodes.push_back(Node());
            }
            update(noid,v);
            add(S,stid+1,nodes[noid].nxt[c],id,v);
        }
    }

    void add(const string &S,int id,T v=1){
        add(S,0,0,id,v);
    }

    int find(const string &S,vector<int> &alp){
        int noid=0;
        for(int i=0;i<S.size();++i){
            rep(j,26) if(alp[j]>=i) ans+=nodes[noid].acs[j];
            int c=S[i]-start;
            if(nodes[noid].nxt[c]==NONE) return NONE;
            noid=nodes[noid].nxt[c];
        }
        return noid;
    }

    void solve(vector<string> &S){
      int N=S.size();
      for(int i=0;i<N;i++){
        string t=S[i].substr(0,(int)S[i].size()-1);
        char c=S[i][(int)S[i].size()-1];

        vector<int> A(26,-1);
        rep(j,S[i].size()) A[S[i][j]-'a']=j;
        find(S[i],A);

        add(t,i,c-'a');
      }
      cout<<ans<<endl;
    }
};

