        for (char c : s) cnt[c - 'a']++;
        Int idx = 0;
        REP(i, s.size() - 1) {
            REP(c, 26) { ans += num[idx][c] && cnt[c] > 0; }
            Int c = s[i] - 'a';
            cnt[c]--;
            if (t.tree[idx][c] == -1) {
                t.tree[idx][c] = t.tree.size();
                t.tree.emplace_back();
                num.emplace_back(26);
            }
            idx = t.tree[idx][c];
        }
        num[idx][s.back() - 'a']++;
    }
    std::cout << ans << std::endl;
