  RollingHash rh[N];
  for (int i = 0; i < N; i++) rh[i] = RollingHash(S[i], base1);
  // cerr << tick() << '\n' << flush;
  unordered_map<uint64_t, vector<long long>> mp;
  long long ans = 0;
  for (int i = 0; i < N; i++) {
