    uint32_t bits = 0;
    for (int j = 0; j < n; j++) {
      bits |= 1 << (S[i][j] - 'a');
      auto itr = mp.find(rh[i].get_hash(j + 1, n));
      if (itr == mp.end()) continue;
      for (int k = 0; k < 26; k++)
        if ((bits >> k) & 1) ans += itr->second[k];
    }
    auto hash = rh[i].get_hash(1, n);
    if (mp.find(hash) == mp.end()) mp[hash].assign(26, 0);
    mp[hash][S[i][0] - 'a']++;
  }
