struct Vertex{
    int next[K];
    int descendants; // total number of descendants, including itself
    int suffix[K]; // how many descendants have char c
    int leaf = 0;
    int p = -1; // parent
    char pch; // edge from p -> this

    Vertex(int p = -1, char ch = '(') : p(p), pch(ch) {
        msetn1(next);
    }
};

vector <Vertex> aho(1);

void add(string &s){
	int cur = 0;
	Fora(ch, s){
		if (aho[cur].next[ch - 'a'] == -1){
			aho[cur].next[ch - 'a'] = aho.size();
			aho.eb(cur, ch);
		}
		cur = aho[cur].next[ch - 'a'];
	}
	aho[cur].leaf++;
}

void del(string &s){
    int cur = 0;
    Fora(ch, s){
        cur = aho[cur].next[ch - 'a'];
    }
    while (cur != 0){
        aho[aho[cur].p].descendants -= aho[cur].descendants;
        For(i, 0, 26){
            aho[aho[cur].p].suffix[i] -= (i == aho[cur].pch - 'a' ? aho[cur].descendants
                                                                  : aho[cur].suffix[i]);
        }
        aho[cur].leaf--;
        aho[cur].descendants--;
        For(i, 0, 26){
            aho[aho[cur].p].suffix[i] += (i == aho[cur].pch - 'a' ? aho[cur].descendants
                                                                  : aho[cur].suffix[i]);
        }
        aho[aho[cur].p].descendants += aho[cur].descendants;
        cur = aho[cur].p;
    }
}

void dfscalsumsuffix(int u){
