        ll sum=0;
        std::set<ll> s;
        vi mem(T.size()+1),m(T.size()+1,1);
        rep(i,0,T.size()){
            ll X=T[i]-'a'+1;
            sum=(sum+memo*X)%mod;
            memo=memo*27%mod;
            s.insert(sum);
            mem[i+1]=sum;
            m[i+1]=memo;
        }
        vector<bool> F(26);
        per(i,T.size()-1,1){
            ll X=T[i]-'a';
            F[X]=1;
            rep(j,0,26){
                if(F[j]){
                    ll Y=(mem[i-1]+m[i-1]*(j+1))%mod;
                    s.insert(Y);
                }
            }
        }
        ans+=cnt[sum];
        for(auto p:s) cnt[p]++;
    }
    cout<<ans<<endl;
