#define pb push_back

typedef long long ll;

const int MOD = 1e9+7;
const int MOD2 = 999998137;
const int INF = 1e9+5;
const int mul = 37;
const int mul2 = 31337;

char c[1000005];
string s[200005];

int dul[1000005];

int cnt[200];

map <pair<pair<int, int>, char>, int> M;

bool cmp(string a, string b) {
	if (a.size() != b.size()) return a.size()<b.size();
	return a<b;
}

int main() {
	int n;
	scanf("%d", &n);
	for (int i=0 ; i<n ; i++) {
		scanf("%s", c);
		s[i] = c;
		dul[s[i].size()]++;
	}
	sort(s, s+n, cmp);
	int sol = 0;
	for (int i=0 ; i<n ; i++) {
		int h = 0;
		int h2 = 0;
		ll B = 1;
		ll B2 = 1;
		for (int j=0 ; j<s[i].size() ; j++) {
			cnt[s[i][j]]++;
		}
		for (int j=s[i].size() ; j>=1 ; j--) {
			if (j<s[i].size()) {
				h += B*(s[i][j]-'a'+1)%MOD;
				h2 += B2*(s[i][j]-'a'+1)%MOD2;
				if (h >= MOD) h-=MOD;
				if (h2 >= MOD2) h2-=MOD2;
			}
			if (j<s[i].size()) cnt[s[i][j]]--;
			if (dul[s[i].size()+1-j]) {
				for (int k='a' ; k<='z' ; k++) {
					if (cnt[k]) sol += M[mp(mp(h, h2), k)];
				}
			}
			if (j<s[i].size()) {
				B = B*mul%MOD;
				B2 = B2*mul%MOD2;
			}
		}
		M[mp(mp(h, h2), s[i][0])]++;
		for (int j='a' ; j<='z' ; j++) cnt[j] = 0;
	}
	printf("%lld\n", sol);
	return 0;
}

