        ll id = 0;

        ll sum[len(s) + 1][26];
        rep(j, len(s) + 1) rep(k, 26) sum[j][k] = 0;
        rep(j, len(s)) sum[j][s[j] - 'a']++;
        dec(j, len(s) - 1, 0) rep(k, 26) sum[j][k] |= sum[j + 1][k];

        rep(k, 26) if (sum[0][k]) res += cnt[k][id];
        rep(j, len(s)) {
            each(k, Trie[id].second) {
