	Trie *root = newNode();

	ll ans = 0;
	fo(i, 0, n) {
		if(v[i].size() > 1) {
			ll res = qry1(root, v[i], 0);
			ans += res;
			ans += qry2(root, v[i], 0, v[i].back() - 'a') - res;
