}
int32_t main()
{
	SYNC
	int n; cin >> n;
	root = new node;
	long long ans = 0;
	a.resize(n);
	rep(i,0,n)	cin >> a[i];
	sort(all(a), comp);
	vi magic(26, 0);
	rep(i,0,n) {
		s = a[i];
		reverse(all(s));
		if (sz(s) == 1)	fre[s]++;
		else {
			node* cur = root;
			int ok = true;
			for (int j = 0; j < sz(s)-1; j++) {
				int now = s[j]-'a';
				if (cur->nxt[now] == NULL) {
					ok = false;
					break;
				} else {
					cur = cur->nxt[now];
				}
			}
