			for (int j = sz(s)-2; j >= 0; j--) {
				rep(k,0,26)
					cum[j][k] = cum[j+1][k];
				cum[j][s[j]-'a'] = true;
			}
			rep(k,0,26) {
				if (cum[0][k])	magic[k]++;
			}
			cur = root;
			for (int j = 0; j < sz(s); j++) {
				int now = s[j]-'a';
				if (j != sz(s)-1) {
					rep(k,0,26) {
						if (cum[j+1][k])	cur->dp[k]++;
					}
