struct Trie {
  Trie *node[26];
  vector<int> val;
  Trie() : val(26, 0) { std::fill(node, node + 26, nullptr); }
  void insert(const std::string &s) {
    Trie *r = this;
    for (int i = 0; i < (int)s.length() - 1; i++) {
      int c = s[i] - 'a';
      if (!r->node[c]) r->node[c] = new Trie;
      r = r->node[c];
    }
    int idx = s[0] - 'a';
    r->val[idx]++;
    return;
  }
  Trie *find(const char &s, Trie *pos) {
    int c = s - 'a';
    if (!pos->node[c]) return nullptr;
    return pos->node[c];
  }
  ll count(const string &s) {
    ll ans = 0;
    vector<int> cnt(26);
    for (auto c : s) cnt[c - 'a']++;
    Trie *r = this;
    for (int i = 0; i < (int)s.size(); i++) {
      for (int j = 0; j < 26; j++) {
        if (cnt[j]) {
          ans += r->val[j];
        }
      }
      auto nxt = find(s[i], r);
      if (!nxt) break;
      r = nxt;
      cnt[s[i] - 'a']--;
    }
    return ans;
  }
};

