    for(i=1;i<=n;i++) {
        string s;
        cin >> s;
        string t = s;
        reverse(t.begin(), t.end());
        arr[i] = t;
        v.push_back({(int)s.length(), i});
    }
    ll chaeng = 0;
    vector<ll> to;
    for(auto x : v) {
        int sz = x.first;
        int idx = x.second;
        for(i=1;i<=26;i++) cnt[i] = 0;
        for(auto x : arr[idx]) cnt[x - 'a' + 1]++;
        ll now = 0, pp = p;
        for(i=1;i<=26;i++) {
            if(cnt[i] > 0) mp[i%mod]++;
        }
        for(i=0;i<sz-1;i++) {
            now += (arr[idx][i]-'a'+1)*pp;
            now %= mod;
            pp *= p;
            pp %= mod;
            cnt[arr[idx][i]-'a'+1]--;
            for(j=1;j<=26;j++) {
                if(cnt[j] > 0) mp[(now+(1LL*j*pp))%mod]++;
            }
        }
        now += (arr[idx][sz-1]-'a'+1)*pp;
        now %= mod;
        if(sz==1) now/=pp;
        to.push_back(now);
    }
    for(auto x : to) {
        mp[x]--;
        chaeng += mp[x];
        mp[x]++;
    }
    cout << chaeng << endl;
    return 0;
}

