typedef long long ll;
const int mod=2000003,base=23;
const int N=200010,L=2000010;
int n,pl[N],pr[N],Hash[L],mp[30][2100010],vis[26];
char s[L];
bool cnt[26];
ll ans;
int main(){
	scanf("%d",&n);
	for(int i=1;i<=n;i++){
		scanf("%s",s+pr[i-1]+2);
		pl[i]=pr[i-1]+2;
		for(pr[i]=pl[i];s[pr[i]+1]!='\0';pr[i]++);
		if(pr[i]==pl[i]){
			cnt[s[pl[i]]-'a']=1;
			continue;
		}
		Hash[pr[i]+1]=0;
		int bs=base;
		for(int j=pr[i]+1;j>pl[i];j--){
			Hash[j-1]=(Hash[j]+(s[j-1]-'a'+1ll)*bs)%mod;
			bs=1ll*bs*base%mod;
		}
		mp[s[pl[i]]-'a'][Hash[pl[i]+1]]++;
	}
	for(int i=1;i<=n;i++){
		if(pr[i]==pl[i])
			continue;
		for(int j=pr[i];j>=pl[i];j--){
			ans+=mp[s[j]-'a'][Hash[j+1]];
			if(j+2<=pr[i]+1)
				ans+=mp[s[j]-'a'][Hash[j+2]];
		}
		ans--;
		for(int j=pl[i];j<=pr[i];j++)
			if(vis[s[j]-'a']!=i&&cnt[s[j]-'a'])
				ans++;
	}
	printf("%lld\n",ans);
	return 0;
}

