template<int char_size>
struct TrieNode {
    int nxt[char_size];
    int exist;
    vector<int> accept;

    TrieNode() : exist(0) { memset(nxt, -1, sizeof(nxt)); }
};

template<int char_size, int margin>
struct Trie {
    using Node = TrieNode<char_size>;

    vector<Node> nodes;
    int root;
    ll ans = 0;

    Trie() : root(0) { nodes.push_back(Node()); }

    void update_direct(int node, int id) { nodes[node].accept.push_back(id); }

    void update_child(int node, int child, int id) { ++nodes[node].exist; }

    void add_solve(const string& str, vector<vector<int>>& table, int str_idx, int node_idx, int id){
        if(str_idx == (int)str.size())  update_direct(node_idx, id);
        else{
            for(int i = 0; i < 26; ++i){
                if(nodes[node_idx].nxt[i] == -1)    continue;
                int pos = *lower_bound(table[i].begin(), table[i].end(), str_idx);
                if(pos == (int)str.size())  continue;
                if(nodes[nodes[node_idx].nxt[i]].accept.size()) ++ans;
            }
            const int c = str[str_idx] - margin;
            if(nodes[node_idx].nxt[c] == -1){
                nodes[node_idx].nxt[c] = (int)nodes.size();
                nodes.push_back(Node());
            }
            add_solve(str, table, str_idx + 1, nodes[node_idx].nxt[c], id);
            update_child(node_idx, nodes[node_idx].nxt[c], id);
        }
    }

    void add_solve(const string& str, vector<vector<int>>& table, int id)   { add_solve(str, table, 0, 0, id); }

    void add_solve(const string& str, vector<vector<int>>& table)   { add_solve(str, table, (int)nodes[0].exist); }

    int count() const { return nodes[0].exist; }

    int size() const { return (int)nodes.size(); }
};

