unordered_map<string, int> target_count;

large check(const string& current, const int s_index, const bool original) {
    {
        auto itr = solved[s_index].find(current);
        if (itr != solved[s_index].end())
            return 0;
    }

    solved[s_index].emplace(current);

    auto sum = 0LL;
    auto itr = target_count.find(current);
    if (itr != target_count.end()) {
        sum += itr->second;
        if (original) {
            sum--; // Exclude itself
        }
        if (sum != 0) {
            cerr << "Found: " << current << " from [" << s_index << "]" << s[s_index] << "\n";
        }
    }

    if (current.length() >= 2) {
        auto t = current.substr(1);
        sum += check(t, s_index, false);
        t[0] = current[0];
        sum += check(t, s_index, false);
    }

    return sum;
}


