template< int char_size >
struct TrieNode {
  int nxt[char_size];

  int exist;
  vector< int > accept;

  array<int,char_size> hist;

  TrieNode() : exist(0) {
    memset(nxt, -1, sizeof(nxt));
    hist = {};
  }
};

template< int char_size, int margin >
struct Trie {
  using Node = TrieNode< char_size >;

  vector< Node > nodes;
  int root;

  Trie() : root(0) {
    nodes.push_back(Node());
  }

  void update_direct(int node, int id) {
    nodes[node].accept.push_back(id);
  }

  void update_child(int node, int child, int id, array<int,char_size> childhist) {
    ++nodes[node].exist;
    rep(c,char_size) nodes[node].hist[c]+=childhist[c];
  }

  array<int,char_size> add(const string &str, int str_index, int node_index, int id) {
    if(str_index == str.size()) {
      update_direct(node_index, id);
      return {};
    } else {
      const int c = str[str_index] - margin;
      if(nodes[node_index].nxt[c] == -1) {
        nodes[node_index].nxt[c] = (int) nodes.size();
        nodes.push_back(Node());
      }
      auto childhist = add(str, str_index + 1, nodes[node_index].nxt[c], id);
      childhist[c]=1;
      update_child(node_index, nodes[node_index].nxt[c], id, childhist);
      return childhist;
    }
  }

  void add(const string &str, int id) {
    add(str, 0, 0, id);
  }

  void add(const string &str) {
    add(str, nodes[0].exist);
  }

  void query(const string &str, const function< void(array<int,char_size>) > &f, int str_index, int node_index) {
    if(str_index == str.size()) {
      f(nodes[node_index].hist);
      return;
    } else {
      const int c = str[str_index] - margin;
      if(nodes[node_index].nxt[c] == -1) return;
      query(str, f, str_index + 1, nodes[node_index].nxt[c]);
    }
  }

  void query(const string &str, const function< void(array<int,char_size>) > &f) {
    query(str, f, 0, 0);
  }

  int count() const {
    return (nodes[0].exist);
  }

  int size() const {
    return ((int) nodes.size());
  }

};

