struct node {
	bool is_end;
	node *go[26];

	node(): is_end(0) { memset(go,0,sizeof go); }
};

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	ll n; cin >> n;
	vector<string> a(n);
	FOR(i,0,n) {
		cin >> a[i];
		reverse(all(a[i]));
	}

	node *root = new node();

	for (string s: a) {
		node *cur = root;
		for (char c: s) {
			if (!cur->go[c-'a']) {
				cur->go[c-'a'] = new node();
			}
			cur = cur->go[c-'a'];
		}
		cur->is_end = 1;
	}

	ll res = 0;
	for (string s: a) {
		vl last_occ(26,-1);
		FOR(i,0,sz(s)) last_occ[s[i]-'a'] = i;

		node *cur = root;
		FOR(i,0,sz(s)-1) {
			FOR(c,0,26) if (last_occ[c] >= i) {
				if (cur->go[c] && cur->go[c]->is_end) res++;
			}
			cur = cur->go[s[i]-'a'];
		}
	}
	cout << res << endl;
}

