		b[i].back()[s[i].back()-'a']=1;
		for(int j=s[i].size()-2;j>=0;j--){
			b[i][j]=b[i][j+1];
			b[i][j][s[i][j]-'a']=1;
		}
	}
	for(int i=0;i<n;i++){
		memset(c,0,sizeof c);
		for(int j=i+1;a[j-1]>=s[i].size()-1&&j<n;j++)
			for(int k=0;k<26;k++)
				c[k]+=b[j][s[i].size()-1][k];
		ans+=c[s[i].back()-'a'];
	}
	cout<<ans<<endl;
	return 0;
}

