typedef long long ll;

const int N = 1000010;
const int MOD = 1e9 + 7;
const ll P[2] = {97, 1000003};

ll bigMod (ll a, ll e) {
  if (e == -1) e = MOD - 2;
  ll ret = 1;
  while (e) {
    if (e & 1) ret = ret * a % MOD;
    a = a * a % MOD, e >>= 1;
  }
  return ret;
}

int n, id[N], len[N];
map <ll, int> cnt[30];
char tmp[N]; string a[N];
ll pwr[2][N], inv[2][N], h[2][N];

inline ll get (int l, int r) {
  if (l > r) return 0;
  ll one = (h[0][r] - h[0][l - 1]) * inv[0][l] % MOD;
  ll two = (h[1][r] - h[1][l - 1]) * inv[1][l] % MOD;
  if (one < 0) one += MOD; if (two < 0) two += MOD;
  return (one << 31LL) | two;
}

int main() {
  for (int it = 0; it < 2; ++it) {
    pwr[it][0] = inv[it][0] = 1;
    ll cur = P[it], inv_cur = bigMod(cur, -1);
    for (int i = 1; i < N; ++i) {
      pwr[it][i] = pwr[it][i - 1] * cur % MOD;
      inv[it][i] = inv[it][i - 1] * inv_cur % MOD;
    }
  }
  cin >> n;
  for (int i = 1; i <= n; ++i) {
    id[i] = i;
    scanf("%s", tmp);
    a[i] = tmp, len[i] = strlen(tmp);
