    for (int it = 0; it < 2; ++it) {
      h[it][0] = 0;
      for (int j = 1; j <= l; ++j) {
        h[it][j] = (h[it][j - 1] + (a[i][j - 1] - 'a' + 1) * pwr[it][j]) % MOD;
      }
    }
    int prv = 1 << (a[i][0] - 'a');
    for (int j = 1; j <= l; ++j) {
      ll cur = get(j + 1, l);
      for (int k = 0; k < 26; ++k) if (prv & 1 << k) {
        ans += cnt[k][cur];
      }
      if (j < l) prv |= 1 << (a[i][j] - 'a');
    }
    ll cur = get(2, l);
    ++cnt[a[i][0] - 'a'][cur];
  }
  cout << ans << '\n';
  return 0;
}

