using ull = unsigned long long;
struct RollingHash{
    const ull mod = (1ll << 61) - 1, mask30 = (1ll << 30) - 1, mask31 = (1ll << 31) - 1;
    const ull base = 1009, positiviser = mod * 5;
    ull sn;
    vector<ull> hash, power;

    RollingHash(){}
    RollingHash(const string& s){
        sn = s.size();
        hash.assign(sn + 1, 0);
        power.assign(sn + 1, 0);
        power[0] = 1;
        for (int i = 0;i < sn;i++){
            power[i + 1] = calc_mod(mul(power[i], base));
            hash[i + 1] = calc_mod(mul(hash[i], base) + s[i]);
        }
    }

    inline ull mul(ull a, ull b){
        ull au = a >> 31, ad = a & mask31;
        ull bu = b >> 31, bd = b & mask31;
        ull mid = ad * bu + au * bd;

        return ((au * bu) << 1) + ad * bd + ((mid & mask30) << 31) + (mid >> 30);
    }

    inline ull calc_mod(ull a){
        a = (a & mod) + (a >> 61);
        if (a >= mod) a -= mod;
        return a;
    }

    // S[b1:b1+len), S[b2:b2+len)が同じか判定
    inline bool match(int begin1, int begin2, int len){
        ull h1 = calc_mod(hash[begin1 + len] + positiviser - mul(hash[begin1], power[len]));
        ull h2 = calc_mod(hash[begin2 + len] + positiviser - mul(hash[begin2], power[len]));

        return h1 == h2;
    }
    inline bool match(ull h1, ull h2){
        return h1 == h2;
    }

    // S[b:b+len)のハッシュを返す
    inline ull get(int begin, int len){
        return calc_mod(hash[begin + len] + positiviser - mul(hash[begin], power[len]));
    }

};

