struct TrieNode {
    TrieNode *children[26];
    bool end_of_word;
    TrieNode() {
        fill(children, children + 26, (TrieNode *)NULL);
        end_of_word = false;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N;
    cin >> N;
    TrieNode *root = new TrieNode();
    vector<string> S(N);
    for (int i = 0; i < N; ++i) {
        cin >> S[i];
        // insert reverse of S[i]
        TrieNode *cur = root;
        for (int j = S[i].length() - 1; j >= 0; --j) {
            int index = S[i][j] - 'a';
            if (cur->children[index] == NULL) {
                cur->children[index] = new TrieNode();
            }
            cur = cur->children[index];
        }
        cur->end_of_word = true;
    }
    int ans = 0;
    for (int i = 0; i < N; ++i) {
        int L = S[i].length();
        vector<int> count(26, 0);
        for (int j = 0; j < L; ++j) {
            ++count[S[i][j] - 'a'];
        }
        TrieNode *cur = root;
        for (int j = L - 1; j >= 0 && cur != NULL; --j) {
            for (int k = 0; k < 26; ++k) {
                if (count[k] != 0 && cur->children[k] != NULL && cur->children[k]->end_of_word) {
                    ++ans;
                }
            }
            cur = cur->children[S[i][j] - 'a'];
            --count[S[i][j] - 'a'];
        }
    }
    cout << ans - N << '\n';
    return 0;
}

