        ll sum[len(S[i]) + 1][26];
        rep(j, len(S[i]) + 1) rep(k, 26) sum[j][k] = 0;
        rep(j, len(S[i])) sum[j][S[i][j] - 'a']++;
        dec(j, len(S[i]) - 1, 0) rep(k, 26) sum[j][k] += sum[j + 1][k];

        rep(j, S[i].size()) {
            rep(k, 26) if (sum[j][k]) res += cnt[k][id];
            each(k, Trie[id].second) {
                if (Trie[k].first == S[i][j]) {
                    id = k;
                    goto success;
                }
            }
            break;
        success:;
        }

        id = 0;
        rep(j, S[i].size() - 1) {
            each(k, Trie[id].second) {
                if (Trie[k].first == S[i][j]) {
                    id = k;
                    goto next;
                }
            }
            Trie[id].second.push_back(Trie.size());
            id = Trie.size();
            Trie.push_back({S[i][j], {}});
            rep(k, 26) cnt[k].pb(0);
        next:;
        }
        cnt[S[i].back() - 'a'][id]++;
    }

    cout << res << rt;
}

