const int MOD = 1e9 + 7;

vector<vector<int>> fs, trie;
vector<int> sub;
int sz;
int construct_node() {
    ++sz;
    trie.push_back(vector<int>(26, -1));
    fs.push_back(vector<int>(26, 0));
    sub.push_back(0);
    return sz-1;
}

void solve() {
    int n;
    cin >> n;
    vector<string> s(n);
    vector<pair<int,int>> ord(n);
    for (int i=0;i<n;++i) {
        cin >> s[i];
        ord[i] = {-(int)s[i].size(), i};
    }
    sort(ord.begin(), ord.end());
    vector<string> ts = s;
    for (int i=0;i<n;++i) {
        s[i] = ts[ord[i].second];
        reverse(s[i].begin(), s[i].end());
    }
    sz = 0;
    construct_node();
    LL ans = 0;
    for (auto it : s) {
        int m = it.size();
        // cout << m << " " << it << '\n';
        int cur = 0;
        for (int i=0;i<m-1;++i) {
            cur = trie[cur][it[i]-'a'];
            if (cur == -1) break;
        }
        if (cur != -1) {
            // cout << it << " found\n";
            ans += fs[cur][it[m-1]-'a'];
        }

        vector<int> backtrack;
        cur = 0;
        int newp = m + 1;
        for (int i=0;i<m;++i) {
            backtrack.push_back(cur);
            int go = trie[cur][it[i]-'a'];
            if (go == -1) {
                newp = min(newp, i);
                go = construct_node();
                trie[cur][it[i]-'a'] = go;
            } 
            cur = go;
        }
        sub[cur]++;
        for (int i=m-1;i>=0;--i) {
            int pcur = cur;
            cur = backtrack[i];
            sub[cur]++;
            fill(fs[cur].begin(), fs[cur].end(), 0);
            for (int k=0;k<26;++k) {
                int nxt = trie[cur][k];
                if (nxt == -1) continue;
                for (int j=0;j<26;++j) if (j != k) {
                    fs[cur][j] += fs[nxt][j];
                }
                fs[cur][k] += sub[nxt];
            }
        }
    }

    cout << ans << '\n';
}   

