void go(int now,int is,string s_){
	if(is==s_.length()) return;
	if(is&&(!now)){
		return;
	}
	if(son[now][s_[is]]){
	if(have[s_[is]]==1){
		old[son[now][s_[is]]][s_[is]]++;
		cnt[son[now][s_[is]]][s_[is]]++;
	}
	have[s_[is]]--;
		go(son[now][s_[is]],is+1,s_);
	}
	else{
		son[now][s_[is]]=++cnt_;
		if(have[s_[is]]==1){
		old[son[now][s_[is]]][s_[is]]++;
		cnt[son[now][s_[is]]][s_[is]]++;
		}
		have[s_[is]]--;
		go(son[now][s_[is]],is+1,s_);
	}	
}
