	rb(i,1,26){
		if(son[now][i]){
			calc(son[now][i]);
			rb(k,1,26)
				cnt[now][k]+=cnt[son[now][i]][k];
		}
	}
}
int rest(int now,int is,string s_,int need){	
	if(is==s_.length()) return cnt[now][need]-old[now][need]-1;
	return rest(son[now][s_[is]],is+1,s_,need);
}
