            p1[i + 1] = (p1[i] * b1) % mod1;
            p2[i + 1] = (p2[i] * b2) % mod2;
        }
    }

    inline pll get(ll l, ll r) const {
        ll res1 = h1[r] - h1[l] * p1[r-l] % mod1;
        if (res1 < 0) res1 += mod1;
        ll res2 = h2[r] - h2[l] * p2[r-l] % mod2;
        if (res2 < 0) res2 += mod2;
        return make_pair(res1, res2);
    }

    inline pll get() const {
        int n = h1.size();
        return get(0, n - 1);
    }
};

