            memo2[i].push_back(a2);
            memo3[i].push_back(a3);
            memo4[i].push_back(a4);
        }
        mykey now_key = make_tuple(*s[i].rbegin() - 'a', a1.x, a2.x, a3.x, a4.x);
        hash_num.insert(now_key);
    }
    ll res = 0;
    rep(i,N){
        vector<bool> exist(26, false);
        Rrep(j, (int)s[i].size()){
            exist[s[i][j] - 'a'] = true;
            rep(k, 26){
                if(exist[k] && hash_num.find(make_tuple(k, memo1[i][j].x, memo2[i][j].x, memo3[i][j].x, memo4[i][j].x)) != hash_num.end()){
                    ++res;
                }
            }
        }
    }
    cout<<res - N<<endl;
}

