void solve() {
	ll N;
	cin>>N;
	vector<string> a(N);
	rep(i,N){
		cin>>a[i];
		reverse(all(a[i]));
	}

	sort(a.begin(), a.end(), [](const string &x, const string &y) {
		return x.size() > y.size();
	});

	vector<vector<ll>> pos(N,vector<ll>(26,-INF));
	rep(i,N){
		rep(j,a[i].size())chmax(pos[i][a[i][j]-'a'],j);
	}

	set<ll> stringlen;
	rep(i,N){
		if(a[i].size()==(size_t)1)continue;
		stringlen.insert(a[i].size()-1);
	}

	using rh_type = __uint128_t;
	constexpr ll rh_mod = (ll)1e15 + 37;
	constexpr ll rh_base = (ll)1e4 + 7;

	map<rh_type,vector<ll>> hashmap;
	vector<RollingHash<rh_type>> hashs;
	rep(i,N){
		hashs.emplace_back(a[i], rh_mod, rh_base);
		for(ll len:stringlen){
			if(len>(ll)a[i].size())break;
			rh_type h=hashs[i].query(0,len);
			hashmap[h].emplace_back(i);
		}
	}

	ll ans=0;
	rep(index,N){
		if(a[index].size()==(size_t)1)continue;

		auto update = [&](ll i){
			if(index==i)return;
			ll x=a[index].back()-'a';
			if(pos[i][x]>=(ll)(a[index].size())-1)ans++;
		};
		ll h=hashs[index].query(0, a[index].size()-1);
		for(auto&& i:hashmap[h])update(i);
	}

	vector<ll> c(26,0);
	rep(i,N){
		if(a[i].size()!=(size_t)1)continue;
		c[a[i][0]-'a']++;
	}
	rep(i,N){
		if(a[i].size()==(size_t)1)continue;
		vector<ll> t(26,false);
		rep(j,a[i].size())t[a[i][j]-'a']=true;
		rep(j,26){
			if(t[j])ans+=c[j];
		}
	}
	p(ans);
}

