struct Node{
    LL cnt;
    LL leaf_cnt;
    LL symbol;
    vector<Node*> children;
    vector<LL> symbol_cnt;
    Node():symbol(0), leaf_cnt(0), cnt(0), children(26, nullptr), symbol_cnt(26){}
};

void addString(Node& node, string& s, LL cur){
    node.cnt++;
    if(cur == s.size()){
        node.leaf_cnt++;
    }else{
        if(node.children[s[cur] - 'a'] == nullptr){
            node.children[s[cur] - 'a'] = new Node();
            node.children[s[cur] - 'a']->symbol = s[cur] - 'a';
        }
        addString(*(node.children[s[cur] - 'a']), s, cur+1);
    }
}

void process(Node& node, LL& ans){
    for(LL i = 0; i < 26; ++i){
        if(node.children[i] != nullptr){
            process(*node.children[i], ans);
        }
    }
    //cerr << "node " << char(node.symbol + 'a') << endl;
    for(LL i = 0; i < 26; ++i){
        if(node.children[i] == nullptr) continue;
        for(LL j = 0; j < 26; ++j){
            node.symbol_cnt[j] += node.children[i]->symbol_cnt[j];
        }
    }
    for(LL i = 0; i < 26; ++i){
        if(node.children[i] == nullptr) continue;
        LL cnt = node.children[i]->leaf_cnt;
        ans += cnt * node.symbol_cnt[i];
        if(cnt > 0){
            ans += cnt * (cnt-1) / 2;
        }
        //cerr << "child " << char('a' + i) << " " << node.symbol_cnt[i] << " " << cnt << endl;
        node.symbol_cnt[i] += cnt;
    }
    node.symbol_cnt[node.symbol] += node.cnt - node.leaf_cnt;
}

int main(){
    LL n;
    cin >> n;
    Node root;
    for(LL i = 0; i < n; ++i){
        string s;
        cin >> s;
        reverse(s.begin(), s.end());
        addString(root, s, 0);
    }
    LL ans = 0;
    process(root, ans);
    cout << ans << endl;
    return 0;
}

