            res += sum[c[p.se] - 'a'].sum(upper_id[p.se] + 1) - sum[c[p.se] - 'a'].sum(p.se + 1);
        }else{
            p.se = -p.se;
            int al = p.se % 26, id = p.se / 26;
            sum[al].add(id, -1);
        }
    }
    cout<<res<<endl;
}

