void add(string x){

	int m = (int) x.size() ; 
	int cur = 1 ; 

	int mask = 0 ; 
	for(auto u: x){
		mask |= (1<<(u - 'a')) ; 
	}

	for(int i = 0 ;i < m; i++){
		if(!trie[cur][x[i]-'a'])
			trie[cur][x[i]-'a'] = ++ nodes ; 

		//cnt[cur] ++ ; 
		for(int j = 0 ;j < 26 ;j++){
			if(mask&(1<<j)){
				cntc[cur][j] ++ ; 
			}
		}
		cur = trie[cur][x[i]-'a'] ; 

	}
}

I solve(string x){
	int cur = 1 ; 
	int m = (int) x.size() ; 

	if(m == 1){
		ans+= cntc[cur][x[m-1] - 'a'] ; 
		return ; 
	}
	for(int i = 0 ;i < m ;i++){
		if(!trie[cur][x[i]-'a'])
			break ; 
		cur = trie[cur][x[i]-'a'] ;

		if(i == m - 2){
			ans += cntc[cur][ x[m-1] - 'a' ]; 
			break ; 
		}
	}
}

