const int maxn = 234567, base = 227;
int pre[26];
int n;
string s[maxn];
map<pii, int> m; 

void input()
{
	ios::sync_with_stdio(false); cin.tie(0);
	cin >> n;
	F1 (i, n)
		cin >> s[i];
}

void solve()
{
	F1 (i, n)
	{
		for (auto x : s[i]) ++pre[x - 'a'];
		int hsh = 0;
		for (int j = 0; j < 26; ++j)
			if (pre[j]) m[mp(0, j)]++;
		for (int j = s[i].length() - 1; j >= 0; --j)
		{
			--pre[s[i][j] - 'a'];
			hsh *= base; hsh += s[i][j];
			for (int j = 0; j < 26; ++j)
				if (pre[j]) m[mp(hsh, j)]++;
		}
	}
	int ans = 0;
	F1 (i, n)
	{
		int hsh = 0;
		for (int j = s[i].length() - 1; j >= 1; --j)
		{
			hsh *= base; hsh += s[i][j];
		}
		ans += m[mp(hsh, s[i][0] - 'a')];
	}
	cout << ans - n << '\n';
}

main()
{
	input();
	solve();
}

