// super rolling hash
struct SRH {
  RH rh;
  RH2 rh2;
  SRH(){}
  SRH(const string &s){
    rh = RH(s);
    rh2 = RH2(s);
  }

  ll get(ll l, ll r){
    return rh.get(l,r) + 1e9 * rh2.get(l,r);
  }
};



