  for(int i = 0; i < n; i++) {
    cin >> s[i];
    reverse(s[i].begin(), s[i].end());
  }
  sort(s.begin(), s.end(), [&](string a, string b){return a.length() > b.length();});
  vector<int> leaf(1);
  vector<vector<int>> to(1, vector<int>(26, -1));
  vector<vector<int>> sum(1, vector<int>(26));
  long long res = 0;
  for(string p : s) {
    int sz = p.length();
    int cur = 0;
    vector<int> path;
    path.push_back(cur);
    for(int i = 0; i < sz; i++) {
      int c = p[i] - 'a';
      if(to[cur][c] == -1) {
        to[cur][c] = leaf.size();
        leaf.push_back(0);
        to.push_back(vector<int>(26, -1));
        sum.push_back(vector<int>(26));
        cur = leaf.size() - 1;
      } else {
        cur = to[cur][c];
      }
      path.push_back(cur);
    }
    int root = path[sz - 1];
    int last_char = p.back() - 'a';
    res += sum[root][last_char];
    for(int i = 1; i <= sz; i++) {
      int node = path[i];
      int par = path[i - 1];
      vector<int> rev = sum[node];
      for(int j = 0; j < 26; j++) if(to[par][j] == node) rev[j] = leaf[node];
      for(int j = 0; j < 26; j++) sum[par][j] -= rev[j];
    }
    for(int i = 0; i <= sz; i++) {
      int node = path[i];
      leaf[node]++;
    }
    for(int i = sz; i > 0; i--) {
      int par = path[i - 1];
      int node = path[i];
      vector<int> add = sum[node];
      for(int j = 0; j < 26; j++) if(to[par][j] == node) add[j] = leaf[node];
      for(int j = 0; j < 26; j++) sum[par][j] += add[j];
    }
  }
  cout << res;
  return 0;
}

