	int nx = str[i]-'a';
	if (!trie[a].child[nx]) {
		trie[a].child[nx] = ++upto;
	}
	add(trie[a].child[nx], str, len, i+1);
}
ll ans = 0;
void dfs(int a, const char* str, int len, int i, int canchange) {
	if (!trie[a].am) return;
	if (len == i) {
		ans += trie[a].am;
		return;
	}
	int nx = str[i]-'a';
	if (canchange) {
		for (int j = 0; j < 26; j++) {
			if (j != nx) dfs(trie[a].child[j], str, len, i, 0);
		}
	}
	dfs(trie[a].child[nx], str, len, i+1, canchange);
}

