void pow_ini() {
    pow_.resize(HASHnum);
    rep(i, HASHnum) {
        pow_[i].clear();
        pow_[i].push_back(HASHlist[i]);
        rep(j, 62) {
            ll nxt = pow_[i][j] * pow_[i][j];
            nxt %= mod;
            pow_[i].push_back(nxt);
        }
    }
    return;
}

ll pow1(int i, ll b) {
    ll ans = 1;
    rep(n, 62) {
        if ((b >> n) % 2 == 1) {
            ans *= pow_[i][n];
            ans %= mod;
        }
    }
    return ans;
}

