class Rolling_hash {
public:
    int AN, BN;
    vector<vl> hash_A;
    vector<vl> hash_B;
    vector<vl> hash_sum_A;
    vector<vl> hash_sum_B;
    vector<vl> pow_HASH_inv;
    void h_ini_from_array(vl A, vl B);
    void h_ini_from_string(string A, string B);
    vl hash_val_A(int Ai, int len);
    vl hash_val_B(int Bi, int len);
    bool same(int Ai, int Bi, int len);
};


void Rolling_hash::h_ini_from_array(vl A, vl B) {
    hash_A.resize(HASHnum);
    hash_B.resize(HASHnum);
    hash_sum_A.resize(HASHnum);
    hash_sum_B.resize(HASHnum);
    pow_HASH_inv.resize(HASHnum);
    AN = A.size();
    BN = B.size();
    rep(i, HASHnum) {
        hash_A[i].resize(AN);
        hash_B[i].resize(BN);
        hash_sum_A[i].resize(AN + 1);
        hash_sum_B[i].resize(BN + 1);
        hash_sum_A[i][0] = 0;
        hash_sum_B[i][0] = 0;

        ll hashtmp = 1;
        rep(j, AN) {
            hash_A[i][j] = A[j] * hashtmp;
            hash_A[i][j] %= mod;
            hash_sum_A[i][j + 1] = hash_sum_A[i][j] + hash_A[i][j];
            hash_sum_A[i][j + 1] %= mod;
            hashtmp *= HASHlist[i];
            hashtmp %= mod;
        }
        hashtmp = 1;
        rep(j, BN) {
            hash_B[i][j] = B[j] * hashtmp;
            hash_B[i][j] %= mod;
            hash_sum_B[i][j + 1] = hash_sum_B[i][j] + hash_B[i][j];
            hash_sum_B[i][j + 1] %= mod;
            hashtmp *= HASHlist[i];
            hashtmp %= mod;
        }

        int powN = max(AN, BN);
        pow_HASH_inv[i].resize(powN);
        pow_HASH_inv[i][powN - 1] = pow1(i, mod - (ll)powN);
        for (int j = powN - 2; j >= 0; j--) {
            pow_HASH_inv[i][j] = pow_HASH_inv[i][j + 1] * HASHlist[i];
            pow_HASH_inv[i][j] %= mod;
        }
    }
    return;
}

void Rolling_hash::h_ini_from_string(string A, string B) {
    AN = A.length();
    BN = B.length();
    vl Avec(AN);
    vl Bvec(BN);
    rep(i, AN) {
        Avec[i] = (ll)A[i] - (ll)'a' + 1;
    }
    rep(i, BN) {
        Bvec[i] = (ll)B[i] - (ll)'a' + 1;
    }
    h_ini_from_array(Avec, Bvec);
    return;
}

vl Rolling_hash::hash_val_A(int Aj, int len) { // substr(Aj, len)
    vl hash_val(HASHnum);
    rep(i, HASHnum) {
        ll hash_tmp = hash_sum_A[i][Aj + len] - hash_sum_A[i][Aj];
        hash_tmp += mod;
        hash_tmp *= pow_HASH_inv[i][Aj];
        hash_tmp %= mod;
        hash_val[i] = hash_tmp;
    }
    return hash_val;
}

vl Rolling_hash::hash_val_B(int Bj, int len) { // substr(Bj, len)
    vl hash_val(HASHnum);
    rep(i, HASHnum) {
        ll hash_tmp = hash_sum_B[i][Bj + len] - hash_sum_B[i][Bj];
        hash_tmp += mod;
        hash_tmp *= pow_HASH_inv[i][Bj];
        hash_tmp %= mod;
        hash_val[i] = hash_tmp;
    }
    return hash_val;
}

bool Rolling_hash::same(int Ai, int Bi, int len) {
    return (hash_val_A(Ai, len) == hash_val_B(Bi, len));
}

