    map<P,ll> mp;

    auto judge = [&](string &sss,ll i){
        if(sid.count(sss)){
            ll j = sid[sss];
            if(i==j)return;
            if(i>j){
                mp[mp(j,i)]++;
            }else{
                mp[mp(i,j)]++;
            }
        }
    };

    rep(j,n){
        string &s = vs[j];
        ll len = s.length();
        string x;
        string y;

        Vec L(26,INF);
        Vec R(26,0LL);

        rep(i,len){
            ll c = s[i]-'a';
            chmin(L[c],i);
            chmax(R[c],i);
        }

        //1文字と後ろ
        rep(i, len){
            x += s[i];
            y += s[i];
            judge(x, j);

            rep(k,26){
                if(i<R[k]){
                    char c = 'a'+k;
                    y += c;
                    judge(y, j);
                    y.pop_back();
                }
            }
        }

        //1文字だけ
        rep(i, len){
            string tmp;
            tmp += s[i];
            judge(tmp,j);
        }

