namespace Trie
{
	int ch[M][26], sz;
	int val[M];

	void insert(char *str, int len)
	{
		int u = 0;
		for (int i = 0; i < len; i++)
		{
			int c = str[i] - 'a';
			if (!ch[u][c]) ch[u][c] = ++sz;
			u = ch[u][c];
		}
		val[u]++;
	}
}

int n;

int main()
{
	cin >> n;
	for (int i = 1; i <= n; i++)
	{
		scanf("%s", str + R[i-1] + 1);
		int len = strlen(str + R[i-1] + 1);
		L[i] = R[i-1] + 1;
		R[i] = L[i] + len - 1;
		reverse(str + L[i], str + R[i] + 1);
		Trie::insert(str + L[i], len);
	}

	LL Ans = 0;
	for (int i = 1; i <= n; i++)
	{
		static int cnt[27];
		memset(cnt, 0, sizeof(cnt));
		for (int j = L[i]; j <= R[i]; j++) cnt[str[j] - 'a']++;
		int u = 0;
		for (int j = L[i]; j <= R[i]; j++)
		{
			for (int k = 0; k < 26; k++)
				if (cnt[k] && Trie::ch[u][k])
					Ans += Trie::val[Trie::ch[u][k]];
			cnt[str[j] - 'a']--;
			u = Trie::ch[u][str[j] - 'a'];
		}
	}
	cout << Ans - n << endl;

	return 0;
}
