const int N=1000005;
const int mod[2]={1000000009,1019260817};
const int seed[2]={666,19260817};
namespace hsh{
	const int M=3051439;
	int A[M],B[M],L[M],h[M],sz;
	int harsh(ll a,ll b){
		return ((a<<13)^(a>>2)^(a<<4)^(b<<3)^(b>>5))%M;
	}
	void ins(int a,int b){
		int ha=harsh(a,b);
		A[++sz]=a,B[sz]=b,L[sz]=h[ha],h[ha]=sz;
	}
	int qry(int a,int b){
		int k=h[harsh(a,b)];
		for(;k;k=L[k]){
			if(A[k]==a&&B[k]==b){
				return 1;
			}
		}
		return 0;
	}
}
int f[2][N],rk[N],flag[26],n;
