		return s[a].size()<s[b].size();
	});
	rep(i,1,n){
		int k=rk[i],m=s[k].size();
		REP(t,2) per(j,m,1){
			f[t][j]=((ll)f[t][j+1]*seed[t]+s[k][j-1]-'a'+1)%mod[t];
		}
		memset(flag,0,sizeof flag);
		rep(j,1,m){
			flag[s[k][j-1]-'a']++;
			REP(c,26) if(flag[c]){
				int A=((ll)f[0][j+1]*seed[0]+c+1)%mod[0];
				int B=((ll)f[1][j+1]*seed[1]+c+1)%mod[1];
				ans+=hsh::qry(A,B);
			}
		}
		hsh::ins(f[0][1],f[1][1]);
	}
	cout<<ans<<endl;
	return 0;
}

