//    map<string, ll> mp;
    map<pll, ll> mp;
    ll ans = 0;
    rep(i, n) {
        string& t = v[i].second;
        pll p = RollingHash(t).get();
        ans += mp[p];
        vll c(26);
        rep(j, t.size()) ++c[t[j] - 'a'];
        string _t = "";
//        map<string, ll> _mp;
        map<pll, ll> _mp;
        rep(j, t.size()) {
            rep(k, 26) if(c[k] > 0) {
                pll q = RollingHash(_t + (char)('a' + k)).get();
                ++_mp[q];
            }
