struct Trie{
    Trie* children[26];
    long long is_end;
    long long num;

    Trie(){
        for(int i = 0; i < 26; ++i)
            children[i] = NULL;
        is_end = 0;
        num = 0;
    }
    Trie* upsert(char ch){
        if(children[ch - 'a'] == NULL){
            children[ch - 'a'] = new Trie();
        }
        return children[ch - 'a'];
    }
};

int main(){
    int n;
    scanf("%d", &n);
    char s[1000000];
    Trie *root = new Trie();
    Trie *p;
    int len;
    int i, j;
    int d[26];
    long long ans = 0;
    while(n--){
        scanf("%s", s);
        len = strlen(s);
        for(i = 0; i < 26; ++i)
            d[i] = 0x7FFFFFFF;
        for(i = len - 1; i >= 0; --i)
            d[s[i] - 'a'] = i;
        for(i = 0; i < 26; ++i)
            if(d[i] < len){
                p = root->upsert('a' + i);
                ++p->num;
                ans += p->is_end;
            }
        p = root;
        //printf("%lld ", ans);
        for(i = len - 1; i >= 1; --i){
            p = p->upsert(s[i]);
            for(j = 0; j < 26; ++j)
                if(d[j] < i){
                    ++p->upsert('a' + j)->num;
                    ans += p->upsert('a' + j)->is_end;
                    //printf("%c%d ", 'a' + j , ans);
                }
        }
        p = p->upsert(s[0]);
        ++p->is_end;
        //printf("%lld ", ans);
        ans += p->num - 1;
        //++p->num;
        //printf("%lld\n", ans);
    }
    printf("%lld\n", ans);
    return 0;
}

