const int N = 2e6 + 10;
const int A = 26;
struct Query {
	Query(int _c, int _x, int _sign) : c(_c), x(_x), sign(_sign) {};
	int c, x, sign;
};
int f[A][N];
int get(int c, int r) {
	int s = 0;
	while (r >= 0) {
		s += f[c][r];
		r &= r + 1;
		--r;
	}
	return s;
}
int get(int c, int l, int r) {
	return get(c, r) - get(c, l - 1);
}
void upd(int c, int pos) {
	while (pos < N) {
		f[c][pos]++;
		pos |= pos + 1;
	}
}
int main() {
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	int n;
	cin >> n;
	vector<string> a(n);
	vector<vector<Query>> q(n);
	vector<vector<int>> h(n);
	for (auto& e : a) {
		cin >> e;
		reverse(all(e));
	}
	sort(all(a));
	const int mod = 1e9 + 7;
	const int base = 239;
	for (int i = 0; i < n; i++) {
		int m = sz(a[i]);
		vector<int> cur(m + 1);
		for (int j = 0; j < m; j++)
			cur[j + 1] = (1ll * cur[j] * base % mod + a[i][j] - 'a' + 1) % mod;
		h[i] = cur;
	}
	for (int i = 0; i < n; i++) {
		int len = sz(a[i]) - 1;
		int H = h[i][len];
		int l = i, r = n;
		while (l + 1 < r) {
			int mid = (l + r) / 2;
			if (sz(h[mid]) <= len || h[mid][len] != H)
				r = mid;
			else
				l = mid;
		}
		int cnt = 0;
		for (char c : a[i])
			if (c == a[i].back()) cnt++;
		q[r - 1].pb(Query(a[i].back() - 'a', cnt, 1));
		q[i].pb(Query(a[i].back() - 'a', cnt, -1));
	}
	ll s = 0;
	for (int i = 0; i < n; i++) {
		vector<int> cnt(A);
		for (char c : a[i])
			cnt[c - 'a']++;
		for (int i = 0; i < A; i++)
			upd(i, cnt[i]);
		for (auto [c, x, sign] : q[i])
			s += sign * get(c, x, N - 1);
	}
	cout << s;
	return 0;
}

