int add_node(vector<array<int,26>>& trie) {
	int n = trie.size();
	trie.resize(n + 1);
	fill(trie[n].begin(), trie[n].end(), -1);
	return n;
}

i64 compute_score(vector<array<int,26>>& trie, vector<array<int,26>>& matches, vector<int>& paths, int v, int ok, int ch, array<int,26> pendings) {

	char ch_char = ch + 'a';

	if(ch >= 0) {
		ok += pendings[ch];
		pendings[ch] = 0;
	}

	dbg(v, ok, ch_char, paths[v]);
	i64 score = 0;
	score += (i64)paths[v] * ok;
	for(auto c : range(26)) {
		pendings[c] += matches[v][c];
	}

	for(auto c : range(26)) {
		int w = trie[v][c];
		if(w == -1) {
			continue;
		}
		i64 s = compute_score(trie, matches, paths, w, ok, c, pendings);
		score += s;
	}

	return score;
}

int main() {

	cin.tie(0);
	ios::sync_with_stdio(false);

	int N = read_item();
	vector<string> Ss(N);
	for(auto i : range(N)) {
		string s = read_item();
		Ss[i] = s;
	}

	vector<array<int,26>> trie;
	vector<array<int,26>> matches;
	vector<int> paths;

	add_node(trie);
	matches.push_back({});
	paths.push_back(0);

	for(auto s : Ss) {

		int v = 0;
		int len = s.size();

		for(auto i : revrange(len)) {

			char raw_ch = s[i];
			int c = raw_ch - 'a';

			if(i == 0) {
				matches[v][c] += 1;
			}

			int w = trie[v][c];
			if(w == -1) {
				w = add_node(trie);
				trie[v][c] = w;
				matches.push_back({});
				paths.push_back(0);
			}
			v = w;
		}

		paths[v] += 1;
	}

	array<int,26> pendings = {};
	i64 score = compute_score(trie, matches, paths, 0, 0, -1, pendings) - N;

	printf("%lld\n", score);

	return 0;
}

