int main()
{
	std::ios::sync_with_stdio(false);
	cin >> n;
	for (int i = 1; i <= n; ++i)
	{
		cin >> s[i];
		len[i] = s[i].length();
	}
	iota(id + 1, id + 1 + n, 1);
	sort(id + 1, id + 1 + n, cmp);
	ll ans = 0;
	int mx = 0;
	for (int i = 1; i <= n; ++i)
	{
		int x = id[i];
		while (mx > len[x] - 1)
			--mx;
		for (int c = 0; c < 26; ++c)
			cur[c] = 0;
		ull val = 0;
		for (int j = len[x] - 1; j >= 1; --j)
			val = val * Base + s[x][j] - 'a' + 1, ++cur[s[x][j] - 'a'];
		++cur[s[x][0] - 'a'];
		if (len[x] - 1 <= mx && len[x] <= Z)
			ans += t[len[x] - 1][val * Base + s[x][0] - 'a' + 1];
		val = 0;
		int lim = i == n ? -1 : len[id[i + 1]] - 1;
		if (lim >= 0)
			for (int c = 0; c < 26; ++c)
				if (cur[c])
					++t[0][val * Base + c + 1];
		for (int j = len[x] - 1, p = 1; j >= 0; --j, ++p)
		{
			val = val * Base + s[x][j] - 'a' + 1;
			cur[s[x][j] - 'a']--;
			if (p > Z || p > lim)
				break;
			for (int c = 0; c < 26; ++c)
				if (cur[c])
					++t[p][val * Base + c + 1], mx = max(mx, p);
		}
	}
	cout << ans << endl;
