void solve(vector <vector <string>> &A,ll &ats) {
	if (A.size()>1) {
	vector <vector <vector <string>>> D(26);
	if (A[0][0].length()==1) {
		vector <int> B(26,0);
		vector <int> C(26,0);
		for (int i=0;i<(int)A[0].size();i++) {
			int x=A[0][i][0]-'a';
			B[x]++;
			}
		for (int j=1;j<(int)A.size();j++) {
			for (int k=0;k<(int)A[j].size();k++) {
				isgood(A[j][k],C);
				}
			}
		for (int i=0;i<26;i++) {ats+=B[i]*C[i];}
		}
	else {
		vector <vector <string>> F(26);
		for (int i=0;i<(int)A[0].size();i++) {
			string s=A[0][i];
			int a=s[s.length()-1]-'a';
			s.pop_back();
			//cout<<a<<" "<<s<<endl;
			F[a].push_back(s);
			}
		//print(F);
		for (int i=0;i<26;i++) {
			if (F[i].size()>0) {D[i].push_back(F[i]);}
			}
		}
	for (int k=1;k<(int)A.size();k++) {
		vector <vector <string>> F(26);
	for (int i=0;i<(int)A[k].size();i++) {
		string s=A[k][i];
		int a=s[s.length()-1]-'a';
		s.pop_back();
		F[a].push_back(s);
		}
	for (int i=0;i<26;i++) {
		if (F[i].size()>0) {D[i].push_back(F[i]);}
		}}
	for (int i=0;i<26;i++) {
		if (D[i].size()>1) {
		solve(D[i],ats);}
		}
	}
	return;
	}

