#include <bits/stdc++.h>
using namespace std;
const int N=1000023;
int child[N][30];
int nxt=1;
bool isend[N];
vector <int> paths[N];
void construct_trie(vector <string> v,int n)
{
    for(int i=0;i<n;i++)
    {
        string s=v[i];
        int node=0;
        for(auto ch:s)
        {
            if(child[node][ch-'a']==0)
            {
                child[node][ch-'a']=nxt++;
            }
            node=child[node][ch-'a'];
            paths[i].push_back(node);
        }
        isend[node]=1;
    }
}
int main()
{
    int n;
    cin>>n;
    vector <string> v;
    for(int i=0;i<n;i++)
    {
        string s;
        cin>>s;
        reverse(s.begin(),s.end());
        v.push_back(s);
    }
    construct_trie(v,n);
    int ans=0;
    for(int i=0;i<n;i++)
    {
        string s=v[i];
        int cnt[30]={0};
        for(int j=s.length()-1;j>=0;j--)
        {
            cnt[s[j]-'a']++;
            int node=0;
            if(j>0)
                node=paths[i][j-1];
            for(char ch='a';ch<='z';ch++)
            {
                if(cnt[ch-'a']==0)
                    continue;
                int x=child[node][ch-'a'];
                if(x!=0 && isend[x])
                    ans++;
            }
        }
    }
    ans-=n;
    cout<<ans<<'\n';
}

