#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e5+7;

const int alphabet = 26;
const int offset = 'a';

struct node {
    int val;
    node* nxt[alphabet];

    node () {
        val = 0;
        for (int i = 0; i < alphabet; i++) nxt[i] = nullptr;
    }
};

struct Trie {
    node* root;

    Trie() {
        root = new node();
    }

    void addString(const string& s) {
        node* tmp = root;

        for (int i = 0; i+1 < s.size(); i++) {
            if (tmp->nxt[s[i]-offset]==nullptr)
                tmp->nxt[s[i]-offset] = new node();
            tmp = tmp->nxt[s[i]-offset];
        }
        tmp->val |= 1<<(s.back()-offset);
    }

    int countPrefixes(const string& s) {
        vector< int >fr(alphabet, 0);
        for (char c : s) fr[c-offset]++;

        int ans = 0;
        node* tmp = root;
        for (int i = 0; i+1 < s.size(); i++) {
            for (int j = 0; j < alphabet; j++) {
                if (fr[j]==0) continue;
                ans += (tmp->val>>j)&1;
            }
            fr[s[i]-offset]--;
            if (tmp->nxt[s[i]-offset]==nullptr) break;
            tmp = tmp->nxt[s[i]-offset];
        }

        return ans;
    }

    ~Trie() {
        deleteSubtree(root);
    }

    void deleteSubtree(node* u) {
        for (int i = 0; i < alphabet; i++)
            if (u->nxt[i]!=nullptr) deleteSubtree(u->nxt[i]);
        delete u;
    }
};

string s[MAXN];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;


    Trie trie;
    for (int i = 0; i < n; i++) {
        cin >> s[i];
        reverse(s[i].begin(), s[i].end());
        trie.addString(s[i]);
    }

    long long ans = 0;
    for (int i = 0; i < n; i++) {
        ans += trie.countPrefixes(s[i]);
    }

    cout << ans << "\n";

    return 0;
}

