struct rolling_hash {
  static constexpr uint64_t mod = 2e9 + 33;
  static inline array<long long, 2> base{randi(1e9, 2e9), randi(1e9, 2e9)};
  static inline array<vector<int>, 2> powb{vector{1}, vector{1}};
  int n;
  array<vector<int>, 2> h{vector{0}, vector{0}};
  template <class S = string> rolling_hash(const S& s = "") : n(size(s)) {
    for (int k : {0, 1}) {
      for (auto c : s) h[k].push_back((h[k].back() * base[k] + c) % mod);
      while ((int)size(powb[k]) <= n)
        powb[k].push_back(powb[k].back() * base[k] % mod);
    }
  }
  int get(int l, int r, int k) const {
    return (h[k][r] + (mod - h[k][l]) * powb[k][r - l]) % mod;
  }
  auto get(int l, int r) const { return make_pair(get(l, r, 0), get(l, r, 1)); }
};

struct chash {
  static uint64_t splitmix64(uint64_t x) {
    x += 0x9e3779b97f4a7c15;
    x = (x ^ x >> 30) * 0xbf58476d1ce4e5b9;
    x = (x ^ x >> 27) * 0x94d049bb133111eb;
    return x ^ x >> 31;
  }
  size_t operator()(pair<int, int> p) const {
    return splitmix64(p.first | (uint64_t)p.second << 32);
  }
};

