template< int char_size >
struct TrieNode {
  int par;
  int depth;
  array<int,char_size> childs;
  int exist;
  vector< int > accept;

  array<int,char_size> hist;

  TrieNode(int par, int depth) : par(par), depth(depth), exist(0) {
    childs.fill(-1);
    hist={};
  }
};

template< int char_size, int margin >
struct Trie {
  using Node = TrieNode< char_size >;

  vector< Node > nodes;
  int root;

  Trie() : root(0) {
    nodes.push_back(Node(-1,0));
  }

  void add(const string &str, int id) {
    int depth=0;
    int cur=root;
    while(depth<str.size()){
      const int c=str[depth]-margin;
      if(nodes[cur].childs[c]==-1) {
        nodes[cur].childs[c]=(int)nodes.size();
        nodes.push_back(Node(cur,depth+1));
      }
      cur=nodes[cur].childs[c];
      depth++;
    }
    nodes[cur].accept.push_back(id);

    array<int,char_size> itemhist={};
    cur=nodes[cur].par; //add対象文字列は長さ1以上なのでok
    while(true){
      const int c=str[nodes[cur].depth]-margin;

      itemhist[c]=1;
      nodes[cur].exist++;
      rep(c,char_size) nodes[cur].hist[c]+=itemhist[c];

      cur=nodes[cur].par;
      if(cur==-1) break;
    }
  }

  void add(const string &str) {
    add(str, nodes[0].exist);
  }

  void query(const string &str, const function< void(array<int,char_size>) > &f, int str_index, int node_index) {
    if(str_index == str.size()) {
      f(nodes[node_index].hist);
      return;
    } else {
      const int c = str[str_index] - margin;
      if(nodes[node_index].childs[c] == -1) return;
      query(str, f, str_index + 1, nodes[node_index].childs[c]);
    }
  }

  void query(const string &str, const function< void(array<int,char_size>) > &f) {
    query(str, f, 0, 0);
  }

  int count() const {
    return (nodes[0].exist);
  }

  int size() const {
    return ((int) nodes.size());
  }

};

