    RollingHash rh1(1012924417, M[i], c);
    // RollingHash rh2(924844033, M[i], c);
    pair<ll, ll> p = {rh1.getHash(1, M[i]), 0};
    counter[c[0] - 'a'][p]++;
    rhs[0].push_back(rh1);
    // rhs[1].push_back(rh2);

    s[i] = c;
    c += M[i] + 1;
  }

  ll ans = 0;

  for (int i = 0; i < N; i++) {
    bool f[26] = {};
    for (int j = 0; j < M[i]; j++) {
      f[s[i][j] - 'a'] = true;

      for (int k = 0; k < 26; k++) {
        if (!f[k]) continue;
        pair<ll, ll> p = {rhs[0][i].getHash(j + 1, M[i]), 0};
        auto it = counter[k].find(p);

        if (it != counter[k].end()) {
          ans += it->second - (j == 0);
        }
      }
    }
  }

  cout << ans << endl;

  return 0;
}

