struct Node {
  Node *nxt[26], *par;
  int f[26];
};

const int M = 2e6;
Node cache[M];
int cidx = 0;
Node *new_node() {
  return &cache[cidx++];
}

Node *root;

bool pres[26];
void add(const string& s) {
  Node *cur = root;
  for (char c: s) {
    int idx = c - 'a';
    if (!cur->nxt[idx]) {
      cur->nxt[idx] = new_node();
      cur->nxt[idx]->par = cur;
    }
    cur = cur->nxt[idx];
  }

  memset(pres, 0, sizeof pres);
  const int n = s.size();
  for (int i = n - 1; i >= 0; i--) {
    int idx = s[i] - 'a';
    pres[idx] = true;

    cur = cur->par;
    for (int j = 0; j < 26; j++) {
      if (pres[j]) cur->f[j]++;
    }
  }
}

int solve(const string& s) {
  Node *cur = root;
  const int n = s.size();
  for (int i = 0; i < n - 1; i++) {
    cur = cur->nxt[s[i] - 'a'];
  }
  return cur->f[s.back() - 'a'];
}

