    unordered_map<P, ll, HashPair> keys;
    rep(i, N){
        vector<int> list(26, inf);
        int siz = s[i].size();
        for(int j = siz - 1; 0 <= j; j--){ 
            list[s[i][j] - 'a'] = j;
        }
        ll hash = 0;
        for(int j = siz - 1; 0 <= j; j--){
            rep(k, 26){
                if(list[k] <= j){
