struct Trie{
  struct Node{
      int c;
      bool accept;
      vector<int> nextid;
      Node(int c):c(c),accept(false){
        nextid.assign(26,-1);
      }
  };
  vector<Node> g;
  Trie(){
    g.emplace_back(0);
  }
  bool match(int tmp,int c){
    assert(tmp < g.size());
    return (g[tmp].nextid[c] != -1) && g[g[tmp].nextid[c]].accept;
  }
  void insert(string& s){
    int tmp = 0;
    for(int i = 0;i < s.size();i++){
      int& nid = g[tmp].nextid[s[i] - 'a'];
      if(nid == -1){
        nid = g.size();
        g.emplace_back(s[i] - 'a');
      }
      tmp = nid;
    }
    g[tmp].accept = true;
  }
};

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n;
  cin >> n;
  vector<string> a(n);
  for(int i = 0;i < n;i++){
    cin >> a[i];
    reverse(all(a[i]));
  }
  sort(a.begin(),a.end(),[](string& s,string& t){
    return s.size() < t.size();
  });

  Trie trie;
  ll ans = 0;
  for(int i = 0;i < n;i++){
    string s = a[i];
    int sz = s.size();
    vector<int> last(26,-1);
    for(int j = sz - 1;j >= 0;j--) {
      if(last[s[j] - 'a'] == -1){
        last[s[j] - 'a'] = j;
      }
    }
    int tmp = 0;
    for(int j = 0;j < sz;j++){
      for(int c = 0;c < 26;c++){
        if(j <= last[c] && trie.match(tmp,c)){
          ans++;
        }
      }
      int nid = trie.g[tmp].nextid[s[j] - 'a'];
      if(nid == -1) break;
      else tmp = nid;
    }
    trie.insert(s);
  }
  cout << ans << '\n';
  return 0;
}

