struct Trie{
  map<char, int> ch;
  map<char, long long> ends;
  long long sum = 0;
};

void push(vector<Trie>& trie, int v, string& s, int i){
  if(s.size() == i+1){
    trie[v].ends[s[i]]++;
    return;
  }
  if(trie[v].ch.count(s[i]) == 0){
    trie[v].ch[s[i]] = trie.size();
    trie.push_back(Trie{});
  }
  trie[v].sum++;
  push(trie, trie[v].ch[s[i]], s, i+1);
}

long long search(vector<Trie>& trie, int v, string& s, int i, int& a){
  if(s.size() == i+1){
    a |= 1<<(s[i] - 'a');
    return 0;
  }
  long long res = 0;
  res += search(trie, trie[v].ch[s[i]], s, i+1, a);
  a |= 1<<(s[i] - 'a');

  for(int j=0; j<26; j++){
    if((~a>>j)&1) continue;
    if(trie[v].ends.count('a'+j)){
      res += trie[v].ends['a'+j];
    }
  }
  return res;
}

