template <int K, class T>
struct Trie
{
  struct Node
  {
    int c;
    std::array<int, K> nxt;
    std::array<int, K> cnt; // 文字cを含むような子孫の数
    int sz;                 // 部分木のサイズ

    explicit Node(int c) : c(c), sz(0)
    {
      nxt.fill(-1);
      cnt.fill(0);
    }
  };

  std::vector<Node> nodes;
  std::function<int(T)> enc;

  explicit Trie(T base)
  {
    nodes.emplace_back(-1);
    enc = [=](T c) { return c - base; };
  }

  explicit Trie(const std::function<int(T)> &enc) : enc(enc)
  {
    nodes.emplace_back(-1);
  }

  template <class Container>
  void add(const Container &s)
  {
    int pos = 0;
    for (T c : s)
    {
      int ci = enc(c);

      int npos = nodes[pos].nxt[ci];
      if (npos == -1)
      {
        npos = nodes.size();
        nodes[pos].nxt[ci] = npos;
        nodes.emplace_back(ci);
      }
      pos = npos;
    }

    ++nodes[pos].sz;
  }

  template <class Container>
  int find(const Container &s) const
  {
    int pos = 0;
    for (char c : s)
    {
      int ci = enc(c);
      pos = nodes[pos].nxt[ci];
      if (pos == -1)
        return -1;
    }
    return pos;
  }

  // cntを埋める
  void fillcnt()
  {
    for (int pos = (int)nodes.size() - 1; pos >= 0; --pos)
    {
      auto &node = nodes[pos];

      for (int c = 0; c < 26; ++c)
      {
        int npos = node.nxt[c];
        if (npos == -1)
          continue;

        const auto &cnode = nodes[npos];
        node.sz += cnode.sz;
        for (int d = 0; d < 26; ++d)
        {
          node.cnt[d] += cnode.cnt[d];
        }
      }

      // 全ての子孫はcを含む
      if (node.c != -1)
        node.cnt[node.c] = node.sz;
    }
  }
};

