void solve(void)
{
  int n;
  cin >> n;
  vector<string> vs(n);
  for (int i = 0; i < n; i++)
  {
    cin >> vs[i];
    reverse(ALL(vs[i]));
  }
  Trie<26, char> trie('a');
  for (auto &&s : vs)
  {
    trie.add(s);
  }
  trie.fillcnt();
  int res = 0;
  for (auto &&s : vs)
  {
    int last = s.back() - 'a';
    s.pop_back();
    int pos = trie.find(s);
    for (int ci = 0; ci < 26; ci++)
    {
      int npos = trie.nodes[pos].nxt[ci];
      if (npos == -1)
        continue;
      res += trie.nodes[npos].cnt[last];
      if (ci == last)
        res--;
    }
  }
  cout << res << endl;

  return;
}

