class rollinghash {
public:
    string s;
    ll base1 = 1007, base2 = 2009;
    ll mod1 = 1000000007, mod2 = 998244353;
    VL hash1, hash2, power1, power2;
    rollinghash(const string& _s) {
        s = _s;
        int n = s.size();
        hash1.resize(n + 1);
        hash2.resize(n + 1);
        power1.resize(n + 1, 1);
        power2.resize(n + 1, 1);
        rFOR(i, 0, n) {
            hash1[i] = (hash1[i + 1] * base1 + s[i]) % mod1;
            hash2[i] = (hash2[i + 1] * base2 + s[i]) % mod2;
            power1[i] = (power1[i + 1] * base1) % mod1;
            power2[i] = (power2[i + 1] * base2) % mod2;
        }
    }

    inline pair<ll, ll> hash(int l) const {
        return { hash1[l], hash2[l] };
    }
};

