        strpo2 = now2;
      }
    }

    auto po = make_pair(strpo, strpo2);
    char poo = S[SI[i].second][0];
    if (M.find(po) == M.end()) {
      map<char, ll> yo;
      yo[poo] = 1;
      M[po] = yo;
    } else {
      if (M[po].find(poo) == M[po].end())
        M[po][poo] = 1;
      else
        M[po][poo]++;
    }
  }
  cout << ans << endl;

  return 0;
}

