void add(const string &s) {
    memset(tot, 0, sizeof(tot));
    for (char c : s) {
        ++tot[c - 'a'];
    }
    int v = 0;
    for (char c : s) {
        for (int to = 0; to < max_c; ++to) {
            if (tot[to]) {
                ++cnt[v][to];
            }
        }
        --tot[c - 'a'];
        if (!nxt[v][c - 'a']) {
            nxt[v][c - 'a'] = ++first;
        }
        v = nxt[v][c - 'a'];
    }
}

