struct rolling_hash {
    using ull = unsigned long long int;
    using uint = unsigned int;
    const ull MASK30 = (1ULL << 30) - 1;
    const ull MASK31 = (1ULL << 31) - 1;
    const ull MOD = (1ULL << 61) - 1;
    const ull POSITIVIZER = MOD * ((1ULL << 3) - 1);

     uint base;
    vector<ull> pow_memo, hash;

    rolling_hash(const string& s) {
        random_device rd;
        uniform_int_distribution<uint> dist(129, numeric_limits<int>::max() - 1);
        base = dist(rd);
        init(s);
    }

    rolling_hash(const string& s, uint base) : base(base) { init(s); }

    void init(const string& s) {
        pow_memo.resize(s.size() + 1, 1);
        hash.resize(s.size() + 1);
        for (int i = 0; i < (int)s.size(); ++i) {
            pow_memo[i+1] = calc_mod(mul(pow_memo[i], base));
            hash[i+1] = calc_mod(mul(hash[i], base) + s[i]);
        }
    }

    ull substr(int begin, int length) {
        return calc_mod(hash[begin + length] + POSITIVIZER - mul(hash[begin], pow_memo[length]));
    }

    ull mul(ull a, ull b) {
        ull au = a >> 31;
        ull al = a & MASK31;
        ull bu = b >> 31;
        ull bl = b & MASK31;
        ull mid = au * bl + al * bu;
        ull midu = mid >> 30;
        ull midl = mid & MASK30;
        return ((au * bu) << 1) + midu + (midl << 31) + al * bl;
    }

    ull mul(ull a, uint b) {
        ull au = a >> 31;
        ull al = a & MASK31;
        ull bl = b & MASK31;
        ull mid = au * bl;
        ull midu = mid >> 30;
        ull midl = mid & MASK30;
        return midu + (midl << 31) + al * bl;
    }

    ull calc_mod(ull x) {
        ull xu = x >> 61;
        ull xl = x & MOD;
        ull res = xu + xl;
        if (res >= MOD) res -= MOD;
        return res;
    }
};

