		int c = (s[i] - 'a');
		if (!t[c][v]) {
			t[c][v] = ++sz;
			arr[0] = c, arr[1] = sz;
			tv[v].pb(arr);
		}
		v = t[c][v];
	}
	leaf[v] = 1;
}

void dfs(int v) {
	s[v] = leaf[v];
	for (auto i : tv[v]) {
		int c = i[0], to = i[1];
		dfs(to);
		for (int j = 0; j < 26; j++) {
			if (c == j)
				dp[v][j] += s[to];
			else
				dp[v][j] += dp[to][j];
		}
		s[v] += s[to];
	}
}

ll ans;

void go(int v, int p, int ch) {
	if (leaf[v]) {
		ans += dp[p][ch] - 1;
	}
	for (auto i : tv[v]) {
		int c = i[0], to = i[1];
		go(to, v, c);
	}
}

