class tree{
    public:
        class node{
            public:
                vector<int> contains;
                vector<node*> childs;
                node(){
                    contains.resize(26,0);
                    childs.resize(26,NULL);
                }
        };
        node *root;
        tree(){
            root = new node();
        }

        void add(node *n,vector<int> &line,vvector<bool> &has,int p){
            if(line.size()==p)return;
            rep(i,26){
                n->contains[i] += has[p][i];
            }
            if(n->childs[line[p]]==NULL){
                n->childs[line[p]] = new node();
            }
            add(n->childs[line[p]],line,has,p+1);
        }
        void add(vector<int> &line,vvector<bool> &has){
            add(root,line,has,0);
        }

        ll count(node *n,vector<int> &line,int p){
            if(p+1==line.size()){
                return n->contains[line[p]];
            }
            return count(n->childs[line[p]],line,p+1);
        }

        ll count(vector<int> &line){
            return count(root,line,0);
        }
};

