void solve(int n, vector<string> s) {
  vector<pair<int, string>> ls(n);
  rep(i, n)ls[i] = mp(sz(s[i]), s[i]);
  SORT(ls);
  auto rh_base = rolling_hash::generate_base();
  rolling_hash::init_power(ls.back().first, rh_base);
  vector<u_int64_t> as(26);
  rep(i, 26)as[i] = rolling_hash(string(1, 'a' + i), rh_base).query(0, 1);
  umap<u_int64_t, int> hs;
  int ans = 0;
  each(p, ls) {
    auto [l, x] = p;
    rolling_hash rh(x, rh_base);
    int cm = 0;
    rep(i, p.first) {
      cm |= lshift(x[i] - 'a');
      auto h = rh.query(i + 1, l);
      int l2 = l - i - 1;
      rep(j, 26) {
        if((cm >> j) & 1){
          auto jh = rolling_hash::combine(as[j], h, l2);
          ans += hs[jh];
        }
      }
    }
    hs[rh.query(0, l)]++;
  }
  COUT(ans);
}


