int val[1 << 21][26];

int add(string str) {
	int cx = 0, ret = 0, v[26];
	for (int i = 0; i < 26; i++) v[i] = (1 << 30);
	for (int i = (int)str.size() - 1; i >= 0; i--) v[str[i] - 'a'] = i;

	for (int i = (int)str.size() - 1; i >= 0; i--) {
		if (nex[cx][str[i] - 'a'] == -1) { nex[cx][str[i] - 'a'] = M; M++; }
		for (int j = 0; j < 26; j++) {
			if (v[j] <= i) val[cx][j] += 1;
		}
		if (i == 0) ret = cx;
		cx = nex[cx][str[i] - 'a'];
	}
	return ret;
}

