const int CCNT = 30;
struct node;

typedef node* pnode;

char cur[CCNT];

Long red;

struct node {
    pnode nxt[30];
    int e = 0;
    int av[30];

    node() {
        FILL(nxt, 0);
        FILL(av, 0);
        e = 0;
    }

    void add(const string &s, int p) {
        if (p == s.length()) {
            ++e;
            return;
        }

        REP(i, CCNT) {
            if (cur[i] > 0)
                av[i]++;
        }

        int ch = s[p] - 'a';
        cur[ch]--;

        if (nxt[ch] == 0) {
            nxt[ch] = new node();
        }

        nxt[ch] -> add(s, p+1);
    }

    Long cnt(const string &s, int p) {
        int ch = s[p] - 'a';

        if (p == s.length() - 1) {
            return av[ch];
        }

        if (nxt[ch] == 0) {
            cerr << "BAD";
            throw 1;
        }

        return nxt[ch]->cnt(s, p+1);

    }

    void dfs() {
        red += (1LL*e*e - 1LL*e*(e-1)/2);
        REP(i, CCNT) {
            if (nxt[i] != 0)
                nxt[i] -> dfs();
        }
    }
};

pnode root;

class BFirstSecond {
public:
    void solve(std::istream& in, std::ostream& out) {
        // fastIO();

        int n;
        root = new node();
        in >> n;
        vector<string> v(n);
        in >> v;
        for(auto &s: v)
            reverse(ALL(s));

        for(const auto &s: v) {
            FILL(cur, 0);
            for(auto c: s)
                cur[c-'a']++;
            root->add(s, 0);
        }

        int ans = 0;
        for (const auto&s: v) {
            ans += root->cnt(s, 0);
        }

        red = 0;
        root->dfs();
        ans -= red;

        out << ans << endl;
    }
};


int main() {
	BFirstSecond solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	cerr << 1.0 * clock() / CLOCKS_PER_SEC << endl;
	return 0;
}

