void solve(int n, vector<string> s) {
  vector<pair<int, string>> ls(n);
  rep(i, n)ls[i] = mp(sz(s[i]), s[i]);
  SORT(ls);
  vector<map<u_int64_t, int>> hs(26);
  auto rh_base = rolling_hash::generate_base();
  rolling_hash::init_power(1000000, rh_base);
  int ans = 0;
  each(p, ls) {
    auto [l, x] = p;
    rolling_hash rh(x, rh_base);
    vb cm(26);
    rep(i, p.first) {
      cm[x[i] - 'a'] = true;
      auto h = rh.query(i + 1, l);
      rep(j, 26) {
        if(cm[j])ans += hs[j][h];
      }
    }
    hs[x[0] - 'a'][rh.query(1, l)]++;
  }
  COUT(ans);
}


