const int N = 2e6 + 10;
const int A = 26;
struct Query {
	Query(int _c, int _x, int _sign) : c(_c), x(_x), sign(_sign) {};
	int c, x, sign;
};
int f[A][N];
int get(int c, int r) {
	int s = 0;
	while (r >= 0) {
		s += f[c][r];
		r &= r + 1;
		--r;
	}
	return s;
}
int get(int c, int l, int r) {
	return get(c, r) - get(c, l - 1);
}
void upd(int c, int pos) {
	while (pos < N) {
		f[c][pos]++;
		pos |= pos + 1;
	}
}
int main() {
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	int n;
	cin >> n;
	vector<string> a(n);
