	vector<vector<int>> h(n);
	for (auto& e : a) {
		cin >> e;
		reverse(all(e));
	}
	sort(all(a));
	const int mod = 998353244;
	const int base = 239;
	for (int i = 0; i < n; i++) {
		int m = sz(a[i]);
		vector<int> cur(m + 1);
		for (int j = 0; j < m; j++)
			cur[j + 1] = (1ll * cur[j] * base % mod + a[i][j] - 'a' + 1) % mod;
		h[i] = cur;
	}
	for (int i = 0; i < n; i++) {
		int len = sz(a[i]) - 1;
