		while (l + 1 < r) {
			int mid = (l + r) / 2;
			if (sz(a[mid]) < sz(a[i]) || a[mid].substr(0, len) != t)
				r = mid;
			else
				l = mid;
		}
		int cnt = 0;
		for (char c : a[i])
			if (c == a[i].back()) cnt++;
		q[r - 1].pb(Query(a[i].back() - 'a', cnt, 1));
		q[i].pb(Query(a[i].back() - 'a', cnt, -1));
	}
	ll s = 0;
	for (int i = 0; i < n; i++) {
		vector<int> cnt(A);
		for (char c : a[i])
			cnt[c - 'a']++;
		for (int i = 0; i < A; i++)
			upd(i, cnt[i]);
		for (auto [c, x, sign] : q[i])
			s += sign * get(c, x, N - 1);
	}
	cout << s;
	return 0;
}

