using namespace std;

using ll = long long;
using ull = unsigned long long;

mt19937 mt(736);


class trie
{
	struct node
	{
		array<int, 26> nxt{}, cnt{};
		bool fin;
		int sz;

		node() : fin(false), sz(0)
		{
			fill(nxt.begin(), nxt.end(), -1);
		}
	};

	vector<node> mem;


	int build_sz(int v)
	{
		if (v == -1)
			return 0;

		for (auto it : mem[v].nxt)
			mem[v].sz += build_sz(it);

		if (mem[v].fin)
			mem[v].sz++;

		return mem[v].sz;
	}

	array<int, 26> build_cnt(int v)
	{
		if (v == -1)
			return {0};

		auto &cur = mem[v];

		for (int i = 0; i < cur.nxt.size(); i++)
			if (cur.nxt[i] != -1)
			{
				auto q = build_cnt(cur.nxt[i]);

				q[i] = mem[cur.nxt[i]].sz;

				for (int j = 0; j < q.size(); j++)
					cur.cnt[j] += q[j];
			}

		return cur.cnt;
	}

public:
	explicit trie(const vector<string> &arr) : mem(1)
	{
		for (const auto &str : arr)
		{
			int last = 0;

			for (auto it : str)
			{
				if (mem[last].nxt[it - 'a'] == -1)
				{
					mem[last].nxt[it - 'a'] = mem.size();
					mem.emplace_back();
				}

				last = mem[last].nxt[it - 'a'];
			}

			mem[last].fin = true;
		}

		build_sz(0);

		assert(mem.front().sz == arr.size());

		build_cnt(0);
	}


	[[nodiscard]] ll get_ans() const
	{
		ll ans = 0;

		for (const auto &cur : mem)
		{
			for (int i = 0; i < cur.nxt.size(); i++)
				if (cur.nxt[i] != -1 && mem[cur.nxt[i]].fin)
					ans += cur.cnt[i];
		}

		return ans;
	}
};


