void Add(string S)
{
	for(int i=0;i<30;i++)
		occur[i]=1e9;
	for(int i=0;i<S.length();i++)
		occur[S[i]-'a']=min(occur[S[i]-'a'],i);
	pair<long long,long long> HASH1=make_pair(0,0);
	for(int i=0;i<26;i++)
		if(occur[i]!=1e9)
			M[make_pair(make_pair(i,0),HASH1)]++;
	for(int i=S.length()-1;i;i--)
	{
		HASH1.first*=26;
		HASH1.second*=26;
		HASH1.first+=S[i]-'a';
		HASH1.second+=S[i]-'a';
		HASH1.second%=MOD;
		for(int j=0;j<26;j++)
			if(occur[j]<i)
				M[make_pair(make_pair(j,S.length()-i),HASH1)]++;
	}
}
pair<long long,long long> HASH(string S)
{
	reverse(S.begin(),S.end());
	pair<long long,long long> HASH1=make_pair(0,0);
	for(int i=0;i<S.length();i++)
	{
		HASH1.first*=26;
		HASH1.second*=26;
		HASH1.first+=S[i]-'a';
		HASH1.second+=S[i]-'a';
		HASH1.second%=MOD;
	}
	return HASH1;
}
