// Solver Function(s)
class Trie
{
    public:
    unordered_map<char,Trie*> child;
    bool last;
    int pre_count=0, cnt=0;
    vector<string> prefix;
    int cntt=0;
    Trie()  
    {
        cnt=0;
        last=false;
        cntt=0;
    }   
    void insert(Trie *root, string s)
    {
        Trie *itr=root;
        each(x,s)
        {
            Trie *next=itr->child[x];
            if(!next)
            {
                next=new Trie();
                itr->child[x]=next;
            }
            itr=next;
            itr->cnt++;
        }
        itr->last=true;
        itr->cntt++;
    }
    int search(Trie *root, string s)
    {
        Trie *itr=root;
        each(x,s)
        {
            if(!itr->child[x])
            {
                return false;
            }
            itr=itr->child[x];
        }
        return itr->cntt;
    }
    bool empty(Trie *curr) 
    { 
        each(x,curr->child)
        {
            if(x.second)
            {
                return false;
            }
        }
        return true; 
    } 
    int countt(Trie *curr, char *ch)
    {
        int ret=0;
        each(x,curr->child)
        {
            if(x.second)
            {
                ret++;
                *ch=x.first;
            }
        }
        return ret;
    }
    Trie *rem(Trie *root, string s, int depth=0) //Remove the String
    {  
        if(!root) 
        {
            return NULL;
        }
        if(depth==sz(s)) 
        {          
            if(root->last) 
            {
                root->last=false;
            }
            if(empty(root)) 
            { 
                delete(root);
                root=NULL;
            }
            return root;
        }  
        root->child[s[depth]]->cnt--;
        root->child[s[depth]]=rem(root->child[s[depth]],s,depth+1);
        if(empty(root) && root->last==false)
        {
            delete(root);
            root=NULL;
        }
        return root;
    } 
    void all_pre(Trie *root, string s)
    {
        pre_count=0;
        prefix.clear();
        Trie *curr=root;
        each(x,s)
        {
            curr=root->child[x];
            if(!curr)
            {
                return;
            }
            root=curr;
        }
        all_pref(root,s);
    }
    void all_pref(Trie *curr, string s) //Strings having Prefix as "s"
    {
        if(curr->last==true) 
        {
            pre_count++;
            prefix.pb(s);
        }   
        each(x,curr->child)
        { 
            if(x.second) 
            {
                all_pref(x.second,s+x.first); 
            }
        } 
    }
    string walk(Trie *root) //Longest Common Prefix
    { 
        Trie *curr=root;
        char ch=' ';
        string ret="";
        while(countt(curr,&ch)==1 && curr->last==false) 
        { 
            curr=curr->child[ch];
            ret.pb(ch);
        } 
        return ret; 
    } 
    void dfs(Trie *root)
    {
        if(!root)
        {
            return;
        }
        each(x,root->child)
        {
            // Stuff, related to the Problem
            if(x.second)
            {
                dfs(x.second);
            }
        }
    }
};
void solve()
{
    int n;
    IN n;
    vector<string> v(n);
    read(v)
    Trie *tr=new Trie();
    loop(i,0,n)
    {
        vector<int> cnt(26,0);
        each(x,v[i])
        {
            cnt[x-'a']++;
        }
        string temp="";
        rloop(j,sz(v[i])-1,0)
        {
            loop(ch,0,26)
            {
                if(cnt[ch])
                {
                    tr->insert(tr,temp+(char)(ch+'a'));
                }
            }
            cnt[v[i][j]-'a']--;
            temp+=v[i][j];
        }
    }
    ll ans=0;
    loop(i,0,n)
    {
        reverse(all(v[i]));
        ans+=(ll)(tr->search(tr,v[i]));
        ans--;
    }
    OUT ans<<nl;
}  

