struct Trie{
  //vector<int> node;
  vector<gp_hash_table<char,int> > edge;
  vector<vector<int> > present; 
  int curr = 0;
  int newNode(){
    gp_hash_table<char,int> m;
    edge.pb(m);
    vector<int> v;
    present.pb(v);
    return curr++;
  }
  void init(){
    edge.clear();
    present.clear();
    edge.reserve(1000);
    present.reserve(1000);
    curr = 0;
    newNode();
  }

  void addWord(const string &s){
    //cout << "adding word: " << s << endl;
    int root = 0;
    int id = 0;

    if(present[root].size() == 0){
     present[root].resize(ALP);
     for(int i = 0;i < ALP; ++i) present[root][i] = 0;
    }
    vector<bool> valid(ALP,false);
    for(int i = 0;i < s.size(); ++i)
      valid[s[i]-'a'] = true;
    for(int i = 0;i < ALP;  ++i){
      if(valid[i]){
       present[root][i]++;
     }
    }
    if(v[id] == 1) ++id;

    for(int i = 0;i < s.size() ; ++i){
      if(edge[root].find(s[s.size()-1-i]) == edge[root].end())
        edge[root][s[s.size()-1-i]] = newNode();
      root = edge[root][s[s.size()-1-i]];
      if(v[id] == i+2){
        //cout << s << ' ' << id << ' ' << v[id] << endl;
        if(present[root].size() == 0){
         present[root].resize(ALP);
         for(int i = 0;i < ALP; ++i) present[root][i] = 0;
        }
        vector<bool> valid(ALP,false);
        for(int i = 0;i < s.size()-i-1; ++i)
          valid[s[i]-'a'] = true;
        for(int i = 0;i < ALP;  ++i){
          if(valid[i]){
           present[root][i]++;
         }
        }
        ++id;
      }
    }
    //cout << "added word: " << s << endl;
  }
  int query(int len, const string &s, char c){
    //cout << "querying word: " << s << endl;
    int root = 0;
    for(int i = 0;i < len ; ++i){
      if(edge[root].find(s[s.size()-1-i]) == edge[root].end()) return 0;
      root = edge[root][s[s.size()-1-i]];
    }
    //if(present[root].size() == 0) return 0;
    return present[root][c-'a'];
  }
};
