struct RollingHash {
private:
    using u64 = uint_fast64_t;
    using size_type = uint_fast32_t;
    using i128 = __int128_t;
    string str;
    vector<u64> hashed, power;
    static constexpr u64 mod = (1uL << 61) - 1;
    static constexpr u64 base = 1e9 + 7;
    //static constexpr u64 base = 1e9 + 9;
    static constexpr u64 mask30 = (1ul << 30) - 1;
    static constexpr u64 mask31 = (1ul << 31) - 1;
    u64 mul(i128 a, i128 b) const {
        i128 t = a * b;
        t = (t >> 61) + (t & mod);
        if (t >= mod)
            return (u64)(t - mod);
        return (u64)t;
    }
    //
public:
    void set(const string& _str) {
        str = _str;
        hashed.resize(str.size() + 1, 0);
        power.resize(str.size() + 1, 1);
        for (size_type i = 0; i < str.size(); i++) {
            hashed[i + 1] = mul(hashed[i], base) + str[i] + 1;
            power[i + 1] = mul(power[i], base);
            if (hashed[i + 1] >= mod)
                hashed[i + 1] -= mod;
        }
    }
    RollingHash() : str(){};
    RollingHash(const string& str) : str() {
        set(str);
    };
    u64 hash() const { return hashed.back(); }
    u64 hash(size_type l, size_type r) const {
        u64 ret = mod + hashed[r] - mul(hashed[l], power[r - l]);
        return ret < mod ? ret : ret - mod;
    }
    size_type size() const { return str.size(); }
};

int N;
vector<string> S;


void solve() {
    unordered_map<int, int> mp[30];
    int ans = 0;
    for (int i = 0; i < N; i++) {
        RollingHash Roll(S[i]);
        int mask = 0;
        for (int j = S[i].size() - 1; j >= -1; j--) {
            int hash = Roll.hash(0, j + 1);
            for (int x = 0; x < 26; x++) {
                if ((1 << x) & mask) {
                    if (mp[x].count(hash))
                        ans += mp[x][hash];
                }
            }
            if (j >= 0)
                mask |= 1 << S[i][j];
        }
        mp[(int)S[i].back()][Roll.hash(0, S[i].size() - 1)]++;
    }
    cout << ans << endl;
}

