	for (auto &s : a) {
		ull h = 0, p = 1;
		for (int i = s.size() - 1; i; i--, p *= base) {
			h *= base;
			h += p * s[i];
		}
		cnt[{s.size() - 1, h}][s[0]]++;
	}
	ll ans = 0;
	auto solve = [&](pair<int, ull> key, vector<int> &mask) {
		unordered_map<char, int> &now = cnt[key];
		for (int i = 0; i < 26; i++) {
			if (mask[i] && now.find('a' + i) != now.end()) ans += now['a' + i];
		}
	};
	for (auto &s : a) {
		ull h = 0, p = 1;
		vector<int> cnt(26, 0);
		for (auto c : s) cnt[c - 'a']++;
		solve({h, 0}, cnt);
		for (int i = s.size() - 1; i; i--, p *= base) {
			h *= base;
			h += p * s[i];
			cnt[s[i] - 'a']--;
			solve({s.size() - i, h}, cnt);
		}
	}
	cout << ans - n << '\n';
}

