class Node {
public:
    int total = 0;
    int count[26];
    int chidx[26];
    bool exist = false;
    Node() {
        fill(count, count+26, 0);
        fill(chidx, chidx+26, -1);
    }
    int child(char c) {
        return chidx[c - 'a'];
    }
    int getcount(char c) {
        return count[c - 'a'];
    }
};

vector<Node> pool(1);

void add(string &s) {
    int idx = 0;
    for (char c : s) {
        int nxt = pool[idx].child(c);
        if (nxt == -1) {
            nxt = pool.size();
            pool[idx].chidx[c - 'a'] = nxt;
            pool.push_back(Node());
        }
        idx = nxt;
    }
    pool[idx].exist = true;
}

void calc(int i) {
    for (int j = 0; j < 26; j++) {
        int k = pool[i].chidx[j];
        if (k >= 0) {
            calc(k);
            for (int jj = 0; jj < 26; jj++) {
                if (j == jj)
                    pool[i].count[jj] += pool[k].total;
                else
                    pool[i].count[jj] += pool[k].count[jj];
            }
            pool[i].total += pool[k].total;
        }
    }
    if (pool[i].exist) pool[i].total++;
}

void dump() {
    for (Node &n : pool) {
        cerr << n.total << " " << int(n.exist) << endl;
        for (int i = 0; i < 26; i++) cerr << n.count[i] << ' '; cerr << endl;
        for (int i = 0; i < 26; i++) cerr << n.chidx[i] << ' '; cerr << endl;
    }
}

