	for (auto& x : g)
		std::cin >> x;
	std::sort(g.rbegin(), g.rend(), [&](auto a, auto b) { return a.size() < b.size(); });
	ll ans = 0;
	int root = it++;
	for (int i = 0; i < n; ++i) {
		std::vector<int> m{0};
		for (auto c : g[i])
			m.push_back(m.back() | (1 << (c - 'a')));
		int s = root;
		for (auto c : std::string(g[i].rbegin(), g[i].rend())) {
			for (int k = 0; k < 26; ++k)
				if (((1 << k) & m.back()) && k != c - 'a')
					cnt[get_child(s, k)]++;
			s = get_child(s, c - 'a');
			cnt[s]++;
			m.pop_back();
		}
		ans += cnt[s] - 1;
	}
	std::cout << ans << '\n';
}

