template<int char_size, int base>
struct Trie {
  struct Node {
    vector<int> nex, accept;
    int c, common;
    //
    vi al;//
    Node(int c_) : c(c_), common(0) {
      nex.assign(char_size, -1);
      //
      al.assign(26, 0);//
    }
  };

  vector<Node> nodes;
  int root;
  Trie() : root(0) {
    nodes.assign(1, Node(root));
  }

  void insert(const string &word, int word_id) {
    //
    int aal[26] = {};
    rep(i, word.size()) {
      aal[word[i]-base]++;
    }//
    int node_id = 0;
    for(int i = 0; i < (int)word.size(); i++) {
      int c = word[i] - base;
      int &next_id = nodes[node_id].nex[c];
      //
      rep(j, 26) if(aal[j]) nodes[node_id].al[j]++;
      aal[c]--;//
      if(next_id == -1) {
        next_id = nodes.size();
        nodes.emplace_back(Node(c));
      }
      ++nodes[node_id].common;
      node_id = next_id;
    }
    ++nodes[node_id].common;
    nodes[node_id].accept.emplace_back(word_id);
  }
  inline void insert(const string &word) {
    insert(word, nodes[root].common);
  }

  bool search(const string &word, bool prefix = false) {
    int node_id = 0;
    for(int i = 0; i < (int)word.size(); i++) {
      int c = word[i] - base;
      int &next_id = nodes[node_id].nex[c];
      if(next_id == -1) {
        return false;
      }
      node_id = next_id;
    }
    return prefix ? true : !nodes[node_id].accept.empty();
  }

  inline bool start_with(const string &prefix) {
    return search(prefix, true);
  }

  //
  int query(const string &word) {
    int node_id = 0;
    for(int i = 0; i < (int)word.size()-1; i++) {
      int c = word[i] - base;
      int &next_id = nodes[node_id].nex[c];
      if(next_id == -1) {
        return 0;
      }
      node_id = next_id;
    }
    return nodes[node_id].al[word[word.size()-1] - base];
  }//

  int count() const {
    return nodes[0].common;
  }

  size_t size() const {
    return nodes.size();
  }
};

