}

void calc_dp(int v) {
	for (int i = 0; i < K; ++i) {
		int v1 = go[v][i];
		if (v1 != -1) {
			// cerr << "edge " << v << " " << v1 << " " << (char)('a' + i) << endl;
			calc_dp(v1);
