void solve() {
	ll N;
	cin>>N;
	vector<string> a(N);
	rep(i,N){
		cin>>a[i];
		reverse(all(a[i]));
	}

	vector<vector<ll>> pos(N,vector<ll>(26,-INF));
	rep(i,N){
		rep(j,a[i].size())chmax(pos[i][a[i][j]-'a'],j);
	}

	set<ll> stringlen;
	rep(i,N){
		if(a[i].size()==(size_t)1)continue;
		stringlen.insert(a[i].size()-1);
	}

	map<string,vector<ll>> hashmap;
	rep(i,N){
		for(ll len:stringlen){
			if(len>(ll)a[i].size())break;
			string h=a[i].substr(0,len);
			hashmap[h].emplace_back(i);
		}
	}

	ll ans=0;
	rep(i,N){
		if(a[i].size()==(size_t)1)continue;
		string h=a[i].substr(0, a[i].size()-1);
		for(auto&& index:hashmap[h]){
			if(index==i)break;
			ll x=a[i].back()-'a';
			if(pos[index][x]>=(ll)(a[i].size())-1)ans++;
		}
	}

	vector<ll> c(26,0);
	rep(i,N){
		if(a[i].size()!=(size_t)1)continue;
		c[a[i][0]-'a']++;
	}
	rep(i,N){
		if(a[i].size()==(size_t)1)continue;
		vector<ll> t(26,false);
		rep(j,a[i].size())t[a[i][j]-'a']=true;
		rep(j,26){
			if(t[j])ans+=c[j];
		}
	}
	p(ans);
}

