signed main(){
	int N;
	cin >> N;
	vector<string>v(N);
	REP(i, N) {
		cin >> v[i];
	}
	vector<vector<vector<int>>>vs;
	REP(i, N) {
		vector<vector<int>>tmp(v[i].size() + 1, vector<int>(26));
		REP(j, v[i].size()) {
			REP(k, 26) {
				tmp[j + 1][k] += tmp[j][k] + (v[i][j] - 'a' == k);
			}
		}
		vs.emplace_back(tmp);
	}
	vector<int>id(N);
	iota(ALL(id), 0);
	auto dfs = [&](auto&&f, vector<int>&a, int tail) -> long long {
		vector<int>cnt(26);
		REP(i, a.size()) {
			if(v[a[i]].size() - tail == 1) {
				++cnt[v[a[i]][0] - 'a'];
			}
		}
		long long ret = 0;
		REP(i, a.size()) {
			REP(j, 26) {
				int t = vs[a[i]][vs[a[i]].size() - tail - 1][j] - vs[a[i]][0][j];
				if(t) ret += cnt[j];
			}
		}
		ret -= accumulate(ALL(cnt), 0ll);
		vector<vector<int>>next(26);
		REP(i, a.size()) {
			if(v[a[i]].size() - tail == 1) continue;
			next[v[a[i]][v[a[i]].size() - tail - 1] - 'a'].emplace_back(a[i]);
		}
		vector<int>().swap(a);
		REP(i, 26) {
			if(next[i].size() == 0) continue;
			ret += f(f, next[i], tail + 1);
			vector<int>().swap(next[i]);
		}
		return ret;
	};
	out(dfs(dfs, id, 0));
}

