int insert(std::vector<int> &astr){
  int akt = 0;  
  int anxt = 0;
  int res = 0;
  for(int i = 0;i<astr.size();i++){
    if(i == astr.size()-1)res = akt;
    int ac = astr[i];
    if(tree[akt].nxt.count(ac)){
      anxt = tree[akt].nxt[ac];
    }else{
      trie tmp;
      tree.push_back(tmp);
      tree[akt].nxt[ac] = gc;
      anxt = gc;
      gc++;
    };
    for(int j = 0;j<30;j++){
      if(acnt[j]){
        if(tree[akt].cnt.count(j)){
          tree[akt].cnt[j]++;
        }else{
          tree[akt].cnt[j] = 1;  
        };
      };  
    };
    acnt[ac]--;
    akt = anxt;
  };
  return res;
};

