int64_t mod_pow(int64_t x,int64_t y,int64_t mod){
    int64_t ret=1;
    while(y){
        if(y&1)(ret*=x)%=mod;
        (x*=x)%=mod;
        y>>=1;
    }
    return ret;
}
auto meld(tuple<int64_t,int64_t,int64_t,int> s,tuple<int64_t,int64_t,int64_t,int> t){
    constexpr int64_t base=10007;
    constexpr int64_t mod[3]={1000000007LL,999999937LL,998244353LL};
    int64_t a[3]={};
    a[0]=(get<0>(s)*basemod[0]+get<0>(t))%mod[0];
    a[1]=(get<1>(s)*base%mod[1]+get<1>(t))%mod[1];
    a[2]=(get<2>(s)*base%mod[2]+get<2>(t))%mod[2];
    return make_tuple(a[0],a[1],a[2],get<3>(s)+get<3>(t));
}
