void solve(){
    // generate_array(size, min, max);
    ll n; in1(n);
    vector<string> ss(n);
    rep(i, n) in1(ss[i]);
    sort(all(ss), [](string s1, string s2)->bool{
        return s1.length() < s2.length();
    });

    vb2 inc(26, vb(n, false));
    map<ll, ll> cnt;
    map<ll, vector<string>> vs;
    rep(i, n){
        rep(j, ss[i].length())
            inc[ss[i][j] - 'a'][i] = true;
        rep(j, 26) cnt[j] += inc[j][i];
        ll x = ss[i].length() - 1;
        if (x != 0) vs[ss[i][x]].pb(ss[i]);
    }

    auto judge = [&](string si, string sj) -> bool{
        ll mi = si.length(), mj = sj.length();
        string ssi, ssj;
        ssi = substring(si, 1, mi - 1);
        ssj = substring(sj, mj - mi + 1, mj - 1);
        if (ssi != ssj) return false;
        rep(k, mj - mi + 1)
            if (si[0] == sj[k])
                return true;
        return false;
    };

    ll ans = 0;
    rep(i, n - 1)
        if (ss[i].length() == 1)
            ans += cnt[ss[i][0] - 'a'] - 1;

    for (auto& v: vs){
        ll m = v.e2.size();
        rep(i, m - 1) For(j, i + 1, m)
            ans += judge(v.e2[i], v.e2[j]);
    }

    prl(ans);

    // ### DEBUG PART ###
    auto naive_solver = [&](){
    };
    #ifdef _LOCAL
        naive_solver();
    #endif
}

