	LL ans = 0;
	int len;

	tr.init();
	while(n--){
		scanf("%s", s);
		len = strlen(s);
		reverse(s, s+len);

		ans += tr.query(len);
		ans -= tr.ins(len);
	}

	printf("%lld\n", ans);

	return 0;
}

