struct Node {
    bool is_word;
    int total;
    vector<Node*> children;
    vector<int> counts;
    Node(): is_word(false),
            total(0),
            children(26, nullptr),
            counts(26 ,0) {}
};

void insert(Node* root, const string& w, int offset = 0) {
    if (offset == w.size()) {
        root->is_word = true;
        root->total = 1;
        return;
    }
    int ind = w[offset] - 'a';
    if (root->children[ind] == nullptr) {
        root->children[ind] = new Node();
    }
    insert(root->children[ind], w, offset + 1);
}

long long compute_counts(Node* root) {
    long long ans = 0;
    for (int i = 0; i < 26; ++i) {
        Node *n = root->children[i];
        if (n == nullptr)
            continue;
        ans += compute_counts(n);
        root->total += n->total;
        for (int j = 0; j < 26; ++j) {
            if (j != i)
                root->counts[j] += n->counts[j];
        }
        root->counts[i] += n->total;
    }

    for (int i = 0; i < 26; ++i) {
        Node *n = root->children[i];
        if (n == nullptr)
            continue;
        if (n->is_word) {
            ans += root->counts[i] - 1;
//            cout << 'a' + i << " " << root->counts[i] - 1 << "\n";
        }
    }
    return ans;
}
