vector<pair<char, vector<ll>>> Trie;
vector<ll> cnt[26];
void trie_init(vector<string> &T) {
    Trie.push_back({'0', {}});
    rep(k, 26) cnt[k].pb(0);
    rep(i, T.size()) {
        ll id = 0;
        rep(j, T[i].size() - 1) {
            each(k, Trie[id].second) {
                if (Trie[k].first == T[i][j]) {
                    id = k;
                    goto next;
                }
            }
            Trie[id].second.push_back(Trie.size());
            id = Trie.size();
            Trie.push_back({T[i][j], {}});
            rep(k, 26) cnt[k].pb(0);
        next:;
        }
        cnt[T[i].back() - 'a'][id]++;
    }
}

ll find(string S) {
    vector<ll> V;
    ll id = 0, res = 0;

    ll sum[len(S) + 1][26];
    rep(i, len(S) + 1) rep(j, 26) sum[i][j] = 0;
    rep(i, len(S)) sum[i + 1][S[i] - 'a']++;
    dec(i, len(S) - 1, 0) rep(j, 26) sum[i][j] += sum[i + 1][j];

    rep(i, S.size()) {
        rep(k, 26) if (sum[i][k]) res += cnt[k][id];
        each(j, Trie[id].second) {
            if (Trie[j].first == S[i]) {
                id = j;
                goto success;
            }
        }
        break;
    success:;
    }
    return res;
}

