int N;
vector<string> S;
unordered_map<string,bool> chk;
void input(){
    fast_io();
    cin >> N;
    for (int i = 0; i < N; i++)
    {
        string t; cin >> t;
        S.push_back(t);
        chk[t] = true;
    }
}

int solve(){
    // auto cmp = [](string a, string b){return a.length()>b.length();};
    // sort(S.begin(),S.end(),cmp);
    ll ans = 0LL;
    for (int i = 0; i < N; i++)
    {
        string T = S[i];
        if((int)T.length()==1) continue;
        // cnt++;
        vector<bool> Head(30,false);
        for (int j = 0; j < (int)T.length(); j++)
        {
            Head[T[j]-'a'] = true;
            if(j==0) continue;
            string Tail = T.substr(j+1);
            for(char c='a';c<='z';c++){
                if(Head[c-'a']){
                    string Make = c+Tail;
                    if(chk[Make]) ans++;
                }
            }
        }
    }
    // cout << (ans-cnt) << endl;
    cout << (ans) << endl;
    return 0;
}   

int main()
{
    input();
    solve();
    return 0;
}

