const int N = 200200;
const int M = (int)1e6 + 7;
const int A = 26;
string s[N];
int n;
pii ord[N];
int go[M][A];
int m;
int a[M][A];
int cnt[A];
ll ans = 0;

void solve(int id) {
	int v = 0;
	int L = (int)s[id].length();
	for (int i = 0; i < A; i++)
		cnt[i] = 0;
	for (int i = 0; i < L; i++)
		cnt[(int)(s[id][i] - 'a')]++;
	for (int i = 0; i < L; i++) {
		for (int i = 0; i < A; i++)
			if (cnt[i] > 0)
				ans += a[v][i];
		if (i == L - 1) break;
		int c = (int)(s[id][i] - 'a');
		if (go[v][c] == 0) go[v][c] = m++;
		v = go[v][c];
	}
	int c = (int)(s[id].back() - 'a');
	a[v][c]++;
}

int main()
{
	startTime = clock();
//	freopen("input.txt", "r", stdin);
//	freopen("output.txt", "w", stdout);

	ios_base::sync_with_stdio(false);
	cin.tie(0);

	cin >> n;
	for (int i = 0; i < n; i++) {
		cin >> s[i];
		reverse(all(s[i]));
		ord[i] = mp((int)s[i].length(), i);
	}
	sort(ord, ord + n);
	m = 1;
	for (int i = 0; i < n; i++)
		solve(ord[i].second);
	cout << ans << "\n";

	return 0;
}

