typedef long long LL; 
const int MAX_N = 2e5 + 5; 
int N; 
string s[MAX_N]; 
int ch[MAX_N][26]; 
int ed[MAX_N], tot = 1; 
void ins(string s) {
    int o = 1; 
    for (int i = 0; i < (int)s.length(); i++) { 
        int c = s[i] - 'a'; 
        if (!ch[o][c]) ch[o][c] = ++tot; 
        o = ch[o][c]; 
    } 
    ed[o]++; 
} 
int main () {
    ios::sync_with_stdio(0); 
    cin >> N; 
    for (int i = 1; i <= N; i++) cin >> s[i]; 
    for (int i = 1; i <= N; i++) reverse(s[i].begin(), s[i].end()), ins(s[i]);
    LL ans = 0; 
    for (int i = 1; i <= N; i++) { 
        int o = 1, cnt = 0, buc[30];
        memset(buc, 0, sizeof(buc)); 
        for (int j = 0; j < (int)s[i].length(); j++) ++buc[s[i][j] - 'a']; 
        for (int j = 0; j < (int)s[i].length(); j++) { 
            for (int k = 0; k < 26; k++) 
                if (buc[k] && k != s[i][j] - 'a') cnt += ed[ch[o][k]]; 
            o = ch[o][s[i][j] - 'a'], buc[s[i][j] - 'a']--, cnt += ed[o]; 
        } 
        ans += cnt; 
    } 
    cout << ans - N << '\n'; 
    return 0; 
}

