vector<vector<SINT64>> dat(200005,vector<SINT64>(26));

SINT64 ch(vector<Pls> root) {

	if (root.size() == 0) {
		return 0;
	}

	SINT64 an = 0;
	vector<Pls> buf;
	string s = root[0].F;
	SINT64 ct = s.size()-1;
	vector<SINT64> sss(26,0);

	if (ct < 0) return 0;

	rep(i,0,ct) {
		sss[s[i]]++;
	}
//	rep(i,0,root.size()) {
//		put(root[i].F);
//	} cout << endl;

	rep(i,1,root.size()) {
		string p = root[i].F;
		SINT64 ok = 0;
		if (p.size() >= ct) {
			rep(j,0,ct) {
				if (p[j] != s[j]) {
					ok = 1;
					break;
				}
			}
		} else {
			ok = 1;
		}

		if (ok == 0) {
			rep(j,0,26) {
				dat[root[i].S][j] -= sss[j];
			}
			root[i].F.erase(root[i].F.begin(),root[i].F.begin()+ct);
//			put(root[i].F);
			buf.emplace_back(Pls(root[i].F,root[i].S));
//			put(s[s.size()-1]-'a');
			if (dat[root[i].S][s[s.size()-1]-'a'] != 0) {
				an++;
			}

		} else {
			if (buf.size() != 0) {
				an += ch(buf);
			}
			s = root[i].F;
			ct = s.size()-1;
			rep(j,0,26) {
				sss[j] = 0;
			}
			rep(j,0,ct) {
				sss[s[j]]++;
			}			
			buf.clear();
		}

	}
	if (buf.size() != 0) {
		an += ch(buf);
	}

	return an;
}

int main() {
	SINT64 N;	cin >> N;

	vector<Pls> root;
	SINT64 ans = 0;

	rep(i,0,N) {
		string s;	cin >> s;
		reverse(s.begin(),s.end());
		root.emplace_back(Pls(s,i));
		rep(j,0,s.size()) {
			dat[i][s[j]-'a']++;
		}
	}
	sort(root.begin(),root.end());
	ans += ch(root);
	put(ans);

	return 0;
}


