void add_string (const string & s, int indx = 0,  int v = 0) {
    if (indx == s.size()) return;

    char c = s[indx] - 'a';
    if (t[v].next[c] == -1) {
        memset(t[sz].next, 255, sizeof t[sz].next);
        memset(t[sz].go, 255, sizeof t[sz].go);
        memset(t[sz].subtree, 0, sizeof t[sz].subtree);
        t[sz].link = -1;
        t[sz].p = v;
        t[sz].pch = c;
        t[v].next[c] = sz++;
    }

    for (int i = 0; i < 26; ++ i){
        if (cnt_crr[i])
            t[v].subtree[i]++;
    }
    cnt_crr[c]--;
    add_string(s, indx + 1, t[v].next[c]);
}

int go (int v, char c);

int get_link (int v) {
    if (t[v].link == -1)
        if (v == 0 || t[v].p == 0)
            t[v].link = 0;
        else
            t[v].link = go (get_link (t[v].p), t[v].pch);
    return t[v].link;
}

int go (int v, char c) {
    if (t[v].go[c] == -1)
        if (t[v].next[c] != -1)
            t[v].go[c] = t[v].next[c];
        else
            t[v].go[c] = v==0 ? 0 : go (get_link (v), c);
    return t[v].go[c];
}

