class Trie {
  private:
    vvec<int> nxt;
    vec<int> end;  //suffix link,そのノードに存在する文字列の数
    vec<int> last; //その文字にとって最後のアルファベットだけ数える
    int root, p;
    int maxn; //文字の合計サイズ
    vvec<int> con;

  public:
    Trie(int maxn) : maxn(maxn), nxt(maxn, vec<int>(26, -1)), end(maxn, 0), last(maxn, 0), p(1), root(0), con(maxn, vec<int>(26, 0)) {}

    void insert(const string &s) {
        ll m = s.size();
        vec<bool> used(26, false);
        vec<bool> las(m, 0);
        REP2(i, m) {
            if(used[s[i] - 'a'])
                continue;
            used[s[i] - 'a'] = true;
            las[i] = true;
        }

        int now = root;
        for(int i = 0; i < s.size(); i++) {
            if(nxt[now][s[i] - 'a'] == -1)
                nxt[now][s[i] - 'a'] = p++;
            now = nxt[now][s[i] - 'a'];
            if(las[i])
                last[now]++;
        }
        end[now]++;
    }

    ll dfs(int now) {
        vec<ll> cone(26, 0);
        ll ret = 0;
        REP(i, 26) {
            if(nxt[now][i] == -1)
                continue;
            ret += dfs(nxt[now][i]);
            cone[i] += end[nxt[now][i]];

            con[now][i] += last[nxt[now][i]];
            REP(j, 26) {
                con[now][j] += con[nxt[now][i]][j];
            }
        }

        REP(i, 26) {
            if(cone[i] == 0)
                continue;
            ret += (con[now][i] - cone[i]) * cone[i];
        }

        return ret;
    }
};

