const int kAlpha = 26;
const int kMaxSize = 4e5;

struct Node {
	int children[kAlpha];
	bool is_end;
};
int num_nodes = 1;

Node nodes[kMaxSize];
int cnt_alpha[kAlpha];

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	cout << fixed << setprecision(11);
	cerr << fixed << setprecision(6);

	int n;
	cin >> n;
	vector<string> ss(n);
	for (auto &x : ss) { cin >> x; }
	sort(ALL(ss), [&](const string &lhs, const string &rhs) {
		return SZ(lhs) < SZ(rhs);
	});

	ll ans = 0;

	for (string str : ss) {
		for (int i = 0; i < kAlpha; ++i) {
			cnt_alpha[i] = 0;
		}
		for (char ch : str) {
			++cnt_alpha[ch - 'a'];
		}

		const int len = SZ(str);
		int curv = 0;
		for (int i = len - 1; i >= 0; --i) {
			const char ch = str[i];
			const int chidx = ch - 'a';
			for (int other = 0; other < kAlpha; ++other) {
				if (!cnt_alpha[other]) { continue; }
				const int s = nodes[curv].children[other];
				if (s && nodes[s].is_end) {
					++ans;
				}
			}
			--cnt_alpha[chidx];

			if (!nodes[curv].children[chidx]) {
				break;
			} else {
				curv = nodes[curv].children[chidx];
			}
		}

		curv = 0;
		for (int i = len - 1; i >= 0; --i) {
			const char ch = str[i];
			const int chidx = ch - 'a';
			int &s = nodes[curv].children[chidx];
			if (!s) {
				s = num_nodes++;
			}
			curv = s;
		}
		nodes[curv].is_end = true;
	}

	cout << ans << "\n";
}

