auto meld(tuple<int,int,int> s,tuple<int,int,int> t){
    constexpr int64_t base=10007;
    constexpr int64_t mod[2]={1000000007LL,999999937LL};
    int64_t a[2]={};
    a[0]=(int64_t(get<0>(s))*base%mod[0]+get<0>(t))%mod[0];
    a[1]=(int64_t(get<1>(s))*base%mod[1]+get<1>(t))%mod[1];
    return make_tuple(a[0],a[1],get<2>(s)+get<2>(t));
}
auto make(char c){
    return make_tuple(int(c),int(c),1);
}
auto empty(){
	return make_tuple(0,0,0);
}

int main(){
	auto f=[](auto s){return get<0>(s)^get<1>(s);};
	unordered_map<tuple<int,int,int>,int,decltype(f)>m(10,f);
	int n;
	cin>>n;
	vector<tuple<int,int,int>>v(n,empty());
	for(int i=0;i<n;++i){
		string s;
		cin>>s;
		reverse(all(s));
		vector<int>cnt(26,0);
		for(int j=0;j<(int)s.size();++j)cnt[s[j]-'a']++;
		bitset<26>b;
		for(int j=0;j<26;++j)if(cnt[j])b[j]=1;
		for(int j=0;j<(int)s.size();++j){
			for(int k=b._Find_first();k<26;k=b._Find_next(k)){
				auto e=meld(v[i],make(k+'a'));
				m[e]++;
			}
			v[i]=meld(v[i],make(s[j]));
			cnt[s[j]-'a']--;
			if(!cnt[s[j]-'a'])b[s[j]-'a']=0;
		}
	}
	int64_t ans=0;
	for(int i=0;i<n;++i){
		ans+=m[v[i]]-1;
	}
	cout<<ans<<endl;
}

