#include <bits/stdc++.h>
using namespace std;

const int N = 26; // changable

struct Trie {
	Trie* child[N];
	int endVal;
	Trie(){
		for(int i = 0; i < N; i++){
			child[i] = NULL;
		}
		endVal = 0;
	}
	~Trie(){
		for(int i = 0; i < N;i ++){
			delete child[i];
		}
	}
} *root = new Trie();

void add(string s){
	Trie* cur = root;
	for(int i = 0; i < s.length(); i++){
		int j = s[i] - 'a';
		if(cur -> child[j] == NULL){
			cur -> child[j] = new Trie();
		}
		cur = cur -> child[j];
	}
	cur -> endVal ++;
}

int search(string s){
	Trie* cur = root;
	for(int i = 0; i < s.length(); i++){
		int j = s[i] - 'a';
		if(cur -> child[j] == NULL) return 0;
		cur = cur -> child[j];
	}
	if(cur == NULL) return 0;
	else return cur -> endVal;
}

