  string last=a.substr(2,a_size-2);
  if(a_size==2){
    auto it2=memo[x].lower_bound({a[0]-'a',0});
    if(it2->first.first==a[0]-'a')return 1;
    else return 0;
  }
  if(last!=b.substr(n-(a_size-2),a_size-2))return 0;
  auto it=memo[x].find({a[1]-'a',n-(a_size-2)-1});
  if(it==memo[x].end())return 0;
  else return 1;
  rep(i,n){
    if(cur>0){
      if(a[1]==b[i]){
        if(n-1-i==a.length()-2){
          if(b.substr(i+1,n-1-i)==a.substr(2,a_size-2))return 1;
          else return 0;
        }
      }
      else{
        if(n-1-i<=a_size-2)return 0;
      }
    }
    else if(a[cur]==b[i])++cur;
  }
  return 0;
}

