    map<char, Node*> nxt;
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n; cin >> n;
    V<string> s(n);
    for (int i = 0; i < n; i++) {
        cin >> s[i]; reverse(ALL(s[i]));
    }
    sort(ALL(s), [&](string i, string j) {
        return i.size() > j.size();
    });

    Node* root = new Node;
    root->count = 0;

    ll ans = 0;
    for (int i = 0; i < n; i++) {
        Node* tmp = root;
        bool ok = true;
        int j;
        for (j = 0; j < int(s[i].size()) - 1; j++) {
            int nxtc = s[i][j];
            if (tmp->nxt.find(nxtc) != tmp->nxt.end()) tmp = tmp->nxt[nxtc];
            else {
                ok = false;
                break;
            }
        }
        // cout << i << ' ' << j << '\n';

        // s[i] を接頭辞に持つ文字列がある場合、縮約
        if (ok) {
            queue<Node*> que;
            for (P<char, Node*> p: tmp->nxt) que.push(p.second);
            while (!que.empty()) {
                Node* q = que.front(); que.pop();
                for (P<char, Node*> p: q->nxt) {
                    // cout << p.first << ' ' << p.second->count << '\n';
                    if (tmp->nxt.find(p.first) == tmp->nxt.end()) {
                        tmp->nxt[p.first] = new Node;
                        tmp->nxt[p.first]->count = 0;
                    }
                    tmp->nxt[p.first]->count += p.second->count;
                    que.push(p.second);
                }
                q->nxt.clear();
            }
            if (tmp->nxt.find(s[i].back()) != tmp->nxt.end()) {
                ans += ll(tmp->nxt[s[i].back()]->count);
            }
        } else {
            for (int jj = j; jj < int(s[i].size()); jj++) {
                int nxtc = s[i][jj];
                tmp->nxt[nxtc] = new Node;
                tmp->nxt[nxtc]->count = 1;
                tmp = tmp->nxt[nxtc];
            }
            tmp->count = 1;
        }
    }
    cout << ans << '\n';
    return 0;
}

