    for(int i=n-1;i>=0;i--){
        pref = (pref*p+(s[i]-'a'+1))%m;
        letras[s[i]-'a'+1]--;
        for(int j=1;j<27;j++){
            if(letras[j]){
                cnt[(pref*p+j)%m]++;
            }
        }
    }
    return pref;
}

