struct HashTable {
	int val[MOD + 2], id[MOD + 2];
	int ton(ULL x) {
		int now = x % MOD;
		while(id[now] != -1 && id[now] != x) {
			now += 107;
			if(now >= MOD) now -= MOD;
		}
		return now;
	}
	void insert(ULL pos, int v) {
		int now = ton(pos);  //if(id[now] != -1) return;
		id[now] = pos; val[now] = v;
	}
	int query(int pos) {
		int now = ton(pos);
		return val[now];
	}
	void reset() {
		memset(id, -1, sizeof(id));
		memset(val, 0, sizeof(val));
	}
}
