void chemthan() {
    int n; cin >> n;
    static const int maxn = 2e6;
    static int nxt[maxn][26];
    static int cnt[maxn][26];
    int ptr = 0;
    auto add = [&] (string s) {
        int k = sz(s);
        vi f(k);
        int msk = 0;
        FORd(i, k, 0) {
            int d = s[i] - 'a';
            msk |= 1 << d;
            f[i] = msk;
        }
        int rt = 0;
        FOR(j, 0, 26) if (bit(f[0], j)) {
            cnt[rt][j]++;
        }
        FOR(i, 0, k - 1) {
            int d = s[i] - 'a';
            if (!nxt[rt][d]) {
                nxt[rt][d] = ++ptr;
            }
            rt = nxt[rt][d];
            FOR(j, 0, 26) if (bit(f[i + 1], j)) {
                cnt[rt][j]++;
            }
        }
    };
    long long res = 0;
    auto upd = [&] (string s) {
        int k = sz(s);
        int rt = 0;
        FOR(i, 0, k - 1) {
            int d = s[i] - 'a';
            rt = nxt[rt][d];
        }
        int d = s[k - 1] - 'a';
        res += cnt[rt][d];
    };
    vector<string> s(n);
    FOR(i, 0, n) {
        cin >> s[i];
        reverse(all(s[i]));
        add(s[i]);
    }
    FOR(i, 0, n) {
        upd(s[i]);
        res--;
    }
    cout << res << "\n";
}

