class rollinghash {
    int base1 = 1007, base2 = 2009;
    int mod1 = 1000000007, mod2 = 998244353;
    VI hash1, hash2, power1, power2;
public:
    rollinghash(const string& s) {
        int n = s.size();
        hash1.resize(n + 1);
        hash2.resize(n + 1);
        rFOR(i, 0, n) {
            hash1[i] = (ll(hash1[i + 1]) * base1 + s[i]) % mod1;
            hash2[i] = (ll(hash2[i + 1]) * base2 + s[i]) % mod2;
        }
    }
    inline pair<int, int> hash(int l, char c) const {
        return { (ll(hash1[l]) * base1 + c) % mod1, (ll(hash2[l]) * base2 + c) % mod2 };
    }
    inline pair<int, int> hash(int l) const {
        return { hash1[l], hash2[l] };
    }
};

