signed main(){
  int n;cin>>n;
  vector<string> s(n);
  for(int i=0;i<n;i++)cin>>s[i];
  for(int i=0;i<n;i++)reverse(s[i].begin(),s[i].end());
  sort(s.begin(),s.end());
  for(int i=0;i<n;i++){
    vector<int> memo(26,-1);
    for(int j=0;j<s[i].size();j++)memo[s[i][j]-'a']=j;
    for(int j=0;j<26;j++)v[j].push_back(memo[j]);
  }
  for(int i=0;i<26;i++)seg[i].build(v[i]);
  for(int i=0;i<n;i++){
    ll a=1,b=1,c=1,d=1;
    hsh[i].push_back(PP(P(a,b),P(c,d)));
    for(int j=0;j<s[i].size();j++){
      (a*=s[i][j]*(j+1))%=MODA;
      (b*=s[i][j]+j+124)%=MODB;
      (c*=(s[i][j]*(j+7)))%=MODC;
      (d+=(s[i][j]*(j*j+5)%MODD))%=MODD;
      hsh[i].push_back(PP(P(a,b),P(c,d)));
    }
  }
  ll ans=0;
  for(int i=0;i<n;i++){
    int st=-1,r=i+1;//(st,i]がiと被る
    int L=s[i].size();
    while(r-st>1){
      int mid=(r+st)>>1;
      (hsh[mid].size()>=L&&hsh[mid][L-1]==hsh[i][L-1]?r:st)=mid;
    }
    int l=i-1,en=n;//[i,en)がiと被る
    while(en-l>1){
      int mid=(l+en)>>1;
      (hsh[mid].size()>=L&&hsh[mid][L-1]==hsh[i][L-1]?l:en)=mid;
    }
    int la=s[i].back()-'a';
    ans+=(ll)seg[la].Q(st+1,en,L-1)-1LL;
  }
  cout<<ans<<endl;
}

