struct Trie{
    char a_init; // 最初の文字
    int D; // 文字の種類数
    int INVALID = -1;
    std::vector<std::vector<int>> child;
    // 子のid．サイズは（頂点数，文字の種類数）で，child[v][c]は「頂点vから文字cで下降したときの頂点のid」
    // 行き先に頂点がない場合はINVALIDが格納される
    using T_NODE = int;
    vector<T_NODE> v_info;
    vector<int> par;
    vector<int> par_edge;
    // v_info には適当に頂点vの性質をメモすることができる
    // 例えば add_word の info に1を入れると出現回数のカウントができる
    Trie(char a_init = 'a', int D = 26) : a_init(a_init), D(D), child(1, std::vector<int>(D, INVALID)), v_info(1) {}
    int add_word(string str, T_NODE info) {
        int now = 0; // 頂点のid
        for (auto &c : str) {
            if (child[now][c - a_init] == INVALID) {
                int sz = child.size();
                child[now][c - a_init] = sz;
                child.emplace_back(std::vector<int>(D, INVALID));
                sz++;
                v_info.resize(sz);
                par.resize(sz);
                par_edge.resize(sz);
            }
            int ch = child[now][c - a_init];
            par[ch] = now;
            par_edge[ch] = c - a_init;
            now = ch;
        }
        v_info[now] += info;
        return now;
    }

    // 操作はこの上でdfsなどをすればOK
};

