                                break;
                        }
                        v = v->child[c];
                        for (int k = 0; k < 26; k++) {
                                if (f[k] != -1 && f[k] < j) {
                                        ans += v->cnt[k];
                                }
                        }
                }
                for (int k = 0; k < 26; k++) {
                        if (f[k] != -1) {
                                ans += root->cnt[k];
                        }
                }
                add(root, s);
        }
        cout << ans << endl;
}


