int bs(string &s,vector<pair<string,int>> &v){
  int l = -1,r = v.size()-1;
  while(r-l > 1){
    int mid = (r+l)/2;
    if(v[mid].first < s)l = mid;
    else r = mid;
  }
  return r;
}

