template <unsigned long long mod> class mint{
    public:
        ll x;
        unsigned long long mod_plus;
        mint(){x = 0;}
        mint(ll _x){
            mod_plus = (LLONG_MAX / mod) * mod;
            x = (_x < 0 ? ((_x += mod_plus) < 0 ? _x + mod_plus : _x) : _x)%mod;
        }

        mint operator-(){
            return x == 0 ? 0 : mod - x;
        }
        mint& operator+=(const mint& a){
            if((x += a.x) >= mod) x -= mod;
            return *this;
        }
        mint operator+(const mint& a) const{
            return (*this) += a;
        }
        mint& operator-=(const mint& a){
            if((x -= a.x) < 0) x += mod;
            return *this;
        }
        mint operator-(const mint& a) const{
            return (*this) -= a;
        }
        mint& operator*=(const mint& a){
            (x *= a.x)%=mod;
            return *this;
        }
        mint operator*(const mint& a) const{
            return (*this) *= a;
        }
        mint pow(unsigned long long pw) const{
            mint res(1), comp(*this);
            while(pw){
                if(pw&1) res *= comp;
                comp *= comp;
                pw >>= 1;
            }
            return res;
        }
        //以下、modが素数のときのみ
        mint inv() const{
            mint res(*this);
            return res.pow(mod - 2);
        }
        mint& operator/=(const mint &a){
            (x *= a.inv().x)%=mod;
            return *this;
        }
        mint operator/(const mint &a) const{
            return (*this) /= a;
        }
};

