struct Trie {
    struct Node {
        vector<int> child;
        bool is_end = false;

        Node() : child(26, -1) {};
    };

    vector<Node> nodes;
    vector<vector<int>> paths;

    Trie(int N) : nodes(1), paths(N) {}

    void add(string& s, int id) {
        int node = 0;
        for (char c : s) {
            paths[id].push_back(node);
            if (nodes[node].child[c - 'a'] == -1) {
                nodes[node].child[c - 'a'] = nodes.size();
                nodes.emplace_back();
            }
            node = nodes[node].child[c - 'a'];
        }
        nodes[node].is_end = true;
    }

    int query(string& s, int id) {
        int ret = 0;
        set<char> suffix;
        for (int j = s.size() - 1; j >= 0; j--) {
            suffix.insert(s[j]);
            int node = paths[id][j];
            for (char c : suffix) {
                if (nodes[node].child[c - 'a'] != -1) {
                    ret += nodes[nodes[node].child[c - 'a']].is_end;
                }
            }
        }
        return ret;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
