        cin >> S[i];
        reverse(S[i].begin(), S[i].end());
    }
    Trie trie(N);
    ll ans = 0;
    for (int i = 0; i < N; i++) trie.add(S[i], i);
    for (int i = 0; i < N; i++) ans += trie.query(S[i], i);
    ans -= N;
    cout << ans << endl;
}

