			cnt[c - 'a']++;
		}
		int hash = 0;
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < 26; ++j) {
				int curhash = hash * pw + (j + 1);
				curhash %= mod;
				if (cnt[j] and mp[i + 1].count(curhash)) {
					ans += mp[i + 1][curhash];
				}
			}
			--cnt[s[n - i - 1] - 'a'];
			hash = hash * pw + (s[n - i - 1] - 'a') + 1;
			hash %= mod;
		}
		++mp[n][hash];
	}
	return ans;
}

