template<char start, int C>
struct Trie {
	struct Node {
		vector<int> nxt, accept;
		int exist;
		Node() : exist(0) { nxt.assign(C, -1); }
	};

	vector<Node> nodes;
	int root;
	Trie() : root(0) { nodes.push_back(Node()); }

	int count() const { return nodes[0].exist; }
	int size() const { return (int)nodes.size(); }

	void update_direct(int node, int id) {
		nodes[node].accept.push_back(id);
	}
	void update_child(int node, int child, int id) {
		++nodes[node].exist;
	}

	void add(const string& str, int str_index, int node_index, int id) {
		if (str_index == str.size()) {
			update_direct(node_index, id);
			return;
		}
		int c = str[str_index] - start;
		if (nodes[node_index].nxt[c] == -1) {
		   	nodes[node_index].nxt[c] = (int)nodes.size();
			nodes.push_back(Node());
		}
		add(str, str_index + 1, nodes[node_index].nxt[c], id);
		update_child(node_index, nodes[node_index].nxt[c], id);
	}
	void add(const string& str, int id) { add(str, 0, 0, id); }
	void add(const string& str) { add(str, nodes[0].exist); }

	int find(const string& str) {
		int node_index = 0;
		for (auto c : str) {
			node_index = nodes[node_index].nxt[c - start];
			if (node_index < 0) { return node_index; }
		}
		return node_index;
	}
};

