			hs=hs*P+s[i][j]-'a'+1;
			cnt[s[i][j]-'a'+1]--;
			for(int k=1;k<=26;k++)if(cnt[k])alp[hs*P+k]++;
		}
		ans+=alp[hs]-1;
	}
	printf("%lld\n",ans);
	return 0;
}

