int main() {
  ios_base::sync_with_stdio(0); cin.tie(0);

  int n_strings; cin >> n_strings;
  vec<string, 1> strings(n_strings);
  for (auto& i : strings) {
    cin >> i;
  }

  sort(ALL(strings), [&](const auto& i, const auto& j) { return SZ(i) < SZ(j); });

  int64_t answer = 0;
  map<pair<int, int>, set<char>> f;
  for (auto& i : strings) {
    vec<int, 1> first_index_characters(26);
    for (int j = 0; j < 26; ++j) {
      first_index_characters[j] = static_cast<int>(find(ALL(i), static_cast<char>(j + 'a')) - i.begin());
    }

    ModInt value_1, value_2;
    for (int j = SZ(i); j; --j) {
      for (int k = 0; k < 26; ++k) {
        answer += first_index_characters[k] < j && f[make_pair(value_1.a, value_2.a)].count(static_cast<char>(k + 'a'));
      }
      if (j - 1) {
        value_1 = value_1 * base + ModInt(i[j - 1]);
        Mod = kMod2;
        value_2 = value_2 * base + ModInt(i[j - 1]);
        Mod = kMod1;
      }
    }
    f[make_pair(value_1.a, value_2.a)].emplace(i[0]);
  }

  cout << answer << '\n';

  return 0;
}

