    for (auto &c : s) ++cnt[c - 'a'];
    int k = 0;
    trie.query(s, [&](int idx) {
      rep(j,26) {
        if (cnt[j] && (nxt = trie.nodes[idx].nxt[j]) != -1) {
          ans += trie.nodes[nxt].accept.size();
        }
      }
      --cnt[s[k++] - 'a'];
    });
  }

  cout << ans << endl;
}


