	for(int i=0;i<n;i++)
	{
		string s; cin>>s;
		vec.pb(s); L.insert(int(s.length()));
		exlen[int(s.length())-1]=1;
	}
	unordered_map<ll,int> dp[26]; 
	for(int i=0;i<n;i++)
	{
		string s = vec[i];
		int ct[26] = {};
		int len = s.length();
		int bit = 0;
		for(int j=0;j<len;j++)
		{
			ct[s[j]-'a']++;
			bit|=(1<<(s[j]-'a'));
		}
		int hsh[2] = {0,0};
		for(int k=0;k<26;k++)
		{
			if(bit&(1<<k)) dp[k][0]++;
		}
		if(len==1)
		{
			hashes[i] = 0;
		}
		for(int j=len-1;j>=0;j--)
		{
			ct[s[j]-'a']--;
			if(ct[s[j]-'a']==0) 
			{
				bit^=(1<<(s[j]-'a'));
			}
			for(int z=0;z<2;z++)
			{
				hsh[z]=mult(hsh[z],C[z],MOD[z]);
				hsh[z]=add(hsh[z],s[j],MOD[z]);
			}
			if(exlen[len-j])
			{
				for(int k=0;k<26;k++)
				{
					if(bit&(1<<k)) dp[k][make(hsh[0],hsh[1])]++;
				}
			}
			if(j==1)
			{
				hashes[i] = make(hsh[0],hsh[1]);
			}
		}
	}
	//all strings distinct
	ll ans = 0;
	for(int i=0;i<n;i++)
	{
		//suppose i am smaller
		ll tmp = hashes[i];
		int ch = vec[i][0]-'a';
		ans+=dp[ch][tmp]-1;
	}
	cout<<ans<<'\n';
}

