#define MAX_N 1010101
long long extgcd(long long a, long long b, long long& x, long long& y) {
    long long d = a;
    if (b != 0) {
        d = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    } else {
        x = 1; y = 0;
    }
    return d;
}
long long mod_inverse(long long a, long long m) {
    long long x, y;
    if(extgcd(a, m, x, y) == 1) return (m + x % m) % m;
    else return -1;
}
vector<long long> fact(MAX_N+1, inf);
long long mod_fact(long long n, long long& e) {
    if(fact[0] == inf) {
        fact[0]=1;
        if(MAX_N != 0) fact[1]=1;
        for(ll i = 2; i <= MAX_N; ++i) {
            fact[i] = (fact[i-1] * i) % mod;
        }
    }
    e = 0;
    if(n == 0) return 1;
    long long res = mod_fact(n / mod, e);
    e += n / mod;
    if((n / mod) % 2 != 0) return (res * (mod - fact[n % mod])) % mod;
    return (res * fact[n % mod]) % mod;
}
// return nCk
long long mod_comb(long long n, long long k) {
    if(n < 0 || k < 0 || n < k) return 0;
    long long e1, e2, e3;
    long long a1 = mod_fact(n, e1), a2 = mod_fact(k, e2), a3 = mod_fact(n - k, e3);
    if(e1 > e2 + e3) return 0;
    return (a1 * mod_inverse((a2 * a3) % mod, mod)) % mod;
}

using mi = modint;

mi mod_pow(mi a, ll n) {
    mi ret = 1;
    mi tmp = a;
    while(n > 0) {
        if(n % 2) ret *= tmp;
        tmp = tmp * tmp;
        n /= 2;
    }
    return ret;
}

ll gcd(ll a, ll b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}

ll ans = 0;

struct Trie {
    bool cont;
    vector<Trie*> child;
    Trie() {
        cont = false;
        child.resize(26);
        REP(i, 26) child[i] = nullptr;
    }
    void Add(string& str, int idx) {
        if(idx == (int)str.size()) {
            cont = true;
            return;
        }
        int num = str[idx] - 'a';
        if(child[num] == nullptr) {
            child[num] = new Trie();
        }
        child[num]->Add(str, idx + 1);
    }
};

pair<vector<ll>, ll> dfs(Trie* node) {
    vector<ll> cnt(26, 0);
    ll sum = 0;
    vector<bool> ok(26, false);
    vector<ll> minus(26, 0);
    REP(i, 26) {
        if(node->child[i] == nullptr) continue;
        auto tmp = dfs(node->child[i]);
        tmp.first[i] = tmp.second;
        if((node->child[i])->cont) ok[i] = true;
        minus[i] = tmp.second;
        REP(j, 26) cnt[j] += tmp.first[j];
        sum += tmp.second;
    }
    REP(i, 26) {
        if(ok[i]) ans += cnt[i] - minus[i];
    }
    if(node->cont) ans += sum;
    if(node->cont) sum += 1;
    return {cnt, sum};
}

