	{
		scanf("%s",tmp+1);
		s[i]=(tmp+1);
		int m=strlen(tmp+1),now=1,las;
		for(int j=m;j>=1;--j)
		{
			las=now;
			if(!son[now][tmp[j]-'a'])son[now][tmp[j]-'a']=++tot;
			now=son[now][tmp[j]-'a'];
			++alpha[i][tmp[j]-'a'];
		}
		++val[las][tmp[1]-'a'];
		++cnt[now];
	}
	for(int i=1;i<=n;++i)
	{
		int m=s[i].length(),now=1;
