struct ST;
int n;
vector<string> s;
vector<ST> sts(1);
struct ST{
	vector<int> e;
	vector<int> tp;
	ST(): tp(26), e(26, -1) {}
};

void STadd(string ts){
	auto si=0;
	for(int i=ts.size()-1; i>=0; i--){
		char c=ts[i];
		int ci=c-'a';

		if(i>=1){
			int nsi=sts[si].e[ci];
			if(nsi== -1){
				sts.push_back(ST());
				nsi=sts.size()-1;
				sts[si].e[ci]=nsi;
			}
			si=nsi;
		}
		else{//i==0
			sts[si].tp[ci]++;
		}
	}
}

int main(){
	cin>>n;
	s=vector<string>(n);
	rep(i, n) cin>>s[i];

	map<char, int> sm1;

	rep(i, n){
		if(s[i].size()==1){
			sm1[s[i][0]]++;
		}
		else{
			STadd(s[i]);
		}
	}

	ll cnt=0;
	rep(i, n){
		vector<int> deta(26, 0);
		rep(j, s[i].size()) deta[s[i][j]-'a']++;
		rep(k, 26) if(deta[k]>0) cnt+=sm1['a'+k];

		int si=0;
		for(int j=s[i].size()-1; j>=0; j--){
			if(j<s[i].size()-1){
				int nsi=sts[si].e[s[i][j+1]-'a'];
				if(nsi== -1) break;
				si=nsi;
				rep(k, 26) if(deta[k]>0){
					cnt+= sts[si].tp[k];
				}
			}
			deta[s[i][j]-'a']--;
		}
	}
	cnt-=n;

	cout<<cnt<<endl;

	return 0;
}

