using namespace std;
using ll = long long;

class Rolling_Hash {
  private:
    ll n;
    static constexpr ll base1 = 1007, base2 = 2009;
    static constexpr ll mod1 = (1e9+7), mod2 = (1e9+9);
    vector<ll> hash1, hash2, mpow1, mpow2;
  public:
    Rolling_Hash(const string& s) {
        n=s.size();
        hash1.assign(n + 1, 0);
        hash2.assign(n + 1, 0);
        mpow1.assign(n + 1, 1);
        mpow2.assign(n + 1, 1);
        for(int i = 0; i < n; i++) {
            hash1[i + 1] = (hash1[i]*base1+s[i])%mod1;
            hash2[i + 1] = (hash2[i]*base2+s[i])%mod2;
            mpow1[i + 1] = (mpow1[i]*base1) % mod1;
            mpow2[i + 1] = (mpow2[i]*base2) % mod2;
        }
    }

    //get_hash [l, r)
    auto get(ll l, ll r) {
        ll lefval = hash1[r] - hash1[l]*mpow1[r-l]%mod1;
        ll rigval = hash2[r] - hash2[l]*mpow2[r-l]%mod2;
        if(lefval<0)lefval += mod1;
        if(rigval<0)rigval += mod2;
        return make_pair(lefval,rigval);
    }

    //最小共通接頭辞を求める
    auto get_LCP(ll a,ll b){
        ll len = min( n-a+1,n-b+1 );
        ll low=0,high=len;
        while( high-low>1 ){
            ll mid=(high+low)/2;
            if(get(a,a+mid)!=get(b,b+mid))high=mid;
            else low=mid;
        }
    return low;
    }
};


int main()
{
    int n; cin >> n;
    vector<string> s(n);
    for(int i = 0; i < n; i++)cin >> s[i];
    sort(s.begin(), s.end(), [](string& s, string& t){return s.size() > t.size();});
    unordered_map<pair<pair<ll,ll>,char>,int> mp;
    unordered_map<char,int> uni;
    ll ans = 0;

    for(int I = 0; I < n; I++) { //s[I]は減らして作られる側

        string t = s[I];
        int m = s[I].size();
        Rolling_Hash rh(t);

        //ask-part
        if(t.size() == 1)ans += uni[t[0]-'a'];
        ans += mp[{rh.get(1,m), t[0]-'a'}];

        //add-part
        vector<bool> alf(26);
        for(int i = 0; i < m; i++) {
            for(int j = 0; j < 26; j++) {
                if(alf[j])mp[{rh.get(i,m),j}]++;
                if(t[i]-'a' == j)alf[j]=true;
            }
        }
        for(int i = 0; i < 26; i++)if(alf[i])uni[i]++;
    }
    cout << ans << endl;

}

