vector <int> edges[N];
int res[N];

int root = 0;
int cnt = 1;

void add(string &s) {
	int now = root;
	for (char c : s) {
		int k = c - 'a';
		if (edges[now][k] == -1) {
			edges[now][k] = cnt;
			edges[cnt++].resize(26, -1);
		}
		now = edges[now][k];
	}
	res[now]++;
}

int go(string s) {
	vector <int> path;
	int now = root;
	for (char c : s) {
		int k = c - 'a';
		path.pb(now);
		now = edges[now][k];
	}
	path.pb(now);
	vector <int> have(26, 0);
	reverse(s.begin(), s.end());
	reverse(path.begin(), path.end());
	have[s[0] - 'a'] = true;
	int ans = 0;

	for (int i = 2; i < path.size(); ++i) {
		have[s[i - 1] - 'a'] = true;
		for (int x = 0; x < 26; ++x) {
			int kek = edges[path[i]][x];
			if (kek != -1 && have[x]) {
				ans += res[kek];
			}
		}
	}
	//cout << s << " " << ans << endl;
	return ans;
}

int main(){
#ifdef LOCAL
	freopen("B_input.txt", "r", stdin);
	//freopen("B_output.txt", "w", stdout);
#endif
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	edges[0].resize(26, -1);

	int n;
	cin >> n;
	vector <string> t;
	for (int i = 0; i < n; ++i) {
		string s;
		cin >> s;
		reverse(s.begin(), s.end());
		add(s);
		t.pb(s);
	}
	int ans = 0;
	for (string s : t) {
		ans += go(s);
	}
	cout << ans << endl;

}

#include<bits/stdc++.h>
#define ll long long 
#define rint register int 
#define pa pair<int,int> 
using namespace std;
int N;
char s[1011000];
int Sum[1010010],S[1010000][26],Summ[1001000];
int Col[1100010];
int cnt,ch[1011000][26],fa[1010010];
ll ans=0;
inline void Insert(int len) {
	int now=1;
	for(rint i=1;i<=len;++i){
		int c=s[i]-'a';
		if(!ch[now][c]) {
			++cnt;fa[cnt]=now;
			Col[cnt]=c;
			ch[now][c]=cnt;
			now=cnt;
		}
		else now=ch[now][c];
	}
	Sum[now]++;
}
inline void DFS(int now) {
	Summ[now]=Sum[now];
	for(rint i=0;i<26;++i) {
		int to=ch[now][i];if(!to) continue;
		DFS(to);
		Summ[now]+=Summ[to];
	}
	if(now!=1) {
		S[fa[now]][Col[now]]+=Summ[now];
		for(rint i=0;i<26;++i){
			if(i!=Col[now])S[fa[now]][i]+=S[now][i];
		}
	}
}
inline void DFS2(int now) {
	if(Sum[now]) {
		ans+=1ll*Sum[now]*(S[fa[now]][Col[now]]-Sum[now]);
		ans+=1ll*Sum[now]*(Sum[now]-1)/2; 
	}
	for(rint i=0;i<26;++i) {
		int to=ch[now][i];if(!to) continue;
		DFS2(to);
	}
}
int main() {
	cin>>N;
	cnt=1;
	for(rint i=1;i<=N;++i) {
		scanf("%s",s+1);
		int len=strlen(s+1);
		reverse(s+1,s+len+1);
		Insert(len);
	}
	DFS(1);DFS2(1);
	cout<<ans<<endl;
	return 0;
}

