        }

        void solve() {
            print_case();
            // <code here>
            int n;
            in >> n;
            vector<string> s(n);
            in >> s;
            for (auto &ss : s) reverse(all(ss));
            sort(all(s));

            vpi sbl;
            fori(i, n) sbl.emplace_back(s[i].size(), i);
            sort(all(sbl));
            reverse(all(sbl));

            ll ans = 0;
            int cur_len = sbl[0].first + 10;
            vi active_s;
            vector<range_query::sum_range_query<int>> eq(26, range_query::sum_range_query<int>(n));
            for (auto p : sbl) {
                int nxt_len = p.first - 1;

                for (int i = nxt_len; i < cur_len; i++) {
                    for (int si : active_s) {
                        eq[s[si][i] - 'a'][si] = 1;
                    }
                }
                cur_len = nxt_len;
                active_s.push_back(p.second);
                eq[s[p.second][nxt_len] - 'a'][p.second] = 1;


                string cs = s[p.second];
                int last_char = cs.back() - 'a';
                cs.pop_back();
                int lb = lower_bound(all(s), cs) - s.begin();
