	vector<string> V;
	for(int i = 0; i < N; ++i){
		string s; cin >> s;
		V.push_back(s);
		vector<int> C(26, 0);
		for(char c : s)
			C[gI(c)]++;

		ll ch1 = 0, ch2 = 0;
		for(int j = s.size() - 1; j >= 0; --j){
			for(int k = 0; k < 26; ++k){
				if(C[k] > 0){
					ll h1 = (ch1*K1 + k) % MOD1;
