		cin>>S[i];
	}

	sort(S.begin(), S.end(), [](string const& lhs, string const& rhs) {
		return lhs.size() < rhs.size();
	});

	for(int i = 0; i < N; i++){
		vector<bool> con(NUM_a, false);
        vector<vector<vector<bool>>> con2(S[i].size(), vector<vector<bool>>(NUM_a, vector<bool>(NUM_a, false)));

		for(int j = 0; j < S[i].size(); j++){

			for(int k = 0; k < NUM_a; k++){
				if(con[k] == true) con2[j][k][S[i][j]-'a'] = true;
                if(j&&con2[j-1][k][S[i][j]-'a']) con2[j][k][S[i][j]-'a'] = con2[j-1][k][S[i][j]-'a'];
			}

			con[S[i][j]-'a'] = true;
		}

        reverse(S[i].begin(), S[i].end());

        count += tr.count(&S[i][0], con, con2, S[i].size()-1);

        // tr.add(&S[i][0]);
	}

    cout<<count<<endl;

