typedef vector<int> vi;
#define rep(i, n) for (int i = 0; i < (n) ; i++)
#define all(v) (v).begin(), (v).end()

int main(void){
    int n, sz, ans = 0; string sb; cin >> n;
    vector<string> ss(n); vi loc(26); map<string, int> cnt;
    rep(i, n) {cin >> ss[i]; reverse(all(ss[i]));}
    auto cmp = [&](string s1, string s2)->bool{return s1.length() < s2.length();};
    sort(all(ss), cmp);

    for (string& s: ss){
        fill(all(loc), -1); sz = s.length(); sb = "";
        rep(i, sz) loc[s[i] - 'a'] = i;
        rep(i, sz){
            if (!cnt.count(sb)) {sb += s[i]; continue;}
            int bit = cnt[sb];
            for (char c = 'a'; c <= 'z'; ++c) if (loc[c - 'a'] >= i && (bit >> (c - 'a') & 1)) ans++;
            sb += s[i];
        }
        cnt[s.substr(0, sz - 1)] |= (1LL << (s[sz - 1] - 'a'));
    }
    cout << ans << endl;
    return 0;
}

