int N, P = 1;
vector<string> v;
int go[1010101][26], cnt[1010101][26];
// cnt[n][c] : n 아래에 문자 c가 존재하는 문자열이 몇 개인가?
int C[26]; // Insert 함수 전용

void Insert(int n, int p, string &s) // suffix 삽입
{
	if (p == -1) return;

	for(int i=0; i<26; i++)
		if (C[i])
			cnt[n][i]++;
	C[s[p]-'a']--;

	int next = go[n][s[p]-'a'];
	if (next == 0) go[n][s[p]-'a'] = next = ++P;
	//cout << n << " -> " << next << " : " << s[p] << "\n";
	Insert(next, p-1, s);
}

int Find(int n, int p, string &s)
{
	if (p == 0) return cnt[n][s[0]-'a'];

	int next = go[n][s[p]-'a'];
	if (next == 0) return 0;
	return Find(next, p-1, s);
}

int main()
{
	ios::sync_with_stdio(0); cin.tie(0);
	cin >> N;
	for(int i=0; i<N; i++)
	{
		string s;
		cin >> s;
		v.push_back(s);
	}
	sort(v.begin(), v.end(), [&](string &a, string &b){return a.size() > b.size(); }); // 길이가 긴 순으로 삽입

	ll res = 0;
	vector<int> upd;
	for(int i=0; i<N; i++)
	{
		upd.push_back(i);

		int val = Find(1, (int)v[i].size()-1, v[i]);
		//cout << v[i] << " " << val << "\n";
		res += val;

		// 몰아서 업데이트
		if (i+1 != N && v[i].size() != v[i+1].size())
		{
			for(int idx : upd)
			{
				memset(C, 0, sizeof(C));
				for(char c : v[idx])
					C[c-'a']++;
				Insert(1, (int)v[idx].size()-1, v[idx]);
			}
			upd.clear();
		}
	}
	cout << res;
	return 0;
}

