            trie[query[i-1][j].first].add(S[query[i-1][j].second.first][query[i-1][j].second.second]);
        }
        rep(j, S[i].size()){
            string tmp = S[i][j].substr(0, S[i][j].size()-1);
            ans += trie[S[i][j].back()-'a'].count_prefix(tmp);
            int p[26];
            memset(p, -1, sizeof(p));
            rep(l, S[i][j].size()){
                p[S[i][j][l]-'a'] = l;
            }
            rep(l, 26){
                if(p[l] == i-1) trie[l].add(S[i][j]);
                else if(p[l] != -1) query[p[l]].pb({ l,{i,j } });
            }
        }
    }

    cout << ans << endl;
}

