    for(int i=0;i<26;i++)
    {
        Trie[nT].child[i]=0;
        Trie[nT].sum[i]=0;
    }
    Trie[nT].P=0;
    return nT;
}

void AddWord(string s)
{
    memset(cnt,0,sizeof cnt);
    int r=root;
    for(int i=0;i<s.size();i++)
    {
        int k=s[i]-'a';
        int l;
        if (Trie[r].child[k]==0)
        {
            l=AddNode();
            Trie[r].child[k]=l;
            Trie[l].P=r;
        }
        r=Trie[r].child[k];
    }
    int cur=s.size()-1;
    while (r!=root)
    {
        r=Trie[r].P;
        if(cnt[s[cur]-'a']==0) cnt[s[cur]-'a']++;
        for(int i=0;i<26;i++) Trie[r].sum[i]+=cnt[i];
        cur--;
    }
}

