class Trie {
public:
  Trie* used[charNum];
  vector<Trie*> next;
  int num[charNum];
  vector<char> last_char;

  Trie() {
    fill(used, used + charNum, (Trie*)(NULL));
    fill(num, num + charNum, 0);
  }

  void insert(string &s, int depth, vector<char> &rem) {
    if (depth == s.size() - 1) {
      last_char.push_back(s.back());
    }
    if (depth == s.size()) {
      return;
    }
    if (!this->used[s[depth] - firstChar]) {
      this->used[s[depth] - firstChar] = new Trie;
      next.push_back(this->used[s[depth] - firstChar]);
    }
    rep (i, charNum) {
      if (rem[i] > 0) num[i]++;
    }
    rem[s[depth] - firstChar]--;
    this->used[s[depth] - firstChar]->insert(s, depth + 1, rem);
  }

  void dfs(int depth) {
    // DEBUG(depth);
    for (char ch: last_char) {
      sum += num[ch - firstChar] - 1;
      // DEBUG(ch);
      // DEBUG(sum);
    }
    rep (i, next.size()) {
      next[i]->dfs(depth + 1);
    }
  }
};


