    vector<rolling_hash> R;
    REP(i, N){
        rolling_hash rh(S[i], base);
        R.emplace_back(rh);
    }

    unordered_map<ull, ll> mp;
    REP(i, N){
        ll sz = S[i].size();
        ull h = R[i].hash(0, sz);
        mp[h]++;
    }

    ll res = 0;
    REP(i, N){
        ll sz = S[i].size();
        vl cnt(26, 0);
        REP(j, sz){
            cnt[S[i][j]-'a']++;
        }
        REP(j, sz){
            REP(k, 26){
                if(cnt[k]>0){
                    ull h = R[i].add_hash(j, k);
                    res += mp[h];
                }
            }
            cnt[S[i][j]-'a']--;
        }
    }

