typedef bitset<26> bst;

struct tp {
	tp *child[26];
	int cnt[26];
	tp() {
		for (int i = 0; i < 25; ++i) {
			child[i] = 0;
			cnt[i] = 0;
		}
	}
}*root;

int n;
char s[10 * N];

bst update(int u, tp *cur) {
	if (u == 0) {
		bst c;
		return c;
	}
	int a = s[u] - 'a';
	if (!cur->child[a]) cur->child[a] = new tp();
	bst b = update(u - 1, cur->child[a]);
	if (!b[a]) b[a] = 1;
	for (int i = 0; i < 26; ++i) {
		cur->cnt[i] += b[i];
	}
	return b;
}

int query(tp *cur, int len) {
	int a = s[len] - 'a';
	if (!cur) {
		return 0;
	}
	if (len == 1) {
		return cur->cnt[a];
	}
	return query(cur->child[a], len - 1);
}

