				if((int)s[mid].size()>=sz && s[mid][j]==s[i][j])
					r1 = mid-1, l = mid;
				else
					l1 = mid+1;
			}
			l1 = i, r1 = r;
			r = i;
			while(l1<=r1){
				int mid = (l1+r1)>>1;
				if((int)s[mid].size()>=sz && s[mid][j]==s[i][j])
					l1 = mid+1, r = mid;
				else
					r1 = mid-1;
			}
		}

		//cerr<<s[i]<<" "<<l<<" "<<r<<endl;
		char ch = s[i][sz-1];
		rep(j,l,r)
			if(last[j][ch-'a'] >= sz) ans++;
	}
	cout<<ans-n<<endl;
	return 0;
}

