void ins(int &o, const string &s, int dep, vector<int> &flag)
{
    if(o == 0)
        o = create();

    if(dep == s.size()) return ;

    int c = s[dep] - 'a';
    ins(T[o].son[c], s, dep + 1, flag);

    flag[c] = 1;
    for(int i = 0; i < 26; i++)
        T[o].cnt[i] += flag[i];
}

