struct wavelet_tree {
    int lo, hi;
    wavelet_tree *l, *r;
    vector <int> b;

    wavelet_tree(int *from, int *to, int x, int y){
        lo = x, hi = y;
        if(lo == hi or from >= to) return;
        int mid = (lo+hi)/2;
        auto f = [mid](int x){ return x <= mid; };
        b.reserve(to-from+1);
        b.push_back(0);
        for(auto it = from; it != to; it++)
            b.push_back(b.back() + f(*it));
        auto pivot = stable_partition(from, to, f);
        l = new wavelet_tree(from, pivot, lo, mid);
        r = new wavelet_tree(pivot, to, mid+1, hi);
    }

    // number of elements <= k in subarray [l,r]
    int LTE(int l, int r, int k) {
        if(l > r or k < lo) return 0;
        if(hi <= k) return r - l + 1;
        int lb = b[l-1], rb = b[r];
        return this->l->LTE(lb+1, rb, k) + this->r->LTE(l-lb, r-rb, k);
    }

    ~wavelet_tree() {
        delete l;
        delete r;
    }
};


int lcp(int a, int b) {
    int ret = 0;
    for(int i = 0; i < (int)min(s[a].size(), s[b].size()); ++i) {
        if(s[a][i] == s[b][i]) ret++;
        else break;
    }
    return ret;
}

int n;

int getlb(int p) {
    int low = 1, high = p, ret = p;
    while(low <= high) {
        int mid = (low + high) >> 1;
        if(lcp(p, mid) >= (int)s[p].size() - 1) {
            ret = mid;
            high = mid - 1;
        }
        else low = mid + 1;
    }
    return ret;
}


int getub(int p) {
    int low = p, high = n, ret = p;
    while(low <= high) {
        int mid = (low + high) >> 1;
        if(lcp(p, mid) >= (int)s[p].size() - 1) {
            ret = mid;
            low = mid + 1;
        }
        else high = mid - 1; 
    }
    return ret;
}


