typedef long long ll;
typedef long double ld;
typedef unsigned long long ull;
typedef pair<ll, ll> hashVal;

mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

const int K = 26;
const ll mod1 = 1e9 + 7;
const ll mod2 = 1e9 + 9;

inline hashVal operator+(hashVal a, hashVal b){
	ll x = a.first + b.first; if(x >= mod1)x -= mod1;
	ll y = a.second + b.second; if(y >= mod2)y -= mod2;
	return {x, y};
}

inline hashVal operator-(hashVal a, hashVal b){
	ll x = a.first - b.first; if(x < 0)x += mod1;
	ll y = a.second - b.second; if(y < 0)y += mod2;
	return {x, y};
}

inline hashVal operator*(hashVal a, hashVal b){
	return {a.first*b.first%mod1, a.second*b.second%mod2};
}

inline hashVal operator*(hashVal a, ll k){
	return {a.first*k%mod1, a.second*k%mod2};
}

inline hashVal operator*(ll k, hashVal a){
	return {a.first*k%mod1, a.second*k%mod2};
}

hashVal base, val[K];

void pre(){
	base = {0, 0};
	while(base.first == 0 || base.second == 0){
		base = {rng()%mod1, rng()%mod2};
	}
	for(int i = 0; i < K; i++){
		val[i] = {0, 0};
		while(val[i].first == 0 || val[i].second == 0){
			val[i] = {rng()%mod1, rng()%mod2};
			for(int j = 0; j < i; j++){
				if(val[i].first == val[j].first || val[i].second == val[j].second){
					val[i] = {0, 0};
					break;
				}
			}
			if(val[i].first == base.first || val[i].second == base.second){
				val[i] = {0, 0};
			}
		}
	}
}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(NULL);
	cout<<setprecision(32);

	pre();
	int n; cin>>n;
	vector<string> v(n);
	for(auto &x : v){
		cin>>x;
	}
	sort(v.begin(), v.end(), [](string &a, string &b){
		return a.size() < b.size();
	});
	unordered_map<hashVal, int> mp;
	ll ans = 0;
	for(int i = 0; i < n; i++){
		reverse(v[i].begin(), v[i].end());
		vector<int> f(K);
		for(auto ch : v[i]){
			f[ch - 'a']++;
		}
		int sz = v[i].size();
		hashVal hv = {0, 0};
		for(int j = 0; j < sz; j++){
			for(int k = 0; k < K; k++){
				if(f[k]){
					hashVal tmp = hv*base + val[k];
					if(mp.count(tmp))ans += mp[tmp];
				}
			}
			f[v[i][j] - 'a']--;
			hv = hv*base + val[v[i][j] - 'a'];
		}
		mp[hv]++;
	}
	cout<<ans;


	return 0;
}

