            return x.size() < y.size();
        }
        return x < y;
    });
    vector<rollinghash> R;
    vvi P;
    FOR(s, S)
    {
        R.push_back(rollinghash(s));
        vi p(26, INF);
        for (ll j = s.size() - 1; j >= 0; --j)
        {
            p[s[j] - 'a'] = j;
        }
        P.push_back(p);
    }
    ll ans = 0;
    map<ii, vi> dp;
    REP(i, N)
    {
        ll len_i = S[i].size();
        if (i == 0 or len_i > S[i - 1].size())
        {
            for (ll j = i + 1; j < N; ++j)
            {
                ll len_j = S[j].size();
                if (len_j == len_i)
                {
                    continue;
                }
                auto h = len_i == 1 ? ii(0LL, 0LL) : R[j].hash(len_j - (len_i - 1), len_j);
                if (dp.find(h) == dp.end())
                {
                    dp[h] = vi(26, 0);
                }
                REP(k, 26)
                {
                    dp[h][k] += P[j][k] < len_j - (len_i - 1);
                }
            }
