string s;
long long ans = 0;
bool fp[26];

struct trie
{
	trie *nt[26], *pr;
	int sp[26], rc;
	bool f;

	trie()
	{
		pr = nullptr;
		for (int i = 0; i < 26; i++) {
			nt[i] = nullptr;
			sp[i] = 0;
		}
		f = false;
		rc = 0;
	}

	void insert(int p)
	{
		if (p >= s.length()) {
			for (int i = 0; i < 26; i++)
				if (fp[i])
					sp[i] = 1;
			f = true;
			return;
		}
		int tc = s[p] - 'a';
		if (!nt[tc])
			nt[tc] = new trie;
		nt[tc]->pr = this;
		nt[tc]->rc = tc;
		fp[tc] = true;
		nt[tc]->insert(p + 1);
		for (int i = 0; i < 26; i++)
			if (fp[i])
				sp[i]++;
	}

	void ps()
	{
		if (f)
			ans += pr->sp[rc];
		for (int i = 0; i < 26; i++) {
			if (!nt[i]) continue;
			nt[i]->ps();
		}
	}
};

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);
	int n; cin >> n;
	trie *rt = new trie;
	for (int i = 0; i < n; i++) {
		cin >> s;
		reverse(s.begin(), s.end());
		rt->insert(0);
		for (int j = 0; j < 26; j++)
			fp[j] = false;
	}
	rt->ps();
	cout << ans - n << '\n';
	return 0;
}

