struct AhoCorasick {
    static constexpr int ASIZE = 26;
    struct tnode {
        char c;
        bool used = false;
        vector<int> source;
        int p = -1;
        i64 cost = -1e18;
        array<int, ASIZE> anext;
        array<int, ASIZE> tnext;
        array<i64, ASIZE> cc;

        tnode() {
            anext.fill(-1);
            tnext.fill(-1);
            cc.fill(0);
        }
    };

    vector<int> suf;

    vector<tnode> trie;
    vector<int> used;
    int scount = 0;
    int st_ = 0;

    template<typename Container>
    static AhoCorasick OnStrings(const Container& strs) {
        AhoCorasick ac;
        for (const auto& str : strs) {
            ac.add_string(str);
        }
        ac.suf.resize(ac.trie.size(), -1);
        ac.used.resize(strs.size());
        return ac;
    }

    AhoCorasick(int size = 0) {
        trie.reserve(size);
        trie.emplace_back();
    }

    void reset_state() { st_ = 0; }
    void set_state(int st) { st_ = st; }
    int nstates() const { return trie.size(); }

    void build_all() {
        for (int i = 0; i < trie.size(); i++) {
            set_state(i);
            for (char c = 0; c < ASIZE; c++) {
                move_char('a' + c);
            }
        }
    }

    void add_string(const string& s) {
        int v = 0;
        auto cc = make_vec(0ll, s.size() + 1, 26);
        for (int i = s.size() - 1; i >= 0; i--) {
            forn(j, 26) {
                cc[i][j] = cc[i + 1][j] + (s[i] == j + 'a');
                uin(cc[i][j], 1ll);
            }            
        }

        for (int i = 0; i < s.size(); i++) {
            char c = s[i] - 'a';
            if (trie[v].anext[c] == -1) {
                trie[v].anext[c] = trie.size();
                trie.emplace_back();
                trie.back().p = v;
                trie.back().c = c;
            }
            forn(j, 26) {
                trie[v].cc[j] += cc[i][j];
            }
            v = trie[v].anext[c];
        }

        trie[v].source.push_back(scount);
        scount++;
    }

    const tnode& move_trie(const string& s) {
        int v = 0;
        forn(i, s.size()) {
            v = trie[v].anext[s[i] - 'a'];
        }
        return trie[v];
    }

    int slink(int p) {
        if (suf[p] != -1) {
            return suf[p];
        }

        int parent = trie[p].p;
        if (p == 0 || parent == 0) {
            suf[p] = 0;
        } else {
            suf[p] = move(slink(trie[p].p), trie[p].c);
        }

        return suf[p];
    }

    void finish(int st) {
        if (st == 0 || trie[st].used) {
            return;
        } else {
            for (int i = 0; i < trie[st].source.size(); i++) {
                used[trie[st].source[i]] = true;
            }
            trie[st].used = true;
            finish(slink(st));
        }
    }

    int move(int st, char c) {
        if (trie[st].tnext[c] != -1) {
            return trie[st].tnext[c];
        }

        int next_st;
        if (trie[st].anext[c] != -1) {
            next_st = trie[st].anext[c];
        } else if (st == 0) {
            next_st = 0;
        } else {
            next_st = move(slink(st), c);
        }
        trie[st].tnext[c] = next_st;
        return trie[st].tnext[c];
    }

    int move_char(char c) {
        st_ = move(st_, c - 'a');
        finish(st_);
        return st_;
    }
    int move_str(const string& s) {
        for (auto c : s) {
            move_char(c);
        }
        return st_;
    }
};

