    std::vector<std::string> S(N);
    for (auto &s : S) {
        std::cin >> s;
    }

    std::vector<std::vector<int>> paths(N);
    int state = 1;
    for (int i = 0; i < N; i++) {
        auto& s = S[i];
        std::reverse(s.begin(), s.end());

        int node = 0;
        for (const auto c : s) {
            paths[i].push_back(node);
            if (E[node][c - 'a'] == 0) {
                E[node][c - 'a'] = state;
                state++;
            }
            node = E[node][c - 'a'];
        }
        accept[node] = true;
    }

    int ans = 0;
    for (int i = 0; i < N; i++) {
        const auto& s = S[i];

        std::set<char> suffix;
        for (int j = s.length() - 1; j >= 0; j--) {
            suffix.insert(s[j]);

            const int node = paths[i][j];
            for (const auto c: suffix) {
                ans += accept[E[node][c - 'a']];
            }
        }
    }

    std::cout << ans - N << '\n';
}

