struct node {
  int par, letter, cnt;
  array<int, 26> to;
};
void solve() {
  INT(n);
  vector<node> a;
  a.pb({});
  vi pos;
  rep (n) {
    STR(s);
    rev(s);
    int i = 0;
    FOR (x, s) {
      if (a[i].to[x - 'a'])
        i = a[i].to[x - 'a'];
      else {
        a.pb({});
        a.back().par = i;
        a.back().letter = x - 'a';
        a[i].to[x - 'a'] = SZ(a) - 1;
        i = SZ(a) - 1;
      }
      a[i].cnt++;
    }
    pos.pb(i);
  }
  int m = SZ(a);
  vv<int> cnt(m, 26);
  down (i, m - 1, 0) {
    rng (j, 26) {
      int t = a[i].to[j];
      if (t) {
        cnt[i][j] += a[t].cnt;
        rng (k, 26)
          if (k != j)
            cnt[i][k] += cnt[t][k];
      }
    }
  }
  ll ans = 0;
  FOR (i, pos) {
    ans += cnt[a[i].par][a[i].letter];
    debug(i);
  }
  pl(ans - n);
}
