int dfs(int m, ll &f, int t = 0, int node = 0) {
    if (t == s[m].size()) {
        f = 0;
        return 0;
    }
    else if (t == s[m].size() - 1) {
        dfs(m,f,t+1,g[node][s[m][t]-'a']);
        f |= 1<<(s[m][t]-'a');
        return 0;
    }
    else {
        int ret = 0;
        ret += dfs(m,f,t+1,g[node][s[m][t]-'a']);
        f |= 1<<(s[m][t]-'a');
        for(int i = 0;i < 26;i++) {
            if (g[node][i] == 0) continue;
            if (is_end[g[node][i]] && (f & (1 << i))) {
                ret++;
            }
        }
        return ret;
    }
}

