                g.push_back(vector< int >(26, 0));
                is_end.push_back(false);
            }
            node = g[node][s[i][t] - 'a'];
            t++;
        }
        is_end[node] = true;
    }
    ll ans = 0;
    for (int i = 0; i < n; i++) {
        ll f;
        ans += dfs(i,f);
    }
    cout << ans << endl;
    return 0;
}

