void dfs(int x) {
    rep(i, G[x].size()) {
        int c = G[x][i].first - 'a';
        int to = G[x][i].second;
        cnt[c] += stop[to];
    }
    rep(i, G[x].size()) {
        int c = G[x][i].first - 'a';
        int to = G[x][i].second;
        ans += cnt[c] * band[to];
        int tmp = cnt[c];
        cnt[c] = 0;
        dfs(to);
        cnt[c] = tmp;
    }
    rep(i, G[x].size()) {
        int c = G[x][i].first - 'a';
        int to = G[x][i].second;
        cnt[c] -= stop[to];
    }
}
