void insertt(trie *root,string key,int chh ){

    struct trie *tmp = root;
    for(int i=0;i<sz(key);i++){
        int ch= key[i]-'a';
        if(tmp->child[ch]== NULL){
            tmp->child[ch]= getNode();
            tmp= tmp->child[ch];
        }
    }
    tmp->ch.pb(chh);

}
void query(trie *root, string key,int cid,int ex)
{
    trie*tmp = root;

    for (int i = 0; i < sz(key); i++)
    {
        int ch = key[i] - 'a';

        for(int j=0;j<sz(tmp->ch);j++){
            int no= tmp->ch[j];
            if(rng(0,cid,no)==0||(cid==0&&no==ex)) continue;
            ans++;
        }

        tmp = tmp->child[ch];
        cid--;
    }
    for(int j=0;tmp!=NULL&&j<sz(tmp->ch);j++){
            int no= tmp->ch[j];
            if(rng(0,cid,no)==0||(cid==0&&no==ex)) continue;
            ans++;
    }
}

