int p1=37,p2=53;
const int m1=1000000007;
ll good[1000023];
bool mark[m1+5];
ll compute_hash(string s,ll p,ll m)
{
    ll mult=1;
    ll ans=0;
    for(int i=0;i<s.length();i++)
    {
        ans+=(s[i]*mult);
        ans%=m;
        mult*=p;
        mult%=m;
    }
    return ans;
}
void solve()
{
    ll n;
    cin>>n;
    vs v;
    vector <pair<ll,ll>> temp;
    rep(i,n)
    {
        string s;
        cin>>s;
        v.pb(s);
        ll a=compute_hash(s,p1,m1);
        // ll b=compute_hash(s,p2,m2);
        mark[a]=1;
        good[s.length()]=1;
    }
    ll ans=0;
    for(auto s:v)
    {
        ll len=s.length();
        int cnt[28]={0};
        for(int i=0;i<len;i++)
        {
            cnt[s[i]-'a']++;
        }
        ll suff1=0;
        for(int req=1;req<len;req++)
        {
            if(req==1)
            {
                for(char ch='a';ch<='z';ch++)
                {
                    if(cnt[ch-'a']>0)
                    {
                        ll now=ch;
                        ans+=mark[now];
                    }
                }
                continue;
            }
            cnt[s[len-req+1]-'a']--;
            suff1*=p1;
            suff1+=(s[len-req+1]*p1);
            suff1%=m1;
            // suff2*=p2;
            // suff2+=(s[len-req+1]*p2);
            // suff2%=m2;
            if(good[req]==0)
                continue;
            for(char ch='a';ch<='z';ch++)
            {
                if(cnt[ch-'a']>0)
                {
                    ll now1=(suff1+ch)%m1;
                    // ll now2=(suff2+ch)%m2;
                    ans+=mark[now1];
                }
            }
        }
    }
    cout<<ans<<'\n';
}
