#include <map>

const int N = 3;
using ARR = array<ll, N>;

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n;
    cin, n;
    ll ans = -n;
    ARR MOD = {{1000000007, 1000000009, 1234567891}};
    ARR Base = {{1007, 1009, 1013}};

    auto nxt = [&](const ARR &arr, char c) {
        ARR a;
        REP(i, 0, N) {
            a[i] = (arr[i] * Base[i] + c) % MOD[i];
        }
        return a;
    };

    vector<map<ARR, ll>> m(26);
    vector<string> v(n);
    REP(i, 0, n) {
        cin, v[i];
        reverse(v[i].begin(), v[i].end());
    }

    REP(i, 0, n) {
        ARR arr = {0, 0, 0};
        REP(j, 0, v[i].size() - 1) {
            arr = nxt(arr, v[i][j]);
        }
        int last = v[i].back() - 'a';
        m[last][arr]++;
    }

    REP(_, 0, n) {
        string s = v[_];
        vector<int> mp(26, 0);
        int sz = s.size();
        REP(i, 0, sz) {
            mp[s[i] - 'a']++;
        }
        ARR a = {0, 0, 0};
        REP(i, 0, sz + 1) {
            REP(j, 0, 26) {
                if (mp[j] > 0) {
                    ans += m[j][a];
                }
            }
            if (i != sz) {
                mp[s[i] - 'a']--;
                a = nxt(a, s[i]);
            }
        }
    }
    print(ans);

    return 0;
}

