using namespace std;

const ll mod = 1007;

int main(){
    ll n; cin >> n;
    vector<string> s(n); rep(i,n) cin >> s[i];
    sort(all(s),[&](string a, string b){ return a.size() > b.size(); } );

    vector<vector<ll>> sub(n,vector<ll>(26,0));
    vector<ll> abc(26,0);
    rep(i,n){
        rep(j,s[i].size()) sub[i][s[i][j]-'a']++;
        rep(j,26) if(sub[i][j]) abc[j]++;
    }

    ll ans = 0, num = 1, save = n;
    vector<ll> hash(n,0);
    unordered_map<ll,ll> mp;
    rep(i,26) mp[i] = abc[i];

    while(save > 1){
        unordered_map<ll,ll> nmp;
        rrep(i,save){
            if(s[i].size() == num){
                char c = s[i][0];
                ans += mp[hash[i]*26+(c-'a')]-1;
                n--;
            }
            else{
                char c = s[i][s[i].size()-num];
                hash[i] *= mod;
                hash[i] += c-'a';
                sub[i][c-'a']--;
                rep(j,26) if(sub[i][j]) nmp[hash[i]*26+j]++;
            }
        }
        mp = nmp;
        save = n;
        num++;
    }
    cout << ans << endl;
    return 0;
}

