void insert(string s,int rt)
{
    vector<int> nodes;
    nodes.clear(); 
    for(int i=0;i<(int)s.size();i++)
    {
        int x=s[i]-'a';
        if(trie[rt][x]==0) trie[rt][x]=++tot;
        nodes.push_back(rt);
        rt=trie[rt][x];
    }
    memset(has,false,sizeof(has));
    for(int i=(int)s.size()-1;i>=0;i--)
    {
        has[s[i]-'a']=true;
        int cur=nodes[i];
        for(int j=0;j<26;j++) if(has[j]) cnt[cur][j]++;
    }
}
int get_ans(string s,int rt)
{
    for(int i=0;i<(int)s.size()-1;i++)
    {
        int x=s[i]-'a';
        if(trie[rt][x]==0) return false;
        rt=trie[rt][x];
    }
    int x=s[s.size()-1]-'a';
    return cnt[rt][x];
}
