vector<pair<char, vector<ll>>> Trie;
vector<ll> cnt[26];

signed main() {
    ll N, res = 0;
    cin >> N;
    vector<string> S(N);
    each(s, S) cin >> s, reverse(all(s));
    sort(all(S));
    Trie.push_back({'0', {}});
    rep(k, 26) cnt[k].pb(0);

    each(s, S) {
        ll id = 0;

        ll sum[len(s) + 1][26];
        rep(j, len(s) + 1) rep(k, 26) sum[j][k] = 0;
        rep(j, len(s)) sum[j][s[j] - 'a']++;
        dec(j, len(s) - 1, 0) rep(k, 26) sum[j][k] |= sum[j + 1][k];

        rep(k, 26) if (sum[0][k]) res += cnt[k][id];
        rep(j, len(s) - 1) {
            each(k, Trie[id].second) {
                if (Trie[k].first == s[j]) {
                    id = k;
                    goto success;
                }
            }
            break;
        success:;
            rep(k, 26) if (sum[j + 1][k]) res += cnt[k][id];
        }

        id = 0;
        rep(j, len(s) - 1) {
            each(k, Trie[id].second) {
                if (Trie[k].first == s[j]) {
                    id = k;
                    goto next;
                }
            }
            Trie[id].second.push_back(len(Trie));
            id = len(Trie);
            Trie.push_back({s[j], {}});
            rep(k, 26) cnt[k].pb(0);
        next:;
        }
        cnt[s.back() - 'a'][id]++;
    }

    cout << res << rt;
}

