long long compute_hash(string s) {
    int p = 41;
    int m = 1e9 + 7;
    long long hash_v = 0;
    long long p_pow = 1;
    for (int i = 0; i < s.length(); i++)
    {
        hash_v = (hash_v + (s[i] - 'a' + 1) * p_pow) % m;
        p_pow = (p_pow * p) % m;
    }
    return hash_v;
}
void transform()
{
  int x=compute_hash(cu);
