struct node {
	node* nxt[26];
	int cnt[26];
	int val, sz;
	node() {
		for(int i = 0; i < 26; i++) nxt[i] = nullptr, cnt[i] = 0;
		val = 0;
		sz = 0;
	}
} *root;

void add(string s) {
	node* ptr = root;
	for(char c:s) {
		ptr -> sz++;
		if(!(ptr -> nxt[c-'a'])) {
			ptr -> nxt[c-'a'] = new node();
		}
		ptr = ptr -> nxt[c-'a'];
	}
	ptr -> val++;
	ptr -> sz++;
}

void dfs(node* root) {
	for(int i = 0; i < 26; i++) {
		if(root -> nxt[i]) {
			dfs(root -> nxt[i]);
			root -> cnt[i] += root -> nxt[i] -> sz;
			for(int j = 0; j < 26; j++) if(j != i)
				root -> cnt[j] += root -> nxt[i] -> cnt[j];
		}
	}
}

ll ans = 0;

void dfs1(node* u) {
	for(int i = 0; i < 26; i++)
		if(u -> nxt[i]) {
			ans += (ll) (u -> nxt[i] -> val) * (u -> cnt[i] - 1);
			dfs1(u -> nxt[i]);
		}
}

