bool cmp(string &a , string &b)
{
	return a.size() < b.size() ;
}

int tree[MAX][26] , cnt[MAX][26] ;

int id = 1 ;

void insert(string &s , char c)
{
	int node = 1 ;
	for(auto &c : s)
	{
		if(!tree[node][c-'a'])
			tree[node][c-'a'] = ++id ;
		node = tree[node][c-'a'] ;
	}
	cnt[node][c-'a']++ ;
}

int calc(int node)
{
	int x = 0 ;
	for(int j = 0 ; j < 26 ; ++j)
	{
		if(freq[j])
			x += cnt[node][j] ;
	}
	return x ;
}

int query(string &s)
{
	int node = 1 ;
	int x = calc(node) ;
	for(auto &c : s)
	{
		freq[c-'a']-- ;
		if(!tree[node][c-'a'])
			return x ;
		node = tree[node][c-'a'] ;
		x += calc(node) ;
	}
	return x ;
}

