typedef pair<ll, ll> pll;
typedef vector<pll> vpll;
typedef vector<int> vi;

const ll MOD1 = 1e9 + 7;
const ll MOD2 = 1e9 + 9;
const ll p = 31;
const ll K = 2e9;

vpll sufHashes(string s){
    int n = s.length();
    vpll h(n);
    ll h1 = 0, h2 = 0;
    fornr(i, n){
        ll x = s[i] - 'a' + 1;
        h1 = (h1 * p + x) % MOD1;
        h2 = (h2 * p + x) % MOD2;
        h[i] = {h1, h2};
    }
    h.pb({0, 0});
    return h;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    cout.precision(20);
    int n;
    cin >> n;
    vector<string> a(n);
    forn(i, n) cin >> a[i];
    vector<vector<pair<ll, ll>>> h;
    unordered_set<ll> hashes;
    vector<vi> pos(n, vi(26, 1e9));
    forn(i, n) {
        forn(j, a[i].length()) {
            int c = a[i][j] - 'a';
            if (pos[i][c] == 1e9) pos[i][c] = j;
        }
    }
    forn(i, n) {
        h.pb(sufHashes(a[i]));
        hashes.insert(h[i][0].fst * K + h[i][0].snd);
    }
    ll ans = 0;
    forn(i, n) {
        int l = a[i].length();
        forab(j, 1, sz(a[i])) {
            l--;
            pair<ll, ll> h0 = h[i][j + 1];
            forn(c, 26) {
                if (pos[i][c] <= j) {
                    pair<ll, ll> H = {(h0.fst * p + c + 1) % MOD1, (h0.snd * p + c + 1) % MOD2};
                    if (hashes.count(H.fst * K + H.snd)) {
                        ans++;
                    }
                }
            }
        }
    }
    cout << ans << '\n';
    return 0;
}

