void insert(int u,int d)
{
    if(d==m+1){ed[u]++;return;}
    if(!ch[u][s[d]-'a']) ch[u][s[d]-'a']=++cnt;
    for(int i=0;i<26;i++)
    if(tot[d][i]) ans+=ed[ch[u][i]];
    if(d==m) ans+=ttot[u][s[d]-'a'];
    insert(ch[u][s[d]-'a'],d+1);
    for(int i=0;i<26;i++)
    ttot[u][i]+=tot[d][i];
}
