class AhoCorasick {
private:
	vector2<int> nxt;//現在のノードにchを追加した場合のノード　存在しなければsuffix linkを辿る
	vector<int> fail, end;//suffix link,そのノードに存在する文字列の数
	int root;
	int p;//ノードの数
	int maxn;//文字の合計サイズ
	vector2<int> type;
public:
	AhoCorasick(int maxn) :maxn(maxn), nxt(maxn, vector<int>(26, -1)), fail(maxn), end(maxn, 0), p(1), root(0),type(maxn,vector<int>(26,0)) {}

	inline void insert(const string& s) {
       		Array cnt(26, 0);
      		for(auto ch:s ) cnt[ch-'a']++;
		int now = root;
		REP(i, 26) {
			if (cnt[i] != 0)type[now][i]++;
		}
		for (int i = 0; i < s.size(); i++) {
			if (nxt[now][s[i] - 'a'] == -1) nxt[now][s[i] - 'a'] = p++;
			now = nxt[now][s[i] - 'a'];
			cnt[s[i] - 'a']--;
			REP(j, 26) {
				if (cnt[j] != 0)type[now][j]++;
			}
		}
		end[now]++;
	}

	inline int solve(const string& s) {
		int now = root;
		for (int i = 0; i < s.size() - 1; i++)now = nxt[now][s[i] - 'a'];
		return type[now][s.back() - 'a'] - 1;
	}
};

