struct Node {
  Node *child[26];
  int val[26];

  Node() {
    for (int i = 0; i < 26; ++i) {
      val[i] = 0;
      child[i] =0 ;
    }
  }
};

Node *root;

void add(const string &s) {
  vector<Node*> path;
  path.push_back(root);
  for (int i = (int) s.size() - 1; i >= 0; --i) {
    if (!(path.back()->child[s[i] - 'a'])) {
      path.back()->child[s[i] - 'a'] = new Node();
    }
    path.push_back(path.back()->child[s[i] - 'a']);
  }

  int mask = 0;
  path.pop_back();
  for (int i = 0; i < s.size(); ++i) {
    mask |= (1 << s[i] - 'a');
    for (int j = 0; j < 26; ++j) {
      path.back()->val[j] += (mask >> j & 1);
    }
    path.pop_back();
  }
}

int query(const string &s) {
  Node *cur = root;
  for (int i = (int) s.size() - 1; i > 0; --i) {
    if (!(cur->child[s[i] - 'a'])) return 0;
    cur = cur->child[s[i] - 'a'];
  }

  return cur->val[s[0] - 'a'];
}

