    add(s[i]);
  }

  root = new Node();

  for (int i = n-1; i >= 0; --i) {
    ans += query(s[i]);
    // cerr << ans << endl;
    add(s[i]);
  }

  printf("%lld\n", ans);
  return 0;
}

