int ins()
{
	int no=0;
	for (R i=1;i<=len;++i)
	{
		int x=s[i]-'a'+1;
		if(!ch[no][x]) ch[no][x]=++cnt,cr[cnt]=x;
		no=ch[no][x];
	}
	a[no]++; t[no][ cr[no] ]++; ep[no]++;
	return no;
