struct identity {
    template<typename T>
    T operator()(const T &x) const {
        return x;
    }
};

const double HASH_TABLE_TOO_FULL = 0.95;

template<typename T_key, typename hash_fn_cls>
struct fixed_size_hash_set {
    const hash_fn_cls hash_fn = hash_fn_cls();
    using hash_t = decltype(hash_fn(T_key()));

    int size = 0, inserted = 0;
    vector<hash_t> table;
    vector<bool> filled;

    static int round_up_power_two(int n) {
        while (n & (n - 1))
            n = (n | (n - 1)) + 1;

        return max(n, 1);
    }

    fixed_size_hash_set(int _size = 0) {
        init(_size);
    }

    void init(int _size) {
        size = round_up_power_two(_size);
        table.resize(size);
        filled.assign(size, false);
    }

    // Returns the location where hash_value either has been inserted or would be inserted.
    int locate(hash_t hash_value) const {
        int position = int(hash_value & (size - 1));

        while (filled[position] && table[position] != hash_value)
            position = (position + 1) & (size - 1);

        return position;
    }

    bool contains(T_key key) const {
        hash_t hash_value = hash_fn(key);
        int position = locate(hash_value);
        return filled[position];
    }

    // Returns true if the key was not in the hash table previously.
    bool insert(T_key key) {
        hash_t hash_value = hash_fn(key);
        int position = locate(hash_value);

        if (!filled[position]) {
            filled[position] = true;
            table[position] = hash_value;
            inserted++;
            assert(inserted < HASH_TABLE_TOO_FULL * size);
            return true;
        }

        return false;
    }
};


const int ALPHABET = 26;
const char MIN_CHAR = 'a';

const int HASH_TABLE_SIZE = 4e5;

int main() {
    ios::sync_with_stdio(false);
#ifndef NEAL_DEBUG
    cin.tie(nullptr);
#endif

    int N;
    cin >> N;
    vector<string> S(N);

    for (auto &s : S)
        cin >> s;

    sort(S.begin(), S.end(), [](const string &x, const string &y) {
        return x.size() < y.size();
    });

    fixed_size_hash_set<uint64_t, identity> hash_set(HASH_TABLE_SIZE);
    int64_t answer = 0;

    for (auto &str : S) {
        int n = int(str.size());
        reverse(str.begin(), str.end());
        vector<int> latest(ALPHABET, -1);

        for (int i = 0; i < n; i++)
            latest[str[i] - MIN_CHAR] = i;

        string_hash<string> hasher;

        for (int i = 0; i < n; i++) {
            for (int c = 0; c < ALPHABET; c++)
                if (latest[c] >= i) {
                    hasher.add_char(char(MIN_CHAR + c));
                    answer += hash_set.contains(hasher.complete_hash());
                    hasher.pop_char();
                }

            hasher.add_char(str[i]);
        }

        hash_set.insert(hasher.complete_hash());
    }

    cout << answer << '\n';
}

