class Trie {
    struct Node {
        Node() {
            // memset(next,0,sizeof(next));
            memset(rightest,0,sizeof(rightest));
            deep = 0;
        }
        int deep;
        int rightest[26];//a-z
        // Node* next[26];
        unordered_map<char, Node*> next;
    };
public:
    ~Trie() {
        for(auto it = root.next.begin(); it != root.next.end(); it++) {
            deleteNode(it->second);
        }
        root.next.clear();
    }
    void deleteNode(Node* node) {
        if(node==nullptr) return;
        for(auto it = node->next.begin(); it != node->next.end(); it++) {
            deleteNode(it->second);
        }
        delete node;
    }
    void addToTrie(string &s, int* rightest) {
        rep(i,0,26) {
            if(rightest[i] >= root.deep) root.rightest[i]++;
        }
        if(root.next.count(s[0]) == 0) {
            root.next[s[0]] = new Node();
        }
        Node* cur = root.next[s[0]];
        cur->deep = 0;
        rep(i,0,26) {
            if(rightest[i] > cur->deep) cur->rightest[i]++;
        }
        rep(i,1,s.length()) {
            if(cur->next.count(s[i])==0) {
                cur->next[s[i]] = new Node();
            }
            Node* next = (cur->next[s[i]]);
            next->deep = cur->deep+1;
            rep(j,0,26) {
                if(rightest[j] > next->deep) next->rightest[j]++;
            }
            cur = next;
        }
    }
    ll countT(string &s) {
        Node* cur = &root;
        rep(i,0,s.length()-1) {
            Node* next = cur->next[s[i]];
            cur = next;
        }
        return cur->rightest[s[s.length()-1]-'a']-1;
    }
    Node root;
};

class Solution
{
public:
	void Solve()
	{
		int n;
        while(cin>>n)
        {
            Trie trie;
            vector<string> vs(n);
            rep(i,0,n) {
                cin>>vs[i];
                int rightest[26];
                memset(rightest,-1,sizeof(rightest));
                reverse(vs[i].begin(), vs[i].end());
                rep(j,0,vs[i].length()) {
                    rightest[vs[i][j]-'a'] = j;
                }

                trie.addToTrie(vs[i], rightest);
            }
            ll ans = 0;
            rep(i,0,n) {
                ans += trie.countT(vs[i]);
            }
            cout<<ans<<endl;
        }
	}

private:
};
