void reverse(string &s) {
	int l = 0, r = s.length() - 1;
	while (l < r) {
		swap(s[l], s[r]);
		l++; r--;
	}
}

int n;
string s[200000];
int l[200000], r[200000];
int cnts[1000001][26];

bool check(string &key, string &s, int comp) {
	if (s.length() < key.length()) return false;
	int i;
	for (i = 0; i < key.length(); i++) {
		if (s[i] != key[i]) {
			if (comp == 0) {
				if (s[i] < key[i]) return false;
				return true;
			}

			if (s[i] > key[i]) return false;
			return true;
		}
	}
	return true;
}

int findL(int index) {
	string key;
	int i;
	rep(i, (int)s[index].length() - 1) key += s[index][i];

	int ng = -1, ok = index;
	while (ok - ng >= 2) {
		int mid = (ng + ok) / 2;
		if (check(key, s[mid], 0)) ok = mid;
		else ng = mid;
	}
	return ok;
}

int findR(int index) {
	string key;
	int i;
	rep(i, (int)s[index].length() - 1) key += s[index][i];

	int ok = index, ng = n;
	while (ng - ok >= 2) {
		int mid = (ng + ok) / 2;
		if (check(key, s[mid], 1)) ok = mid;
		else ng = mid;
	}
	return ok;
}

void add(int index) {
	int len = s[index].length();

	for (int i = 0; i < len; i++) {
		//TLE
		for (int j = 0; j <= i; j++) {
			cnts[j][s[index][i] - 'a']++;
		}
	}
}

void del(int index) {
	int len = s[index].length();

	for (int i = 0; i < len; i++) {
		//TLE
		for (int j = 0; j <= i; j++) {
			cnts[j][s[index][i] - 'a']--;
		}
	}
}

signed main() {
	int i;

	cin >> n;
	rep(i, n) {
		cin >> s[i];
		reverse(s[i]);
	}
	sort(s, s + n);

	/*rep(i, n) {
		cout << "s[" << i << "] = " << s[i] << endl;
	}*/

	rep(i, n) {
		l[i] = findL(i);
		r[i] = findR(i) + 1;
		//cout << "前処理: " << s[i] << ", l = " << l[i] << ", r = " << r[i] << endl;
	}

	vector<int> qi(n);
	rep(i, n) qi[i] = i;
	int sq = sqrt((double)n);
	sort(qi.begin(), qi.end(), [&](int i, int j) {
		if (l[i] / sq != l[j] / sq) return l[i] < l[j];
		return r[i] < r[j];
	});

	//クエリの処理
	int ans = 0;
	int nl = 0, nr = 0;	//[nl, nr)
	for (int i : qi) {
		while (nl > l[i]) { --nl; add(nl); }
		while (nr < r[i]) { add(nr); nr++; }
		while (nl < l[i]) { del(nl); nl++; }
		while (nr > r[i]) { --nr; del(nr); }

		//cout << "i = " << i << ", s = " << s[i] << ", l = " << nl << ", r = " << nr << endl;

		/*クエリの計算結果*/
		int len = s[i].length() - 1;
		ans += cnts[len][s[i][len] - 'a'];
	}

	cout << ans - n << endl;
	return 0;
}

