int Ile(vector<int>& a, int k)
{
    int l = 0, p = a.size() - 1, s, r = -1;
    while (l <= p)
    {
        s = (l + p) / 2;
        if (a[s] >= k)
        {
            r = s;
            p = s - 1;
        }
        else
            l = s + 1;
    }
    if (r == -1)
        return 0;
    return a.size() - r;
}

ll Pyt(vector< vector<int> >& T, int a, int b, int k)
{
    a += l;
    b += l;
    int wyn = Ile(T[a], k);
    if (a != b)
        wyn += Ile(T[b], k);
    while (a / 2 != b / 2)
    {
        if (a % 2 == 0)
            wyn += Ile(T[a + 1], k);
        if (b % 2 == 1)
            wyn += Ile(T[b - 1], k);
        a /= 2;
        b /= 2;
    }
    return wyn;
}

