template <typename T>
class RecursiveFunction {
    T t;

public:
    RecursiveFunction(T&& t) : t(forward<T>(t)) {}

    template <typename... Args>
    auto operator()(Args&& ... args) const {
        return t(*this, forward<Args>(args)...);
    }
};


class BFirstSecond {
public:
    void solve() {
        int n = in.readInt();
        auto s = in.readStringArray(n);

        struct Node {
            arr<Node*> children = arr<Node*>(26, nullptr);
            int ends = 0;
        };
        Node* root = new Node();
        for (auto& t : s) {
            reverse(all(t));
            Node* cur = root;
            for (char c : t) {
                c -= 'a';
                if (cur->children[c] == nullptr) {
                    cur->children[c] = new Node();
                }
                cur = cur->children[c];
            }
            cur->ends++;
        }
        arri qty(26, 0);
        ll answer = -n;
        RecursiveFunction rec = [&](const auto& self, Node* root, int total) -> void {
            answer += ll(total) * root->ends;
            for (int i : range(26)) {
                if (root->children[i] != nullptr) {
                    qty[i] += root->children[i]->ends;
                }
            }
            for (int i : range(26)) {
                if (root->children[i] != nullptr) {
                    int was = qty[i];
                    qty[i] = 0;
                    self(root->children[i], total + was);
                    qty[i] = was;
                }
            }
            for (int i : range(26)) {
                if (root->children[i] != nullptr) {
                    qty[i] -= root->children[i]->ends;
                }
            }
        };
        rec(root, 0);
        out.printLine(answer);
    }
};


