#define lk 32

typedef struct{
  int lp;
  int par;
  int bkw;
  int chi[lk];
  int cnt[lk];
}trn;

int trc=0;
trn *trie;
long long res=0;

void trinit(){
  int i;
  trie[0].lp=0;
  trie[0].par=-1;
  trie[0].bkw=-1;
  for(i=0;i<lk;i++){
    trie[0].chi[i]=-1;
    trie[0].cnt[i]=0;
  }
  trc=1;
}

void crn(int x,int pt){
  int i;
  trie[x].chi[pt]=trc;
  trie[trc].par=x;
  trie[trc].bkw=pt;
  trie[trc].lp=trie[x].lp+1;
  for(i=0;i<lk;i++){
    trie[trc].chi[i]=-1;
    trie[trc].cnt[i]=0;
  }
  trc++;
}

int run(string &s,int l){
  int i,j,v=0,c;
  int rem[32]={0};
  for(i=0;i<l;i++){rem[s[i]-'`']++;}
  for(i=0;i<l;i++){
    c=s[i]-'`';
    for(j=1;j<32;j++){
      if(rem[j]!=0){res+=trie[v].cnt[j];}
    }
    if(i==l-1){trie[v].cnt[s[i]-'`']++;}
    rem[c]--;
    if(trie[v].chi[c]==-1){crn(v,c);}
    v=trie[v].chi[c];
  }
  return v;
}

int main(void){
  trie=((trn*)malloc(sizeof(trn)*1048576));
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  trinit();

  long long i,j,n,p,l;
  sd dat[262144];

  cin >> n;
  vector<string> str(n);
  for(i=0;i<n;i++){
    cin >> str[i];
    reverse(str[i].begin(),str[i].end());
    dat[i].val=str[i].size();
    dat[i].node=i;
  }
  qsort(dat,n,sizeof(dat[0]),sdsortfnc);
  for(i=0;i<n;i++){
    p=dat[i].node;
    l=dat[i].val;
    run(str[p],l);
  }
  cout << res << '\n';
  return 0;
}

