void make_substr2(string& s, vector<unordered_set<string>>& output) {
    output[s.length()].emplace(s);
    if (s.length() >= 2) {
        auto s0 = s.back();
        s.pop_back();
        auto s1 = s.back();
        make_substr2(s, output);
        s.back() = s0;
        make_substr2(s, output);

        s.back() = s1;
        s.push_back(s0);
    }
}

void make_substr(string s, vector<unordered_set<string>>& output) {
    if (!s.empty()) {
        output.assign(s.length() + 1, {});
        make_substr2(s, output);
    }
}

