        for (int j = m - 1;j >= 0;--j) {
            hash.first = (hash.first * B1 + s[j] - 'a')%M1;
            hash.second = (hash.second * B2 + s[j] - 'a')%M2;
            hashes[j] = hash;
        }

        set<Pu> now;
        for (int j = 0;j < m; ++j) {
            if (j - 2 >= 0) alpha[s[j - 2] - 'a'] = 1;
            now.insert(hashes[j]);
            rep(k,26) {
