        if ( v[ where ].to[ i ] > 0 ) {
            upd ( v[ where ].to[ i ] ) ;
            for ( int j = 0 ; j < 26 ; ++ j ) {
                if ( i != j ) {
                    v[ where ].cnt[ j ] += v[ v[ where ].to[ i ] ].cnt[ j ] ;
