ll binPow(ll num, ll p, ll mod){
    if(!p) return 1;
    ll aux = binPow(num,p/2,mod);
    return aux*aux%mod*(p%2?num:1)%mod;
}
inline ll modInv(ll num, ll mod){
    return binPow(num,mod-2,mod);
}
const ll BIG = 1e18;
const ll NMAX = 2e5+5;
const ll MOD = 1e9+7;
const ll hashMod=1521602933,hashP=31;
ll polyhash(string s){
    if(s.empty()) return 0;
    ll currentPow=1,hashval=0;
    for(ll i=s.size()-1;i>=0;i--){
        hashval=(hashval+currentPow*(s[i]-'a'))%hashMod;
        currentPow=currentPow*hashP%hashMod;
    }
    return hashval;
}
