    cout << setprecision(10) << fixed;
    cin >> N;
    for(int i = 0; i < N; i++){
        cin >> T[i];
        p[i] = P(T[i].size(), i);
    }
    sort(p, p+N);
    for(int i = 0; i < N; i++){
        int idx = p[i].second; 
        S[i] = T[idx];
        reverse(S[i].begin(), S[i].end());
    }
    node root = (node){'a', vector<int>(), 0, vector<node>()};
    ll ans = 0;
    for(int i = 0; i < N; i++){
        // cout << S[i] << endl;
        vector<int> cnt(26);
        auto cur = &root;
        int sz = S[i].size();
        for(int j = 0; j < cur->v.size(); j++){
            cnt[j] += cur->v[j];
        }
        for(int j = 0; j+1 < sz; j++){
            char c = S[i][j];
            ans += cnt[c-'a'];
            if(hasChar(*cur, c)){
                // cout << "has:" << c << endl;
                cur = &getNode(*cur, c);
            }else{
                addNode(*cur, c);
                cur = &getNode(*cur, c);
            }
            for(int j = 0; j < cur->v.size(); j++){
                cnt[j] += cur->v[j];
            }
        }
        if(cur->v.size() == 0){
            cur->v = vector<int>(26);
        }
        char c = S[i][sz-1];
        ans += cnt[c-'a'];
        cur->v[c-'a']++;
        // cout << ans << endl;
    }
    cout << ans << endl;
}

