struct Trie{
    Trie * next[26];
    int cnt[26];

    Trie()
    {
        for(int i=0;i<26;i++)
        {
            next[i] = NULL;
            cnt[i] = 0;
        }
    }
};

Trie * head = new Trie;

int found(string &str)
{
    Trie * np = head;
    int n = str.size();
    for(int i = n-1; i>0;i--)
    {
        if(np->next[str[i] - 'a'] == NULL)
            return 0;
        np = np->next[str[i] - 'a'];
    }
    return np->cnt[str[0] - 'a'];
}

void add(string &str)
{
    vector<int> count(26,0);
    int n = str.size();
    for(int i=0;i<n;i++)
        count[str[i] - 'a']++;
    Trie * np = head;
    for(int i=n-1; i>=0; i--)
    {   
        for(int j=0;j<26;j++)
        {
            if(count[j] > 0)
                np->cnt[j]++;
        }
        count[str[i] - 'a']--;
        if(np->next[str[i] - 'a'] == NULL)
            np->next[str[i] - 'a'] = new Trie;
        np = np->next[str[i] - 'a'];
    }
}

