inline bool check(string s, string t)
{
    if(s.size() == t.size())
    {
        if(s == t) return true;
        else return false;
    }
    if(s.size() > t.size()) swap(s, t);
    rep(i,s.size()-1) if(s[i] != t[i]) return false;
    char c = s.back();
    for(int i = s.size()-1; i < t.size(); i++)
    {
        if(c == t[i]) return true;
    }
    return false;
}
