void solve() {
  ini(N);
  vs s(N);
  in(s);
  each(x,s)reverse(all(x));
  sort(all(s));
  vl lcp(N);
  rep(i, N - 1) {
    int j = 0;
    while (j < sz(s[i]) and j < sz(s[i + 1]) and s[i][j] == s[i + 1][j])
      lcp[i] = ++j;
  }
  //trc(s);
  SparseTable<ll> sparse(lcp);
  //trc(lcp);
  V<V<V<ll>>> calc(N);
  rep(_, N) {
    vvl& v = calc[_];
    v.resize(sz(s[_]) + 1, vl(26));
    rep(i, sz(s[_])) rep(j, 26) v[i + 1][j] = v[i][j] + (s[_][i] == j + 'a');
    //trc(_);trc(v);
  }

  // auto ord = mkord(N, [&](int i, int j) { return sz(s[i]) > sz(s[j]); });

  ll ans = 0;
  trc(s);
  rep(i, N) {
    int left, right;
    int len = sz(s[i]) - 1;
    {
      int ng = -1, ok = i;
      while (ng + 1 < ok) {
        int med = (ng + ok) / 2;
        (sparse.query(med, i) >= len ? ok : ng) = med;
      }
      left = ok;
    }
    {
      int ok = i, ng = N;
      while (ok + 1 < ng) {
        int med = (ok + ng) / 2;
        (sparse.query(i, med) >= len ? ok : ng) = med;
      }
      right = ok;
    }
    int c = s[i].back() - 'a';
    trc(i,left,right,c);
    for (int j = left; j <= right; j++) {
      if (sz(s[j]) == sz(s[i])) continue;
      trc(s[i],s[j]);
      //trc(calc[j].back());
      //trc(calc[j][len]);
      ans += (calc[j][sz(s[j])][c] - calc[j][len][c] > 0);
    }
    trc(ans);
  }

  out(ans);
}

