class trie {
public:
  trie(size_t max_size) {
    size = 1; // only root
    next.assign(26, vector<int>(max_size, -1));
    end.assign(max_size, false);
    //
    count.assign(26, vector<int>(max_size, 0));
    //
  }

  bool search(string s) {
    int now = 0;
    for (char c : s) {
      if (next[c - 'a'][now] == -1) return false;
      now = next[c - 'a'][now];
    }
    return end[now];
  }

  void insert(string s) {
    int now = 0;
    vector<int> path;
    int checked = 0;
    for (char c : s) {
      path.push_back(now);
      if (next[c - 'a'][now] == -1) next[c - 'a'][now] = size++;
      //
      if ((checked >> (c - 'a') & 1) == 0) {
        checked |= 1 << (c - 'a');
        for (size_t i = 0; i < path.size(); ++i) ++count[c - 'a'][path[i]];
      }
      //
      now = next[c - 'a'][now];
    }
    end[now] = true;
  }
  //
  int solve(string s, char x) {
    int now = 0;
    for (char c : s) now = next[c - 'a'][now];
    return count[x - 'a'][now];
  }
  //

private:
  vector<vector<int>> next;
  vector<bool> end;
  //
  vector<vector<int>> count;
  //
  int size;
};

int main() {
  int n;
  cin >> n;
  vector<string> a(n);
  trie tr(1000001);
  rep(i, 0, n) {
    cin >> a[i];
    reverse(a[i].begin(), a[i].end());
    tr.insert(a[i]);
  }
  int ans = 0;
  rep(i, 0, n) {
    char last = a[i].back();
    a[i].pop_back();
    ans += tr.solve(a[i], last) - 1;
  }
  cout << ans << '\n';
  return 0;
}

