int Trie(string& X, int c, int ind) {
	if (ind == X.size()) {
		return c;
	}
	if (trie[c][X[ind] - 'a']) {
		return Trie(X, trie[c][X[ind] - 'a'], ind + 1);
	}
	T_sz++;
	vc[T_sz] = X[ind];
	pa[T_sz] = c;
	trie[c][X[ind] - 'a'] = T_sz;
	return Trie(X, T_sz, ind + 1);
}

int sear(int c, char ch) {
	if (vc[c] == ch) {
		vi[c][ch - 'a'] = cnt[c];
		for (int i = 0;i < 26;i++) {
			if (trie[c][i] == 0)continue;
			sear(trie[c][i], ch);
		}
		return cnt[c];
	}
	int A = 0;
	for (int i = 0;i < 26;i++) {
		if (trie[c][i] == 0)continue;
		A += sear(trie[c][i], ch);
	}
	vi[c][ch - 'a'] = A;
	return A;
}

