int n,tot=1,ans,val[1000010];
string s[200010];
vector<pair<int,int> > v[1000010];

inline void dfs(int x,int pr,int id,int lvl)
{
	if(lvl<0){
		val[x]++;return;
	}
	bool flag=false;
	for(int i=0;i<v[x].size();i++) if(v[x][i].first!=pr){
		if(v[x][i].second==s[id][lvl]-'a'){
			flag=true;
			dfs(v[x][i].first,x,id,lvl-1);
			break;
		}
	}
	if(!flag){
		tot++;
		v[x].push_back(make_pair(tot,s[id][lvl]-'a'));
		v[tot].push_back(make_pair(x,s[id][lvl]-'a'));
		dfs(tot,x,id,lvl-1);
	}
}

inline void solve(int x,int pr,int sum,vector<int> col)
{
	if(val[x]){
		ans+=sum;
		sum++;
	}
	vector<int> nw;nw.resize(26,0);
	for(int i=0;i<26;i++) nw[i]=col[i];
	for(int i=0;i<v[x].size();i++) if(v[x][i].first!=pr){
		if(val[v[x][i].first]) nw[v[x][i].second]++;
	}
	for(int i=0;i<v[x].size();i++) if(v[x][i].first!=pr){
		int pre=nw[v[x][i].second];
		sum+=nw[v[x][i].second]-val[v[x][i].first];nw[v[x][i].second]=0;
		solve(v[x][i].first,x,sum,nw);
		nw[v[x][i].second]=pre;sum-=nw[v[x][i].second]-val[v[x][i].first];
	}
}

signed main()
{
	ios::sync_with_stdio(false);
	cin>>n;
	for(int i=1;i<=n;i++) cin>>s[i];
	for(int i=1;i<=n;i++){
		dfs(1,-1,i,s[i].size()-1);
	}
	vector<int> xx;xx.resize(26,0);
	solve(1,-1,0,xx);
	cout<<ans<<endl;
	return 0;
}

