ll ans;

int tot=1,ch[1000005][26],siz[1000005];
void insert(vector<int>& S){
    static int pre[1000005][26];
    REP(i,1,sz(S))memset(pre[i],0,sizeof pre[i]);
    REP(i,0,sz(S)-1){
	memcpy(pre[i+1],pre[i],sizeof pre[i]);
	++pre[i+1][S[i]];
    }
    reverse(S.begin(),S.end());
    int p=1,t=sz(S);
    for(int c:S){
	REP(i,0,25)if(pre[t][i])ans+=siz[ch[p][i]];
	if(!ch[p][c])ch[p][c]=++tot;
	p=ch[p][c],--t;
    }
    ++siz[p];
}

