#define B1 100000007
#define B2 9999999999999937

ll rolling_hash(string const& S) {
    ll res = 1, b_n = 1;
    rep(i, S.size()){
        res = (res + S[i]*b_n) % B2;
        b_n = b_n * B1 % B2;
    }
    return res;
}

