		else res+=Map[mp(s[0],hash_s.get_prefix(1,len-1))];
		for(int i=0;i<len;++i){
			c.insert(s[i]);
			for(char x:c)
				if(i==len-1) Map[mp(x,mp(-1,-1))]++;
