    auto num = make_vec<Int>(1, 26, 0);
    for (const std::string& s : ss) {
        Int idx = 0;
        REP(i, s.size() - 1) {
            REP(c, 26) {
                if (num[idx][c] && std::find(s.begin() + i, s.end(), 'a' + c) != s.end()) ans += num[idx][c];
            }
            Int c = s[i] - 'a';
            if (t.tree[idx][c] == -1) {
                t.tree[idx][c] = t.tree.size();
                t.tree.emplace_back();
                num.emplace_back(26);
            }
            idx = t.tree[idx][c];
        }
        num[idx][s.back() - 'a']++;
    }
    std::cout << ans << std::endl;
