const int N = (int) 2e5 + 7;
int n;
int lcp[N];
int lim[N];
int t[4 * N];
int f[N][26];
string a[N];
int mn[26][4 * N];
int mx[26][4 * N];

void build(int v, int tl, int tr) {
  if (tl == tr) {
    for (int x = 0; x < 26; x++) {
      mn[x][v] = mx[x][v] = f[tl][x];
    }
    t[v] = lcp[tl];
  } else {
    int tm = (tl + tr) / 2;
    build(2 * v, tl, tm);
    build(2 * v + 1, tm + 1, tr);
    t[v] = min(t[2 * v], t[2 * v + 1]);
    for (int x = 0; x < 26; x++) {
      mn[x][v] = min(mn[x][2 * v], mn[x][2 * v + 1]);
      mx[x][v] = max(mx[x][2 * v], mx[x][2 * v + 1]);
    }
  }
}

int get(int v, int tl, int tr, int l, int r) {
  if (tr < l || r < tl) {
    return (int) 1e9;
  }
  if (l <= tl && tr <= r) {
    return t[v];
  }
  int tm = (tl + tr) / 2;
  return min(get(2 * v, tl, tm, l, r), get(2 * v + 1, tm + 1, tr, l, r));
}

void build() {
  build(1, 1, n);
}

int get(int i, int j) {
  if (i == j) {
    cout << "why equal?\n";
    exit(0);
  }
  if (i > j) {
    swap(i, j);
  }
  return get(1, 1, n, i, j - 1);
}

int calc(int v, int tl, int tr, int l, int r, int x, int need) {
  if (tr < l || r < tl) {
    return 0;
  }
  if (l <= tl && tr <= r) {
    if (mn[x][v] >= need) {
      return tr - tl + 1;
    }
    if (mx[x][v] < need) {
      return 0;
    }
  }
  int tm = (tl + tr) / 2;
  return calc(2 * v, tl, tm, l, r, x, need) + calc(2 * v + 1, tm + 1, tr, l, r, x, need);
}

