  for (int i = 1; i <= n; i++) {
    cin >> a[i];
    reverse(a[i].begin(), a[i].end());
  }
  sort(a + 1, a + n + 1);
  for (int i = 1; i < n; i++) {
    lcp[i] = get_lcp(a[i], a[i + 1]);
  }
  for (int i = 1; i <= n; i++) {
    for (auto &ch : a[i]) {
      f[i][ch - 'a']++;
    }
  }
  build();
  for (int i = 1; i <= n; i++) {
    int len = (int) a[i].size();
    int pos = i, lo = i + 1, hi = n;
    while (lo <= hi) {
      int mid = (lo + hi) / 2;
      if (get(i, mid) >= len - 1) {
        pos = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
    lim[i] = pos;
  }
  ll sol = 0;
  for (int i = 1; i <= n; i++) {
    int x = a[i].back() - 'a', need = f[i][x];
    int now = calc(1, 1, n, i + 1, lim[i], x, need);
    sol += now;
  }
  cout << sol << "\n";
  return 0;
}

