    for(int i=1;i<MAX;i++){
        ru1[i]=ru1[i-1]*ha1%mod1;
        ru2[i]=ru2[i-1]*ha2%mod2;
    }
    int N;cin>>N;
    ll ans=0;
    vector<string> A(N);
    for(int i=0;i<N;i++){
        cin>>A[i];
        reverse(all(A[i]));
    }
    sort(all(A),[](auto a,auto b){
        if(si(a)==si(b)) return a<b;
        return si(a)<si(b);
    });

    vector<Rollinghash> S(N);
    for(int i=0;i<N;i++){
        S[i].make(A[i],ha1,ha2);
    }

    int i=0;
    while(i<N){
        int j=i;
        while(j<N&&si(A[i])==si(A[j])) j++;

        map<pair<ll,ll>,int> MA;

        for(int k=i;k<j;k++){
            MA[S[k].ha(0,si(A[k])-1)]|=(1<<(A[k].back()-'a'));
