struct node {
  node *nex[26];
  int tot[26];
  int sum;
} *root = new node;

string s[200005];

node *add(string &s) {
  node *cur = root;
  node *old = nullptr;
  for (char c : s) {
    cur->sum++;
    int i = c - 'a';
    if (cur->nex[i] == nullptr)
      cur->nex[i] = new node;
    old = cur;
    cur = cur->nex[i];
  }
  cur->sum++;
  return old;
}

void comp(node *cur) {
  for (int i = 0; i < 26; i++) {
    if (cur->nex[i] == nullptr)
      continue;
    comp(cur->nex[i]);
    cur->tot[i] += cur->nex[i]->sum;
    for (int j = 0; j < 26; j++) {
      if (i == j) continue;
      cur->tot[j] += cur->nex[i]->tot[j];
    }
  }
}

