struct Tnode
{
    int sum[26];
    int child[26];
    int P;
};

Tnode Trie[N];
int nT=0;
int root;

int AddNode()
{
    nT++;
    for(int i=0;i<26;i++)
    {
        Trie[nT].child[i]=0;
        Trie[nT].sum[i]=0;
    }
    Trie[nT].P=0;
    return nT;
}

void AddWord(string s)
{
    memset(cnt,0,sizeof cnt);
    int r=root;
    for(int i=0;i<s.size();i++)
    {
        int k=s[i]-'a';
        int l;
        if (Trie[r].child[k]==0)
        {
            l=AddNode();
            Trie[r].child[k]=l;
            Trie[l].P=r;
        }
        r=Trie[r].child[k];
    }
    int cur=s.size()-1;
    while (r!=root)
    {
        r=Trie[r].P;
        if(cnt[s[cur]-'a']==0) cnt[s[cur]-'a']++;
        for(int i=0;i<26;i++) Trie[r].sum[i]+=cnt[i];
        cur--;
    }
}

void solve()
{
    cin>>n;
    vector<pii>order;
    for(int i=1;i<=n;i++)
    {
        cin>>s[i];
        order.push_back(mp(s[i].size(),i));
    }
    sort(order.rbegin(),order.rend());
    long long res=0;
    for(int i=0;i<n;i++)
    {
        string t=s[order[i].se];
        reverse(t.begin(),t.end());
        int cur=0;
        bool kt=true;
        for(int j=0;j<t.size()-1;j++)
        {
            if(!Trie[cur].child[t[j]-'a'])
            {
                kt=false;
                break;
            }
            cur=Trie[cur].child[t[j]-'a'];
        }
        if(kt)
        {
            int val=t.back()-'a';
            res+=1ll*Trie[cur].sum[val];
        }
        AddWord(t);
    }
    cout<<res;
}

