using Node = array<int, 26>;

struct Trie {
	vector<Node> a;
	vector<Node> counts;

	Trie() {
		a.push_back({});
		counts.push_back({});
	}

	int create() {
		a.push_back({});
		counts.push_back({});
		return (int)a.size() - 1;
	}

	int proceed(const string& s) {
		int v = 0;
		for (char c : s) {
			if (!a[v][c - 'a']) {
				int nw = create();
				a[v][c - 'a'] = nw;
			}
			v = a[v][c - 'a'];
		}
		return v;
	}

	void add(const string& s) {
		vector<int> path = {0};
		for (char c : s) {
			if (!a[path.back()][c - 'a']) {
				int nw = create();
				a[path.back()][c - 'a'] = nw;
			}
			int nw = a[path.back()][c - 'a'];
			path.push_back(nw);
		}
		set<char> S;
		for (int i = (int)s.length() - 1; i >= 0; --i) {
			path.pop_back();
			int v = path.back();
			S.insert(s[i]);
			for (char c : S) {
				counts[v][c - 'a'] += 1;
			}
		}
	}
};

void solve() {
	int n = nxt();
	vector<string> a(n);
	for (auto& s : a) {
