	});
	Trie t;
	long long ans = 0;
	for (const auto& s : a) {
		int v = t.proceed(s.substr(0, (int)s.length() - 1));
		ans += t.counts[v][s.back() - 'a'];
		t.add(s);
	}
	cout << ans << "\n";
}

int main() {
	ios_base::sync_with_stdio(false);

	int t = 1; // nxt();
	while (t--) {
		solve();
	}

