class RollingHash {
 public:
  void Add(char c) {
    const unsigned long long base = 100000007;
    hash_ = hash_ * base + c;
  }
  size_t hash() const { return hash_ ^ (hash_ >> 32); }
  bool operator==(const RollingHash &h) const { return hash_ == h.hash_; }

 private:
  unsigned long long hash_ = 0;
};

