void add_string(string const& s) {
    int v = 0;
    for (char ch : s) {
        int c = ch - 'a';
        if (trie[v].next[c] == -1) {
            trie[v].next[c] = trie.size();
            trie.emplace_back();
        }
        trie[v].leafs_cnt++;
        v = trie[v].next[c];
    }


    trie[v].leaf = true;
    trie[v].leafs_cnt++;
}

void simplify(int v, int way)
{

    for(int i= 0;i<K;i++)
    {
        if(trie[v].next[i] != -1)
        {
            simplify(trie[v].next[i], i);
        }


    }



    for(int i= 0;i<K;i++)
    {
        if(trie[v].next[i] != -1)
        {
            for(int j = 0;j<K;j++)
            {
                trie[v].cnt[j] += trie[trie[v].next[i]].cnt[j];
            }
            trie[v].cnt[i]+= (trie[trie[v].next[i]].leaf ==true);
        }
    }
    if(way != -1)
        trie[v].cnt[way] = trie[v].leafs_cnt - (trie[v].leaf==true);

}

