    rep(i, n) {in1(ss[i]); reverse(all(ss[i]));}
    // n = 1e6; ss = vector<string>(n, "a");
    auto cmp = [&](string s1, string s2)->bool{return s1.length() < s2.length();};
    sort(all(ss), cmp);

