/*
      x: 1001 1010  1100 1011 1101  1111
x & ~ x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

####### Attention #######
S | (1 << i) -> S union {i}
S & ~(1 << i) -> S - {i}

# inclusion-exclusion principle
|U[i = 1 to n] Ai| = sum[i = 1 to n] |Ai| - sum[i < j]|Ai ^ Aj| + ... + (-1)^(n - 1) |^[i = 1 to n]Ai|
*/

const ll MAX_N = 200005;
const size_t MAX_BIT = 160 * 160 + 10;
typedef bitset<MAX_BIT> bts;
typedef vector<bts> vbt;
typedef vector<vbt> vbt2;
typedef vector<vbt2> vbt3;
const bool multiple_queries = false;

void solve(){
    // generate_array(size, min, max);
    ll n; in1(n);
    vector<string> ss(n);
    rep(i, n) in1(ss[i]);
    sort(all(ss), [](string s1, string s2)->bool{
        return s1.length() < s2.length();
    });

    vb2 inc(26, vb(n, false));
    map<ll, ll> cnt;
    rep(i, n){
        rep(j, ss[i].length()){
            inc[ss[i][j] - 'a'][i] = true;
        }
        rep(j, 26) cnt[j] += inc[j][i];
    }

    auto judge = [&](ll i, ll j) -> bool{
        ll mi = ss[i].length(), mj = ss[j].length();
        string si, sj;
        si = substring(ss[i], 1, mi - 1);
        sj = substring(ss[j], mj - mi + 1, mj - 1);
        if (si != sj) return false;
        rep(k, mj - mi + 1)
            if (ss[i][0] == ss[j][k])
                return true;
        return false;
    };

    ll ans = 0;
    rep(i, n - 1){
        if (ss[i].length() == 1){
            ans += cnt[ss[i][0] - 'a'] - 1;
            continue;
        }
        For(j, i + 1, n)
            ans += judge(i, j);
    }

    prl(ans);

    // ### DEBUG PART ###
    auto naive_solver = [&](){
    };
    #ifdef _LOCAL
        naive_solver();
    #endif
}

void test(ll num = 0, bool verbose = false){
    rep(i, max(1LL, num)){
        ll t = clock();
        if (verbose) prl4("\n#####", i + 1, "#####", "\n## Answer ##");
        solve();
        if (verbose) {prl(""); prl_time(t);}
    }
}

