// Trie 木
// O(|S|) で文字列を挿入する
// O(max(Trie木に入っている文字列 & 検索キーとなる文字列) ) なので、検索キー文字列が長くても、辞書内の文字列が短ければすぐ終わる  ex)天下一2016-C たんごたくさん
// メモリ領域は最悪でも max(|S|)*(文字種数)*(文字種数)+(文字列数) か？
// Trie<26, 'a'> trie; などとして構築
// void insert(str word);              文字列の挿入
// bool search(str word);              指定した文字列そのものがあるか
// bool search_prefix(str prefix);     指定したprefixを持つ文字列があるか
// int word_count();                   挿入した単語の数
// int node_count();                   頂点の総数（根を含む）
// accept 変数を使えば、条件に沿う文字列が「いくつあるか」への変更は容易と思われる
template <int char_size, int base>
struct Trie {
  struct Node { // 頂点の構造体を定義
    vector<int> next;   // 子の頂点番号を格納。存在しなければ-1
                        // next[c] := 次の文字が c となる子頂点の頂点番号
    vector<int> accept; // 末端がこの頂点になる文字列の str_id を保存
                        // str_id := その文字列が何番目に入ったか(0-indexed)
    int c;              // base からの間隔をint型で表現したもの
    int common;         // いくつの文字列がこの頂点を共有しているか（根は全員が共有）
    Node(int c_) : c(c_), common(0) { // <- なぜ0で生成？ 1では？
      next.assign(char_size, -1); // 生成時は子がいないので、next[全文字種] = -1
    }
  };
  vector<Node> nodes;  // trie 木本体
  int root; // 根（の頂点番号か？ と思いきや、Node(root)としているから、頂点の文字種になっちゃってないか？ どういうこと？）
  Trie() : root(0) {
    // 初期化。はじめは根しか無い
    nodes.push_back(Node(root)); // rootノード.cが0とはどういうことか？ 文字種'a'ってことになっちゃわないか？
  }

  // 単語を追加 ※使う時は、void insert(const string &word) の方を使う
  void insert(const string &word, int word_id) { // 単語:str と 単語の番号: str_id
    int node_id = 0;  // 今見ている頂点番号 最初は根(0)
    // 今の頂点から、次の頂点（子）を探す
    // 深さ1辿るごとに必ず1文字進むので、文字数と同じ回数ループすれば良い
    for (int i = 0; i < (int)word.size(); i++) {
      int c = (int)(word[i] - base);  // i文字目(0-indexed)を探す
      // 今の頂点の子の中で、次に文字種cが来る頂点番号（-1なら更新したいので参照渡し）
      int &next_id = nodes[node_id].next[c];
      if (next_id == -1) {            // 次の頂点が存在しなければ追加
        next_id = (int)nodes.size();  // 現在ある頂点数 = 新しい頂点の頂点番号
        nodes.push_back(Node(c));     // 文字種 c の頂点を追加
      }
      ++nodes[node_id].common;        // 今の頂点を共有する文字列を1つ増やす
      node_id = next_id;              // 次の頂点（子）に移動
    }
    // 最後の頂点（最後の文字）の処理を忘れずに行う
    ++nodes[node_id].common;
    nodes[node_id].accept.push_back(word_id); // 単語の終端なので、頂点に番号を入れておく
  }
  void insert(const string &word) {
    insert(word, nodes[0].common); // 根を共有する文字列の数 = 挿入済みの文字列数 = str_id
  }

  // 単語 もしくは prefixの検索
  // 第二引数として 今回見始めるのは何文字目（0-indexed）からかを渡す
  vector<int> search(const string &word, int s_idx) {
    vector<int> res; // 見つけた単語のstr_id
    int node_id = 0;        // 今見ている頂点番号 最初は根(0)
    // 今の頂点から、次の頂点（子）を探す
    // 深さ1辿るごとに必ず1文字進むので、文字数と同じ回数ループすれば良い
    for (int i = s_idx; i < (int)word.size(); i++) {
      int c = (int)(word[i] - base);
      int &next_id = nodes[node_id].next[c];
      if (next_id == -1) {  // 次の頂点が存在しなければ終了
        return res;
      }
      node_id = next_id;
      // ここで次の頂点に移っているので、ここで文字列が見つかったか判定する
      for (int id_found : nodes[node_id].accept) res.p_b(id_found);
    }
    return res;
  }

  // 挿入した単語の数
  int word_count() const {
      return (nodes[0].common);
  }

  // Trie木のノード数
  int node_count() const {
      return ((int)nodes.size());
  }

};


