void solve(){
    // generate_array(size, min, max);
    ll n; in1(n);
    vector<string> ss(n);
    rep(i, n) in1(ss[i]);
    sort(all(ss), [](string s1, string s2)->bool{
        return s1.length() < s2.length();
    });

    auto judge = [&](ll i, ll j) -> bool{
        ll mi = ss[i].length(), mj = ss[j].length();
        string si, sj;
        si = substring(ss[i], 1, mi - 1);
        sj = substring(ss[j], mj - mi + 1, mj - 1);
        if (si != sj) return false;
        rep(k, mj - mi + 1)
            if (ss[i][0] == ss[j][k])
                return true;
        return false;
    };

    ll ans = 0;
    rep(i, n - 1) For(j, i + 1, n)
        ans += judge(i, j);

    prl(ans);

