struct Trie{
    int nxt[MAXN][26] = {};
    short cnt[MAXN] = {};
    short cntp[MAXN] = {};
    short cntpc[MAXN][26] = {};
    int head = 1, tot = 1; // head is idx of head node, tot is the last allocated node

    int & __alloc() {
        cnt[++tot] = 0;
        memset(nxt[tot], 0, sizeof(nxt[tot]));
        return tot;
    }

    void clear() { tot = 0; head = __alloc(); }

    void insert(const string & s, int ub) {
        int n = s.size();
        dp[n] = vector<bool>(26);
        rrep(i,n-1,-1){
            dp[i]=dp[i+1];
            dp[i][s[i]-'a']=1;
        }
        print(s);
        // print(dp[0]);
        // print(dp[1]);
        // print(dp[2]);
        // print(dp[3]);

        int tmp = head;

        cntp[tmp]++;
        rep(j,0,26) if(dp[0][j]) cntpc[tmp][j]++;
        // printn(cntpc[tmp],26);

        for(int i = 0; i < s.size() && i <= ub; i++) {
            if(nxt[tmp][s[i] - 'a']) tmp = nxt[tmp][s[i] - 'a'];
            else tmp = nxt[tmp][s[i] - 'a'] = __alloc();

            cntp[tmp]++;
            rep(j,0,26) if(dp[i+1][j]) cntpc[tmp][j]++;
        }
        // print("visiting node ", tmp);
        cnt[tmp]++;
    }

    int count(const string & s) {
        int n=s.size();
        int res=0;

        int tmp = head;
        if(n==1) res+=cntpc[tmp][s.back() - 'a'];
        for(int i = 0; i < s.size(); i++) {
            if(!nxt[tmp][s[i] - 'a']) break;
            tmp = nxt[tmp][s[i] - 'a'];

            if(i==n-2) res+=cntpc[tmp][s.back() - 'a'];
            // else if(i==n-1) res+=cntp[tmp];

        }
        res+=cnt[tmp];
        return res;
    }
} trie;

