int solve(){
    ll n;
    cin>>n;
    Vs vs(n);
    cin>>vs;
    map<string,ll> sid;
    rep(i,n){
        string &t = vs[i];
        reverse(ALL(t));
        sid[t] = i;
    }
    dbgmap(sid);

    ll ans = 0;
    map<P,ll> mp;

    auto judge = [&](string sss,ll i){
        if(sid.count(sss)){
            ll j = sid[sss];
            ans++;
        }
    };

    rep(j,n){
        string &s = vs[j];
        ll len = s.length();
        string x;

        Vec L(26,INF);
        Vec R(26,0LL);

        rep(i,len){
            ll c = s[i]-'a';
            chmin(L[c],i);
            chmax(R[c],i);
        }

        dbg(s)
        dbg(L)
        dbg(R)

        //1文字と後ろ
        rep(i, len){
            x += s[i];
            judge(x, j);

            rep(k,26){
                if(i<R[k]){
                    char c = 'a'+k;
                    judge(x+c, j);
                }
            }
        }

        //1文字だけ
        rep(i, len){
            string tmp;
            tmp += s[i];
            judge(tmp,j);
        }

        if(len<2) continue;

        //2文字だけ
        rep(i,26){
            rep(k,26){
                if(L[i]<R[k]){
                    char c = 'a'+i;
                    char d = 'a'+j;
                    string tmp;
                    tmp += c;
                    tmp += d;
                    judge(tmp,j);
                }
            }
        }

    }
    dbgmap(mp);
    out(mp.size());
    return  0;
}

