int ls[30];
string str[M];

typedef struct node{
	node* nxt[26];
	int dp[26];
}node;

node* nnode()
{
	node* tmp = new node;
	for(int i=0;i<26;++i)
	{
		tmp->nxt[i] = NULL;
		tmp->dp[i] = 0;
	}
	return tmp;
}

node* insert(node* root,string ar)
{
	node* cur = root;
	int n = ar.size();

	for(int j=0;j<26;++j)
		ls[j] = -1;

	for(int i=0;i<n;++i)
		ls[ar[i]-'a'] = i;

	for(int i=0;i<n;++i)
	{
		for(int j=0;j<26;++j)
		{
			if(ls[j] >= i)
				cur->dp[j]++;
		}
		if(cur->nxt[ar[i]-'a']==NULL)
		{
			node* tmp=nnode();
			cur->nxt[ar[i]-'a']=tmp;
			cur=cur->nxt[ar[i]-'a'];
		}
		else
			cur=cur->nxt[ar[i]-'a'];
	}
	return root;
}

int search(node* root,string ar)
{
	node* cur=root;
	int n = ar.size();

	for(int i=0;i<n-1;++i)
		cur=cur->nxt[ar[i]-'a'];

	return cur->dp[ar[n-1]-'a']-1;
}	

