const int maxn=2e5+10,maxl=2e5+10;
struct node
{
	int ch[30],fa,f;
	int v[30];
}tree[maxn];
string s[maxl];
int dan[30];bool bos[30];
int t,n,m,num,ans;
int q[maxn],head,tail;

void ins(string st)
{
	int j=0;
	for (int i=0;;i++)
	{
		if (!st[i]) break;
		if (!tree[j].ch[st[i]-96]) tree[j].ch[st[i]-96]=++num,tree[num].fa=j;
		j=tree[j].ch[st[i]-96];
	}
	bool bo[30];
	for (int i=1;i<=26;i++) bo[i]=0;
	int k=st.length()-1;
	for (;j;j=tree[j].fa)
	{
		bo[st[k]-96]=1;
		for (int i=1;i<=26;i++) tree[j].v[i]+=bo[i]; 
		k--;
	}
}

void buildtree()
{
	head=tail=0;
	for (int i=1;i<=26;i++) q[tail++]=tree[0].ch[i];
	while (head<tail)
	{
		int k=q[head++];
		for (int i=1;i<=26;i++)
			if (tree[k].ch[i])
			{
				int j=tree[k].f;
				while (!tree[j].ch[i]) j=tree[j].f;
				tree[tree[k].ch[i]].f=tree[j].ch[i];
				q[tail++]=tree[k].ch[i];
			}
	}
}

void match(string st)
{
	for (int i=0,j=0;st[i];i++)
	{
		while (!tree[j].ch[st[i]-96]) j=tree[j].f;
		j=tree[j].ch[st[i]-96];
		if (i==st.length()-2) {ans+=tree[j].v[st[i+1]-96];break;}
	}
}
