		for (int j=0;j<s[i].length();j++) bos[s[i][j]-96]=1;
		for (int j=1;j<=26;j++)
			if (bos[j]) dan[j]++;
	}
	buildtree();
	for (int i=1;i<=n;i++)
	{
		if (s[i].length()==1) ans+=dan[s[i][0]-96];
		else match(s[i]);
