void Insert(string s){
    int p=0,len=s.size();
    for (int i=len-1;i>=0;i--){
        int r=s[i]-'a';
        if(T[p].next[r]==-1){
            T[le].init();
            T[le].type=r;
            T[p].next[r]=le++;
        }
        p=T[p].next[r];
        T[p].cnt++;  
    }
	val[p]++;
}
void dfs(int x){
	for(int i=0,v;i<26;i++){
		v=T[x].next[i];
		if(v<=0) continue;
		dfs(v);
		val[x]+=val[v];
		for(int j=0;j<26;j++){
			dp[x][j]+=dp[v][j];
		}
	}
	dp[x][T[x].type]=val[x];
}
