#define N (1<<18)
class SegmentTree{
	public:
	vector<int> dat[2*N];
	void push(int i,int x){
		i+=N;
		while(i>0){
			dat[i].push_back(x);
			i/=2;
		}
	}
	void init(){
		rep(i,2*N)sort(all(dat[i]));
	}
	int cnt(int k,int x){
		return dat[k].size()-(lower_bound(all(dat[k]),x)-dat[k].begin());
	}
	int query(int l,int r,int x){//[l,r]
		l+=N,r+=N+1;
		int ans=0;
		for(;l<r;l>>=1,r>>=1){
			if(l&1)ans+=cnt(l,x),l++;
			if(r&1)r--,ans+=cnt(r,x);
		}
		return ans;
	}
};
SegmentTree seg[26];
