		reverse(all(s[i]));
	}
	sort(s,s+n);
	int cha[26];
	rep(i,26)cha[i]=0;
	rep(i,n){
		bool vis[26];
		rep(j,26)vis[j]=0;
		for(int j=s[i].size()-1;j>=0;j--){
			if(vis[s[i][j]-'a'])continue;
			vis[s[i][j]-'a']=1;
			seg[s[i][j]-'a'].push(i,j);
		}
		rep(j,26)cha[j]+=vis[j];
	}
	rep(i,26)seg[i].init();
	ll ans=0;
	rep(i,n){
		if(s[i].size()==1){
			ans+=cha[s[i][0]-'a']-1;
			continue;
		}
		string t=s[i];
		t.pop_back();
		ll l,r,mid;
		l=-1,r=n;
		while(l<r-1){
			mid=(l+r)>>1;
			if(t<=s[mid])r=mid;
			else l=mid;
		}
		ll L=r;
		t.push_back('z'+1);
		l=-1,r=n;
		while(l<r-1){
			mid=(l+r)>>1;
			if(s[mid]<t)l=mid;
			else r=mid;
		}
		ll R=l;
		t.back()=s[i].back();
		ans+=seg[t.back()-'a'].query(L,R,t.size()-1)-1;
	}
	cout<<ans<<endl;
}

