pair<ll, vector<count_t>> traverse_count(Node &node){
    node.num_child = node.leaf.size();
    auto node_count = vector<count_t>(26);
    ll ret = 0;
    for(auto &child_node: node.child){
        const auto child_node_count = traverse_count(child_node.second);
        for(auto i=0; i<26; ++i){
            node_count[i] += child_node_count.second[i];
        }
        node.num_child += child_node.second.num_child;
        ret += child_node_count.first;
        for(const auto &c: node.leaf){
            ret += child_node_count.second[c-'a'];
        }
    }
    node_count[node.c - 'a'] = node.num_child;
    for (const auto &c: node.leaf){
        if (c != node.c) node_count[c - 'a']++;
    }
    return {ret, node_count};
}

