const int pw = 31, mod = 1e9 + 7;
const int N = 1e6 + 1;

map<int, int> mp[N];

int solve(const vector<string> &v) {
	for (int i = 0; i < N; ++i) mp[i].clear();
	int ans = 0;
	for (string s : v) {
		int n = s.size();
		int cnt[26] = {0};
		for (char c : s) {
			cnt[c - 'a']++;
		}
		int hash = 0;
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < 26; ++j) {
				int curhash = hash * pw + (j + 1);
				curhash %= mod;
				if (cnt[j] and mp[i + 1].count(curhash)) {
					ans += mp[i + 1][curhash];
				}
			}
			--cnt[s[n - i - 1] - 'a'];
			hash = hash * pw + (s[n - i - 1] - 'a') + 1;
			hash %= mod;
		}
		++mp[n][hash];
	}
	return ans;
}

