            v = g[v][s[i][e] - 'a'];
            cur.pb(v);
        }
        cnt[v]++;
        for (int j = 0; j < 26; j++)
            used[j] = 0;
        for (int e = (int)s[i].size() - 1; e >= 0; e--)
        {
            if (!used[s[i][e] - 'a'])
            {
                dp[cur[e]][s[i][e] - 'a']++;
