		S[1LL * h0[i] * mo1 + h1[i]] ++;
	}
	ll ans = 0;
	rep(i, n) {
		int cnt[26]; memset(cnt, 0, sizeof(cnt));
		rep(j, ln[i]) {
			cnt[s[bg[i] + j] - 'a'] ++;
			int rs = ln[i] - j - 1;
			int rh0 = rs ? hs0[bg[i] + j + 1] : 0;
			int rh1 = rs ? hs1[bg[i] + j + 1] : 0;
			if (!hav[rs + 1]) continue;
			rep(c, 26) if (cnt[c]) {
				int nh0 = (1LL * (c + 'a') * pw0[rs] + rh0) % mo0;
				int nh1 = (1LL * (c + 'a') * pw1[rs] + rh1) % mo1;
				if (j) ans += S[1LL * nh0 * mo1 + nh1];
			}
		}
	}
	printf("%lld\n", ans);
	return 0;
}

