struct hashInt {
	int a, b;
	hashInt()
		: a(0)
		, b(0) {}
	hashInt(int a, int b) {
		this->a = (a + MOD1) % MOD1;
		this->b = (b + MOD2) % MOD2;
	}
	hashInt(ll a, ll b) {
		this->a = (a + MOD1) % MOD1;
		this->b = (b + MOD2) % MOD2;
	}
};

hashInt operator+(const hashInt &a, const hashInt &b) {
	return hashInt(a.a + b.a, a.b + b.b);
}

hashInt operator*(const hashInt &a, const hashInt &b) {
	return hashInt(1LL * a.a * b.a, 1LL * a.b * b.b);
}

bool operator<(const hashInt &a, const hashInt &b) {
	return make_pair(a.a, a.b) < make_pair(b.a, b.b);
}

