bool check(string &s, string &t) {
    rep(i, min(s.size(), t.size())) {
        if (s[i] != t[i]) {
            return s[i] < t[i];
        }
    }
    return s.size() > t.size();
}

int bisect_right(vector<string> &s, string target) {
    int l = 0;
    int r = s.size();
    while (r-l > 1) {
        int mid = (l+r)/2;
        if (check(s[mid], target)){
            l = mid;
        }
        else {
            r = mid;
        }
    }

    return r;
}

