		for (int j = 0; j < 26; ++j)
			if (count[j] != 0)
				++one[j];

		int depth = 0;
		fix([&](auto&& f, std::unique_ptr<Node>& ptr) -> void {
			if (ptr == nullptr)
				ptr = std::make_unique<Node>();

			if (depth + 2 == s.size())
				++ptr->count[s[0] - 'a'];
			else {
				--count[*(s.rbegin() + depth) - 'a'];
				for (int j = 0; j < 26; ++j)
					if (count[j] != 0)
						++ptr->count[j];

				++depth;
				f(f, ptr->children[*(s.rbegin() + depth) - 'a']);
			}
		})(roots[s.back() - 'a']);
	}

	for (auto&& s : input) {
		if (s.size() == 1) {
			ans += one[s[0] - 'a'] - 1;
			continue;
		}

		int depth = 0;
		fix([&](auto&& f, const std::unique_ptr<Node>& ptr) -> void {
			if (ptr == nullptr)
				exit(1);

			if (depth + 2 == s.size())
				ans += ptr->count[s[0] - 'a'] - 1;
			else {
				++depth;
				f(f, ptr->children[*(s.rbegin() + depth) - 'a']);
			}
		})(roots[s.back() - 'a']);
	}

	std::cout << ans << std::endl;
}

