typedef long long ll;
const int maxn=200050;
const int maxlen=1000050;
const int maxc=30;
vector<char> v[maxn];
int ch[maxlen][26],sum[maxlen][26];
int pos[maxn],stk[maxlen],_id[maxlen];
char s[maxlen];
bool beused[maxc];
int n,tot;

int cmp(int a,int b){
	return v[a].size()>v[b].size();
}
void solve(){
	scanf("%d",&n);
	for(int i=1;i<=n;i++){
		scanf("%s",s);
		int len_s=strlen(s);
		reverse(s,s+len_s);
		for(int j=0;j<len_s;j++)	v[i].push_back(s[j]);
		pos[i]=i;
	}
	sort(pos+1,pos+n+1,cmp);
	ll res=0;
	for(int i=1;i<=n;i++){
		int u=0,now=0,id=0;
		for(auto x:v[pos[i]]){
			id=x-'a';
			if(!ch[u][id])	ch[u][id]=++tot;
			stk[++now]=u;_id[now]=id;
			u=ch[u][id];
		}
		res+=sum[stk[now]][id];
		memset(beused,0,sizeof(beused));
		for(int j=now;j>=1;j--){
			beused[_id[j]]=1;
			for(int k=0;k<26;k++)	sum[stk[j]][k]+=beused[k];
		}
	}
	printf("%lld\n",res);
}
int main(){
	solve();
	return 0;
}

