namespace TRIE {

struct Node;
Node* new_node(char c);

struct Node {
    char c; // character from parent;
    int val;
    Node *left, *right;

    Node* lookup(char alpha, bool add, bool move_to_front) {
	Node *ch = left, *prv = 0;
	while (ch) {
	    if (ch->c == alpha) {
		if (move_to_front && prv) {
		    prv->right = ch->right;
		    ch->right = left;
		    left = ch;
		}
		return ch;
	    }
	    prv = ch;
	    ch = ch->right;
	}
	if (add) {
	    // push front;
	    ch = new_node(alpha);
	    ch->right = left;
	    left = ch;
	}
	return ch;
    }
};

const int NODES = 1000011;
int node_i;
Node nodes[NODES];

void clear() {
    node_i = 0;
}

Node* new_node(char c) {
    Node *x = nodes + node_i;
    node_i++;
    x->c = c;
    x->val = 0;
    x->left = x->right = 0;
    return x;
}

Node* new_root() {
    return new_node(0);
}

void add(Node *root, const string &s, LL num) {
    Node *x = root;
    // x->sum += num;
    REP (i, s.size()) {
	x = x->lookup(s[i], true, true);
	// x->sum += num;
    }
    x->val += num;
}


