struct ByLen {
    bool operator()(const string &s, const string &t) const {
	return s.size() != t.size() ? s.size() < t.size()
	    : s < t;
    }
} byLen;

int C[26];

void MAIN() {
    scanf("%d", &N);
    REP (i, N) {
	scanf("%s", buf);
	S[i] = buf;
	reverse(S[i].begin(), S[i].end());
    }

    sort(S, S+N, byLen);
    Node *root = new_root();

    LL ans = 0;
    REP (i, N) {
	const string &s = S[i];
	memset(C, 0, sizeof C);
	REP (j, s.size()) C[s[j]-'a']++;

	Node *x = root;
	LL tmp = 0;
	tmp += x->val;
	REP (j, s.size()) {
	    Node *y = x->left;
	    while (y) {
		// eprintf("%s %c\n", s.c_str(), y->c);
		if (C[y->c-'a']) tmp += y->val;
		y = y->right;
	    }

	    char c = s[j];
	    C[c-'a']--;
	    x = x->lookup(c, false, true);
	    if (!x) break;
	}

	add(root, s, 1);
	ans += tmp;
    }

    printf("%lld\n", ans);
}

