char s[1000001];
long long ans = 0;

struct node {
    bool last;
    int count[26];
    node* child[26];
};

node* create() {
    int i;
    node* n = new node();

    n->last = false;
    for (i = 0; i < 26; i++) n->count[i] = 0;
    for (i = 0; i < 26; i++) n->child[i] = NULL;

    return n;
}

int add(node* now, int x) {
    if (x == -1) {
        now->last = true;
        return 0;
    } else {
        int c = s[x] - 'a', p, i;

        if (now->child[c] == NULL) now->child[c] = create();

        p = add(now->child[c], x - 1) | (1 << c);

        for (i = 0; i < 26; i++) {
            if ((p >> i) & 1) now->count[i]++;
        }

        return p;
    }
}

void dfs(node* now) {
    int i, j;

    for (i = 0; i < 26; i++) {
        if (now->child[i] != NULL && now->child[i]->last) ans += now->count[i] - 1;
    }

    for (i = 0; i < 26; i++) {
        if (now->child[i] != NULL) dfs(now->child[i]);
    }
}

int main() {
    int n, i;
    node* top = create();

    scanf("%d", &n);

    for (i = 0; i < n; i++) {
        int m;

        scanf("%s", s);

        m = strlen(s);

        add(top, m - 1);
    }

    dfs(top);

    printf("%lld\n", ans);

    return 0;
}

