main() {
    INT(n);
    unordered_map<ll, int> mp;
    vector<string> s(n);
    rep(i, n) cin >> s[i], reverse(all(s[i]));
    sort(all(s), [&](string &l, string &r) { return size(l) < size(r); });
    ll ans = 0;
    rep(i, n) {
        RollingHash rh(s[i]);
        int mask = 0;
        rep3(j, size(s[i]) - 1, 0) {
            mask |= 1 << (s[i][j] - 'a');
            ans += popcount(mask & mp[rh.get(0, j)]);
        }
        mp[rh.get(0, size(s[i]) - 1)] += 1 << (s[i].back() - 'a');
    }
    cout << ans << endl;
}

