}
int qq(string &s){
    int ret=0;
    int now=0;
    int AA[26]={};
    REP(i,SZ(s)){
        if(now!=-1){
            REP(j,26)AA[j]+=cc[now][j];
        }
        ret+=AA[s[i]-'a'];
        AA[s[i]-'a']=0;
        if(now!=-1&&nxt[now][s[i]-'a']){
            now=nxt[now][s[i]-'a'];
        } else now=-1;
    }
    return ret;
}
