struct TRIE {
	static const int Alpha = 26;
	struct node {
		char ch;
		int cntend;
		int par;
		int child[Alpha];

		node() {
			ch = '#', cntend = 0, par = -1;
			memset(child, -1, sizeof(child));
		}
		node(char _ch) {
			ch = _ch, cntend = 0, par = -1;
			memset(child, -1, sizeof(child));
		}
	};

	vector<node> tree;

	TRIE() {
		tree.push_back(node());
	}

	void insert(string s) {
		int cur = 0;
		for(char ch : s) {
			assert(cur < sz(tree));
			if(tree[cur].child[ch - 'a'] == -1) {
				tree[cur].child[ch - 'a'] = sz(tree);
				tree.push_back(*(new node(ch)));
			}
			int to = tree[cur].child[ch - 'a'];
			tree[to].par = cur;
			cur = to;
		}
		assert(cur < sz(tree));
		tree[cur].cntend++;
	}

	bool check(string s) {
		int cur = 0;
		for(char ch : s) {
			if(tree[cur].child[ch - 'a'] == -1) return false;
			cur = tree[cur].child[ch - 'a'];
		}
		return tree[cur].cntend > 0;
	}

	int count() {
		int ans = 0;
		for(int i = 1; i < sz(tree); i++) {
			if(tree[i].cntend == 0) continue;
			int res = 0;
			set<char> st{tree[i].ch};
			int cur = tree[i].par;
			while(cur != -1) {
				for(char ch : st) {
					int to = tree[cur].child[ch - 'a'];
					if(to != -1 and to != i and tree[to].cntend > 0) {
						res += tree[i].cntend * tree[to].cntend;
					}
				}
				st.insert(tree[cur].ch);
				cur = tree[cur].par;
			}
			ans += res;
		}
		return ans;
	}

};

