ll powmod(ll a, ll b, ll mod)
{
    a %= mod;assert(b >= 0);
    ll res = 1;
    for(;b;b>>=1)
    {
        if(b&1) res = (res * a) % mod;
        a = (a * a) % mod;
    }
    return res;
}

