struct Trie{
	Trie *po[26];
	vector <ll> v;
	ll cnt = 0;
};
Trie* newNode()
{
	Trie* node = new Trie();
	node -> cnt = 0;
	node -> v.resize(26); 
	for(int i = 0; i < 26; i++) {
		node -> po[i] = NULL;
		node -> v[i] = 0;
	}
	return node;
}
void insert(Trie *root, string &s, int ind, vector<vector <int> > &w)
{
	if(ind == s.size()) return;
	int x = s[ind] - 'a';

	if(root -> po[x] == NULL) root -> po[x] = newNode();
	root -> po[x] -> cnt++;
	for(int i = 0; i < 26; i++)
	root -> po[x] -> v[i] += (w[ind][i] > 0);

	insert(root -> po[x], s, ind + 1, w);
}

ll qry1(Trie *root, string &s, int ind)
{
	if(ind == s.size()) return root -> cnt;

	int x = s[ind] - 'a';
	if(root -> po[x] == NULL) return 0;
	qry1(root -> po[x], s, ind + 1);
}

ll qry2(Trie *root, string &s, int ind, int req)
{
	if(ind == s.size() - 1) return root -> v[req];

	int x = s[ind] - 'a';
	if(root -> po[x] == NULL) return 0;
	qry2(root -> po[x], s, ind + 1, req);
}

