void solve(){
    cin >> n;
    for(int i=0;i<n;i++){
        cin >> tableee[i].second;
        tableee[i].first = tableee[i].second.size();
        exist[tableee[i].first] = true;
        cexist[tableee[i].first][tableee[i].second.front() - 'a'] = true;
    }
    sort(tableee, tableee + n);
    for(int i=0;i<n;i++){
        string s;
        s = tableee[n-1-i].second;
        reverse(s.begin(), s.end());
        int mylen = s.size() - 1;
        ll ret = 0;
        rets.clear();
        for(int j=0;j<s.size();j++){
            ret *= mykake;
            ret += s[j] - 'a' + 25;
            ret %= mymod;
            rets.pb(ret);
        }
        ans += st[s];
        table.clear();
        for(int j=0;j<26;j++){
            table.pb(-INF);
        }
        for(int j=0;j<s.size();j++){
            table[s[j] - 'a'] = max(table[s[j] - 'a'], (ll)j);
        }
        for(int k=0;k<26;k++){
            string t = "";
            t += (char)('a' + k);
            if (table[k] != -INF) st[t] ++;
        }
        for(int j=0;j<s.size();j++){
            ret = rets[j];
            if (!exist[j + 2]) continue;
            ll idx = ret * 26;
            for(int k=0;k<26;k++){
                if (table[k] != -INF && cexist[j + 2][k] && table[k] >= j + 1) st[s.substr(0, j+1) + (char)(k+'a')]++;
                idx++;
            }
        }
    }
    p(ans);
    return;
}

