template <class T>
vector<T> SLICE(vector<T>& v, int first, int last, int step) {
    int n = (int)v.size(), now = first;
    vector<T> ret;
    if (first < 0 || n <= last) { return {}; }
    if (step * (last - first) <= 0) { return {}; }
    if (step > 0) {
        while (first <= now && now < last) {
            ret.push_back(v[now]);
            now += step;
        }
    } else {
        while (first >= now && now > last) {
            ret.push_back(v[now]);
            now += step;
        }
    }
    return ret;
}
template <class T, class S, class R>
long long pow(T n_0, S k_0, R mod_0) {
    long long n = n_0;
    long long k = k_0;
    long long mod = mod_0;
    long long now = 1;
    while (true) {
        if (k & 1) { now = now * n % mod; }
        k >>= 1;
        if (k == 0) { return now; }
        n = (n * n) % mod;
    }
}
