        if(nidx >= (int)nodes.size()){
            nodes.push_back({});
        }
        auto& dests = nodes[nidx].dests;
        nodes[nidx].ch = sidx >= 0 ? s[sidx] : 0;
        nodes[nidx].parentIdx = pidx;

        if(!nodes[nidx].isRoot()){
            azs[nodes[nidx].ch - 'a']--;
            for(int i = 0; i < 27; i++){
                nodes[nidx].nums[i] += azs[i] > 0;
            }
        }
        // printde(nodes[nidx].ch, nodes[nidx].nums);

		if(sidx + 1 == (int)s.size()){ nodes[nidx].leaf = true; return; }
		char next = s[sidx + 1];
		if(!dests.count(next)){
            dests[next] = nodes.size();
            add(s, azs, sidx + 1, nodes.size(), nidx);
		}else{
            add(s, azs, sidx + 1, dests[next], nidx);
        }
        printde(nodes[nidx].ch);
        // printde(nodes[nidx].ch, nodes[nidx].dests);
    }

    ll calc(int nidx = 0){
        ll ret = 0;
        printde(nodes[nidx].ch, nodes[nidx].dests);
        if(nodes[nidx].leaf){
            ret = nodes[nodes[nidx].parentIdx].nums[nodes[nidx].ch - 'a'] - 1;
            // printde(nodes[nidx].ch, ret, nodes[nodes[nidx].parentIdx].ch, nodes[nodes[nidx].parentIdx].nums[nodes[nidx].ch - 'a']);
        }
        for(auto& dest : nodes[nidx].dests){
            ret += calc(dest.second);
        }
        return ret;
    }
};

