void add(const string &s)
{
    int i, j;

    memset(last, -1, sizeof(last));
    for(i=0; i<s.size(); ++i)
        last[s[i] - 'a'] = i;

    int key1 = 0, key2 = 0;

    for(i=0; i<s.size(); ++i)
    {
        for(j=0; j<26; ++j)
            if(last[j] >= i)
                hsh[j][{ key1, key2 }] ++;

        key1 = (ll) (key1 * base1 + (s[i] - 'a' + 1)) % Mod;
        key2 = (ll) (key2 * base2 + (s[i] - 'a' + 1)) % Mod;
    }
}

int query(char c, const string &s)
{
    int key1 = 0, key2 = 0, i;

    for(i=0; i<s.size(); ++i)
    {
        key1 = (ll) (key1 * base1 + (s[i] - 'a' + 1)) % Mod;
        key2 = (ll) (key2 * base2 + (s[i] - 'a' + 1)) % Mod;
    }

    return hsh[c - 'a'][{ key1, key2 }];
}

