vector<int> tree_dist(vector<vector<int>>& g, int start) {
    int n = (int)g.size(), u, v, inf = pow(10, 9);
    vector<int> q(1, start);
    vector<int> dist(n, inf);
    dist[start] = 0;
    while (q.size()) {
        u = q.back();
        q.pop_back();
        for (int temp : g[u]) {
            v = temp;
            if (dist[v] == inf) {
                q.push_back(v);
                dist[v] = dist[u] + 1;
            }
        }
    }
    return dist;
}

template <class T>
vector<int> argsort(vector<T>& seq, bool reverse = false) {
    int sz = (int)seq.size();
    vector<tuple<T, int>> seq2(sz);
    for (int i = 0; i < sz; i++) { seq2[i] = make_tuple(seq[i], i); }
    if (reverse == false) {
        sort(seq2.begin(), seq2.end(), [](const auto& x, const auto& y) {
            return get<0>(x) < get<0>(y);
        });
    } else {
        sort(seq2.begin(), seq2.end(), [](const auto& x, const auto& y) {
            return get<0>(x) > get<0>(y);
        });
    }
    vector<int> ret(sz);
    for (int i = 0; i < sz; i++) { ret[i] = get<1>(seq2[i]); }
    return ret;
}

