		ptr.resize(26);
		rep(i,26)
			ptr[i] = NULL;
		fre.resize(26, 0);
	}
};
void Insert(TrieNode* root, str s)
{
	int n = s.length();

	rloop(i,n-1,1,1)
	{
		int c = s[i]-'a';
		if(root->ptr[c])
