int main(){
  int N;
  cin >> N;
  vector<vector<int>> G(1,vector<int>(26,-1));
  vector<vector<int>> C(1,vector<int>(26,0));

  auto add = [&](const string& s){
               int v = 0;
               vector<int> cnt(26);
               for(auto cc : s){
                 ++cnt[cc-'a'];
               }
               for(auto cc : s){
                 for(int i = 0; i < 26; ++i){
                   if(cnt[i] > 0) ++C[v][i];
                 }

                 int c = cc-'a';
                 --cnt[c];
                 if(G[v][c] < 0){
                   int v_ = G.size();
                   G[v][c] = v_;
                   G.push_back(vector<int>(26,-1));
                   C.push_back(vector<int>(26,0));
                 }
                 v = G[v][c];
               }
             };

  auto solve = [&](const string& s){
                 int v = 0;
                 for(size_t i = 0; i+1 < s.length(); ++i){
                   int c = s[i] - 'a';
                   v = G[v][c];
                 }
                 return C[v][s.back()-'a'];
               };

  vector<string> S(N);
  for(int i = 0; i < N; ++i){
    cin >> S[i];
    reverse(S[i].begin(), S[i].end());
    add(S[i]);
  }
  long long ans = 0;
  for(auto s : S){
    // cerr << s << endl;
    // cerr << solve(s) << endl;
    ans += solve(s);
  }
  ans -= N;
  cout << ans << endl;
}

