int N;
vector<string> S;
unordered_map<int,vector<pair<string,char> > >  chkL;
unordered_map<int,bool> chk;
void input(){
    fast_io();
    cin >> N;
    for (int i = 0; i < N; i++)
    {
        string t; cin >> t;
        S.push_back(t);
        chkL[t.length()-1].emplace_back(t.substr(1),t[0]);
        chk[t.length()] = true;
    }
}

int solve(){
    for(auto &[l,v]:chkL) {
        sort(v.begin(),v.end());
    }
    ll ans = 0LL;
    auto cmp = [](string a, string b){return a.length()>b.length();};
    sort(S.begin(),S.end(),cmp);
    for (int i = 0; i < N; i++)
    {
        string T = S[i];
        int L = T.length();
        if(L==1) break;

        vector<bool> Head(30,false);
        Head[T[0]-'a'] = true;
        T = T.substr(1);
        L--;

        while(L>0)
        {
            Head[T[0]-'a'] = true;
            T = T.substr(1);
            L--;
            if(!chk[L+1]) continue;
            if(chkL[L].empty()) continue;
            auto itr = lower_bound(chkL[L].begin(),chkL[L].end(),make_pair(T,'a'));
            while(itr->first==T){
                if(Head[itr->second-'a']) ans++;
                itr++;
            }
        }
    }
    cout << (ans) << endl;
    return 0;
}   

int main()
{
    input();
    solve();
    return 0;
}

