constexpr int N = 1000001;
struct RollingHash {
    unsigned h1[N], h2[N], p1[N], p2[N];
    const unsigned mod1 = 1000000007, mod2 = 998244353;
    unsigned b1, b2;
    inline unsigned mul1(unsigned a, unsigned b) const {
        unsigned long long x = (unsigned long long)a * b;
        unsigned xh = (unsigned)(x >> 32), xl = (unsigned)x, d, m;
        asm("divl %4; \n\t" : "=a"(d), "=d"(m) : "d"(xh), "a"(xl), "r"(mod1));
        return m;
    }
    inline unsigned mul2(unsigned a, unsigned b) const {
        unsigned long long x = (unsigned long long)a * b;
        unsigned xh = (unsigned)(x >> 32), xl = (unsigned)x, d, m;
        asm("divl %4; \n\t" : "=a"(d), "=d"(m) : "d"(xh), "a"(xl), "r"(mod2));
        return m;
    }

    RollingHash(const string &s) : b1(rnd(100000)), b2(rnd(100000)) {
        int sz = (int)s.size();
        h1[0] = h2[0] = 0;
        p1[0] = p2[0] = 1;
        for(int i = 0; i < sz; i++) {
            h1[i + 1] = mul1(h1[i], b1) + s[i], p1[i + 1] = mul1(p1[i], b1);
            h2[i + 1] = mul2(h2[i], b2) + s[i], p2[i + 1] = mul2(p2[i], b2);
            if(h1[i + 1] >= mod1) h1[i + 1] -= mod1;
            if(h2[i + 1] >= mod2) h2[i + 1] -= mod2;
        }
    }

    unsigned long long int get(int l, int r) const {
        unsigned r1 = h1[r] + mod1 - mul1(h1[l], p1[r - l]);
        unsigned r2 = h2[r] + mod2 - mul2(h2[l], p2[r - l]);
        if(r1 >= mod1) r1 -= mod1;
        if(r2 >= mod2) r2 -= mod2;
        return (unsigned long long int)r2 * mod1 + r1;
    }

    unsigned long long int connect(unsigned long long int h1, unsigned long long int h2, int h2len) const {
        unsigned long long int r1 = mul1(h1 % mod1, p1[h2len]) + h2 % mod1;
        unsigned long long int r2 = mul2(h1 / mod1, p2[h2len]) + h2 / mod2;
        if(r1 >= mod1) r1 -= mod1;
        if(r2 >= mod2) r2 -= mod2;
        return (unsigned long long int)r2 * mod1 + r1;
    }

    int LCP(const RollingHash &b, int l1, int r1, int l2, int r2) {
        int len = min(r1 - l1, r2 - l2);
        int low = -1, high = len + 1;
        while(high - low > 1) {
            int mid = (low + high) / 2;
            if(get(l1, l1 + mid) == b.get(l2, l2 + mid))
                low = mid;
            else
                high = mid;
        }
        return (low);
    }
    RollingHash() = default;
};

using u8 = unsigned char;
using u32 = unsigned int;
using u64 = unsigned long long int;
template <typename KeyT, typename ValT, typename Hash, ValT Z = ValT()> class hash_map {
    int n;
    u32 sz;
    std::vector<u64> s;
    std::vector<std::pair<KeyT, ValT>> v;
    Hash hash;
    static constexpr ValT nf = Z;

    bool test(u32 i, const std::vector<u64> &t) const { return !!(t[i / 64] & (1ULL << (i % 64))); }
    void set(u32 i, std::vector<u64> &t) { t[i / 64] |= 1ULL << (i % 64); }

    u32 find(const KeyT &a) const {
        u32 ind = hash(a, n);
        u32 i;
        for(i = ind; i < ind + (1 << n); ++i) {
            u32 j = i & ((1 << n) - 1);
            if(!test(j, s)) return j;
            if(v[j].first == a) return j;
        }
        return -1;
    }

    void reallocate() {
        ++n;
        std::vector<u64> t(1 << (n - 6));
        std::vector<std::pair<KeyT, ValT>> w(1 << n);
        for(u32 i = 0; i < v.size(); ++i) {
            if(!test(i, s)) continue;
            u32 j = hash(v[i].first, n);
            while(test(j, t)) ++j, j &= (1 << n) - 1;
            set(j, t);
            w[j] = v[i];
        }

        s.swap(t);
        v.swap(w);
    }

  public:
    hash_map() : n(10), sz(0), s(1 << (n - 6)), v(1 << n) {}

    ValT &operator[](const KeyT &a) {
        u32 i = find(a);
        if(v[i].first == a) return v[i].second;

        ++sz;
        if(sz + sz / 2 >= (1U << n)) {
            reallocate();
            i = find(a);
        }
        set(i, s);
        v[i].first = a;
        return v[i].second = Z;
    }

    const ValT &at(const KeyT &a) const {
        u32 i = find(a);
        return test(i, s) ? v[i].second : nf;
    }

    u32 size() const { return sz; }
};

struct hash_u64 {
    u32 operator()(u64 a, int n) const {
        static constexpr u64 r = 11995408973635179863ULL;
        return a * r >> (64 - n);
    }
};
template <const int sz = 5 * 10000000, typename T = long long> struct IO {
