const int ALPHABET_SIZE = 26; 

// trie node 
struct TrieNode 
{ 
    struct TrieNode *children[ALPHABET_SIZE]; 
  	int cnt[ALPHABET_SIZE];
    // isEndOfWord is true if the node represents 
    // end of a word 
    int isEndOfWord=0; 
    int count=0;
}; 

// Returns new trie node (initialized to NULLs) 
struct TrieNode *getNode(void) 
{ 
    struct TrieNode *pNode =  new TrieNode; 

    pNode->isEndOfWord = 0; 	
    for (int i = 0; i < ALPHABET_SIZE; i++) 
        pNode->children[i] = NULL,pNode->cnt[i]=0; 

    return pNode; 
} 

// If not present, inserts key into trie 
// If the key is prefix of trie node, just 
// marks leaf node 
void insert(struct TrieNode *root, string key) 
{ 
    struct TrieNode *pCrawl = root; 

    for (int i = 0; i < key.length(); i++) 
    { 
        int index = key[i] - 'a'; 
        if (!pCrawl->children[index]) 
            pCrawl->children[index] = getNode(); 

        pCrawl = pCrawl->children[index]; 
    } 

    // mark last node as leaf 
    pCrawl->isEndOfWord += 1; 
} 
using node = TrieNode;
void dfs(node* r)
{
	assert(r!=NULL);
	r->count=r->isEndOfWord;
	for(int i=0;i<26;++i)
	{
		if(r->children[i])
		{
			dfs(r->children[i]);
			r->count += r->children[i]->count;
			//for(int j=0;j<26;++j)
			//	r->cnt[j]+=r->children[i]->cnt[j];
		}
	}
	for(int j=0;j<26;++j)
	{
		if(r->children[j])
			r->cnt[j]+=r->children[j]->count;
		for(int k=0;k<26;++k)
		{
			if(j==k)continue;
			if(r->children[k])
					r->cnt[j]+=r->children[k]->cnt[j];
		}
	}
}

ll go_(node* root,string &s)
{
	char c=s.back();
	s.pop_back();
	int n=sz(s);
	node *temp=root;
	for(int i=0;i<n;++i)
	{
		int x = s[i]-'a';
		temp = temp->children[x];
	}
	return temp->cnt[c-'a'];
}

