typedef struct tnode{
	struct tnode*oya;
	struct tnode*ko[26];
	int a[26];
} trienode;

trienode*maketrienode(trienode*vv){
	trienode*v=malloc(sizeof(trienode));
	v->oya=vv;
	rep(i,0,26)v->ko[i]=0;
	rep(i,0,26)v->a[i]=0;
	return v;
}

int trieins(trienode*v,char*s){
	if(s[0]==0)return 0;
	if(! v->ko[s[0]-'a'])v->ko[s[0]-'a']=maketrienode(v);
	int ret=trieins(v->ko[s[0]-'a'],s+1);
	ret|=1<<(s[0]-'a');
	rep(i,0,26)if(bit(ret,i))v->a[i]++;
	return ret;
}

trienode*triesearch(trienode*v,char*s){
	if(s[0]==0)return v;
	if(! v->ko[s[0]-'a'])return 0;
	return triesearch(v->ko[s[0]-'a'],s+1);
}

