long long int rimac(const char *s1, const char *s2) {
	int i, j, k;
	const char *big, *small;
	(strlen(s1)-strlen(s2)>=0) ? (big=s1, small=s2) : (big=s2, small=s1);
	for (i=0; i<strlen(big)-strlen(small)+1; i++) {
		if (small[0] == big[i]) {
			for (j=i+1; j<strlen(big)-strlen(small)+2; j++) {
				if (small[1] == big[j]) {
					if (strcmp(&small[2], &big[j+1]) == 0) {
						return 1;
					}
				}
			}
		}
	}
	return 0;
}

int main(int argc, char **argv) {
	int i, j;
	int n;
	long long int count = 0;
	char **s;
	scanf("%d", &n);
	if ((s = (char **) calloc(n, sizeof(char *))) == NULL)
	{
		exit(1);
	}

	for (i=0; i<n; i++) {
		char buf[2000000];
		scanf("%s", buf);
		if ((s[i] = (char *)calloc(strlen(buf), sizeof(char)))
			== NULL) {
				exit(1);
		}
		strcpy(s[i], buf);	
	}

	for (i=0; i<n-1; i++) {
		for (j=i+1; j<n; j++) {
			count += rimac(s[i], s[j]);
		}
	}

	printf("%lld", count);
	return 0;
}

