fun main() { _writer.solve(); _writer.flush() }
fun PrintWriter.solve() {
//    val startTime = System.nanoTime()

    val numCases = 1//readInt()
    case@ for(case in 1..numCases) {
//        print("Case #$case: ")

        val n = readInt()
        val S = Array(n) { read() }

        val P = Array(n) { i ->
            val s = S[i]
            val res = Array(s.length) { BooleanArray(26) }
            for(j in s.indices) {
                if(j > 0) res[j-1].copyInto(res[j])
                res[j][s[j] - 'a'] = true
            }
            res
        }

        val conc = StringBuilder()
        val posInConc = IntArray(n)
        for(i in 0 until n) {
            posInConc[i] = conc.length
            conc.append(S[i]).append('$')
        }

        val (suff, lcp) = conc.suffixArrayAndLCP()

        val id = IntArray(suff.size)
        val pos = IntArray(suff.size)
        val sufflen = IntArray(suff.size)

        for(i in 1..suff.lastIndex) {
            id[i] = posInConc.bsIndexOfLast { suff[i] >= it }
            pos[i] = suff[i] - posInConc[id[i]]
            sufflen[i] = S[id[i]].length - pos[i]
        }

        var start = 1
        var ans = 0L

        while(start < suff.size) {
            var end = start
            while(end < lcp.size && lcp[end] > sufflen[end]) end++

            val cnt = IntArray(26)
            for(i in start..end) {
                if(pos[i] > 1) {
                    val p = P[id[i]][pos[i]-1]
                    for(j in 0 until 26) if(p[j]) cnt[j]++
                }
            }

            for(i in start..end) {
                if(pos[i] == 1) {
                    val c = S[id[i]][0]
                    ans += cnt[c - 'a']
                }
            }

            start = end + 1
        }

        println(ans)

    }

//    iprintln("Time: ${(System.nanoTime() - startTime) / 1000000} ms")
}

class IntList(initialCapacity: Int = 12) {
    private var _arr = IntArray(initialCapacity)
    private val capacity get() = _arr.size
    var size = 0
        private set
    inline val lastIndex get() = size - 1
    inline val indices get() = 0 until size

    constructor(copyFrom: IntArray): this(copyFrom.size) { copyFrom.copyInto(_arr); size = copyFrom.size }
    constructor(copyFrom: Collection<Int>): this(copyFrom.size) { _arr = copyFrom.toIntArray(); size = copyFrom.size }

    fun contentEquals(other: IntList): Boolean {
        return this === other || size == other.size && indices.all { this[it] == other[it] }
    }

    private fun grow(minCapacity: Int = 8) {
        val newCapacity = maxOf(minCapacity, capacity + (capacity shr 1))
        _arr = _arr.copyOf(newCapacity)
    }

    fun ensureCapacity(minCapacity: Int) { if(capacity < minCapacity) grow(minCapacity) }

    operator fun get(index: Int): Int {
        require(index in 0 until size)
        return _arr[index]
    }

    operator fun set(index: Int, value: Int) {
        require(index in 0 until size)
        _arr[index] = value
    }

    fun add(value: Int) {
        if(size == capacity) grow()
        _arr[size++] = value
    }

    fun addAll(list: IntList) {
        ensureCapacity(size + list.size)
        list._arr.copyInto(_arr, size, 0, list.size)
        size += list.size
    }

    fun add(index: Int, element: Int) {
        if(size == capacity) grow()
        _arr.copyInto(_arr, index + 1, index, size)
        size++
        set(index, element)
    }

    fun clear() { size = 0 }

    fun removeAt(index: Int): Int {
        val e = get(index)
        _arr.copyInto(_arr, index, index + 1, size)
        size--
        return e
    }

    operator fun iterator() = object: IntIterator() {
        private var pos = 0
        override fun hasNext() = pos < size
        override fun nextInt() = get(pos++)
    }

    inline fun isEmpty() = size == 0
    inline fun isNotEmpty() = size != 0

    fun pop() = _arr[--size]

    fun swap(i: Int, j: Int) { val t = this[i]; this[i] = this[j]; this[j] = t }
