fun CharSequence.suffixArrayAndLCP(): Pair<IntArray, IntArray> {
    if(isEmpty()) return intArrayOf(0) to intArrayOf()

    val n = length

    var S = IntArray(n + 1)
    S[0] = n // for empty suffix ('$')

    // counting sort for ascii (max value assumed 127)
    val bkt = IntArray(129)
    bkt[0] = 1 // for empty suffix
    for(i in 0 until n) {
        bkt[this[i].toInt() + 1]++
    }
    for(i in 1 until bkt.lastIndex) {
        bkt[i] += bkt[i-1]
    }
    for(i in 0 until n) {
        S[bkt[this[i].toInt()]++] = i
    }

    // STL sort
//    val A = MutableList(n) { it }
//    A.sortBy { this[it] }
//    for(i in 0 until n) S[i+1] = A[i]

    var C = IntArray(n + 1)
    C[S[1]] = 1
    for(i in 2..n) {
        C[S[i]] = C[S[i-1]]
        if(this[S[i]] != this[S[i-1]]) C[S[i]]++
    }

    var k = 1
    while(k < n) {
        // counting sort
        @Suppress("NAME_SHADOWING")
        val bkt = IntArray(n+2)
        for(i in 0..n) {
            bkt[C[i]+1]++
        }
        for(i in 2..n) {
            bkt[i] += bkt[i-1]
        }

        val Sk = IntArray(n+1)
        for(s in S) {
            val j = s - k modulo n+1
            Sk[bkt[C[j]]++] = j
        }

        val Ck = IntArray(n+1)
        for(i in 1..n) {
            val a = Sk[i]
            val b = Sk[i-1]
            Ck[a] = Ck[b]

            val cmp = C[a] != C[b] || C[(a + k) % (n+1)] != C[(b + k) % (n+1)]
            if(cmp) Ck[a]++
        }

        S = Sk
        C = Ck

        k = k shl 1
    }

    // LCP
    val L = IntArray(n)
    k = 0
    for(i in 0 until n) {
        val pi = C[i] // final C = S^-1
        val j = S[pi - 1]
        while(max(i, j) + k < n && this[i+k] == this[j+k]) k++
        L[pi-1] = k
        if(k > 0) k--
    }

    return S to L
}

infix fun Int.modulo(mod: Int): Int = (this % mod).let { (it shr Int.SIZE_BITS - 1 and mod) + it }


