class Trie {
  private var values = LongArray(26)
  private val childs = Array<Trie?>(26) { null }

  fun insert(s: String) {
    var node = this
    val length = s.length
    for (i in 0 until length - 1) {
      val c = s[i] - 'a'
      if (node.childs[c] == null) node.childs[c] = Trie()
      node = node.childs[c]!!
    }
    node.values[s[length - 1] - 'a']++
  }

  fun count(s: String): Long {
    val cnt = IntArray(26)
    for (c in s) {
      cnt[c - 'a']++
    }
    var res = 0L
    var node = this
    for (c in s) {
      for (i in cnt.indices) {
        if (cnt[i] > 0) res += node.values[i]
      }
      val n = c - 'a'
      if (node.childs[n] == null) break
      node = node.childs[n]!!
      cnt[n]--
    }
    return res
  }
}

