class Trie {
    static class Node {
        int[] next;
        List<Integer> accept = new ArrayList<>();
        int c;
        int common;
        Node(int c) {
            this.c = c;
            next = new int[26];
            Arrays.fill(next, -1);
        }
    }

    List<Node> nodes = new ArrayList<>();

    Trie() {
        nodes.add(new Node(0));
    }

    void insert(String word) {
        int wordId = nodes.get(0).common;
        int nodeId = 0;
        for (int i = 0; i < word.length(); i++) {
            int c = word.charAt(i) - 'a';
            int nextId = nodes.get(nodeId).next[c];
            if (nextId == -1) {
                nodes.get(nodeId).next[c] = nodes.size();
                nextId = nodes.size();
                nodes.add(new Node(c));
            }
            nodes.get(nodeId).common++;
            nodeId = nextId;
        }
        nodes.get(nodeId).common++;
        nodes.get(nodeId).accept.add(wordId);
    }

    boolean search(String word) {
        int nodeId = 0;
        for (int i = 0; i < word.length(); i++) {
            int c = word.charAt(i) - 'a';
            int nextId = nodes.get(nodeId).next[c];
            if (nextId == -1) {
                return false;
            }
            nodeId = nextId;
        }
        return nodes.get(nodeId).accept.size() > 0;
    }

    int searchPrefix(String word) {
        int nodeId = 0;
        for (int i = 0; i < word.length(); i++) {
            int c = word.charAt(i) - 'a';
            int nextId = nodes.get(nodeId).next[c];
            if (nextId == -1) {
                return 0;
            }
            nodeId = nextId;
        }
        return nodes.get(nodeId).common;
    }
}

