            return this;
        }

        public FastOutput append(long c) {
            cache.append(c);
            return this;
        }

        public FastOutput println(long c) {
            return append(c).println();
        }

        public FastOutput println() {
            cache.append(System.lineSeparator());
            return this;
        }

        public FastOutput flush() {
            try {
                os.append(cache);
                os.flush();
                cache.setLength(0);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return this;
        }

        public void close() {
            flush();
            try {
                os.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        public String toString() {
            return cache.toString();
        }

    }

    static class Node {
        static int charset = 'z' - 'a' + 1;
        Node[] next = new Node[charset];
        int cnt;

        public Node get(int i) {
            if (next[i] == null) {
                next[i] = new Node();
            }
            return next[i];
        }

        public int count(PartialString seq, int i) {
            if (i == seq.length()) {
                return 0;
            }
            int ans = 0;
            int suf = seq.getSuf(i);
            for (int j = 0; j < charset; j++) {
                if (next[j] != null && Bits.get(suf, j) == 1) {
                    ans += next[j].cnt;
                }
            }
            if (next[seq.get(i)] != null) {
                ans += next[seq.get(i)].count(seq, i + 1);
            }
            return ans;
        }

        public void add(PartialString seq, int i) {
            if (i == seq.length()) {
                cnt++;
                return;
            }
            get(seq.get(i)).add(seq, i + 1);
        }

    }

    static class Bits {
        private Bits() {
        }

        public static int get(int x, int i) {
            return (x >>> i) & 1;
        }

    }

    static class PartialString {
        int[] s;
        int[] suf;
        int l;
        int r;

        public PartialString(int[] s, int[] suf, int l, int r) {
            this.s = s;
            this.suf = suf;
            this.l = l;
            this.r = r;
        }

        public int get(int i) {
            return s[l + i];
        }

        public int getSuf(int i) {
            return suf[l + i];
        }

        public int length() {
            return r - l + 1;
        }

    }

    static class SequenceUtils {
        public static void swap(int[] data, int i, int j) {
            int tmp = data[i];
            data[i] = data[j];
            data[j] = tmp;
        }

        public static void reverse(int[] data, int l, int r) {
            while (l < r) {
                swap(data, l, r);
                l++;
                r--;
            }
        }

    }
}

