        Arrays.sort(st, (String s1, String s2) -> Integer.compare(s1.length(), s2.length()));

        long ans = 0;
        Node root = new Node();
        for(int i = 0; i< N; i++){
            ans += countPairs(root, st[i]);
            insert(root, st[i]);
        }
        pn(ans);
