			for (int c = 0; c < s.length(); c++) {
				ff[s.charAt(c) - 'a'][c]++;
			}
			for (int c = 1; c < s.length(); c++) {
				for (int ch = 0; ch < 26; ch++) {
					ff[ch][c] += ff[ch][c - 1];
				}
			}
			f[r] = ff;
		}

		int ans = 0;
		for (int i = 0; i < n - 1; i++) {
			for (int j = i + 1; j < n; j++) {
				if (strs[i].length() > 1) {
					int len = strs[i].length() - 1;
					int fromi = 1;
					int toi = strs[i].length() - 1;
					long hashi = rls[i].query(fromi, toi)[0];
					int fromj = strs[j].length() - len;
					int toj = strs[j].length() - 1;
