//					System.out.println(strs[i].substring(fromi, toi + 1) + " " + hashi + " "
//							+ strs[j].substring(fromj, toj + 1) + " " + hashj);
					if (hashi != hashj)
						continue;
					if (!equal(strs[i], fromi, toi, strs[j], fromj, toj))
						continue;
				}
//				System.out.println(strs[i] + " " + strs[j]);
				int first = strs[i].charAt(0) - 'a';
