        Arrays.setAll(a, $ -> nextInt());
        return a;
    }
    public int[] ints(final int n, final IntUnaryOperator f) {
        final int[] a = new int[n];
        Arrays.setAll(a, $ -> f.applyAsInt(nextInt()));
        return a;
    }
    public int[][] ints(final int n, final int m) {
        final int[][] a = new int[n][];
        Arrays.setAll(a, $ -> ints(m));
        return a;
    }
    public int[][] ints(final int n, final int m, final IntUnaryOperator f) {
        final int[][] a = new int[n][];
        Arrays.setAll(a, $ -> ints(m, f));
        return a;
    }
    public long[] longs(final int n) {
        final long[] a = new long[n];
        Arrays.setAll(a, $ -> nextLong());
        return a;
    }
    public long[] longs(final int n, final LongUnaryOperator f) {
        final long[] a = new long[n];
        Arrays.setAll(a, $ -> f.applyAsLong(nextLong()));
        return a;
    }
    public long[][] longs(final int n, final int m) {
        final long[][] a = new long[n][];
        Arrays.setAll(a, $ -> longs(m));
        return a;
    }
    public long[][] longs(final int n, final int m, final LongUnaryOperator f) {
        final long[][] a = new long[n][];
        Arrays.setAll(a, $ -> longs(m, f));
        return a;
    }
    public char[][] charArrays(final int n) {
        final char[][] c = new char[n][];
        Arrays.setAll(c, $ -> nextChars());
        return c;
    }
    public char[][] charArrays(final int n, final int m) {
        final char[][] c = new char[n][];
        Arrays.setAll(c, $ -> nextChars(m));
        return c;
    }
    public double[] doubles(final int n) {
        final double[] a = new double[n];
        Arrays.setAll(a, $ -> nextDouble());
        return a;
    }
    public double[][] doubles(final int n, final int m) {
        final double[][] a = new double[n][];
        Arrays.setAll(a, $ -> doubles(m));
        return a;
    }
    public String[] strings(final int n) {
        final String[] s = new String[n];
        Arrays.setAll(s, $ -> next());
        return s;
    }
    public String[] strings(final int n, final int m) {
        final String[] s = new String[n];
        Arrays.setAll(s, $ -> next(m));
        return s;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

	static PrintWriter out;

	public static void main(String[] args) throws IOException {
		MyScanner sc = new MyScanner();
		out = new PrintWriter(System.out);
		int N = sc.nextInt();
		char[][] words = new char[N][];
		for (int i = 0; i < N; i++) {
			words[i] = sc.next().toCharArray();
			insert(words[i], 0, words[i].length - 1);
		}
		//print(0, "\t");
		long ans = 0;
		for (int i = 0; i < N; i++) {
			ans += calc(words[i]);
		}
		out.println(ans);

		out.flush();
	}

	static int[][] count = new int[26][1000002];
	static int[][] next = new int[26][1000002];
	static int size = 1;

	static int insert(char[] word, int node, int pos) {
		if (pos == -1) return 0;
		int idx = word[pos] - 'a';
		int child = next[idx][node];
		if (child == 0) {
			next[idx][node] = child = size++;
		}
		int ret = insert(word, child, pos - 1) | (1 << idx);
		for (int i = 0; i < 26; i++) if (contains(ret, i)) {
			count[i][node]++;
		}
		return ret | (1 << idx);
	}

	static int calc(char[] word) {
		int cur = 0;
		for (int i = word.length - 1; i >= 1; i--) {
			cur = next[word[i] - 'a'][cur];
		}
		//System.err.println(new String(word) + " => " + cur.count[word[0] - 'a']);
		return count[word[0] - 'a'][cur] - 1;
	}

	static void print(int node, String tab) {
		for (int i = 0; i < 26; i++) {
			if (count[i][node] > 0) {
				System.err.print(tab + " count= " + (char) (i + 'a') + " => " + count[i][node]);
			}
		}
		System.err.println();
		for (int i = 0; i < 26; i++) {
			if (next[i][node] != 0) {
				print(next[i][node], tab + (char) (i + 'a'));
			}
		}
	}

	static boolean contains(int mask, int pos) {
		return (mask & (1<<pos)) != 0;
	}

	static class MyScanner {
		private BufferedReader br;
		private StringTokenizer tokenizer;

		public MyScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		public String next() {
			while (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return tokenizer.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

		public long nextLong() {
			return Long.parseLong(next());
		}
	}
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Set;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.StringTokenizer;
import java.util.SplittableRandom;
import java.math.BigInteger;
import java.io.BufferedReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        B_FirstSecond solver = new B_FirstSecond();
        solver.solve(1, in, out);
        out.close();
    }

    static class B_FirstSecond {
        SplittableRandom random = new SplittableRandom(0);
        long MOD;
        long X;
        final int N = (int) (1e6 + 100);
        long[] pow;

        {
            MOD = (long) 1e9 + random.nextInt((int) 1e8);
            while (!BigInteger.valueOf(MOD).isProbablePrime(100)) {
                ++MOD;
            }
            X = 1 + random.nextInt((int) (MOD - 1));

            pow = new long[N + 1];
            pow[0] = 1;
            for (int i = 1; i < pow.length; i++) {
                pow[i] = X * pow[i - 1] % MOD;
            }
        }

        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            char[][] s = new char[n][];
            StringHasher[] h = new StringHasher[n];
            Set<Long> fullStrings = new HashSet<>();
            for (int i = 0; i < n; i++) {
                s[i] = in.next().toCharArray();
                h[i] = new StringHasher(s[i]);
                long fh = h[i].get(0, s[i].length - 1);
                if (fullStrings.contains(fh)) {
                    throw new AssertionError();
                }
                fullStrings.add(fh);
            }

            long ans = 0;
            for (int i = 0; i < n; i++) {
                boolean[] got = new boolean[26];
                for (int j = 0; j < s[i].length; j++) {
                    got[s[i][j] - 'a'] = true;
                    for (int c = 0; c < 26; c++) {
                        if (!got[c]) {
                            continue;
                        }
                        long suff = h[i].get(j + 1, s[i].length - 1);
                        int suffLen = s[i].length - j - 1;
                        long full = ((c + 'a') * pow[suffLen] + suff) % MOD;
                        if (fullStrings.contains(full)) {
                            ++ans;
                        }
                    }
                }
            }

            out.println(ans - n);
        }

        class StringHasher {
            long[] h;

            StringHasher(char[] s) {
                int n = s.length;
                h = new long[n + 1];
                for (int i = 0; i < n; i++) {
                    h[i + 1] = (X * h[i] + s[i]) % MOD;
                }
            }

            long get(int l, int r) {
                long res = (h[r + 1] - pow[r - l + 1] * h[l]) % MOD;
                if (res < 0) {
                    res += MOD;
                }
                return res;
            }

        }

    }

    static class FastScanner {
        private BufferedReader in;
        private StringTokenizer st;

        public FastScanner(InputStream stream) {
            in = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;

import javax.transaction.xa.Xid;

public class Main {
	static final long MOD=1000000007;//998244353;
	public static void main(String[] args) {
		PrintWriter out = new PrintWriter(System.out);
		InputReader sc=new InputReader(System.in);
		int N=sc.nextInt();
		Trie trie=new Trie();
		String[] strings=new String[N];
		for (int i = 0; i < strings.length; i++) {
			strings[i]=new StringBuffer(sc.next()).reverse().toString();
		}
		long ans=0;
		Arrays.sort(strings,(s1,s2)->s1.length()-s2.length());
		for (int i = 0; i < strings.length; i++) {
			ans+=trie.count(strings[i]);
			trie.insert(strings[i], i);
		}
		System.out.println(ans);
	}
	static class Trie{
		class Node{
			int[] next=new int[26];//子
			ArrayList<Integer> accept=new ArrayList<>();//この頂点を末端とする文字列のID
			int c;
			int common;
			public Node(int c) {
				this.c=c;//nodeの表す文字
				Arrays.fill(next, -1);
			}
		}
		ArrayList<Node> nodes=new ArrayList<>();
		public Trie() {
			nodes.add(new Node(0));
		}
		void insert(String string,int str_id) {
			char[] cs=string.toCharArray();
			int node_id=0;
			for (int i = 0; i < cs.length; i++) {
				nodes.get(node_id).common++;
				int x=(int)cs[i]-'a';//辺に対応する文字
				int nextnode=nodes.get(node_id).next[x];
				if (nextnode==-1) {
					nextnode=nodes.size();
					nodes.get(node_id).next[x]=nodes.size();
					nodes.add(new Node(x));
				}
				node_id=nextnode;
			}
			nodes.get(node_id).common++;
			nodes.get(node_id).accept.add(str_id);
		}
		boolean search(String string) {
			char[] cs=string.toCharArray();
			int node_id=0;
			for (int i = 0; i < cs.length; i++) {
				int x=(int)cs[i]-'a';
				int nextnode=nodes.get(node_id).next[x];
				if (nextnode==-1) {
					return false;
				}
				node_id=nextnode;
			}
			if (nodes.get(node_id).accept.size()>0) {
				return true;
			}
			return false;
		}
		long count(String string){
			char[] cs=string.toCharArray();
			int node_id=0;
			long[] bitmask=new long[cs.length];
			long bitfirst=0;
			long ans=0; 
			for (int i = cs.length-2; i >= 0; i--) {
				bitmask[i]=bitmask[i+1]|((long)1<<((int)cs[i+1]-'a'));
			}
			bitfirst=bitmask[0]|(long)1<<((int)cs[0]-'a');
			for (int i = 0; i < 26; i++) {
				if ((1&(bitfirst>>i))==1) {
					int next=nodes.get(node_id).next[i];
					if (next!=-1) {
						ans+=nodes.get(next).accept.size();
					}
				}
			}
			for (int i = 0; i < cs.length; i++) {
				int x=(int)cs[i]-'a';
				int nextnode=nodes.get(node_id).next[x];
				if (nextnode==-1){
					return ans;
				}
				node_id=nextnode;
				for (int j = 0; j < 26; j++) {
					if ((1&(bitmask[i]>>j))==1) {
						int next=nodes.get(node_id).next[j];
						if (next!=-1) {
							ans+=nodes.get(next).accept.size();
						}
					}
				}
			}
			return ans;
		}
	}
	static class InputReader { 
		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;
		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}
	}

import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
	static class LenComparator implements Comparator<String>{
		@Override
		public int compare(String o1, String o2) {
			return o1.length() - o2.length();
		}
	}
	static long solve(String S[]){
		Arrays.sort(S, new LenComparator());
		Map<String, int[]> map = new HashMap<String, int[]>();
		long tot = 0;
		for(String s : S){
			int vis[] = new int[26];
			vis[s.charAt(0) - 'a'] = 1; 
			for(int i = 1; i <= s.length() ; ++i){
				String sub = s.substring(i);
				if(map.containsKey(sub)){
					int[] arr = map.get(sub);
					for(int j = 0 ; j < 26 ; ++j){
						tot += arr[j] * vis[j];
					}
				}
				if(i < s.length()){
					vis[s.charAt(i) - 'a'] = 1;					
				}
			}
			String suffix = s.substring(1);
			if(!map.containsKey(suffix)){
				map.put(suffix, new int[26]);
			}
			char s0 = s.charAt(0);
			int arr[] = map.get(suffix);
			arr[s0 - 'a']++;
		}
		return tot;
	}
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);		
		int N = sc.nextInt();
		String S[] = new String[N];
		for(int i = 0 ; i < N ; ++i){
			S[i] = sc.next();			
		}
		long ret = solve(S);
		System.out.println(ret);
	}
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        char[][] c = sc.charArrays(n);
        String[] s = new String[n];
        for (int i = 0; i < n; i++) {
            int l = 0, r = c[i].length - 1;
            while (l < r) {
                char tmp = c[i][l]; c[i][l] = c[i][r]; c[i][r] = tmp;
                l++; r--;
            }
            s[i] = String.valueOf(c[i]);
        }
        Arrays.sort(s);
        int[][] cnt = new int[26][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < s[i].length(); j++) {
                cnt[s[i].charAt(j) - 'a'][i]++;
            }
        }
        long ans = 0;
        for (int i = 0; i < n; i++) {
            int l = i, r = n;
            String pref = s[i].substring(0, s[i].length() - 1);
            int x = s[i].charAt(s[i].length() - 1) - 'a';
            while (r - l > 1) {
                int m = (l + r) / 2;
                if (s[m].startsWith(pref)) {
                    l = m;
                } else {
                    r = m;
                }
            }
            for (int k = i + 1; k < r; k++) {
                if (cnt[x][k] >= cnt[x][i]) {
                    ans++;
                }
            }
        }
        out.writeln(ans);
    }
}


