			}
			return length > 0;
		}

		private byte readByte() {
			if (hasNextByte()) return buffer[read++];
			throw new NoSuchElementException();
		}

		private boolean readNewLine() {
			if (hasNextByte()) {
				if (buffer[read] == '\r') {
					++ read;
					if (hasNextByte() && buffer[read] == '\n') ++ read;
					return true;
				}
				if (buffer[read] == '\n') {
					++ read;
					return true;
				}
			}
			return false;
		}

		private static boolean isPrintableChar(byte c) {
			return 32 < c || c < 0;
