class Trie {
    static class Node {
        int[] next;
        int[] has;
        int c;
        int common;

        Node(int c) {
            this.c = c;
            this.has = new int[26];
            next = new int[26];
            Arrays.fill(next, -1);
        }
        @Override
        public String toString() {
            return "{" + "c=" + (char)(c+'a') + ", common=" + common + ", " + Arrays.toString(has) + '}';
        }
    }

    List<Node> nodes;

    Trie(int n) {
        nodes = new ArrayList<>();
        nodes.add(new Node(0));
    }

    void insert(String word) {
        int[] rem = new int[26];
        int has = 0;
        for (char ch : word.toCharArray()) {
            if (rem[ch - 'a'] == 0) {
                has |= 1 << (ch - 'a');
            }
            rem[ch - 'a']++;
        }
        int nodeId = 0;
        for (int i = 0; i < word.length(); i++) {
            int c = word.charAt(i) - 'a';
            int nextId = nodes.get(nodeId).next[c];
            if (nextId == -1) {
                nodes.get(nodeId).next[c] = nodes.size();
                nextId = nodes.size();
                nodes.add(new Node(c));
            }
            for (int j = 0; j < 26; j++) {
                if (((has >> j) & 1) == 1) {
                    nodes.get(nodeId).has[j]++;
                }
            }
            nodes.get(nodeId).common++;
            nodeId = nextId;
            rem[c]--;
            if (rem[c] == 0) {
                has ^= 1 << c;
            }
        }
        for (int j = 0; j < 26; j++) {
            if (((has >> j) & 1) == 1) {
                nodes.get(nodeId).has[j]++;
            }
        }
        nodes.get(nodeId).common++;
    }

    int searchPrefix(String word, int ch) {
        int nodeId = 0;
        for (int i = 0; i < word.length(); i++) {
            int c = word.charAt(i) - 'a';
            int nextId = nodes.get(nodeId).next[c];
            if (nextId == -1) {
                return 0;
            }
            nodeId = nextId;
        }
        return nodes.get(nodeId).has[ch];
    }
}

