import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

	static PrintWriter out;

	public static void main(String[] args) throws IOException {
		MyScanner sc = new MyScanner();
		out = new PrintWriter(System.out);
		int N = sc.nextInt();
		char[][] words = new char[N][];
		root = new Node();
		for (int i = 0; i < N; i++) {
			words[i] = sc.next().toCharArray();
			insert(words[i], root, words[i].length - 1);
		}
		//print(root, "\t");
		long ans = 0;
		for (int i = 0; i < N; i++) {
			ans += calc(words[i]);
		}
		out.println(ans);

		out.flush();
	}

	static Node root;

	static class Node {
		Node[] children;
		int[] count;

		public Node() {
			children = new Node[26];
			count = new int[26];
		}
	}

	static int insert(char[] word, Node node, int pos) {
		if (pos == -1) return 0;
		int idx = word[pos] - 'a';
		Node child = node.children[idx];
		if (child == null) {
			node.children[idx] = child = new Node();
		}
		int ret = insert(word, child, pos - 1) | (1 << idx);
		for (int i = 0; i < 26; i++) if (contains(ret, i)) {
			node.count[i]++;
		}
		return ret | (1 << idx);
	}

	static int calc(char[] word) {
		Node cur = root;
		for (int i = word.length - 1; i >= 1; i--) {
			cur = cur.children[word[i] - 'a'];
		}
		//System.err.println(new String(word) + " => " + cur.count[word[0] - 'a']);
		return cur.count[word[0] - 'a'] - 1;
	}

	static void print(Node node, String tab) {
		if (node == null) throw new RuntimeException();
		for (int i = 0; i < 26; i++) {
			if (node.count[i] > 0) {
				System.err.print(tab + " count= " + (char) (i + 'a') + " => " + node.count[i]);
			}
		}
		System.err.println();
		for (int i = 0; i < 26; i++) {
			if (node.children[i] != null) {
				print(node.children[i], tab + (char) (i + 'a'));
			}
		}
	}

	static boolean contains(int mask, int pos) {
		return (mask & (1<<pos)) != 0;
	}

	static class MyScanner {
		private BufferedReader br;
		private StringTokenizer tokenizer;

		public MyScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		public String next() {
			while (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return tokenizer.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

		public long nextLong() {
			return Long.parseLong(next());
		}
	}
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.function.IntFunction;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        char[][] c = sc.charArrays(n);
        String[] s = new String[n];
        for (int i = 0; i < n; i++) {
            CharArrays.reverse(c[i]);
            s[i] = String.valueOf(c[i]);
        }
        Arrays.sort(s);
        int[][] cnt = new int[26][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < s[i].length(); j++) {
                cnt[s[i].charAt(j) - 'a'][i]++;
            }
        }
        long ans = 0;
        for (int i = 0; i < n; i++) {
            int l = i, r = n;
            String pref = s[i].substring(0, s[i].length() - 1);
            int x = s[i].charAt(s[i].length() - 1) - 'a';
            while (r - l > 1) {
                int m = (l + r) / 2;
                if (s[m].startsWith(pref)) {
                    l = m;
                } else {
                    r = m;
                }
            }
            for (int k = i + 1; k < r; k++) {
                if (cnt[x][k] >= cnt[x][i]) {
                    ans++;
                }
            }
        }
        out.writeln(ans);
    }
}


