	static void solve() {
		int n = ni();
		String a[] = new String[n];
		for(int i=0;i<n;i++) {
			a[i] = getReverse(ns());
		}
		Arrays.sort(a, (i, j)->{
			if(i.length() == j.length()) {
				return i.compareTo(j);
			}
			return i.length() - j.length();
		});


		Map<String, int[]> map = new HashMap<>();
		long ans = 0;
		for(int i=0;i<n;i++) {
			String s = a[i];
			int m = s.length();
			int[] use = new int[26];
			for(int j=0;j<m;j++) {
				use[s.charAt(j) - 'a']++;
			}
			StringBuilder now = new StringBuilder();
			for(int j=0;j<=m;j++) {
				if(map.containsKey(now.toString())){
					int[] have = map.get(now.toString());
					for(int k=0;k<26;k++) {
						if(have[k] > 0 && use[k]>0) {
							ans += have[k];
						}
					}
				}
				if(j == m)continue;
				now.append(s.charAt(j));
				use[s.charAt(j) - 'a']--;
			}

			//自分を格納する
			String sub = s.substring(0,s.length()-1);
			map.putIfAbsent(sub, new int[26]);
			char t = s.charAt(s.length()-1);
			map.get(sub)[t - 'a']++;
		}
		out.println(ans);

	}	

