/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "", 1 << 29);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastInput in = new FastInput(inputStream);
            FastOutput out = new FastOutput(outputStream);
            BFirstSecond solver = new BFirstSecond();
            solver.solve(1, in, out);
            out.close();
        }
    }

    static class BFirstSecond {
        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            int[][] strings = new int[n][];
            int[] s = new int[(int) 1e6];
            Node root = new Node();
            long ans = 0;
            for (int i = 0; i < n; i++) {
                int len = in.readString(s, 0);
                for (int j = 0; j < len; j++) {
                    s[j] -= 'a';
                }
                SequenceUtils.reverse(s, 0, len - 1);
                strings[i] = Arrays.copyOf(s, len);
            }

            Arrays.sort(strings, (a, b) -> Integer.compare(a.length, b.length));
            for (int[] string : strings) {
                int len = string.length;
                int[] suf = new int[len];
                suf[len - 1] = 1 << string[len - 1];
                for (int j = len - 2; j >= 0; j--) {
                    suf[j] = suf[j + 1] | (1 << string[j]);
                }
                int contrib = root.count(string, suf, 0);
                ans += contrib;
                root.add(string, 0);
            }
            out.println(ans);
        }

    }

    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

        public int readString(int[] data, int offset) {
            skipBlank();

            int originalOffset = offset;
            while (next > 32) {
                data[offset++] = (char) next;
                next = read();
            }

            return offset - originalOffset;
        }

    }

    static class Node {
        static int charset = 'z' - 'a' + 1;
        Node[] next = new Node[charset];
        int cnt;

        public Node get(int i) {
            if (next[i] == null) {
                next[i] = new Node();
            }
            return next[i];
        }

        public int count(int[] seq, int[] suf, int i) {
            if (i == seq.length) {
                return 0;
            }
            int ans = 0;
            for (int j = 0; j < charset; j++) {
                if (next[j] != null && Bits.get(suf[i], j) == 1) {
                    ans += next[j].cnt;
                }
            }
            if (next[seq[i]] != null) {
                ans += next[seq[i]].count(seq, suf, i + 1);
            }
            return ans;
        }

        public void add(int[] seq, int i) {
            if (i == seq.length) {
                cnt++;
                return;
            }
            get(seq[i]).add(seq, i + 1);
        }

    }

    static class FastOutput implements AutoCloseable, Closeable, Appendable {
        private StringBuilder cache = new StringBuilder(10 << 20);
        private final Writer os;

        public FastOutput append(CharSequence csq) {
            cache.append(csq);
            return this;
        }

        public FastOutput append(CharSequence csq, int start, int end) {
            cache.append(csq, start, end);
            return this;
        }

        public FastOutput(Writer os) {
            this.os = os;
        }

        public FastOutput(OutputStream os) {
            this(new OutputStreamWriter(os));
        }

        public FastOutput append(char c) {
            cache.append(c);
            return this;
