    static class BFirstSecond {
        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            PartialString[] ps = new PartialString[n];
            int[] s = new int[(int) 1e6];
            int[] suf = new int[(int) 1e6];
            Node root = new Node();
            long ans = 0;
            int wpos = 0;
            for (int i = 0; i < n; i++) {
                int len = in.readString(s, wpos);
                ps[i] = new PartialString(s, suf, wpos, wpos + len - 1);
                for (int j = 0; j < len; j++) {
                    s[wpos + j] -= 'a';
                }
                SequenceUtils.reverse(s, wpos, wpos + len - 1);
                suf[wpos + len - 1] = 1 << s[wpos + len - 1];
                for (int j = len - 2; j >= 0; j--) {
                    suf[wpos + j] = suf[wpos + j + 1] | (1 << s[wpos + j]);
                }
                wpos += len;
            }

            Arrays.sort(ps, (a, b) -> Integer.compare(a.length(), b.length()));
            for (PartialString string : ps) {
                int contrib = root.count(string, 0);
                ans += contrib;
                root.add(string, 0);
            }
            out.println(ans);
        }

    }

    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

        public int readString(int[] data, int offset) {
            skipBlank();

            int originalOffset = offset;
            while (next > 32) {
                data[offset++] = (char) next;
                next = read();
            }

            return offset - originalOffset;
        }

    }

