    static class Node {
        static int charset = 'z' - 'a' + 1;
        Node[] next = new Node[charset];
        int cnt;

        public Node get(int i) {
            if (next[i] == null) {
                next[i] = new Node();
            }
            return next[i];
        }

        public int count(PartialString seq) {
            int ans = 0;
            int i = 0;
            for (Node node = this; node != null; node = node.next[seq.get(i)], i++) {
                if (i == seq.length()) {
                    break;
                }
                int suf = seq.getSuf(i);
                for (int j = 0; j < charset; j++) {
                    if (node.next[j] != null && Bits.get(suf, j) == 1) {
                        ans += node.next[j].cnt;
                    }
                }
            }
            return ans;
        }

        public void add(PartialString seq) {
            int i = 0;
            for (Node node = this; node != null; node = node.get(seq.get(i)), i++) {
                if (i == seq.length()) {
                    node.cnt++;
                    break;
                }
            }
        }

    }

    static class Bits {
        private Bits() {
        }

        public static int get(int x, int i) {
            return (x >>> i) & 1;
        }

    }

    static class PartialString {
        int[] s;
        int[] suf;
        int l;
        int r;

        public PartialString(int[] s, int[] suf, int l, int r) {
            this.s = s;
            this.suf = suf;
            this.l = l;
            this.r = r;
        }

        public int get(int i) {
            return s[l + i];
        }

        public int getSuf(int i) {
            return suf[l + i];
        }

        public int length() {
            return r - l + 1;
        }

    }

    static class SequenceUtils {
        public static void swap(int[] data, int i, int j) {
            int tmp = data[i];
            data[i] = data[j];
            data[j] = tmp;
        }

        public static void reverse(int[] data, int l, int r) {
            while (l < r) {
                swap(data, l, r);
                l++;
                r--;
            }
        }

    }
}

import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class Main {
    public static final int max = 1_000_001;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine());
        String[] strings = new String[n];
        for (int i = 0; i < n; i++) {
            strings[i] = scanner.nextLine();
        }
        System.out.println(solve(strings));
    }

    public static long solve(String[] strings) {
        int[][] child = new int[max][26];
        boolean[] isWord = new boolean[max];
        int length = strings.length;
        int[][] paths = new int[length][];
        int nxt = 1;
        for (int k = 0; k < length; k++) {
            String s = strings[k];
            int n = s.length();
            int[] path = new int[n];
            int node = 0;
            for (int i = n - 1, j = 0; i >= 0; i--, j++) {
                int c = s.charAt(i) - 'a';
                path[j] = node;
                if (child[node][c] == 0) child[node][c] = nxt++;
                node = child[node][c];
            }
            paths[k] = path;
            isWord[node] = true;
        }
        long ans = 0;
        for (int k = 0; k < length; k++) {
            String s = strings[k];
            int n = s.length();
            int[] path = paths[k];
            Set<Integer> set = new HashSet<>();
            for (int i = 0, j = n - 1; j >= 0; i++, j--) {
                set.add(s.charAt(i) - 'a');
                int node = path[j];
                for (Integer c : set) {
                    if (isWord[child[node][c]]) ans++;
                }
            }
        }
        return ans - length;
    }
}

