public class Main {
    private static final boolean N_CASE = false;

    private static final int CN = 26;

    private static class Node {
        Node[] nxt;
        int[] cnt;

        Node() {
            nxt = new Node [CN];
            cnt = new int[CN];
        }
    }

    private static class Trie {
        Node root;

        Trie() {
            root = new Node();
        }

        private void insert(String s) {
            int m = s.length();
            int[] cnt = new int[CN];
            for (int i = 0; i < m; ++i) {
                ++cnt[s.charAt(i) - 'a'];
            }

            Node p = root;
            for (int i = 0; i < CN; ++i) {
                if (cnt[i] > 0) {
                    ++p.cnt[i];
                }
            }

            for (int i = m - 1; i >= 0; --i) {
                int j = s.charAt(i) - 'a';
                Node nxt = p.nxt[j];
                if (nxt == null) {
                    nxt = new Node();
                    p.nxt[j] = nxt;
                }
                --cnt[j];
                p = nxt;
                for (int k = 0; k < CN; ++k) {
                    if (cnt[k] > 0) {
                        ++p.cnt[k];
                    }
                }
            }
        }

        private int search(String s) {
            int m = s.length();
            Node p = root;
            for (int i = m - 1; i > 0; --i) {
                int j = s.charAt(i) - 'a';
                p = p.nxt[j];
                if (p == null) {
                    return 0;
                }
            }

            return p.cnt[s.charAt(0) - 'a'];
        }
    }

    private void solve() {
        int N = sc.nextInt();
        List<String> S = new ArrayList<>();
        for (int i = 0; i < N; ++i) {
            S.add(sc.next());
        }

        S.sort(Comparator.comparingInt(String::length));

        long ans = 0;
        Trie trie = new Trie();
        for (int i = N - 1; i >= 0; --i) {
            ans += trie.search(S.get(i));
            trie.insert(S.get(i));
        }

        out.println(ans);
    }

    private void run() {
        int T = N_CASE ? sc.nextInt() : 1;
        for (int t = 0; t < T; ++t) {
            solve();
        }
    }

