    //私が好きなアルゴリズム::累積和・UF木
    //PriorityQueueは拡張for文で出すとsortされてない順番で出てくるよ
    //longのbit演算は1L<<posに注意
    //long long
    //JOIはMLEが厳しい  shortというものがあるよ。
	public static void main(String[] args) throws Exception {
		FastScanner sc = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);

		int n = sc.nexI();

		String[] s4disp = new String[n];

		int[][] ss = new int[n][];

		int[] lns = new int[n];

		int[][] lasposOfAchar = new int[n][26]; //ある文字が最後に出現する箇所。(0-indexed)これをdepthと比較する
		fill(lasposOfAchar,-1);

		//文字列を反転、0-25にして保存
		for(int i=0; i<n; i++){
		    String s1 = sc.next();
		    s4disp[i] = s1;

		    lns[i] = s1.length();
		    int[] c1 = new int[lns[i]];
		    for(int p=0; p<lns[i]; p++){
		        c1[p] = s1.charAt(lns[i]-p-1)-97;
		    }
		    ss[i] = c1;
		    for(int p=0; p<lns[i]; p++){
		        lasposOfAchar[i][ss[i][p]] = max(lasposOfAchar[i][ss[i][p]], p);
		    }
		}

		//show2(lasposOfAchar,"");

		//全てのstringをとりあえず一つに
		GroupOfStrings uallg = new GroupOfStrings(0);   //depthは 1-indexed

		for(int i=0; i<n; i++){
		    uallg.add(i, lasposOfAchar[i]);
		}

		ArrayDeque<GroupOfStrings> todo = new ArrayDeque<>();
		todo.add(uallg);

		long ans = 0L;
		while(todo.size()>0){
		    GroupOfStrings grp1 = todo.poll();  //d1-1文字目までは共通な文字列の集まり
		    int d1 = grp1.depth+1;  //1-indexed

		    GroupOfStrings[] newgrps = new GroupOfStrings[26];  //d1文字目で仕分ける用
		    for(int i=0; i<26; i++){
		        newgrps[i] = new GroupOfStrings(d1);
		    }

		    for(int e: grp1.dt){
		        //out.print(s4disp[e]);
		        if(lns[e]==d1){
		            //out.println("  go away; ans += "+(grp1.ncontains[ss[e][d1-1]]-1));
		            ans += (long)grp1.ncontains[ss[e][d1-1]];
		            ans--;  //自身
		        }else{
		            //out.println("  goes to  "+ss[e][d1-1]+"  group");
		            newgrps[ss[e][d1-1]].add(e, lasposOfAchar[e]);
		        }
		    }
		    for(int i=0; i<26; i++){
		        if(newgrps[i].dt.size()>=2) todo.add(newgrps[i]);
		    }
		}
		out.println(ans);
	    out.flush();
	}

	static class GroupOfStrings {
	    public ArrayList<Integer> dt = new ArrayList<>();
	    public int depth = 0;   //何文字目が共通なのか(1-indexed)
	    public int[] ncontains = new int[26];      //文字iをdepth「より」後に含んだものが何個あるか
	    GroupOfStrings(int d1){
	        depth=d1;
	        fill(ncontains,0);
	    }
	    public void add(int vn, int[] lasposOfAchar){
	        dt.add(vn);
	        for(int i=0; i<26; i++){
	            if(lasposOfAchar[i]>=depth) ncontains[i]++; //!!depthは 1-indexed, lasposOfAcharは 0-indexed
	        }
	    }
	}

