class Trie {

	static class TrieNode{
		TrieNode[] links;
		final int R = 26;
		boolean isEnd;
		Set<Character> needChars;//extension
		public TrieNode() {
			links = new TrieNode[R];
			needChars = new HashSet<>();
		}
		public boolean containKey(char ch) {
			return links[ch - 'a'] != null;
		}
		public TrieNode get(char ch) {
			return links[ch - 'a'];
		}
		public void put(char ch, TrieNode node) {
			links[ch - 'a'] = node;
		} 
		public void setEnd() {
			isEnd = true;
		}
	}


	TrieNode root;
	int cnt = 0;

    /** Initialize your data structure here. */
    public Trie() {
    	root = new TrieNode();
    }

    /** Inserts a word into the trie. */
    public void insert(String word) {
    	int[] cCnt = new int[26];
    	for(int i=0;i<word.length();i++) {
    		cCnt[word.charAt(i)-'a']++;
    	}
    	char last = word.charAt(word.length()-1);
    	word = word.substring(0, word.length()-1);
        TrieNode node = root;
        for(int i=0;i<word.length();i++) {
        	char ch = word.charAt(i);
        	cCnt[ch - 'a']--;
        	if(!node.containKey(ch)) {
        		node.put(ch, new TrieNode());
        	}
        	node = node.get(ch);
        	if(node.isEnd) {
        		for(char c : node.needChars) {
        			if(cCnt[c - 'a'] > 0)cnt++;        			
        		}
        	}
        }
        node.setEnd();
        node.needChars.add(last);
    }


}

import java.util.*;
public class Main {

    /**
     * @param n int整型
     * @param m int整型
     * @param a int整型一维数组
     * @return int整型
     */
    public static int count(int n, String[] s) {
        int ret = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (convert1to2(s[i], s[j])) ret++;
            }
        }
        return ret;
    }

    public static boolean convert1to2(String a, String b) {
        int m1 = a.length(), m2 = b.length();
        if (m1 == m2) return false;
        if (b.length() == 1) {
            return a.indexOf(b) != -1;
        }

        if (a.substring(m1 - m2, m1).equals(b)) return true;
        if        (a.substring(m1 - m2 + 1, m1).equals(b.substring(1, m2))
                        && a.indexOf(b.substring(0, 1)) <= m1 - m2 && a.indexOf(b.substring(0, 1)) >= 0)
            return true;

        else
            return false;

    }

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String[] s = new String[n];

        for (int i = 0; i < n; i++) {
            s[0] = sc.next();
        }
        Arrays.sort(s, (s1, s2) -> s2.length() - s1.length());                
        sc.close();

        System.out.println(count(n, s));
    }
}

