import static java.lang.Integer.parseInt;
import static java.lang.Long.parseLong;
import static java.lang.System.exit;
import static java.util.Arrays.fill;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {

	static List<int[]> trans, stats;

	static int mkstate() {
		int r = trans.size();
		int ctrans[] = new int[26];
		fill(ctrans, -1);
		trans.add(ctrans);
		stats.add(new int[27]);
		return r;
	}

	static void solve() throws Exception {
		int n = scanInt();
		String s[] = new String[n];
		trans = new ArrayList<>();
		stats = new ArrayList<>();
		mkstate();
		for (int i = 0; i < n; i++) {
			s[i] = scanString();
			int cur = 0;
			for (int j = s[i].length() - 1; j >= 0; j--) {
				int c = s[i].charAt(j) - 'a';
				int ctrans[] = trans.get(cur);
				if (ctrans[c] < 0) {
					ctrans[c] = mkstate();
				}
				cur = ctrans[c];
			}
			++stats.get(cur)[26];
		}
		go(0);
		long ans = 0;
		for (int i = 0; i < n; i++) {
			int cur = 0;
			for (int j = s[i].length() - 1; j > 0; j--) {
				int c = s[i].charAt(j) - 'a';
				int ctrans[] = trans.get(cur);
				cur = ctrans[c];
			}
			ans += stats.get(cur)[s[i].charAt(0) - 'a'] - 1;
		}
		out.print(ans);
	}

	static void go(int cur) {
		int ctrans[] = trans.get(cur), cstats[] = stats.get(cur);
		for (int i = 0; i < 26; i++) {
			if (ctrans[i] >= 0) {
				go(ctrans[i]);
				int nstats[] = stats.get(ctrans[i]);
				for (int j = 0; j < 27; j++) {
					cstats[j] += nstats[j == i ? 26 : j];
				}
			}
		}
	}

	static int scanInt() throws IOException {
		return parseInt(scanString());
	}

	static long scanLong() throws IOException {
		return parseLong(scanString());
	}

	static String scanString() throws IOException {
		while (tok == null || !tok.hasMoreTokens()) {
			tok = new StringTokenizer(in.readLine());
		}
		return tok.nextToken();
	}

	static BufferedReader in;
	static PrintWriter out;
	static StringTokenizer tok;

	public static void main(String[] args) {
		try {
			in = new BufferedReader(new InputStreamReader(System.in));
			out = new PrintWriter(System.out);
			solve();
			in.close();
			out.close();
		} catch (Throwable e) {
			e.printStackTrace();
			exit(1);
		}
	}
}

import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
	static class LenComparator implements Comparator<String>{
		@Override
		public int compare(String o1, String o2) {
			return o1.length() - o2.length();
		}
	}
	static class Trie{
		int firsts[];
		Trie children[];
		public Trie() {
			firsts = null; // new int[26];
			children = new Trie[26];
		}

		void add(char arr[] , int index, int first){
			if(index == arr.length){
				if(firsts == null){
					firsts = new int[26];
				}
				firsts[first]++;
			}else{
				int c = arr[index] - 'a';
				if(children[c] == null){
					children[c] = new Trie();
				}
				children[c].add(arr, index + 1, first);
			}
		}

		long hit(char arr[] , int index, int vis[]){
			if(index == arr.length){
				long ret = 0;
				for(int i = 0 ; i < 26 ; ++i){
					ret += vis[i] * firsts[i];
				}
				return ret;
			}else{
				int c = arr[index] - 'a';
				if(children[c] == null){
					return 0;
				}
				return children[c].hit(arr, index + 1, vis);
			}
		}
	}
	static long solve(String S[]){
		Arrays.sort(S, new LenComparator());
		long tot = 0;
		Trie root = new  Trie();
		for(String s : S){
			char arr[] = s.toCharArray();
			int vis[] = new int[26];
			vis[s.charAt(0) - 'a'] = 1; 
			for(int i = 1; i <= s.length() ; ++i){
				tot += root.hit(arr , i , vis);
				if(i < s.length()){
					vis[s.charAt(i) - 'a'] = 1;					
				}
			}
			char s0 = s.charAt(0);
			root.add(arr, 1, s0 - 'a');
		}
		return tot;
	}
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);		
		int N = sc.nextInt();
		String S[] = new String[N];
		for(int i = 0 ; i < N ; ++i){
			S[i] = sc.next();			
		}
		long ret = solve(S);
		System.out.println(ret);
	}
}

import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine());
        String[] strings = new String[n];
        Trie root = new Trie();
        for (int i = 0; i < n; i++) {
            String str = scanner.nextLine();
            strings[i] = str;
            char[] s = str.toCharArray();
            Trie tmp = root;
            for (int j = s.length - 1; j >= 0; j--) {
                int c = s[j] - 'a';
                if (tmp.children == null) tmp.children = new Trie[26];
                if (tmp.children[c] == null) tmp.children[c] = new Trie();
                tmp = tmp.children[c];
            }
            tmp.isWord = true;
        }
        long ans = 0;
        for (String str : strings) {
            char[] s = str.toCharArray();
            Trie tmp = root;
            Set<Integer> suffix = new HashSet<>();
            for (int j = s.length - 1; j >= 0; j--) {
                int c = s[j] - 'a';
                suffix.add(c);
                tmp = tmp.children[c];
                for (Integer sfx : suffix) {
                    if(tmp.children!=null && tmp.children[sfx]!=null && tmp.children[sfx].isWord) ans++;
                }
            }
        }
        System.out.println(ans-n);
    }

    private static class Trie {
        boolean isWord;
        Trie[] children;
    }
}

