public class Main implements Runnable{

	public static final int BASE = 987654321;
	public static final int MOD = 998_244_353;
	@SuppressWarnings("static-method")
	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * AtCoder Grand Contest 047 B問題
		 * 考察メモ
		 * まず|S| = |T|のとき、単に同じ文字列か比較してはい
		 * そうでないとする
		 * |S| > |T|のとき、Sの方のみ操作を行うことは明らか
		 * まず、Sの末尾|T|-1文字は一致してないと単純に合わせられないので、それを比較する
		 * とはいえ、任意の2ペアで比較するわけにもいかないので……？
		 * 各文字列について、末尾1, 2, ..., |S_i|文字を取った部分文字列、合計何個だっけ？
		 * あ、合計はΣ|S_i|なので10^6を超えない……なるほど
		 * set(x)を元の文字列がxであるようなものの集合とする
		 * 文字列a, bとaに含まれる文字cに対し、set(x) ∪ {c + b}≠∅ならば答えに1を加算
		 * これは2 * 10^7通りの文字列比較になるので、なんかいい感じに比較高速化したいが
		 * まぁRollingHashで雑に比較すれば良さそう
		 */
		int N = io.nextInt();
		Set<HashString> set = new HashSet<>(N);
		char[][] S = new char[N][];
		int[] hash = new int[N];
		for (int i = 0;i < N;++ i) {
			S[i] = io.nextChars();
			HashString put = new HashString(S[i], 0, S[i].length);
			set.add(put);
			hash[i] = put.hash;
		}
		long ans = 0;
		ModUtility mod = new ModUtility(new Prime(MOD));
		final int inverse = mod.inverse(64);
		IntBinaryOperator fun = (x, y) -> mod.multiply(mod.subtract(x, y), inverse);
		IntBinaryOperator fun2 = (x, y) -> mod.add(mod.multiply(x, 64), y);
		for (int i = 0;i < N;++ i) {
			char[] T = S[i];
			int useAlphabet = 1 << T[0] - 'a';
			int h = fun.applyAsInt(hash[i], T[0]);
			for (int j = 0;j < T.length - 1;++ j) {
				useAlphabet |= 1 << T[j + 1] - 'a';
				h = fun.applyAsInt(h, T[j + 1]);
				for (int k = 0;k < 26;++ k) {
					if ((useAlphabet >> k & 1) == 0) continue;
					HashString compare = new HashString((char)(k + 'a'), T, j + 2, T.length, fun2.applyAsInt(h, k + 'a'));
					if (set.contains(compare)) ++ ans;
				}
			}
		}
		io.println(ans);
	}

	class HashString {
		final int hash;
		final char[] s;
		final char addFirst;
		final int from, to;
		HashString(char[] s, int from, int to) {
			this.s = s;
			this.from = from;
			this.to = to;
			addFirst = 0;
			hash = calcHash();
		}
		HashString(char addFirst, char[] s, int from, int to, int hash) {
			this.s = s;
			this.from = from;
			this.to = to;
			this.addFirst = addFirst;
			this.hash = hash;
		}
		private int calcHash() {
			long hash = BASE;
			for (int i = to - 1;i >= from;-- i) {
				hash *= 64;
				hash += s[i];
				hash %= MOD;
			}
			return (int)hash;
		}
		@Override
		public boolean equals(Object o) {
			if (o instanceof HashString) {
				HashString hs = (HashString)o;
				if (hash != hs.hash) return false;
				return equals(this, hs);
			}
			return false;
		}
		public boolean equals(HashString a, HashString b) {
			int sFrom = a.from, sTo = a.to, tFrom = b.from, tTo = b.to;
			char[] s = a.s, t = b.s;
			if (sTo - sFrom != tTo - b.from) {
				if (sTo - sFrom + 1 == tTo - tFrom && a.addFirst != 0 && b.addFirst == 0) {
					if (a.addFirst == t[tFrom]) ++ tFrom;
					else return false;
				} else if (sTo - sFrom == tTo - tFrom + 1 && a.addFirst == 0 && b.addFirst != 0) {
					if (b.addFirst == s[sFrom]) ++ sFrom;
					else return false;
				} else return false;
			}
			for (int i = sFrom, j = tFrom;i < sTo;++ i, ++ j) {
				if (s[i] != t[j]) return false;
			}
			return true;
		}
		@Override
		public int hashCode() {
			return hash;
		}
		@Override
		public String toString() {
			String out = "";
			if (addFirst != 0) out += addFirst;
			for (int i = from;i < to;++ i) out += s[i];
			return "(" + hash + ", " + out + ")";
		}
	}

	/** デバッグ用コードのお供に */
	private static boolean DEBUG = false;
	/** 確保するメモリの大きさ(単位: MB)*/
	private static final long MEMORY = 64;
	private final FastIO io;
	private final String[] args;

