internal partial class Solver {

    class Trie {
        public Trie[] Child = new Trie[26];
        public int val = 0;

        static public void Add(Trie t, string s, int bit) {
            int index = 0;
            while (index < s.Length) {
                var d = s[index++] - 'a';
                if (t.Child[d] == null) t.Child[d] = new Trie();
                t = t.Child[d];
            }
            t.val |= bit;
        }
    }

    public void Run() {
        var n = ni();
        var S = ns(n);
#if false
