        S[0] = new string('b', 100000);
        S[1] = new string('a', 100000 - 1);*/
#endif
        var maxLen = S.Max(s => s.Length);


        long ans = 0;
        var target = new HashMap<string, int>(StringComparer.Ordinal);
        var trie = new Trie();
        foreach (var s in S) {
            Trie.Add(trie, new string(s.Substring(1).AsEnumerable().Reverse().ToArray()), 1 << (s[0] - 'a'));
        }
        var exist = new int[maxLen + 1];
        foreach (var s in S) {
            var b = new StringBuilder();
            exist[0] = 0;
            for (int i = 0; i < s.Length; i++) {
                if (i > 0) exist[i] = exist[i - 1];
                exist[i] |= 1 << (s[i] - 'a');
            }
            var current = trie;
            for (int i = s.Length - 1; i > 0; i--) {
                var d = s[i] - 'a';
                ans += PopCount((ulong)(current.val & exist[i]));
                current = current.Child[d];
                if (current == null) break;
            }
        }
        cout.WriteLine(ans);
    }

    private static int PopCount(ulong x) {
        x = (x & 0x5555555555555555UL) + ((x >> 1) & 0x5555555555555555UL);
        x = (x & 0x3333333333333333UL) + ((x >> 2) & 0x3333333333333333UL);
        x = (x + (x >> 4)) & 0x0f0f0f0f0f0f0f0fUL;
        x += x >> 8;
        x += x >> 16;
        x += x >> 32;
        return (int)(x & 0x7FLU);
    }

