public class RabinKarpHash {
    private const ulong MASK30 = (1UL << 30) - 1;
    private const ulong MASK31 = (1UL << 31) - 1;
    private const ulong MOD = (1UL << 61) - 1;
    private const ulong MASK61 = MOD;
    private ulong[] Data;
    private ulong[] Power;
    private readonly uint Base;
    private static readonly uint defaultBase = (uint)new Random().Next(1024, int.MaxValue);

    public RabinKarpHash() : this(defaultBase) { }

    public RabinKarpHash(uint @base) {
        Base = @base;
        Power = new ulong[64];
        Power[0] = 1;
        for (var i = 1; i < Power.Length; i++) {
            Power[i] = CalcMod(Mul(Power[i - 1], Base));
        }
    }

    public void Build(IList<uint> array) {
        Build(array.Count, i => array[i]);
    }

    public void Build(int n, Func<int, uint> create) {
        Data = new ulong[n + 1];
        if (Power.Length < n + 1) {
            var originalSize = Power.Length;
            Array.Resize(ref Power, n + 1);
            for (var i = originalSize; i < Power.Length; i++) {
                Power[i] = CalcMod(Mul(Power[i - 1], Base));
            }
        }
        ulong hash = 0;
        for (var i = 0; i < n; i++) {
            Data[i + 1] = hash = CalcMod(Mul(hash, Base) + create(i) + 1);
        }
    }

    private ulong Mul(ulong a, ulong b) {
        ulong ua = a >> 31, la = a & MASK31;
        ulong ub = b >> 31, lb = b & MASK31;
        var mid = la * ub + ua * lb;
        var midu = mid >> 30;
        var midd = mid & MASK30;
        return ua * ub * 2 + midu + (midd << 31) + la * lb;
    }

    private ulong CalcMod(ulong x) {
        var res = (x >> 61) + (x & MASK61);
        if (res >= MOD) {
            res -= MOD;
        }
        return res;
    }

    public ulong CalcHash(int begin, int end) { // [begin, end)
        return CalcMod(Data[end] + (MOD << 2) - Mul(Data[begin], Power[end - begin]) % MOD);
    }
}
