	public class TrieTree
	{
		private readonly int charCount_;
		private readonly char baseChar_;
		private readonly List<Node> nodes_;
		private readonly List<int[]> pathes_;

		public TrieTree(
			int capacity = 100000,
			int charCount = 26,
			char baseChar = 'a')
		{
			charCount_ = charCount;
			baseChar_ = baseChar;
			nodes_ = new List<Node>(capacity) { new Node(0, charCount_) };
			pathes_ = new List<int[]>();
		}

		public Node GetNode(int nodeID) => nodes_[nodeID];
		public Node GetNode(int wordID, int index)
			=> nodes_[pathes_[wordID][index + 1]];

		public void Add(string word) => Add(word, nodes_[0].Count);
		private void Add(string word, int wordID)
		{
			var path = new int[word.Length + 1];
			Node node = nodes_[0];
			for (int i = 0; i < word.Length; i++) {
				int c = ToIndex(word[i]);
				if (node.Children[c] == 0) {
					node.Children[c] = nodes_.Count();
					nodes_.Add(new Node(c, charCount_));
				}

				path[i + 1] = node.Children[c];
				++node.Count;
				node = nodes_[node.Children[c]];
			}

			pathes_.Add(path);
			++node.Count;
			node.EndWords.Add(wordID);
		}

		public bool Search(string word, bool prefix = false)
		{
			Node node = nodes_[0];
			for (int i = 0; i < word.Length; i++) {
				int c = ToIndex(word[i]);
				if (node.Children[c] == 0) {
					return false;
				}

				node = nodes_[node.Children[c]];
			}

			return prefix || node.EndWords.Count > 0;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public int ToIndex(char c) => c - baseChar_;

		public class Node
		{
			public int[] Children { get; set; }
			public List<int> EndWords { get; set; } = new List<int>();
			public int C { get; set; }
			public int Count { get; set; } = 0;
			public Node(int c, int charCount)
			{
				C = c;
				Children = new int[charCount];
			}
		}
	}

	public struct ModInt
	{
		public const long P = 200003;
		//public const long P = 1000000007;
		//public const long P = 998244353;

		public static ModInt Inverse(ModInt value) => Pow(value, P - 2);
		public static ModInt Pow(ModInt value, long k) => Pow(value.value_, k);
		public static ModInt Pow(long value, long k)
		{
			long ret = 1;
			for (k %= P - 1; k > 0; k >>= 1, value = value * value % P) {
				if ((k & 1) == 1) {
					ret = ret * value % P;
				}
			}
			return new ModInt(ret);
		}

		private long value_;

		public ModInt(long value)
			=> value_ = value;
		public ModInt(long value, bool mods)
		{
			if (mods) {
				value %= P;
				if (value < 0) {
					value += P;
				}
			}

			value_ = value;
		}

		public static ModInt operator +(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = (lhs.value_ + rhs.value_) % P;
			return lhs;
		}
		public static ModInt operator +(long lhs, ModInt rhs)
		{
			rhs.value_ = (lhs + rhs.value_) % P;
			return rhs;
		}
		public static ModInt operator +(ModInt lhs, long rhs)
		{
			lhs.value_ = (lhs.value_ + rhs) % P;
			return lhs;
		}

		public static ModInt operator -(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = (P + lhs.value_ - rhs.value_) % P;
			return lhs;
		}
		public static ModInt operator -(long lhs, ModInt rhs)
		{
			rhs.value_ = (P + lhs - rhs.value_) % P;
			return rhs;
		}
		public static ModInt operator -(ModInt lhs, long rhs)
		{
			lhs.value_ = (P + lhs.value_ - rhs) % P;
			return lhs;
		}

		public static ModInt operator *(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = lhs.value_ * rhs.value_ % P;
			return lhs;
		}
		public static ModInt operator *(long lhs, ModInt rhs)
		{
			rhs.value_ = lhs * rhs.value_ % P;
			return rhs;
		}
		public static ModInt operator *(ModInt lhs, long rhs)
		{
			lhs.value_ = lhs.value_ * rhs % P;
			return lhs;
		}

		public static ModInt operator /(ModInt lhs, ModInt rhs)
		{
			long exp = P - 2;
			while (exp > 0) {
				if (exp % 2 > 0) {
					lhs *= rhs;
				}

				rhs *= rhs;
				exp /= 2;
			}

			return lhs;
		}

		public static implicit operator ModInt(long n) => new ModInt(n, true);
		public long ToLong() => value_;
		public override string ToString() => value_.ToString();
	}

