public class Trie{
	static private int o,n;
	public int cnt=1;
	public long ans=0;
	public Nd root;
	public List<Nd> lih;
	public class Nd{
		public Nd[] ar;
		public int hb=0;
		public int c,f=0,n;
		public bool b=false;
		public Nd(int c,int f,int n){this.c=c-o;this.f=f;this.n=n;}
		public override string ToString(){
			var t="n:"+n.ToString("d2")+" f:"+f.ToString()+" c:"+(char)(c+o)+" ";
			if(ar==null){t+=new string('-',Trie.n);}
			else{for(int j=0;j<ar.Length;j++){t+=(b&&ar[j]!=null?(char)(j+o):'-');}}
			t+=" "+Binary(hb,Trie.n);
			return t;
		}
		public string Binary(long a,int b){
			string s=Convert.ToString(a,2);
			return (b>s.Length?new string('0',b-s.Length):"")+s;
		}
	}
	public Trie(int a,int z){
		n=z-a+1;
		o=a;
		root=new Nd(a-1,0,0);
		lih=new List<Nd>();
		lih.Add(root);
	}
	public void Add((string,int[]) t){
		var r=root;
		for(int j = 0;j<t.Item1.Length;j++) {
			if(t.Item1.Length==1){
				r.hb|=1<<(t.Item1[0]-o);
				break;
			}
			if(j==0){ans+=Pc(r.hb&(t.Item2[j]|(1<<(t.Item1[t.Item1.Length-1]-o))));}
			else{ans+=Pc(r.hb&t.Item2[j]);}
			if(j==t.Item1.Length-2){
				r.hb|=1<<(t.Item1[t.Item1.Length-1]-o);
			}
			if(!r.b){r.ar=new Nd[n];r.b=true;}
			if(r.ar[t.Item1[j]-o]==null){lih.Add(r=r.ar[t.Item1[j]-o]=new Nd(t.Item1[j],j+1,lih.Count));cnt++;}
			else{r=r.ar[t.Item1[j]-o];}
		}
	}
	private int Pc(int n){
		n-=(n>>1)&0x55555555;
		n=(n&0x33333333)+((n>>2)&0x33333333);
		return ((n+(n>>4)&0xF0F0F0F)*0x1010101)>>24;
    }
}
