    void calc()
    {
        int N = cin.nextInt();
        string[] S = new string[N];
        for (int i = 0; i < N; i++)
        {
            S[i] = cin.next();
        }
        IComparer<string> strlenComp = new StrLenComparer();
        Array.Sort(S, strlenComp);

        Node FirstNode = new Node();

        long ans = 0;

        for (int i = 0; i < N; i++)
        {
            Node NowNode = FirstNode;
            int[] num = new int[26];
            bool active = true;

            foreach(var c in S[i])
            {
                num[c - 'a']++;
            }

            for (int j = S[i].Length - 1; j >= 0; j--)
            {
                if (active)
                {
                    for (int k = 0; k < 26; k++)
                    {
                        if (num[k] == 0) continue;
                        if (NowNode.Next[k] != null && NowNode.Next[k].exist) ans++; 
                    }
                }
                char c = S[i][j];
                int p = c - 'a';
                num[p]--;
                if(NowNode.Next[p] == null)
                {
                    active = false;
                    NowNode.Next[p] = new Node();
                }
                NowNode = NowNode.Next[p];

            }
            NowNode.exist = true;
        }


        Console.WriteLine(ans);

    }

