			}
			Array.Sort(rs,(x,y)=>StrCmp(x,y));
			Dictionary<string,ulong> dic = new Dictionary<string, ulong>();
			long ans = 0;
			foreach (var e in rs)
			{
				ulong[] c1 = new ulong[e.Length+1];
				for (int i = e.Length-1; 0<=i; i--) {
					c1[i] = c1[i+1] | 1UL<<(e[i]-'a');
				}
				ulong o;
				if(dic.TryGetValue("",out o)){
					ans += NumberOfSetBits(o & c1[0]);
				}
				for (int i = 0; i < e.Length-2; i++)
				{
					if(dic.TryGetValue(e.Substring(0,i+1),out o)){
						ans += NumberOfSetBits(o & c1[i+1]);
					}
				}
				var s1 = e.Substring(0,e.Length-1);
				if(!dic.ContainsKey(s1)) dic[s1]=0;
				dic[s1] |= 1UL<<(e[e.Length-1]-'a');
			}




			Lib_IO.wm(ans);
		}
	}

	[CS.MethodImpl(256)] public static int NumberOfSetBits(ulong i) {
		i = i - ((i >> 1) & 0x5555555555555555UL);
		i = (i & 0x3333333333333333UL) + ((i >> 2) & 0x3333333333333333UL);
		return (int)(unchecked(((i + (i >> 4)) & 0xF0F0F0F0F0F0F0FUL) * 0x101010101010101UL) >> 56);
	}
    public static int StrCmp(string a,string b) {
        if (a.Length > b.Length) return 1;
        else if(a.Length < b.Length)return -1;
		var l = Math.Min(a.Length, b.Length);
        for (var i = 0; i < l; i++)
            if (a[i] < b[i]) return -1;
            else if (a[i] > b[i]) return 1;
        return 0;
    }












