class Trie{
	// 
	public List<int[]> E;
	public List<char> C;
	public List<long> Val;
	public List<int> Parent;
	public int Root;
	const int M = 26;


	public Trie(){
		E = new List<int[]>();
		C = new List<char>();
		Val = new List<long>();
		Parent = new List<int>();

		Root = 0;
		E.Add(new int[M]);
		C.Add('$');
		Val.Add(0);
		Parent.Add(-1);
	}
	public void Add(String s){
		Add(s, s.Length);
	}
	public void Add(String s, long v){
		// Add key: s, Value: v;
		int n = s.Length;
		int now = Root;
		for(int i=0;i<n;i++){
			int c = (int) (s[i] - 'a');
			if(E[now][c] <= 0){
				AddEdge(now, s[i]);
				now = E[now][c];
			} else {
				now = E[now][c];
			}
		}
		Val[now] = v;
	}
	public void Add(char[] s){
		Add(s, s.Length);
	}
	public void Add(char[] s, long v){
		// Add key: s, Value: v;
		int n = s.Length;
		int now = Root;
		for(int i=0;i<n;i++){
			int c = (int) (s[i] - 'a');
			if(E[now][c] <= 0){
				AddEdge(now, s[i]);
				now = E[now][c];
			} else {
				now = E[now][c];
			}
		}
		Val[now] = v;
	}
	void AddEdge(int now, char c){
		int nxt = E.Count;
		E.Add(new int[M]);
		C.Add(c);
		Val.Add(0);
		Parent.Add(now);
		E[now][c - 'a'] = nxt;
	}

	public bool Contains(String s){
		long v;
		return Contains(s, out v);
	}

	public int GetNode(char[] s, int length = -1){
		if(length == -1) length = s.Length;
		if(length == 0) return 0;
		int now = Root;
		for(int i=0;i<length;i++){
			now = E[now][s[i] - 'a'];
			if(now == 0){
				return -1;
			}
		}
		return now;
	}



	public bool Contains(String s, out long v){
		v = 0;
		if(s == ""){
			return false;
		}
		int n = s.Length;
		int now = Root;
		for(int i=0;i<n;i++){
			int c = (int) (s[i] - 'a');
			if(E[now][c] <= now){
				return false;
			}
			now = E[now][c];
		}
		v = Val[now];
		return v != 0;
	}

}

