    public class Trie<T> {
        private Trie<T>[] _child;
        public T Value { get; set; }
        private readonly int capacity;

        public Trie(int capacity) {
            this.capacity = capacity;
        }

        public Trie<T> GetOrCreate(IEnumerable<int> s) {
            var t = this;
            foreach (var d in s) {
                if (t._child == null) t._child = new Trie<T>[capacity];
                if (t._child[d] == null) t._child[d] = new Trie<T>(capacity);
                t = t._child[d];
            }
            return t;
        }
        public Trie<T> Get(IEnumerable<int> s) {
            var t = this;
            foreach (var d in s) {
                t = t.GetNext(d);
                if (t == null) break;
            }
            return t;
        }
        public Trie<T> GetNext(int x) {
            if (_child == null) return null;
            return _child[x];
        }
    }

    public class StringTrie<T> {
        private StringTrie<T>[] _child;
        public T Value { get; set; }
        private readonly int _capacity;
        private readonly Func<char, int> _charToInt;

        public StringTrie(int capacity, Func<char, int> charToInt) {
            this._capacity = capacity;
            this._charToInt = charToInt;
        }

        public StringTrie<T> GetOrCreate(IEnumerable<char> s) {
            var t = this;
            foreach (var c in s) {
                var d = _charToInt(c);
                if (t._child == null) t._child = new StringTrie<T>[_capacity];
                if (t._child[d] == null) t._child[d] = new StringTrie<T>(_capacity, _charToInt);
                t = t._child[d];
            }
            return t;
        }
        public StringTrie<T> Get(IEnumerable<char> s) {
            var t = this;
            foreach (var c in s) {
                t = t.GetNext(c);
                if (t == null) break;
            }
            return t;
        }
        public StringTrie<T> GetNext(char c) {
            if (_child == null) return null;
            return _child[_charToInt(c)];
        }
    }
    public void Run() {
        var n = ni();
        var S = ns(n);
        var maxLen = S.Max(s => s.Length);


        long ans = 0;
        var target = new HashMap<string, int>(StringComparer.Ordinal);
        var trie = new StringTrie<int>(26, c => c - 'a');
        foreach (var s in S) {
            var cc = trie.GetOrCreate(s.Substring(1).AsEnumerable().Reverse().ToArray());
            cc.Value |= 1 << (s[0] - 'a');
        }
        var exist = new int[maxLen + 1];
        foreach (var s in S) {
            var b = new StringBuilder();
            exist[0] = 0;
            for (int i = 0; i < s.Length; i++) {
                if (i > 0) exist[i] = exist[i - 1];
                exist[i] |= 1 << (s[i] - 'a');
            }
            var current = trie;
            for (int i = s.Length - 1; i > 0; i--) {
                ans += PopCount((ulong)(current.Value & exist[i]));
                current = current.GetNext(s[i]);
                if (current == null) break;
            }
        }
        cout.WriteLine(ans);
    }

    private static int PopCount(ulong x) {
        x = (x & 0x5555555555555555UL) + ((x >> 1) & 0x5555555555555555UL);
        x = (x & 0x3333333333333333UL) + ((x >> 2) & 0x3333333333333333UL);
        x = (x + (x >> 4)) & 0x0f0f0f0f0f0f0f0fUL;
        x += x >> 8;
        x += x >> 16;
        x += x >> 32;
        return (int)(x & 0x7FLU);
    }

