		private readonly int childCount_;
		private readonly Func<TKey, int> toIndex_;
		private readonly TValue initialValue_;
		private readonly List<Node> nodes_;
		private readonly int[][] wordNodeNumbers_;

		public TrieTree(
			int maxWordCount,
			int childCount,
			Func<TKey, int> toIndex,
			TValue initialValue,
			int nodeCapacity = 200000)
		{
			childCount_ = childCount;
			toIndex_ = toIndex;
			initialValue_ = initialValue;
			nodes_ = new List<Node>(nodeCapacity) { null, new Node(initialValue_, childCount_) };
			Root = nodes_[1];
			wordNodeNumbers_ = new int[maxWordCount][];
		}

		public Node Root { get; }
		public Node GetNode(int wordID, int count) => nodes_[wordNodeNumbers_[wordID][count]];
		public Node GetChild(Node node, TKey c) => nodes_[node.Children[toIndex_(c)]];

		public int WordCount => Root.AllCount;
		public int NodeCount => nodes_.Count - 1;

		public void Add(IReadOnlyList<TKey> word)
		{
			var numbers = new int[word.Count + 1];
			numbers[0] = 1;

			Node node = Root;
			for (int i = 0; i < word.Count; i++) {
				int c = toIndex_(word[i]);
				if (node.Children[c] == 0) {
					node.Children[c] = nodes_.Count();
					nodes_.Add(new Node(initialValue_, childCount_));
				}

				numbers[i + 1] = node.Children[c];
				++node.AllCount;
				node = nodes_[node.Children[c]];
			}

			++node.AllCount;
			++node.EndCount;

			wordNodeNumbers_[Root.AllCount - 1] = numbers;
		}

		public (bool exists, Node node) Find(IReadOnlyList<TKey> word, bool prefix = false)
		{
			Node node = Root;
			for (int i = 0; i < word.Count; i++) {
				int c = toIndex_(word[i]);
				if (node.Children[c] == 0) {
					return (false, null);
				}

				node = nodes_[node.Children[c]];
			}

			return prefix || node.EndCount > 0
				? (true, node)
				: (false, null);
		}

		public class Node
		{
			public TValue Value { get; set; }
			public int[] Children { get; }
			public int AllCount { get; set; } = 0;
			public int EndCount { get; set; } = 0;

			public Node(TValue value, int childCount)
			{
				Value = value;
				Children = new int[childCount];
			}
		}
	}

	public struct ModInt
	{
		public const long P = 200003;
		//public const long P = 1000000007;
		//public const long P = 998244353;

		public static ModInt Inverse(ModInt value) => Pow(value, P - 2);
		public static ModInt Pow(ModInt value, long k) => Pow(value.value_, k);
		public static ModInt Pow(long value, long k)
		{
			long ret = 1;
			for (k %= P - 1; k > 0; k >>= 1, value = value * value % P) {
				if ((k & 1) == 1) {
					ret = ret * value % P;
				}
			}
			return new ModInt(ret);
		}

		private long value_;

		public ModInt(long value)
			=> value_ = value;
		public ModInt(long value, bool mods)
		{
			if (mods) {
				value %= P;
				if (value < 0) {
					value += P;
				}
			}

			value_ = value;
		}

		public static ModInt operator +(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = (lhs.value_ + rhs.value_) % P;
			return lhs;
		}
		public static ModInt operator +(long lhs, ModInt rhs)
		{
			rhs.value_ = (lhs + rhs.value_) % P;
			return rhs;
		}
		public static ModInt operator +(ModInt lhs, long rhs)
		{
			lhs.value_ = (lhs.value_ + rhs) % P;
			return lhs;
		}

		public static ModInt operator -(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = (P + lhs.value_ - rhs.value_) % P;
			return lhs;
		}
		public static ModInt operator -(long lhs, ModInt rhs)
		{
			rhs.value_ = (P + lhs - rhs.value_) % P;
			return rhs;
		}
		public static ModInt operator -(ModInt lhs, long rhs)
		{
			lhs.value_ = (P + lhs.value_ - rhs) % P;
			return lhs;
		}

		public static ModInt operator *(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = lhs.value_ * rhs.value_ % P;
			return lhs;
		}
		public static ModInt operator *(long lhs, ModInt rhs)
		{
			rhs.value_ = lhs * rhs.value_ % P;
			return rhs;
		}
		public static ModInt operator *(ModInt lhs, long rhs)
		{
			lhs.value_ = lhs.value_ * rhs % P;
			return lhs;
		}

		public static ModInt operator /(ModInt lhs, ModInt rhs)
		{
			long exp = P - 2;
			while (exp > 0) {
				if (exp % 2 > 0) {
					lhs *= rhs;
				}

				rhs *= rhs;
				exp /= 2;
			}

			return lhs;
		}

		public static implicit operator ModInt(long n) => new ModInt(n, true);
		public long ToLong() => value_;
		public override string ToString() => value_.ToString();
	}

