using CompLib.Util;

public class Program
{
    private int N;
    private string[] S;
    private const long Mod1 = 1000000007;
    private const long Mod2 = (119 << 23) + 1;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        S = new string[N];
        for (int i = 0; i < N; i++)
        {
            S[i] = sc.Next();
        }

        Array.Sort(S, (l, r) => -l.Length.CompareTo(r.Length));

        // 1文字+のこり

        // 末尾 + 
        // 末尾が一致してる + 以前一致1文字
        // 

        var map = new HashMap<(long h1, int len), int>();
        long ans = 0;
        foreach (var t in S)
        {
            // tの末尾のハッシュ値
            long h1 = 0;
            int[] cnt = new int[26];
            for (int i = 0; i < t.Length; i++)
            {
                h1 *= 26;
                h1 += t[i] - 'a';
                h1 %= Mod1;
                cnt[t[i] - 'a']++;
            }

            ans += map[(h1, t.Length - 1)];

            long p1 = 1;
            h1 = 0;
            for (int i = 0; i < t.Length; i++)
            {
                int j = t.Length - i - 1;
                for (int c = 0; c < 26; c++)
                {
                    if (cnt[c] == 0) continue;
                    long hh1 = (h1 + p1 * c) % Mod1;
                    map[(hh1, i)]++;
                }

                cnt[t[j] - 'a']--;
                h1 += (t[j] - 'a') * p1;
                h1 %= Mod1;
                p1 *= 26;
                p1 %= Mod1;
            }
        }

        Console.WriteLine(ans);
    }

    public static void Main(string[] args) => new Program().Solve();
}

