	public class RollingHash
	{
		private const ulong MASK30 = (1UL << 30) - 1;
		private const ulong MASK31 = (1UL << 31) - 1;
		private const ulong MOD = (1UL << 61) - 1;
		private const ulong POSITIVIZER = MOD * 4;

		private static readonly ulong base_;
		private static readonly List<ulong> basePows_ = new List<ulong>(1000) { 1 };
		static RollingHash()
		{
			var random = new Random();
			base_ = (uint)random.Next(1 << 10, int.MaxValue);
		}

		private readonly ulong[] hash_;
		public string String { get; }
		public RollingHash(string s)
		{
			String = s;
			int n = s.Length;
			for (int i = basePows_.Count; i <= n; i++) {
				basePows_.Add(CalculateMod(basePows_[i - 1] * base_));
			}

			hash_ = new ulong[n + 1];
			for (int i = 0; i < n; i++) {
				hash_[i + 1] = CalculateMod(Multiply(hash_[i], base_) + s[i]);
			}
		}

		public ulong GetHash(Range range)
		{
			var (start, offset) = range.GetOffsetAndLength(String.Length);
			return GetHash(start, start + offset);
		}
		public ulong GetHash(int a, int b)
		{
			return CalculateMod(hash_[b] + POSITIVIZER - Multiply(hash_[a], basePows_[b - a]));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private ulong Multiply(ulong a, ulong b)
		{
			ulong msbA = a >> 31;
			ulong lsbA = a & MASK31;
			ulong msbB = b >> 31;
			ulong lsbB = b & MASK31;
			ulong mid = lsbA * msbB + msbA * lsbB;
			return msbA * msbB * 2 + (mid >> 30) + ((mid & MASK30) << 31) + lsbA * lsbB;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private ulong CalculateMod(ulong x)
		{
			ulong res = (x >> 61) + (x & MOD);
			if (res >= MOD) {
				res -= MOD;
			}

			return res;
		}
	}

	public struct ModInt
	{
		public const long P = 200003;
		//public const long P = 1000000007;
		//public const long P = 998244353;

		public static ModInt Inverse(ModInt value) => Pow(value, P - 2);
		public static ModInt Pow(ModInt value, long k) => Pow(value.value_, k);
		public static ModInt Pow(long value, long k)
		{
			long ret = 1;
			for (k %= P - 1; k > 0; k >>= 1, value = value * value % P) {
				if ((k & 1) == 1) {
					ret = ret * value % P;
				}
			}
			return new ModInt(ret);
		}

		private long value_;

		public ModInt(long value)
			=> value_ = value;
		public ModInt(long value, bool mods)
		{
			if (mods) {
				value %= P;
				if (value < 0) {
					value += P;
				}
			}

			value_ = value;
		}

		public static ModInt operator +(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = (lhs.value_ + rhs.value_) % P;
			return lhs;
		}
		public static ModInt operator +(long lhs, ModInt rhs)
		{
			rhs.value_ = (lhs + rhs.value_) % P;
			return rhs;
		}
		public static ModInt operator +(ModInt lhs, long rhs)
		{
			lhs.value_ = (lhs.value_ + rhs) % P;
			return lhs;
		}

		public static ModInt operator -(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = (P + lhs.value_ - rhs.value_) % P;
			return lhs;
		}
		public static ModInt operator -(long lhs, ModInt rhs)
		{
			rhs.value_ = (P + lhs - rhs.value_) % P;
			return rhs;
		}
		public static ModInt operator -(ModInt lhs, long rhs)
		{
			lhs.value_ = (P + lhs.value_ - rhs) % P;
			return lhs;
		}

		public static ModInt operator *(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = lhs.value_ * rhs.value_ % P;
			return lhs;
		}
		public static ModInt operator *(long lhs, ModInt rhs)
		{
			rhs.value_ = lhs * rhs.value_ % P;
			return rhs;
		}
		public static ModInt operator *(ModInt lhs, long rhs)
		{
			lhs.value_ = lhs.value_ * rhs % P;
			return lhs;
		}

		public static ModInt operator /(ModInt lhs, ModInt rhs)
		{
			long exp = P - 2;
			while (exp > 0) {
				if (exp % 2 > 0) {
					lhs *= rhs;
				}

				rhs *= rhs;
				exp /= 2;
			}

			return lhs;
		}

		public static implicit operator ModInt(long n) => new ModInt(n, true);
		public long ToLong() => value_;
		public override string ToString() => value_.ToString();
	}

