	public static ulong[] RollingHash(string value, bool fromlast=false){
		return RollingHash( Array.ConvertAll<char,uint>(value.ToCharArray(),x=>x), fromlast );
	}
	public static ulong[] RollingHash(uint[] value, bool fromlast=false){
		int MLEN = 2;
		ulong[][] BM = new ulong[][]{
			new ulong[] {123457UL, 4294967143UL},
			new ulong[] {223463UL, 4294966441UL},
			new ulong[] {323467UL, 4294965457UL},
			new ulong[] {423469UL, 4294964461UL},
			new ulong[] {523459UL, 4294963459UL},
		};

		var ret = new ulong[value.Length+1];
		var hs = new ulong[MLEN];
		for (int i = 0; i < value.Length; i++)
		{
			ret[i+1] = 1;
			int idx = (fromlast?value.Length-i-1:i);
			for (int j = 0; j < hs.Length; j++)
			{
				hs[j] = (hs[j] * BM[j][0] + value[idx]) % BM[j][1];
				ret[i+1] *= hs[j];
			}
		}

		return ret;
	}
    public static int StrCmp(string a,string b) {
        if (a.Length > b.Length) return 1;
        else if(a.Length < b.Length)return -1;
		var l = Math.Min(a.Length, b.Length);
        for (var i = 0; i < l; i++)
            if (a[i] < b[i]) return -1;
            else if (a[i] > b[i]) return 1;
        return 0;
    }












