    public static int StrCmp(string a,string b) {
        if (a.Length > b.Length) return 1;
        else if(a.Length < b.Length)return -1;
		var l = Math.Min(a.Length, b.Length);
        for (var i = 0; i < l; i++)
            if (a[i] < b[i]) return -1;
            else if (a[i] > b[i]) return 1;
        return 0;
    }












