	public class TrieTree
	{
		private readonly int childCount_;
		private readonly Func<char, int> toIndex_;
		private readonly Node root_;
		private readonly List<Node[]> pathes_;

		public TrieTree(
			int childCount,
			Func<char, int> toIndex)
		{
			childCount_ = childCount;
			toIndex_ = toIndex;
			root_ = new Node(childCount_);
			pathes_ = new List<Node[]>();
		}

		public Node GetNode(int wordID, int index) => pathes_[wordID][index + 1];
		public Node GetChild(Node node, char c) => node?.Children[toIndex_(c)];

		public void Add(string word) => Add(word, root_.Count);
		private void Add(string word, int wordID)
		{
			var path = new Node[word.Length + 1];
			path[0] = root_;

			Node node = root_;
			for (int i = 0; i < word.Length; i++) {
				int c = toIndex_(word[i]);
				if (node.Children[c] is null) {
					node.Children[c] = new Node(childCount_);
				}

				path[i + 1] = node.Children[c];
				++node.Count;
				node = node.Children[c];
			}

			pathes_.Add(path);
			++node.Count;
			node.EndWords.Add(wordID);
		}

		public (bool exists, Node node) Find(string word, bool prefix = false)
		{
			Node node = root_;
			for (int i = 0; i < word.Length; i++) {
				int c = toIndex_(word[i]);
				if (node.Children[c] is null) {
					return (false, null);
				}

				node = node.Children[c];
			}

			return prefix || node.EndWords.Count > 0
				? (true, node)
				: (false, null);
		}

		public class Node
		{
			public Node[] Children { get; }
			public List<int> EndWords { get; } = new List<int>();
			public int Count { get; set; } = 0;
			public Node(int childCount)
			{
				Children = new Node[childCount];
			}
		}
	}

	public struct ModInt
	{
		public const long P = 200003;
		//public const long P = 1000000007;
		//public const long P = 998244353;

		public static ModInt Inverse(ModInt value) => Pow(value, P - 2);
		public static ModInt Pow(ModInt value, long k) => Pow(value.value_, k);
		public static ModInt Pow(long value, long k)
		{
			long ret = 1;
			for (k %= P - 1; k > 0; k >>= 1, value = value * value % P) {
				if ((k & 1) == 1) {
					ret = ret * value % P;
				}
			}
			return new ModInt(ret);
		}

		private long value_;

		public ModInt(long value)
			=> value_ = value;
		public ModInt(long value, bool mods)
		{
			if (mods) {
				value %= P;
				if (value < 0) {
					value += P;
				}
			}

			value_ = value;
		}

		public static ModInt operator +(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = (lhs.value_ + rhs.value_) % P;
			return lhs;
		}
		public static ModInt operator +(long lhs, ModInt rhs)
		{
			rhs.value_ = (lhs + rhs.value_) % P;
			return rhs;
		}
		public static ModInt operator +(ModInt lhs, long rhs)
		{
			lhs.value_ = (lhs.value_ + rhs) % P;
			return lhs;
		}

		public static ModInt operator -(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = (P + lhs.value_ - rhs.value_) % P;
			return lhs;
		}
		public static ModInt operator -(long lhs, ModInt rhs)
		{
			rhs.value_ = (P + lhs - rhs.value_) % P;
			return rhs;
		}
		public static ModInt operator -(ModInt lhs, long rhs)
		{
			lhs.value_ = (P + lhs.value_ - rhs) % P;
			return lhs;
		}

		public static ModInt operator *(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = lhs.value_ * rhs.value_ % P;
			return lhs;
		}
		public static ModInt operator *(long lhs, ModInt rhs)
		{
			rhs.value_ = lhs * rhs.value_ % P;
			return rhs;
		}
		public static ModInt operator *(ModInt lhs, long rhs)
		{
			lhs.value_ = lhs.value_ * rhs % P;
			return lhs;
		}

		public static ModInt operator /(ModInt lhs, ModInt rhs)
		{
			long exp = P - 2;
			while (exp > 0) {
				if (exp % 2 > 0) {
					lhs *= rhs;
				}

				rhs *= rhs;
				exp /= 2;
			}

			return lhs;
		}

		public static implicit operator ModInt(long n) => new ModInt(n, true);
		public long ToLong() => value_;
		public override string ToString() => value_.ToString();
	}

