			return array;
		}

		private static readonly int[] delta4_ = { 1, 0, -1, 0, 1 };
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static void DoAt4(int i, int j, int imax, int jmax, Action<int, int> action)
		{
			for (int dn = 0; dn < 4; dn++) {
				int d4i = i + delta4_[dn];
				int d4j = j + delta4_[dn + 1];
				if ((uint)d4i < (uint)imax && (uint)d4j < (uint)jmax) {
					action(d4i, d4j);
				}
			}
		}

		private static readonly int[] delta8_ = { 1, 0, -1, 0, 1, 1, -1, -1, 1 };
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static void DoAt8(int i, int j, int imax, int jmax, Action<int, int> action)
		{
			for (int dn = 0; dn < 8; dn++) {
				int d8i = i + delta8_[dn];
				int d8j = j + delta8_[dn + 1];
				if ((uint)d8i < (uint)imax && (uint)d8j < (uint)jmax) {
					action(d8i, d8j);
				}
			}
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static void ForEachSubBit(int bit, Action<int> action)
		{
			for (int sub = bit; sub >= 0; sub--) {
				sub &= bit;
				action(sub);
			}
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static string Reverse(string src)
		{
			var chars = src.ToCharArray();
			for (int i = 0, j = chars.Length - 1; i < j; i++, j--) {
				var tmp = chars[i];
				chars[i] = chars[j];
				chars[j] = tmp;
			}
			return new string(chars);
		}
	}

	public class Scanner
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private readonly string filePath_;
		private readonly Func<string> reader_;
		private string[] buf_;
		private int index_;

		public Scanner(string file = "")
		{
			if (string.IsNullOrWhiteSpace(file)) {
				reader_ = Console.ReadLine;
			} else {
				filePath_ = file;
				var fs = new StreamReader(file);
				reader_ = fs.ReadLine;
			}
			buf_ = new string[0];
			index_ = 0;
		}

		public string NextLine() => reader_();
		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = reader_();
			while (st == "") {
				st = reader_();
			}

			buf_ = st.Split(delimiter_, StringSplitOptions.RemoveEmptyEntries);
			if (buf_.Length == 0) {
				return Next();
			}

			index_ = 0;
			return buf_[index_++];
		}

		public int Int() => int.Parse(Next());
		public long Long() => long.Parse(Next());
		public double Double() => double.Parse(Next());

		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Int() + add;
			}
			return Array;
		}

		public long[] ArrayLong(int N, long add = 0)
		{
			long[] Array = new long[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Long() + add;
			}
			return Array;
		}

		public double[] ArrayDouble(int N, double add = 0)
		{
			double[] Array = new double[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Double() + add;
			}
			return Array;
		}

		public void Save(string text)
		{
			if (string.IsNullOrWhiteSpace(filePath_)) {
				return;
			}

			File.WriteAllText(filePath_ + "_output.txt", text);
		}
	}

	public static class Extensions
	{
		public static string Join<T>(this IEnumerable<T> values, string separator = "")
			=> string.Join(separator, values);
	}
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using static System.Console;
using static System.Math;

namespace AtTest.AGC_047
{
    class B
    {
        static void Main(string[] args)
        {
            var sw = new System.IO.StreamWriter(OpenStandardOutput()) { AutoFlush = false };
            SetOut(sw);

            Method(args);

            Out.Flush();
        }

        static void Method(string[] args)
        {
            int n = ReadInt();
            string[] ss = new string[n];
            for(int i = 0; i < n; i++)
            {
                ss[i] = Read();
            }
            Array.Sort(ss,(a,b)=>a.Length-b.Length);

            Trie trie = new Trie();
            int res = 0;
            for(int i = 0; i < n; i++)
            {
                res += trie.Count(ss[i]);
                trie.AddWord(ss[i]);
            }

            WriteLine(res);
        }

        public class Node
        {
            public Dictionary<char, int> edges;
            public int[] cnts;

            public Node()
            {
                edges = new Dictionary<char, int>();
                cnts = new int[26];
            }
        }

        public class Trie
        {
            public List<Node> nodes;

            public Trie()
            {
                nodes = new List<Node>();
                nodes.Add(new Node());
                for (int i = 0; i < 26; i++)
                {
                    nodes[0].edges.Add((char)('a' + i), i + 1);
                    nodes.Add(new Node());
                }
            }

            public void AddWord(string s)
            {
                int now = 0;
                for (int i = s.Length - 1; i > 0; i--)
                {
                    char c = s[i];
                    if (nodes[now].edges.ContainsKey(c))
                    {
                        now = nodes[now].edges[c];
                    }
                    else
                    {
                        nodes[now].edges.Add(c, nodes.Count);
                        nodes.Add(new Node());
                    }
                }
                nodes[now].cnts[s[0] - 'a']++;
            }

            public int Count(string s)
            {
                int[] cnts = new int[26];
                for(int i = 0; i < s.Length; i++)
                {
                    cnts[s[i] - 'a']++;
                }

                int cnt = 0;
                int now = 0;
                for(int i = 0; i < 26; i++)
                {
                    if (cnts[i] > 0)
                    {
                        cnt += nodes[now].cnts[i];
                    }
                }
                for (int i =  s.Length - 1; i > 0; i--)
                {
                    cnts[s[i] - 'a']--;
                    if (!nodes[now].edges.ContainsKey(s[i]))
                    {
                        break;
                    }
                    now = nodes[now].edges[s[i]];
                    for(int j = 0; j < 26; j++)
                    {
                        if (cnts[j] > 0)
                        {
                            cnt += nodes[now].cnts[j];
                        }
                    }
                }

                return cnt;
            }
        }

        private static string Read() { return ReadLine(); }
        private static char[] ReadChars() { return Array.ConvertAll(Read().Split(), a => a[0]); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }
    }
}

