public class RabinKarpHash {
    private ulong[] Data;
    private ulong[] Power;
    private uint P;

    public RabinKarpHash(uint p) {
        this.P = p;
    }

    public void Build(IEnumerable<int> sequence) {
        int size = sequence.Count();
        Data = new ulong[size + 1];
        Power = new ulong[size + 1];
        Data[0] = 0;
        Power[0] = 1;
        ulong hash = 0;
        int index = 1;
        foreach (int x in sequence) {
            hash = (Mul(hash, P) + (ulong)(x + 1)) % MOD;
            Data[index] = hash;
            Power[index] = Mul(Power[index - 1], P);
            index++;
        }
    }
    const ulong MASK30 = (1UL << 30) - 1;
    const ulong MASK31 = (1UL << 31) - 1;
    const ulong MOD = (1UL << 61) - 1;
    const ulong MASK61 = MOD;

    ulong Mul(ulong a, ulong b) {
        ulong au = a >> 31, ad = a & MASK31;
        ulong bu = b >> 31, bd = b & MASK31;
        ulong mid = ad * bu + au * bd;
        ulong midu = mid >> 30;
        ulong midd = mid & MASK30;
        return CalcMod(au * bu * 2 + midu + (midd << 31) + ad * bd);
    }

    ulong CalcMod(ulong x) {
        ulong xu = x >> 61, xd = x & MASK61;
        ulong res = xu + xd;
        if (res >= MOD) res -= MOD;
        return res;
    }
    public ulong FindHash(int begin, int end) { // [begin, end)
        var res = (Data[end] + MOD - (Data[begin] * Power[end - begin] % MOD)) % MOD;
        return res;
    }
}
