public class Solver
{
	public void Solve()
	{
		long N = GetLong();
		var S = Range(0, N).Select(_ => GetString().Select(x => (long)(x - 'a')).ToArray()).ToArray();
		for(long i = 0; i < N; i++)
			Array.Reverse(S[i]);

		long MAX = S.Sum(x => x.Length) + 1;
		var child = Range(0, MAX).Select(_ => new long[26]).ToArray();
		var isEnd = new bool[MAX];
		var paths = Range(0, N).Select(_ => new List<long>()).ToArray();

		long cnt = 1;
		for(long i = 0; i < N; i++)
		{
			long v = 0;
			foreach(var c in S[i])
			{
				paths[i].Add(v);
				if(child[v][c] == 0)
					child[v][c] = cnt++;

				v = child[v][c];
			}
			isEnd[v] = true;
		}

		long ans = 0;
		for(long i = 0; i < N; i++)
		{
			var suffix = new HashSet<long>();
			for(long j = S[i].Length - 1; j >= 0; j--)
			{
				suffix.Add(S[i][j]);
				long v = paths[i][(int)j];
				foreach(var c in suffix)
				{
					if(isEnd[child[v][c]])
						ans++;
				}
			}
		}

		WriteLine(ans - N);
	}
}

