    public void Run() {
        var n = ni();
        var S = ns(n);
        var hist = new HashMap<ulong, int>();
        Array.Sort(S, (s1, s2) => s1.Length.CompareTo(s2.Length));
        long ans = 0;
        foreach (var s in S) {
            var rhash = new RabinKarpHash(1013);
            rhash.Build(s.Select(c => c - 'a').ToArray());
            int used = 0;
            for (int i = 0; i < s.Length; i++) {
                used |= 1 << (s[i] - 'a');

                var bit = (ulong)hist[rhash.CalcHash(i + 1, s.Length)];
                ans += PopCount((ulong)used & bit);
            }

            hist[rhash.CalcHash(1, s.Length)] |= 1 << (s[0] - 'a');
        }
        cout.WriteLine(ans);
    }

    private static int PopCount(ulong x) {
        x = (x & 0x5555555555555555UL) + ((x >> 1) & 0x5555555555555555UL);
        x = (x & 0x3333333333333333UL) + ((x >> 2) & 0x3333333333333333UL);
        x = (x + (x >> 4)) & 0x0f0f0f0f0f0f0f0fUL;
        x += x >> 8;
        x += x >> 16;
        x += x >> 32;
        return (int)(x & 0x7FLU);
    }
}


