public class RabinKarpHash {
    const ulong MASK30 = (1UL << 30) - 1;
    const ulong MASK31 = (1UL << 31) - 1;
    const ulong MOD = (1UL << 61) - 1;
    const ulong MASK61 = MOD;
    private ulong[] Data;
    private ulong[] Power;
    private uint Base;

    public RabinKarpHash(uint @base) {
        Base = @base;
    }

    public void Build(IList<int> array) {
        Build(array.Count, i => array[i]);
    }

    public void Build(int n, Func<int, int> create) {
        Data = new ulong[n + 1];
        Power = new ulong[n + 1];
        Data[0] = 0;
        Power[0] = 1;
        ulong hash = 0;
        int index = 1;
        for (int i = 0; i < n; i++) {
            var x = create(i);
            hash = CalcMod(Mul(hash, Base) + (ulong)(x + 1));
            Data[index] = hash;
            Power[index] = CalcMod(Mul(Power[index - 1], Base));
            index++;
        }
    }

    ulong Mul(ulong a, ulong b) {
        ulong au = a >> 31, ad = a & MASK31;
        ulong bu = b >> 31, bd = b & MASK31;
        ulong mid = ad * bu + au * bd;
        ulong midu = mid >> 30;
        ulong midd = mid & MASK30;
        return au * bu * 2 + midu + (midd << 31) + ad * bd;
    }

    ulong CalcMod(ulong x) {
        ulong xu = x >> 61, xd = x & MASK61;
        ulong res = xu + xd;
        if (res >= MOD) res -= MOD;
        return res;
    }

    public ulong CalcHash(int begin, int end) { // [begin, end)
        return CalcMod(Data[end] + (MOD << 2) - Mul(Data[begin], Power[end - begin]) % MOD);
    }
}
