class RollingHash2{
	String S;
	RollingHash Left, Right;
	public RollingHash2(String S_){
		S = S_;
		Left = new RollingHash(S, 2525, (long) 1e9 + 7);
		Right = new RollingHash(S, 1234567, (long) 1e9 + 9);
	}
	public long GetHash(int strt,int len){
		long h1 = Left.GetHash(strt, len);
		long h2 = Right.GetHash(strt, len);
		return (h1 >> 5) ^ h2;
	}

}



class RollingHash{

	long[] Hash;
	long[] Base;
	String S;
	long mod;
	int N;

	public RollingHash(String s_,long base_=2525,long mod_=(long)1e9+7){
		mod=mod_;
		S=s_;
		N=S.Length;
		Hash=new long[N+1];

		Base=new long[N+1];
		Base[0]=1;
		Base[1]=base_;

		for(int i=1;i<N;i++){
			Base[i+1]=Base[i]*Base[1];
			if(Base[i+1]>=mod)Base[i+1]%=mod;
		}

		Hash[0]=0;
		Hash[1]=(long)S[0];
		for(int i=1;i<N;i++){
			Hash[i+1]=Hash[i]*Base[1]+(long)S[i];
			if(Hash[i+1]>=mod)Hash[i+1]%=mod;
		}
	}

	public long GetHash(int strt,int len){
		//return hash of S.Substring(strt,len);
		if(len==0)return 0;
		if(strt+len>=N)len=N-strt;
		long ret=Hash[strt+len]+mod-(Hash[strt]*Base[len]>=mod?Hash[strt]*Base[len]%mod:Hash[strt]*Base[len]);
		return ret>=mod?ret%mod:ret;
	}


}

using System;
