public class Program
{
    private int N;
    private string[] S;
    private const long Mod1 = 1000000007;
    private const long Mod2 = (119 << 23) + 1;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        S = new string[N];
        for (int i = 0; i < N; i++)
        {
            S[i] = sc.Next();
        }

        Array.Sort(S, (l, r) => -l.Length.CompareTo(r.Length));

        // 1文字+のこり

        // 末尾 + 
        // 末尾が一致してる + 以前一致1文字
        // 

        var map = new HashMap<(long h1, long h2, int len, char ch), int>();
        long ans = 0;
        foreach (var t in S)
        {
            // tの末尾のハッシュ値
            long h1 = 0;
            long h2 = 0;
            int[] cnt = new int[26];
            for (int i = 1; i < t.Length; i++)
            {
                h1 *= 26;
                h2 *= 26;
                h1 += t[i] - 'a';
                h2 += t[i] - 'a';
                h1 %= Mod1;
                h2 %= Mod2;
                cnt[t[i] - 'a']++;
            }

            cnt[t[0] - 'a']++;
            ans += map[(h1, h2, t.Length - 1, t[0])];
            long p1 = 1;
            long p2 = 1;
            h1 = 0;
            h2 = 0;
            for (int i = 0; i < t.Length; i++)
            {
                int j = t.Length - i - 1;
                for (int c = 0; c < 26; c++)
                {
                    if (cnt[c] == 0) continue;
                    map[(h1, h2, i, (char) (c + 'a'))]++;
                }

                cnt[t[j] - 'a']--;
                h1 += (t[j] - 'a') * p1;
                h1 %= Mod1;
                h2 += (t[j] - 'a') * p2;
                h2 %= Mod2;
                p1 *= 26;
                p1 %= Mod1;
                p2 *= 26;
                p2 %= Mod2;
            }
        }

        Console.WriteLine(ans);
    }

    public static void Main(string[] args) => new Program().Solve();
}

