public class RabinKarpHash {
    private ulong[] Data;
    private ulong[] Power;
    private uint P;

    public RabinKarpHash(uint p) {
        this.P = p;
    }

    public void Build(IEnumerable<int> sequence) {
        int size = sequence.Count();
        Data = new ulong[size + 1];
        Power = new ulong[size + 1];
        Data[0] = 0;
        Power[0] = 1;
        unchecked {
            ulong hash = 0;
            int index = 1;
            foreach (int x in sequence) {
                hash = hash * P + (ulong)(x + 1);
                Data[index] = hash;
                Power[index] = Power[index - 1] * P;
                index++;
            }
        }
    }

    public ulong FindHash(int begin, int end) { // [begin, end)
        unchecked {
            return Data[end] - Data[begin] * Power[end - begin];
        }
    }
}
