			}
			Array.Sort(rs,(x,y)=>StrCmp(x,y));
			Dictionary<ulong,ulong> dic = new Dictionary<ulong, ulong>();
			long ans = 0;
			foreach (var e in rs)
			{
				ulong[] c1 = new ulong[e.Length+1];
				for (int i = e.Length-1; 0<=i; i--) {
					c1[i] = c1[i+1] | 1UL<<(e[i]-'a');
				}
				ulong o;
				ulong hs = 0;
				for (int i = 0; i < e.Length; i++)
				{
					if(dic.TryGetValue(hs,out o)){
						ans += NumberOfSetBits(o & c1[i]);
					}
					if(i==e.Length-1) break;
					hs = (hs * 123457UL + e[i]-'a'+1) % 4294967143UL;
				}
				if(!dic.ContainsKey(hs)) dic[hs]=0;
				dic[hs] |= 1UL<<(e[e.Length-1]-'a');
			}




