using System;
using System.Collections.Generic;
class Program
{
	static void Main(string[] args)
	{
		int N = int.Parse(Console.ReadLine());
		var dic = new Dictionary<string,int>[1000001];
		for(var i=0;i<=1000000;i++){
			dic[i] = new Dictionary<string,int>();
		}
		for(var i=0;i<N;i++){
			string s = Console.ReadLine();
			int l = s.Length;
			if(dic[l].ContainsKey(s)){
				dic[l][s]++;
			} else {
				dic[l][s] = 1;
			}
		}
		long ans = 0;
		for(var i=0;i<=1000000;i++){
			foreach(var d in dic[i].Keys){
				for(var j=0;j<=i;j++){
					foreach(var e in dic[j].Keys){
						int d1 = d.Length-1;
						int e1 = e.Length-1;
						int ct = 0;
						bool flag = true;
						bool flag2 = true;
						while(true){
							if(d.Substring(d1,1)==e.Substring(e1,1)){
								d1--;
								e1--;
								if(e1==-1){
									break;
								}
								if(d1==-1){
									flag2 = false;
									break;
								}
							} else {
								d1--;
								if(d1<0){
 									flag2 = false;
                                  	break;
								}
								if(flag==false){
									flag2 = false;
									break;
								} else {
									flag = false;
								}
							}
						}
						if(flag2){
							ans++;
						}
					}
				}
			}
		}
		Console.WriteLine(ans-N);
	}
}

