        int n = sc.Int;
        var trie = new Trie('a', 26);
        var s = new string[n];
        for (int i = 0; i < n; i++)
        {
            s[i] = sc.Str;
            s[i] = new string(s[i].ToCharArray().Reverse().ToArray());
            trie.insert(s[i]);
        }
        long ans = 0;
        for (int i = 0; i < n; i++)
        {
            if (s[i].Length == 1) {
                ++ans;
                continue;
            }
            var cnt = new int[26];
            foreach (var item in s[i])
            {
                ++cnt[item - 'a'];
            }
            ans += trie.calc(s[i], cnt);
        }
        Prt(ans - n);
    }
}

