class Trie {
    public int cnt, dep;
    private readonly char fir;
    private readonly int len;
    Trie[] childs;

    public Trie(char fir, int len) : this(fir, len, 0) {}
    Trie(char fir, int len, int dep) {
        cnt = 0;
        this.dep = dep;
        this.fir = fir;
        this.len = len;
        childs = new Trie[len];
    }

    public void insert(string s) {
        if (dep == s.Length) {
            ++cnt;
            return;
        }
        if (childs[s[dep] - fir] == null) childs[s[dep] - fir] = new Trie(fir, len, dep + 1);
        childs[s[dep] - fir].insert(s);
    }
    public int calc(string s, int[] cnts) {
        if (dep == s.Length) {
            return 0;
        }
        int res = 0;
        for (int i = 0; i < childs.Length; i++)
        {
            if (cnts[i] > 0 && childs[i] != null) {
                res += childs[i].cnt;
            }
        }
        --cnts[s[dep] - fir];
        return res + childs[s[dep] - fir].calc(s, cnts);
    }
}

