class TRIE{
  constructor(){
    this.tree = [{last:false}];
  }
  search(s){
    var id = 0, tr = this.tree;
    for(var i = 0; i < s.length; i++){
      if(tr[id][s[i]] === undefined)return false;
      id = tr[id][s[i]];
    }
    return tr[id].last;
  }
  add(s){
    var id = 0, tr = this.tree, i = 0;
    for(; i < s.length; i++){
      if(tr[id][s[i]] === undefined)break;
      id = tr[id][s[i]];
    }
    for(; i < s.length; i++){
      id = tr[id][s[i]] = tr.length;
      tr.push({last:false});
    }
    tr[id].last = true;
  }
  searchAndAdd(s){
    var id = 0, tr = this.tree, i = 0;
    for(; i < s.length; i++){
      if(tr[id][s[i]] === undefined)break;
      id = tr[id][s[i]];
    }
    if(i === s.length){
      if(tr[id].last)return true;
      tr[id].last = true;
      return false;
    }
    for(; i < s.length; i++){
      id = tr[id][s[i]] = tr.length;
      tr.push({last:false});
    }
    tr[id].last = true;
    return false;
  }
  next(id,s){
    var tr = this.tree;
    if(tr[id][s] === undefined){
      id = tr[id][s] = tr.length;
      tr.push({last:false});
    }else id = tr[id][s];
    return id;
  }
}

