func fs(as, bs string) bool {
	a := []byte(as)
	b := []byte(bs)
	if len(a) <= len(b) {
		return false
	}
	if len(b) == 1 {
		for _, i := range a {
			if i == b[0] {
				return true
			}
		}
		return false
	}
	if len(b) == 2 {
		if !(a[len(a)] == b[1]) {
			return false
		}
		a = a[:len(a)-1]
		for _, i := range a {
			if i == b[0] {
				return true
			}
		}
	}
	if reflect.DeepEqual(b[1:], a[len(a)-len(b)+1:]) {
		for _, i := range a[:len(a)-len(b)+1] {
			if b[0] == i {
				return true
			}
		}
	}
	return false
}

