		for _, r := range S[i] {
			memo[r-'a']++
		}

		for j := 0; j < len(S[i]); j++ {
			base := S[i][:j]

			if !trie.FindStartWith(base) {
				break
			}

			for k := 0; k < ALPHABET_NUM; k++ {
				if memo[k] > 0 {
					key := base + string(k+'a')
					if trie.Find(key) {
						ans++
					}
				}
			}

			memo[S[i][j]-'a']--
		}

		trie.Insert(S[i])
	}

