	if a >= 0 {
		return a
	}
	return -a
}

func lowerBound(a []int, x int) int {
	idx := sort.Search(len(a), func(i int) bool {
		return a[i] >= x
	})
	return idx
}

func upperBound(a []int, x int) int {
	idx := sort.Search(len(a), func(i int) bool {
		return a[i] > x
	})
	return idx
}

func check(a, b string) bool {
	if a == b {
		return true
	}
	i := 0
	for i < len(a) {
		if a[i] == b[0] {
			break
		}
		i++
	}
	if len(a) == i {
		return false
	}
	a = a[i:]
	d := len(a) - len(b)
	if d > 0 {
		a = string(a[0]) + a[d+1:]
	}
	return a == b
}

func rev(s []byte) string {
	N := len(s)
	for i := 0; i < N/2; i++ {
		s[i], s[N-1-i] = s[N-1-i], s[i]
	}
	return string(s)
}

