func main() {
	sc.Split(bufio.ScanWords)
	n := nextInt()
	ss := make([]string, 0)
	m := make(map[string]bool)
	for i := 0; i < n; i++ {
		s := nextString()
		m[s] = true
		if len(s) == 1 {
			continue
		}
		ss = append(ss, s)
	}

	used := make(map[string]bool)
	ans := 0

	memo := make(map[string]int)

	var dfs func(s, o string) int
	dfs = func(s, o string) int {
		if v, ok := memo[s]; ok {
			if used[o+":"+s] {
				return 0
			}
			if m[s] {
				used[o+":"+s] = true
				return v
			}
			return 0
		}

		cnt := 0
		if m[s] && !used[o+":"+s] {
			used[o+":"+s] = true
			cnt++
		}

		if len(s) > 1 {
			t1 := s[1:]
			t2 := s[0:1] + s[2:]
			cnt += dfs(t1, o)
			cnt += dfs(t2, o)
		}

		memo[s] = cnt
		used[o+":"+s] = true

		return cnt
	}

	// memo = make(map[string]int)
	for _, s := range ss {
		m[s] = false
		c := dfs(s, s)
		ans += c
		m[s] = true
	}

	fmt.Println(ans)
}

