func main() {
	n, an, an2 := 0, 0, 0
	var s []string
	fmt.Scanf("%d", &n)
	sc := bufio.NewScanner(os.Stdin)
	for i := 0; i < n; i++ {
		sc.Scan()
		s = append(s, sc.Text())
	}
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			if i == j {
				continue
			}
			if s[i] == s[j] {
				an2++
				continue
			}
			if fs(s[i], s[j]) {
				an++
			}
		}
	}
	fmt.Println(an + an2/2)
}
func fs(as, bs string) bool {
	a := []byte(as)
	b := []byte(bs)
	if len(b) == 1 {
		for _, i := range a {
			if i == b[0] {
				return true
			}
		}
		return false
	}
	if len(b) == 2 {
		if !(a[len(a)-1] == b[1]) {
			return false
		}
		var tmp int
		for _, i := range a {
			if i == b[0] {
				tmp = 1
			}
			if tmp == 1 && i == b[1] {
				return true
			}
		}
	}
	for {
		if len(a) > 1 {
			if a[0] == b[0] {
				break
			}

			a = a[1:]
		} else {
			return false
		}
	}
	for {
		if len(a) > 2 {
			if a[1] == b[1] {
				if reflect.DeepEqual(a, b) {
					return true
				} else {
					return false
				}
			}
			tmp := a[1]
			a = a[1:]
			a[1] = tmp
		} else {
			return false
		}
	}
}

