	sc.Scan()
	return sc.Text()
}

// min, max, asub, absなど基本関数
func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func asub(a, b int) int {
	if a > b {
		return a - b
	}
	return b - a
}

func abs(a int) int {
	if a >= 0 {
		return a
	}
	return -a
}

func lowerBound(a []int, x int) int {
	idx := sort.Search(len(a), func(i int) bool {
		return a[i] >= x
	})
	return idx
}

func upperBound(a []int, x int) int {
	idx := sort.Search(len(a), func(i int) bool {
		return a[i] > x
	})
	return idx
}

func check(a, b string) bool {
	if a == b {
		return true
	}
	i := 0
	for i < len(a) {
		if a[i] == b[0] {
			break
		}
		i++
	}
	if len(a) == i {
		return false
	}
	a = a[i:]
	d := len(a) - len(b)
	if d > 0 {
		a = string(a[0]) + a[d+1:]
	}
	return a == b
}

func rev(s []byte) string {
	N := len(s)
	for i := 0; i < N/2; i++ {
		s[i], s[N-1-i] = s[N-1-i], s[i]
	}
	return string(s)
}

func check2(a, b string) bool {
	if len(a) > len(b) {
		return false
	}
	for i := 0; i < len(a)-1; i++ {
		if a[i] != b[i] {
			return false
		}
	}
	for i := len(a) - 1; i < len(b); i++ {
		if a[len(a)-1] == b[i] {
			return true
		}
	}
	return false
}

func main() {
	sc.Split(bufio.ScanWords)
	sc.Buffer([]byte{}, 1000000)
	N := getInt()
	s := make([]string, N)
	for i := 0; i < N; i++ {
		s[i] = rev([]byte(getString()))
	}
	sort.Strings(s)
	// out(s)
	cnt := 0
	for i := 0; i < len(s); i++ {
		// a := s[i][:len(s[i])-1]
		for j := i + 1; j < len(s); j++ {
			if len(s[i]) > len(s[j]) {
				break
			}
			if check2(s[i], s[j]) {
				cnt++
			}
		}
	}
	out(cnt)
}

