	val = (val & _RH_MOD) + (val >> 61)
	if val > _RH_MOD {
		val -= _RH_MOD
	}
	return val
}

func ReverseMyself(slice interface{}) {
	rv := reflect.ValueOf(slice)
	swap := reflect.Swapper(slice)
	length := rv.Len()
	for i, j := 0, length-1; i < j; i, j = i+1, j-1 {
		swap(i, j)
	}
}

