struct Trie(long char_size, long base) {
    public struct TrieNode {            // 頂点を表す構造体
        long[] next;    // 子の頂点番号を格納。存在しなければ-1
        long[] accept;  // 末端がこの頂点になる単語の word_id を保存
        long c;               // base からの間隔をint型で表現したもの
        long common;          // いくつの単語がこの頂点を共有しているか
        long[char_size] count;
        this(long c_){
            c = c_;
            next = new long[char_size];
            next[] = -1;
        }
    }

    TrieNode[] nodes = [TrieNode(0)];  // trie 木本体

    // 単語の挿入
    void insert(char[] word, long word_id) {
        long node_id = 0;
        for (long i = 0; i < word.length; i++) {
            long c = word[i] - base;
            debugPrint!(node_id, c, nodes);
            auto next_id = nodes[node_id].next[c];
            if (next_id == -1) {  // 次の頂点が存在しなければ追加
                nodes[node_id].next[c] = nodes.length;
                debugPrint!(()=>nodes[node_id].next[c]);
                nodes ~= TrieNode(c);
            }
            ++nodes[node_id].common;
            node_id = next_id;
        }
        ++nodes[node_id].common;
        nodes[node_id].accept ~=  word_id;
    }
    void insert(char[] word) {
        insert(word, nodes[0].common);
    }

    TrieNode* searchNode(char[] word, long[] nums) {
        long node_id = 0;
        for (long i = 0; i < word.length; i++) {
            long c = word[i] - base;
            auto next_id = nodes[node_id].next[c];
            if (next_id == -1) {  // 次の頂点が存在しなければ終了
                return null;
            }
            foreach(b, num; nums)
            {
                nodes[node_id].count[b] += num>0?1:0;
            }
            nums[c-'a']--;
            node_id = next_id;
        }
        return &nodes[node_id];
    }

    // 挿入した単語の数
    long count() {
        return (nodes[0].common);
    }
    // Trie木のノード数
    long size() {
        return (nodes.length);
    }
}

