struct Factor
{
    long n;
    long c;
}

//素因数分解
Factor[] factors(long n) pure
{
    Factor[] res;
    for (long i = 2; i ^^ 2 <= n; i++)
    {
        if (n % i != 0)
            continue;

        long c;
        while (n % i == 0)
        {
            n = n / i;
            c++;
        }
        res ~= Factor(i, c);
    }
    if (n != 1)
        res ~= Factor(n, 1);

    return res;
}
//約数をすべて列挙
long[] divisors(long n) pure
{
    long[] list;
    void func(Factor[] fs, long n)
    {
        if(fs.empty){
            list ~= n;
            return;
        }

        foreach(c; 0..fs[0].c+1)
        {
            func(fs[1..$], n * (fs[0].n ^^ c));
        }
    }

    func(factors(n), 1);
    sort(list);
    return list;
}
//nまでの素数のリスト
long[] primes(long n) pure
{
    if(n<2)return [];

    auto table = new long[cast(size_t)n+1];

    long[] res;
    for(size_t i = 2;i<=n;i++)
    {
        if(table[i]==-1) continue;
        for(size_t a = i;a<table.length;a+=i)
        {
            table[a] = -1;
        }
        res ~= i;
    }
    return res;
}
//素数判定
bool isPrime(long n) pure
{
    if (n <= 1)
        return false;
    if (n == 2)
        return true;
    if (n % 2 == 0)
        return false;
    for (long i = 3; i ^^ 2 <= n; i += 2)
        if (n % i == 0)
            return false;
    return true;
}

//桁を数える
long digitCount(long n, long base=10) pure
{
    long res;
    do{
        n/=base;
        res++;
    }while(n!=0);

    return res;
}

import std.stdio, std.algorithm, std.conv, std.array, std.string, std.math, std.typecons, std.numeric, std.container, std.range;

class Tree
{
    Tree[26] children;
    long[26] counts;
    char c;

    this(char c) {
        this.c = c;
    }

    void add(string s) {
        assert(this.c == '\n');

        auto last = s[$-2];
        if (children[last - 'a'] is null) {
            children[last - 'a'] = new Tree(last);
        }
        long[26] cs;
        cs = children[last - 'a'].add(s[0..$-2], cs);
        foreach (i, c; cs) this.counts[i] += c;
    }

    long[26] add(string s, long[26] cs) {
        if (s.empty) {
            ++cs[this.c - 'a'];
            return cs;
        }

        auto last = s[$-1];
        if (children[last - 'a'] is null) {
            children[last - 'a'] = new Tree(last);
        }
        cs = children[last - 'a'].add(s[0..$-1], cs);

        foreach (i, c; cs) this.counts[i] += c;
        if (cs[this.c - 'a'] == 0) cs[this.c - 'a'] = 1;
        return cs;
    }

    long count(string s) {
        if (s[$-1] == '\n') s = s[0..$-1];

        if (s.length == 1) {
            return this.counts[s[0] - 'a'] - 1;
        } else {
            return this.children[s[$-1] - 'a'].count(s[0..$-1]);
        }
    }
}

void main()
{
    auto N = readln.chomp.to!int;
    auto tree = new Tree('\n');
    string[] ss;
    long[string] memo;
    foreach (_; 0..N) {
        auto s = readln;
        if (s[$-1] != '\n') s ~= '\n';
        tree.add(s);
        ss ~= s;
        ++memo[s];
    }
    long r;
    foreach (s; ss) r += tree.count(s);
    foreach (_, n; memo) r -= n * (n-1) / 2;
    writeln(r);
}

