class Node:
    def __init__(self):
        self.child = [None] * 26
        self.counts = [0] * 26

    def add(self, s, bucket, idx_s):
        c = s[idx_s]
        if self.child[c] is None:
            self.child[c] = Node()
        for i, cnt in enumerate(bucket):
            if cnt:
                self.counts[i] += 1
        bucket[c] -= 1
        if idx_s >= 1:
            self.child[c].add(s, bucket, idx_s-1)

    def get(self, s, idx_s):
        c = s[idx_s]
        if idx_s > 0:
            return self.child[c].get(s, idx_s-1)
        else:
            return self.counts[c]

