def solve(alpha):
    query=[]
    for i in range(N):
        if S[i][-1]==alpha and i!=N-1 and exact[i+1]>=len(S[i])-1:
            start=i+1
            end=N
            while end-start>1:
                test=(end+start)//2
                if cond(i+1,test,len(S[i])-1):
                    start=test
                else:
                    end=test
            query.append((len(S[i])-1,i+1,start+1))
        id=lastappear[i][dic[alpha]]
        query.append((id,N+1,i+1))
    query.sort(reverse=True)
    res=0
    bit=BIT(N)
    for val,l,r in query:
        if l==N+1:
            bit.update(r,1)
        else:
            res+=bit.query(r)-bit.query(l)
    return res


