def lower_bound(x, i, s, t):
    s, t = s-1, t
    while t - s > 1:
        m = (s + t) // 2
        if len(S[m]) >= i and S[m][i] >= x[i]:
            t = m
        else:
            s = m

    return t

def upper_bound(x, i, s, t):
    s, t = s-1, t
    while t - s > 1:
        m = (s + t) // 2
        if len(S[m]) >= i and S[m][i] > x[i]:
            t = m
        else:
            s = m

    return t


