class Trie:
    class Node:
        def __init__(self):
            self.nxt = [-1] * 26
            self.is_end = False

    def __init__(self, N):
        self.nodes = [self.Node()]
        self.paths = [[] for _ in range(N)]

    def add(self, s, i):
        node = 0
        for c in s:
            c = ord(c) - ord('a')
            self.paths[i].append(node)
            if self.nodes[node].nxt[c] == -1:
                self.nodes[node].nxt[c] = len(self.nodes)
                self.nodes.append(self.Node())
            node = self.nodes[node].nxt[c]
        self.nodes[node].is_end = True

    def query(self, s, i):
        ret = 0
        suffix = set()
        for j in range(len(s) - 1, -1, -1):
            suffix.add(ord(s[j]) - ord('a'))
            node = self.paths[i][j]
            for c in suffix:
                if self.nodes[node].nxt[c] != -1:
                    ret += self.nodes[self.nodes[node].nxt[c]].is_end
        return ret

