def char_to_i(c):
    return string.ascii_letters.index(c) % 26

class Node:
    def __init__(self):
        self.children = [None for _ in range(26)]
        self.count = 0

    def append(self, word):
        i = char_to_i(word[0])
        if self.children[i] is None:
            self.children[i] = Node()

        if len(word) == 1:
            self.children[i].count += 1
            return 
        else:
            self.children[i].append(word[1:])

    def exists(self, word):
        i = char_to_i(word[0])
        if self.children[i] is None:
            return 0

        # case exist i
        if len(word) == 1:
            return self.children[i].count
        else:
            return self.children[i].exists(word[1:])



def remac(word):
    if len(word) == 1:
        return []
    if len(word) == 2:
        return [word[1], word[0]]

    return [word[1:], word[0]+word[2:]]


def extract(word):
    candidates = {}
    queue = []
    queue.append(word)

    while len(queue) > 0:
        c = queue.pop()
        candidates[c] = ""
        queue.extend(remac(c))

    return candidates.keys()


