from collections import Counter


class TrieNode:
    def __init__(self):
        self.edges = {}
        self.letter___count = Counter()

    def count_strings(self, word):
        curr_node = self
        for letter in word[:-1]:
            if letter not in curr_node.edges:
                return 0
            curr_node = curr_node.edges[letter]
        return curr_node.letter___count[word[-1]]

    def add(self, word):
        curr_node = self
        counts = Counter(word)
        for letter in word:
            for l in counts:
                curr_node.letter___count[l] += 1
            counts[letter] -= 1
            if counts[letter] == 0:
                counts.pop(letter)
            if letter not in curr_node.edges:
                curr_node.edges[letter] = TrieNode()
            curr_node = curr_node.edges[letter]


