def limak_comparator(s1, s2):
    # spcieal case 1
    if len(s1) == len(s2):
        if s1 == s2:
            return True
        return False

    # special case 2
    if s1[0:2] == s2[0:2]:
        return False

    # normal case
    if len(s1) > len(s2):
        longer = s1
        shorter = s2
    else:
        longer = s2
        shorter = s1

    length = len(shorter)
    pointer = 0
    for c in longer:
        if c == shorter[pointer]:
            pointer += 1
            if pointer >= length:
                return True
    return False

