        def __init__(self):
            self.clue = {c:0 for c in string.ascii_lowercase}
            self.ch = defaultdict(TrieTree.Node)
            self.cnt = 0
            self.end = False

    def __init__(self):
        self.root = self.Node()
        self.route = [self.root]

    def register(self,word):
        node = self.root
        for w in word:
            node.cnt += 1
            if w not in node.ch:
                self.route.append(node.ch[w])
            node = node.ch[w]
        node.cnt += 1
        node.end = True

    def prefix(self, word):
        node = self.root
        for w in word:
            if w not in node.ch:
                return False
            else:
                node = node.ch[w]
        return node

