class Node:
    def __init__(self, sigma, depth):
        self.end = False
        self.child = [None] * sigma
        self.depth = depth
        self.count = [0]*sigma
        self.par = None
    def __setitem__(self, i, x):
        self.child[i] = x
    def __getitem__(self, i):
        return self.child[i]

class Trie():
    def __init__(self, sigma):
        self.sigma = sigma
        self.root = Node(sigma, 0)

    def add(self, S):
        vn = self.root
        for cs in S:
            if vn[cs] is None:
                vn[cs] = Node(self.sigma, vn.depth + 1)
                vn[cs].par = vn
            vn = vn[cs]
        vn.end = True

    def up(self, S):
        vn = self.root
        for cs in S:
            if vn[cs] is None:
                vn[cs] = Node(self.sigma, vn.depth + 1)
            vn = vn[cs]

        k = [0]*self.sigma
        ls = len(S)
        for i in range(ls-1, -1, -1):
            vn = vn.par
            s = S[i]
            k[s] = 1
            for i in range(self.sigma):
                vn.count[i] += k[i]

    def count(self, S, ss):
        vn = self.root
        for cs in S:
            if vn[cs] is None:
                vn[cs] = Node(self.sigma, vn.depth + 1)
            vn = vn[cs]

        global ans
        ans += vn.count[ss]

