        let len = s.len();
        let pre = &s[..(len - 1)];
        let k = (s[len - 1] - b'a') as usize;
        *map.entry(len - 1).or_insert(BTreeMap::new()).entry(pre).or_insert(0) |= 1 << k;
    }
