fn run() {
    let _: usize = scan();
    let sv: Vec<String> = scan_iter().collect();
    let sv: Vec<Vec<char>> = sv.into_iter().map(|s| s.chars().collect()).collect();
    let base = 9973u64;
    let module = 1_000_000_007u64;
    let mut g_sets: Vec<BTreeMap<u64, u64>> = vec![BTreeMap::new(); 26];
    for idx in 0..sv.len() {
        let s = &sv[idx];
        let n = s.len();
        let mut counts = vec![0; 26];
        for i in 0..n {
            let c = s[i] as u8 - b'a';
            counts[c as usize] += 1;
        }

        let mut h = 0u64;
        for i in (0..n).rev() {
            for c in 0..26 {
                if counts[c as usize] == 0 {
                    continue;
                }
                let key = (h, c);
                *g_sets[key.1].entry(key.0).or_default() += 1;
            }

            let c = s[i] as u8 - b'a';
            counts[c as usize] -= 1;
            h = (h * base + c as u64) % module;
        }
    }

    let mut ans = 0u64;
    for idx in 0..sv.len() {
        let s = &sv[idx];
        let n = s.len();
        let mut h = 0u64;
        for i in (1..n).rev() {
            let c = s[i] as u8 - b'a';
            h = (h * base + c as u64) % module;
        }
        let fc = s[0] as u8 - b'a';
        let key = (h, fc);
        if let Some(v) = g_sets[key.1 as usize].get(&key.0) {
            ans += v - 1;
        }
    }
    println!("{}", ans);
}

