const l: usize = 26;

#[derive(Default, Debug)]
struct Node {
    is_leaf: bool,
    nleafs: usize,
    counts: [usize; l],
    children: BTreeMap<u8, Box<Node>>,
    seen: bool,
}

fn add_count(node: &mut Node) {
    for (k, v) in &mut node.children {
        add_count(v);
        let vn = v.nleafs + if v.is_leaf { 1 } else { 0 };
        node.nleafs += vn;
        for i in 0..l {
            if i != *k as usize {
                node.counts[i] += v.counts[i];
            } else {
                node.counts[i] += vn;
            }
        }
    }
}

fn count(node: &Node) -> usize {
    let mut ret = 0;
    for (k, v) in &node.children {
        if v.is_leaf {
            let pret = node.counts[*k as usize] - 1;
            ret += pret;
            if pret > 0 {
                // debug!("{:?} {:?}", (k, pret), node); // DEBUG
            }
        }
        ret += count(v);
    }
    ret
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize);
    let mut root = Node {
        is_leaf: false,
        counts: [0; 26],
        children: BTreeMap::new(),
        nleafs: 0,
        seen: false,
    };
    for _ in 0..n {
        let s: Vec<_> = it.next().unwrap().bytes().rev().collect();
        let mut cur = &mut root;
        for (i, c) in s.iter().enumerate() {
            let k = c - b'a';
            cur = cur.children.entry(k).or_default();
            if i == s.len() - 1 {
                cur.is_leaf = true;
            }
        }
    }
    add_count(&mut root);
    assert_eq!(root.nleafs, n);
    debug!("{:?}", root); // DEBUG
    println!("{}", count(&root));
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

