use utils::adj4_iter;

fn run() {
    let _: usize = scan();
    let sv: Vec<String> = scan_iter().collect();
    let sv: Vec<Vec<char>> = sv.into_iter().map(|s| s.chars().collect()).collect();
    let base = 9973u64;
    let module1 = 1_000_000_007u64;
    let module2 = 999999937;
    let mut g_sets: Vec<HashMap<(u64, u64), u64>> = vec![HashMap::new(); 26];
    let mut lengths = HashSet::new();
    for s in &sv {
        lengths.insert(s.len());
    }
    for idx in 0..sv.len() {
        let s = &sv[idx];
        let n = s.len();
        let mut counts = vec![0; 26];
        for i in 0..n {
            let c = s[i] as u8 - b'a';
            counts[c as usize] += 1;
        }

        let mut h1 = 0u64;
        let mut h2 = 0u64;
        let mut len = 0;
        for i in (0..n).rev() {
            for c in 0..26 {
                if counts[c as usize] == 0 {
                    continue;
                }
                let key = (h1, h2);
                if lengths.contains(&(len + 1)) {
                    *g_sets[c].entry(key).or_default() += 1;
                }
            }

            let c = s[i] as u8 - b'a';
            counts[c as usize] -= 1;
            h1 = (h1 * base + c as u64) % module1;
            h2 = (h2 * base + c as u64) % module2;
            len += 1;
        }
    }

    let mut ans = 0u64;
    for idx in 0..sv.len() {
        let s = &sv[idx];
        let n = s.len();
        let mut h1 = 0u64;
        let mut h2 = 0u64;
        for i in (1..n).rev() {
            let c = s[i] as u8 - b'a';
            h1 = (h1 * base + c as u64) % module1;
            h2 = (h2 * base + c as u64) % module2;
        }
        let key = (h1, h2);
        let fc = s[0] as u8 - b'a';
        if let Some(v) = g_sets[fc as usize].get(&key) {
            ans += v - 1;
        }
    }
    println!("{}", ans);
}

fn main() {
    std::thread::Builder::new()
        .name("run".to_string())
        .stack_size(256 * 1024 * 1024)
        .spawn(run)
        .unwrap()
        .join()
        .unwrap()
}
