const MOD: usize = 1_000_000_007;
const INF: i64 = std::i64::MAX/2;

use std::cell::RefCell;
use std::rc::Rc;

type Ref = Rc<RefCell<Node>>;
type Link = Option<Ref>;

pub struct Node {
    v: Vec<Link>,
    count: Vec<i64>,
}

impl Node {
    pub fn new() -> Self{
        Node {
            v: vec![None;26],
            count: vec![0;26],
        }
    }
}

fn add(mut node: Link, c: &[char]) {
    let n = c.len();
    let mut count = vec![0;26];
    add_dfs(node, &mut count, &c, 0);
}

fn add_dfs(mut node: Link, mut count: &mut Vec<i64>, c: &[char], idx: usize) {
    if node.is_none() {
        return;
    }
    if idx==c.len() {
        return;
    }
    let cur = node.unwrap();
    let nxt = (c[idx] as u8 - 'a' as u8) as usize;
    if cur.borrow().v[nxt].is_none() {
        cur.borrow_mut().v[nxt] = Some(Rc::new(RefCell::new(Node::new())));
    }
    add_dfs(cur.borrow().v[nxt].clone(),&mut count, &c, idx+1);
    count[nxt] = 1;
    for i in 0..26 {
        cur.borrow_mut().count[i] += count[i];
    }
}

fn find(mut node: Link, c: &[char]) -> i64 {
    let n = c.len();
    let mut count = 0;
    find_dfs(node, &mut count, &c, 0);
    return count;
}

fn find_dfs(mut node: Link, mut count: &mut i64, c: &[char], idx: usize) -> bool {
    if node.is_none() {
        return false;
    }
    let cur = node.unwrap();
    let nxt = (c[idx] as u8 - 'a' as u8) as usize;
    if idx==c.len()-1 {
        *count = cur.borrow().count[nxt];
        return true;
    }
    if cur.borrow().v[nxt].is_none() {
        return false;
    }
    return find_dfs(cur.borrow().v[nxt].clone(),&mut count, &c, idx+1);
}

fn solve() {
    let n = read!(usize);
    let mut c = read!([char];n);
    let mut v = vec![];
    for c in &c {
        v.push((c.len(),c));
    }
    v.sort_by(|a,b| b.cmp(a));
    let mut root = Some(Rc::new(RefCell::new(Node::new())));
    let mut ans = 0;
    for (_,x) in v {
        let mut c = x.clone();
        c.reverse(); 
        let tmp = find(root.clone(),&c);
        // println!("{:?} {}",c, tmp);
        // println!("{:?}", root.clone().unwrap().borrow().count);
        ans += tmp;
        add(root.clone(), &c);
    }
    println!("{}",ans);
}

fn run() {
    solve();
}

