const MOD: usize = 1_000_000_007;
const INF: i64 = std::i64::MAX/2;

use std::cell::RefCell;
use std::rc::Rc;

type Ref = Rc<RefCell<Node>>;
type Link = Option<Ref>;

pub struct Node {
    v: Vec<Link>,
    count: Vec<i64>,
}

impl Node {
    pub fn new() -> Self{
        Node {
            v: vec![None;26],
            count: vec![0;26],
        }
    }
}

fn add(mut node: Link, c: &[char]) {
    let n = c.len();
    let mut cum = vec![vec![0;26];n+1];
    for i in 0..n {
        let val = (c[i] as u8 - 'a' as u8) as usize;
        for j in 0..26 {
            cum[i+1][j] += cum[i][j];
            if val==j {
                cum[i+1][j] += 1;
            }
        }
    }
    let mut cur = node.clone();
    let mut cidx = 0;
    while let Some(val) = cur.clone() {
        if cidx==c.len() {
            break;
        }
        let nidx = (c[cidx] as u8 - 'a' as u8) as usize;
        if val.borrow().v[nidx].is_none() {
            val.borrow_mut().v[nidx] = Some(Rc::new(RefCell::new(Node::new())));
        }
        for i in 0..26 {
            let tmp = cum[n][i] - cum[cidx][i];
            if tmp>0 {
                val.borrow_mut().count[i] += 1;
            }
        }
        cur = val.borrow().v[nidx].clone();
        cidx += 1;
    }

}

fn find(mut node: Link, c: &[char])->i64{
    let mut cur = node.clone();
    let mut cidx = 0;
    let mut count = 0;
    while let Some(val) = cur.clone() {
        let nidx = (c[cidx] as u8 - 'a' as u8) as usize;
        if cidx==c.len()-1 {
            count = val.borrow().count[nidx];
            break;
        }
        cur = val.borrow().v[nidx].clone();
        cidx += 1;
    }
    return count;
}

fn solve() {
    let n = read!(usize);
    let mut c = read!([char];n);
    let mut v = vec![];
    for c in &c {
        v.push((c.len(),c));
    }
    v.sort_by(|a,b| b.cmp(a));
    let mut root = Some(Rc::new(RefCell::new(Node::new())));
    let mut ans = 0;
    for (_,x) in v {
        let mut c = x.clone();
        c.reverse(); 
        let tmp = find(root.clone(),&c);
        // println!("{:?} {}",c, tmp);
        // println!("{:?}", root.clone().unwrap().borrow().count);
        ans += tmp;
        add(root.clone(), &c);
    }
    println!("{}",ans);
}

fn run() {
    solve();
}

