fn solve<R, W>(reader: R, mut writer: W) -> std::io::Result<()>
where
  R: BufRead,
  W: Write,
{
  let mut _scanner = lib::io::Scanner::new(reader);
  #[allow(unused_macros)]
  macro_rules! scan {
    ($T:ty) => {
      _scanner.parse_next::<$T>()?.unwrap()
    };
    ($($T:ty),+) => {
      ($(scan!($T)),+)
    };
    ($T:ty; $n:expr) => {
      _scanner.parse_next_n::<$T>($n)?.unwrap()
    };
    ($($T:ty),+; $n:expr) => {
      iter::repeat_with(|| -> std::io::Result<_> { Ok(($(scan!($T)),+)) })
        .take($n)
        .collect::<std::io::Result<Vec<_>>>()?
    };
  }
  #[allow(unused_macros)]
  macro_rules! scan_bytes_map {
    ($f:expr) => {
      _scanner.map_next_bytes($f)?
    };
    ($f:expr; $n:expr) => {
      _scanner.map_next_bytes_n($n, $f)?
    };
  }
  #[allow(unused_macros)]
  macro_rules! print {
    ($($arg:tt)*) => {
      write!(writer, $($arg)*)?
    };
  }
  #[allow(unused_macros)]
  macro_rules! println {
    ($($arg:tt)*) => {
      writeln!(writer, $($arg)*)?
    };
  }
  #[allow(unused_macros)]
  macro_rules! answer {
    ($($arg:tt)*) => {{
      println!($($arg)*);
      return Ok(());
    }};
  }
  {
    const C: usize = 26;

    let n = scan!(usize);
    let mut s = scan_bytes_map!(ByteChar; n);
    s.sort_unstable_by_key(|s_i| Reverse(s_i.len()));
    let s = s;

    fn idx(c: ByteChar) -> usize {
      (c.0 - b'a') as usize
    }

    #[derive(Clone, Default, Debug)]
    struct Node {
      cnt: [u64; C],
      ch: [Option<Box<Node>>; C],
    }

    impl Node {
      fn find(&self, s: &[ByteChar]) -> u64 {
        let &c = s.last().unwrap();
        if s.len() == 1 {
          return self.cnt[idx(c)];
        }
        self.ch[idx(c)]
          .as_ref()
          .map_or(0, |node| node.find(&s[..s.len() - 1]))
      }

      fn insert(&mut self, s: &[ByteChar]) {
        let mut cnt = [0; C];
        for &c in s {
          cnt[idx(c)] += 1;
        }
        self.do_insert(s, cnt);
      }

      fn do_insert(&mut self, s: &[ByteChar], mut cnt: [u64; C]) {
        let &c = s.last().unwrap();
        for i in 0..C {
          self.cnt[i] += cmp::min(1, cnt[i]);
        }
        cnt[idx(c)] -= 1;
        if s.len() == 1 {
          return;
        }
        self.ch[idx(c)]
          .get_or_insert(Box::new(Node::default()))
          .do_insert(&s[..s.len() - 1], cnt);
      }
    }

    let mut root = Node::default();
    let mut ans = 0;
    for s_i in s {
      ans += root.find(&s_i);
      root.insert(&s_i);
    }
    println!("{}", ans);
  }
  #[allow(unreachable_code)]
  Ok(())
}

