    let stack_size = 104_857_600 << 8; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    solve();
}

use proconio::*;
use proconio::marker::*;

type Link = Option<Box<Node>>;

const F: usize = 26;

#[derive(Default)]
struct Node {
    cnt: [u32; F],
    next: [Link; F],
}

fn run() {
    input! {
        n: usize,
        mut s: [Bytes; n],
    }
    s.sort_by_key(|s| s.len());
    let mut root = Some(Box::new(Node::default()));
    let mut ans = 0;
    for s in s.iter_mut().rev() {
        s.reverse();
        let mut now = root.take().unwrap();
        let mut stack = vec![];
        for c in s.iter() {
            let k = (*c - b'a') as usize;
            if now.next[k].is_none() {
                now.next[k] = Some(Box::new(Node::default()));
            }
            let next = now.next[k].take().unwrap();
            stack.push(now);
            now = next;
        }
        let mut bit = 0;
        for (i, c) in s.iter().rev().enumerate() {
            let mut parent = stack.pop().unwrap();
            let k = (*c - b'a') as usize;
            if i == 0 {
                ans += parent.cnt[k] as usize;
            }
            bit |= 1 << k;
            for (j, cnt) in parent.cnt.iter_mut().enumerate() {
                *cnt += ((bit >> j) & 1) as u32;
            }
            parent.next[k] = Some(now);
            now = parent;
        }
        root = Some(now);
    }
    println!("{}", ans);
}

