    }
    pub fn add(&mut self, c: &[char]) {
        let n = c.len();
        let mut cum = vec![vec![0;26];n+1];
        for i in 0..n {
            let val = (c[i] as u8 - 'a' as u8) as usize;
            for j in 0..26 {
                cum[i+1][j] += cum[i][j];
                if val==j {
                    cum[i+1][j] += 1;
                }
            }
        }
        let mut cur = 0;
        let mut cidx = 0;
        loop {
            if cidx==c.len() {
                break;
            }
            let nidx = (c[cidx] as u8 - 'a' as u8) as usize;
            if self.nodes[cur].child[nidx]==0 {
                let nnode = Node::new();
                self.nodes.push(nnode);
                self.nodes[cur].child[nidx] = self.nodes.len()-1;
            }
            for i in 0..26 {
                let tmp = cum[n][i] - cum[cidx][i];
                if tmp>0 {
                    self.nodes[cur].count[i] += 1;
                }
            }
            cur = self.nodes[cur].child[nidx];
            cidx += 1;
        }        
    }
    pub fn find(&self, c: &[char])->i64{
        let mut cur = 0;
        let mut cidx = 0;
        let mut count = 0;
        loop {
            let nidx = (c[cidx] as u8 - 'a' as u8) as usize;
            if cidx==c.len()-1 {
                count = self.nodes[cur].count[nidx];
                break;
            }
            cur = self.nodes[cur].child[nidx];
            if cur==0 {
                break;
            }
            cidx += 1;
        }
        return count;
    }
}

fn solve() {
    let n = read!(usize);
    let mut c = read!([char];n);
    let mut v = vec![];
    for c in &c {
        v.push((c.len(),c));
    }
    v.sort_by(|a,b| b.cmp(a));
    let mut trie = Trie::new();
    let mut ans = 0;
    for (_,x) in v {
        let mut c = x.clone();
        c.reverse(); 
        let tmp = trie.find(&c);
        // println!("{:?} {}",c, tmp);
        // println!("{:?}", root.clone().unwrap().borrow().count);
        ans += tmp;
        trie.add(&c);
    }
    println!("{}",ans);
}

fn run() {
    let stack_size = 104_857_600; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    solve();
}

pub trait IterScan: Sized {
    type Output;
    fn scan<'a, I: Iterator<Item = &'a str>>(iter: &mut I) -> Option<Self::Output>;
}
pub trait MarkedIterScan: Sized {
    type Output;
    fn mscan<'a, I: Iterator<Item = &'a str>>(self, iter: &mut I) -> Option<Self::Output>;
}
#[derive(Debug)]
pub struct Scanner<'a> {
    iter: std::str::SplitAsciiWhitespace<'a>,
}
impl<'a> Scanner<'a> {
    #[inline]
    pub fn new(s: &'a str) -> Self {
        let iter = s.split_ascii_whitespace();
        Self { iter }
    }
    #[inline]
    pub fn scan<T: IterScan>(&mut self) -> <T as IterScan>::Output {
        T::scan(&mut self.iter).unwrap()
    }
    #[inline]
    pub fn mscan<T: MarkedIterScan>(&mut self, marker: T) -> <T as MarkedIterScan>::Output {
        marker.mscan(&mut self.iter).unwrap()
    }
    #[inline]
    pub fn scan_vec<T: IterScan>(&mut self, size: usize) -> Vec<<T as IterScan>::Output> {
        (0..size)
            .map(|_| T::scan(&mut self.iter).unwrap())
            .collect()
    }
    #[inline]
    pub fn scan_chars(&mut self) -> Vec<char> {
        self.iter.next().unwrap().chars().collect::<Vec<char>>()
    }
