pub struct Trie {
    child: Vec<Vec<usize>>,
    accept: Vec<usize>,
    char_size: usize,
}
impl Trie {
    pub fn new(char_size: usize) -> Self {
        Self {
            child: vec![vec![0; char_size]],
            accept: vec![0],
            char_size,
        }
    }
    pub fn insert(&mut self, iter: impl IntoIterator<Item = usize>) -> Vec<usize> {
        let mut path = Vec::new();
        let mut idx = 0;
        for item in iter.into_iter() {
            path.push(idx);
            if self.child[idx][item] == 0 {
                self.child[idx][item] = self.child.len();
                self.child.push(vec![0; self.char_size]);
                self.accept.push(0);
            }
            idx = self.child[idx][item];
        }
        self.accept[idx] += 1;
        path
    }
    pub fn next_node(&self, node: usize, ch: usize) -> usize {
        self.child[node][ch]
    }
    pub fn count(&self, node: usize) -> usize {
        self.accept[node]
    }
    pub fn next_count(&self, node: usize, ch: usize) -> usize {
        self.accept[self.child[node][ch]]
    }
}

// ローリングハッシュ計算用の定数
static B: i64 = 1861;
static MOD: i64 = 3983466482;

fn main() {
    // 問題文中で使われる変数の型宣言をしておく。
    let n: i64;
    let mut s: Vec<Vec<u8>>;
    // 【入力段ここから】
    // 定型句 bufにstdinから1行読み込む。読み込んだ後、CRLFが入りっぱなしになっている点に注意。
    let mut buf: String;
    buf = String::new();
    let stdin_obj = std::io::stdin();
    stdin_obj.read_line(&mut buf).ok();
    // 定型句 buf（Str）に読み込んだ文字列をi64にパースしてnに代入。
    n = buf.trim().parse().ok().unwrap();
    s = Vec::<Vec<u8>>::with_capacity(n as usize);
    for _ in 0..n {
        buf = String::new();
        stdin_obj.read_line(&mut buf).ok();
        let tmp_str = buf.trim().to_string();
        s.push(tmp_str.into_bytes());
    }
    // 【入力段ここまで】
    // ==================================
    // 【計算段ここから】
    s.sort_by_key(|a| a.len());
    // 予備計算しとくもの。
    // A: ローリングハッシュテーブル plane
    // 予めすべての文字列について、後ろからx文字目までのハッシュを計算しておく。
    // ローリングハッシュを確保する配列。ヘッダ部分だけ確保。中身は後で動的確保、最大8MB
    let mut plane: Vec<Vec<i64>> = Vec::<Vec<i64>>::with_capacity(n as usize);
    for i in 0..n {
        let ref tmp_str = s[i as usize];
        // tmp_vect[i] は tmp_strの後ろから順番に、 i+1 文字分のローリングハッシュを格納する。
        let mut tmp_vect: Vec<i64> = Vec::<i64>::with_capacity(tmp_str.len() as usize);
        for x in 0..tmp_str.len() {
            let ix = tmp_str.len() - 1 - x;
            let val = tmp_str[ix];
            if x == 0 {
                tmp_vect.push(1);
            } else {
                tmp_vect.push(tmp_vect[x - 1 as usize])
            }
            tmp_vect[x as usize] *= B;
            tmp_vect[x as usize] += val as i64;
            tmp_vect[x as usize] %= MOD;
        }
        plane.push(tmp_vect.clone());
    }
    // B: 先頭からの素数積化テーブル plane2 三次元面
    let mut plane2: Vec<Vec<Vec<i64>>> = Vec::<Vec<Vec<i64>>>::with_capacity(n as usize);
    for i in 0..n {
        let tmp_str = s[i as usize].clone();
        // tmp_vect[i] は tmp_strの前から順番に26要素のベクタを格納していく。「そこまでに見つかってた個数」
        let mut tmp_vect: Vec<Vec<i64>> = Vec::<Vec<i64>>::with_capacity(tmp_str.len() as usize);
        let mut tmp_vect2: Vec<i64> = Vec::<i64>::with_capacity(26);
        for _ in 0..26 {
            tmp_vect2.push(0);
        }
        for x in 0..tmp_str.len() {
            let tmp_ix = tmp_str[x] - ('a' as u8);
            tmp_vect2[tmp_ix as usize] += 1;
            tmp_vect.push(tmp_vect2.clone());
        }
        plane2.push(tmp_vect.clone());
    }

    let mut counter = 0;
    for i in 0..n {
        let ref s_i = s[i as usize]; // 削る目標
        let i_len = s_i.len();
        for j in (i + 1)..n {
            let ref s_j = s[j as usize];
            let j_len = s_j.len();
            // 削る目標の2~n文字部分を、削られる側の末尾と比較する。
            if i_len > 1 {
                let det_last_ix = i_len - 2 as usize;
                if plane[i as usize][det_last_ix] != plane[j as usize][det_last_ix] {
                    continue;
                }
            }
            // 最後に残った1文字を検索する。
            let search_remain_ix = j_len - i_len;
            let search_ix = (s_i[0] - ('a' as u8)) as usize;
            if search_remain_ix > 0 {
                if plane2[j as usize][search_remain_ix][search_ix] > 0 {
                    counter += 1;
                }
            } else {
                continue;
            }
        }
    }
    println!("{}", counter);
}

