fn run<I: Input, O: Write>(mut kin: I, mut out: O) -> io::Result<()> {
    macro_rules! output { ($($args:expr),+) => { write!(&mut out, $($args),+)?; }; }
    macro_rules! outputln {
        ($($args:expr),+) => { output!($($args),+); outputln!(); };
        () => { output!("\n"); if cfg!(debug_assertions) { out.flush()?; } }
    }

    let n: usize = kin.input();
    let mut s: Vec<Vec<u8>> = kin.seq(n);

    s.sort_by_key(|s| -(s.len() as isize));

    let mut map = vec![BTreeMap::new(); 1000001];
    const P1: i64 = 1e9 as i64 + 7;
    const P2: i64 = 998244353;
    const D: i64 = 101;
    let mut cnt = [0; 128];
    let mut ans = 0i64;
    for mut s in s {
        s.reverse();
        for &c in s.iter() {
            cnt[c as usize] += 1;
        }
        let mut h1 = 0;
        let mut h2 = 0;
        for i in 0..s.len() {
            if i == s.len() - 1 {
                let h = h1 + ((s[s.len() - 1] as i64) << 32); 
                ans += *map[i].get(&h).unwrap_or(&0);
            }
            for c in b'a'..=b'z' {
                if cnt[c as usize] > 0 {
                    let h = h1 + ((c as i64) << 32); 
                    *map[i].entry(h).or_insert(0) += 1;
                }
            }
            cnt[s[i] as usize] -= 1;
            h1 = (D * h1 + s[i] as i64) % P1;
            h2 = (D * h2 + s[i] as i64) % P2;
        }
    }

    /*
    for i in 0..5 {
        eprintln!("{:?}", &map[i]);
    }
    */

    outputln!("{}", ans);

    Ok(())
}

