pub mod kyoproio {
    use std::io::prelude::*;
    pub trait Input {
        fn str(&mut self) -> &str;
        fn input<T: InputParse>(&mut self) -> T {
            T::input(self)
        }
        fn iter<T: InputParse>(&mut self) -> Iter<T, Self> {
            Iter(self, std::marker::PhantomData)
        }
        fn seq<T: InputParse, B: std::iter::FromIterator<T>>(&mut self, n: usize) -> B {
            self.iter().take(n).collect()
        }
    }
    pub struct KInput<R> {
        src: R,
        buf: String,
        pos: usize,
    }
    impl<R: BufRead> KInput<R> {
        pub fn new(src: R) -> Self {
            Self {
                src,
                buf: String::with_capacity(1024),
                pos: 0,
            }
        }
    }
    impl<R: BufRead> Input for KInput<R> {
        fn str(&mut self) -> &str {
            loop {
                if self.pos >= self.buf.len() {
                    self.pos = 0;
                    self.buf.clear();
                    if self.src.read_line(&mut self.buf).expect("io error") == 0 {
                        return &self.buf;
                    }
                }
                let range = self.pos
                    ..self.buf[self.pos..]
                        .find(|c: char| c.is_ascii_whitespace())
                        .map(|i| i + self.pos)
                        .unwrap_or_else(|| self.buf.len());
                self.pos = range.end + 1;
                if range.end > range.start {
                    return &self.buf[range];
                }
            }
        }
    }
    pub struct Iter<'a, T, I: ?Sized>(&'a mut I, std::marker::PhantomData<*const T>);
    impl<'a, T: InputParse, I: Input + ?Sized> Iterator for Iter<'a, T, I> {
        type Item = T;
        fn next(&mut self) -> Option<T> {
            Some(self.0.input())
        }
    }
    pub trait InputParse: Sized {
        fn input<I: Input + ?Sized>(src: &mut I) -> Self;
    }
    impl InputParse for Vec<u8> {
        fn input<I: Input + ?Sized>(src: &mut I) -> Self {
            src.str().as_bytes().to_owned()
        }
    }
    macro_rules! from_str_impl {
        { $($T:ty)* } => {
            $(impl InputParse for $T {
                fn input<I: Input + ?Sized>(src: &mut I) -> Self {
                    src.str().parse::<$T>().expect("parse error")
                }
            })*
        }
    }
    from_str_impl! {
        String char bool f32 f64 isize i8 i16 i32 i64 i128 usize u8 u16 u32 u64 u128
    }
    macro_rules! tuple_impl {
        ($H:ident $($T:ident)*) => {
            impl<$H: InputParse, $($T: InputParse),*> InputParse for ($H, $($T),*) {
                fn input<I: Input + ?Sized>(src: &mut I) -> Self {
                    ($H::input(src), $($T::input(src)),*)
                }
            }
            tuple_impl!($($T)*);
        };
        () => {}
    }
    tuple_impl!(A B C D E F G);
    #[macro_export]
    macro_rules! kdbg {
        ($($v:expr),*) => {
            if cfg!(debug_assertions) { dbg!($($v),*) } else { ($($v),*) }
        }
    }
}

use proconio::marker::*;
use proconio::*;

type Link = Option<Box<Node>>;

const F: usize = 26;

#[derive(Default)]
struct Node {
    cnt: [u32; F],
    next: [Link; F],
}

impl Node {
    fn insert(&mut self, s: &[u8]) -> (usize, usize) {
        if s.is_empty() {
            return (0, 0);
        }
        let k = (s[0] - b'a') as usize;
        let (mut bit, mut ans) = self.next[k]
            .get_or_insert_with(|| Box::new(Node::default()))
            .insert(&s[1..]);
        if s.len() == 1 {
            ans += self.cnt[k] as usize;
        }
        bit |= 1 << k;
        for (i, c) in self.cnt.iter_mut().enumerate() {
            *c += (bit >> i & 1) as u32;
        }
        (bit, ans)
    }
}

fn run() {
    input! {
        n: usize,
        mut s: [Bytes; n],
    }
    let mut root = Box::new(Node::default());
    s.sort_by_key(|s| s.len());
    let mut ans = 0;
    for s in s.iter_mut().rev() {
        s.reverse();
        ans += root.insert(s).1;
    }
    println!("{}", ans);
}

fn main() {
    let stack_size = 1 << 30;
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| run()).unwrap().join().unwrap();
}

// ローリングハッシュ計算用の定数
static B: i64 = 100007;
static MOD: i64 = 100009;

fn main() {
    // 問題文中で使われる変数の型宣言をしておく。
    let n: i64;
    let mut s: Vec<String>;
    // 【入力段ここから】
    // 定型句 bufにstdinから1行読み込む。読み込んだ後、CRLFが入りっぱなしになっている点に注意。
    let mut buf: String;
    buf = String::new();
    let stdin_obj = std::io::stdin();
    stdin_obj.read_line(&mut buf).ok();
    // 定型句 buf（Str）に読み込んだ文字列をi64にパースしてnに代入。
    n = buf.trim().parse().ok().unwrap();
    s = Vec::<String>::with_capacity(n as usize);
    for _ in 0..n {
        buf = String::new();
        stdin_obj.read_line(&mut buf).ok();
        s.push(buf.trim().to_string());
    }
    // 【入力段ここまで】
    // ==================================
    // 【計算段ここから】
    s.sort_by_key(|a| a.len());
    // 予めすべての文字列について、後ろからx文字目までのハッシュを計算しておく。
    // ローリングハッシュを確保する配列。ヘッダ部分だけ確保。中身は後で動的確保、最大8MB
    let mut plane: Vec<Vec<i64>> = Vec::<Vec<i64>>::with_capacity(n as usize);
    for i in 0..n {
        let tmp_str = s[i as usize].as_bytes();
        // tmp_vect[i] は tmp_strの後ろから順番に、 i+1 文字分のローリングハッシュを格納する。
        let mut tmp_vect: Vec<i64> = Vec::<i64>::with_capacity(tmp_str.len() as usize);
        for x in 0..tmp_str.len() {
            let ix = tmp_str.len() - 1 - x;
            let val = tmp_str[ix];
            if x == 0 {
                tmp_vect.push(1);
            } else {
                tmp_vect.push(tmp_vect[x - 1 as usize])
            }
            tmp_vect[x as usize] *= B;
            tmp_vect[x as usize] += val as i64;
            tmp_vect[x as usize] %= MOD;
        }
        plane.push(tmp_vect.clone());
    }

    let mut counter = 0;
    for i in 0..n {
        let s_i = s[i as usize].as_bytes(); // 削る目標
        for j in (i + 1)..n {
            let s_j = s[j as usize].as_bytes();
            // ケース1: OK例 削る目標が1文字の場合、削る対象の中にその1文字が入っていたら、OK判定。
            if s_i.len() == 1 {
                for x in 0..s_j.len() {
                    if s_i[0] == s_j[x] {
                        counter += 1;
                        break;
                    }
                }
                continue;
            }
            // ケース2 ケース1 に入らなかった場合、後ろから最後の一文字を残して一致判定する。一致していなかったら、NG判定して弾く。
            let det_last_ix = plane[i as usize].len() - 2 as usize;
            if plane[i as usize][det_last_ix] != plane[j as usize][det_last_ix] {
                continue;
            }
            // ケース2.1 最後に残った1文字を検索する。
            let search_remain_ix = plane[j as usize].len() - plane[i as usize].len();
            for x in 0..(search_remain_ix + 1) {
                if s_i[0] == s_j[x] {
                    counter += 1;
                    break;
                }
            }
        }
    }
    println!("{}", counter);
}

use proconio::*;
use proconio::marker::*;

// A からBが得られるには
// Aの末尾|B| - 1 文字がB[1..] と等しい
// かつAの末尾|B| - 1 文字以外の文字の中に B[0] がある
// O(N^2)
// 文字が長いやつからTrieに挿入、戻る時に存在する文字をbitで覚えてカウンタ更新
//

type Link = Option<Box<Node>>;

const F: usize = 26;

#[derive(Default)]
struct Node {
    cnt: [u32; F],
    next: [Link; F],
}

fn insert(node: &mut Link, s: &[u8], ans: &mut usize) -> usize {
    if node.is_none() {
        *node = Some(Box::new(Node::default()));
    }
    let node = node.as_mut().unwrap();
    if s.len() == 0 {
        0
    } else {
        let k = (s[0] - b'a') as usize;
        let mut mask = insert(&mut node.next[k], &s[1..], ans);
        if s.len() == 1 {
            *ans += node.cnt[k] as usize;
        }
        mask |= 1 << k;
        for (i, c) in node.cnt.iter_mut().enumerate() {
            *c += ((mask >> i) & 1) as u32;
        }
        mask
    }
}

fn run() {
    input! {
        n: usize,
        mut s: [Bytes; n],
    }
    s.sort_by_key(|s| s.len());
    let mut root = None;
    let mut ans = 0;
    for s in s.iter_mut().rev() {
        s.reverse();
        insert(&mut root, s, &mut ans);
    }
    println!("{}", ans);
}

fn main() {
    let stack_size = 104_857_600 << 2; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| run()).unwrap().join().unwrap();
}

