fn solve() {
    let n = read!(usize);
    let mut c = read!([char];n);
    let mut v = vec![];
    for c in &c {
        v.push((c.len(),c));
    }
    v.sort_by(|a,b| b.cmp(a));
    let mut root = Some(Rc::new(RefCell::new(Node::new())));
    let mut ans = 0;
    for (_,x) in v {
        let mut c = x.clone();
        c.reverse(); 
        let tmp = find(root.clone(),&c);
        // println!("{:?} {}",c, tmp);
        // println!("{:?}", root.clone().unwrap().borrow().count);
        ans += tmp;
        add(root.clone(), &c);
    }
    println!("{}",ans);
}

fn run() {
    let stack_size = 104_857_600 << 2; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    solve();
}

