use text_scanner::{scan, scan_iter, scanln, scanln_iter};
use utils::adj4_iter;

struct Node {
    nexts: [Option<usize>; 26],
    counts: [usize; 26],
}

impl Node {
    fn new() -> Node {
        Node {
            nexts: [None; 26],
            counts: [0; 26],
        }
    }
}

fn run() {
    let _: usize = scan();
    let sv: Vec<String> = scan_iter().collect();
    let mut sv: Vec<Vec<char>> = sv.into_iter().map(|s| s.chars().collect()).collect();
    for i in 0..sv.len() {
        sv[i].reverse();
    }

    let mut nodes = Vec::new();
    nodes.push(Node::new());

    for k in 0..sv.len() {
        let s = &sv[k];
        let mut counts = vec![0; 26];
        for i in 0..s.len() {
            let c = (s[i] as u8 - b'a') as usize;
            counts[c] += 1;
        }
        let mut r = 0;
        for i in 0..s.len() {
            for c in 0..26 {
                if counts[c] > 0 {
                    nodes[r].counts[c] += 1;
                }
            }
            let c = (s[i] as u8 - b'a') as usize;
            let nr = if let Some(nr) = nodes[r].nexts[c] {
                nr
            } else {
                nodes.push(Node::new());
                let nr = nodes.len() - 1;
                nodes[r].nexts[c] = Some(nr);
                nr
            };
            r = nr;
        }
    }
    let mut ans = 0;
    for k in 0..sv.len() {
        let s = &sv[k];
        let mut r = 0;
        for i in 0..s.len() - 1 {
            let c = (s[i] as u8 - b'a') as usize;
            r = nodes[r].nexts[c].unwrap();
        }
        let c = (s[s.len() - 1] as u8 - b'a') as usize;
        assert!(nodes[r].counts[c] > 0);
        ans += nodes[r].counts[c] - 1;
    }
    println!("{}", ans);
}

fn main() {
    std::thread::Builder::new()
        .name("run".to_string())
        .stack_size(256 * 1024 * 1024)
        .spawn(run)
        .unwrap()
        .join()
        .unwrap()
}
