  }
}

fn solve<R, W>(reader: R, mut writer: W) -> std::io::Result<()>
where
  R: BufRead,
  W: Write,
{
  let mut _scanner = lib::io::Scanner::new(reader);
  #[allow(unused_macros)]
  macro_rules! scan {
    ($T:ty) => {
      _scanner.parse_next::<$T>()?.unwrap()
    };
    ($($T:ty),+) => {
      ($(scan!($T)),+)
    };
    ($T:ty; $n:expr) => {
      _scanner.parse_next_n::<$T>($n)?.unwrap()
    };
    ($($T:ty),+; $n:expr) => {
      iter::repeat_with(|| -> std::io::Result<_> { Ok(($(scan!($T)),+)) })
        .take($n)
        .collect::<std::io::Result<Vec<_>>>()?
    };
  }
  #[allow(unused_macros)]
  macro_rules! scan_bytes_map {
    ($f:expr) => {
      _scanner.map_next_bytes($f)?
    };
    ($f:expr; $n:expr) => {
      _scanner.map_next_bytes_n($n, $f)?
    };
  }
  #[allow(unused_macros)]
  macro_rules! print {
    ($($arg:tt)*) => {
      write!(writer, $($arg)*)?
    };
  }
  #[allow(unused_macros)]
  macro_rules! println {
    ($($arg:tt)*) => {
      writeln!(writer, $($arg)*)?
    };
  }
  #[allow(unused_macros)]
  macro_rules! answer {
    ($($arg:tt)*) => {{
      println!($($arg)*);
      return Ok(());
    }};
  }
  {
    const C: usize = 26;

    let n = scan!(usize);
    let mut s = scan_bytes_map!(ByteChar; n);
    s.sort_unstable_by_key(|s_i| Reverse(s_i.len()));
    let s = s;

    fn idx(c: ByteChar) -> usize {
      (c.0 - b'a') as usize
    }

    #[derive(Clone, Default, Debug)]
    struct Node {
      cnt: [u64; C],
      ch: [Option<Box<Node>>; C],
    }

    impl Node {
      fn find(&self, s: &[ByteChar]) -> u64 {
        let &c = s.last().unwrap();
        if s.len() == 1 {
          return self.cnt[idx(c)];
        }
        self.ch[idx(c)]
          .as_ref()
          .map_or(0, |node| node.find(&s[..s.len() - 1]))
      }

      fn insert(&mut self, s: &[ByteChar]) {
        let mut cnt = vec![0; C];
        for &c in s {
          cnt[idx(c)] += 1;
        }
        self.do_insert(s, cnt);
      }

      fn do_insert(&mut self, s: &[ByteChar], mut cnt: Vec<u64>) {
        let &c = s.last().unwrap();
        for i in 0..C {
          self.cnt[i] += cmp::min(1, cnt[i]);
        }
        cnt[idx(c)] -= 1;
        if s.len() == 1 {
          return;
        }
        self.ch[idx(c)]
          .get_or_insert(Box::new(Node::default()))
          .do_insert(&s[..s.len() - 1], cnt);
      }
    }

    let mut root = Node::default();
    let mut ans = 0;
    for s_i in s {
      ans += root.find(&s_i);
      root.insert(&s_i);
    }
    println!("{}", ans);
  }
  #[allow(unreachable_code)]
  Ok(())
}

// ローリングハッシュ計算用の定数
static B: i64 = 100007;
static MOD: i64 = 100009;

fn main() {
    // 問題文中で使われる変数の型宣言をしておく。
    let n: i64;
    let mut s: Vec<String>;
    // 【入力段ここから】
    // 定型句 bufにstdinから1行読み込む。読み込んだ後、CRLFが入りっぱなしになっている点に注意。
    let mut buf: String;
    buf = String::new();
    let stdin_obj = std::io::stdin();
    stdin_obj.read_line(&mut buf).ok();
    // 定型句 buf（Str）に読み込んだ文字列をi64にパースしてnに代入。
    n = buf.trim().parse().ok().unwrap();
    s = Vec::<String>::with_capacity(n as usize);
    for _ in 0..n {
        buf = String::new();
        stdin_obj.read_line(&mut buf).ok();
        s.push(buf.trim().to_string());
    }
    // 【入力段ここまで】
    // ==================================
    // 【計算段ここから】
    s.sort_by_key(|a| a.len());
    // 予めすべての文字列について、後ろからx文字目までのハッシュを計算しておく。
    // ローリングハッシュを確保する配列。ヘッダ部分だけ確保。中身は後で動的確保、最大8MB
    let mut plane: Vec<Vec<i64>> = Vec::<Vec<i64>>::with_capacity(n as usize);
    for i in 0..n {
        let tmp_str = s[i as usize].as_bytes();
        // tmp_vect[i] は tmp_strの後ろから順番に、 i+1 文字分のローリングハッシュを格納する。
        let mut tmp_vect: Vec<i64> = Vec::<i64>::with_capacity(tmp_str.len() as usize);
        for x in 0..tmp_str.len() {
            let ix = tmp_str.len() - 1 - x;
            let val = tmp_str[ix];
            if x == 0 {
                tmp_vect.push(1);
            } else {
                tmp_vect.push(tmp_vect[x - 1 as usize])
            }
            tmp_vect[x as usize] *= B;
            tmp_vect[x as usize] += val as i64;
            tmp_vect[x as usize] %= MOD;
        }
        plane.push(tmp_vect.clone());
    }

    let mut counter = 0;
    for i in 0..n {
        let s_i = s[i as usize].as_bytes(); // 削る目標
        for j in (i + 1)..n {
            let s_j = s[j as usize].as_bytes();
            // ケース1: OK例 削る目標が1文字の場合、削る対象の中にその1文字が入っていたら、OK判定。
            if s_i.len() == 1 {
                for x in 0..s_j.len() {
                    if s_i[0] == s_j[x] {
                        counter += 1;
                        break;
                    }
                }
                continue;
            }
            // ケース2 ケース1 に入らなかった場合、後ろから最後の一文字を残して一致判定する。一致していなかったら、NG判定して弾く。
            let det_last_ix = plane[i as usize].len() - 2 as usize;
            if plane[i as usize][det_last_ix] != plane[j as usize][det_last_ix] {
                continue;
            }
            // ケース2.1 最後に残った1文字を検索する。
            let search_remain_ix = plane[j as usize].len() - plane[i as usize].len();
            for x in 0..(search_remain_ix + 1) {
                if s_i[0] == s_j[x] {
                    counter += 1;
                    break;
                }
            }
        }
    }
    println!("{}", counter);
}

