use proconio::marker::*;
use proconio::*;

type Link = Option<Box<Node>>;

const F: usize = 26;

#[derive(Default)]
struct Node {
    cnt: [u32; F],
    next: [Link; F],
}

impl Node {
    fn insert(&mut self, s: &[u8]) -> (usize, usize) {
        if s.is_empty() {
            return (0, 0);
        }
        let k = (s[0] - b'a') as usize;
        let (mut bit, mut ans) = self.next[k]
            .get_or_insert_with(|| Box::new(Node::default()))
            .insert(&s[1..]);
        if s.len() == 1 {
            ans += self.cnt[k] as usize;
        }
        bit |= 1 << k;
        for (i, c) in self.cnt.iter_mut().enumerate() {
            *c += (bit >> i & 1) as u32;
        }
        (bit, ans)
    }
}

fn run() {
    input! {
        n: usize,
        mut s: [Bytes; n],
    }
    let mut root = Box::new(Node::default());
    s.sort_by_key(|s| s.len());
    let mut ans = 0;
    for s in s.iter_mut().rev() {
        s.reverse();
        ans += root.insert(s).1;
    }
    println!("{}", ans);
}

fn main() {
    run();
}

pub trait IterScan: Sized {
