pub mod kyoproio {
    use std::io::prelude::*;
    pub trait Input {
        fn str(&mut self) -> &str;
        fn input<T: InputParse>(&mut self) -> T {
            T::input(self)
        }
        fn iter<T: InputParse>(&mut self) -> Iter<T, Self> {
            Iter(self, std::marker::PhantomData)
        }
        fn seq<T: InputParse, B: std::iter::FromIterator<T>>(&mut self, n: usize) -> B {
            self.iter().take(n).collect()
        }
    }
    pub struct KInput<R> {
        src: R,
        buf: String,
        pos: usize,
    }
    impl<R: BufRead> KInput<R> {
        pub fn new(src: R) -> Self {
            Self {
                src,
                buf: String::with_capacity(1024),
                pos: 0,
            }
        }
    }
    impl<R: BufRead> Input for KInput<R> {
        fn str(&mut self) -> &str {
            loop {
                if self.pos >= self.buf.len() {
                    self.pos = 0;
                    self.buf.clear();
                    if self.src.read_line(&mut self.buf).expect("io error") == 0 {
                        return &self.buf;
                    }
                }
                let range = self.pos
                    ..self.buf[self.pos..]
                        .find(|c: char| c.is_ascii_whitespace())
                        .map(|i| i + self.pos)
                        .unwrap_or_else(|| self.buf.len());
                self.pos = range.end + 1;
                if range.end > range.start {
                    return &self.buf[range];
                }
            }
        }
    }
    pub struct Iter<'a, T, I: ?Sized>(&'a mut I, std::marker::PhantomData<*const T>);
    impl<'a, T: InputParse, I: Input + ?Sized> Iterator for Iter<'a, T, I> {
        type Item = T;
        fn next(&mut self) -> Option<T> {
            Some(self.0.input())
        }
    }
    pub trait InputParse: Sized {
        fn input<I: Input + ?Sized>(src: &mut I) -> Self;
    }
    impl InputParse for Vec<u8> {
        fn input<I: Input + ?Sized>(src: &mut I) -> Self {
            src.str().as_bytes().to_owned()
        }
    }
    macro_rules! from_str_impl {
        { $($T:ty)* } => {
            $(impl InputParse for $T {
                fn input<I: Input + ?Sized>(src: &mut I) -> Self {
                    src.str().parse::<$T>().expect("parse error")
                }
            })*
        }
    }
    from_str_impl! {
        String char bool f32 f64 isize i8 i16 i32 i64 i128 usize u8 u16 u32 u64 u128
    }
    macro_rules! tuple_impl {
        ($H:ident $($T:ident)*) => {
            impl<$H: InputParse, $($T: InputParse),*> InputParse for ($H, $($T),*) {
                fn input<I: Input + ?Sized>(src: &mut I) -> Self {
                    ($H::input(src), $($T::input(src)),*)
                }
            }
            tuple_impl!($($T)*);
        };
        () => {}
    }
    tuple_impl!(A B C D E F G);
    #[macro_export]
    macro_rules! kdbg {
        ($($v:expr),*) => {
            if cfg!(debug_assertions) { dbg!($($v),*) } else { ($($v),*) }
        }
    }
}

const N: usize = 26;
fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let mut trie = Trie {
        nodes: vec![Node::new()],
    };
    let n: usize = sc.read();
    let mut ss = vec![];
    for _ in 0..n {
        let s = sc
            .read::<String>()
            .chars()
            .rev()
            .map(|c| c as usize - 'a' as usize)
            .collect::<Vec<usize>>();
        let mut count = [0; N];
        for &c in s.iter() {
            count[c] += 1;
        }
        trie.insert(0, &s, 0, &mut count);
        ss.push(s);
    }

    let mut ans = 0;
    for s in ss.iter() {
        let count = trie.get(0, s, 0);
        assert!(count >= 1);
        ans += count - 1;
        // eprintln!("count={}", count);
    }
    println!("{}", ans);
}

struct Trie {
    nodes: Vec<Node>,
}

impl Trie {
    fn insert(&mut self, node_id: usize, s: &[usize], pos: usize, count: &mut [usize]) {
        for i in 0..N {
            if count[i] > 0 {
                self.nodes[node_id].one_char_count[i] += 1;
            }
        }
        if s.len() == pos {
            return;
        }

        let c = s[pos];
        let next_id = if self.nodes[node_id].children[c] == 0 {
            let next_id = self.nodes.len();
            self.nodes.push(Node::new());
            self.nodes[node_id].children[c] = next_id;
            next_id
        } else {
            self.nodes[node_id].children[c]
        };

        count[c] -= 1;
        self.insert(next_id, s, pos + 1, count);
    }

    fn get(&self, node_id: usize, s: &[usize], pos: usize) -> usize {
        if pos == s.len() - 1 {
            let last_c = s[pos];
            return self.nodes[node_id].one_char_count[last_c];
        }

        let next_c = s[pos];
        let next_id = self.nodes[node_id].children[next_c];
        assert_ne!(next_id, 0);
        self.get(next_id, s, pos + 1)
    }
}

struct Node {
    children: [usize; N],
    one_char_count: [usize; N],
}

impl Node {
    fn new() -> Self {
        Self {
            children: [0; 26],
            one_char_count: [0; 26],
        }
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        Self(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write_all(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

