    }
    s.sort();
    // eprintln!("{:?}", s);
    let mut last_index = vec![vec![0; 26]; n];
    for i in 0..n {
        for (j, &c) in s[i].iter().enumerate() {
            let c = c as usize - 'a' as usize;
            last_index[i][c] = j;
