use proconio::*;
use proconio::marker::*;

// A からBが得られるには
// Aの末尾|B| - 1 文字がB[1..] と等しい
// かつAの末尾|B| - 1 文字以外の文字の中に B[0] がある
// O(N^2)
// 文字が長いやつからTrieに挿入、戻る時に存在する文字をbitで覚えてカウンタ更新
//

type Link = Option<Box<Node>>;

const F: usize = 26;

#[derive(Default)]
struct Node {
    cnt: [u32; F],
    next: [Link; F],
}

fn insert(node: &mut Link, s: &[u8], ans: &mut usize) -> usize {
    if node.is_none() {
        *node = Some(Box::new(Node::default()));
    }
    let node = node.as_mut().unwrap();
    if s.len() == 0 {
        0
    } else {
        let k = (s[0] - b'a') as usize;
        let mut mask = insert(&mut node.next[k], &s[1..], ans);
        if s.len() == 1 {
            *ans += node.cnt[k] as usize;
        }
        mask |= 1 << k;
        for (i, c) in node.cnt.iter_mut().enumerate() {
            *c += (mask >> i) & 1;
        }
        mask
    }
}

fn run() {
    input! {
        n: usize,
        mut s: [Bytes; n],
    }
    s.sort_by_key(|s| s.len());
    let mut root = None;
    let mut ans = 0;
    for s in s.iter_mut().rev() {
        s.reverse();
        insert(&mut root, s, &mut ans);
    }
    println!("{}", ans);
}

fn main() {
    run();
}

fn main() {
    let n: usize = {
        let mut buf = String::new();
        std::io::stdin().read_line(&mut buf).unwrap();
        buf.trim_end().parse().unwrap()
    };

    let mut s: Vec<Vec<char>> = Vec::with_capacity(n);
    for _ in 0..n {
        let mut buf = String::new();
        std::io::stdin().read_line(&mut buf).unwrap();
        s.push(buf.trim_end().chars().rev().collect());
    }

    let mut g = vec![vec![0; 26]];
    let mut v = vec![vec![]; n];
    let mut leaves = std::collections::HashSet::new();
    for i in 0..n {
        let mut now = 0;
        for &c in &s[i] {
            v[i].push(now);
            let k = c as usize - 'a' as usize;
            if g[now][k] == 0 {
                g[now][k] = g.len();
                g.push(vec![0; 26]);
            }
            now = g[now][k];
        }
        leaves.insert(now);
    }

    let mut ans = 0;
    for i in 0..n {
        let mut check = vec![false; 26];
        for j in (0..s[i].len()).rev() {
            check[s[i][j] as usize - 'a' as usize] = true;
            let now = v[i][j];
            for k in 0..26 {
                if check[k] && leaves.contains(&g[now][k]) {
                    ans += 1;
                }
            }
        }
    }
    println!("{}", ans - n);
}

