    let mut buf: String;
    buf = String::new();
    let stdin_obj = std::io::stdin();
    stdin_obj.read_line(&mut buf).ok();
    // 定型句 buf（Str）に読み込んだ文字列をi64にパースしてnに代入。
    n = buf.trim().parse().ok().unwrap();
    s = Vec::<String>::with_capacity(n as usize);
    for _ in 0..n {
        buf = String::new();
        stdin_obj.read_line(&mut buf).ok();
        s.push(buf.trim().to_string());
    }
    // 【入力段ここまで】
    // ==================================
    // 【計算段ここから】
    s.sort_by_key(|a| a.len());
    // 予めすべての文字列について、後ろからx文字目までのハッシュを計算しておく。
    // ローリングハッシュを確保する配列。ヘッダ部分だけ確保。中身は後で動的確保、最大8MB
    let mut plane: Vec<Vec<i64>> = Vec::<Vec<i64>>::with_capacity(n as usize);
    for i in 0..n {
        let tmp_str = s[i as usize].as_bytes();
        // tmp_vect[i] は tmp_strの後ろから順番に、 i+1 文字分のローリングハッシュを格納する。
        let mut tmp_vect: Vec<i64> = Vec::<i64>::with_capacity(tmp_str.len() as usize);
        for x in 0..tmp_str.len() {
            let ix = tmp_str.len() - 1 - x;
            let val = tmp_str[ix];
            if x == 0 {
                tmp_vect.push(1);
            } else {
                tmp_vect.push(tmp_vect[x - 1 as usize])
            }
            tmp_vect[x as usize] *= B;
            tmp_vect[x as usize] += val as i64;
            tmp_vect[x as usize] %= MOD;
        }
        plane.push(tmp_vect.clone());
    }

    let mut counter = 0;
    for i in 0..n {
        let s_i = s[i as usize].as_bytes(); // 削る目標
        for j in (i + 1)..n {
            let s_j = s[j as usize].as_bytes();
            // ケース1: OK例 削る目標が1文字の場合、削る対象の中にその1文字が入っていたら、OK判定。
            if s_i.len() == 1 {
                for x in 0..s_j.len() {
                    if s_i[0] == s_j[x] {
                        counter += 1;
                        break;
                    }
                }
                continue;
            }
            // ケース2 ケース1 に入らなかった場合、後ろから最後の一文字を残して一致判定する。一致していなかったら、NG判定して弾く。
            let det_last_ix = plane[i as usize].len() - 2 as usize;
            if plane[i as usize][det_last_ix] != plane[j as usize][det_last_ix] {
                continue;
            }
            // ケース2.1 最後に残った1文字を検索する。
            let search_remain_ix = plane[j as usize].len() - plane[i as usize].len();
            for x in 0..(search_remain_ix + 1) {
                if s_i[0] == s_j[x] {
                    counter += 1;
                    break;
                }
            }
        }
    }
    println!("{}", counter);
}

