  let writer = stdout.lock();
  macro_rules! with_wrapper {
    ($($wrapper:expr)?) => {{
      let mut writer = $($wrapper)?(writer);
      solve(reader, &mut writer)?;
      writer.flush()
    }};
  }
  if cfg!(debug_assertions) || INTERACTIVE {
    with_wrapper!()
  } else {
    with_wrapper!(std::io::BufWriter::new)
  }
}

fn solve<R, W>(reader: R, mut writer: W) -> std::io::Result<()>
where
  R: BufRead,
  W: Write,
{
  let mut _scanner = lib::io::Scanner::new(reader);
  #[allow(unused_macros)]
  macro_rules! scan {
    ($T:ty) => {
      _scanner.parse_next::<$T>()?.unwrap()
    };
    ($($T:ty),+) => {
      ($(scan!($T)),+)
    };
    ($T:ty; $n:expr) => {
      _scanner.parse_next_n::<$T>($n)?.unwrap()
    };
    ($($T:ty),+; $n:expr) => {
      iter::repeat_with(|| -> std::io::Result<_> { Ok(($(scan!($T)),+)) })
        .take($n)
        .collect::<std::io::Result<Vec<_>>>()?
    };
  }
  #[allow(unused_macros)]
  macro_rules! scan_bytes_map {
    ($f:expr) => {
      _scanner.map_next_bytes($f)?
    };
    ($f:expr; $n:expr) => {
      _scanner.map_next_bytes_n($n, $f)?
    };
  }
  #[allow(unused_macros)]
  macro_rules! print {
    ($($arg:tt)*) => {
      write!(writer, $($arg)*)?
    };
  }
  #[allow(unused_macros)]
  macro_rules! println {
    ($($arg:tt)*) => {
      writeln!(writer, $($arg)*)?
    };
  }
  #[allow(unused_macros)]
  macro_rules! answer {
    ($($arg:tt)*) => {{
      println!($($arg)*);
      return Ok(());
    }};
  }
  {
    const C: usize = 26;

    let n = scan!(usize);
    let mut s = scan_bytes_map!(ByteChar; n);
    s.sort_unstable_by_key(|s_i| Reverse(s_i.len()));
    let s = s;

    fn idx(c: ByteChar) -> usize {
      (c.0 - b'a') as usize
    }

    #[derive(Clone, Default, Debug)]
    struct Node {
      cnt: [u64; C],
      ch: [Option<Box<Node>>; C],
    }

    impl Node {
      fn find(&self, mut s: &[ByteChar]) -> u64 {
        let mut this = self;
        loop {
          let &c = s.last().unwrap();
          if s.len() == 1 {
            return this.cnt[idx(c)];
          }
          if let Some(node) = this.ch[idx(c)].as_ref() {
            this = node;
            s = &s[..s.len() - 1];
          } else {
            return 0;
          }
        }
      }

      fn insert(&mut self, s: &[ByteChar]) {
        let mut cnt = [0; C];
        for &c in s {
          cnt[idx(c)] += 1;
        }
        self.do_insert(s, cnt);
      }

      fn do_insert(&mut self, mut s: &[ByteChar], mut cnt: [u64; C]) {
        let mut this = self;
        loop {
          let &c = s.last().unwrap();
          for i in 0..C {
            this.cnt[i] += cmp::min(1, cnt[i]);
          }
          cnt[idx(c)] -= 1;
          if s.len() == 1 {
            return;
          }
          this = this.ch[idx(c)].get_or_insert(Box::new(Node::default()));
          s = &s[..s.len() - 1];
        }
      }
    }

    let mut root = Node::default();
    let mut ans = 0;
    for s_i in s {
      ans += root.find(&s_i);
      root.insert(&s_i);
    }
    println!("{}", ans);
  }
  #[allow(unreachable_code)]
  Ok(())
}

