    let mut hi = ss.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let s = &ss[mid][..target.len().min(ss[mid].len())];
        if target < s {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    hi
}

fn main() {
    let source = AutoSource::from(
        r#"6
b
a
abc
c
d
ab
"#,
    );
    input! {
        from source,
        n: usize,
        ss: [Bytes; n],
    }
    let mut ss = ss
        .into_iter()
        .map(|s| s.into_iter().rev().map(|c| c - 97).collect::<Vec<_>>())
        .collect::<Vec<_>>();
    ss.sort();

    let mut count = 0;
    let mut will_remove = HashMap::new();
    let mut btree_list = vec![BTreeSet::new(); 26];
    for (i, s) in ss.iter().enumerate() {
        let j = i + bisect(&ss[i + 1..], &s[..s.len() - 1]);

        let c = *s.last().unwrap();
        let m = s.len() - 1;
        will_remove.entry(j).or_insert_with(Vec::new).push((c, m));
        btree_list[c as usize].insert(m);

        if let Some(remove) = will_remove.get(&i) {
            for &(c, k) in remove.iter() {
                btree_list[c as usize].remove(&k);
            }
        }
        let mut used = [false; 26];
        for (i, &c) in s.iter().enumerate().rev() {
            let c = c as usize;
            if used[c] {
                continue;
            }
            used[c] = true;
            for k in btree_list[c].iter() {
                if *k <= i {
                    count += 1;
                } else {
                    break;
                }
            }
        }
    }
    println!("{}", count);
}

