#[derive(Default, Debug)]
struct Trie {
    children: [Option<Box<Trie>>; 26],
    leaf: [bool; 26],
    acc: [usize; 26],
}

impl Trie {
    fn insert(&mut self, x: &[u8]) {
        let target = (x[x.len() - 1] - b'a') as usize;
        if x.len() == 1 {
            self.leaf[target] = true;
        } else {
            if self.children[target].is_none() {
                self.children[target] = Some(Box::new(Trie::default()));
            }
            self.children[target]
                .as_mut()
                .unwrap()
                .insert(&x[..x.len() - 1]);
        }
    }
    fn build_acc(&mut self) {
        for i in 0..26 {
            self.acc[i] = self.leaf[i] as usize;
        }
        for (i, c) in self.children.iter_mut().enumerate() {
            if let Some(c) = c.as_mut() {
                c.build_acc();
                self.acc[i] += 1;
                for j in 0..26 {
                    self.acc[j] += c.acc[j];
                }
            }
        }
    }
    fn aggregate(&self) -> usize {
        let mut sum = 0;
        for c in self.children.iter() {
            if let Some(c) = c.as_ref() {
                sum += c.aggregate();
            }
        }
        for i in 0..26 {
            if self.leaf[i] {
                sum += self.acc[i] - 1;
            }
        }
        sum
    }
}

