    let mut prefix = vec![0; n];
    for i in 1..n {
        let mut k = 0;
        while k < s[i - 1].len() - 1 && k < s[i].len() - 1 && s[i - 1][k] == s[i][k] {
            k += 1;
        }
        prefix[i] = k;
    }
    for i in 0..n - 1 {
        let length = prefix[i + 1];
        if s[i].len() - 1 != length {
