pub mod input_mcr {
    // ref: tanakh <https://qiita.com/tanakh/items/0ba42c7ca36cd29d0ac8>
    #[macro_export(local_inner_macros)]
    macro_rules! input {
        (source = $s:expr, $($r:tt)*) => {
            let mut parser = Parser::from_str($s);
            input_inner!{parser, $($r)*}
        };
        (parser = $parser:ident, $($r:tt)*) => {
            input_inner!{$parser, $($r)*}
        };
        (new_stdin_parser = $parser:ident, $($r:tt)*) => {
            let stdin = std::io::stdin();
            let reader = std::io::BufReader::new(stdin.lock());
            let mut $parser = Parser::new(reader);
            input_inner!{$parser, $($r)*}
        };
        ($($r:tt)*) => {
            input!{new_stdin_parser = parser, $($r)*}
        };
    }

    #[macro_export(local_inner_macros)]
    macro_rules! input_inner {
        ($parser:ident) => {};
        ($parser:ident, ) => {};
        ($parser:ident, $var:ident : $t:tt $($r:tt)*) => {
            let $var = read_value!($parser, $t);
            input_inner!{$parser $($r)*}
        };
    }

    #[macro_export(local_inner_macros)]
    macro_rules! read_value {
        ($parser:ident, ( $($t:tt),* )) => {
            ( $(read_value!($parser, $t)),* )
        };
        ($parser:ident, [ $t:tt ; $len:expr ]) => {
            (0..$len).map(|_| read_value!($parser, $t)).collect::<Vec<_>>()
        };
        ($parser:ident, chars) => {
            read_value!($parser, String).chars().collect::<Vec<char>>()
        };
        ($parser:ident, char_) => {
            read_value!($parser, String).chars().collect::<Vec<char>>()[0]
        };
        ($parser:ident, usize1) => {
            read_value!($parser, usize) - 1
        };
        ($parser:ident, line) => {
            $parser.next_line()
        };
        ($parser:ident, line_) => {
            $parser.next_line().chars().collect::<Vec<char>>()
        };
        ($parser:ident, $t:ty) => {
            $parser.next::<$t>().expect("Parse error")
        };
    }

    use std::io;
    use std::io::BufRead;
    use std::str;
    use std::collections::VecDeque;

    pub struct Parser<R> {
        pub reader: R,
        buf: VecDeque<u8>,
        parse_buf: Vec<u8>,
    }

    impl Parser<io::Empty> {
        pub fn from_str(s: &str) -> Parser<io::Empty> {
            Parser {
                reader: io::empty(),
                buf: VecDeque::from(s.as_bytes().to_vec()),
                parse_buf: vec![],
            }
        }
    }

    impl<R: BufRead> Parser<R> {
        pub fn new(reader: R) -> Parser<R> {
            Parser {
                reader: reader,
                buf: VecDeque::new(),
                parse_buf: vec![],
            }
        }
        pub fn update_buf(&mut self) {
            loop {
                let (len, complete) = {
                    let buf2 = self.reader.fill_buf().unwrap();
                    self.buf.extend(buf2.iter());
                    let len = buf2.len();
                    (len, buf2.last() < Some(&0x20))
                };
                self.reader.consume(len);
                if complete {
                    break;
                }
            }
        }
        pub fn next<T: str::FromStr>(&mut self) -> Result<T, T::Err> {
            loop {
                while let Some(c) = self.buf.pop_front() {
                    if c > 0x20 {
                        self.buf.push_front(c);
                        break;
                    }
                }
                self.parse_buf.clear();
                while let Some(c) = self.buf.pop_front() {
                    if c <= 0x20 {
                        self.buf.push_front(c);
                        break;
                    } else {
                        self.parse_buf.push(c);
                    }
                }
                if self.parse_buf.is_empty() {
                    self.update_buf();
                } else {
                    return unsafe { str::from_utf8_unchecked(&self.parse_buf) }.parse::<T>();
                }
            }
        }
        pub fn next_line(&mut self) -> String {
            loop {
                while let Some(c) = self.buf.pop_front() {
                    if c >= 0x20 {
                        self.buf.push_front(c);
                        break;
                    }
                }
                self.parse_buf.clear();
                while let Some(c) = self.buf.pop_front() {
                    if c < 0x20 {
                        self.buf.push_front(c);
                        break;
                    } else {
                        self.parse_buf.push(c);
                    }
                }
                if self.parse_buf.is_empty() {
                    self.update_buf();
                } else {
                    return unsafe { str::from_utf8_unchecked(&self.parse_buf) }.to_string();
                }
            }
        }
    }
}
pub mod xorshift {
    pub struct XorShift128 {
        x: u32,
        y: u32,
        z: u32,
        w: u32,
    }

    impl XorShift128 {
        pub fn new_with_seed(seed: u32) -> XorShift128 {
            XorShift128 {
                x: 123456789,
                y: 362436069,
                z: 521288629,
                w: seed,
            }
        }
        pub fn new() -> XorShift128 {
            XorShift128 {
                x: 123456789,
                y: 362436069,
                z: 521288629,
                w: 88675123,
            }
        }
        pub fn gen(&mut self) -> u32 {
            let t = self.x ^ (self.x << 11);
            self.x = self.y;
            self.y = self.z;
            self.z = self.w;
            self.w = (self.w ^ (self.w >> 19)) ^ (t ^ (t >> 8));
            self.w
        }
        pub fn gen_u64(&mut self) -> u64 {
            let high = (self.gen() as u64) << 32;
            let low = self.gen() as u64;
            high | low
        }
        pub fn gen_mod(&mut self, n: u32) -> u32 {
            self.gen() % n
        }
        pub fn gen_f64(&mut self) -> f64 {
            self.gen() as f64 / (1i64 << 32) as f64
        }
        pub fn shuffle<T>(&mut self, xs: &mut [T]) {
            let n = xs.len();
            for i in (1..n).rev() {
                let k = self.gen_mod(i as u32) as usize;
                xs.swap(i,k);
            }
        }
    }
}

use proconio::*;
use proconio::marker::*;

const F: usize = 26;

#[derive(Default)]
struct Node {
    cnt: [u32; F],
    next: [usize; F],
}

fn run() {
    input! {
        n: usize,
        mut s: [Bytes; n],
    }
    s.sort_by_key(|s| s.len());
    let mut node = vec![Node::default()];
    let empty = 0;
    let root = 0;
    let mut ans = 0;
    for s in s.iter_mut().rev() {
        s.reverse();
        let mut now = root;
        let mut stack = vec![];
        for c in s.iter() {
            let k = (*c - b'a') as usize;
            if node[now].next[k] == empty {
                let len = node.len();
                node.push(Node::default());
                node[now].next[k] = len;
            }
            stack.push(now);
            now = node[now].next[k];
        }
        let mut bit = 0;
        for (i, c) in s.iter().rev().enumerate() {
            let parent = stack.pop().unwrap();
            let k = (*c - b'a') as usize;
            if i == 0 {
                ans += node[parent].cnt[k] as usize;
            }
            bit |= 1 << k;
            for (j, cnt) in node[parent].cnt.iter_mut().enumerate() {
                *cnt += ((bit >> j) & 1) as u32;
            }
        }
    }
    println!("{}", ans);
}

fn main() {
    run();
}

