struct DFS {
    s: Vec<Vec<char>>,
}

impl DFS {
    fn new(s: Vec<Vec<char>>) -> DFS {
        DFS { s }
    }

    fn search(&mut self, d: usize, ids: &Vec<usize>, mut vb: Vec<bool>) -> i64 {
        let mut res = 0;

        if d > 0 {
            let k = self.s[ids[0]][d - 1] as usize - 'a' as usize;
            vb[k] = false;
        }

        let mut next = vec![vec![]; 26];
        for &i in ids {
            if self.s[i].len() == d {
                res += ids.len() as i64 - 1;
                continue;
            }
            let k = self.s[i][d] as usize - 'a' as usize;
            next[k].push(i);
        }

        for i in 0..26 {
            if vb[i] {
                res += next[i].len() as i64;
            }
        }

        for &i in ids {
            if self.s[i].len() == d + 1 {
                let k = self.s[i][d] as usize - 'a' as usize;
                vb[k] = true;
            }
        }

        for i in 0..26 {
            if !next[i].is_empty() {
                res += self.search(d + 1, &next[i], vb.clone());
            }
        }

        res
    }
}

