    for s in s.iter_mut() {
        s.reverse();
    }
    s.sort();
    let v: Vec<_> = s
        .iter()
        .map(|s| {
            let mut v = s
                .iter()
                .rev()
                .scan(0u32, |acc, &c| {
                    *acc |= 1 << ch2usize(c);
                    Some(*acc)
                })
                .collect::<Vec<_>>();
            v.reverse();
            v
        })
        .collect();
    let mut cnt = v
        .iter()
        .map(|v| {
            v.iter()
                .map(|x| {
                    (0..26)
                        .map(|i| (x & 1 << i != 0) as u32)
                        .collect::<Vec<_>>()
                })
                .collect::<Vec<_>>()
        })
        .collect::<Vec<_>>();
    for i in 0..n - 1 {
        for j in 0..cnt[i].len().min(cnt[i + 1].len()) {
            for k in 0..26 {
                cnt[i + 1][j][k] += cnt[i][j][k];
            }
        }
    }
    let mut ans = 0;
    let mut stack = vec![(0, 0, n)];
    while let Some((p, q, r)) = stack.pop() {
        if p >= n - 1 {
            continue;
        }
        let m = s[p].len();
        let mut j = p + 1;
        while j < r && s[p].len() <= s[j].len() && s[p][q..m - 1] == s[j][q..m - 1] {
            j += 1;
        }
        let j = binary_search(
            |j| !(s[p].len() <= s[j].len() && s[p][q..m - 1] == s[j][q..m - 1]),
            r,
            p,
        );
        if j > p + 1 {
            let b = ch2usize(s[p][m - 1]);
            ans += cnt[j - 1][m - 1][b] - cnt[p][m - 1][b];
        }
        if j > p + 2 {
