use xorshift::*;

fn main() {
    input! {
        n: usize,
        ss: [chars; n],
    }
    let mut hash = vec![vec![]; 26];
    let mut rand = XorShift128::new_with_seed(314);
    for i in 0..26 {
        for k in 0..1_000_100 {
            hash[i].push(rand.gen_u64());
        }
    }
    let mut rec = vec![HashMap::<u64,i64>::new(); 26];
    let mut ys = vec![];
    for s in &ss {
        // eprintln!("s = {:?}", s);
        let mut exist_bits = vec![]; 
        let mut bits = 0;
        exist_bits.push(bits);
        for &c in s.iter() {
            let v = c as usize - 'a' as usize;
            bits |= 1 << v;
            exist_bits.push(bits);
        }
        let mut h = 0;
        let mut tail_h = 0;
        for i in (0..s.len()+1).rev() {
            for j in 0..26 {
                if exist_bits[i] & (1 << j) != 0 {
                    //eprintln!("j = {}, h = {}, += 1", j, h);
                    *rec[j].entry(h).or_insert(0) += 1;
                }
            }
            if i == 1 {
                tail_h = h;
            }
            if i > 0 {
                let v = s[i-1] as usize - 'a' as usize;
                let k = s.len() - (i-1) - 1;
                h ^= hash[v][k];
            }
        }
        ys.push((s[0] as usize - 'a' as usize, tail_h));
    }
    for y in &ys {
        //eprintln!("y = {:?}", y);
    }
    let mut res = 0i64;
    for &(v,tail_h) in &ys {
        res += *rec[v].get(&tail_h).unwrap_or(&0);
    }
    res -= n as i64;
    println!("{}", res);
}
pub mod input_mcr {
    // ref: tanakh <https://qiita.com/tanakh/items/0ba42c7ca36cd29d0ac8>
    #[macro_export(local_inner_macros)]
    macro_rules! input {
        (source = $s:expr, $($r:tt)*) => {
            let mut parser = Parser::from_str($s);
            input_inner!{parser, $($r)*}
        };
        (parser = $parser:ident, $($r:tt)*) => {
            input_inner!{$parser, $($r)*}
        };
        (new_stdin_parser = $parser:ident, $($r:tt)*) => {
            let stdin = std::io::stdin();
            let reader = std::io::BufReader::new(stdin.lock());
            let mut $parser = Parser::new(reader);
            input_inner!{$parser, $($r)*}
        };
        ($($r:tt)*) => {
