        let nownagasa = nowstr.len();
        let mut have_in_prefix: Vec<bool> = vec![false; 26];
        let chars_table = vec![
            'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q',
            'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z',
        ];
        have_in_prefix[(nowstr.pop().unwrap() as usize) - ('a' as usize)] = true;
        for _j in 1..nownagasa {
            have_in_prefix[(nowstr.pop().unwrap() as usize) - ('a' as usize)] = true;
            for k in 0..26 {
                if !have_in_prefix[k as usize] {
                    continue;
                }
                nowstr.push(chars_table[k]);
                if already_seen.contains(nowstr.as_str()) {
                    ans += 1;
                }
                nowstr.pop();
            }
        }
        already_seen.insert(s[i - 1].as_str());
    }
    println!("{}", ans);
}

struct DFS {
    s: Vec<Vec<char>>,
}

impl DFS {
    fn new(s: Vec<Vec<char>>) -> DFS {
        DFS { s }
    }

    fn search(&mut self, d: usize, ids: &Vec<usize>, mut cnts: Vec<i64>) -> i64 {
        let mut res = 0;

        if d > 0 {
            let k = self.s[ids[0]][d - 1] as usize - 'a' as usize;
            cnts[k] = 0;
        }

        let mut next = vec![vec![]; 26];
        for &i in ids {
            if self.s[i].len() == d {
                res += ids.len() as i64 - 1;
            } else {
                let k = self.s[i][d] as usize - 'a' as usize;
                next[k].push(i);    
            }
        }

        for i in 0..26 {
            res += next[i].len() as i64 * cnts[i];
        }

        for &i in ids {
            if self.s[i].len() == d + 1 {
                let k = self.s[i][d] as usize - 'a' as usize;
                cnts[k] += 1;
            }
        }

        for i in 0..26 {
            if !next[i].is_empty() {
                res += self.search(d + 1, &next[i], cnts.clone());
            }
        }

        res
    }
}

fn main() {
    let n: usize = {
        let mut buf = String::new();
        std::io::stdin().read_line(&mut buf).unwrap();
        buf.trim_end().parse().unwrap()
    };

    let mut s: Vec<Vec<char>> = Vec::with_capacity(n);
    for _ in 0..n {
        let mut buf = String::new();
        std::io::stdin().read_line(&mut buf).unwrap();
        s.push(buf.trim_end().chars().rev().collect());
    }

    let mut dfs = DFS::new(s);
    let ans = dfs.search(0, &(0..n).collect(), vec![0; 26]);
    println!("{}", ans);
}

use proconio::*;
use proconio::marker::*;
use std::collections::*;

fn run() {
    input! {
        n: usize,
        mut s: [Bytes; n],
    }
    s.iter_mut().for_each(|s| s.reverse());
    s.sort_by_key(|s| s.len());
    const F: usize = 26;
    let mut map = BTreeMap::<usize, BTreeMap<&[u8], [bool; F]>>::new();
    let mut ans = 0;
    for s in s.iter() {
        let mut bit = 0;
        let mut pos = s.len();
        for (&len, map) in map.iter().rev() {
            while pos > len {
                pos -= 1;
                bit |= 1 << (s[pos] - b'a') as usize;
            }
            let pre = &s[..pos];
            if let Some(v) = map.get(pre) {
                ans += v.iter().enumerate().filter(|p| (bit >> p.0) & 1 == 1 && *p.1).count();
            }
        }
        let len = s.len();
        let pre = &s[..(len - 1)];
        let k = (s[len - 1] - b'a') as usize;
        map.entry(len - 1).or_insert(BTreeMap::new()).entry(pre).or_insert([false; 26])[k] = true;
    }
    println!("{}", ans);
}

fn main() {
    run();
}
